AQ.alphabet=[{"id":"alif","ar":"ا","name":{"bn":"আলিফ","en":"Alif"},"nameAr":"أَلِفْ","tr":{"bn":"আ","en":"ā"},"forms":{"isolated":"ا","initial":"ا","medial":"ـا","final":"ـا"},"connects":false,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"মুখ ও গলার ফাঁকা জায়গা (জাওফ) — টানা 'আ' হলে","en":"The open space of mouth and throat (jawf), when it is a long 'ā'"},"sound":{"bn":"আলিফের নিজের কোনো আলাদা আওয়াজ নেই: এটি হরকত বা হামযা বহন করে, আর যবরের পরে এলে 'আ'-কে লম্বা করে। বাংলাভাষীরা প্রায়ই একে 'অ' পড়েন — মুখ খুলে পরিষ্কার 'আ' বলুন।","en":"Alif has no sound of its own: it carries a vowel or a hamza, and after a fatha it stretches 'a' into a long 'ā'. Bangla speakers often say 'o' (অ) — open your mouth for a clear 'a'."},"family":"alif","example":{"ar":"أَحَدٌ","tr":{"bn":"আহাদুন","en":"aḥadun"},"mean":{"bn":"এক","en":"one"}},"mnemonic":{"bn":"আলিফ দেখতে ইংরেজি সংখ্যা 1-এর মতো — আর এটিই আরবির ১ নম্বর অক্ষর! একটা সোজা দাঁড়ানো লাঠি।","en":"Alif looks like the number 1 — and it is letter number one! A straight, standing stick."}},{"id":"ba","ar":"ب","name":{"bn":"বা","en":"Baa"},"nameAr":"بَاءْ","tr":{"bn":"ব","en":"b"},"forms":{"isolated":"ب","initial":"بـ","medial":"ـبـ","final":"ـب"},"connects":true,"heavy":false,"sun":false,"qalqalah":true,"makhraj":{"bn":"দুই ঠোঁট (ভেতরের ভেজা অংশ)","en":"Both lips (the inner, wet part)"},"sound":{"bn":"দুই ঠোঁট মিলিয়ে পরিষ্কার 'ব'। বাংলা 'ভ'-এর মতো বাতাস ছাড়বেন না, আর ইংরেজি v-এর মতো দাঁতে ঠোঁট লাগাবেন না।","en":"Close both lips for a clean 'b'. Don't add a puff of air like Bangla 'ভ', and never touch your teeth to your lip like a 'v'."},"family":"ba","example":{"ar":"بَيْتٌ","tr":{"bn":"বাইতুন","en":"baytun"},"mean":{"bn":"ঘর","en":"house"}},"mnemonic":{"bn":"একটা নৌকা, নিচে একটি বিন্দু — যেন নৌকার নিচে একটা বল (ball)। বা = বল নিচে!","en":"A boat with one dot underneath — a ball under the boat. Baa = ball below!"}},{"id":"ta","ar":"ت","name":{"bn":"তা","en":"Taa"},"nameAr":"تَاءْ","tr":{"bn":"ত","en":"t"},"forms":{"isolated":"ت","initial":"تـ","medial":"ـتـ","final":"ـت"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দুই দাঁতের গোড়া","en":"Tongue tip + roots of the upper front teeth"},"sound":{"bn":"জিভের আগা ওপরের সামনের দাঁতের গোড়ায় লাগিয়ে পাতলা, নরম 'ত'। বাংলা 'ট'-এর মতো জিভ উল্টাবেন না, 'থ'-এর মতো বাতাসও ছাড়বেন না।","en":"Tongue tip on the gum-line behind the upper front teeth: a light, crisp 't'. Don't curl the tongue like Bangla 'ট', and no puff of air like 'থ'."},"family":"ba","example":{"ar":"تُرَابٌ","tr":{"bn":"তুরাবুন","en":"turābun"},"mean":{"bn":"মাটি, ধুলা","en":"soil, dust"}},"mnemonic":{"bn":"নৌকার ওপরে দুটি বিন্দু — যেন দুটি চোখ ওপরে তাকিয়ে আছে। তা = দুই চোখ ওপরে!","en":"Two dots on top of the boat — two eyes looking up. Taa = two on top!"}},{"id":"tha","ar":"ث","name":{"bn":"ছা","en":"Thaa"},"nameAr":"ثَاءْ","tr":{"bn":"ছ","en":"th"},"forms":{"isolated":"ث","initial":"ثـ","medial":"ـثـ","final":"ـث"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দুই দাঁতের মাথা","en":"Tongue tip + edges of the upper front teeth"},"sound":{"bn":"জিভের আগা একটু বের করে ওপরের দাঁতের মাথায় লাগান, তারপর আলতো বাতাস ছাড়ুন — ইংরেজি think-এর th। বাংলাভাষীরা প্রায়ই 'স' বলে ফেলেন; জিভ যেন দাঁতের ফাঁকে উঁকি দেয়।","en":"Let the tongue tip peek out and touch the edges of the upper front teeth, then blow softly — the 'th' in 'think'. Bangla speakers often say 's'; let the tongue show between the teeth."},"family":"ba","example":{"ar":"ثَلَاثَةٌ","tr":{"bn":"ছালাছাতুন","en":"thalāthatun"},"mean":{"bn":"তিন","en":"three"}},"mnemonic":{"bn":"নৌকার ওপরে তিনটি বিন্দু, ছোট্ট পাহাড়ের মতো সাজানো। ইংরেজি Three শুরু হয় th দিয়ে — Thaa-ও তাই, আর তার বিন্দুও ৩টা!","en":"Three dots piled like a little hill on the boat. 'Three' starts with 'th' — so does Thaa, and it has three dots!"}},{"id":"jim","ar":"ج","name":{"bn":"জীম","en":"Jeem"},"nameAr":"جِيمْ","tr":{"bn":"জ","en":"j"},"forms":{"isolated":"ج","initial":"جـ","medial":"ـجـ","final":"ـج"},"connects":true,"heavy":false,"sun":false,"qalqalah":true,"makhraj":{"bn":"জিভের মাঝখান + তালুর মাঝখান","en":"Middle of the tongue + middle of the hard palate"},"sound":{"bn":"জিভের মাঝখান তালুতে চেপে পরিষ্কার 'জ', যেমন jam। নরম 'য' বা 'ঝ' বানাবেন না। জযম থাকলে আওয়াজ একটু লাফিয়ে ওঠে (কলকলা)।","en":"Press the middle of the tongue to the hard palate: a clear 'j' as in 'jam'. Don't soften it. With a sukun it gives a small bounce (qalqalah)."},"family":"jim","example":{"ar":"جَنَّةٌ","tr":{"bn":"জান্নাতুন","en":"jannatun"},"mean":{"bn":"বাগান, জান্নাত","en":"garden, Paradise"}},"mnemonic":{"bn":"একটা খোলা মুখ বা বড়শির মতো, পেটের ভেতর একটি বিন্দু — যেন জীম একটা জাম গিলে ফেলেছে!","en":"An open mouth (or a hook) with a dot in its belly — Jeem swallowed a jam-berry!"}},{"id":"hha","ar":"ح","name":{"bn":"হা","en":"Ḥaa"},"nameAr":"حَاءْ","tr":{"bn":"হ","en":"ḥ"},"forms":{"isolated":"ح","initial":"حـ","medial":"ـحـ","final":"ـح"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার মাঝখান","en":"Middle of the throat"},"sound":{"bn":"গলার মাঝখান একটু চেপে বাতাস ছাড়ুন — যেন গরম চা খেয়ে 'হাহ্' বলছেন। সাধারণ 'হ' (ه)-এর চেয়ে এটি বেশি ঘষা ও জোরালো; বাংলাভাষীরা প্রায়ই দুটো এক করে ফেলেন।","en":"Tighten the middle of the throat and push air through — like the 'ḥaah' after sipping hot tea. It is raspier than a normal 'h' (ه); Bangla speakers often mix the two."},"family":"jim","example":{"ar":"حَمْدٌ","tr":{"bn":"হামদুন","en":"ḥamdun"},"mean":{"bn":"প্রশংসা","en":"praise"}},"mnemonic":{"bn":"জীমের মতোই শরীর, কিন্তু পেট খালি (বিন্দু নেই) — তাই সে ক্ষুধায় 'হাহ্' করে হাঁপাচ্ছে!","en":"Same body as Jeem but an empty belly (no dot) — so it pants 'ḥaah' with hunger!"}},{"id":"kha","ar":"خ","name":{"bn":"খা","en":"Khaa"},"nameAr":"خَاءْ","tr":{"bn":"খ","en":"kh"},"forms":{"isolated":"خ","initial":"خـ","medial":"ـخـ","final":"ـخ"},"connects":true,"heavy":true,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার ওপরের অংশ (মুখের দিকের)","en":"Top of the throat (nearest the mouth)"},"sound":{"bn":"গলার ওপরের অংশ থেকে ঘষা আওয়াজ — যেন আলতো করে গলা পরিষ্কার করছেন। এটি বাংলা 'খ' (ক + বাতাস) নয়। এটি মোটা (ভারী) অক্ষর, তাই মুখ ভরে উচ্চারণ হয়।","en":"A scraping sound from the top of the throat, like gently clearing it (the 'ch' in Scottish 'loch'). It is not Bangla 'খ' (k + puff). It's a heavy letter, said with a full mouth."},"family":"jim","example":{"ar":"خَيْرٌ","tr":{"bn":"খাইরুন","en":"khayrun"},"mean":{"bn":"ভালো, কল্যাণ","en":"good"}},"mnemonic":{"bn":"জীমের শরীর, বিন্দুটা মাথার ওপরে — যেন টুপি পরেছে। খা = খোলা মাথায় টুপি!","en":"Jeem's body with the dot on its head like a cap. Khaa wears a cap!"}},{"id":"dal","ar":"د","name":{"bn":"দাল","en":"Daal"},"nameAr":"دَالْ","tr":{"bn":"দ","en":"d"},"forms":{"isolated":"د","initial":"د","medial":"ـد","final":"ـد"},"connects":false,"heavy":false,"sun":true,"qalqalah":true,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দুই দাঁতের গোড়া","en":"Tongue tip + roots of the upper front teeth"},"sound":{"bn":"জিভের আগা ওপরের দাঁতের গোড়ায় লাগিয়ে নরম 'দ'। বাংলা 'ড'-এর মতো জিভ পেছনে উল্টাবেন না। জযম থাকলে আওয়াজ লাফিয়ে ওঠে (কলকলা)।","en":"Tongue tip on the roots of the upper front teeth: a soft 'd'. Don't curl the tongue back like Bangla 'ড'. With a sukun it bounces (qalqalah)."},"family":"dal","example":{"ar":"دِينٌ","tr":{"bn":"দীনুন","en":"dīnun"},"mean":{"bn":"দীন, জীবনব্যবস্থা","en":"religion, way of life"}},"mnemonic":{"bn":"দেখতে একটা ভাঁজ করা কনুই বা হাঁটুর মতো — দাল লাইনের ওপরেই ভাঁজ হয়ে বসে থাকে।","en":"Looks like a bent elbow sitting right on the line — Daal sits down."}},{"id":"dhal","ar":"ذ","name":{"bn":"যাল","en":"Dhaal"},"nameAr":"ذَالْ","tr":{"bn":"য","en":"dh"},"forms":{"isolated":"ذ","initial":"ذ","medial":"ـذ","final":"ـذ"},"connects":false,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দুই দাঁতের মাথা","en":"Tongue tip + edges of the upper front teeth"},"sound":{"bn":"জিভের আগা ওপরের দাঁতের মাথায় লাগিয়ে গুনগুন কম্পনসহ আওয়াজ — ইংরেজি this-এর th। বাংলাভাষীরা প্রায়ই 'জ' বলেন; জিভ দাঁতের ফাঁকে রাখুন।","en":"Tongue tip touching the edges of the upper front teeth, with a buzz — the 'th' in 'this'. Saying 'j' is a common slip; keep the tongue between the teeth."},"family":"dal","example":{"ar":"ذِكْرٌ","tr":{"bn":"যিকরুন","en":"dhikrun"},"mean":{"bn":"স্মরণ, যিকির","en":"remembrance"}},"mnemonic":{"bn":"দালের মাথায় একটি বিন্দু — দাল টুপি পরলেই যাল!","en":"Daal with a dot on its head — Daal puts on a cap and becomes Dhaal!"}},{"id":"ra","ar":"ر","name":{"bn":"রা","en":"Raa"},"nameAr":"رَاءْ","tr":{"bn":"র","en":"r"},"forms":{"isolated":"ر","initial":"ر","medial":"ـر","final":"ـر"},"connects":false,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা (একটু পিঠসহ) + ওপরের মাড়ি","en":"Tongue tip (with a little of its top) + the upper gum"},"sound":{"bn":"জিভের আগা ওপরের মাড়িতে একবার আলতো ছুঁয়ে 'র'। বারবার কাঁপিয়ে 'র্‌র্‌র্' করবেন না। যবর বা পেশে সাধারণত মোটা, যেরে চিকন শোনায়।","en":"The tongue tip taps the upper gum once: 'r'. Don't roll it again and again. It usually sounds heavy with fatha or damma and light with kasra."},"family":"ra","example":{"ar":"رَبٌّ","tr":{"bn":"রাব্বুন","en":"rabbun"},"mean":{"bn":"রব, প্রতিপালক","en":"Lord, Sustainer"}},"mnemonic":{"bn":"একটা ছোট্ট স্লিপার, যা লাইনের নিচে নেমে যায় — রা পিছলে নিচে যায়!","en":"A little slide that dips below the line — Raa slides down!"}},{"id":"zay","ar":"ز","name":{"bn":"যা","en":"Zaay"},"nameAr":"زَايْ","tr":{"bn":"য","en":"z"},"forms":{"isolated":"ز","initial":"ز","medial":"ـز","final":"ـز"},"connects":false,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + নিচের সামনের দাঁতের কাছে (শিস দেওয়া অক্ষর)","en":"Tongue tip near the lower front teeth (a whistling letter)"},"sound":{"bn":"জিভের আগা নিচের দাঁতের কাছে রেখে মৌমাছির মতো 'য্‌য্‌য্' গুঞ্জন — ইংরেজি z। 'জ' (j) বলবেন না।","en":"Tongue tip near the lower front teeth with a bee-like buzz 'zzz' — English z. Don't say 'j'."},"family":"ra","example":{"ar":"زَيْتُونٌ","tr":{"bn":"যাইতূনুন","en":"zaytūnun"},"mean":{"bn":"জলপাই","en":"olive"}},"mnemonic":{"bn":"রা-এর মাথায় একটি বিন্দু — যেন স্লিপারে একটা মৌমাছি বসে 'যযয' করছে!","en":"Raa with a dot on top — a bee sitting on the slide going 'zzz'!"}},{"id":"sin","ar":"س","name":{"bn":"সীন","en":"Seen"},"nameAr":"سِينْ","tr":{"bn":"স","en":"s"},"forms":{"isolated":"س","initial":"سـ","medial":"ـسـ","final":"ـس"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + নিচের সামনের দাঁতের কাছে (শিস দেওয়া অক্ষর)","en":"Tongue tip near the lower front teeth (a whistling letter)"},"sound":{"bn":"জিভের আগা নিচের দাঁতের কাছে রেখে পাতলা শিসের মতো 'স' — সাপের 'স্‌স্‌স্'। বাংলাভাষীরা প্রায়ই 'শ' বলে ফেলেন; আওয়াজ চিকন ও তীক্ষ্ণ রাখুন।","en":"Tongue tip near the lower front teeth: a thin, hissing 's', like a snake. Bangla speakers often slide into 'sh' — keep it thin and sharp."},"family":"sin","example":{"ar":"سَلَامٌ","tr":{"bn":"সালামুন","en":"salāmun"},"mean":{"bn":"শান্তি","en":"peace"}},"mnemonic":{"bn":"তিনটি ছোট দাঁত আর একটা লেজ — যেন সাপ হাসছে তিন দাঁত বের করে: স্‌স্‌স্!","en":"Three little teeth and a tail — a smiling snake showing three teeth: sss!"}},{"id":"shin","ar":"ش","name":{"bn":"শীন","en":"Sheen"},"nameAr":"شِينْ","tr":{"bn":"শ","en":"sh"},"forms":{"isolated":"ش","initial":"شـ","medial":"ـشـ","final":"ـش"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের মাঝখান + তালুর মাঝখান","en":"Middle of the tongue + middle of the hard palate"},"sound":{"bn":"জিভের মাঝখান তালুর দিকে তুলে 'শ' — চুপ করানোর 'শ্‌শ্‌'। বাতাস মুখে ছড়িয়ে পড়ে।","en":"Raise the middle of the tongue toward the palate: 'sh' as in 'shush'. The air spreads through the mouth."},"family":"sin","example":{"ar":"شَمْسٌ","tr":{"bn":"শামসুন","en":"shamsun"},"mean":{"bn":"সূর্য","en":"sun"}},"mnemonic":{"bn":"সীনের মাথায় তিনটি বিন্দু — যেন তিন বন্ধু ঠোঁটে আঙুল দিয়ে বলছে 'শ্‌শ্‌শ্, চুপ!'","en":"Seen with three dots on top — three friends saying 'shhh!'"}},{"id":"sad","ar":"ص","name":{"bn":"সোয়াদ","en":"Ṣaad"},"nameAr":"صَادْ","tr":{"bn":"স","en":"ṣ"},"forms":{"isolated":"ص","initial":"صـ","medial":"ـصـ","final":"ـص"},"connects":true,"heavy":true,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা নিচের সামনের দাঁতের কাছে, সাথে জিভের পেছন ওপরে তোলা","en":"Tongue tip near the lower front teeth, with the back of the tongue raised"},"sound":{"bn":"সীনের জায়গা থেকেই, কিন্তু জিভের পেছন ওপরে তুলে মুখ ভরে মোটা 'স'। এর সাথে যবর পড়লে আওয়াজ গভীর ও ভারী শোনায়।","en":"Same spot as Seen, but raise the back of the tongue for a full, heavy 's'. A fatha after it sounds deep and dark."},"family":"sad","example":{"ar":"صَبْرٌ","tr":{"bn":"সাবরুন","en":"ṣabrun"},"mean":{"bn":"ধৈর্য","en":"patience"}},"mnemonic":{"bn":"একটা লম্বা মোটা লুপ আর ছোট্ট একটা দাঁত — মোটা লুপ = মোটা আওয়াজ!","en":"A long, fat loop with a tiny tooth — fat loop = fat (heavy) sound!"}},{"id":"dad","ar":"ض","name":{"bn":"দোয়াদ","en":"Ḍaad"},"nameAr":"ضَادْ","tr":{"bn":"দ","en":"ḍ"},"forms":{"isolated":"ض","initial":"ضـ","medial":"ـضـ","final":"ـض"},"connects":true,"heavy":true,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের এক বা দুই পাশ + ওপরের মাড়ির দাঁত","en":"Side(s) of the tongue + the upper molars"},"sound":{"bn":"জিভের পাশ ওপরের মাড়ির দাঁতে চেপে ভারী, মুখ-ভরা 'দ'-এর মতো আওয়াজ। এটি 'য/জ' নয়, আবার সাধারণ 'দ'-ও নয় — আরবির সবচেয়ে বিশেষ অক্ষর।","en":"Press the side(s) of the tongue against the upper molars for a heavy, full-mouthed 'd'-like sound. It is not 'z', and not a plain 'd' — Arabic's most special letter."},"family":"sad","example":{"ar":"ضَعِيفٌ","tr":{"bn":"দ'ঈফুন","en":"ḍa'īfun"},"mean":{"bn":"দুর্বল","en":"weak"}},"mnemonic":{"bn":"সোয়াদের মাথায় একটি বিন্দু। আরবিকে বলা হয় 'দোয়াদের ভাষা' — কারণ এই আওয়াজ আর কোনো ভাষায় সহজে পাওয়া যায় না!","en":"Ṣaad with a dot. Arabic is nicknamed 'the language of Ḍaad' because this sound is so rare!"}},{"id":"tta","ar":"ط","name":{"bn":"ত্বোয়া","en":"Ṭaa"},"nameAr":"طَاءْ","tr":{"bn":"ত","en":"ṭ"},"forms":{"isolated":"ط","initial":"طـ","medial":"ـطـ","final":"ـط"},"connects":true,"heavy":true,"sun":true,"qalqalah":true,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দাঁতের গোড়া, জিভের পেছন ওপরে তোলা","en":"Tongue tip + roots of the upper front teeth, back of the tongue raised"},"sound":{"bn":"তা-এর জায়গা থেকেই, কিন্তু জিভের পেছন তুলে মুখ ভরে মোটা 'ত'। বাংলা 'ট' নয়। জযম থাকলে লাফিয়ে ওঠে (কলকলা)।","en":"Same spot as Taa, but with the back of the tongue raised: a heavy, full 't'. Not Bangla 'ট'. With sukun it bounces (qalqalah)."},"family":"tta","example":{"ar":"طَعَامٌ","tr":{"bn":"ত্বা'আমুন","en":"ṭa'āmun"},"mean":{"bn":"খাবার","en":"food"}},"mnemonic":{"bn":"একটা লুপের ওপর খাড়া একটা দণ্ড — যেন কেউ ছাতা ধরে দাঁড়িয়ে আছে!","en":"A loop with a tall pole standing up — like someone holding an umbrella!"}},{"id":"zza","ar":"ظ","name":{"bn":"যোয়া","en":"Ẓaa"},"nameAr":"ظَاءْ","tr":{"bn":"য","en":"ẓ"},"forms":{"isolated":"ظ","initial":"ظـ","medial":"ـظـ","final":"ـظ"},"connects":true,"heavy":true,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দাঁতের মাথা, জিভের পেছন ওপরে তোলা","en":"Tongue tip + edges of the upper front teeth, back of the tongue raised"},"sound":{"bn":"যালের জায়গা থেকে (জিভ দাঁতের মাথায়), কিন্তু জিভের পেছন তুলে মোটা ও গুনগুন আওয়াজ। 'জ' বলবেন না।","en":"Same spot as Dhaal (tongue on the tooth edges), but with the back of the tongue raised: a heavy, buzzing 'th' as in 'this'. Not 'j'."},"family":"tta","example":{"ar":"ظِلٌّ","tr":{"bn":"যিল্লুন","en":"ẓillun"},"mean":{"bn":"ছায়া","en":"shade"}},"mnemonic":{"bn":"ত্বোয়ার পাশে একটি বিন্দু — ছাতার পাশে একটা বৃষ্টির ফোঁটা!","en":"Ṭaa with a dot beside the pole — a raindrop next to the umbrella!"}},{"id":"ain","ar":"ع","name":{"bn":"আইন","en":"'Ayn"},"nameAr":"عَيْنْ","tr":{"bn":"আ","en":"'"},"forms":{"isolated":"ع","initial":"عـ","medial":"ـعـ","final":"ـع"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার মাঝখান","en":"Middle of the throat"},"sound":{"bn":"গলার মাঝখান চেপে স্বর বের করুন — গলা থেকে চাপা, গভীর 'আ'। বাংলাভাষীরা প্রায়ই সাধারণ 'আ' (হামযা) পড়েন; এতে শব্দের অর্থ বদলে যেতে পারে।","en":"Squeeze the middle of the throat while voicing — a tight, deep 'a' from the throat. Reading it as a plain 'a' (like hamza) is the commonest mistake and can change meaning."},"family":"ain","example":{"ar":"عِلْمٌ","tr":{"bn":"'ইলমুন","en":"'ilmun"},"mean":{"bn":"জ্ঞান","en":"knowledge"}},"mnemonic":{"bn":"ওপরে ছোট্ট একটা খোলা মুখ, নিচে বড় একটা লেজ — যেন কেউ হাঁ করে গলা থেকে আওয়াজ বের করছে। মজার কথা: عَيْنٌ মানে 'চোখ'!","en":"A small open mouth on top and a big swoosh below — someone opening wide to make a throat sound. Fun fact: عَيْنٌ means 'eye'!"}},{"id":"ghain","ar":"غ","name":{"bn":"গাইন","en":"Ghayn"},"nameAr":"غَيْنْ","tr":{"bn":"গ","en":"gh"},"forms":{"isolated":"غ","initial":"غـ","medial":"ـغـ","final":"ـغ"},"connects":true,"heavy":true,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার ওপরের অংশ (মুখের দিকের)","en":"Top of the throat (nearest the mouth)"},"sound":{"bn":"গলার ওপরের অংশ থেকে গার্গল করার মতো কম্পনসহ আওয়াজ। এটি সাধারণ বাংলা 'গ' নয়; এটি মোটা অক্ষর।","en":"From the top of the throat, a gargling, vibrating sound (like a French 'r'). Not a plain 'g'. A heavy letter."},"family":"ain","example":{"ar":"غَفُورٌ","tr":{"bn":"গাফূরুন","en":"ghafūrun"},"mean":{"bn":"অতি ক্ষমাশীল","en":"Most Forgiving"}},"mnemonic":{"bn":"আইনের মাথায় একটি বিন্দু — গার্গল করার সময় যেন এক ফোঁটা পানি ছিটকে উঠেছে!","en":"'Ayn with a dot on its head — a drop of water splashing up while you gargle!"}},{"id":"fa","ar":"ف","name":{"bn":"ফা","en":"Faa"},"nameAr":"فَاءْ","tr":{"bn":"ফ","en":"f"},"forms":{"isolated":"ف","initial":"فـ","medial":"ـفـ","final":"ـف"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"নিচের ঠোঁটের ভেতরের অংশ + ওপরের সামনের দাঁতের মাথা","en":"Inner lower lip + edges of the upper front teeth"},"sound":{"bn":"ওপরের দাঁত নিচের ঠোঁটের ভেতরে ছুঁইয়ে বাতাস ছাড়ুন — ইংরেজি f। বাংলা 'ফ' (প + বাতাস) নয়।","en":"Upper teeth touch the inside of the lower lip, then blow: English 'f'. Not Bangla 'ফ' (a breathy p)."},"family":"fa","example":{"ar":"فِيلٌ","tr":{"bn":"ফীলুন","en":"fīlun"},"mean":{"bn":"হাতি","en":"elephant"}},"mnemonic":{"bn":"ছোট্ট গোল মাথা, ওপরে এক বিন্দু, আর লম্বা চ্যাপ্টা শরীর। ফা = ১ বিন্দু, শরীর লাইনের ওপর।","en":"A small round head with one dot and a long flat body. Faa = one dot, body on the line."}},{"id":"qaf","ar":"ق","name":{"bn":"ক্বাফ","en":"Qaaf"},"nameAr":"قَافْ","tr":{"bn":"ক","en":"q"},"forms":{"isolated":"ق","initial":"قـ","medial":"ـقـ","final":"ـق"},"connects":true,"heavy":true,"sun":false,"qalqalah":true,"makhraj":{"bn":"জিভের একদম গোড়া + নরম তালু (আলজিভের কাছে)","en":"Very back of the tongue + soft palate (near the uvula)"},"sound":{"bn":"জিভের একদম পেছন নরম তালুতে চেপে গভীর, মোটা 'ক' — কাফ (ك)-এর চেয়েও পেছন থেকে। জযম থাকলে লাফিয়ে ওঠে (কলকলা)।","en":"The very back of the tongue presses the soft palate: a deep, heavy 'q', further back than Kaaf (ك). With sukun it bounces (qalqalah)."},"family":"fa","example":{"ar":"قَلَمٌ","tr":{"bn":"ক্বালামুন","en":"qalamun"},"mean":{"bn":"কলম","en":"pen"}},"mnemonic":{"bn":"ফা-এর মতো মাথা, কিন্তু দুই বিন্দু, আর লেজ লাইনের নিচে গভীর বাটির মতো — গভীর বাটি, গভীর আওয়াজ!","en":"Like Faa's head but with two dots, and its tail dips deep below the line like a bowl — deep bowl, deep sound!"}},{"id":"kaf","ar":"ك","name":{"bn":"কাফ","en":"Kaaf"},"nameAr":"كَافْ","tr":{"bn":"ক","en":"k"},"forms":{"isolated":"ك","initial":"كـ","medial":"ـكـ","final":"ـك"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"জিভের পেছন (ক্বাফের একটু সামনে) + তালু","en":"Back of the tongue (a little forward of Qaaf) + the palate"},"sound":{"bn":"জিভের পেছন তালুতে লাগিয়ে পাতলা, হালকা 'ক' — বাংলা 'ক'-এর কাছাকাছি। ক্বাফের মতো গভীর বা মোটা করবেন না।","en":"Back of the tongue against the palate: a light 'k', close to Bangla 'ক'. Don't make it deep and heavy like Qaaf."},"family":"kaf","example":{"ar":"كِتَابٌ","tr":{"bn":"কিতাবুন","en":"kitābun"},"mean":{"bn":"বই","en":"book"}},"mnemonic":{"bn":"দেখতে একটা ঘরের কোণের মতো, ভেতরে ছোট্ট একটা আঁকাবাঁকা চিহ্ন — কাফ নিজের ঘরে ছোট্ট একটা কলম রাখে!","en":"Like the corner of a little room with a small squiggle inside — Kaaf keeps a tiny pen in its room!"}},{"id":"lam","ar":"ل","name":{"bn":"লাম","en":"Laam"},"nameAr":"لَامْ","tr":{"bn":"ল","en":"l"},"forms":{"isolated":"ل","initial":"لـ","medial":"ـلـ","final":"ـل"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগার কিনারা + ওপরের সামনের দাঁতের মাড়ি","en":"Front edges of the tongue + gum above the front teeth"},"sound":{"bn":"জিভের আগা ওপরের মাড়িতে লাগিয়ে 'ল'। সাধারণত পাতলা; শুধু 'আল্লাহ' শব্দে (যবর বা পেশের পরে) মোটা হয়।","en":"The tongue tip touches the gum above the front teeth: 'l'. Usually light; only in the word Allah (after fatha or damma) does it become heavy."},"family":"lam","example":{"ar":"لَيْلٌ","tr":{"bn":"লাইলুন","en":"laylun"},"mean":{"bn":"রাত","en":"night"}},"mnemonic":{"bn":"আলিফের মতো লম্বা, কিন্তু নিচে একটা বাঁকা হুক — যেন একটা হকি স্টিক!","en":"Tall like Alif but with a hook at the bottom — like a hockey stick!"}},{"id":"mim","ar":"م","name":{"bn":"মীম","en":"Meem"},"nameAr":"مِيمْ","tr":{"bn":"ম","en":"m"},"forms":{"isolated":"م","initial":"مـ","medial":"ـمـ","final":"ـم"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"দুই ঠোঁট (শুকনো অংশ), সাথে নাকের বাঁশি","en":"Both lips (the dry part), with the nasal passage"},"sound":{"bn":"দুই ঠোঁট আলতো মিলিয়ে 'ম' — নাক দিয়েও একটু গুনগুন আওয়াজ বের হয়। বাংলা 'ম'-এর মতোই সহজ।","en":"Close both lips gently: 'm', with a little hum through the nose. Just like Bangla 'ম'."},"family":"mim","example":{"ar":"مَسْجِدٌ","tr":{"bn":"মাসজিদুন","en":"masjidun"},"mean":{"bn":"মসজিদ","en":"mosque"}},"mnemonic":{"bn":"ছোট্ট গোল মাথা আর নিচে ঝুলে থাকা লেজ — যেন সুতায় বাঁধা একটা বেলুন!","en":"A small round head with a tail hanging down — like a balloon on a string!"}},{"id":"nun","ar":"ن","name":{"bn":"নূন","en":"Noon"},"nameAr":"نُونْ","tr":{"bn":"ন","en":"n"},"forms":{"isolated":"ن","initial":"نـ","medial":"ـنـ","final":"ـن"},"connects":true,"heavy":false,"sun":true,"qalqalah":false,"makhraj":{"bn":"জিভের আগা + ওপরের সামনের দাঁতের মাড়ি, সাথে নাকের বাঁশি","en":"Tongue tip + gum above the front teeth, with the nasal passage"},"sound":{"bn":"জিভের আগা ওপরের মাড়িতে লাগিয়ে 'ন', সাথে নাকে গুনগুন। বাংলা 'ন'-এর মতোই।","en":"Tongue tip on the upper gum: 'n', with a nasal hum. Just like Bangla 'ন'."},"family":"nun","example":{"ar":"نُورٌ","tr":{"bn":"নূরুন","en":"nūrun"},"mean":{"bn":"আলো","en":"light"}},"mnemonic":{"bn":"একটা গোল বাটি, ওপরে একটি বিন্দু — বাটির ওপর একটা আঙুর! বা-এর চ্যাপ্টা নৌকার চেয়ে নূনের বাটি গভীর।","en":"A round bowl with one dot above — a grape over a bowl! Deeper than Baa's flat boat."}},{"id":"waw","ar":"و","name":{"bn":"ওয়াও","en":"Waaw"},"nameAr":"وَاوْ","tr":{"bn":"ও","en":"w"},"forms":{"isolated":"و","initial":"و","medial":"ـو","final":"ـو"},"connects":false,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"দুই ঠোঁট গোল করে (না মিলিয়ে)","en":"Both lips rounded (not closed)"},"sound":{"bn":"দুই ঠোঁট গোল করে, না মিলিয়ে 'ওয়া'। দাঁত দিয়ে ঠোঁট ছুঁয়ে 'ভ' (v) বলবেন না — বাংলাভাষীদের খুব সাধারণ ভুল।","en":"Round the lips without closing them: 'w'. Never touch teeth to lip to make a 'v' — a very common slip."},"family":"waw","example":{"ar":"وَلَدٌ","tr":{"bn":"ওয়ালাদুন","en":"waladun"},"mean":{"bn":"সন্তান, ছেলে","en":"child, boy"}},"mnemonic":{"bn":"গোল মাথা আর বাঁকা লেজ — দেখতে একটা বড় কমার (,) মতো। গোল মাথাটা মনে করিয়ে দেয়: ঠোঁট গোল করো!","en":"A round head with a curved tail — like a giant comma. The round head reminds you: round your lips!"}},{"id":"ha","ar":"ه","name":{"bn":"হা (গোল হা)","en":"Haa"},"nameAr":"هَاءْ","tr":{"bn":"হ","en":"h"},"forms":{"isolated":"ه","initial":"هـ","medial":"ـهـ","final":"ـه"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার একদম গভীর অংশ (বুকের দিকের)","en":"Deepest part of the throat (nearest the chest)"},"sound":{"bn":"গলার একদম গভীর থেকে নরম, বাতাসভরা 'হ' — আয়নায় ভাপ দেওয়ার মতো 'হা'। শব্দের শেষে থাকলেও স্পষ্ট শোনাতে হবে।","en":"From the deepest part of the throat: a soft, breathy 'h', like fogging a mirror. Say it clearly even at the end of a word."},"family":"ha","example":{"ar":"هُدًى","tr":{"bn":"হুদান","en":"hudan"},"mean":{"bn":"হিদায়াত, পথনির্দেশ","en":"guidance"}},"mnemonic":{"bn":"এই অক্ষর সবচেয়ে বেশি রূপ বদলায়: ه هـ ـهـ ـه — যেন একজন অভিনেতা, প্রতি দৃশ্যে নতুন পোশাক!","en":"This letter changes shape the most: ه هـ ـهـ ـه — an actor with a new costume in every scene!"}},{"id":"hamza","ar":"ء","name":{"bn":"হামযা","en":"Hamzah"},"nameAr":"هَمْزَةْ","tr":{"bn":"অ","en":"ʼ"},"forms":{"isolated":"ء","initial":"ء","medial":"ء","final":"ء"},"connects":false,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"গলার একদম গভীর অংশ (বুকের দিকের)","en":"Deepest part of the throat (nearest the chest)"},"sound":{"bn":"গলার গভীরে হঠাৎ একটা 'থামা' — যেমন 'আ-আ' বলতে গিয়ে মাঝখানে ক্ষণিক বিরতি। তারপর হরকত অনুযায়ী আ, ই বা উ। শব্দের শেষে থাকলে একে হারিয়ে ফেলবেন না।","en":"A sudden catch deep in the throat — the little stop in 'uh-oh'. Then it takes its vowel: a, i or u. Don't swallow it at the end of a word."},"family":"hamza","example":{"ar":"سَمَاءٌ","tr":{"bn":"সামা-উন","en":"samāʼun"},"mean":{"bn":"আকাশ","en":"sky"}},"mnemonic":{"bn":"দেখতে আইনের (ع) ছোট্ট মাথার মতো। সে একা বসতে পারে (ء), আবার আলিফ, ওয়াও বা ইয়ার পিঠে চড়েও বসে: أ إ ؤ ئ।","en":"Looks like the little head of 'Ayn (ع). It can sit alone (ء) or ride on an Alif, Waaw or Yaa: أ إ ؤ ئ."}},{"id":"ya","ar":"ي","name":{"bn":"ইয়া","en":"Yaa"},"nameAr":"يَاءْ","tr":{"bn":"ই","en":"y"},"forms":{"isolated":"ي","initial":"يـ","medial":"ـيـ","final":"ـي"},"connects":true,"heavy":false,"sun":false,"qalqalah":false,"makhraj":{"bn":"জিভের মাঝখান + তালুর মাঝখান","en":"Middle of the tongue + middle of the hard palate"},"sound":{"bn":"জিভের মাঝখান তালুর দিকে তুলে 'ইয়া' (yes-এর y)। 'জ' বলবেন না।","en":"Raise the middle of the tongue toward the palate: 'y' as in 'yes'. Don't turn it into 'j'."},"family":"ya","example":{"ar":"يَدٌ","tr":{"bn":"ইয়াদুন","en":"yadun"},"mean":{"bn":"হাত","en":"hand"}},"mnemonic":{"bn":"শেষে বসলে হাঁসের মতো বাঁকা শরীর, নিচে দুই বিন্দু — যেন হাঁসের দুটো পা! ইয়া = নিচে ২ বিন্দু।","en":"At the end it curves like a swan, with two dots underneath — the swan's two feet! Yaa = two dots below."}}];
AQ.units.push({"id":"reading","order":1,"icon":"ا","color":"teal","title":{"bn":"আরবি পড়তে শিখি","en":"Learn to Read"},"subtitle":{"bn":"আলিফ থেকে শুরু করে কুরআনের আয়াত পড়া পর্যন্ত — ধাপে ধাপে আধুনিক কায়দা","en":"From Alif to reading real Quranic ayahs — a modern Qaida, step by step"},"lessons":[{"id":"rd-welcome","icon":"أهلا","title":{"bn":"স্বাগতম! আরবি কীভাবে কাজ করে","en":"Welcome! How Arabic Works"},"subtitle":{"bn":"শুরু করার আগে আরবি লেখার ৫টি মজার নিয়ম","en":"Five friendly facts about Arabic writing before we begin"},"minutes":10,"goals":[{"bn":"আরবি কোন দিক থেকে লেখা ও পড়া হয়","en":"Which direction Arabic is written and read"},{"bn":"আরবি বর্ণমালা বাংলা থেকে কীভাবে আলাদা","en":"How the Arabic alphabet differs from Bangla"},{"bn":"প্রতিদিন ১৫ মিনিটে কীভাবে পড়াশোনা করবেন","en":"How to study in just 15 minutes a day"},{"bn":"এই অ্যাপ ও বই কীভাবে ব্যবহার করবেন","en":"How to use this app and book"}],"blocks":[{"type":"text","bn":"আস্‌সালামু আলাইকুম! আপনি এমন এক যাত্রা শুরু করছেন, যার শেষে আপনি নিজের চোখে **কুরআন** পড়তে পারবেন। চিন্তার কিছু নেই — বয়স যা-ই হোক, প্রতিদিন অল্প অল্প করে এগোলে আরবি পড়া একদম সহজ।","en":"Assalamu alaikum! You are starting a journey that ends with you reading the **Quran** with your own eyes. Don't worry — whatever your age, a little every day makes Arabic reading easy."},{"type":"tip","kind":"fun","bn":"আপনি হয়তো জানেন না, কিন্তু আপনি আগে থেকেই অনেক আরবি শব্দ জানেন! বাংলায় কলম, কিতাব, দুনিয়া, ওয়াক্ত, হিসাব — সবই আরবি থেকে এসেছে।","en":"You already know lots of Arabic words without realising it! Bangla words like kolom (pen), kitab (book), duniya (world), waqt (time) and hisab (account) all come from Arabic.","title":{"bn":"আপনি আগেই আরবি জানেন!","en":"You already know some Arabic!"}},{"type":"examples","items":[{"ar":"قَلَمٌ","tr":{"bn":"ক্বালামুন","en":"qalamun"},"mean":{"bn":"কলম","en":"pen"}},{"ar":"كِتَابٌ","tr":{"bn":"কিতাবুন","en":"kitābun"},"mean":{"bn":"কিতাব, বই","en":"book"}},{"ar":"دُنْيَا","tr":{"bn":"দুনইয়া","en":"dunyā"},"mean":{"bn":"দুনিয়া, পৃথিবী","en":"world"}},{"ar":"وَقْتٌ","tr":{"bn":"ওয়াক্‌তুন","en":"waqtun"},"mean":{"bn":"ওয়াক্ত, সময়","en":"time"}},{"ar":"حِسَابٌ","tr":{"bn":"হিসাবুন","en":"ḥisābun"},"mean":{"bn":"হিসাব","en":"account, reckoning"}}],"title":{"bn":"বাংলায় আরবি শব্দ","en":"Arabic words inside Bangla"}},{"type":"text","bn":"**নিয়ম ১ — ডান থেকে বাম।** বাংলা ও ইংরেজি বাম দিক থেকে শুরু হয়, কিন্তু আরবি শুরু হয় **ডান দিক** থেকে। তাই আরবি বই খোলে আমাদের চোখে 'উল্টো' দিক থেকে — কুরআন শরীফ হাতে নিলেই দেখবেন!","en":"**Fact 1 — Right to left.** Bangla and English start on the left, but Arabic starts on the **right**. So an Arabic book opens from what looks to us like the 'back' — pick up a mushaf and see!","title":{"bn":"ডান থেকে বাম","en":"Right to left"}},{"type":"tip","kind":"memory","bn":"ডান হাত দিয়ে আমরা ভালো কাজ শুরু করি — আরবিও শুরু হয় ডান দিক থেকে! পড়ার সময় আঙুল ডানে রেখে বাম দিকে সরান।","en":"We begin good deeds with the right hand — and Arabic begins on the right! When reading, put your finger on the right and slide it left."},{"type":"text","bn":"**নিয়ম ২ — ২৯টি অক্ষর।** আরবি বর্ণমালায় (হামযাসহ) ২৯টি অক্ষর। বাংলার মতো আলাদা 'স্বরবর্ণ' নেই — প্রায় সব অক্ষরই ব্যঞ্জনের মতো কাজ করে।","en":"**Fact 2 — 29 letters.** The Arabic alphabet has 29 letters (counting hamza). There are no separate 'vowel letters' like in Bangla — almost every letter works like a consonant.","title":{"bn":"২৯টি অক্ষর","en":"29 letters"}},{"type":"letters","items":["alif","ba","ta","tha","jim","hha","kha","dal","dhal","ra","zay","sin","shin","sad","dad","tta","zza","ain","ghain","fa","qaf","kaf","lam","mim","nun","waw","ha","hamza","ya"],"title":{"bn":"পুরো বর্ণমালা — যেকোনো অক্ষরে চাপ দিন","en":"The whole alphabet — tap any letter"}},{"type":"text","bn":"**নিয়ম ৩ — বড় হাতের অক্ষর নেই।** ইংরেজির মতো A/a ঝামেলা নেই। তবে শব্দের শুরু, মাঝখান বা শেষে অক্ষরের চেহারা একটু বদলায় — সেটা পরে শিখব।","en":"**Fact 3 — No capital letters.** No A/a fuss like English. But a letter's shape changes a little at the start, middle or end of a word — we'll learn that soon.","title":{"bn":"বড় হাতের অক্ষর নেই","en":"No capitals"}},{"type":"text","bn":"**নিয়ম ৪ — অক্ষরগুলো হাত ধরাধরি করে।** আরবিতে শব্দের অক্ষরগুলো সাধারণত একে অপরের সাথে জোড়া লাগানো থাকে, যেন হাত ধরে দাঁড়িয়ে আছে।","en":"**Fact 4 — Letters hold hands.** In an Arabic word the letters are usually joined to each other, as if holding hands.","title":{"bn":"অক্ষর জোড়া লাগে","en":"Letters join"}},{"type":"examples","items":[{"ar":"كَتَبَ","tr":{"bn":"কাতাবা","en":"kataba"},"mean":{"bn":"সে লিখল","en":"he wrote"},"note":{"bn":"ك + ت + ب = তিনটি অক্ষর জোড়া লেগে একটি শব্দ","en":"ك + ت + ب = three letters joined into one word"}}]},{"type":"text","bn":"**নিয়ম ৫ — স্বর হলো ছোট্ট চিহ্ন।** বাংলায় যেমন ক + া = কা, ক + ি = কি — আরবিতেও তেমনি অক্ষরের ওপরে বা নিচে ছোট্ট চিহ্ন (হরকত) বসিয়ে স্বর দেওয়া হয়।","en":"**Fact 5 — Vowels are tiny marks.** Just as Bangla adds া or ি to ক to make কা, কি — Arabic puts tiny marks (harakat) above or below a letter to give it a vowel.","title":{"bn":"স্বর = ছোট্ট চিহ্ন","en":"Vowels = tiny marks"}},{"type":"examples","items":[{"ar":"بَ","tr":{"bn":"বা","en":"ba"},"note":{"bn":"ওপরে তির্যক দাগ = 'আ'","en":"slanted line above = 'a'"}},{"ar":"بِ","tr":{"bn":"বি","en":"bi"},"note":{"bn":"নিচে তির্যক দাগ = 'ই'","en":"slanted line below = 'i'"}},{"ar":"بُ","tr":{"bn":"বু","en":"bu"},"note":{"bn":"ওপরে ছোট্ট و = 'উ'","en":"tiny و above = 'u'"}}]},{"type":"tip","kind":"memory","bn":"বাংলার 'কার' চিহ্ন (া ি ু) আর আরবির 'হরকত' একই কাজ করে। পার্থক্য শুধু একটাই: আরবিতে এগুলো অক্ষরের ওপরে-নিচে বসে।","en":"Bangla vowel signs (া ি ু) and Arabic harakat do the same job. The only difference: in Arabic they sit above or below the letter."},{"type":"table","head":[{"bn":"বিষয়","en":"Feature"},{"bn":"বাংলা","en":"Bangla"},{"bn":"আরবি","en":"Arabic"}],"rows":[[{"bn":"দিক","en":"Direction"},{"bn":"বাম → ডান","en":"Left → right"},{"bn":"ডান → বাম","en":"Right → left"}],[{"bn":"অক্ষর","en":"Letters"},{"bn":"৫০টি (স্বর + ব্যঞ্জন)","en":"50 (vowels + consonants)"},{"bn":"২৯টি","en":"29"}],[{"bn":"স্বরচিহ্ন","en":"Vowel signs"},{"bn":"কার: া ি ু","en":"kar signs: া ি ু"},{"bn":"হরকত: ◌َ ◌ِ ◌ُ","en":"harakat: ◌َ ◌ِ ◌ُ"}],[{"bn":"যুক্ত করা","en":"Joining"},{"bn":"যুক্তবর্ণ (ক্ষ, ন্ত…)","en":"conjuncts (ক্ষ, ন্ত…)"},{"bn":"পাশাপাশি জোড়া লাগে","en":"letters join side by side"}]],"title":{"bn":"এক নজরে: বাংলা বনাম আরবি","en":"At a glance: Bangla vs Arabic"}},{"type":"tip","kind":"warn","bn":"কুরআনে একটি অক্ষরের উচ্চারণ ভুল হলে অর্থ বদলে যেতে পারে। নিচের দুটি শব্দ দেখুন — শুধু প্রথম অক্ষর আলাদা!","en":"In the Quran, mispronouncing one letter can change the meaning. Look at these two words — only the first letter differs!","title":{"bn":"কেন সঠিক উচ্চারণ জরুরি","en":"Why correct sounds matter"}},{"type":"compare","items":[{"ar":"قَلْبٌ","label":{"bn":"ক্বালবুন — হৃদয়","en":"qalbun — heart"},"desc":{"bn":"গলার কাছ থেকে গভীর ق","en":"deep ق from the back of the mouth"}},{"ar":"كَلْبٌ","label":{"bn":"কালবুন — কুকুর","en":"kalbun — dog"},"desc":{"bn":"হালকা ك","en":"light ك"}}]},{"type":"steps","items":[{"title":{"bn":"শুনুন","en":"Listen"},"desc":{"bn":"আরবি লেখায় চাপ দিয়ে আওয়াজ শুনুন (বইয়ে থাকলে শিক্ষক বা ক্বারীর তিলাওয়াত শুনুন)।","en":"Tap Arabic text to hear it (with the book, listen to a teacher or reciter)."}},{"title":{"bn":"জোরে বলুন","en":"Say it aloud"},"desc":{"bn":"মনে মনে নয় — মুখে জোরে বলুন। জিভ ও ঠোঁটকে অভ্যস্ত করুন।","en":"Not silently — out loud. Train your tongue and lips."}},{"title":{"bn":"লিখুন","en":"Write it"},"desc":{"bn":"প্রতিটি অক্ষর আঙুল বা কলম দিয়ে ট্রেস করুন।","en":"Trace every letter with your finger or a pen."}},{"title":{"bn":"কুইজ দিন","en":"Take the quiz"},"desc":{"bn":"প্রতি পাঠের শেষে কুইজ দিন — ভুল হলে আবার দেখুন।","en":"Finish each lesson with its quiz — review whatever you miss."}},{"title":{"bn":"আগেরটা ঝালাই করুন","en":"Review yesterday"},"desc":{"bn":"নতুন পাঠের আগে ২ মিনিট আগের পাঠ দেখে নিন।","en":"Spend 2 minutes on yesterday's lesson before starting a new one."}}],"title":{"bn":"প্রতিদিন ১৫ মিনিটের রুটিন","en":"Your 15-minute daily routine"}},{"type":"tip","kind":"tip","bn":"প্রতিদিন ১৫ মিনিট, সপ্তাহে একদিন ৩ ঘণ্টার চেয়ে অনেক বেশি কাজ করে। একটা নির্দিষ্ট সময় ঠিক করুন — যেমন ফজরের পর বা ঘুমানোর আগে।","en":"15 minutes every day beats 3 hours once a week. Pick a fixed time — after Fajr, or before bed."},{"type":"tip","kind":"tip","bn":"অ্যাপে: যেকোনো আরবি লেখা বা অক্ষরে চাপ দিলে আওয়াজ শোনা যাবে। বইয়ে: কুইজের উত্তর ইউনিটের শেষে আছে, আর ট্রেসিংয়ের জন্য ডট লাইন দেওয়া আছে।","en":"In the app: tap any Arabic word or letter to hear it. In the book: quiz answers are at the end of the unit, and dotted rows are there for tracing.","title":{"bn":"অ্যাপ ও বই ব্যবহার","en":"Using the app and book"}},{"type":"practice","bn":"ডান দিক থেকে শুরু করে প্রতিটি অক্ষরে আঙুল রাখুন (নাম এখনই না জানলেও চলবে)।","en":"Starting from the right, touch each letter (it's fine if you don't know the names yet).","lines":["ا ب ت ث","ج ح خ","د ذ ر ز"]},{"type":"quiz","items":[{"q":{"bn":"আরবি কোন দিক থেকে পড়া হয়?","en":"Which way is Arabic read?"},"options":[{"bn":"ডান থেকে বাম","en":"Right to left"},{"bn":"বাম থেকে ডান","en":"Left to right"},{"bn":"ওপর থেকে নিচে","en":"Top to bottom"}],"answer":0},{"q":{"bn":"এই কোর্সে আরবি বর্ণমালায় কয়টি অক্ষর?","en":"How many letters does the Arabic alphabet have in this course?"},"options":[{"bn":"২৬","en":"26"},{"bn":"২৯","en":"29"},{"bn":"৩৯","en":"39"}],"answer":1,"explain":{"bn":"হামযাসহ ২৯টি অক্ষর।","en":"29 letters, counting hamza."}},{"q":{"bn":"আরবিতে স্বর (আ, ই, উ) সাধারণত কীভাবে লেখা হয়?","en":"How are vowels (a, i, u) usually written in Arabic?"},"options":[{"bn":"বড় হাতের অক্ষর দিয়ে","en":"With capital letters"},{"bn":"অক্ষরের ওপরে-নিচে ছোট্ট চিহ্ন দিয়ে","en":"With tiny marks above or below letters"},{"bn":"আলাদা বড় অক্ষর দিয়ে","en":"With separate big letters"}],"answer":1},{"q":{"bn":"আরবিতে কি বড় হাতের (capital) অক্ষর আছে?","en":"Does Arabic have capital letters?"},"options":[{"bn":"হ্যাঁ","en":"Yes"},{"bn":"না","en":"No"}],"answer":1},{"q":{"bn":"এই শব্দের অর্থ কী?","en":"What does this word mean?"},"ar":"قَلْبٌ","options":[{"bn":"কুকুর","en":"dog"},{"bn":"কলম","en":"pen"},{"bn":"হৃদয়","en":"heart"}],"answer":2,"explain":{"bn":"قَلْبٌ = হৃদয়; كَلْبٌ = কুকুর। একটি অক্ষরেই অর্থ বদলে যায়!","en":"قَلْبٌ = heart; كَلْبٌ = dog. One letter changes everything!"}},{"q":{"bn":"আরবি শেখার সবচেয়ে ভালো রুটিন কোনটি?","en":"What is the best routine for learning?"},"options":[{"bn":"প্রতিদিন ১৫ মিনিট","en":"15 minutes every day"},{"bn":"শুধু পরীক্ষার আগে","en":"Only before a test"},{"bn":"মাসে একবার ৩ ঘণ্টা","en":"3 hours once a month"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-letters-1","icon":"ا ب","title":{"bn":"অক্ষর ১: আলিফ থেকে খা","en":"Letters 1: Alif to Khaa"},"subtitle":{"bn":"প্রথম ৭টি অক্ষর: ا ب ت ث ج ح خ","en":"The first 7 letters: ا ب ت ث ج ح خ"},"minutes":15,"goals":[{"bn":"প্রথম ৭টি অক্ষরের নাম, আকার ও উচ্চারণ","en":"Names, shapes and sounds of the first 7 letters"},{"bn":"বিন্দু দেখে ب ت ث চেনা","en":"Telling ب ت ث apart by their dots"},{"bn":"গলার অক্ষর ح ও খ-এর সঠিক আওয়াজ","en":"The throat sounds ح and خ"}],"blocks":[{"type":"text","bn":"চলুন প্রথম ৭টি অক্ষরের সাথে পরিচিত হই! প্রতিটি কার্ডে চাপ দিন, আওয়াজ শুনুন, আর জোরে জোরে নাম বলুন।","en":"Let's meet the first 7 letters! Tap each card, listen, and say the name out loud."},{"type":"letters","items":["alif","ba","ta","tha","jim","hha","kha"]},{"type":"text","bn":"**আলিফ (ا)** একটা সোজা খাড়া দাগ। আলিফ নিজে কোনো আলাদা শব্দ করে না — এটি হয় হামযা বা হরকত বহন করে (أَ = আ), নয়তো আগের 'আ'-কে লম্বা করে (بَا = বা-)।","en":"**Alif (ا)** is one straight standing line. It makes no sound of its own — it either carries a hamza/vowel (أَ = a) or stretches the 'a' before it (بَا = bā).","title":{"bn":"আলিফ: সোজা লাঠি","en":"Alif: the straight stick"}},{"type":"text","bn":"এবার একটা ছোট্ট পরিবার: **ب ت ث**। তিন ভাইয়ের শরীর একদম এক — একটা চ্যাপ্টা নৌকা। পার্থক্য শুধু **বিন্দুতে**।","en":"Now a little family: **ب ت ث**. The three brothers have exactly the same body — a flat boat. The only difference is the **dots**.","title":{"bn":"নৌকা পরিবার","en":"The boat family"}},{"type":"compare","items":[{"ar":"ب","label":{"bn":"বা","en":"Baa"},"desc":{"bn":"নিচে ১ বিন্দু","en":"1 dot below"}},{"ar":"ت","label":{"bn":"তা","en":"Taa"},"desc":{"bn":"ওপরে ২ বিন্দু","en":"2 dots above"}},{"ar":"ث","label":{"bn":"ছা","en":"Thaa"},"desc":{"bn":"ওপরে ৩ বিন্দু","en":"3 dots above"}}]},{"type":"tip","kind":"memory","bn":"১-২-৩ সিঁড়ি: বা = নিচে ১, তা = ওপরে ২, ছা = ওপরে ৩। অক্ষর যত এগোয়, বিন্দু তত বাড়ে!","en":"The 1-2-3 ladder: Baa = 1 below, Taa = 2 above, Thaa = 3 above. As you move along, the dots go up!"},{"type":"tip","kind":"warn","bn":"ث (ছা)-কে 'স' পড়বেন না! জিভের আগা ওপরের দাঁতের নিচে সামান্য বের করে আলতো বাতাস ছাড়ুন — ইংরেজি think-এর th।","en":"Don't read ث (Thaa) as 's'! Let the tongue tip peek out under the upper teeth and blow gently — the 'th' of 'think'."},{"type":"text","bn":"দ্বিতীয় পরিবার: **ج ح خ**। শরীর এক — একটা খোলা মুখ বা বড়শি। এখানেও পার্থক্য বিন্দুতে: জীমের পেটে, খা-এর মাথায়, আর হা-এর কোথাও নেই।","en":"Second family: **ج ح خ**. Same body — an open mouth or hook. Again the dots decide: Jeem's is in the belly, Khaa's on the head, and Ḥaa has none.","title":{"bn":"বড়শি পরিবার","en":"The hook family"}},{"type":"compare","items":[{"ar":"ج","label":{"bn":"জীম","en":"Jeem"},"desc":{"bn":"পেটের ভেতরে ১ বিন্দু","en":"1 dot inside the belly"}},{"ar":"ح","label":{"bn":"হা","en":"Ḥaa"},"desc":{"bn":"কোনো বিন্দু নেই","en":"no dot"}},{"ar":"خ","label":{"bn":"খা","en":"Khaa"},"desc":{"bn":"মাথার ওপরে ১ বিন্দু","en":"1 dot on top"}}]},{"type":"text","bn":"ح ও خ দুটোই **গলা** থেকে আসে, কিন্তু গলার ভিন্ন জায়গা থেকে। আসল মজা এখানেই — চলুন আওয়াজের তফাৎ শুনি।","en":"ح and خ both come from the **throat**, but from different parts of it. Here's the fun bit — let's hear the difference.","title":{"bn":"গলার আওয়াজ","en":"Throat sounds"}},{"type":"compare","items":[{"ar":"حَ","label":{"bn":"হা — গলার মাঝখান","en":"ḥa — middle of throat"},"desc":{"bn":"পরিষ্কার, ঘষা বাতাস: গরম চা খেয়ে 'হাহ্'","en":"clean, raspy air: the 'ḥaah' after hot tea"}},{"ar":"خَ","label":{"bn":"খা — গলার ওপর","en":"kha — top of throat"},"desc":{"bn":"খসখসে, মোটা আওয়াজ: গলা পরিষ্কার করার মতো","en":"scratchy, heavy: like clearing your throat"}},{"ar":"هَ","label":{"bn":"হা (গোল হা) — গলার গভীর","en":"ha — deepest throat"},"desc":{"bn":"নরম, হালকা 'হ' (পরে শিখব)","en":"soft, light 'h' (coming later)"}}]},{"type":"tip","kind":"memory","bn":"ح বলার কৌশল: চশমার কাচে ভাপ দিন 'হাআ', এবার গলাটা একটু চেপে ধরুন — এটাই ح! আর خ: যেন গলায় কাঁটা আটকেছে, পরিষ্কার করছেন।","en":"Trick for ح: breathe 'haaa' to fog your glasses, then tighten the throat a little — that's ح! And خ: as if clearing a fishbone from your throat."},{"type":"examples","items":[{"ar":"أَبٌ","tr":{"bn":"আবুন","en":"abun"},"mean":{"bn":"বাবা","en":"father"},"hl":"أ"},{"ar":"بَابٌ","tr":{"bn":"বাবুন","en":"bābun"},"mean":{"bn":"দরজা","en":"door"},"hl":"ب"},{"ar":"تَمْرٌ","tr":{"bn":"তামরুন","en":"tamrun"},"mean":{"bn":"খেজুর","en":"dates"},"hl":"ت"},{"ar":"ثَوْبٌ","tr":{"bn":"ছাওবুন","en":"thawbun"},"mean":{"bn":"পোশাক","en":"garment"},"hl":"ث"},{"ar":"جَبَلٌ","tr":{"bn":"জাবালুন","en":"jabalun"},"mean":{"bn":"পাহাড়","en":"mountain"},"hl":"ج"},{"ar":"حَجٌّ","tr":{"bn":"হাজ্জুন","en":"ḥajjun"},"mean":{"bn":"হজ","en":"Hajj"},"hl":"ح"},{"ar":"خُبْزٌ","tr":{"bn":"খুবযুন","en":"khubzun"},"mean":{"bn":"রুটি","en":"bread"},"hl":"خ"}],"title":{"bn":"শব্দে অক্ষর খুঁজুন (শুনুন ও বলুন)","en":"Find the letter in a word (listen and repeat)"}},{"type":"tip","kind":"fun","bn":"এই শব্দগুলো এখনই পড়তে না পারলেও কোনো সমস্যা নেই! শুধু শুনুন আর অক্ষরটা খুঁজে বের করুন। কয়েক পাঠ পরে নিজেই পড়বেন, ইন শা আল্লাহ।","en":"Don't worry if you can't read these words yet! Just listen and spot the letter. In a few lessons you'll read them yourself, in sha Allah."},{"type":"trace","items":["ا","ب","ت","ث","ج","ح","خ"],"title":{"bn":"লেখার অনুশীলন","en":"Writing practice"}},{"type":"tip","kind":"tip","bn":"লেখার সময়ও ডান থেকে বামে কলম চালান। আগে শরীর লিখুন, শেষে বিন্দু দিন।","en":"When writing, move your pen right to left too. Write the body first, add the dots last."},{"type":"practice","bn":"প্রতিটি অক্ষরের নাম জোরে বলুন। ডান দিক থেকে শুরু করুন!","en":"Say each letter's name aloud. Start from the right!","lines":["ا ب ت ث","ج ح خ","ب ت ث ب","ح خ ج ح","ث ت ب ا","خ ح ج ب ت","ا ث ح ت خ ب ج"]},{"type":"quiz","items":[{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ب","options":[{"bn":"বা","en":"Baa"},{"bn":"তা","en":"Taa"},{"bn":"ছা","en":"Thaa"},{"bn":"নূন","en":"Noon"}],"answer":0},{"q":{"bn":"ث অক্ষরে কয়টি বিন্দু?","en":"How many dots does ث have?"},"ar":"ث","options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":2},{"q":{"bn":"এই অক্ষরের বিন্দু কোথায়?","en":"Where is this letter's dot?"},"ar":"خ","options":[{"bn":"নিচে","en":"Below"},{"bn":"পেটের ভেতরে","en":"Inside the belly"},{"bn":"ওপরে","en":"Above"}],"answer":2},{"q":{"bn":"কোন অক্ষর গলার মাঝখান থেকে আসে?","en":"Which letter comes from the middle of the throat?"},"options":["ح","ج","خ"],"answer":0},{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ت","options":[{"bn":"বা","en":"Baa"},{"bn":"তা","en":"Taa"},{"bn":"ছা","en":"Thaa"}],"answer":1},{"q":{"bn":"ث-এর সঠিক আওয়াজ কোনটি?","en":"What is the correct sound of ث?"},"options":[{"bn":"স","en":"s"},{"bn":"শ","en":"sh"},{"bn":"think-এর th","en":"'th' as in think"}],"answer":2},{"q":{"bn":"কোন অক্ষরের পেটের ভেতরে বিন্দু?","en":"Which letter has its dot inside the belly?"},"options":["ج","ح","خ"],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-letters-2","icon":"د س","title":{"bn":"অক্ষর ২: দাল থেকে সোয়াদ","en":"Letters 2: Daal to Ṣaad"},"subtitle":{"bn":"পরের ৭টি অক্ষর: د ذ ر ز س ش ص","en":"The next 7 letters: د ذ ر ز س ش ص"},"minutes":15,"goals":[{"bn":"د ذ ر ز — চার 'লাজুক' অক্ষর চেনা","en":"Meet four 'shy' letters: د ذ ر ز"},{"bn":"দাল আর রা-এর আকারের পার্থক্য","en":"The shape difference between Daal and Raa"},{"bn":"س ش ص — তিন রকম 'স'-এর আওয়াজ","en":"Three kinds of 's': س ش ص"}],"blocks":[{"type":"text","bn":"দারুণ! আপনি ৭টি অক্ষর শিখে ফেলেছেন। এবার আরও ৭টি। এই দলে আছে দুটি জোড়া (د ذ, ر ز) আর 'স'-এর তিন রকম রূপ।","en":"Great job — 7 letters down! Now 7 more. This group has two pairs (د ذ, ر ز) and three different kinds of 's'."},{"type":"letters","items":["dal","dhal","ra","zay","sin","shin","sad"]},{"type":"text","bn":"**د (দাল)** দেখতে একটা ভাঁজ করা কনুইয়ের মতো, আর **ر (রা)** একটা ছোট্ট স্লিপারের মতো। দুটোকে প্রায়ই গুলিয়ে ফেলা হয় — চলুন পাশাপাশি দেখি।","en":"**د (Daal)** looks like a bent elbow, and **ر (Raa)** like a little slide. People often mix them up — let's put them side by side.","title":{"bn":"দাল বনাম রা","en":"Daal vs Raa"}},{"type":"compare","items":[{"ar":"د","label":{"bn":"দাল","en":"Daal"},"desc":{"bn":"কোণাকৃতি, লাইনের ওপরে বসে থাকে","en":"angled, sits ON the line"}},{"ar":"ر","label":{"bn":"রা","en":"Raa"},"desc":{"bn":"গোল বাঁক, লাইনের নিচে নেমে যায়","en":"curved, dips BELOW the line"}}]},{"type":"tip","kind":"memory","bn":"দাল **দাঁড়িয়ে** থাকে লাইনের ওপর (দ = দাঁড়ানো), আর রা **রাস্তায় পিছলে** নিচে চলে যায় (র = রাস্তা)!","en":"Daal **sits** on the line like someone resting; Raa **slides** down below it. Daal = Down-sitting, Raa = Rolling down!"},{"type":"text","bn":"এবার বিন্দু যোগ করুন: দাল + বিন্দু = **ذ (যাল)**, রা + বিন্দু = **ز (যা)**। দুটোর বাংলা উচ্চারণ লেখা হয় 'য' দিয়ে, কিন্তু আসলে আওয়াজ একদম আলাদা!","en":"Now add a dot: Daal + dot = **ذ (Dhaal)**, Raa + dot = **ز (Zaay)**. Bangla writes both with 'য', but they actually sound quite different!","title":{"bn":"দুই রকম 'য'","en":"Two different 'z' sounds"}},{"type":"compare","items":[{"ar":"ذَ","label":{"bn":"যাল — জিভ দাঁতের ফাঁকে","en":"dha — tongue between teeth"},"desc":{"bn":"ইংরেজি this-এর th; জিভ একটু বের হবে","en":"the 'th' in 'this'; tongue peeks out"}},{"ar":"زَ","label":{"bn":"যা — জিভ ভেতরে","en":"za — tongue inside"},"desc":{"bn":"মৌমাছির 'যযয'; ইংরেজি z","en":"a bee's 'zzz'; English z"}}]},{"type":"tip","kind":"warn","bn":"বাংলাভাষীরা ذ ও ز দুটোকেই প্রায়ই 'জ' পড়েন। এটা ভুল! ذ-তে জিভ দাঁতে, ز-তে মৌমাছির গুঞ্জন — কোনোটাই 'জ' নয়।","en":"Bangla speakers often read both ذ and ز as 'j'. That's wrong! ذ = tongue on teeth, ز = bee buzz — neither is 'j'."},{"type":"tip","kind":"fun","bn":"د ذ ر ز — এই চারটি অক্ষর একটু 'লাজুক': এরা আগের অক্ষরের হাত ধরে, কিন্তু পরের অক্ষরের সাথে কখনো জোড়া লাগে না। এদের কথা পরে বিস্তারিত শিখব।","en":"د ذ ر ز are a bit 'shy': they hold the hand of the letter before them, but never join to the letter after. More about this later."},{"type":"text","bn":"এবার 'স' পরিবার। **س (সীন)** তিন দাঁতওয়ালা, **ش (শীন)** একই আকারের ওপর তিন বিন্দু, আর **ص (সোয়াদ)** একটা মোটা লুপ।","en":"Now the 's' family. **س (Seen)** has three teeth, **ش (Sheen)** is the same shape with three dots, and **ص (Ṣaad)** is a fat loop.","title":{"bn":"তিন রকম 'স'","en":"Three kinds of 's'"}},{"type":"compare","items":[{"ar":"سَ","label":{"bn":"সীন — চিকন স","en":"sa — thin s"},"desc":{"bn":"পাতলা শিস, সাপের স্‌স্‌স্","en":"thin hiss, like a snake"}},{"ar":"شَ","label":{"bn":"শীন — শ","en":"sha — sh"},"desc":{"bn":"চুপ করানোর শ্‌শ্‌","en":"the 'shh' of 'hush'"}},{"ar":"صَ","label":{"bn":"সোয়াদ — মোটা স","en":"ṣa — heavy s"},"desc":{"bn":"জিভের পেছন তুলে মুখ ভরা আওয়াজ","en":"back of tongue raised, full-mouthed"}}]},{"type":"tip","kind":"warn","bn":"সবচেয়ে সাধারণ ভুল: س-কে 'শ' পড়া। سَلَامٌ হলো 'সালাম', 'শালাম' নয়! আওয়াজ চিকন রাখুন।","en":"The most common slip: reading س as 'sh'. سَلَامٌ is 'salām', not 'shalām'! Keep it thin."},{"type":"tip","kind":"memory","bn":"সীনের তিন দাঁত = চিরুনি। শীন = চিরুনির ওপর তিন ফোঁটা পানি 'শ্‌শ্‌' করে পড়ছে। সোয়াদ = মোটা ডিম — মোটা আওয়াজ!","en":"Seen's three teeth = a comb. Sheen = three water drops on the comb going 'shh'. Ṣaad = a fat egg — fat sound!"},{"type":"examples","items":[{"ar":"دَرْسٌ","tr":{"bn":"দারসুন","en":"darsun"},"mean":{"bn":"পাঠ","en":"lesson"},"hl":"د"},{"ar":"ذَهَبٌ","tr":{"bn":"যাহাবুন","en":"dhahabun"},"mean":{"bn":"সোনা","en":"gold"},"hl":"ذ"},{"ar":"رَحْمَةٌ","tr":{"bn":"রাহমাতুন","en":"raḥmatun"},"mean":{"bn":"দয়া, রহমত","en":"mercy"},"hl":"ر"},{"ar":"زَكَاةٌ","tr":{"bn":"যাকাতুন","en":"zakātun"},"mean":{"bn":"যাকাত","en":"zakah (charity)"},"hl":"ز"},{"ar":"سَمَكٌ","tr":{"bn":"সামাকুন","en":"samakun"},"mean":{"bn":"মাছ","en":"fish"},"hl":"س"},{"ar":"شَجَرٌ","tr":{"bn":"শাজারুন","en":"shajarun"},"mean":{"bn":"গাছপালা","en":"trees"},"hl":"ش"},{"ar":"صَلَاةٌ","tr":{"bn":"সালাতুন","en":"ṣalātun"},"mean":{"bn":"নামায, সালাত","en":"prayer"},"hl":"ص"}],"title":{"bn":"শব্দে অক্ষর খুঁজুন","en":"Find the letter in a word"}},{"type":"trace","items":["د","ذ","ر","ز","س","ش","ص"],"title":{"bn":"লেখার অনুশীলন","en":"Writing practice"}},{"type":"practice","bn":"নাম বলুন — দ্রুত, কিন্তু সঠিকভাবে!","en":"Say the names — quickly, but correctly!","lines":["د ذ ر ز","س ش ص","د ر د ر","ذ ز ذ ز","س ص س ص","ش س ص ذ ز","ا ب ت ث ج ح خ د ذ ر ز س ش ص"]},{"type":"quiz","items":[{"q":{"bn":"কোন অক্ষর লাইনের নিচে নেমে যায়?","en":"Which letter dips below the line?"},"options":["د","ر"],"answer":1},{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ذ","options":[{"bn":"যা","en":"Zaay"},{"bn":"যাল","en":"Dhaal"},{"bn":"দাল","en":"Daal"}],"answer":1},{"q":{"bn":"ইংরেজি this-এর th আওয়াজ কোন অক্ষরের?","en":"Which letter has the 'th' sound of 'this'?"},"options":["ج","ز","ذ"],"answer":2},{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ش","options":[{"bn":"শীন","en":"Sheen"},{"bn":"সোয়াদ","en":"Ṣaad"},{"bn":"সীন","en":"Seen"}],"answer":0},{"q":{"bn":"কোনটি মোটা (ভারী) 'স'?","en":"Which one is the heavy 's'?"},"options":["ش","ص","س"],"answer":1},{"q":{"bn":"سَلَامٌ শব্দের প্রথম আওয়াজ কোনটি?","en":"What is the first sound of سَلَامٌ?"},"options":[{"bn":"শ","en":"sh"},{"bn":"ছ","en":"ch"},{"bn":"স (চিকন)","en":"s (thin)"}],"answer":2},{"q":{"bn":"ز-এর সঠিক আওয়াজ কোনটি?","en":"What is the correct sound of ز?"},"options":[{"bn":"মৌমাছির মতো z","en":"a buzzing z"},{"bn":"জ (j)","en":"j"},{"bn":"দ","en":"d"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-letters-3","icon":"ض ق","title":{"bn":"অক্ষর ৩: দোয়াদ থেকে ক্বাফ","en":"Letters 3: Ḍaad to Qaaf"},"subtitle":{"bn":"পরের ৭টি অক্ষর: ض ط ظ ع غ ف ق","en":"The next 7 letters: ض ط ظ ع غ ف ق"},"minutes":15,"goals":[{"bn":"মোটা (ভারী) অক্ষর কী এবং কীভাবে বলতে হয়","en":"What heavy letters are and how to say them"},{"bn":"হালকা-মোটা জোড়া: ت/ط, د/ض, ذ/ظ, س/ص","en":"Light–heavy pairs: ت/ط, د/ض, ذ/ظ, س/ص"},{"bn":"গলার অক্ষর ع ও غ","en":"The throat letters ع and غ"}],"blocks":[{"type":"text","bn":"এই পাঠে আছে আরবির সবচেয়ে 'স্পেশাল' কিছু আওয়াজ। মনোযোগ দিয়ে শুনুন — একবার ধরে ফেললে আপনার তিলাওয়াত অনেক সুন্দর হবে!","en":"This lesson has some of Arabic's most special sounds. Listen closely — once you get them, your recitation will sound beautiful!"},{"type":"letters","items":["dad","tta","zza","ain","ghain","fa","qaf"]},{"type":"text","bn":"আরবিতে ৭টি অক্ষর **মোটা (ভারী)** — এগুলো বলার সময় জিভের পেছনটা ওপরের তালুর দিকে উঠে যায়, ফলে আওয়াজ মুখ ভরে গভীর হয়। বাকিগুলো সাধারণত **পাতলা (হালকা)**।","en":"Arabic has 7 **heavy** letters — when you say them, the back of the tongue rises toward the roof of the mouth, making a full, deep sound. Most others are **light**.","title":{"bn":"মোটা অক্ষর","en":"Heavy letters"}},{"type":"tip","kind":"memory","bn":"৭টি মোটা অক্ষর মনে রাখার বিখ্যাত আরবি বাক্য: {{خُصَّ ضَغْطٍ قِظْ}} — এতে আছে خ ص ض غ ط ق ظ। (খুস্‌সা দাগতিন ক্বিয্)","en":"The famous Arabic phrase to remember the 7 heavy letters: {{خُصَّ ضَغْطٍ قِظْ}} — it contains خ ص ض غ ط ق ظ. (khuṣṣa ḍaghṭin qiẓ)"},{"type":"tip","kind":"tip","bn":"মোটা অক্ষর বলার কৌশল: মুখে যেন একটা ছোট্ট আলু আছে — জিভের পেছন উঁচু, মুখ ভেতরে ফাঁপা। পাতলা অক্ষরে মুখ সমান ও হালকা।","en":"Trick for heavy letters: imagine a small potato in your mouth — back of the tongue raised, mouth hollow inside. For light letters the mouth stays flat and relaxed."},{"type":"text","bn":"মজার ব্যাপার হলো, অনেক মোটা অক্ষরের একটা করে 'হালকা যমজ' আছে। জায়গা প্রায় এক, শুধু জিভের পেছন ওঠে কি না — এই তফাৎ।","en":"Here's the cool part: many heavy letters have a 'light twin'. Almost the same spot — the only difference is whether the back of the tongue rises.","title":{"bn":"হালকা ও মোটা যমজ","en":"Light and heavy twins"}},{"type":"table","head":[{"bn":"হালকা","en":"Light"},{"bn":"মোটা","en":"Heavy"},{"bn":"তফাৎ","en":"Difference"}],"rows":[["تَ","طَ",{"bn":"ত বনাম মোটা ত","en":"t vs heavy ṭ"}],["دَ","ضَ",{"bn":"দ বনাম পাশ থেকে মোটা দ","en":"d vs heavy side-ḍ"}],["ذَ","ظَ",{"bn":"হালকা th বনাম মোটা th","en":"light dh vs heavy ẓ"}],["سَ","صَ",{"bn":"চিকন স বনাম মোটা স","en":"thin s vs heavy ṣ"}],["كَ","قَ",{"bn":"হালকা ক বনাম গভীর ক্ব","en":"light k vs deep q"}]]},{"type":"compare","items":[{"ar":"تِينٌ","label":{"bn":"তীনুন — ডুমুর","en":"tīnun — fig"},"desc":{"bn":"হালকা ت","en":"light ت"}},{"ar":"طِينٌ","label":{"bn":"ত্বীনুন — কাদামাটি","en":"ṭīnun — clay"},"desc":{"bn":"মোটা ط","en":"heavy ط"}}],"title":{"bn":"একটি অক্ষরেই অর্থ বদল","en":"One letter, a new meaning"}},{"type":"tip","kind":"warn","bn":"ض (দোয়াদ) 'য' বা 'জ' নয়, সাধারণ 'দ'-ও নয়। জিভের এক পাশ ওপরের মাড়ির দাঁতে চেপে মোটা আওয়াজ করুন। শুরুতে কঠিন লাগবে — একজন ভালো ক্বারীর তিলাওয়াত শুনে বারবার অনুশীলন করুন।","en":"ض (Ḍaad) is not 'z' or 'j', and not a plain 'd'. Press one side of the tongue against the upper molars and make it heavy. It feels hard at first — listen to a good reciter and repeat often."},{"type":"text","bn":"এবার গলার আরও দুটি অক্ষর: **ع (আইন)** আর **غ (গাইন)**। একই শরীর, গাইনের মাথায় একটি বিন্দু।","en":"Now two more throat letters: **ع ('Ayn)** and **غ (Ghayn)**. Same body; Ghayn has a dot on its head.","title":{"bn":"আইন ও গাইন","en":"'Ayn and Ghayn"}},{"type":"compare","items":[{"ar":"أَ","label":{"bn":"হামযা — হালকা থামা","en":"hamza — light stop"},"desc":{"bn":"গলার গভীরে ছোট্ট 'থামা', তারপর আ","en":"a tiny stop deep in the throat, then a"}},{"ar":"عَ","label":{"bn":"আইন — চাপা আ","en":"'a — squeezed a"},"desc":{"bn":"গলার মাঝখান চেপে গভীর 'আ'","en":"a deep 'a' with the middle of the throat squeezed"}},{"ar":"غَ","label":{"bn":"গাইন — গার্গল","en":"gha — gargle"},"desc":{"bn":"গলার ওপর থেকে কম্পন, মোটা","en":"vibration from the top of the throat, heavy"}}]},{"type":"tip","kind":"memory","bn":"ع বলার কৌশল: মনে করুন কেউ আপনার গলা হালকা চেপে ধরেছে আর আপনি 'আ' বলছেন — চাপা, গভীর আওয়াজ। غ: মুখে পানি নিয়ে গার্গল করার আওয়াজ, শুধু পানি ছাড়া!","en":"Trick for ع: imagine saying 'a' while your throat is gently squeezed — tight and deep. غ: the sound of gargling, minus the water!"},{"type":"text","bn":"শেষে **ف (ফা)** আর **ق (ক্বাফ)**। মাথা দেখতে একই রকম, কিন্তু ফা-তে এক বিন্দু আর শরীর লাইনের ওপরে; ক্বাফে দুই বিন্দু আর লেজ লাইনের নিচে গভীর বাটির মতো।","en":"Finally **ف (Faa)** and **ق (Qaaf)**. Their heads look alike, but Faa has one dot and a flat body on the line; Qaaf has two dots and a deep bowl dipping below the line.","title":{"bn":"ফা ও ক্বাফ","en":"Faa and Qaaf"}},{"type":"compare","items":[{"ar":"ف","label":{"bn":"ফা","en":"Faa"},"desc":{"bn":"১ বিন্দু, চ্যাপ্টা শরীর","en":"1 dot, flat body"}},{"ar":"ق","label":{"bn":"ক্বাফ","en":"Qaaf"},"desc":{"bn":"২ বিন্দু, গভীর বাটি","en":"2 dots, deep bowl"}}]},{"type":"tip","kind":"warn","bn":"ف আসলে ইংরেজি f — ওপরের দাঁত নিচের ঠোঁটে। বাংলা 'ফ'-এর মতো দুই ঠোঁট মিলিয়ে 'ফ' (ph) বলবেন না।","en":"ف is really English f — upper teeth on the lower lip. Don't close both lips for a Bangla-style 'ph'."},{"type":"examples","items":[{"ar":"ضَيْفٌ","tr":{"bn":"দোয়াইফুন","en":"ḍayfun"},"mean":{"bn":"মেহমান","en":"guest"},"hl":"ض"},{"ar":"طِفْلٌ","tr":{"bn":"ত্বিফলুন","en":"ṭiflun"},"mean":{"bn":"শিশু","en":"child"},"hl":"ط"},{"ar":"ظُهْرٌ","tr":{"bn":"যুহরুন","en":"ẓuhrun"},"mean":{"bn":"দুপুর, যোহর","en":"noon"},"hl":"ظ"},{"ar":"عَيْنٌ","tr":{"bn":"'আইনুন","en":"'aynun"},"mean":{"bn":"চোখ","en":"eye"},"hl":"ع"},{"ar":"غَيْبٌ","tr":{"bn":"গাইবুন","en":"ghaybun"},"mean":{"bn":"অদৃশ্য","en":"the unseen"},"hl":"غ"},{"ar":"فَجْرٌ","tr":{"bn":"ফাজরুন","en":"fajrun"},"mean":{"bn":"ভোর, ফজর","en":"dawn"},"hl":"ف"},{"ar":"قَمَرٌ","tr":{"bn":"ক্বামারুন","en":"qamarun"},"mean":{"bn":"চাঁদ","en":"moon"},"hl":"ق"}],"title":{"bn":"শব্দে অক্ষর খুঁজুন","en":"Find the letter in a word"}},{"type":"trace","items":["ض","ط","ظ","ع","غ","ف","ق"],"title":{"bn":"লেখার অনুশীলন","en":"Writing practice"}},{"type":"practice","bn":"জোড়ায় জোড়ায় বলুন — হালকা, তারপর মোটা। পার্থক্যটা অনুভব করুন!","en":"Say them in pairs — light, then heavy. Feel the difference!","lines":["تَ طَ","دَ ضَ","ذَ ظَ","سَ صَ","كَ قَ","أَ عَ غَ","ض ط ظ ع غ ف ق"]},{"type":"quiz","items":[{"q":{"bn":"নিচের কোনটি মোটা (ভারী) অক্ষর?","en":"Which of these is a heavy letter?"},"options":["ت","ط","ف"],"answer":1},{"q":{"bn":"{{خُصَّ ضَغْطٍ قِظْ}} বাক্যটি কী মনে রাখতে সাহায্য করে?","en":"What does the phrase {{خُصَّ ضَغْطٍ قِظْ}} help you remember?"},"options":[{"bn":"৭টি মোটা অক্ষর","en":"The 7 heavy letters"},{"bn":"গলার অক্ষর","en":"The throat letters"},{"bn":"ঠোঁটের অক্ষর","en":"The lip letters"}],"answer":0},{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ع","options":[{"bn":"হামযা","en":"Hamzah"},{"bn":"গাইন","en":"Ghayn"},{"bn":"আইন","en":"'Ayn"}],"answer":2},{"q":{"bn":"ক্বাফ (ق)-এ কয়টি বিন্দু?","en":"How many dots does Qaaf (ق) have?"},"options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":1},{"q":{"bn":"س-এর মোটা যমজ কোনটি?","en":"Which is the heavy twin of س?"},"options":["ص","ث","ش"],"answer":0},{"q":{"bn":"طِينٌ শব্দের অর্থ কী?","en":"What does طِينٌ mean?"},"ar":"طِينٌ","options":[{"bn":"ডুমুর","en":"fig"},{"bn":"কাদামাটি","en":"clay"},{"bn":"চাঁদ","en":"moon"}],"answer":1},{"q":{"bn":"ف উচ্চারণের সময় কী হয়?","en":"How is ف pronounced?"},"options":[{"bn":"দুই ঠোঁট মিলে যায়","en":"Both lips close"},{"bn":"জিভ তালুতে লাগে","en":"Tongue touches the palate"},{"bn":"ওপরের দাঁত নিচের ঠোঁটে লাগে","en":"Upper teeth touch the lower lip"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-letters-4","icon":"ن ي","title":{"bn":"অক্ষর ৪: কাফ থেকে ইয়া","en":"Letters 4: Kaaf to Yaa"},"subtitle":{"bn":"শেষ ৮টি অক্ষর: ك ل م ن و ه ء ي","en":"The last 8 letters: ك ل م ن و ه ء ي"},"minutes":15,"goals":[{"bn":"শেষ ৮টি অক্ষর চেনা ও বলা","en":"Recognise and say the last 8 letters"},{"bn":"হামযা কোথায় কোথায় বসে","en":"Where hamza sits"},{"bn":"পুরো বর্ণমালা ক্রমানুসারে বলা","en":"Say the whole alphabet in order"}],"blocks":[{"type":"text","bn":"শেষ ধাপ! এই ৮টি অক্ষর শিখলেই আপনি পুরো আরবি বর্ণমালা জানবেন। ভালো খবর: এগুলোর বেশিরভাগই বাংলাভাষীদের জন্য খুব সহজ।","en":"The final stretch! Learn these 8 and you'll know the whole Arabic alphabet. Good news: most of them are very easy for Bangla speakers."},{"type":"letters","items":["kaf","lam","mim","nun","waw","ha","hamza","ya"]},{"type":"compare","items":[{"ar":"ا","label":{"bn":"আলিফ","en":"Alif"},"desc":{"bn":"সোজা লাঠি, কোনো হুক নেই","en":"straight stick, no hook"}},{"ar":"ل","label":{"bn":"লাম","en":"Laam"},"desc":{"bn":"লম্বা, নিচে বাঁকা হুক","en":"tall, with a hook at the bottom"}}],"title":{"bn":"আলিফ বনাম লাম","en":"Alif vs Laam"}},{"type":"compare","items":[{"ar":"ب","label":{"bn":"বা","en":"Baa"},"desc":{"bn":"চ্যাপ্টা নৌকা, নিচে বিন্দু","en":"flat boat, dot below"}},{"ar":"ن","label":{"bn":"নূন","en":"Noon"},"desc":{"bn":"গভীর গোল বাটি, ওপরে বিন্দু","en":"deep round bowl, dot above"}}],"title":{"bn":"বা বনাম নূন","en":"Baa vs Noon"}},{"type":"tip","kind":"tip","bn":"ك (কাফ), ل (লাম), م (মীম), ن (নূন) — এগুলোর আওয়াজ বাংলা ক, ল, ম, ন-এর মতোই। শুধু ك-কে ক্বাফের মতো গভীর করবেন না।","en":"ك (Kaaf), ل (Laam), م (Meem), ن (Noon) sound just like Bangla ক, ল, ম, ন. Just don't make ك deep like Qaaf."},{"type":"text","bn":"**و (ওয়াও)** বলতে দুই ঠোঁট গোল করুন, কিন্তু মেলাবেন না। দাঁত দিয়ে ঠোঁট ছুঁলেই সেটা 'ভ' হয়ে যায় — সাবধান!","en":"For **و (Waaw)**, round your lips but don't close them. If your teeth touch your lip, it turns into 'v' — careful!","title":{"bn":"ওয়াও","en":"Waaw"}},{"type":"text","bn":"এখন আমরা তিন রকম 'হ' জানি। তিনটিই গলা থেকে, কিন্তু ভিন্ন গভীরতা থেকে:","en":"Now we know three kinds of 'h'. All from the throat, but from different depths:","title":{"bn":"তিন রকম 'হ'","en":"Three kinds of 'h'"}},{"type":"compare","items":[{"ar":"هَ","label":{"bn":"গোল হা — সবচেয়ে গভীর","en":"ha — deepest"},"desc":{"bn":"নরম, বাতাসভরা; আয়নায় ভাপ দেওয়ার মতো","en":"soft and breathy, like fogging a mirror"}},{"ar":"حَ","label":{"bn":"হা — মাঝখান","en":"ḥa — middle"},"desc":{"bn":"গলা চেপে ঘষা আওয়াজ","en":"raspy, with the throat tightened"}},{"ar":"خَ","label":{"bn":"খা — ওপর","en":"kha — top"},"desc":{"bn":"খসখসে, মোটা","en":"scratchy and heavy"}}]},{"type":"text","bn":"**ء (হামযা)** হলো একটা ছোট্ট 'থামা' — যেমন বাংলায় 'আ-আ' বলতে গিয়ে মাঝখানে গলা আটকে যায়। হামযা একা বসতে পারে, আবার আলিফ, ওয়াও বা (বিন্দুহীন) ইয়ার ওপর বসতে পারে।","en":"**ء (Hamzah)** is a tiny 'stop' — like the catch in your throat in 'uh-oh'. It can sit alone, or ride on an Alif, a Waaw or a (dotless) Yaa.","title":{"bn":"হামযা — ছোট্ট থামা","en":"Hamzah — the little stop"}},{"type":"table","head":[{"bn":"হামযা","en":"Hamzah"},{"bn":"কোথায় বসে","en":"Where it sits"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["أ",{"bn":"আলিফের ওপরে","en":"on top of Alif"},"أَكَلَ"],["إ",{"bn":"আলিফের নিচে (যের হলে)","en":"under Alif (with kasra)"},"إِبِلٌ"],["ؤ",{"bn":"ওয়াওয়ের ওপরে","en":"on Waaw"},"يُؤْمِنُ"],["ئ",{"bn":"বিন্দুহীন ইয়ার ওপরে","en":"on a dotless Yaa"},"سُئِلَ"],["ء",{"bn":"একা, লাইনের ওপরে","en":"alone, on the line"},"سَمَاءٌ"]]},{"type":"examples","items":[{"ar":"أَكَلَ","tr":{"bn":"আকালা","en":"akala"},"mean":{"bn":"সে খেল","en":"he ate"},"hl":"أ"},{"ar":"إِبِلٌ","tr":{"bn":"ইবিলুন","en":"ibilun"},"mean":{"bn":"উট","en":"camels"},"hl":"إ"},{"ar":"يُؤْمِنُ","tr":{"bn":"ইউ'মিনু","en":"yuʼminu"},"mean":{"bn":"সে ঈমান আনে","en":"he believes"},"hl":"ؤ"},{"ar":"سُئِلَ","tr":{"bn":"সু'ইলা","en":"suʼila"},"mean":{"bn":"জিজ্ঞাসা করা হলো","en":"he was asked"},"hl":"ئ"}]},{"type":"tip","kind":"memory","bn":"হামযা যেন একটা ছোট্ট পাখি — কখনো আলিফের মাথায় বসে, কখনো নিচে ঝোলে, কখনো ওয়াও বা ইয়ার ডালে বসে, আবার কখনো মাটিতে একা হাঁটে!","en":"Hamzah is like a little bird — sometimes on Alif's head, sometimes hanging under it, sometimes perched on a Waaw or Yaa branch, and sometimes walking alone on the ground!"},{"type":"tip","kind":"tip","bn":"ي (ইয়া)-র নিচে দুটি বিন্দু। শব্দের শেষে বিন্দু ছাড়া ى দেখলে সেটা 'আলিফ মাকসূরা' — এর কথা পরে শিখব।","en":"ي (Yaa) has two dots below. A dotless ى at the end of a word is an 'alif maqsura' — we'll meet it later."},{"type":"examples","items":[{"ar":"كَرِيمٌ","tr":{"bn":"কারীমুন","en":"karīmun"},"mean":{"bn":"দয়ালু, সম্মানিত","en":"generous, noble"},"hl":"ك"},{"ar":"لِسَانٌ","tr":{"bn":"লিসানুন","en":"lisānun"},"mean":{"bn":"জিহ্বা, ভাষা","en":"tongue, language"},"hl":"ل"},{"ar":"مَلِكٌ","tr":{"bn":"মালিকুন","en":"malikun"},"mean":{"bn":"রাজা","en":"king"},"hl":"م"},{"ar":"نَارٌ","tr":{"bn":"নারুন","en":"nārun"},"mean":{"bn":"আগুন","en":"fire"},"hl":"ن"},{"ar":"وَجْهٌ","tr":{"bn":"ওয়াজহুন","en":"wajhun"},"mean":{"bn":"মুখমণ্ডল","en":"face"},"hl":"و"},{"ar":"هِلَالٌ","tr":{"bn":"হিলালুন","en":"hilālun"},"mean":{"bn":"নতুন চাঁদ","en":"crescent moon"},"hl":"ه"},{"ar":"يَوْمٌ","tr":{"bn":"ইয়াওমুন","en":"yawmun"},"mean":{"bn":"দিন","en":"day"},"hl":"ي"}],"title":{"bn":"শব্দে অক্ষর খুঁজুন","en":"Find the letter in a word"}},{"type":"trace","items":["ك","ل","م","ن","و","ه","ء","ي"],"title":{"bn":"লেখার অনুশীলন","en":"Writing practice"}},{"type":"tip","kind":"fun","bn":"মাশা আল্লাহ! আপনি এখন পুরো আরবি বর্ণমালা চেনেন — ২৯টি অক্ষর! কুরআনের প্রতিটি শব্দ এই ২৯টি অক্ষর দিয়েই তৈরি।","en":"Masha Allah! You now know the whole Arabic alphabet — all 29 letters! Every word of the Quran is built from these 29.","title":{"bn":"অভিনন্দন!","en":"Congratulations!"}},{"type":"practice","bn":"পুরো বর্ণমালা ক্রমানুসারে বলুন। প্রতিদিন একবার বললে এক সপ্তাহে মুখস্থ!","en":"Say the whole alphabet in order. Once a day and it's memorised in a week!","lines":["ك ل م ن و ه ء ي","ا ب ت ث ج ح خ","د ذ ر ز س ش ص","ض ط ظ ع غ ف ق","ك ل م ن و ه ء ي","ي ه ن م ل ك ق ف","ع ح ه ء غ خ"]},{"type":"quiz","items":[{"q":{"bn":"এই অক্ষরের নাম কী?","en":"What is this letter called?"},"ar":"ل","options":[{"bn":"লাম","en":"Laam"},{"bn":"কাফ","en":"Kaaf"},{"bn":"আলিফ","en":"Alif"}],"answer":0},{"q":{"bn":"নূন (ن) আর বা (ب)-এর পার্থক্য কী?","en":"What's the difference between Noon (ن) and Baa (ب)?"},"options":[{"bn":"কোনো পার্থক্য নেই","en":"No difference"},{"bn":"নূন গভীর বাটি, বিন্দু ওপরে","en":"Noon is a deep bowl, dot above"},{"bn":"নূনে দুই বিন্দু","en":"Noon has two dots"}],"answer":1},{"q":{"bn":"কোন 'হ' গলার সবচেয়ে গভীর থেকে আসে?","en":"Which 'h' comes from the deepest part of the throat?"},"options":["ح","خ","ه"],"answer":2},{"q":{"bn":"و উচ্চারণে কী করবেন না?","en":"What should you NOT do when saying و?"},"options":[{"bn":"দাঁত দিয়ে ঠোঁট ছোঁয়া","en":"Touch teeth to lip"},{"bn":"ঠোঁট গোল করা","en":"Round the lips"},{"bn":"আওয়াজ করা","en":"Make a sound"}],"answer":0},{"q":{"bn":"নিচের কোনটিতে হামযা ওয়াওয়ের ওপর বসেছে?","en":"In which one does hamzah sit on a Waaw?"},"options":["أ","ؤ","ئ"],"answer":1},{"q":{"bn":"ইয়া (ي)-তে কয়টি বিন্দু, কোথায়?","en":"How many dots does Yaa (ي) have, and where?"},"options":[{"bn":"নিচে ১টি","en":"1 below"},{"bn":"ওপরে ২টি","en":"2 above"},{"bn":"নিচে ২টি","en":"2 below"}],"answer":2},{"q":{"bn":"আরবি বর্ণমালার শেষ অক্ষর কোনটি?","en":"What is the last letter of the Arabic alphabet?"},"options":["ي","ه","و"],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-families","icon":"ب ت ث","title":{"bn":"একই চেহারা, ভিন্ন বিন্দু","en":"Look-Alike Families & Dots"},"subtitle":{"bn":"বিন্দু গুনে গুনে অক্ষর চেনার সহজ কৌশল","en":"Count the dots and never mix letters up again"},"minutes":12,"goals":[{"bn":"অক্ষরের 'পরিবার' বা একই আকারের দল চেনা","en":"Spot the 'families' of letters that share a shape"},{"bn":"বিন্দুর সংখ্যা ও জায়গা দেখে অক্ষর আলাদা করা","en":"Tell letters apart by the number and place of dots"},{"bn":"কোন কোন অক্ষরের বিন্দু নিচে থাকে","en":"Know which letters have dots below"}],"blocks":[{"type":"text","bn":"আরবির একটা গোপন রহস্য বলি: ২৯টি অক্ষর মনে রাখতে আসলে ২৯টি আলাদা আকার শিখতে হয় না! অনেক অক্ষরের শরীর এক — শুধু **বিন্দু** আলাদা। বিন্দু চিনলেই অর্ধেক কাজ শেষ।","en":"Here's a secret: you don't need to learn 29 different shapes! Many letters share the same body — only the **dots** differ. Master the dots and you're halfway there."},{"type":"table","head":[{"bn":"পরিবার","en":"Family"},{"bn":"অক্ষর","en":"Letters"},{"bn":"কীভাবে আলাদা করবেন","en":"How to tell apart"}],"rows":[[{"bn":"নৌকা","en":"Boat"},"ب ت ث",{"bn":"নিচে ১ / ওপরে ২ / ওপরে ৩","en":"1 below / 2 above / 3 above"}],[{"bn":"বড়শি","en":"Hook"},"ج ح خ",{"bn":"ভেতরে ১ / নেই / ওপরে ১","en":"1 inside / none / 1 above"}],[{"bn":"কনুই","en":"Elbow"},"د ذ",{"bn":"নেই / ওপরে ১","en":"none / 1 above"}],[{"bn":"স্লিপার","en":"Slide"},"ر ز",{"bn":"নেই / ওপরে ১","en":"none / 1 above"}],[{"bn":"তিন দাঁত","en":"Three teeth"},"س ش",{"bn":"নেই / ওপরে ৩","en":"none / 3 above"}],[{"bn":"মোটা লুপ","en":"Fat loop"},"ص ض",{"bn":"নেই / ওপরে ১","en":"none / 1 above"}],[{"bn":"ছাতা","en":"Umbrella"},"ط ظ",{"bn":"নেই / ওপরে ১","en":"none / 1 above"}],[{"bn":"খোলা মুখ","en":"Open mouth"},"ع غ",{"bn":"নেই / ওপরে ১","en":"none / 1 above"}],[{"bn":"ছোট্ট মাথা","en":"Small head"},"ف ق",{"bn":"ওপরে ১ / ওপরে ২ (আর গভীর লেজ)","en":"1 above / 2 above (and a deeper tail)"}]],"title":{"bn":"৯টি আকারের পরিবার","en":"The 9 shape families"}},{"type":"tip","kind":"memory","bn":"বেশিরভাগ পরিবারে নিয়ম একটাই: **বিন্দু নেই = প্রথম ভাই, বিন্দু আছে = দ্বিতীয় ভাই।** د→ذ, ر→ز, ص→ض, ط→ظ, ع→غ — বর্ণমালায়ও এরা ঠিক এই ক্রমে আসে!","en":"In most families the rule is simple: **no dot = first brother, dot = second brother.** د→ذ, ر→ز, ص→ض, ط→ظ, ع→غ — and they come in exactly this order in the alphabet!"},{"type":"text","bn":"এবার বিন্দুর সংখ্যা অনুযায়ী সব অক্ষর সাজাই। নিজের আঙুল দিয়ে প্রতিটি অক্ষরের বিন্দু গুনে দেখুন।","en":"Now let's sort all the letters by how many dots they have. Count the dots on each one with your finger.","title":{"bn":"বিন্দু গণনা","en":"Counting dots"}},{"type":"table","head":[{"bn":"বিন্দু","en":"Dots"},{"bn":"অক্ষর","en":"Letters"},{"bn":"মোট","en":"Total"}],"rows":[[{"bn":"কোনো বিন্দু নেই","en":"No dots"},"ا ح د ر س ص ط ع ك ل م و ه",{"bn":"১৩","en":"13"}],[{"bn":"১টি বিন্দু","en":"1 dot"},"ب ج خ ذ ز ض ظ غ ف ن",{"bn":"১০","en":"10"}],[{"bn":"২টি বিন্দু","en":"2 dots"},"ت ق ي",{"bn":"৩","en":"3"}],[{"bn":"৩টি বিন্দু","en":"3 dots"},"ث ش",{"bn":"২","en":"2"}]]},{"type":"tip","kind":"fun","bn":"তিন বিন্দুওয়ালা অক্ষর মাত্র দুটি: ث আর ش। দুটোর আওয়াজেই বাতাস 'ছড়িয়ে' পড়ে — যেন তিন বিন্দু বাতাসের তিনটি ঝাপটা!","en":"Only two letters have three dots: ث and ش. Both sounds let air 'spread out' — as if the three dots are three puffs of air!"},{"type":"text","bn":"বিন্দু কোথায় থাকে — ওপরে না নিচে? খুব সহজ: মাত্র **তিনটি** অক্ষরের বিন্দু নিচে থাকে। বাকি সবার বিন্দু ওপরে।","en":"Where do the dots go — above or below? Easy: only **three** letters have dots below. Everyone else has them on top.","title":{"bn":"ওপরে না নিচে?","en":"Above or below?"}},{"type":"compare","items":[{"ar":"ب","label":{"bn":"বা","en":"Baa"},"desc":{"bn":"নিচে ১টি","en":"1 below"}},{"ar":"ج","label":{"bn":"জীম","en":"Jeem"},"desc":{"bn":"নিচে/ভেতরে ১টি","en":"1 below, inside the curve"}},{"ar":"ي","label":{"bn":"ইয়া","en":"Yaa"},"desc":{"bn":"নিচে ২টি","en":"2 below"}}]},{"type":"tip","kind":"memory","bn":"নিচে বিন্দুওয়ালা তিন অক্ষর: ب ج ي — একসাথে বলুন 'বা-জী-ইয়া'! ভাবুন, এরা তিনজন বাজি ধরেছে যে বিন্দু নিচেই রাখবে।","en":"The three 'dots-below' letters: ب ج ي — say them together: 'Baa-Jee-Yaa'! Imagine three friends who bet they'd keep their dots downstairs."},{"type":"text","bn":"শব্দের শুরু বা মাঝখানে কয়েকটি অক্ষর একদম একই 'দাঁত'-এর মতো দেখায়। তখন শুধু বিন্দুই ভরসা!","en":"At the start or middle of a word, several letters shrink to the very same little 'tooth'. Then the dots are your only clue!","title":{"bn":"একই দাঁত, পাঁচ অক্ষর","en":"One tooth, five letters"}},{"type":"compare","items":[{"ar":"بـ","label":{"bn":"বা","en":"Baa"},"desc":{"bn":"নিচে ১","en":"1 below"}},{"ar":"تـ","label":{"bn":"তা","en":"Taa"},"desc":{"bn":"ওপরে ২","en":"2 above"}},{"ar":"نـ","label":{"bn":"নূন","en":"Noon"},"desc":{"bn":"ওপরে ১","en":"1 above"}},{"ar":"يـ","label":{"bn":"ইয়া","en":"Yaa"},"desc":{"bn":"নিচে ২","en":"2 below"}}]},{"type":"examples","items":[{"ar":"بَيْتٌ","tr":{"bn":"বাইতুন","en":"baytun"},"mean":{"bn":"ঘর","en":"house"},"note":{"bn":"بـ আর ـيـ — দুটো দাঁত, বিন্দু দিয়ে চিনুন","en":"بـ and ـيـ — two teeth; read the dots"}},{"ar":"نَبِيٌّ","tr":{"bn":"নাবিয়্যুন","en":"nabiyyun"},"mean":{"bn":"নবী","en":"prophet"},"note":{"bn":"نـ ـبـ ـيّ — তিনটি দাঁত পরপর!","en":"نـ ـبـ ـيّ — three teeth in a row!"}},{"ar":"ثَبَتَ","tr":{"bn":"ছাবাতা","en":"thabata"},"mean":{"bn":"স্থির থাকল","en":"stood firm"},"note":{"bn":"ثـ ـبـ ـت — তিন ভাই একসাথে","en":"ثـ ـبـ ـت — all three brothers together"}}],"title":{"bn":"শব্দে দাঁত গুনুন","en":"Count the teeth in words"}},{"type":"tip","kind":"tip","bn":"ف আর ق শব্দের মাঝখানে প্রায় একই রকম: ـفـ ـقـ। শুধু বিন্দু গুনুন — ১টি হলে ফা, ২টি হলে ক্বাফ। শব্দের শেষে ক্বাফের লেজ গভীরভাবে নিচে নামে।","en":"In the middle of a word ف and ق look almost identical: ـفـ ـقـ. Just count — 1 dot is Faa, 2 dots is Qaaf. At the end, Qaaf's tail dips deep below the line."},{"type":"practice","bn":"প্রতি লাইনে অক্ষরগুলোর নাম বলুন — বিন্দু দেখে!","en":"Name the letters in each line — watch the dots!","lines":["ب ت ث ن ي","ج ح خ","د ذ ر ز","س ش ص ض","ط ظ ع غ","ف ق ف ق","بـ تـ ثـ نـ يـ","ث ب ي ن ت"]},{"type":"quiz","items":[{"q":{"bn":"কোন অক্ষরের বিন্দু নিচে?","en":"Which letter has its dot below?"},"options":["ن","ب","ت"],"answer":1},{"q":{"bn":"৩টি বিন্দুওয়ালা অক্ষর কোনটি?","en":"Which letter has 3 dots?"},"options":["ق","ت","ش"],"answer":2},{"q":{"bn":"এই অক্ষরে কয়টি বিন্দু?","en":"How many dots does this letter have?"},"ar":"ق","options":[{"bn":"০","en":"0"},{"bn":"১","en":"1"},{"bn":"২","en":"2"}],"answer":2},{"q":{"bn":"কোনটি 'বিন্দু নেই' দলের?","en":"Which belongs to the 'no dots' group?"},"options":["ح","خ","ج"],"answer":0},{"q":{"bn":"এই অক্ষরটি কোনটি?","en":"Which letter is this?"},"ar":"يـ","options":[{"bn":"তা","en":"Taa"},{"bn":"বা","en":"Baa"},{"bn":"নূন","en":"Noon"},{"bn":"ইয়া","en":"Yaa"}],"answer":3},{"q":{"bn":"ط-এর সাথে বিন্দু যোগ করলে কোন অক্ষর হয়?","en":"Adding a dot to ط makes which letter?"},"options":["ز","ض","ظ"],"answer":2},{"q":{"bn":"নিচে বিন্দুওয়ালা তিনটি অক্ষর কোনগুলো?","en":"Which three letters have dots below?"},"options":["ب ج ي","ب ت ث","ن ف ق"],"answer":0},{"q":{"bn":"শব্দের মাঝখানে এটি কোন অক্ষর?","en":"Which letter is this, in the middle of a word?"},"ar":"ـقـ","options":[{"bn":"ফা","en":"Faa"},{"bn":"ক্বাফ","en":"Qaaf"},{"bn":"মীম","en":"Meem"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-forms","icon":"بـ","title":{"bn":"অক্ষরের রূপ ও জোড়া লাগানো","en":"Letter Forms & Joining"},"subtitle":{"bn":"শুরু, মাঝখান ও শেষে অক্ষর কেমন দেখায়","en":"How letters look at the start, middle and end"},"minutes":15,"goals":[{"bn":"শব্দের শুরু, মাঝ ও শেষে অক্ষরের রূপ","en":"Letter shapes at the start, middle and end of words"},{"bn":"যে ৬টি অক্ষর পরের অক্ষরের সাথে জোড়া লাগে না","en":"The 6 letters that never join to the next letter"},{"bn":"লাম-আলিফ (لا) চেনা","en":"Recognise lam-alif (لا)"},{"bn":"জোড়া লাগানো শব্দ ভেঙে অক্ষর খুঁজে বের করা","en":"Break joined words into their letters"}],"blocks":[{"type":"text","bn":"মানুষ যেমন বাসায়, স্কুলে বা বিয়েতে আলাদা পোশাক পরে, আরবি অক্ষরও শব্দে তার জায়গা অনুযায়ী 'পোশাক' বদলায়। কিন্তু চিন্তা নেই — অক্ষরের মূল চেহারা (আর বিন্দু) প্রায় একই থাকে!","en":"Just as people wear different clothes at home, at school or at a wedding, Arabic letters change their 'outfit' depending on where they sit in a word. Don't worry — the core shape (and the dots) mostly stay the same!"},{"type":"text","bn":"প্রতিটি অক্ষরের সর্বোচ্চ চারটি রূপ: **একা**, **শুরুতে** (শুধু বাম দিকে জোড়া), **মাঝখানে** (দুই দিকে জোড়া), আর **শেষে** (শুধু ডান দিকে জোড়া)। ছোট্ট টান (ـ) দেখায় কোন দিকে জোড়া লাগছে।","en":"Each letter has up to four forms: **alone**, **beginning** (joins on its left), **middle** (joins on both sides) and **end** (joins on its right). The little line (ـ) shows which side connects.","title":{"bn":"চারটি রূপ","en":"Four forms"}},{"type":"table","head":[{"bn":"অক্ষর","en":"Letter"},{"bn":"একা","en":"Alone"},{"bn":"শুরুতে","en":"Beginning"},{"bn":"মাঝখানে","en":"Middle"},{"bn":"শেষে","en":"End"}],"rows":[[{"bn":"বা","en":"Baa"},"ب","بـ","ـبـ","ـب"],[{"bn":"জীম","en":"Jeem"},"ج","جـ","ـجـ","ـج"],[{"bn":"সীন","en":"Seen"},"س","سـ","ـسـ","ـس"],[{"bn":"সোয়াদ","en":"Ṣaad"},"ص","صـ","ـصـ","ـص"],[{"bn":"ত্বোয়া","en":"Ṭaa"},"ط","طـ","ـطـ","ـط"],[{"bn":"ফা","en":"Faa"},"ف","فـ","ـفـ","ـف"],[{"bn":"কাফ","en":"Kaaf"},"ك","كـ","ـكـ","ـك"],[{"bn":"লাম","en":"Laam"},"ل","لـ","ـلـ","ـل"],[{"bn":"মীম","en":"Meem"},"م","مـ","ـمـ","ـم"],[{"bn":"নূন","en":"Noon"},"ن","نـ","ـنـ","ـن"],[{"bn":"ইয়া","en":"Yaa"},"ي","يـ","ـيـ","ـي"]],"title":{"bn":"সাধারণ অক্ষরের চার রূপ","en":"Four forms of common letters"}},{"type":"tip","kind":"tip","bn":"সাধারণ নিয়ম: শুরু ও মাঝখানে অক্ষরের 'লেজ' কেটে ছোট হয়ে যায়; শেষে বা একা থাকলে পুরো লেজ ফিরে আসে।","en":"General rule: at the beginning and middle a letter loses its 'tail' and gets short; at the end or alone, the full tail comes back."},{"type":"text","bn":"দুটি অক্ষর সবচেয়ে বেশি 'পোশাক বদলায়' — ع আর ه। এদের ভালো করে দেখে রাখুন।","en":"Two letters change their outfit the most — ع and ه. Take a good look at them.","title":{"bn":"সবচেয়ে বেশি বদলায় যারা","en":"The quick-change artists"}},{"type":"compare","items":[{"ar":"ع  عـ  ـعـ  ـع","label":{"bn":"আইন","en":"'Ayn"},"desc":{"bn":"শুরুতে খোলা মুখ, মাঝখানে ভরাট ছোট ত্রিভুজ","en":"open mouth at the start, a small filled loop in the middle"}},{"ar":"ه  هـ  ـهـ  ـه","label":{"bn":"হা","en":"Haa"},"desc":{"bn":"শুরুতে দুই চোখ, মাঝখানে আটের মতো, শেষে ছোট্ট গিঁট","en":"two 'eyes' at the start, figure-8 in the middle, a small knot at the end"}}]},{"type":"examples","items":[{"ar":"عَلَى","tr":{"bn":"'আলা","en":"'alā"},"mean":{"bn":"ওপরে","en":"on"},"note":{"bn":"শুরুতে عـ","en":"beginning form عـ"},"hl":"ع"},{"ar":"بَعْدَ","tr":{"bn":"বা'দা","en":"ba'da"},"mean":{"bn":"পরে","en":"after"},"note":{"bn":"মাঝখানে ـعـ","en":"middle form ـعـ"},"hl":"ع"},{"ar":"هُمْ","tr":{"bn":"হুম","en":"hum"},"mean":{"bn":"তারা","en":"they"},"note":{"bn":"শুরুতে هـ","en":"beginning form هـ"},"hl":"ه"},{"ar":"وَجْهٌ","tr":{"bn":"ওয়াজহুন","en":"wajhun"},"mean":{"bn":"মুখমণ্ডল","en":"face"},"note":{"bn":"শেষে ـه","en":"end form ـه"},"hl":"ه"}]},{"type":"text","bn":"এখন সবচেয়ে গুরুত্বপূর্ণ নিয়ম: ছয়টি অক্ষর আছে যারা **পরের (বাম দিকের) অক্ষরের সাথে কখনো জোড়া লাগে না।** এরা আগের অক্ষরের হাত ধরে, কিন্তু নিজের পরে একটা ফাঁক রেখে দেয়।","en":"Now the most important rule: six letters **never join to the next letter (on their left).** They hold the hand of the letter before them but leave a gap after themselves.","title":{"bn":"৬টি 'লাজুক' অক্ষর","en":"The 6 'shy' letters"}},{"type":"letters","items":["alif","dal","dhal","ra","zay","waw"]},{"type":"tip","kind":"memory","bn":"ছয় লাজুক অক্ষর ক্রমানুসারে: আলিফ, দাল, যাল, রা, যা, ওয়াও। প্রথম আওয়াজগুলো জুড়ে বলুন: **'আ-দা-যা-রা-যা-ও'** — শুনতে লাগে 'আদা, যারা যাও!'","en":"The six shy letters in order: Alif, Daal, Dhaal, Raa, Zaay, Waaw. Chant them like a song: **'A-Da-Dha-Ra-Za-Wa!'** Clap once for each."},{"type":"tip","kind":"tip","bn":"এই ছয়টির পরে যে অক্ষর আসে, সে আবার নতুন করে 'শুরুর রূপ' নেয় — যেন নতুন শব্দ শুরু হলো। তাই একটি শব্দের মাঝেও ফাঁক দেখা যায়; ভয় পাবেন না, এটা একটাই শব্দ!","en":"The letter after one of these six restarts in its 'beginning' form — as if a new word started. So you'll see gaps inside one word; don't panic, it's still one word!"},{"type":"examples","items":[{"ar":"دَارٌ","tr":{"bn":"দারুন","en":"dārun"},"mean":{"bn":"বাড়ি","en":"home"},"note":{"bn":"د ا ر — তিনটিই লাজুক, কেউ কারও সাথে জোড়া নেই!","en":"د ا ر — all three are shy; no joins at all!"}},{"ar":"وَرْدٌ","tr":{"bn":"ওয়ারদুন","en":"wardun"},"mean":{"bn":"গোলাপ","en":"rose"},"note":{"bn":"و ر د — আবারও সবাই লাজুক","en":"و ر د — all shy again"}},{"ar":"قَرَأَ","tr":{"bn":"ক্বারাআ","en":"qaraʼa"},"mean":{"bn":"সে পড়ল","en":"he read"},"note":{"bn":"ق জোড়া লাগে ر-এর সাথে, কিন্তু ر-এর পরে ফাঁক","en":"ق joins ر, but there's a gap after ر"}},{"ar":"رَسُولٌ","tr":{"bn":"রাসূলুন","en":"rasūlun"},"mean":{"bn":"রাসূল, বার্তাবাহক","en":"messenger"},"note":{"bn":"ر-এর পরে ফাঁক, আবার و-এর পরে ফাঁক","en":"gap after ر, and again after و"}}],"title":{"bn":"ফাঁকওয়ালা শব্দ","en":"Words with gaps"}},{"type":"text","bn":"**লাম-আলিফ (لا):** লাম (ل)-এর পরে আলিফ (ا) এলে দুটো মিলে একটা বিশেষ আকার হয় — لا। এটা দুটি অক্ষর, একটি নয়!","en":"**Lam-alif (لا):** when Laam (ل) is followed by Alif (ا), the two merge into a special shape — لا. It's two letters, not one!","title":{"bn":"লাম-আলিফ","en":"Lam-alif"}},{"type":"compare","items":[{"ar":"ل + ا","label":{"bn":"লাম + আলিফ","en":"Laam + Alif"},"desc":{"bn":"দুটি আলাদা অক্ষর","en":"two separate letters"}},{"ar":"لا","label":{"bn":"লাম-আলিফ","en":"Lam-alif"},"desc":{"bn":"মিলে একটি বিশেষ আকার","en":"merged into one special shape"}},{"ar":"ـلا","label":{"bn":"শব্দের মাঝে","en":"inside a word"},"desc":{"bn":"আগের অক্ষরের সাথে জোড়া","en":"joined to the letter before"}}]},{"type":"tip","kind":"memory","bn":"لا দেখতে একটা ইংরেজি V বা কাঁচির মতো — দুই হাত তুলে বলছে 'লা!' (না!)। আসলেই لَا মানে 'না'!","en":"لا looks like a V or a pair of scissors — two arms raised saying 'Laa!' (No!). And لَا really does mean 'no'!"},{"type":"examples","items":[{"ar":"لَا","tr":{"bn":"লা","en":"lā"},"mean":{"bn":"না","en":"no"},"hl":"لَا"},{"ar":"فَلَا","tr":{"bn":"ফালা","en":"falā"},"mean":{"bn":"তাহলে না","en":"so do not"},"hl":"لَا"},{"ar":"سَلَامٌ","tr":{"bn":"সালামুন","en":"salāmun"},"mean":{"bn":"শান্তি","en":"peace"},"hl":"لَا"},{"ar":"كَلَامٌ","tr":{"bn":"কালামুন","en":"kalāmun"},"mean":{"bn":"কথা, বাণী","en":"speech, words"},"hl":"لَا"}]},{"type":"tip","kind":"fun","bn":"আল্লাহর নাম {{اللّٰهُ}} লেখা হয় আলিফ + লাম + লাম + হা দিয়ে, আর দ্বিতীয় লামের ওপর ছোট্ট খাড়া আলিফ বসে। কুরআনে সবচেয়ে বেশিবার আসা শব্দগুলোর একটি এটি!","en":"The name {{اللّٰهُ}} is written Alif + Laam + Laam + Haa, with a small standing alif on the second Laam. It is one of the most frequent words in the Quran!"},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"অক্ষরগুলো","en":"Its letters"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كَتَبَ","ك ت ب",{"bn":"সে লিখল","en":"he wrote"}],["قَلَمٌ","ق ل م",{"bn":"কলম","en":"pen"}],["عِلْمٌ","ع ل م",{"bn":"জ্ঞান","en":"knowledge"}],["مَسْجِدٌ","م س ج د",{"bn":"মসজিদ","en":"mosque"}],["نَعَمْ","ن ع م",{"bn":"হ্যাঁ","en":"yes"}],["شَمْسٌ","ش م س",{"bn":"সূর্য","en":"sun"}],["اللّٰهُ","ا ل ل ه",{"bn":"আল্লাহ","en":"Allah"}]],"title":{"bn":"শব্দ ভেঙে অক্ষর খুঁজুন","en":"Break words into letters"}},{"type":"tip","kind":"tip","bn":"অনুশীলনের খেলা: যেকোনো আরবি শব্দ দেখলে আঙুল দিয়ে ডান থেকে বামে প্রতিটি অক্ষরের নাম বলুন। কুরআনের প্রথম পাতা দিয়ে শুরু করতে পারেন!","en":"Practice game: whenever you see an Arabic word, run your finger right to left and name each letter. Try it on the first page of the mushaf!"},{"type":"practice","bn":"প্রতিটি শব্দের অক্ষরগুলোর নাম ডান থেকে বামে বলুন।","en":"Name the letters of each word, right to left.","lines":["كَتَبَ قَلَمٌ عِلْمٌ","بَيْتٌ نَعَمْ شَمْسٌ","دَارٌ وَرْدٌ رَسُولٌ","لَا فَلَا سَلَامٌ","عَلَى بَعْدَ وَجْهٌ","مَسْجِدٌ اللّٰهُ"]},{"type":"quiz","items":[{"q":{"bn":"কোন অক্ষরটি পরের অক্ষরের সাথে জোড়া লাগে না?","en":"Which letter never joins to the next letter?"},"options":["س","ب","د"],"answer":2},{"q":{"bn":"নিচের কোনটি ছয় 'লাজুক' অক্ষরের দলে নেই?","en":"Which is NOT one of the six 'shy' letters?"},"options":["م","ز","ر","و"],"answer":0},{"q":{"bn":"এটি কোন দুটি অক্ষর মিলে তৈরি?","en":"Which two letters make this shape?"},"ar":"لا","options":["ن + ا","ل + ا","ا + ل"],"answer":1},{"q":{"bn":"শব্দের মাঝখানে এটি কোন অক্ষর?","en":"Which letter is this, in the middle of a word?"},"ar":"ـهـ","options":[{"bn":"মীম","en":"Meem"},{"bn":"আইন","en":"'Ayn"},{"bn":"হা (ه)","en":"Haa (ه)"}],"answer":2},{"q":{"bn":"এই শব্দে কয়টি অক্ষর?","en":"How many letters are in this word?"},"ar":"مَسْجِدٌ","options":[{"bn":"৩","en":"3"},{"bn":"৪","en":"4"},{"bn":"৫","en":"5"}],"answer":1,"explain":{"bn":"م س ج د — ৪টি অক্ষর।","en":"م س ج د — 4 letters."}},{"q":{"bn":"শব্দের শুরুতে বা-এর রূপ কোনটি?","en":"What does Baa look like at the start of a word?"},"options":["بـ","ـب","ـبـ"],"answer":0},{"q":{"bn":"دَارٌ শব্দে কয়টি জোড়া আছে?","en":"How many joins are in دَارٌ?"},"ar":"دَارٌ","options":[{"bn":"২টি","en":"2"},{"bn":"কোনো জোড়া নেই","en":"No joins"},{"bn":"১টি","en":"1"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-harakat","icon":"◌َ","title":{"bn":"হরকত: যবর, যের, পেশ","en":"Harakat: Fatha, Kasra, Damma"},"subtitle":{"bn":"তিনটি ছোট্ট চিহ্ন যা অক্ষরকে কথা বলায়","en":"Three tiny marks that make letters speak"},"minutes":15,"goals":[{"bn":"ফাতহা (যবর), কাসরা (যের), দাম্মা (পেশ) চেনা","en":"Recognise fatha (zabar), kasra (zer) and damma (pesh)"},{"bn":"যেকোনো অক্ষরকে তিন হরকতে পড়া","en":"Read any letter with all three vowels"},{"bn":"হরকত দিয়ে প্রথম আসল শব্দ পড়া","en":"Read your first real words using harakat"}],"blocks":[{"type":"text","bn":"এতদিন অক্ষরগুলো ছিল 'বোবা'। আজ আমরা তাদের কণ্ঠ দেব! আরবিতে তিনটি ছোট্ট চিহ্ন — **হরকত** — অক্ষরকে আ, ই বা উ বানায়। আজকের পর আপনি সত্যিই শব্দ পড়তে শুরু করবেন!","en":"Until now the letters were 'silent'. Today we give them a voice! Three tiny marks — the **harakat** — turn a letter into a, i or u. After today you'll really start reading words!"},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"বাংলা নাম","en":"Bangla name"},{"bn":"আরবি নাম","en":"Arabic name"},{"bn":"আওয়াজ","en":"Sound"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["◌َ",{"bn":"যবর","en":"Zabar"},"فَتْحَةٌ",{"bn":"আ (ছোট)","en":"a (short)"},"بَ"],["◌ِ",{"bn":"যের","en":"Zer"},"كَسْرَةٌ",{"bn":"ই (ছোট)","en":"i (short)"},"بِ"],["◌ُ",{"bn":"পেশ","en":"Pesh"},"ضَمَّةٌ",{"bn":"উ (ছোট)","en":"u (short)"},"بُ"]],"title":{"bn":"তিনটি হরকত","en":"The three harakat"}},{"type":"tip","kind":"memory","bn":"**যবর** ওপরে বসে, মুখ ওপরে খোলে: 'আ'। **যের** নিচে বসে, থুতনি নিচে নামে: 'ই'। **পেশ** দেখতে ছোট্ট و-এর মতো, ঠোঁট গোল হয়: 'উ'।","en":"**Fatha** sits on top and your mouth opens up: 'a'. **Kasra** sits below and your chin drops: 'i'. **Damma** looks like a tiny و and your lips round: 'u'."},{"type":"examples","items":[{"ar":"بَ","tr":{"bn":"বা","en":"ba"},"note":{"bn":"যবর","en":"fatha"}},{"ar":"بِ","tr":{"bn":"বি","en":"bi"},"note":{"bn":"যের","en":"kasra"}},{"ar":"بُ","tr":{"bn":"বু","en":"bu"},"note":{"bn":"পেশ","en":"damma"}},{"ar":"كَ","tr":{"bn":"কা","en":"ka"}},{"ar":"كِ","tr":{"bn":"কি","en":"ki"}},{"ar":"كُ","tr":{"bn":"কু","en":"ku"}}]},{"type":"tip","kind":"warn","bn":"বাংলাভাষীদের সবচেয়ে বড় ভুল: যবরকে 'অ' পড়া (بَ-কে 'ব')। যবর হলো ছোট, খোলা 'আ' — 'বা', 'ব' নয়! তবে টেনে লম্বাও করবেন না।","en":"The biggest slip for Bangla speakers: reading fatha as 'o' (بَ as 'bo'). Fatha is a short, open 'a' — 'ba', not 'bo'! But don't stretch it long either."},{"type":"tip","kind":"tip","bn":"সব হরকত **ছোট** — এক তুড়ির সমান সময়। যের মানে ছোট 'ই', পেশ মানে ছোট 'উ'।","en":"All harakat are **short** — one finger-snap long. Kasra is a short 'i', damma a short 'u'."},{"type":"build","base":["ب","ت","ث","ج","ح","خ","د","ذ","ر","ز","س","ش","ص","ض","ط","ظ","ع","غ","ف","ق","ك","ل","م","ن","و","ه","ي"],"marks":["َ","ِ","ُ"],"labels":[{"bn":"যবর","en":"Fatha"},{"bn":"যের","en":"Kasra"},{"bn":"পেশ","en":"Damma"}],"title":{"bn":"হরকত-গ্রিড: প্রতিটি ঘরে চাপ দিয়ে শুনুন","en":"Harakat grid: tap each cell to hear it"}},{"type":"text","bn":"আলিফের ওপর হরকত বসলে সেখানে আসলে একটা হামযা থাকে: أَ (আ), إِ (ই — হামযা ও যের নিচে), أُ (উ)।","en":"When a vowel sits on Alif, there's really a hamza there: أَ (a), إِ (i — hamza and kasra go below), أُ (u).","title":{"bn":"আলিফের হরকত","en":"Vowels on Alif"}},{"type":"examples","items":[{"ar":"أَ","tr":{"bn":"আ","en":"a"}},{"ar":"إِ","tr":{"bn":"ই","en":"i"}},{"ar":"أُ","tr":{"bn":"উ","en":"u"}}]},{"type":"tip","kind":"warn","bn":"মোটা অক্ষরে (خ ص ض غ ط ق ظ) যবর পড়লে আওয়াজ গভীর ও ভারী শোনায়: خَ صَ طَ قَ। হালকা অক্ষরে যবর পরিষ্কার 'আ'। তুলনা করুন: سَ / صَ, تَ / طَ।","en":"With heavy letters (خ ص ض غ ط ق ظ) a fatha sounds deep and full: خَ صَ طَ قَ. With light letters it's a clear 'a'. Compare: سَ / صَ, تَ / طَ."},{"type":"compare","items":[{"ar":"سَ","label":{"bn":"সা — হালকা","en":"sa — light"},"desc":{"bn":"পরিষ্কার, পাতলা আ","en":"clear, thin a"}},{"ar":"صَ","label":{"bn":"সা — মোটা","en":"ṣa — heavy"},"desc":{"bn":"গভীর, মুখ-ভরা আ","en":"deep, full-mouthed a"}}]},{"type":"text","bn":"এবার আসল মজা! শুধু হরকত দিয়ে তৈরি তিন অক্ষরের শব্দ পড়ি। প্রতিটি অক্ষর তার হরকতসহ বলুন, তারপর মিলিয়ে দিন: كَ + تَ + بَ = كَتَبَ।","en":"Now the real fun! Let's read three-letter words made only of harakat. Say each letter with its vowel, then glue them together: كَ + تَ + بَ = كَتَبَ.","title":{"bn":"প্রথম শব্দ!","en":"Your first words!"}},{"type":"examples","items":[{"ar":"كَتَبَ","tr":{"bn":"কাতাবা","en":"kataba"},"mean":{"bn":"সে লিখল","en":"he wrote"}},{"ar":"خَلَقَ","tr":{"bn":"খালাক্বা","en":"khalaqa"},"mean":{"bn":"তিনি সৃষ্টি করলেন","en":"He created"}},{"ar":"ذَهَبَ","tr":{"bn":"যাহাবা","en":"dhahaba"},"mean":{"bn":"সে গেল","en":"he went"}},{"ar":"جَعَلَ","tr":{"bn":"জা'আলা","en":"ja'ala"},"mean":{"bn":"তিনি বানালেন","en":"He made"}},{"ar":"عَلِمَ","tr":{"bn":"'আলিমা","en":"'alima"},"mean":{"bn":"সে জানল","en":"he knew"}},{"ar":"سَمِعَ","tr":{"bn":"সামি'আ","en":"sami'a"},"mean":{"bn":"সে শুনল","en":"he heard"}},{"ar":"كُتِبَ","tr":{"bn":"কুতিবা","en":"kutiba"},"mean":{"bn":"লেখা হলো","en":"it was written"}},{"ar":"خُلِقَ","tr":{"bn":"খুলিক্বা","en":"khuliqa"},"mean":{"bn":"সৃষ্টি করা হলো","en":"was created"}},{"ar":"رُسُلُ","tr":{"bn":"রুসুলু","en":"rusulu"},"mean":{"bn":"রাসূলগণ","en":"messengers"}}]},{"type":"tip","kind":"fun","bn":"কুরআনে নাযিল হওয়া প্রথম আয়াতগুলোতেই আছে {{خَلَقَ}} (তিনি সৃষ্টি করেছেন)। আপনি এখনই সেটা পড়তে পারছেন!","en":"The very first verses revealed in the Quran contain {{خَلَقَ}} (He created). You can already read it!"},{"type":"practice","bn":"প্রথমে ধীরে, তারপর একটু দ্রুত পড়ুন।","en":"Read slowly first, then a little faster.","lines":["بَ تَ ثَ جَ حَ خَ","بِ تِ ثِ جِ حِ خِ","بُ تُ ثُ جُ حُ خُ","دَ ذِ رُ زَ سِ شُ","صَ ضِ طُ ظَ عِ غُ","فَ قِ كُ لَ مِ نُ","وَ هِ يُ أَ إِ أُ","كَتَبَ خَلَقَ جَعَلَ","عَلِمَ سَمِعَ شَرِبَ","كُتِبَ خُلِقَ جُعِلَ","رُسُلُ كُتُبُ أَحَدَ عَشَرَ"]},{"type":"quiz","items":[{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"بِ","options":[{"bn":"বু","en":"bu"},{"bn":"বা","en":"ba"},{"bn":"বি","en":"bi"}],"answer":2},{"q":{"bn":"পেশ (দাম্মা)-র আওয়াজ কী?","en":"What sound does damma (pesh) make?"},"options":[{"bn":"উ","en":"u"},{"bn":"আ","en":"a"},{"bn":"ই","en":"i"}],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"كَتَبَ","options":[{"bn":"কিতাবা","en":"kitaba"},{"bn":"কাতাবা","en":"kataba"},{"bn":"কুতিবা","en":"kutiba"}],"answer":1},{"q":{"bn":"যবর কোথায় বসে?","en":"Where does fatha sit?"},"options":[{"bn":"অক্ষরের নিচে","en":"Below the letter"},{"bn":"অক্ষরের পাশে","en":"Beside the letter"},{"bn":"অক্ষরের ওপরে","en":"Above the letter"}],"answer":2},{"q":{"bn":"بَ-কে কীভাবে পড়বেন?","en":"How should you read بَ?"},"ar":"بَ","options":[{"bn":"বা (ছোট আ)","en":"ba (short a)"},{"bn":"ব (অ)","en":"bo"},{"bn":"বা-আ-আ (লম্বা)","en":"baaa (long)"}],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"خُلِقَ","options":[{"bn":"খালাক্বা","en":"khalaqa"},{"bn":"খুলিক্বা","en":"khuliqa"},{"bn":"হালাকা","en":"halaka"}],"answer":1},{"q":{"bn":"কাসরাকে বাংলায় কী বলে?","en":"What is kasra called in Bangla?"},"options":[{"bn":"পেশ","en":"Pesh"},{"bn":"যবর","en":"Zabar"},{"bn":"যের","en":"Zer"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-sukun","icon":"◌ْ","title":{"bn":"সুকুন (জযম)","en":"Sukun (Jazm)"},"subtitle":{"bn":"যে চিহ্ন বলে: 'এখানে থামো, স্বর নেই'","en":"The mark that says: 'stop here, no vowel'"},"minutes":12,"goals":[{"bn":"সুকুন/জযম চিহ্ন চেনা","en":"Recognise the sukun/jazm mark"},{"bn":"সুকুনওয়ালা অক্ষরকে আগের অক্ষরের সাথে মিলিয়ে পড়া","en":"Join a letter with sukun to the letter before it"},{"bn":"কলকলা (প্রতিধ্বনি) অক্ষর চেনা","en":"Meet the bouncing (qalqalah) letters"}],"blocks":[{"type":"text","bn":"এখন পর্যন্ত প্রতিটি অক্ষর নিজের স্বর নিয়ে আলাদা আলাদা পড়েছি: بَ تَ। কিন্তু 'আব', 'মিন' বা 'কুল' পড়তে চাইলে? এর জন্য দরকার **সুকুন** — বাংলায় যাকে বলি **জযম**।","en":"So far every letter had its own vowel: بَ تَ. But what about 'ab', 'min' or 'qul'? For that we need **sukun** — called **jazm** in Bangla."},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"নাম","en":"Name"},{"bn":"কাজ","en":"What it does"}],"rows":[["◌ْ",{"bn":"সুকুন / জযম","en":"Sukun / Jazm"},{"bn":"অক্ষরে কোনো স্বর নেই — আগের অক্ষরের সাথে মিলে যায়","en":"no vowel on this letter — it closes onto the letter before"}]]},{"type":"tip","kind":"memory","bn":"সুকুন হলো আরবির **হসন্ত (্)**! বাংলায় যেমন 'ক্' মানে স্বরহীন ক, তেমনি আরবিতে بْ মানে স্বরহীন ব। ছোট্ট গোল চিহ্নটা যেন একটা শূন্য (০) — 'শূন্য স্বর'!","en":"Sukun is Arabic's **hasanta (্)**! Just as Bangla 'ক্' is k without a vowel, Arabic بْ is b without a vowel. The little circle is a zero — 'zero vowel'!"},{"type":"examples","items":[{"ar":"أَبْ","tr":{"bn":"আব্","en":"ab"},"note":{"bn":"أَ + بْ","en":"أَ + بْ"}},{"ar":"إِبْ","tr":{"bn":"ইব্","en":"ib"},"note":{"bn":"إِ + بْ","en":"إِ + بْ"}},{"ar":"أُبْ","tr":{"bn":"উব্","en":"ub"},"note":{"bn":"أُ + بْ","en":"أُ + بْ"}}],"title":{"bn":"কীভাবে মেলাবেন","en":"How to join"}},{"type":"tip","kind":"tip","bn":"সুকুনওয়ালা অক্ষর কখনো একা পড়বেন না। আগের অক্ষরের স্বরের সাথে এক নিঃশ্বাসে মিলিয়ে বলুন: أَبْ = 'আব্', 'আ-বি' নয়।","en":"Never read a sukun letter on its own. Glue it to the previous vowel in one breath: أَبْ = 'ab', not 'a-bi'."},{"type":"examples","items":[{"ar":"مِنْ","tr":{"bn":"মিন্","en":"min"},"mean":{"bn":"থেকে","en":"from"}},{"ar":"عَنْ","tr":{"bn":"'আন্","en":"'an"},"mean":{"bn":"সম্পর্কে, থেকে","en":"about, from"}},{"ar":"لَمْ","tr":{"bn":"লাম্","en":"lam"},"mean":{"bn":"না (অতীতে)","en":"did not"}},{"ar":"قُلْ","tr":{"bn":"ক্বুল্","en":"qul"},"mean":{"bn":"বলুন","en":"say!"}},{"ar":"هَلْ","tr":{"bn":"হাল্","en":"hal"},"mean":{"bn":"কি? (প্রশ্ন)","en":"is/does…?"}},{"ar":"بَلْ","tr":{"bn":"বাল্","en":"bal"},"mean":{"bn":"বরং","en":"rather"}},{"ar":"كَمْ","tr":{"bn":"কাম্","en":"kam"},"mean":{"bn":"কত?","en":"how many?"}},{"ar":"هُمْ","tr":{"bn":"হুম্","en":"hum"},"mean":{"bn":"তারা","en":"they"}}],"title":{"bn":"দুই অক্ষরের শব্দ","en":"Two-letter words"}},{"type":"text","bn":"এবার লম্বা শব্দ। শব্দকে ছোট ছোট টুকরায় (সিলেবল) ভাগ করুন — সুকুন যেখানে, টুকরা সেখানে শেষ।","en":"Now longer words. Split the word into small chunks (syllables) — a chunk ends wherever there's a sukun.","title":{"bn":"লম্বা শব্দ ভাগ করে পড়া","en":"Reading longer words in chunks"}},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"টুকরা","en":"Chunks"},{"bn":"উচ্চারণ","en":"Reading"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["أَنْتَ","أَنْ + تَ",{"bn":"আন্‌তা","en":"an-ta"},{"bn":"তুমি","en":"you"}],["يَعْلَمُ","يَعْ + لَ + مُ",{"bn":"ইয়া'লামু","en":"ya'-la-mu"},{"bn":"সে জানে","en":"he knows"}],["نَعْبُدُ","نَعْ + بُ + دُ",{"bn":"না'বুদু","en":"na'-bu-du"},{"bn":"আমরা ইবাদত করি","en":"we worship"}],["أَنْعَمْتَ","أَنْ + عَمْ + تَ",{"bn":"আন'আমতা","en":"an-'am-ta"},{"bn":"আপনি অনুগ্রহ করেছেন","en":"You have blessed"}],["يَخْلُقُ","يَخْ + لُ + قُ",{"bn":"ইয়াখলুকু","en":"yakh-lu-qu"},{"bn":"তিনি সৃষ্টি করেন","en":"He creates"}]]},{"type":"tip","kind":"warn","bn":"সুকুনওয়ালা ع বা ح হারিয়ে ফেলবেন না! نَعْبُدُ হলো 'না'বুদু' — গলায় আইনের চাপটা থাকবে; 'নাবুদু' বললে শব্দ ভুল হয়ে যায়।","en":"Don't swallow a ع or ح with sukun! نَعْبُدُ is 'na'budu' — keep the throat squeeze of 'Ayn; 'nabudu' is wrong."},{"type":"rule","name":{"bn":"কলকলা","en":"Qalqalah (echo)"},"ar":"قَلْقَلَةٌ","color":"blue","letters":"ق ط ب ج د","desc":{"bn":"পাঁচটি অক্ষরে সুকুন থাকলে আওয়াজটা একটু 'লাফিয়ে' ওঠে, যেন ছোট্ট প্রতিধ্বনি। অক্ষরগুলো মনে রাখার বাক্য: {{قُطْبُ جَدٍّ}}।","en":"When five letters carry a sukun, the sound gives a little 'bounce', like a tiny echo. Remember them with the phrase {{قُطْبُ جَدٍّ}}."},"how":{"bn":"অক্ষর উচ্চারণের জায়গাটা চেপে ধরে হঠাৎ ছেড়ে দিন — একটা হালকা ধাক্কা। কিন্তু পরে কোনো স্বর (আ/ই/উ) যোগ করবেন না।","en":"Press the letter's point firmly, then release it suddenly — a light pop. But don't add any vowel after it."},"examples":[{"ar":"قَدْ","tr":{"bn":"ক্বাদ্","en":"qad"},"hl":"دْ"},{"ar":"يَدْخُلُ","tr":{"bn":"ইয়াদখুলু","en":"yadkhulu"},"hl":"دْ"},{"ar":"يَبْسُطُ","tr":{"bn":"ইয়াবসুতু","en":"yabsuṭu"},"hl":"بْ"},{"ar":"يَجْعَلُ","tr":{"bn":"ইয়াজ'আলু","en":"yaj'alu"},"hl":"جْ"},{"ar":"يَقْطَعُ","tr":{"bn":"ইয়াক্বতা'উ","en":"yaqṭa'u"},"hl":"قْ"}]},{"type":"tip","kind":"tip","bn":"বাংলাদেশে ছাপা কুরআনে জযম সাধারণত গোল নয় — দেখতে ছোট্ট একটা মাথার মতো: {{مِنۡ}}। আকার যেমনই হোক, কাজ একই!","en":"In mushafs printed in Bangladesh, the jazm often isn't a circle — it looks like a tiny head: {{مِنۡ}}. Whatever its shape, the job is the same!"},{"type":"practice","bn":"প্রতিটি টুকরা এক নিঃশ্বাসে পড়ুন।","en":"Read each chunk in one breath.","lines":["أَبْ أَتْ أَثْ أَجْ أَحْ أَخْ","أَدْ أَذْ أَرْ أَزْ أَسْ أَشْ","أَصْ أَضْ أَطْ أَظْ أَعْ أَغْ","أَفْ أَقْ أَكْ أَلْ أَمْ أَنْ","إِبْ إِتْ إِسْ أُبْ أُتْ أُسْ","مِنْ عَنْ لَمْ قُلْ","هَلْ بَلْ كَمْ هُمْ","أَنْتَ أَنْتُمْ لَكُمْ","يَعْلَمُ نَعْبُدُ يَشْكُرُ","أَنْعَمْتَ يَخْلُقُ يَدْخُلُ"]},{"type":"quiz","items":[{"q":{"bn":"সুকুনকে বাংলায় কী বলে?","en":"What is sukun called in Bangla?"},"options":[{"bn":"জযম","en":"Jazm"},{"bn":"যবর","en":"Zabar"},{"bn":"তাশদীদ","en":"Tashdeed"}],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"مِنْ","options":[{"bn":"মান্","en":"man"},{"bn":"মিন্","en":"min"},{"bn":"মিনা","en":"mina"}],"answer":1},{"q":{"bn":"বাংলার কোন চিহ্নের সাথে সুকুনের মিল?","en":"Which Bangla sign is like sukun?"},"options":[{"bn":"আ-কার (া)","en":"aa-kar (া)"},{"bn":"চন্দ্রবিন্দু (ঁ)","en":"Chandrabindu (ঁ)"},{"bn":"হসন্ত (্)","en":"Hasanta (্)"}],"answer":2},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"نَعْبُدُ","options":[{"bn":"না'বুদু","en":"na'budu"},{"bn":"না'আবুদু","en":"na'abudu"},{"bn":"না-বু-দু","en":"nabudu"}],"answer":0},{"q":{"bn":"কোন অক্ষরটি কলকলার অক্ষর?","en":"Which letter is a qalqalah letter?"},"options":["ك","ق","ف"],"answer":1},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"قُلْ","options":[{"bn":"কুল্","en":"kul"},{"bn":"ক্বুলু","en":"qulu"},{"bn":"ক্বুল্","en":"qul"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-tanween","icon":"◌ٌ","title":{"bn":"তানবীন: দুই যবর, দুই যের, দুই পেশ","en":"Tanween: Double Vowels"},"subtitle":{"bn":"শব্দের শেষে লুকানো 'ন্' আওয়াজ","en":"The hidden 'n' sound at the end of words"},"minutes":12,"goals":[{"bn":"তিন রকম তানবীন চেনা ও পড়া","en":"Recognise and read the three tanween"},{"bn":"দুই যবরের সাথে অতিরিক্ত আলিফ বোঝা","en":"Understand the extra alif after double fatha"},{"bn":"থামার সময় তানবীন কীভাবে বদলায়","en":"How tanween changes when you stop"}],"blocks":[{"type":"text","bn":"কখনো কখনো শব্দের শেষে হরকত **দুইবার** লেখা থাকে। একে বলে **তানবীন**। নিয়ম সহজ: তানবীন = হরকত + 'ন্'।","en":"Sometimes a vowel is written **twice** at the end of a word. This is **tanween**. The rule is easy: tanween = vowel + 'n'."},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"বাংলা নাম","en":"Bangla name"},{"bn":"আওয়াজ","en":"Sound"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["◌ً",{"bn":"দুই যবর","en":"Double zabar"},{"bn":"আন্","en":"-an"},"بًا"],["◌ٍ",{"bn":"দুই যের","en":"Double zer"},{"bn":"ইন্","en":"-in"},"بٍ"],["◌ٌ",{"bn":"দুই পেশ","en":"Double pesh"},{"bn":"উন্","en":"-un"},"بٌ"]],"title":{"bn":"তিন রকম তানবীন","en":"The three tanween"}},{"type":"tip","kind":"memory","bn":"তানবীন যেন একটা লুকানো নূন: بٌ শুনতে ঠিক بُنْ-এর মতো, بٍ = بِنْ, بًا = بَنْ। দুটো দাগ দেখলেই মনে মনে বলুন: 'ন্ যোগ করো!'","en":"Tanween is a hidden noon: بٌ sounds just like بُنْ, بٍ = بِنْ, بًا = بَنْ. See two marks? Think: 'add an n!'"},{"type":"compare","items":[{"ar":"بٌ","label":{"bn":"বুন্","en":"bun"},"desc":{"bn":"= بُنْ","en":"= بُنْ"}},{"ar":"بٍ","label":{"bn":"বিন্","en":"bin"},"desc":{"bn":"= بِنْ","en":"= بِنْ"}},{"ar":"بًا","label":{"bn":"বান্","en":"ban"},"desc":{"bn":"= بَنْ","en":"= بَنْ"}}]},{"type":"tip","kind":"tip","bn":"দাম্মাতান (দুই পেশ) প্রায়ই এভাবে লেখা হয়: ٌ — একটা পেশ আর তার সাথে লাগানো একটা উল্টো লেজ। দুই যবর ও দুই যের দেখতে দুটি সমান্তরাল দাগের মতো।","en":"Double damma is often written like ٌ — one damma with a little curl attached. Double fatha and double kasra look like two parallel strokes."},{"type":"text","bn":"দুই যবরের পরে সাধারণত একটা **অতিরিক্ত আলিফ** লেখা থাকে: كِتَابًا। এই আলিফ পড়ার সময় লম্বা হয় না — এটা শুধু লেখার নিয়ম। ব্যতিক্রম: শব্দ ة (গোল তা) বা আলিফের পরের ء দিয়ে শেষ হলে আলিফ বসে না: رَحْمَةً، سَمَاءً।","en":"Double fatha usually comes with an **extra alif**: كِتَابًا. This alif isn't stretched when reading — it's just a spelling rule. Exception: words ending in ة (round ta), or in ء after an alif, don't get it: رَحْمَةً، سَمَاءً.","title":{"bn":"দুই যবরের আলিফ","en":"The alif of double fatha"}},{"type":"build","base":["ب","ت","ج","د","ر","س","ع","ق","ك","ل","م","ن","ه","ي"],"marks":["ً","ٍ","ٌ"],"labels":[{"bn":"দুই যবর","en":"Double fatha"},{"bn":"দুই যের","en":"Double kasra"},{"bn":"দুই পেশ","en":"Double damma"}],"title":{"bn":"তানবীন-গ্রিড","en":"Tanween grid"}},{"type":"examples","items":[{"ar":"وَلَدٌ","tr":{"bn":"ওয়ালাদুন","en":"waladun"},"mean":{"bn":"একটি ছেলে","en":"a boy"}},{"ar":"رَجُلٍ","tr":{"bn":"রাজুলিন","en":"rajulin"},"mean":{"bn":"একজন পুরুষের","en":"of a man"}},{"ar":"قَلَمًا","tr":{"bn":"ক্বালামান","en":"qalaman"},"mean":{"bn":"একটি কলম","en":"a pen"}},{"ar":"أَحَدٌ","tr":{"bn":"আহাদুন","en":"aḥadun"},"mean":{"bn":"এক","en":"one"}},{"ar":"حَسَنَةٌ","tr":{"bn":"হাসানাতুন","en":"ḥasanatun"},"mean":{"bn":"একটি নেকি, ভালো কাজ","en":"a good deed"}},{"ar":"شَجَرَةٍ","tr":{"bn":"শাজারাতিন","en":"shajaratin"},"mean":{"bn":"একটি গাছের","en":"of a tree"}},{"ar":"رَحْمَةً","tr":{"bn":"রাহমাতান","en":"raḥmatan"},"mean":{"bn":"রহমত, দয়া","en":"mercy"}}],"title":{"bn":"তানবীনওয়ালা শব্দ","en":"Words with tanween"}},{"type":"tip","kind":"fun","bn":"তানবীন সাধারণত বোঝায় 'একটি' — যেমন বাংলায় 'একটা বই'। كِتَابٌ = একটি বই। (আর 'আল-' যোগ করলে তানবীন চলে যায় — পরে শিখব!)","en":"Tanween usually means 'a / an' — كِتَابٌ = a book. (Add 'al-' (the) and the tanween disappears — coming soon!)"},{"type":"text","bn":"শব্দের শেষে থামলে (যেমন আয়াতের শেষে) তানবীন বদলে যায়: দুই পেশ ও দুই যের হয়ে যায় সুকুন, আর দুই যবর হয়ে যায় লম্বা 'আ'।","en":"When you stop at the end of a word (e.g. at the end of an ayah), tanween changes: double damma and double kasra become a sukun, and double fatha becomes a long 'ā'.","title":{"bn":"থামার সময়","en":"When you stop"}},{"type":"table","head":[{"bn":"লেখা","en":"Written"},{"bn":"পড়ার সময় (চলতে চলতে)","en":"Reading on"},{"bn":"থামলে","en":"When stopping"}],"rows":[["أَحَدٌ",{"bn":"আহাদুন","en":"aḥadun"},{"bn":"আহাদ্","en":"aḥad"}],["رَجُلٍ",{"bn":"রাজুলিন","en":"rajulin"},{"bn":"রাজুল্","en":"rajul"}],["قَلَمًا",{"bn":"ক্বালামান","en":"qalaman"},{"bn":"ক্বালামা","en":"qalamā"}]]},{"type":"tip","kind":"tip","bn":"বাংলাদেশি কুরআনে মাঝে মাঝে তানবীনের পরে ছোট্ট মীম (ۢ) বা অন্য চিহ্ন দেখবেন — এগুলো তাজবীদের নিয়ম, পরের ইউনিটে শিখব। এখন শুধু 'হরকত + ন্' মনে রাখুন।","en":"In Bangladeshi mushafs you'll sometimes see a tiny meem (ۢ) or other marks near tanween — those are tajweed rules for a later unit. For now, just remember 'vowel + n'."},{"type":"practice","bn":"জোরে পড়ুন — শেষে 'ন্' যেন স্পষ্ট শোনা যায়!","en":"Read aloud — make the final 'n' clear!","lines":["بًا بٍ بٌ","تًا تٍ تٌ","دًا دٍ دٌ","رًا رٍ رٌ","قًا قٍ قٌ","وَلَدٌ قَلَمٌ رَجُلٌ","وَلَدًا قَلَمًا رَجُلًا","وَلَدٍ قَلَمٍ رَجُلٍ","حَسَنَةٌ رَحْمَةً شَجَرَةٍ","أَحَدٌ عَدَدًا"]},{"type":"quiz","items":[{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"بٌ","options":[{"bn":"বুন্","en":"bun"},{"bn":"বিন্","en":"bin"},{"bn":"বান্","en":"ban"}],"answer":0},{"q":{"bn":"তানবীন মানে কী?","en":"What does tanween add?"},"options":[{"bn":"দ্বিগুণ অক্ষর","en":"A doubled letter"},{"bn":"হরকতের পরে 'ন্' আওয়াজ","en":"An 'n' sound after the vowel"},{"bn":"লম্বা স্বর","en":"A long vowel"}],"answer":1},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"رَجُلٍ","options":[{"bn":"রাজুলান","en":"rajulan"},{"bn":"রাজুলুন","en":"rajulun"},{"bn":"রাজুলিন","en":"rajulin"}],"answer":2},{"q":{"bn":"قَلَمًا-তে শেষের আলিফ কি লম্বা করে পড়বেন (চলতে চলতে)?","en":"Is the final alif in قَلَمًا stretched (when reading on)?"},"ar":"قَلَمًا","options":[{"bn":"না, এটা শুধু লেখার নিয়ম","en":"No, it's just spelling"},{"bn":"হ্যাঁ, সবসময়","en":"Yes, always"}],"answer":0},{"q":{"bn":"أَحَدٌ শব্দে থামলে কীভাবে পড়বেন?","en":"How do you read أَحَدٌ when stopping on it?"},"options":[{"bn":"আহাদ্","en":"aḥad"},{"bn":"আহাদা","en":"aḥadā"},{"bn":"আহাদুন","en":"aḥadun"}],"answer":0},{"q":{"bn":"দুই যেরের আওয়াজ কী?","en":"What sound does double kasra make?"},"options":[{"bn":"আন্","en":"-an"},{"bn":"ইন্","en":"-in"},{"bn":"উন্","en":"-un"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-shaddah","icon":"◌ّ","title":{"bn":"তাশদীদ (শাদ্দাহ)","en":"Shaddah (Tashdeed)"},"subtitle":{"bn":"এক অক্ষর, দুইবার পড়া","en":"One letter, read twice"},"minutes":12,"goals":[{"bn":"তাশদীদ চিহ্ন চেনা","en":"Recognise the shaddah mark"},{"bn":"তাশদীদওয়ালা অক্ষরকে দুই ভাগে ভেঙে পড়া","en":"Read a doubled letter by splitting it in two"},{"bn":"ن ও م-এ তাশদীদ থাকলে গুন্নাহ করা","en":"Add ghunnah (nasal hum) on doubled ن and م"}],"blocks":[{"type":"text","bn":"অক্ষরের ওপর ছোট্ট একটা 'w'-এর মতো চিহ্ন দেখেছেন? এটা **তাশদীদ** (শাদ্দাহ)। এর মানে: এই অক্ষরটি **দুইবার** পড়তে হবে — প্রথমবার সুকুন দিয়ে, দ্বিতীয়বার নিজের হরকত দিয়ে।","en":"Seen a tiny 'w' on top of a letter? That's **shaddah** (tashdeed). It means: read this letter **twice** — first with a sukun, then with its own vowel."},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"নাম","en":"Name"},{"bn":"কাজ","en":"What it does"}],"rows":[["◌ّ",{"bn":"তাশদীদ / শাদ্দাহ","en":"Tashdeed / Shaddah"},{"bn":"অক্ষর দ্বিগুণ: প্রথমে সুকুন, তারপর হরকত","en":"doubles the letter: sukun first, then the vowel"}]]},{"type":"tip","kind":"memory","bn":"তাশদীদ দেখতে ইংরেজি ছোট্ট w — আর ইংরেজিতে W-এর নাম 'ডাবল-ইউ' (double)! মানে: অক্ষর ডাবল করো। বাংলায় যেমন 'আব্বা', 'আম্মা' — ব আর ম দুইবার!","en":"Shaddah looks like a tiny w — and W is literally called 'double-u'! So: double the letter. Just like 'Abba' and 'Amma' — the b and m are said twice!"},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"ভাঙলে","en":"Split"},{"bn":"উচ্চারণ","en":"Reading"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["رَبِّ","رَبْ + بِ",{"bn":"রাব্‌বি","en":"rab-bi"},{"bn":"হে আমার রব","en":"my Lord"}],["إِنَّ","إِنْ + نَ",{"bn":"ইন্‌না","en":"in-na"},{"bn":"নিশ্চয়ই","en":"indeed"}],["ثُمَّ","ثُمْ + مَ",{"bn":"ছুম্‌মা","en":"thum-ma"},{"bn":"তারপর","en":"then"}],["كُلُّ","كُلْ + لُ",{"bn":"কুল্‌লু","en":"kul-lu"},{"bn":"প্রত্যেক","en":"every"}],["حَقٌّ","حَقْ + قٌ",{"bn":"হাক্‌কুন","en":"ḥaq-qun"},{"bn":"সত্য","en":"truth"}]],"title":{"bn":"ভেঙে পড়ার কৌশল","en":"The split trick"}},{"type":"tip","kind":"tip","bn":"তাশদীদওয়ালা অক্ষরে একটু 'চাপ' দিন, যেন সেখানে এক মুহূর্ত থামছেন: রাব্—বি। খুব দ্রুত পড়লে তাশদীদ হারিয়ে যায়, তখন রাব্বি হয়ে যায় 'রাবি'!","en":"Lean on the doubled letter, as if pausing on it for a moment: rab—bi. Rushing it loses the shaddah, and rabbi turns into 'rabi'!"},{"type":"compare","items":[{"ar":"عَلِمَ","label":{"bn":"'আলিমা — সে জানল","en":"'alima — he knew"},"desc":{"bn":"তাশদীদ নেই","en":"no shaddah"}},{"ar":"عَلَّمَ","label":{"bn":"'আল্লামা — সে শেখাল","en":"'allama — he taught"},"desc":{"bn":"ل-এ তাশদীদ","en":"shaddah on ل"}}],"title":{"bn":"তাশদীদে অর্থ বদলায়!","en":"Shaddah changes meaning!"}},{"type":"build","base":["ب","ت","ج","د","ر","س","ش","ص","ط","ق","ك","ل","م","ن","ي"],"marks":["َّ","ِّ","ُّ"],"labels":[{"bn":"তাশদীদ + যবর","en":"Shaddah + fatha"},{"bn":"তাশদীদ + যের","en":"Shaddah + kasra"},{"bn":"তাশদীদ + পেশ","en":"Shaddah + damma"}],"title":{"bn":"তাশদীদ-গ্রিড","en":"Shaddah grid"}},{"type":"tip","kind":"tip","bn":"তাশদীদের সাথে যের কখনো তাশদীদের ঠিক নিচে ছোট করে লেখা হয়, আবার কখনো অক্ষরের নিচে। দুটোই যের — পড়া একই।","en":"With shaddah, a kasra is sometimes written small just under the shaddah mark, and sometimes under the letter. Both are kasra — read the same."},{"type":"rule","name":{"bn":"গুন্নাহ","en":"Ghunnah (nasal hum)"},"ar":"غُنَّةٌ","color":"green","letters":"ن م","desc":{"bn":"ن বা م-এ তাশদীদ থাকলে নাক দিয়ে একটা মিষ্টি গুনগুন আওয়াজ হয়, প্রায় দুই হরকত সময় ধরে।","en":"When ن or م has a shaddah, a sweet humming sound comes through the nose, held for about two counts."},"how":{"bn":"অক্ষরে পৌঁছে আওয়াজটা নাকে ধরে রাখুন — 'ইন্‌ন্‌না', 'ছুম্‌ম্‌মা'। নাক চেপে ধরলে আওয়াজ বন্ধ হয়ে গেলে বুঝবেন ঠিক হচ্ছে!","en":"Reach the letter and hold the sound in your nose — 'in-n-na', 'thum-m-ma'. If pinching your nose stops the sound, you're doing it right!"},"examples":[{"ar":"إِنَّ","tr":{"bn":"ইন্‌না","en":"inna"},"hl":"نَّ"},{"ar":"ثُمَّ","tr":{"bn":"ছুম্‌মা","en":"thumma"},"hl":"مَّ"},{"ar":"جَنَّةٌ","tr":{"bn":"জান্‌নাতুন","en":"jannatun"},"hl":"نَّ"},{"ar":"أُمٌّ","tr":{"bn":"উম্‌মুন","en":"ummun"},"hl":"مٌّ"}]},{"type":"examples","items":[{"ar":"رَبِّ","tr":{"bn":"রাব্বি","en":"rabbi"},"mean":{"bn":"হে আমার রব","en":"my Lord"}},{"ar":"مُحَمَّدٌ","tr":{"bn":"মুহাম্মাদুন","en":"muḥammadun"},"mean":{"bn":"মুহাম্মাদ ﷺ","en":"Muhammad ﷺ"}},{"ar":"عَلَّمَ","tr":{"bn":"'আল্লামা","en":"'allama"},"mean":{"bn":"তিনি শিখিয়েছেন","en":"He taught"}},{"ar":"أُمَّةٌ","tr":{"bn":"উম্মাতুন","en":"ummatun"},"mean":{"bn":"জাতি, উম্মাহ","en":"a nation, ummah"}},{"ar":"قَدَّرَ","tr":{"bn":"ক্বাদ্দারা","en":"qaddara"},"mean":{"bn":"তিনি নির্ধারণ করলেন","en":"He measured out"}},{"ar":"كَذَّبَ","tr":{"bn":"কায্‌যাবা","en":"kadhdhaba"},"mean":{"bn":"সে অস্বীকার করল","en":"he denied"}},{"ar":"يُعَلِّمُ","tr":{"bn":"ইউ'আল্লিমু","en":"yu'allimu"},"mean":{"bn":"সে শেখায়","en":"he teaches"}}],"title":{"bn":"তাশদীদওয়ালা শব্দ","en":"Words with shaddah"}},{"type":"tip","kind":"fun","bn":"আমাদের প্রিয় নবীর নাম {{مُحَمَّدٌ}}-এ মীমের ওপর তাশদীদ আছে — তাই 'মুহাম্মাদ', 'মুহামাদ' নয়। এবার থেকে সঠিকভাবে উচ্চারণ করবেন!","en":"Our beloved Prophet's name {{مُحَمَّدٌ}} has a shaddah on the meem — so it's 'Muḥammad', not 'Muḥamad'. Now you'll always say it right!"},{"type":"practice","bn":"তাশদীদে চাপ দিন, ن ও م-এ গুন্নাহ করুন।","en":"Lean on the shaddah; hum on ن and م.","lines":["أَبَّ أَتَّ أَثَّ أَجَّ","إِبِّ إِتِّ أُبُّ أُتُّ","رَبِّ إِنَّ ثُمَّ","كُلُّ حَقٌّ أُمٌّ","عَلَّمَ قَدَّرَ كَذَّبَ","مُحَمَّدٌ جَنَّةٌ أُمَّةٌ","يُكَذِّبُ يُعَلِّمُ"]},{"type":"quiz","items":[{"q":{"bn":"তাশদীদ মানে কী?","en":"What does shaddah mean?"},"options":[{"bn":"স্বর লম্বা করা","en":"Stretch the vowel"},{"bn":"অক্ষর না পড়া","en":"Skip the letter"},{"bn":"অক্ষর দুইবার পড়া","en":"Read the letter twice"}],"answer":2},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"رَبِّ","options":[{"bn":"রাব্বি","en":"rabbi"},{"bn":"রাব্","en":"rab"},{"bn":"রাবি","en":"rabi"}],"answer":0},{"q":{"bn":"إِنَّ শব্দকে ভাঙলে কী হয়?","en":"How does إِنَّ split?"},"options":["إِنَّ + نَ","إِنْ + نَ","إِ + نَ"],"answer":1},{"q":{"bn":"عَلَّمَ শব্দের অর্থ কী?","en":"What does عَلَّمَ mean?"},"ar":"عَلَّمَ","options":[{"bn":"সে লিখল","en":"he wrote"},{"bn":"সে জানল","en":"he knew"},{"bn":"সে শেখাল","en":"he taught"}],"answer":2},{"q":{"bn":"কোন দুই অক্ষরে তাশদীদ থাকলে গুন্নাহ হয়?","en":"Which two letters get ghunnah with a shaddah?"},"options":["ن م","ب ت","ل ر"],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"ثُمَّ","options":[{"bn":"ছুমা","en":"thuma"},{"bn":"ছুম্‌মা (গুন্নাহসহ)","en":"thumma (with a hum)"},{"bn":"সুম্মা","en":"summa"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-madd","icon":"ـَا","title":{"bn":"মাদ্দ: লম্বা স্বর","en":"Madd: Long Vowels"},"subtitle":{"bn":"আলিফ, ওয়াও, ইয়া দিয়ে স্বর টেনে পড়া — আর খাড়া যবর, খাড়া যের, উল্টা পেশ","en":"Stretching vowels with ا و ي — plus standing fatha, standing kasra and inverted damma"},"minutes":15,"goals":[{"bn":"তিনটি মাদ্দের অক্ষর (ا و ي) চেনা","en":"Know the three madd letters (ا و ي)"},{"bn":"খাড়া যবর, খাড়া যের ও উল্টা পেশ পড়া","en":"Read standing fatha, standing kasra and inverted damma"},{"bn":"মাদ্দের চিহ্ন (ٓ) দেখলে আরও লম্বা করা","en":"Stretch longer when you see the madd sign (ٓ)"}],"blocks":[{"type":"text","bn":"এতক্ষণ সব স্বর ছিল ছোট — এক তুড়ির সমান। এখন শিখব **লম্বা স্বর** (মাদ্দ): দুই তুড়ির সমান টেনে পড়া। এর জন্য তিনটি বিশেষ অক্ষর আছে: **ا و ي**।","en":"So far every vowel was short — one finger-snap. Now we learn **long vowels** (madd): held for two snaps. Three special letters do this job: **ا و ي**."},{"type":"table","head":[{"bn":"নিয়ম","en":"Rule"},{"bn":"উদাহরণ","en":"Example"},{"bn":"আওয়াজ","en":"Sound"}],"rows":[[{"bn":"যবর + আলিফ","en":"Fatha + Alif"},"بَا",{"bn":"বা- (লম্বা আ)","en":"bā (long a)"}],[{"bn":"যের + ইয়া","en":"Kasra + Yaa"},"بِي",{"bn":"বী- (লম্বা ঈ)","en":"bī (long i)"}],[{"bn":"পেশ + ওয়াও","en":"Damma + Waaw"},"بُو",{"bn":"বূ- (লম্বা ঊ)","en":"bū (long u)"}]],"title":{"bn":"তিনটি মাদ্দের অক্ষর","en":"The three madd letters"}},{"type":"tip","kind":"memory","bn":"প্রতিটি হরকতের একজন 'বন্ধু' আছে, যে তাকে লম্বা করে: **যবরের বন্ধু আলিফ** (যবর দেখতে ছোট্ট হেলানো আলিফ), **যেরের বন্ধু ইয়া** (দুজনই নিচে থাকে), **পেশের বন্ধু ওয়াও** (পেশ দেখতে ছোট্ট ওয়াও)!","en":"Each vowel has a 'best friend' that stretches it: **fatha's friend is Alif** (fatha looks like a tiny slanted alif), **kasra's friend is Yaa** (both live downstairs), **damma's friend is Waaw** (damma looks like a tiny waaw)!"},{"type":"compare","items":[{"ar":"بَ","label":{"bn":"বা — ছোট","en":"ba — short"},"desc":{"bn":"১ হরকত","en":"1 count"}},{"ar":"بَا","label":{"bn":"বা- — লম্বা","en":"bā — long"},"desc":{"bn":"২ হরকত","en":"2 counts"}}]},{"type":"compare","items":[{"ar":"بِ  بِي","label":{"bn":"বি / বী-","en":"bi / bī"},"desc":{"bn":"ছোট বনাম লম্বা ই","en":"short vs long i"}},{"ar":"بُ  بُو","label":{"bn":"বু / বূ-","en":"bu / bū"},"desc":{"bn":"ছোট বনাম লম্বা উ","en":"short vs long u"}}]},{"type":"tip","kind":"tip","bn":"সময় মাপার সহজ উপায়: আঙুল ভাঁজ করুন। ছোট স্বরে ১টি আঙুল, লম্বা স্বরে ২টি আঙুল — খুব দ্রুতও না, খুব ধীরেও না।","en":"Easy timing trick: fold your fingers. Short vowel = 1 finger, long vowel = 2 fingers — not too fast, not too slow."},{"type":"build","base":["ب","ت","ث","ج","ح","خ","د","ر","س","ص","ع","ق","ك","ل","م","ن"],"marks":["َا","ِي","ُو"],"labels":[{"bn":"যবর + আলিফ","en":"Fatha + Alif"},{"bn":"যের + ইয়া","en":"Kasra + Yaa"},{"bn":"পেশ + ওয়াও","en":"Damma + Waaw"}],"title":{"bn":"মাদ্দ-গ্রিড","en":"Madd grid"}},{"type":"examples","items":[{"ar":"قَالَ","tr":{"bn":"ক্বা-লা","en":"qāla"},"mean":{"bn":"সে বলল","en":"he said"},"hl":"قَا"},{"ar":"قِيلَ","tr":{"bn":"ক্বী-লা","en":"qīla"},"mean":{"bn":"বলা হলো","en":"it was said"},"hl":"قِي"},{"ar":"يَقُولُ","tr":{"bn":"ইয়াক্বূ-লু","en":"yaqūlu"},"mean":{"bn":"সে বলে","en":"he says"},"hl":"قُو"},{"ar":"كِتَابٌ","tr":{"bn":"কিতা-বুন","en":"kitābun"},"mean":{"bn":"বই","en":"book"}},{"ar":"رَسُولٌ","tr":{"bn":"রাসূ-লুন","en":"rasūlun"},"mean":{"bn":"রাসূল","en":"messenger"}},{"ar":"دِينٌ","tr":{"bn":"দী-নুন","en":"dīnun"},"mean":{"bn":"দীন","en":"religion"}},{"ar":"نُورٌ","tr":{"bn":"নূ-রুন","en":"nūrun"},"mean":{"bn":"আলো","en":"light"}},{"ar":"فِيهِ","tr":{"bn":"ফী-হি","en":"fīhi"},"mean":{"bn":"এর মধ্যে","en":"in it"}}],"title":{"bn":"লম্বা স্বরের শব্দ","en":"Words with long vowels"}},{"type":"compare","items":[{"ar":"جَمَلٌ","label":{"bn":"জামালুন — উট","en":"jamalun — camel"},"desc":{"bn":"সব ছোট স্বর","en":"all short vowels"}},{"ar":"جَمَالٌ","label":{"bn":"জামা-লুন — সৌন্দর্য","en":"jamālun — beauty"},"desc":{"bn":"মাঝে লম্বা 'আ'","en":"a long 'ā' in the middle"}}],"title":{"bn":"লম্বা-ছোটতে অর্থ বদলায়","en":"Length changes meaning"}},{"type":"tip","kind":"warn","bn":"ছোট স্বরকে টেনে লম্বা করবেন না, আর লম্বা স্বরকে কেটে ছোট করবেন না — দুটোতেই শব্দ বদলে যেতে পারে।","en":"Don't stretch a short vowel, and don't cut a long one short — either can change the word."},{"type":"text","bn":"কুরআনে কখনো আলিফ পুরোটা না লিখে অক্ষরের ওপর একটা ছোট্ট খাড়া দাগ দেওয়া হয়। একে বলে **খাড়া যবর** ( ٰ )। এটা ঠিক যবর + আলিফের মতো লম্বা 'আ' পড়া হয়।","en":"Sometimes the Quran doesn't write a full alif — just a small upright stroke above the letter. This is the **standing fatha** ( ٰ ), read as a long 'ā' exactly like fatha + alif.","title":{"bn":"খাড়া যবর","en":"Standing fatha"}},{"type":"examples","items":[{"ar":"هٰذَا","tr":{"bn":"হা-যা","en":"hādhā"},"mean":{"bn":"এটি","en":"this"},"hl":"هٰ"},{"ar":"ذٰلِكَ","tr":{"bn":"যা-লিকা","en":"dhālika"},"mean":{"bn":"ওটি","en":"that"},"hl":"ذٰ"},{"ar":"لٰكِنْ","tr":{"bn":"লা-কিন্","en":"lākin"},"mean":{"bn":"কিন্তু","en":"but"},"hl":"لٰ"},{"ar":"إِلٰهٌ","tr":{"bn":"ইলা-হুন","en":"ilāhun"},"mean":{"bn":"উপাস্য","en":"a god"},"hl":"لٰ"}]},{"type":"text","bn":"একইভাবে, বাংলাদেশি কুরআনে আরও দুটি ছোট চিহ্ন আছে: **খাড়া যের** ( ٖ ) — লম্বা 'ঈ', আর **উল্টা পেশ** ( ٗ ) — লম্বা 'ঊ'। এগুলো সাধারণত 'হু/হি' (তার/তাকে) অর্থের ه-এর সাথে বসে।","en":"Similarly, Bangladeshi mushafs have two more small marks: the **standing kasra** ( ٖ ) — a long 'ī', and the **inverted damma** ( ٗ ) — a long 'ū'. They usually sit on the ه that means 'him/his'.","title":{"bn":"খাড়া যের ও উল্টা পেশ","en":"Standing kasra & inverted damma"}},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"নাম","en":"Name"},{"bn":"আওয়াজ","en":"Sound"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["◌ٰ",{"bn":"খাড়া যবর","en":"Standing fatha"},{"bn":"লম্বা আ","en":"long ā"},"هٰذَا"],["◌ٖ",{"bn":"খাড়া যের","en":"Standing kasra"},{"bn":"লম্বা ঈ","en":"long ī"},"بِهٖ"],["◌ٗ",{"bn":"উল্টা পেশ","en":"Inverted damma"},{"bn":"লম্বা ঊ","en":"long ū"},"لَهٗ"]]},{"type":"examples","items":[{"ar":"لَهٗ","tr":{"bn":"লাহূ","en":"lahū"},"mean":{"bn":"তার জন্য","en":"for him"},"hl":"هٗ"},{"ar":"إِنَّهٗ","tr":{"bn":"ইন্নাহূ","en":"innahū"},"mean":{"bn":"নিশ্চয়ই সে","en":"indeed he"},"hl":"هٗ"},{"ar":"رَبَّهٗ","tr":{"bn":"রাব্বাহূ","en":"rabbahū"},"mean":{"bn":"তার রবকে","en":"his Lord"},"hl":"هٗ"},{"ar":"بِهٖ","tr":{"bn":"বিহী","en":"bihī"},"mean":{"bn":"তার দ্বারা","en":"with it"},"hl":"هٖ"},{"ar":"عَبْدِهٖ","tr":{"bn":"'আবদিহী","en":"'abdihī"},"mean":{"bn":"তাঁর বান্দার","en":"His servant"},"hl":"هٖ"}]},{"type":"tip","kind":"tip","bn":"আরব দেশে ছাপা কুরআনে এই খাড়া যের ও উল্টা পেশের বদলে ছোট্ট ইয়া (ۦ) আর ছোট্ট ওয়াও (ۥ) লেখা থাকে। চেহারা ভিন্ন, পড়া একই!","en":"Mushafs printed in Arab countries show a tiny yaa (ۦ) and a tiny waaw (ۥ) instead of these marks. Different look, same reading!"},{"type":"text","bn":"শেষে একটা বিশেষ ঢেউ-চিহ্ন: **মাদ্দের চিহ্ন** ( ٓ )। মাদ্দের অক্ষরের ওপর এটা থাকলে আরও বেশি টানুন — সাধারণত ৪ থেকে ৫ হরকত (কখনো ৬)। বিস্তারিত নিয়ম তাজবীদ ইউনিটে শিখব।","en":"Finally a special wave: the **madd sign** ( ٓ ). When it sits on a madd letter, stretch even longer — usually 4 to 5 counts (sometimes 6). Full rules come in the tajweed unit.","title":{"bn":"মাদ্দের চিহ্ন ( ٓ )","en":"The madd sign ( ٓ )"}},{"type":"examples","items":[{"ar":"جَآءَ","tr":{"bn":"জা---আ","en":"jāʼa"},"mean":{"bn":"সে এল","en":"he came"},"note":{"bn":"৪–৫ হরকত টানুন","en":"stretch 4–5 counts"},"hl":"جَآ"},{"ar":"شَآءَ","tr":{"bn":"শা---আ","en":"shāʼa"},"mean":{"bn":"তিনি চাইলেন","en":"He willed"},"note":{"bn":"৪–৫ হরকত টানুন","en":"stretch 4–5 counts"},"hl":"شَآ"},{"ar":"الٓمّٓ","tr":{"bn":"আলিফ-লা-ম্-মী-ম","en":"alif-lām-mīm"},"note":{"bn":"কিছু সূরার শুরুতে অক্ষরগুলোর নাম পড়া হয়","en":"at the start of some surahs, the letter names are read"}}]},{"type":"tip","kind":"fun","bn":"সূরা বাকারার শুরুতে {{الٓمّٓ}} — এগুলোকে বলে 'হুরূফে মুকাত্তা'আত' (বিচ্ছিন্ন অক্ষর)। এখানে প্রতিটি অক্ষরের **নাম** পড়া হয়: আলিফ, লা-ম, মী-ম। এর অর্থ আল্লাহই ভালো জানেন।","en":"Surah Al-Baqarah begins with {{الٓمّٓ}} — the 'disjointed letters'. Here you read each letter's **name**: Alif, Lāam, Mīim. Allah knows best their meaning."},{"type":"practice","bn":"ছোট ও লম্বার পার্থক্য স্পষ্ট রাখুন। আঙুল দিয়ে গুনুন!","en":"Keep short and long clearly different. Count on your fingers!","lines":["بَا بِي بُو","تَا تِي تُو","قَا قِي قُو","بَ بَا بِ بِي بُ بُو","قَالَ قِيلَ يَقُولُ","كِتَابٌ رَسُولٌ دِينٌ","نُورٌ نُوحٌ فِيهِ","هٰذَا ذٰلِكَ إِلٰهٌ","لَهٗ إِنَّهٗ بِهٖ","جَآءَ شَآءَ"]},{"type":"quiz","items":[{"q":{"bn":"নিচের কোনটি মাদ্দের অক্ষর নয়?","en":"Which is NOT a madd letter?"},"options":["و","ب","ي","ا"],"answer":1},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"بُو","options":[{"bn":"বূ- (লম্বা)","en":"bū (long)"},{"bn":"বাও","en":"baw"},{"bn":"বু","en":"bu"}],"answer":0},{"q":{"bn":"যেরের 'বন্ধু' কোন অক্ষর?","en":"Which letter is kasra's 'best friend'?"},"options":["و","ي","ا"],"answer":1},{"q":{"bn":"খাড়া যবর ( ٰ ) কীভাবে পড়বেন?","en":"How do you read a standing fatha ( ٰ )?"},"ar":"هٰذَا","options":[{"bn":"ছোট আ","en":"short a"},{"bn":"পড়া হয় না","en":"not read"},{"bn":"লম্বা আ","en":"long ā"}],"answer":2},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"لَهٗ","options":[{"bn":"লাহূ (লম্বা)","en":"lahū (long)"},{"bn":"লাহ্","en":"lah"},{"bn":"লাহু (ছোট)","en":"lahu (short)"}],"answer":0},{"q":{"bn":"মাদ্দের চিহ্ন ( ٓ ) দেখলে কী করবেন?","en":"What do you do when you see the madd sign ( ٓ )?"},"options":[{"bn":"থেমে যান","en":"Stop reading"},{"bn":"আরও লম্বা টানুন (৪–৫ হরকত)","en":"Stretch longer (4–5 counts)"},{"bn":"অক্ষরটি বাদ দিন","en":"Skip the letter"}],"answer":1},{"q":{"bn":"جَمَالٌ শব্দের অর্থ কী?","en":"What does جَمَالٌ mean?"},"ar":"جَمَالٌ","options":[{"bn":"পাহাড়","en":"mountain"},{"bn":"উট","en":"camel"},{"bn":"সৌন্দর্য","en":"beauty"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-leen","icon":"ـَيْ","title":{"bn":"লীন ও সব মিলিয়ে পড়া","en":"Leen Letters & Putting It Together"},"subtitle":{"bn":"নরম 'আই' ও 'আও' — তারপর লম্বা শব্দ সহজে পড়া","en":"Soft 'ay' and 'aw' — then reading long words with ease"},"minutes":15,"goals":[{"bn":"লীনের অক্ষর (ـَوْ ـَيْ) পড়া","en":"Read the leen letters (ـَوْ ـَيْ)"},{"bn":"মাদ্দ ও লীনের পার্থক্য বোঝা","en":"Tell madd and leen apart"},{"bn":"লম্বা শব্দকে টুকরা করে পড়া","en":"Read long words by splitting them into chunks"}],"blocks":[{"type":"text","bn":"ওয়াও আর ইয়া খুব কাজের অক্ষর! পেশ/যেরের পরে এরা স্বর লম্বা করে (মাদ্দ)। কিন্তু **যবরের পরে সুকুন নিয়ে** এলে এরা একটা নরম, পিছলে যাওয়া আওয়াজ তৈরি করে — একে বলে **লীন** (নরম)।","en":"Waaw and Yaa are busy letters! After damma/kasra they stretch the vowel (madd). But **after a fatha, carrying a sukun**, they make a soft, gliding sound — called **leen** (soft)."},{"type":"table","head":[{"bn":"রূপ","en":"Pattern"},{"bn":"উদাহরণ","en":"Example"},{"bn":"আওয়াজ","en":"Sound"}],"rows":[[{"bn":"যবর + ওয়াও সাকিন","en":"Fatha + Waaw with sukun"},"بَوْ",{"bn":"বাও (বৌ-এর মতো)","en":"baw (like 'cow')"}],[{"bn":"যবর + ইয়া সাকিন","en":"Fatha + Yaa with sukun"},"بَيْ",{"bn":"বাই (বৈ-এর মতো)","en":"bay (like 'buy')"}]],"title":{"bn":"দুটি লীনের অক্ষর","en":"The two leen letters"}},{"type":"tip","kind":"memory","bn":"বাংলায় আগে থেকেই লীন আছে! 'ঐ' আর 'ঔ' — যেমন 'বৈ', 'বৌ'। بَيْ ≈ বৈ, بَوْ ≈ বৌ। শুধু মুখটা একটু বেশি খুলে 'আ' থেকে শুরু করুন।","en":"You already know leen sounds! Think 'buy' and 'cow': بَيْ ≈ 'bay/buy', بَوْ ≈ 'baw/cow'. Just start from an open 'a'."},{"type":"compare","items":[{"ar":"بُو","label":{"bn":"বূ- — মাদ্দ","en":"bū — madd"},"desc":{"bn":"পেশের পরে ওয়াও: লম্বা ঊ","en":"waaw after damma: long ū"}},{"ar":"بَوْ","label":{"bn":"বাও — লীন","en":"baw — leen"},"desc":{"bn":"যবরের পরে ওয়াও সাকিন: নরম আও","en":"waaw with sukun after fatha: soft aw"}}],"title":{"bn":"মাদ্দ বনাম লীন (ওয়াও)","en":"Madd vs leen (Waaw)"}},{"type":"compare","items":[{"ar":"بِي","label":{"bn":"বী- — মাদ্দ","en":"bī — madd"},"desc":{"bn":"যেরের পরে ইয়া: লম্বা ঈ","en":"yaa after kasra: long ī"}},{"ar":"بَيْ","label":{"bn":"বাই — লীন","en":"bay — leen"},"desc":{"bn":"যবরের পরে ইয়া সাকিন: নরম আই","en":"yaa with sukun after fatha: soft ay"}}],"title":{"bn":"মাদ্দ বনাম লীন (ইয়া)","en":"Madd vs leen (Yaa)"}},{"type":"tip","kind":"tip","bn":"লীন সাধারণত টানা হয় না — একটা মসৃণ, দ্রুত পিছলানো আওয়াজ। আয়াতের শেষে লীনের পরের অক্ষরে থামলে একটু টানা যায় — সেটা তাজবীদ ইউনিটে শিখব।","en":"Leen is normally not stretched — just a smooth, quick glide. When stopping on the letter after it at the end of an ayah you may lengthen a little — that's for the tajweed unit."},{"type":"examples","items":[{"ar":"خَوْفٌ","tr":{"bn":"খাওফুন","en":"khawfun"},"mean":{"bn":"ভয়","en":"fear"},"hl":"وْ"},{"ar":"يَوْمٌ","tr":{"bn":"ইয়াওমুন","en":"yawmun"},"mean":{"bn":"দিন","en":"day"},"hl":"وْ"},{"ar":"قَوْمٌ","tr":{"bn":"ক্বাওমুন","en":"qawmun"},"mean":{"bn":"জাতি, সম্প্রদায়","en":"a people"},"hl":"وْ"},{"ar":"بَيْتٌ","tr":{"bn":"বাইতুন","en":"baytun"},"mean":{"bn":"ঘর","en":"house"},"hl":"يْ"},{"ar":"خَيْرٌ","tr":{"bn":"খাইরুন","en":"khayrun"},"mean":{"bn":"কল্যাণ","en":"good"},"hl":"يْ"},{"ar":"شَيْءٌ","tr":{"bn":"শাইউন","en":"shayʼun"},"mean":{"bn":"কোনো কিছু","en":"a thing"},"hl":"يْ"},{"ar":"عَلَيْهِ","tr":{"bn":"'আলাইহি","en":"'alayhi"},"mean":{"bn":"তার ওপর","en":"on him"},"hl":"يْ"},{"ar":"إِلَيْكَ","tr":{"bn":"ইলাইকা","en":"ilayka"},"mean":{"bn":"তোমার দিকে","en":"to you"},"hl":"يْ"}],"title":{"bn":"লীনওয়ালা শব্দ","en":"Words with leen"}},{"type":"text","bn":"অভিনন্দন — আপনি এখন সব মূল চিহ্ন জানেন: হরকত, সুকুন, তানবীন, তাশদীদ, মাদ্দ ও লীন! এবার যেকোনো লম্বা শব্দ পড়ার 'জাদুর কৌশল' শিখি।","en":"Congratulations — you now know every core mark: harakat, sukun, tanween, shaddah, madd and leen! Now let's learn the 'magic method' for any long word.","title":{"bn":"সব মিলিয়ে","en":"Putting it all together"}},{"type":"steps","items":[{"title":{"bn":"অক্ষর ও চিহ্ন দেখুন","en":"Scan letters and marks"},"ar":"يَعْلَمُونَ","desc":{"bn":"ডান থেকে বামে প্রতিটি অক্ষর ও তার চিহ্ন চিনে নিন।","en":"Right to left, identify every letter and its mark."}},{"title":{"bn":"টুকরা করুন","en":"Cut into chunks"},"ar":"يَعْ · لَ · مُو · نَ","desc":{"bn":"সুকুন আর লম্বা স্বরের পরে টুকরা কাটুন।","en":"Cut after each sukun and each long vowel."}},{"title":{"bn":"প্রতিটি টুকরা পড়ুন","en":"Read each chunk"},"tr":{"bn":"ইয়া' · লা · মূ · না","en":"ya' · la · mū · na"},"desc":{"bn":"ধীরে ধীরে: ইয়া'-লা-মূ-না।","en":"Slowly: ya'-la-mū-na."}},{"title":{"bn":"মসৃণভাবে জুড়ে দিন","en":"Glue it smoothly"},"ar":"يَعْلَمُونَ","tr":{"bn":"ইয়া'লামূনা","en":"ya'lamūna"},"mean":{"bn":"তারা জানে","en":"they know"},"desc":{"bn":"এবার এক নিঃশ্বাসে পুরো শব্দ।","en":"Now the whole word in one breath."}}],"title":{"bn":"যেকোনো লম্বা শব্দ পড়ার ৪ ধাপ","en":"4 steps to read any long word"}},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"টুকরা","en":"Chunks"},{"bn":"উচ্চারণ","en":"Reading"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["مُسْلِمُونَ","مُسْ · لِ · مُو · نَ",{"bn":"মুসলিমূনা","en":"muslimūna"},{"bn":"মুসলিমগণ","en":"Muslims"}],["يُؤْمِنُونَ","يُؤْ · مِ · نُو · نَ",{"bn":"ইউ'মিনূনা","en":"yuʼminūna"},{"bn":"তারা ঈমান আনে","en":"they believe"}],["يَقُولُونَ","يَ · قُو · لُو · نَ",{"bn":"ইয়াক্বূলূনা","en":"yaqūlūna"},{"bn":"তারা বলে","en":"they say"}],["عَلَيْهِمْ","عَ · لَيْ · هِمْ",{"bn":"'আলাইহিম","en":"'alayhim"},{"bn":"তাদের ওপর","en":"upon them"}],["مُسْتَقِيمٌ","مُسْ · تَ · قِي · مٌ",{"bn":"মুস্তাক্বীমুন","en":"mustaqīmun"},{"bn":"সরল, সোজা","en":"straight"}]],"title":{"bn":"টুকরা করে পড়ার অনুশীলন","en":"Chunking practice"}},{"type":"examples","items":[{"ar":"يُقِيمُونَ","tr":{"bn":"ইউক্বীমূনা","en":"yuqīmūna"},"mean":{"bn":"তারা কায়েম করে","en":"they establish"}},{"ar":"يُنْفِقُونَ","tr":{"bn":"ইউনফিক্বূনা","en":"yunfiqūna"},"mean":{"bn":"তারা খরচ করে","en":"they spend"}},{"ar":"رَزَقْنٰهُمْ","tr":{"bn":"রাযাক্বনা-হুম","en":"razaqnāhum"},"mean":{"bn":"আমি তাদের রিযিক দিয়েছি","en":"We provided them"}},{"ar":"خٰلِدُونَ","tr":{"bn":"খা-লিদূনা","en":"khālidūna"},"mean":{"bn":"চিরস্থায়ী","en":"abiding forever"}}],"title":{"bn":"কুরআনের শব্দ — নিজে পড়ুন!","en":"Quranic words — read them yourself!"}},{"type":"tip","kind":"fun","bn":"উপরের শব্দগুলো সূরা বাকারার একদম শুরুর আয়াতগুলো থেকে নেওয়া। আপনি এখন কুরআনের শব্দ নিজে নিজে পড়ছেন — মাশা আল্লাহ!","en":"Some of these words come from the opening verses of Surah Al-Baqarah. You're now reading Quranic words on your own — masha Allah!"},{"type":"practice","bn":"প্রথমে টুকরা করে, তারপর পুরো শব্দ পড়ুন।","en":"Read in chunks first, then the whole word.","lines":["قَوْمٌ يَوْمٌ خَوْفٌ","بَيْتٌ خَيْرٌ شَيْءٌ","عَلَيْهِ إِلَيْكَ لَدَيْهِ","بُو بَوْ بِي بَيْ","يَعْلَمُونَ يَعْمَلُونَ يَقُولُونَ","مُسْلِمُونَ مُؤْمِنُونَ صَادِقُونَ","عَلَيْهِمْ إِلَيْهِمْ","تَعْلَمُونَ تَشْكُرُونَ"]},{"type":"quiz","items":[{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"بَوْ","options":[{"bn":"বাও","en":"baw"},{"bn":"বূ-","en":"bū"},{"bn":"বাওয়া","en":"bawa"}],"answer":0},{"q":{"bn":"লীন তৈরি হয় কখন?","en":"When does leen happen?"},"options":[{"bn":"যেরের পরে ي","en":"ي after a kasra"},{"bn":"যবরের পরে সাকিন و বা ي","en":"و or ي with sukun after a fatha"},{"bn":"পেশের পরে و","en":"و after a damma"}],"answer":1},{"q":{"bn":"بِي আর بَيْ — কোনটি মাদ্দ?","en":"بِي or بَيْ — which one is madd?"},"options":["بِي","بَيْ"],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"خَيْرٌ","options":[{"bn":"খীরুন","en":"khīrun"},{"bn":"খারুন","en":"khārun"},{"bn":"খাইরুন","en":"khayrun"}],"answer":2},{"q":{"bn":"يَعْلَمُونَ শব্দকে সঠিকভাবে টুকরা করুন:","en":"Split يَعْلَمُونَ correctly:"},"options":["يَعْ · لَ · مُو · نَ","يَ · عْلَ · مُونَ","يَعْلَ · مُ · ونَ"],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"عَلَيْهِمْ","options":[{"bn":"'আলাহুম","en":"'alāhum"},{"bn":"'আলাইহিম","en":"'alayhim"},{"bn":"'আলীহিম","en":"'alīhim"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-al","icon":"ال","title":{"bn":"'আল' — সূর্য ও চাঁদের অক্ষর","en":"\"Al-\": Sun & Moon Letters"},"subtitle":{"bn":"'আল' কখন পড়া হয়, কখন হারিয়ে যায় — আর সংযোগের হামযা","en":"When the 'l' of al- is heard, when it vanishes — and the connecting hamza"},"minutes":15,"goals":[{"bn":"'আল' (ال) মানে ও তার প্রভাব","en":"What 'al' (ال) means and what it does"},{"bn":"চাঁদের অক্ষর (লাম পড়া হয়) ও সূর্যের অক্ষর (লাম পড়া হয় না)","en":"Moon letters (lam is read) and sun letters (lam is silent)"},{"bn":"হামযাতুল ওয়াসল: কখন পড়বেন, কখন বাদ দেবেন","en":"Hamzatul wasl: when to read it and when to skip it"}],"blocks":[{"type":"text","bn":"আরবিতে 'আল' (ال) মানে ইংরেজির 'the' — নির্দিষ্ট কিছু বোঝায়। كِتَابٌ = একটি বই, আর الْكِتَابُ = বইটি। খেয়াল করুন: 'আল' যোগ হলে তানবীন চলে যায়!","en":"In Arabic 'al' (ال) means 'the'. كِتَابٌ = a book, and الْكِتَابُ = the book. Notice: when 'al' arrives, the tanween leaves!"},{"type":"compare","items":[{"ar":"كِتَابٌ","label":{"bn":"কিতাবুন — একটি বই","en":"kitābun — a book"},"desc":{"bn":"তানবীন আছে","en":"has tanween"}},{"ar":"الْكِتَابُ","label":{"bn":"আলকিতাবু — বইটি","en":"al-kitābu — the book"},"desc":{"bn":"'আল' আছে, তানবীন নেই","en":"has 'al', no tanween"}}]},{"type":"tip","kind":"memory","bn":"'আল' আর তানবীন কখনো একসাথে থাকে না — যেন দুই প্রতিদ্বন্দ্বী, একজন এলে অন্যজন চলে যায়!","en":"'Al' and tanween are never together — like two rivals: when one walks in, the other walks out!"},{"type":"text","bn":"এখন মজার অংশ: 'আল'-এর লাম কখনো শোনা যায়, কখনো একদম হারিয়ে যায়! এটা নির্ভর করে পরের অক্ষরের ওপর। আরবরা অক্ষরগুলোকে দুই দলে ভাগ করেছে: **চাঁদের অক্ষর** আর **সূর্যের অক্ষর**।","en":"Now the fun part: the lam of 'al' is sometimes heard and sometimes vanishes completely! It depends on the next letter. The letters are split into two teams: **moon letters** and **sun letters**.","title":{"bn":"দুই দল","en":"Two teams"}},{"type":"rule","name":{"bn":"চাঁদের অক্ষর (কামারিয়্যাহ)","en":"Moon letters (qamariyyah)"},"ar":"الْحُرُوفُ الْقَمَرِيَّةُ","color":"blue","letters":"ا ب ج ح خ ع غ ف ق ك م و ه ي","desc":{"bn":"এই ১৪টি অক্ষরের আগে 'আল'-এর লাম স্পষ্ট পড়া হয় — লামে সুকুন থাকে।","en":"Before these 14 letters, the lam of 'al' is clearly pronounced — it carries a sukun."},"how":{"bn":"'আল' বলুন, তারপর পরের অক্ষর: আল্‌-ক্বামারু।","en":"Say 'al', then the next letter: al-qamaru."},"examples":[{"ar":"الْقَمَرُ","tr":{"bn":"আলক্বামারু","en":"al-qamaru"},"hl":"لْ"},{"ar":"الْكِتَابُ","tr":{"bn":"আলকিতাবু","en":"al-kitābu"},"hl":"لْ"},{"ar":"الْبَيْتُ","tr":{"bn":"আলবাইতু","en":"al-baytu"},"hl":"لْ"},{"ar":"الْحَمْدُ","tr":{"bn":"আলহামদু","en":"al-ḥamdu"},"hl":"لْ"},{"ar":"الْعِلْمُ","tr":{"bn":"আল'ইলমু","en":"al-'ilmu"},"hl":"لْ"},{"ar":"الْيَوْمُ","tr":{"bn":"আলইয়াওমু","en":"al-yawmu"},"hl":"لْ"}]},{"type":"rule","name":{"bn":"সূর্যের অক্ষর (শামসিয়্যাহ)","en":"Sun letters (shamsiyyah)"},"ar":"الْحُرُوفُ الشَّمْسِيَّةُ","color":"orange","letters":"ت ث د ذ ر ز س ش ص ض ط ظ ل ن","desc":{"bn":"এই ১৪টি অক্ষরের আগে 'আল'-এর লাম পড়া হয় না; বরং পরের অক্ষরে তাশদীদ বসে, অক্ষরটি দ্বিগুণ হয়।","en":"Before these 14 letters, the lam of 'al' is silent; instead the next letter gets a shaddah and is doubled."},"how":{"bn":"লাম বাদ দিয়ে আলিফ থেকে সরাসরি পরের অক্ষরে চলে যান: আশ্‌-শামসু।","en":"Skip the lam and go straight from the alif to the next letter: ash-shamsu."},"examples":[{"ar":"الشَّمْسُ","tr":{"bn":"আশশামসু","en":"ash-shamsu"},"hl":"ش"},{"ar":"النُّورُ","tr":{"bn":"আননূরু","en":"an-nūru"},"hl":"ن"},{"ar":"الرَّحْمٰنُ","tr":{"bn":"আররাহমা-নু","en":"ar-raḥmānu"},"hl":"ر"},{"ar":"الدِّينُ","tr":{"bn":"আদদীনু","en":"ad-dīnu"},"hl":"د"},{"ar":"السَّلَامُ","tr":{"bn":"আসসালা-মু","en":"as-salāmu"},"hl":"س"},{"ar":"الصَّبْرُ","tr":{"bn":"আসসাবরু","en":"aṣ-ṣabru"},"hl":"ص"}]},{"type":"tip","kind":"tip","bn":"সবচেয়ে সহজ চেনার উপায়: কুরআনে দেখুন **লামের ওপর সুকুন আছে কি না।** লামে সুকুন (الْـ) = চাঁদের অক্ষর, লাম পড়ুন। লামে কিছু নেই আর পরের অক্ষরে তাশদীদ (الشَّـ) = সূর্যের অক্ষর, লাম বাদ!","en":"The easiest clue: look in the mushaf **for a sukun on the lam.** Sukun on lam (الْـ) = moon letter, read the lam. Nothing on lam and a shaddah on the next letter (الشَّـ) = sun letter, skip the lam!"},{"type":"tip","kind":"memory","bn":"নামেই রহস্য: الْقَمَرُ (চাঁদ) শব্দে লাম শোনা যায়, তাই এরা 'চাঁদের অক্ষর'। الشَّمْسُ (সূর্য) শব্দে লাম হারিয়ে যায় — সূর্যের তেজে লাম যেন গলে যায়! চাঁদের অক্ষরগুলো একটি বাক্যে: {{اِبْغِ حَجَّكَ وَخَفْ عَقِيمَهُ}}","en":"The names hold the secret: in الْقَمَرُ (the moon) the lam is heard — 'moon letters'. In الشَّمْسُ (the sun) the lam disappears — melted by the sun's heat! The moon letters fit in one phrase: {{اِبْغِ حَجَّكَ وَخَفْ عَقِيمَهُ}}"},{"type":"tip","kind":"fun","bn":"সূর্যের অক্ষরগুলোর বেশিরভাগই জিভের আগা দিয়ে উচ্চারণ হয় — ঠিক যেখানে লামও উচ্চারণ হয়। তাই লাম তাদের সাথে মিশে যায়!","en":"Most sun letters are made with the tip of the tongue — exactly where lam is made. That's why the lam merges into them!"},{"type":"text","bn":"'আল'-এর আলিফটা আরও একটা রহস্য রাখে। এটা হলো **হামযাতুল ওয়াসল** (সংযোগের হামযা): শব্দ দিয়ে **শুরু** করলে পড়া হয়, কিন্তু আগে অন্য শব্দ থাকলে **বাদ** যায় — আগের শব্দ সরাসরি লামের সাথে জোড়া লাগে।","en":"The alif of 'al' hides another secret. It is a **hamzatul wasl** (connecting hamza): pronounced when you **start** with the word, but **skipped** when another word comes before — the previous word links straight to the lam.","title":{"bn":"হামযাতুল ওয়াসল","en":"Hamzatul wasl"}},{"type":"compare","items":[{"ar":"الْقَمَرُ","label":{"bn":"আলক্বামারু","en":"al-qamaru"},"desc":{"bn":"শুরুতে: আলিফ পড়া হয় ('আ')","en":"at the start: the alif is read ('a')"}},{"ar":"وَالْقَمَرِ","label":{"bn":"ওয়ালক্বামারি","en":"wal-qamari"},"desc":{"bn":"মাঝে: আলিফ বাদ, ওয়া + ল","en":"in the middle: alif skipped, wa + l"}}]},{"type":"examples","items":[{"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লা-হি","en":"bismi-llāhi"},"mean":{"bn":"আল্লাহর নামে","en":"in the name of Allah"},"note":{"bn":"اللّٰه-এর আলিফ পড়া হয় না","en":"the alif of اللّٰه is not read"}},{"ar":"وَالشَّمْسِ","tr":{"bn":"ওয়াশশামসি","en":"wash-shamsi"},"mean":{"bn":"সূর্যের শপথ","en":"by the sun"},"note":{"bn":"আলিফ ও লাম দুটোই নীরব!","en":"both alif and lam are silent!"}},{"ar":"رَبِّ الْعٰلَمِينَ","tr":{"bn":"রাব্বিল 'আ-লামীন","en":"rabbil-'ālamīn"},"mean":{"bn":"সকল জগতের রব","en":"Lord of the worlds"}},{"ar":"مِنَ النَّاسِ","tr":{"bn":"মিনান্না-সি","en":"minan-nāsi"},"mean":{"bn":"মানুষের মধ্য থেকে","en":"among the people"}},{"ar":"فِي الْأَرْضِ","tr":{"bn":"ফিল আরদ্বি","en":"fil-arḍi"},"mean":{"bn":"পৃথিবীতে","en":"on the earth"},"note":{"bn":"فِي-এর লম্বা ঈ এখানে ছোট হয়ে যায়","en":"the long ī of فِي becomes short here"}}],"title":{"bn":"সংযোগ করে পড়া","en":"Linking words"}},{"type":"tip","kind":"warn","bn":"লম্বা স্বরের পরে হামযাতুল ওয়াসল ও সুকুনওয়ালা লাম এলে লম্বা স্বরটা ছোট হয়ে যায়: فِي الْأَرْضِ পড়ুন 'ফিল আরদ্বি', 'ফীল' নয়।","en":"When a long vowel meets a hamzatul wasl followed by a sukun lam, the long vowel shortens: read فِي الْأَرْضِ as 'fil-arḍi', not 'fīl'."},{"type":"tip","kind":"tip","bn":"আরব দেশের কুরআনে হামযাতুল ওয়াসলের আলিফের ওপর ছোট্ট একটা 'স'-এর মাথার মতো চিহ্ন থাকে: ٱ। বাংলাদেশি কুরআনে সাধারণত আলিফটা কোনো চিহ্ন ছাড়াই থাকে — চিহ্নহীন আলিফ দেখলেই বুঝবেন সেটা সংযোগের আলিফ।","en":"Mushafs from Arab countries put a tiny ṣād-head on the wasl alif: ٱ. Bangladeshi mushafs usually leave the alif bare — a bare alif with no mark is your clue that it's a connecting alif."},{"type":"table","head":[{"bn":"শব্দ শুরু হলে","en":"When starting with"},{"bn":"শুরুর হরকত","en":"Start with"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"আল (ال)","en":"Al (ال)"},{"bn":"যবর: 'আ'","en":"fatha: 'a'"},"اَلْحَمْدُ"],[{"bn":"ক্রিয়া, তৃতীয় অক্ষরে পেশ","en":"Verb, 3rd letter has damma"},{"bn":"পেশ: 'উ'","en":"damma: 'u'"},"اُنْظُرْ"],[{"bn":"ক্রিয়া, তৃতীয় অক্ষরে যবর/যের","en":"Verb, 3rd letter has fatha/kasra"},{"bn":"যের: 'ই'","en":"kasra: 'i'"},"اِقْرَأْ"],[{"bn":"কয়েকটি বিশেষ শব্দ (যেমন اسم، ابن)","en":"A few special nouns (e.g. اسم، ابن)"},{"bn":"যের: 'ই'","en":"kasra: 'i'"},"اِبْنٌ"]],"title":{"bn":"হামযাতুল ওয়াসল দিয়ে শুরু করলে কী পড়বেন","en":"What to say when you start on a hamzatul wasl"}},{"type":"examples","items":[{"ar":"اِقْرَأْ","tr":{"bn":"ইক্বরা'","en":"iqraʼ"},"mean":{"bn":"পড়ুন","en":"read!"}},{"ar":"اِهْدِنَا","tr":{"bn":"ইহদিনা-","en":"ihdinā"},"mean":{"bn":"আমাদের পথ দেখান","en":"guide us"}},{"ar":"اُنْظُرْ","tr":{"bn":"উনযুর","en":"unẓur"},"mean":{"bn":"দেখুন","en":"look!"}}]},{"type":"text","bn":"শেষে আল্লাহর নামের একটা সুন্দর নিয়ম: {{اللّٰه}}-এর লাম আগের হরফে যবর বা পেশ থাকলে **মোটা** (মুখ ভরে 'আল্লাহ'), আর যের থাকলে **চিকন** পড়া হয়।","en":"Finally a beautiful rule for the name of Allah: the lam in {{اللّٰه}} is **heavy** (full-mouthed) after a fatha or damma, and **light** after a kasra.","title":{"bn":"আল্লাহ শব্দের লাম","en":"The lam in 'Allah'"}},{"type":"compare","items":[{"ar":"قَالَ اللّٰهُ","label":{"bn":"ক্বা-লাল্লা-হু — মোটা","en":"qālal-lāhu — heavy"},"desc":{"bn":"আগে যবর","en":"after fatha"}},{"ar":"عَبْدُ اللّٰهِ","label":{"bn":"'আবদুল্লা-হি — মোটা","en":"'abdul-lāhi — heavy"},"desc":{"bn":"আগে পেশ","en":"after damma"}},{"ar":"بِسْمِ اللّٰهِ","label":{"bn":"বিসমিল্লা-হি — চিকন","en":"bismil-lāhi — light"},"desc":{"bn":"আগে যের","en":"after kasra"}}]},{"type":"practice","bn":"লামের ওপর সুকুন দেখুন — তারপর সিদ্ধান্ত নিন!","en":"Check the lam for a sukun — then decide!","lines":["الْقَمَرُ الْكِتَابُ الْبَيْتُ","الْحَمْدُ الْعِلْمُ الْيَوْمُ","الشَّمْسُ النُّورُ الدِّينُ","الرَّحْمٰنُ السَّلَامُ الصَّبْرُ","وَالشَّمْسِ وَالْقَمَرِ","فِي الْأَرْضِ مِنَ النَّاسِ","بِسْمِ اللّٰهِ قَالَ اللّٰهُ","اِقْرَأْ اِهْدِنَا اُنْظُرْ"]},{"type":"quiz","items":[{"q":{"bn":"'আল' (ال) মানে কী?","en":"What does 'al' (ال) mean?"},"options":[{"bn":"এবং","en":"and"},{"bn":"না","en":"no"},{"bn":"the (নির্দিষ্ট)","en":"the"}],"answer":2},{"q":{"bn":"এই শব্দে লাম কি পড়া হয়?","en":"Is the lam pronounced in this word?"},"ar":"الشَّمْسُ","options":[{"bn":"হ্যাঁ — চাঁদের অক্ষর","en":"Yes — moon letter"},{"bn":"না — সূর্যের অক্ষর","en":"No — sun letter"}],"answer":1},{"q":{"bn":"কোনটি চাঁদের অক্ষর?","en":"Which is a moon letter?"},"options":["س","ن","ق","ر"],"answer":2},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"النُّورُ","options":[{"bn":"আলনূরু","en":"al-nūru"},{"bn":"আননূরু","en":"an-nūru"},{"bn":"নূরু","en":"nūru"}],"answer":1},{"q":{"bn":"وَالْقَمَرِ-তে 'আল'-এর আলিফ কি পড়া হয়?","en":"In وَالْقَمَرِ, is the alif of 'al' read?"},"options":[{"bn":"না, ওয়া সরাসরি লামের সাথে জোড়া লাগে","en":"No, wa links straight to the lam"},{"bn":"হ্যাঁ, সবসময়","en":"Yes, always"}],"answer":0},{"q":{"bn":"بِسْمِ اللّٰهِ-তে আল্লাহর লাম কেমন?","en":"In بِسْمِ اللّٰهِ, how is the lam of Allah?"},"options":[{"bn":"চিকন","en":"light"},{"bn":"মোটা","en":"heavy"}],"answer":0,"explain":{"bn":"আগে যের (ـمِ), তাই চিকন।","en":"A kasra comes before it (ـمِ), so it's light."}},{"q":{"bn":"'আল' যোগ হলে কী চলে যায়?","en":"What disappears when 'al' is added?"},"options":[{"bn":"সুকুন","en":"Sukun"},{"bn":"তাশদীদ","en":"Shaddah"},{"bn":"তানবীন","en":"Tanween"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-special","icon":"ة","title":{"bn":"বিশেষ বানান ও কুরআনের চিহ্ন","en":"Special Spellings & Mushaf Signs"},"subtitle":{"bn":"গোল তা, আলিফ মাকসূরা, লেখা থাকে কিন্তু পড়া হয় না — আর থামার চিহ্ন","en":"Round ta, alif maqsura, letters written but not read — and stop signs"},"minutes":15,"goals":[{"bn":"গোল তা (ة) ও আলিফ মাকসূরা (ى) পড়া","en":"Read round ta (ة) and alif maqsura (ى)"},{"bn":"যে অক্ষর লেখা থাকে কিন্তু পড়া হয় না তা চেনা","en":"Spot letters that are written but not read"},{"bn":"আলিফ-মাদ্দা (آ) পড়া","en":"Read alif-madda (آ)"},{"bn":"কুরআনের থামার চিহ্ন বোঝা","en":"Understand the stop signs in the mushaf"}],"blocks":[{"type":"text","bn":"আপনি প্রায় পৌঁছে গেছেন! কুরআনের কিছু শব্দের বানান একটু বিশেষ। এগুলো জানলে আর কোনো শব্দে আটকাবেন না।","en":"You're almost there! A few Quranic words have special spellings. Learn these and nothing will trip you up."},{"type":"text","bn":"**গোল তা (ة)** শব্দের শেষে বসে। দেখতে ه-এর মতো, কিন্তু মাথায় ت-এর দুই বিন্দু। চলতে চলতে পড়লে 'ত', আর শব্দে থামলে 'হ' (হালকা)।","en":"**Round ta (ة)** sits at the end of a word. It looks like ه with the two dots of ت on top. Reading on, it's 't'; stopping on the word, it's a soft 'h'.","title":{"bn":"গোল তা (ة)","en":"Round ta (ة)"}},{"type":"tip","kind":"memory","bn":"ة আসলে ه আর ت-এর মিশ্রণ — শরীর হা-এর, বিন্দু তা-এর! তাই কাজও দুটোরই: চলতে থাকলে 'ত' (তা-এর মতো), বিশ্রাম নিলে 'হ' (হা-এর মতো)।","en":"ة is literally a mix of ه and ت — Haa's body with Taa's dots! So it does both jobs: moving on, it's 't' (like Taa); resting, it's 'h' (like Haa)."},{"type":"compare","items":[{"ar":"ت","label":{"bn":"তা","en":"Taa"},"desc":{"bn":"সবসময় 't'","en":"always 't'"}},{"ar":"ة","label":{"bn":"গোল তা","en":"Round ta"},"desc":{"bn":"চলতে 't', থামলে 'h'","en":"'t' moving, 'h' stopping"}},{"ar":"ه","label":{"bn":"হা","en":"Haa"},"desc":{"bn":"সবসময় 'h'","en":"always 'h'"}}]},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"চলতে চলতে","en":"Reading on"},{"bn":"থামলে","en":"Stopping"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["رَحْمَةٌ",{"bn":"রাহমাতুন","en":"raḥmatun"},{"bn":"রাহমাহ্","en":"raḥmah"},{"bn":"দয়া","en":"mercy"}],["جَنَّةٌ",{"bn":"জান্নাতুন","en":"jannatun"},{"bn":"জান্নাহ্","en":"jannah"},{"bn":"জান্নাত","en":"Paradise"}],["نِعْمَةٌ",{"bn":"নি'মাতুন","en":"ni'matun"},{"bn":"নি'মাহ্","en":"ni'mah"},{"bn":"নিয়ামত","en":"blessing"}],["قُوَّةٌ",{"bn":"ক্বুওয়্যাতুন","en":"quwwatun"},{"bn":"ক্বুওয়্যাহ্","en":"quwwah"},{"bn":"শক্তি","en":"strength"}]]},{"type":"text","bn":"**আলিফ মাকসূরা (ى)** দেখতে বিন্দুছাড়া ইয়া, শব্দের শেষে বসে, আর পড়া হয় **লম্বা 'আ'**-এর মতো। বাংলাদেশি কুরআনে প্রায়ই এর আগের অক্ষরে খাড়া যবর থাকে: عَلٰى।","en":"**Alif maqsura (ى)** looks like a dotless yaa, sits at the end of a word, and is read as a **long 'ā'**. Bangladeshi mushafs often put a standing fatha on the letter before it: عَلٰى.","title":{"bn":"আলিফ মাকসূরা (ى)","en":"Alif maqsura (ى)"}},{"type":"compare","items":[{"ar":"ي","label":{"bn":"ইয়া","en":"Yaa"},"desc":{"bn":"নিচে দুই বিন্দু: 'ই/য়'","en":"two dots below: 'ī/y'"}},{"ar":"ى","label":{"bn":"আলিফ মাকসূরা","en":"Alif maqsura"},"desc":{"bn":"বিন্দু নেই: লম্বা 'আ'","en":"no dots: long 'ā'"}}]},{"type":"examples","items":[{"ar":"عَلَى","tr":{"bn":"'আলা-","en":"'alā"},"mean":{"bn":"ওপরে","en":"on, upon"}},{"ar":"إِلَى","tr":{"bn":"ইলা-","en":"ilā"},"mean":{"bn":"দিকে","en":"to, towards"}},{"ar":"هُدًى","tr":{"bn":"হুদান","en":"hudan"},"mean":{"bn":"হিদায়াত","en":"guidance"},"note":{"bn":"তানবীনের সাথে আলিফ মাকসূরা","en":"alif maqsura with tanween"}},{"ar":"مُوسٰى","tr":{"bn":"মূসা-","en":"mūsā"},"mean":{"bn":"মূসা (আ.)","en":"Musa (Moses)"}},{"ar":"عِيسٰى","tr":{"bn":"'ঈসা-","en":"'īsā"},"mean":{"bn":"ঈসা (আ.)","en":"'Isa (Jesus)"}},{"ar":"الْأَعْلٰى","tr":{"bn":"আল-আ'লা-","en":"al-a'lā"},"mean":{"bn":"সর্বোচ্চ","en":"the Most High"}}]},{"type":"text","bn":"**আলিফ-মাদ্দা (آ):** আলিফের ওপর ঢেউ মানে হামযা + লম্বা 'আ' — একসাথে। أَا লেখার বদলে সংক্ষেপে آ লেখা হয়।","en":"**Alif-madda (آ):** a wave on top of an alif means hamza + long 'ā' together. Instead of writing أَا, Arabic writes آ.","title":{"bn":"আলিফ-মাদ্দা (آ)","en":"Alif-madda (آ)"}},{"type":"examples","items":[{"ar":"آمَنُوا","tr":{"bn":"আ-মানূ","en":"āmanū"},"mean":{"bn":"তারা ঈমান এনেছে","en":"they believed"},"hl":"آ"},{"ar":"الْقُرْآنُ","tr":{"bn":"আলক্বুর'আ-নু","en":"al-qurʼānu"},"mean":{"bn":"কুরআন","en":"the Quran"},"hl":"آ"},{"ar":"آدَمُ","tr":{"bn":"আ-দামু","en":"ādamu"},"mean":{"bn":"আদম (আ.)","en":"Adam"},"hl":"آ"}]},{"type":"text","bn":"এবার কিছু অক্ষর যা **লেখা থাকে কিন্তু পড়া হয় না।** সবচেয়ে সাধারণ: বহুবচনের ওয়াওয়ের পরের আলিফ — যেমন قَالُوا (তারা বলল)। শেষের আলিফটা চুপ!","en":"Now some letters that are **written but not read.** The most common: the alif after a plural waaw — as in قَالُوا (they said). The final alif is silent!","title":{"bn":"লেখা আছে, পড়া নেই","en":"Written, not read"}},{"type":"examples","items":[{"ar":"قَالُوا","tr":{"bn":"ক্বা-লূ","en":"qālū"},"mean":{"bn":"তারা বলল","en":"they said"},"note":{"bn":"শেষের আলিফ নীরব","en":"final alif is silent"},"hl":"ا"},{"ar":"كَفَرُوا","tr":{"bn":"কাফারূ","en":"kafarū"},"mean":{"bn":"তারা অস্বীকার করল","en":"they disbelieved"},"note":{"bn":"শেষের আলিফ নীরব","en":"final alif is silent"}},{"ar":"عَمِلُوا","tr":{"bn":"'আমিলূ","en":"'amilū"},"mean":{"bn":"তারা কাজ করল","en":"they did"},"note":{"bn":"শেষের আলিফ নীরব","en":"final alif is silent"}},{"ar":"أَنَا","tr":{"bn":"আনা","en":"ana"},"mean":{"bn":"আমি","en":"I"},"note":{"bn":"চলতে চলতে শেষের আলিফ পড়া হয় না; থামলে 'আনা-'","en":"the final alif is not read when continuing; 'anā' when stopping"}},{"ar":"أُولٰئِكَ","tr":{"bn":"উলা-ইকা","en":"ulāʼika"},"mean":{"bn":"তারাই","en":"those"},"note":{"bn":"প্রথম ওয়াও পড়া হয় না","en":"the first waaw is not read"}},{"ar":"مِائَةٌ","tr":{"bn":"মি'আতুন","en":"miʼatun"},"mean":{"bn":"একশ","en":"one hundred"},"note":{"bn":"মীমের পরের আলিফ পড়া হয় না","en":"the alif after meem is not read"}}]},{"type":"text","bn":"কয়েকটি বিখ্যাত শব্দে 'আ' লম্বা করতে আলিফের বদলে ওয়াও লেখা হয়, আর তার ওপর খাড়া যবর থাকে। ওয়াওটা পড়া হয় না — খাড়া যবর থেকে লম্বা 'আ' পড়ুন।","en":"In a few famous words, the long 'ā' is written with a waaw instead of an alif, with a standing fatha on top. The waaw is not read — just read the long 'ā' of the standing fatha.","title":{"bn":"ওয়াও দিয়ে লেখা 'আ'","en":"'ā' written with a waaw"}},{"type":"examples","items":[{"ar":"الصَّلٰوةُ","tr":{"bn":"আসসালা-তু","en":"aṣ-ṣalātu"},"mean":{"bn":"নামায","en":"the prayer"}},{"ar":"الزَّكٰوةُ","tr":{"bn":"আযযাকা-তু","en":"az-zakātu"},"mean":{"bn":"যাকাত","en":"the zakah"}},{"ar":"الْحَيٰوةُ","tr":{"bn":"আলহায়া-তু","en":"al-ḥayātu"},"mean":{"bn":"জীবন","en":"life"}}]},{"type":"tip","kind":"tip","bn":"আরব দেশের কুরআনে নীরব অক্ষরের ওপর ছোট্ট গোল শূন্য ( ۟ ) দেওয়া থাকে: {{قَالُوا۟}}। বাংলাদেশি কুরআনে নীরব অক্ষরে সাধারণত কোনো হরকতই থাকে না — **হরকতহীন, সুকুনহীন অক্ষর দেখলে বুঝবেন সেটা পড়া হয় না।**","en":"Mushafs from Arab countries put a tiny round zero ( ۟ ) on silent letters: {{قَالُوا۟}}. Bangladeshi mushafs usually leave a silent letter with no mark at all — **a letter with no vowel and no sukun is not read.**"},{"type":"text","bn":"কুরআনের লাইনের ওপর ছোট ছোট অক্ষর দেখবেন — এগুলো **ওয়াকফের চিহ্ন** (কোথায় থামবেন বা থামবেন না)। নিচে বাংলাদেশি কুরআনের সবচেয়ে সাধারণ চিহ্নগুলো। বিস্তারিত তাজবীদ ইউনিটে।","en":"You'll see small letters above the lines of the Quran — these are **waqf (stop) signs** telling you where to stop or not. Below are the most common ones in Bangladeshi mushafs. Details come in the tajweed unit.","title":{"bn":"থামার চিহ্ন","en":"Stop signs"}},{"type":"table","head":[{"bn":"চিহ্ন","en":"Sign"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["۝",{"bn":"আয়াতের শেষ — এখানে থামা উত্তম","en":"End of an ayah — good to stop here"}],["م",{"bn":"অবশ্যই থামুন (না থামলে অর্থ বিগড়ে যেতে পারে)","en":"Must stop (continuing may distort the meaning)"}],["ط",{"bn":"থামা উত্তম","en":"Stopping is preferred"}],["ج",{"bn":"থামা জায়েয (থামতেও পারেন, চালিয়েও যেতে পারেন)","en":"Stopping is permitted (stop or continue)"}],["قلے",{"bn":"থামা উত্তম","en":"Stopping is better"}],["صلے",{"bn":"চালিয়ে যাওয়া উত্তম","en":"Continuing is better"}],["لا",{"bn":"এখানে থামবেন না (আয়াতের মাঝে)","en":"Don't stop here (inside an ayah)"}],[{"bn":"∴ ∴ (তিন বিন্দু, দুই জায়গায়)","en":"∴ ∴ (three dots, in two places)"},{"bn":"দুটির যেকোনো একটিতে থামুন, দুটোতে নয়","en":"Stop at one of the two, not both"}]]},{"type":"tip","kind":"warn","bn":"ভুল জায়গায় থেমে গেলে চিন্তা করবেন না — একটু আগে থেকে আবার শুরু করুন, যাতে অর্থ ঠিক থাকে।","en":"If you stop in the wrong place, don't worry — go back a little and start again so the meaning stays right."},{"type":"practice","bn":"বিশেষ বানানগুলো খেয়াল করে পড়ুন।","en":"Read carefully, watching for special spellings.","lines":["رَحْمَةٌ جَنَّةٌ نِعْمَةٌ","عَلَى إِلَى هُدًى","مُوسٰى عِيسٰى الْأَعْلٰى","آمَنُوا الْقُرْآنُ آدَمُ","قَالُوا كَفَرُوا عَمِلُوا","أَنَا أُولٰئِكَ مِائَةٌ","الصَّلٰوةُ الزَّكٰوةُ الْحَيٰوةُ"]},{"type":"quiz","items":[{"q":{"bn":"জান্নাতুন শব্দে থামলে কীভাবে পড়বেন?","en":"How do you read this word when stopping on it?"},"ar":"جَنَّةٌ","options":[{"bn":"জান্নাহ্","en":"jannah"},{"bn":"জান্নাত্","en":"jannat"},{"bn":"জান্নাতুন","en":"jannatun"}],"answer":0},{"q":{"bn":"এই অক্ষর (শব্দের শেষে) কীভাবে পড়বেন?","en":"How is this letter read at the end of a word?"},"ar":"ى","options":[{"bn":"পড়া হয় না","en":"not read"},{"bn":"লম্বা 'আ'","en":"long 'ā'"},{"bn":"লম্বা 'ঈ'","en":"long 'ī'"}],"answer":1},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"قَالُوا","options":[{"bn":"ক্বা-লূ-আ","en":"qālūā"},{"bn":"ক্বালা","en":"qāla"},{"bn":"ক্বা-লূ","en":"qālū"}],"answer":2},{"q":{"bn":"آ কী বোঝায়?","en":"What does آ stand for?"},"options":[{"bn":"হামযা + লম্বা 'আ'","en":"Hamza + long 'ā'"},{"bn":"শুধু ছোট 'আ'","en":"Just a short 'a'"},{"bn":"নীরব আলিফ","en":"A silent alif"}],"answer":0},{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"الصَّلٰوةُ","options":[{"bn":"আসসালূতু","en":"aṣ-ṣalūtu"},{"bn":"আসসালা-তু","en":"aṣ-ṣalātu"},{"bn":"আসসালাওয়াতু","en":"aṣ-ṣalawatu"}],"answer":1},{"q":{"bn":"লা (لا) চিহ্ন আয়াতের মাঝে থাকলে কী করবেন?","en":"What do you do at a لا sign inside an ayah?"},"options":[{"bn":"অবশ্যই থামবেন","en":"Must stop"},{"bn":"সিজদা দেবেন","en":"Prostrate"},{"bn":"থামবেন না","en":"Don't stop"}],"answer":2},{"q":{"bn":"ة-এর শরীর কোন অক্ষরের মতো?","en":"Round ta (ة) has the body of which letter?"},"options":["ه","ت","ن"],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"rd-fluency","icon":"﴿﴾","title":{"bn":"সাবলীল পড়ার ল্যাব","en":"Fluency Lab"},"subtitle":{"bn":"ছোট শব্দ থেকে কুরআনের আয়াত — ধাপে ধাপে","en":"From short words to real Quranic ayahs, level by level"},"minutes":20,"goals":[{"bn":"ছোট থেকে বড় — ধাপে ধাপে সাবলীল পড়া","en":"Build fluency level by level"},{"bn":"প্রতিদিনের দোয়া ও যিকিরের বাক্য পড়া","en":"Read everyday Islamic phrases"},{"bn":"সূরা ফাতিহার শুরু ও সূরা ইখলাস নিজে পড়া","en":"Read the opening of Al-Fatihah and Surah Al-Ikhlas yourself"}],"blocks":[{"type":"text","bn":"এখন সময় সবকিছু একসাথে কাজে লাগানোর! এই ল্যাবে ৫টি লেভেল আছে। প্রতিটি লেভেল ৩ বার পড়ুন: প্রথমবার ধীরে, দ্বিতীয়বার স্বাভাবিক, তৃতীয়বার আত্মবিশ্বাসের সাথে।","en":"Time to put it all together! This lab has 5 levels. Read each level 3 times: first slowly, then normally, then with confidence."},{"type":"tip","kind":"tip","bn":"আটকে গেলে ভয় নেই — শব্দটাকে টুকরা করুন (পাঠ ১৩-এর কৌশল), চিহ্নগুলো দেখুন, তারপর আবার চেষ্টা করুন।","en":"Stuck? No problem — split the word into chunks (the lesson 13 method), check the marks, and try again."},{"type":"practice","bn":"লেভেল ১: ছোট শব্দ। প্রতিটি শব্দ এক নিঃশ্বাসে।","en":"Level 1: short words. Each word in one breath.","lines":["مِنْ عَنْ لَمْ قُلْ","هُوَ هِيَ لَهُ بِهِ","كَانَ قَالَ نَحْنُ","رَبِّ إِنَّ ثُمَّ","يَوْمٌ خَيْرٌ شَيْءٌ"],"title":{"bn":"লেভেল ১","en":"Level 1"}},{"type":"examples","items":[{"ar":"رَحِيمٌ","tr":{"bn":"রাহীমুন","en":"raḥīmun"},"mean":{"bn":"পরম দয়ালু","en":"Most Merciful"}},{"ar":"عَلِيمٌ","tr":{"bn":"'আলীমুন","en":"'alīmun"},"mean":{"bn":"সর্বজ্ঞ","en":"All-Knowing"}},{"ar":"حَكِيمٌ","tr":{"bn":"হাকীমুন","en":"ḥakīmun"},"mean":{"bn":"প্রজ্ঞাময়","en":"All-Wise"}},{"ar":"سَمِيعٌ","tr":{"bn":"সামী'উন","en":"samī'un"},"mean":{"bn":"সর্বশ্রোতা","en":"All-Hearing"}},{"ar":"بَصِيرٌ","tr":{"bn":"বাসীরুন","en":"baṣīrun"},"mean":{"bn":"সর্বদ্রষ্টা","en":"All-Seeing"}},{"ar":"غَفُورٌ","tr":{"bn":"গাফূরুন","en":"ghafūrun"},"mean":{"bn":"অতি ক্ষমাশীল","en":"Most Forgiving"}},{"ar":"قَدِيرٌ","tr":{"bn":"ক্বাদীরুন","en":"qadīrun"},"mean":{"bn":"সর্বশক্তিমান","en":"All-Powerful"}},{"ar":"خَبِيرٌ","tr":{"bn":"খাবীরুন","en":"khabīrun"},"mean":{"bn":"সব খবর রাখেন","en":"All-Aware"}}],"title":{"bn":"লেভেল ২: আল্লাহর সুন্দর নামসমূহ (কুরআনে বহুবার আসে)","en":"Level 2: Beautiful names of Allah (frequent in the Quran)"}},{"type":"practice","bn":"লেভেল ৩: 'আল'-সহ কুরআনের শব্দ। সূর্য/চাঁদের অক্ষর খেয়াল করুন!","en":"Level 3: Quranic words with 'al'. Watch for sun and moon letters!","lines":["الْكِتَابُ الْقُرْآنُ","الصَّلٰوةَ الزَّكٰوةَ","الْمُؤْمِنُونَ الصّٰلِحٰتِ","الْعٰلَمِينَ الْمُسْتَقِيمَ","السَّمٰوٰتِ الْأَرْضِ"],"title":{"bn":"লেভেল ৩","en":"Level 3"}},{"type":"examples","items":[{"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লা-হ","en":"bismillāh"},"mean":{"bn":"আল্লাহর নামে","en":"In the name of Allah"}},{"ar":"الْحَمْدُ لِلّٰهِ","tr":{"bn":"আলহামদু লিল্লা-হ","en":"al-ḥamdu lillāh"},"mean":{"bn":"সমস্ত প্রশংসা আল্লাহর","en":"All praise is for Allah"}},{"ar":"سُبْحَانَ اللّٰهِ","tr":{"bn":"সুবহা-নাল্লা-হ","en":"subḥāna-llāh"},"mean":{"bn":"আল্লাহ পবিত্র","en":"Glory be to Allah"}},{"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লা-হু আকবার","en":"allāhu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"}},{"ar":"لَا إِلٰهَ إِلَّا اللّٰهُ","tr":{"bn":"লা- ইলা-হা ইল্লাল্লা-হ","en":"lā ilāha illa-llāh"},"mean":{"bn":"আল্লাহ ছাড়া কোনো ইলাহ নেই","en":"There is no god but Allah"}},{"ar":"أَسْتَغْفِرُ اللّٰهَ","tr":{"bn":"আসতাগফিরুল্লা-হ","en":"astaghfiru-llāh"},"mean":{"bn":"আমি আল্লাহর কাছে ক্ষমা চাই","en":"I seek Allah's forgiveness"}},{"ar":"إِنْ شَاءَ اللّٰهُ","tr":{"bn":"ইন শা-আল্লা-হ","en":"in shāʼa-llāh"},"mean":{"bn":"আল্লাহ চাইলে","en":"If Allah wills"}},{"ar":"جَزَاكَ اللّٰهُ خَيْرًا","tr":{"bn":"জাযা-কাল্লা-হু খাইরা-","en":"jazāka-llāhu khayrā"},"mean":{"bn":"আল্লাহ আপনাকে উত্তম প্রতিদান দিন","en":"May Allah reward you with good"}}],"title":{"bn":"লেভেল ৪: প্রতিদিনের বাক্য","en":"Level 4: Everyday phrases"}},{"type":"tip","kind":"fun","bn":"এই বাক্যগুলো আপনি হয়তো প্রতিদিন বলেন — এখন আপনি এগুলো আরবিতে নিজের চোখে পড়তেও পারেন!","en":"You probably say these phrases every day — now you can read them in Arabic with your own eyes!"},{"type":"examples","items":[{"ar":"رَبِّ زِدْنِي عِلْمًا","tr":{"bn":"রাব্বি যিদনী 'ইলমা-","en":"rabbi zidnī 'ilmā"},"mean":{"bn":"হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন","en":"My Lord, increase me in knowledge"},"note":{"bn":"সূরা ত্বা-হা ২০:১১৪","en":"Ta-Ha 20:114"}},{"ar":"فَإِنَّ مَعَ الْعُسْرِ يُسْرًا","tr":{"bn":"ফাইন্না মা'আল 'উসরি ইউসরা-","en":"fa-inna ma'al-'usri yusrā"},"mean":{"bn":"নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে","en":"Indeed, with hardship comes ease"},"note":{"bn":"সূরা আশ-শারহ ৯৪:৫","en":"Ash-Sharh 94:5"}},{"ar":"إِنَّ اللّٰهَ مَعَ الصّٰبِرِينَ","tr":{"bn":"ইন্নাল্লা-হা মা'আস সা-বিরীন","en":"inna-llāha ma'aṣ-ṣābirīn"},"mean":{"bn":"নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন","en":"Indeed, Allah is with the patient"},"note":{"bn":"সূরা আল-বাকারা ২:১৫৩","en":"Al-Baqarah 2:153"}},{"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً","tr":{"bn":"রাব্বানা- আ-তিনা- ফিদ দুনইয়া- হাসানাহ","en":"rabbanā ātinā fid-dunyā ḥasanah"},"mean":{"bn":"হে আমাদের রব, দুনিয়াতে আমাদের কল্যাণ দিন","en":"Our Lord, give us good in this world"},"note":{"bn":"সূরা আল-বাকারা ২:২০১ (অংশ)","en":"Al-Baqarah 2:201 (part)"}},{"ar":"وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ","tr":{"bn":"ওয়াল্লা-হু 'আলা- কুল্লি শাইয়িন ক্বাদীর","en":"wallāhu 'alā kulli shayʼin qadīr"},"mean":{"bn":"আর আল্লাহ সবকিছুর ওপর ক্ষমতাবান","en":"And Allah has power over all things"},"note":{"bn":"সূরা আল-বাকারা ২:২৮৪ (অংশ)","en":"Al-Baqarah 2:284 (part)"}}],"title":{"bn":"লেভেল ৫: কুরআনের ছোট বাক্য","en":"Level 5: Short Quranic phrases"}},{"type":"text","bn":"এবার আসল পুরস্কার: কুরআনের পুরো আয়াত! প্রথমে শব্দে শব্দে পড়ুন, তারপর পুরো আয়াত। আয়াতের শেষে থামুন — মনে আছে, থামলে শেষের হরকত/তানবীন সুকুন হয়ে যায়।","en":"Now the real prize: complete ayahs of the Quran! Read word by word first, then the whole ayah. Stop at the end of each ayah — remember, stopping turns the final vowel or tanween into a sukun.","title":{"bn":"আয়াত পড়ি!","en":"Let's read ayahs!"}},{"type":"ayah","ref":"1:1","ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","words":[{"ar":"بِسْمِ","bn":"নামে","en":"In the name"},{"ar":"اللّٰهِ","bn":"আল্লাহর","en":"of Allah"},{"ar":"الرَّحْمٰنِ","bn":"পরম করুণাময়","en":"the Most Gracious"},{"ar":"الرَّحِيمِ","bn":"অতি দয়ালু","en":"the Most Merciful"}],"tr":{"bn":"বিসমিল্লা-হির রাহমা-নির রাহীম","en":"bismi-llāhi-r-raḥmāni-r-raḥīm"},"mean":{"bn":"পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।","en":"In the name of Allah, the Most Gracious, the Most Merciful."}},{"type":"ayah","ref":"1:2","ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ","words":[{"ar":"الْحَمْدُ","bn":"সমস্ত প্রশংসা","en":"All praise"},{"ar":"لِلّٰهِ","bn":"আল্লাহর জন্য","en":"is for Allah"},{"ar":"رَبِّ","bn":"রব","en":"Lord"},{"ar":"الْعٰلَمِينَ","bn":"সকল জগতের","en":"of all the worlds"}],"tr":{"bn":"আলহামদু লিল্লা-হি রাব্বিল 'আ-লামীন","en":"al-ḥamdu lillāhi rabbil-'ālamīn"},"mean":{"bn":"সমস্ত প্রশংসা আল্লাহর, যিনি সকল জগতের রব।","en":"All praise is for Allah, Lord of all the worlds."}},{"type":"tip","kind":"tip","bn":"সূরা ইখলাস কুরআনের সবচেয়ে ছোট ও প্রিয় সূরাগুলোর একটি। প্রতিটি আয়াতের নিচে শব্দে শব্দে অর্থ আছে — পড়ার সাথে সাথে বুঝুন!","en":"Surah Al-Ikhlas is one of the shortest and most beloved surahs. Each ayah has a word-by-word meaning — understand as you read!","title":{"bn":"সূরা ইখলাস","en":"Surah Al-Ikhlas"}},{"type":"ayah","ref":"112:1","ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","words":[{"ar":"قُلْ","bn":"বলুন","en":"Say"},{"ar":"هُوَ","bn":"তিনি","en":"He is"},{"ar":"اللّٰهُ","bn":"আল্লাহ","en":"Allah"},{"ar":"أَحَدٌ","bn":"এক, অদ্বিতীয়","en":"One (unique)"}],"tr":{"bn":"ক্বুল হুওয়াল্লা-হু আহাদ","en":"qul huwa-llāhu aḥad"},"mean":{"bn":"বলুন, তিনিই আল্লাহ, এক ও অদ্বিতীয়।","en":"Say: He is Allah, the One."}},{"type":"ayah","ref":"112:2","ar":"اللّٰهُ الصَّمَدُ","words":[{"ar":"اللّٰهُ","bn":"আল্লাহ","en":"Allah"},{"ar":"الصَّمَدُ","bn":"অমুখাপেক্ষী","en":"the Self-Sufficient"}],"tr":{"bn":"আল্লা-হুস সামাদ","en":"allāhu-ṣ-ṣamad"},"mean":{"bn":"আল্লাহ অমুখাপেক্ষী — সবাই তাঁর মুখাপেক্ষী।","en":"Allah, the Self-Sufficient, on whom all depend."}},{"type":"ayah","ref":"112:3","ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","words":[{"ar":"لَمْ يَلِدْ","bn":"তিনি জন্ম দেননি","en":"He did not beget"},{"ar":"وَلَمْ","bn":"এবং না","en":"and not"},{"ar":"يُولَدْ","bn":"তাঁকে জন্ম দেওয়া হয়েছে","en":"was He begotten"}],"tr":{"bn":"লাম ইয়ালিদ ওয়া লাম ইউলাদ","en":"lam yalid wa lam yūlad"},"mean":{"bn":"তিনি কাউকে জন্ম দেননি, আর তাঁকেও জন্ম দেওয়া হয়নি।","en":"He neither begets nor was He begotten."}},{"type":"ayah","ref":"112:4","ar":"وَلَمْ يَكُنْ لَّهٗ كُفُوًا أَحَدٌ","words":[{"ar":"وَلَمْ يَكُنْ","bn":"আর নেই","en":"and there is not"},{"ar":"لَّهٗ","bn":"তাঁর","en":"to Him"},{"ar":"كُفُوًا","bn":"সমতুল্য","en":"equal"},{"ar":"أَحَدٌ","bn":"কেউ","en":"anyone"}],"tr":{"bn":"ওয়া লাম ইয়াকুল লাহূ কুফুওয়ান আহাদ","en":"wa lam yakul-lahū kufuwan aḥad"},"mean":{"bn":"আর তাঁর সমতুল্য কেউই নেই।","en":"And there is none equal to Him."}},{"type":"tip","kind":"tip","bn":"১১২:৪-এ يَكُنْ لَّهٗ পড়া হয় 'ইয়াকুল লাহূ' — নূনটা লামের সাথে মিশে যায় (লামের ওপর তাশদীদ দেখুন)। এটা 'ইদগাম', তাজবীদ ইউনিটে বিস্তারিত শিখবেন।","en":"In 112:4, يَكُنْ لَّهٗ is read 'yakul-lahū' — the noon merges into the lam (see the shaddah on the lam). This is 'idgham', covered fully in the tajweed unit."},{"type":"steps","items":[{"title":{"bn":"প্রতিদিন ৫ লাইন","en":"5 lines a day"},"desc":{"bn":"প্রতিদিন কুরআন থেকে অন্তত ৫ লাইন জোরে পড়ুন।","en":"Read at least 5 lines of the Quran aloud every day."}},{"title":{"bn":"শুনে শুনে মেলান","en":"Follow a reciter"},"desc":{"bn":"একজন ভালো ক্বারীর তিলাওয়াত শুনুন আর আঙুল দিয়ে লাইন অনুসরণ করুন।","en":"Listen to a good reciter and follow the lines with your finger."}},{"title":{"bn":"কাউকে শোনান","en":"Read to someone"},"desc":{"bn":"সপ্তাহে একবার শিক্ষক বা পরিবারের কাউকে পড়ে শোনান — ভুল ধরিয়ে দিতে বলুন।","en":"Once a week, read to a teacher or family member and ask them to correct you."}},{"title":{"bn":"তাজবীদ শিখুন","en":"Learn tajweed"},"desc":{"bn":"পরের ইউনিটে তাজবীদের নিয়ম শিখে তিলাওয়াতকে আরও সুন্দর করুন।","en":"Make your recitation even more beautiful with the tajweed rules in the next unit."}}],"title":{"bn":"এরপর কী?","en":"What's next?"}},{"type":"quiz","items":[{"q":{"bn":"এটি কীভাবে পড়বেন?","en":"How do you read this?"},"ar":"بِسْمِ اللّٰهِ","options":[{"bn":"বাসমাল্লা-হ","en":"basmallāh"},{"bn":"বিসমিল্লা-হ","en":"bismillāh"},{"bn":"বিসমি আল্লা-হ","en":"bismi allāh"}],"answer":1,"explain":{"bn":"اللّٰه-এর আলিফ হামযাতুল ওয়াসল, তাই বাদ যায়।","en":"The alif of اللّٰه is a hamzatul wasl, so it's skipped."}},{"q":{"bn":"الصَّمَدُ-এ লাম কেন পড়া হয় না?","en":"Why is the lam silent in الصَّمَدُ?"},"options":[{"bn":"ص চাঁদের অক্ষর","en":"ص is a moon letter"},{"bn":"লাম সবসময় নীরব","en":"lam is always silent"},{"bn":"ص সূর্যের অক্ষর","en":"ص is a sun letter"}],"answer":2},{"q":{"bn":"أَحَدٌ শব্দে আয়াতের শেষে থামলে কীভাবে পড়বেন?","en":"How do you read أَحَدٌ when stopping at the end of the ayah?"},"options":[{"bn":"আহাদ্","en":"aḥad"},{"bn":"আহাদুন","en":"aḥadun"},{"bn":"আহাদা","en":"aḥadā"}],"answer":0},{"q":{"bn":"{{رَبِّ زِدْنِي عِلْمًا}} অর্থ কী?","en":"What does {{رَبِّ زِدْنِي عِلْمًا}} mean?"},"options":[{"bn":"সমস্ত প্রশংসা আল্লাহর","en":"All praise is for Allah"},{"bn":"হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন","en":"My Lord, increase me in knowledge"},{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"}],"answer":1},{"q":{"bn":"لَّهٗ-এর ওপরের উল্টা পেশ কী বোঝায়?","en":"What does the inverted damma on لَّهٗ mean?"},"ar":"لَّهٗ","options":[{"bn":"তানবীন","en":"tanween"},{"bn":"পড়া হয় না","en":"not read"},{"bn":"লম্বা 'ঊ' — লাহূ","en":"a long 'ū' — lahū"}],"answer":2},{"q":{"bn":"الْحَمْدُ-তে লাম কি পড়া হয়?","en":"Is the lam read in الْحَمْدُ?"},"options":[{"bn":"হ্যাঁ — ح চাঁদের অক্ষর","en":"Yes — ح is a moon letter"},{"bn":"না — ح সূর্যের অক্ষর","en":"No — ح is a sun letter"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}},{"type":"tip","kind":"fun","bn":"আলহামদুলিল্লাহ! আপনি আলিফ থেকে শুরু করে কুরআনের আয়াত পড়া পর্যন্ত চলে এসেছেন। এটা অনেক বড় অর্জন। প্রতিদিন একটু একটু পড়তে থাকুন — প্রতিটি অক্ষরে নেকি!","en":"Alhamdulillah! You've journeyed from Alif all the way to reading ayahs of the Quran. That's a huge achievement. Keep reading a little every day — there's reward in every letter!","title":{"bn":"অভিনন্দন!","en":"Congratulations!"}}]}]});
AQ.units.push({"id":"writing","order":2,"icon":"خط","color":"cyan","title":{"bn":"লিখতে শিখি — আরবি হাতের লেখা","en":"Learn to Write — Arabic Handwriting"},"subtitle":{"bn":"কলমের প্রথম টান থেকে আয়াত লেখা পর্যন্ত — ধাপে ধাপে আরবি হাতের লেখা","en":"From your first pen stroke to copying ayahs — Arabic handwriting, phase by phase"},"lessons":[{"id":"wr-ready","icon":"قلم","title":{"bn":"লেখার প্রস্তুতি","en":"Get Ready to Write"},"subtitle":{"bn":"বসা, কলম ধরা, লাইন আর মাপ — লেখার আগে ৫টি জরুরি অভ্যাস","en":"Posture, grip, the line and the size ruler — five habits before you write"},"minutes":10,"goals":[{"bn":"সঠিকভাবে বসা ও পেনসিল ধরা","en":"How to sit and hold your pencil"},{"bn":"আরবি লাইনের কোথায় বসে, কতটা বড় হয়","en":"Where Arabic sits on the line and how big it is"},{"bn":"বিন্দু (নুকতা) কীভাবে দিতে হয়","en":"How to make a dot (nuqta)"},{"bn":"সোনালি নিয়ম: আগে শরীর, তারপর বিন্দু, শেষে হরকত","en":"The golden rule: body first, dots next, harakat last"}],"blocks":[{"type":"text","bn":"পড়া শিখে আপনি অক্ষর চিনেছেন — এবার নিজের হাতে লেখার পালা! যা হাতে লেখা হয়, তা মনে গেঁথে যায়; তাই লিখলে পড়াও দ্রুত হবে। আজ আমরা শুধু প্রস্তুতি নেব: বসা, কলম ধরা আর লাইন চেনা।","en":"You have learned to recognise the letters — now it's time to write them with your own hand! What the hand writes, the mind keeps, so writing will make your reading faster too. Today we only get ready: sitting, holding the pencil and knowing the line."},{"type":"steps","items":[{"title":{"bn":"সোজা হয়ে বসুন","en":"Sit up straight"},"desc":{"bn":"পিঠ সোজা, দুই পা মেঝেতে। খাতা টেবিলে, চোখ থেকে এক হাত দূরে। বাঁ হাত দিয়ে খাতা আলতো চেপে রাখুন।","en":"Back straight, both feet on the floor. Notebook on the table, about an arm's length from your eyes. Rest your free hand gently on the page."}},{"title":{"bn":"পেনসিল আলতো ধরুন","en":"Hold the pencil lightly"},"desc":{"bn":"বুড়ো আঙুল আর তর্জনী দিয়ে ধরুন, মধ্যমার ওপর ভর দিন — মাথা থেকে প্রায় ২ সেমি ওপরে। আঙুলের গিঁট সাদা হয়ে গেলে বুঝবেন খুব জোরে চাপছেন।","en":"Pinch it with thumb and index finger and rest it on the middle finger, about 2 cm above the tip. If your knuckles turn white, you are squeezing too hard."}},{"title":{"bn":"খাতা একটু কাত করুন","en":"Tilt the page a little"},"desc":{"bn":"খাতা সামান্য কাত করলে হাত আরামে ডান থেকে বামে চলে। যে কোণে আপনার হাত সবচেয়ে আরাম পায়, সেটাই ঠিক।","en":"A slight tilt lets your hand glide from right to left. Whatever angle feels most comfortable for your arm is the right one."}},{"title":{"bn":"নরম পেনসিল ও রাবার","en":"Soft pencil and an eraser"},"desc":{"bn":"শুরুতে HB বা 2B পেনসিল নিন। ভুল হলে ভয় নেই — মুছে আবার লিখুন। পরে কলম বা মার্কার দিয়ে লিখবেন।","en":"Start with an HB or 2B pencil. Mistakes are fine — erase and try again. Pens and markers come later."}},{"title":{"bn":"ডান দিক থেকে শুরু","en":"Start on the right"},"desc":{"bn":"প্রতিটি লাইন খাতার ডান কিনারা থেকে শুরু হয়ে বাম দিকে এগোয়। প্রতিটি অক্ষরও সাধারণত ডান দিক থেকে শুরু হয়।","en":"Every line starts at the right edge of the page and travels left. Most letters also begin on their right side."}}],"title":{"bn":"লেখার আগে ৫টি অভ্যাস","en":"Five habits before writing"}},{"type":"text","bn":"আরবি অক্ষর একটা কাল্পনিক লাইনের ওপর বসে — একে বলে **মূল লাইন** (baseline)। বেশিরভাগ অক্ষর লাইনের ওপরে বসে থাকে; কিছু অক্ষরের লেজ লাইনের নিচে ঝুলে পড়ে, যেমন {{ر}} {{ن}} {{ع}} {{م}}।","en":"Arabic letters sit on an imaginary line called the **baseline**. Most letters sit on top of it; some letters drop a tail below it, like {{ر}} {{ن}} {{ع}} {{م}}.","title":{"bn":"মূল লাইন","en":"The baseline"}},{"type":"tip","kind":"memory","bn":"বাংলা অক্ষর ওপরের **মাত্রা** থেকে ঝোলে, যেন কাপড় দড়িতে ঝুলছে। আরবি অক্ষর নিচের লাইনে **বসে**, যেন পাখি বিদ্যুতের তারে বসে আছে — আর কোনো কোনো পাখির লেজ তারের নিচে ঝুলে থাকে!","en":"Bangla letters hang from the **matra** line on top, like clothes on a washing line. Arabic letters **sit** on the bottom line, like birds on a wire — and some birds let their tails hang below the wire!","title":{"bn":"মাত্রা বনাম মূল লাইন","en":"Matra vs baseline"}},{"type":"table","head":[{"bn":"অংশ","en":"Part"},{"bn":"কতটা বড়?","en":"How big?"}],"rows":[[{"bn":"আলিফ {{ا}}","en":"Alif {{ا}}"},{"bn":"পুরো উচ্চতা — এটাই আমাদের মাপকাঠি","en":"Full height — this is our ruler"}],[{"bn":"লম্বা অক্ষর {{ل}} {{ك}} {{ط}}","en":"Tall letters {{ل}} {{ك}} {{ط}}"},{"bn":"প্রায় আলিফের সমান উঁচু","en":"About as tall as alif"}],[{"bn":"নৌকা ও দাঁত {{ب}} {{س}}","en":"Boats and teeth {{ب}} {{س}}"},{"bn":"ছোট — আলিফের প্রায় চার ভাগের এক ভাগ","en":"Short — about a quarter of alif"}],[{"bn":"লেজ {{ر}} {{ن}} {{ي}}","en":"Tails {{ر}} {{ن}} {{ي}}"},{"bn":"লাইনের নিচে প্রায় অর্ধেক আলিফ","en":"About half an alif below the line"}],[{"bn":"বিন্দু","en":"Dot"},{"bn":"কলমের মাথার এক ছোট্ট চাপ","en":"One small press of the pen tip"}]],"title":{"bn":"আলিফ দিয়ে মাপুন","en":"Measure with alif"}},{"type":"tip","kind":"tip","bn":"নাসখ লিপিতে আলিফ প্রায় ৫টি বিন্দু একটার ওপর আরেকটা রাখলে যত উঁচু হয়, ততটা। খাতায় শুধু খেয়াল রাখুন: এক লাইনের সব আলিফ যেন সমান উঁচু হয়।","en":"In Naskh script, alif is about as tall as 5 dots stacked on top of each other. In your notebook, just make sure every alif on a line is the same height."},{"type":"tip","kind":"tip","bn":"আরবি বিন্দু (নুকতা) আসলে ছোট্ট একটা **হীরা** (◆)। কলমের মাথা কাগজে রেখে সামান্য তেরছা করে টেনে নিন। পেনসিলে ছোট্ট ভরাট বিন্দু দিলেই হবে — শুধু সব বিন্দু যেন সমান হয়, আর অক্ষরের গায়ে লেগে না যায়।","en":"An Arabic dot (nuqta) is really a tiny **diamond** (◆). Touch the pen tip down and drag it a tiny bit at a slant. With a pencil, a small filled dot is fine — just keep all dots the same size and never touching the letter.","title":{"bn":"বিন্দুর মাপ","en":"Dot size"}},{"type":"tip","kind":"memory","bn":"**সোনালি নিয়ম: শরীর → বিন্দু → হরকত।** আগে ঘর বানাই (অক্ষরের শরীর), তারপর জানালা বসাই (বিন্দু), শেষে ছাদে পতাকা লাগাই (যবর-যের-পেশ)। ঘর না বানিয়ে কেউ জানালা লাগায় না!","en":"**Golden rule: body → dots → harakat.** First build the house (the letter's body), then fit the windows (the dots), and last put the flags on the roof (the vowel marks). Nobody fits windows before building the house!","title":{"bn":"সোনালি নিয়ম","en":"The golden rule"}},{"type":"strokes","items":[{"id":"line-h","label":{"bn":"শোয়ানো লাইন — ডান থেকে বামে টানুন, মূল লাইনের ওপর দিয়ে","en":"Lying line — pull from right to left along the baseline"}},{"id":"line-v","label":{"bn":"দাঁড়ানো লাইন — ওপর থেকে নিচে, আলিফের মতো","en":"Standing line — top to bottom, like alif"}},{"id":"dot","label":{"bn":"বিন্দু — ছোট্ট এক চাপ, সব সমান মাপের","en":"Dot — one small press, all the same size"}}],"title":{"bn":"প্রথম তিনটি টান","en":"Your first three strokes"}},{"type":"selfcheck","items":[{"bn":"আমি সোজা হয়ে বসেছি, পেনসিল আলতো করে ধরেছি","en":"I sat up straight and held my pencil lightly"},{"bn":"আমি প্রতিটি লাইন ডান দিক থেকে শুরু করেছি","en":"I started every line on the right"},{"bn":"আমার দাঁড়ানো লাইনগুলো সমান উঁচু","en":"My standing lines are all the same height"},{"bn":"আমার বিন্দুগুলো ছোট ও সমান মাপের","en":"My dots are small and the same size"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"আরবি লেখা কোন দিক থেকে শুরু হয়?","en":"Where does Arabic writing start?"},"options":[{"bn":"বাম দিক","en":"The left"},{"bn":"ডান দিক","en":"The right"},{"bn":"মাঝখান","en":"The middle"}],"answer":1},{"q":{"bn":"আরবি অক্ষর কোথায় বসে?","en":"Where do Arabic letters sit?"},"options":[{"bn":"ওপরের মাত্রা থেকে ঝোলে","en":"They hang from a top line"},{"bn":"নিচের মূল লাইনের ওপর","en":"On the bottom baseline"},{"bn":"লাইন ছাড়া যেখানে খুশি","en":"Anywhere, no line"}],"answer":1,"explain":{"bn":"বাংলা মাত্রা থেকে ঝোলে, আরবি নিচের লাইনে বসে।","en":"Bangla hangs from the matra; Arabic sits on the baseline."}},{"q":{"bn":"লেখার সোনালি নিয়মে সঠিক ক্রম কোনটি?","en":"Which is the correct order in the golden rule?"},"options":[{"bn":"হরকত → বিন্দু → শরীর","en":"Harakat → dots → body"},{"bn":"বিন্দু → শরীর → হরকত","en":"Dots → body → harakat"},{"bn":"শরীর → বিন্দু → হরকত","en":"Body → dots → harakat"}],"answer":2},{"q":{"bn":"অক্ষরের মাপ বোঝার জন্য কোন অক্ষরকে মাপকাঠি ধরা হয়?","en":"Which letter do we use as a size ruler?"},"options":["ب","ا","ن"],"answer":1},{"q":{"bn":"পেনসিল খুব জোরে চেপে ধরলে কী হয়?","en":"What happens if you squeeze the pencil too hard?"},"options":[{"bn":"হাত দ্রুত ক্লান্ত হয়, লেখা কাঁপে","en":"Your hand tires quickly and lines wobble"},{"bn":"লেখা আরও সুন্দর হয়","en":"Writing becomes nicer"},{"bn":"কিছুই হয় না","en":"Nothing happens"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-strokes","icon":"◡","title":{"bn":"কলমের ১১টি চাল","en":"The 11 Pen Moves"},"subtitle":{"bn":"হাত গরম করার টান — এগুলো দিয়েই সব অক্ষর তৈরি","en":"Warm-up strokes — every letter is built from these"},"minutes":12,"goals":[{"bn":"আরবি লেখার ১১টি মূল টান চেনা","en":"Know the 11 basic strokes of Arabic writing"},{"bn":"কোন টান কোন অক্ষরে লাগে","en":"Which stroke is used in which letters"},{"bn":"কলমের ওপর নিয়ন্ত্রণ বাড়ানো","en":"Build steady pen control"}],"blocks":[{"type":"text","bn":"খেলোয়াড় খেলার আগে শরীর গরম করে; লেখকও লেখার আগে হাত গরম করে। এই পাঠে ১১টি ছোট টান শিখব। প্রতিটি টান ধীরে, মন দিয়ে, ডান থেকে বামে টানুন।","en":"Players warm up before a match; writers warm up their hands before writing. In this lesson you will learn 11 small strokes. Draw each one slowly and carefully, from right to left."},{"type":"tip","kind":"memory","bn":"লেগো ব্লক দিয়ে যেমন বাড়ি-গাড়ি সব বানানো যায়, তেমনি এই **১১টি চাল** দিয়েই আরবির সব অক্ষর বানানো যায়। চালগুলো শিখে ফেললে অর্ধেক কাজ শেষ!","en":"Just as Lego bricks can build houses and cars, these **11 moves** build every Arabic letter. Learn the moves and half the work is done!","title":{"bn":"১১টি চালেই সব অক্ষর","en":"Every letter from 11 moves"}},{"type":"strokes","items":[{"id":"line-h","label":{"bn":"শোয়ানো লাইন — লাইনের ওপর ডান থেকে বামে; অক্ষর জোড়ার সেতু","en":"Lying line — right to left on the baseline; the bridge that joins letters"}},{"id":"line-v","label":{"bn":"দাঁড়ানো লাইন — ওপর থেকে নিচে: {{ا}} {{ل}} {{ك}}","en":"Standing line — top to bottom: {{ا}} {{ل}} {{ك}}"}},{"id":"slant","label":{"bn":"তেরছা টান — ওপর থেকে নিচে কাত হয়ে: {{كـ}}-এর মাথা","en":"Slant — top to bottom at an angle: the top of {{كـ}}"}},{"id":"cup","label":{"bn":"নৌকা — লাইনের ওপর চ্যাপ্টা কাপ: {{ب}} {{ت}} {{ث}}","en":"Cup — a flat boat on the line: {{ب}} {{ت}} {{ث}}"}},{"id":"bowl","label":{"bn":"বাটি — লাইনের নিচে গোল: {{ن}} {{ل}}","en":"Bowl — round, dipping below the line: {{ن}} {{ل}}"}},{"id":"tail","label":{"bn":"লেজ — ওপর থেকে নিচে বাঁ দিকে পিছলে: {{ر}} {{ز}} {{و}}","en":"Tail — sliding down and to the left: {{ر}} {{ز}} {{و}}"}},{"id":"hook","label":{"bn":"বড়শি — টুপি আর বড় পেট: {{ج}} {{ح}} {{خ}}","en":"Hook — a cap and a big belly: {{ج}} {{ح}} {{خ}}"}},{"id":"teeth","label":{"bn":"দাঁত — ছোট ছোট তিনটি ঢেউ-দাঁত: {{س}} {{ش}}","en":"Teeth — three small zigzag teeth: {{س}} {{ش}}"}},{"id":"loop","label":{"bn":"গোল মাথা — ছোট্ট বন্ধ গোল: {{م}} {{و}} {{ف}} {{ق}} {{ه}}","en":"Loop — a small closed circle: {{م}} {{و}} {{ف}} {{ق}} {{ه}}"}},{"id":"wave","label":{"bn":"ঢেউ — {{ى}} / {{ي}}-এর শেষের ঢেউ খেলানো টান","en":"Wave — the wavy ending of {{ى}} / {{ي}}"}},{"id":"dot","label":{"bn":"বিন্দু — ছোট্ট হীরা, সবশেষে দেওয়া হয়","en":"Dot — a tiny diamond, always added last"}}],"title":{"bn":"১১টি চাল অনুশীলন করুন","en":"Practise the 11 moves"}},{"type":"table","head":[{"bn":"অক্ষর","en":"Letter"},{"bn":"কোন চাল দিয়ে তৈরি","en":"Built from"}],"rows":[["ب",{"bn":"নৌকা + বিন্দু","en":"cup + dot"}],["ن",{"bn":"বাটি + বিন্দু","en":"bowl + dot"}],["ل",{"bn":"দাঁড়ানো লাইন + বাটি","en":"standing line + bowl"}],["و",{"bn":"গোল মাথা + লেজ","en":"loop + tail"}],["ش",{"bn":"দাঁত + বাটি + ৩ বিন্দু","en":"teeth + bowl + 3 dots"}],["ق",{"bn":"গোল মাথা + বাটি + ২ বিন্দু","en":"loop + bowl + 2 dots"}],["ي",{"bn":"ঢেউ + ২ বিন্দু","en":"wave + 2 dots"}]],"title":{"bn":"চাল জোড়া দিলেই অক্ষর","en":"Join moves, get letters"}},{"type":"tip","kind":"tip","bn":"প্রতিদিন লেখার আগে ২ মিনিট এই টানগুলো একবার করে টানুন — ঠিক যেমন গান গাওয়ার আগে গলা সাধা হয়।","en":"Before writing each day, spend 2 minutes drawing each stroke once — just like a singer warms up before a song."},{"type":"tip","kind":"fun","bn":"আরবি লিপিতে একটা মজার ব্যাপার: অনেক অক্ষরের শরীর একই, শুধু বিন্দু আলাদা। {{ب ت ث}} — একই নৌকা, শুধু যাত্রী আলাদা!","en":"A fun fact about Arabic script: many letters share the same body and differ only by dots. {{ب ت ث}} — the same boat, just different passengers!"},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি টান ডান থেকে বামে বা ওপর থেকে নিচে টেনেছি","en":"I drew every stroke right-to-left or top-to-bottom"},{"bn":"আমার নৌকা লাইনের ওপর বসেছে, বাটি লাইনের নিচে নেমেছে","en":"My cups sit on the line and my bowls dip below it"},{"bn":"আমার তিনটি দাঁত সমান ছোট","en":"My three teeth are equally small"},{"bn":"আমি ধীরে টেনেছি, তাড়াহুড়ো করিনি","en":"I went slowly and didn't rush"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{ب}}-এর শরীর কোন চাল দিয়ে তৈরি?","en":"Which move makes the body of {{ب}}?"},"options":[{"bn":"নৌকা (cup)","en":"Cup"},{"bn":"বাটি (bowl)","en":"Bowl"},{"bn":"দাঁত (teeth)","en":"Teeth"}],"answer":0},{"q":{"bn":"কোন চাল লাইনের নিচে নামে?","en":"Which move dips below the line?"},"options":[{"bn":"নৌকা","en":"Cup"},{"bn":"বাটি","en":"Bowl"},{"bn":"বিন্দু","en":"Dot"}],"answer":1},{"q":{"bn":"{{س}} ও {{ش}}-এ কোন চাল আছে?","en":"Which move is in {{س}} and {{ش}}?"},"options":[{"bn":"বড়শি","en":"Hook"},{"bn":"দাঁত","en":"Teeth"},{"bn":"দাঁড়ানো লাইন","en":"Standing line"}],"answer":1},{"q":{"bn":"কোন অক্ষরে দাঁড়ানো লাইন আছে?","en":"Which letter has a standing line?"},"options":["ر","ل","ن"],"answer":1},{"q":{"bn":"কোন চাল সবসময় সবশেষে দেওয়া হয়?","en":"Which move always comes last?"},"options":[{"bn":"বিন্দু","en":"Dot"},{"bn":"লেজ","en":"Tail"},{"bn":"গোল মাথা","en":"Loop"}],"answer":0,"explain":{"bn":"সোনালি নিয়ম: শরীর আগে, বিন্দু পরে।","en":"Golden rule: body first, dots after."}}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-alif-ba","icon":"اب","title":{"bn":"আলিফ ও নৌকা পরিবার","en":"The Alif and Boat Family"},"subtitle":{"bn":"ا ب ت ث ن ي — সোজা লাঠি, নৌকা, বাটি আর ঢেউ","en":"ا ب ت ث ن ي — a stick, a boat, a bowl and a wave"},"minutes":15,"goals":[{"bn":"{{ا ب ت ث ن ي}} সঠিক ক্রমে লেখা","en":"Write {{ا ب ت ث ن ي}} in the correct stroke order"},{"bn":"নৌকা ({{ب}}) আর বাটি ({{ن}})-এর পার্থক্য","en":"The difference between a boat ({{ب}}) and a bowl ({{ن}})"},{"bn":"বিন্দু ঠিক জায়গায় বসানো","en":"Place dots in exactly the right spot"}],"blocks":[{"type":"text","bn":"চলুন প্রথম অক্ষরগুলো লিখি! এই পরিবারে আছে সোজা আলিফ, তিন ভাই {{ب ت ث}} (একই নৌকা, আলাদা বিন্দু), গভীর বাটির {{ن}} আর ঢেউ খেলানো {{ي}}।","en":"Let's write our first letters! This family has straight alif, the three brothers {{ب ت ث}} (same boat, different dots), deep-bowled {{ن}} and wavy {{ي}}."},{"type":"letters","items":["alif","ba","ta","tha","nun","ya"]},{"type":"howto","letter":"ا","steps":[{"bn":"আলিফের পুরো উচ্চতায়, ওপর থেকে শুরু করুন।","en":"Start at the top, at full alif height."},{"bn":"এক টানে সোজা নিচে নামুন।","en":"Pull straight down in one stroke."},{"bn":"মূল লাইনে এসে থামুন — নিচে নামবেন না।","en":"Stop on the baseline — don't go below it."}],"tip":{"bn":"আলিফ যেন সোজা দাঁড়ানো সৈনিক — হেলে পড়বে না!","en":"Alif is a soldier standing straight — no leaning over!"}},{"type":"howto","letter":"ب","steps":[{"bn":"ডান দিকে, লাইনের একটু ওপরে ছোট্ট একটা দাঁত দিয়ে শুরু করুন।","en":"Start on the right with a tiny tooth just above the line."},{"bn":"নিচে নেমে লাইনের ওপর দিয়ে বাঁ দিকে লম্বা, চ্যাপ্টা নৌকা টানুন।","en":"Come down and pull a long, flat boat to the left along the line."},{"bn":"বাঁ মাথায় সামান্য ওপরে বাঁক নিয়ে কলম তুলুন।","en":"Curve up a little at the left end and lift the pen."},{"bn":"সবশেষে নৌকার মাঝখানের নিচে একটি বিন্দু।","en":"Last, one dot under the middle of the boat."}],"tip":{"bn":"নৌকা লাইনের ওপর ভাসে, ডোবে না!","en":"The boat floats on the line — it never sinks!"}},{"type":"howto","letter":"ت","steps":[{"bn":"ডান দিকে, লাইনের একটু ওপরে ছোট্ট একটা দাঁত দিয়ে শুরু করুন।","en":"Start on the right with a tiny tooth just above the line."},{"bn":"নিচে নেমে লাইনের ওপর দিয়ে বাঁ দিকে লম্বা, চ্যাপ্টা নৌকা টানুন।","en":"Come down and pull a long, flat boat to the left along the line."},{"bn":"বাঁ মাথায় সামান্য ওপরে বাঁক নিয়ে কলম তুলুন।","en":"Curve up a little at the left end and lift the pen."},{"bn":"সবশেষে মাঝখানের ওপরে পাশাপাশি দুটি বিন্দু — আগে ডানেরটা।","en":"Last, two dots side by side above the middle — right one first."}]},{"type":"howto","letter":"ث","steps":[{"bn":"ডান দিকে, লাইনের একটু ওপরে ছোট্ট একটা দাঁত দিয়ে শুরু করুন।","en":"Start on the right with a tiny tooth just above the line."},{"bn":"নিচে নেমে লাইনের ওপর দিয়ে বাঁ দিকে লম্বা, চ্যাপ্টা নৌকা টানুন।","en":"Come down and pull a long, flat boat to the left along the line."},{"bn":"বাঁ মাথায় সামান্য ওপরে বাঁক নিয়ে কলম তুলুন।","en":"Curve up a little at the left end and lift the pen."},{"bn":"সবশেষে ওপরে তিনটি বিন্দু: নিচে পাশাপাশি দুটি, তার ওপরে একটি — ছোট্ট পাহাড়।","en":"Last, three dots on top: two side by side, one above them — a tiny hill."}]},{"type":"howto","letter":"ن","steps":[{"bn":"ডান দিকে, লাইনের একটু ওপর থেকে শুরু করুন।","en":"Start on the right, a little above the line."},{"bn":"নিচে নেমে লাইনের নিচে গোল একটা বাটি আঁকুন।","en":"Dip down and draw a round bowl below the line."},{"bn":"বাঁ দিকে উঠে শুরুর উচ্চতার কাছাকাছি শেষ করুন।","en":"Come up on the left and finish near your starting height."},{"bn":"সবশেষে বাটির মাঝখানের ওপরে একটি বিন্দু।","en":"Last, one dot above the middle of the bowl."}],"tip":{"bn":"{{ب}} হলো চ্যাপ্টা নৌকা (লাইনের ওপরে), {{ن}} হলো গভীর বাটি (লাইনের নিচে)।","en":"{{ب}} is a flat boat (on the line); {{ن}} is a deep bowl (below the line)."}},{"type":"howto","letter":"ي","steps":[{"bn":"ওপরে ডান দিক থেকে ছোট্ট একটা বাঁক দিয়ে শুরু করুন — যেন ছোট্ট একটা 's'।","en":"Start at the top right with a small curve — like a little 's'."},{"bn":"না থেমে নিচে নেমে লাইনের নিচে চওড়া, গোল ঢেউ টানুন।","en":"Without stopping, sweep down into a wide, round wave below the line."},{"bn":"শেষে আলতো করে ওপরে তুলে কলম তুলুন।","en":"Finish with a gentle upward flick and lift the pen."},{"bn":"সবশেষে ঢেউয়ের নিচে পাশাপাশি দুটি বিন্দু।","en":"Last, two dots side by side under the wave."}]},{"type":"tip","kind":"memory","bn":"বিন্দুর জায়গা মনে রাখুন: **বা = বল নিচে** (১টি নিচে), **তা = দুই চোখ ওপরে**, **ছা = তিন বিন্দুর পাহাড়**, **নূন = বাটিতে একটি মার্বেল ওপরে**, **ইয়া = দুটি পা নিচে**।","en":"Remember the dot spots: **Baa = ball below** (1 under), **Taa = two eyes on top**, **Thaa = a hill of three**, **Noon = one marble above the bowl**, **Yaa = two feet below**.","title":{"bn":"বিন্দুর ছড়া","en":"Dot rhyme"}},{"type":"tip","kind":"warn","bn":"সবচেয়ে সাধারণ ভুল: নৌকা আঁকার আগেই বিন্দু দিয়ে ফেলা। মনে রাখুন — আগে পুরো শরীর, তারপর বিন্দু।","en":"The most common mistake: putting the dot before drawing the boat. Remember — the whole body first, then the dots."},{"type":"write","level":"letter","items":["ا","ب","ت","ث","ن","ي"],"note":{"bn":"প্রতিটি অক্ষর প্রথমে মডেলের ওপর হাত বুলিয়ে, তারপর নিজে লিখুন।","en":"Trace over the model first, then write each letter on your own."}},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমার বিন্দু সঠিক সংখ্যায় ও সঠিক জায়গায় আছে","en":"My dots are the right number and in the right place"},{"bn":"আমার {{ب}} লাইনের ওপরে, {{ن}} লাইনের নিচে নেমেছে","en":"My {{ب}} sits on the line and my {{ن}} dips below it"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"আলিফ লেখা হয় কোন দিকে?","en":"Which way is alif written?"},"options":[{"bn":"নিচ থেকে ওপরে","en":"Bottom to top"},{"bn":"ওপর থেকে নিচে","en":"Top to bottom"},{"bn":"বাম থেকে ডানে","en":"Left to right"}],"answer":1},{"q":{"bn":"{{ث}}-এর বিন্দু কীভাবে সাজানো?","en":"How are the dots of {{ث}} arranged?"},"options":[{"bn":"নিচে একটি","en":"One below"},{"bn":"ওপরে পাশাপাশি দুটি","en":"Two side by side on top"},{"bn":"ওপরে তিনটি, পাহাড়ের মতো","en":"Three on top, like a hill"}],"answer":2},{"q":{"bn":"কোন অক্ষর লাইনের নিচে বাটি বানায়?","en":"Which letter makes a bowl below the line?"},"options":["ب","ن","ت"],"answer":1},{"q":{"bn":"{{ب}} লিখতে বিন্দু কখন দেবেন?","en":"When do you add the dot of {{ب}}?"},"options":[{"bn":"নৌকা শুরুর আগে","en":"Before the boat"},{"bn":"নৌকা শেষ করার পরে","en":"After finishing the boat"},{"bn":"নৌকার মাঝপথে","en":"Halfway through the boat"}],"answer":1},{"q":{"bn":"{{ي}}-এর বিন্দু কোথায়?","en":"Where are the dots of {{ي}}?"},"options":[{"bn":"ওপরে দুটি","en":"Two above"},{"bn":"নিচে দুটি","en":"Two below"},{"bn":"নিচে একটি","en":"One below"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-jim","icon":"ج","title":{"bn":"বড়শি পরিবার: জীম, হা, খা","en":"The Hook Family: Jeem, Ḥaa, Khaa"},"subtitle":{"bn":"ج ح خ — টুপি, তীক্ষ্ণ কোণ আর বড় গোল পেট","en":"ج ح خ — a cap, a sharp corner and a big round belly"},"minutes":12,"goals":[{"bn":"{{ج ح خ}}-এর একই শরীর এক টানে লেখা","en":"Write the shared body of {{ج ح خ}} in one stroke"},{"bn":"বিন্দু দিয়ে তিন ভাইকে আলাদা করা","en":"Tell the three brothers apart by their dots"},{"bn":"লাইনের নিচে পেট কতটা নামবে","en":"How far the belly drops below the line"}],"blocks":[{"type":"text","bn":"এই তিন ভাইয়ের শরীর হুবহু এক — একটা ছোট টুপি আর বড় গোল পেট, যেন খোলা মুখ বা মাছ ধরার বড়শি। পার্থক্য শুধু বিন্দুতে: {{ج}}-এর পেটে, {{خ}}-এর মাথায়, আর {{ح}}-এর কোথাও নেই।","en":"These three brothers have exactly the same body — a small cap and a big round belly, like an open mouth or a fishing hook. The only difference is the dot: inside the belly for {{ج}}, on the head for {{خ}}, and none at all for {{ح}}."},{"type":"letters","items":["jim","hha","kha"]},{"type":"howto","letter":"ج","steps":[{"bn":"ওপরে ডান দিক থেকে শুরু করে বাঁ দিকে ছোট্ট একটা টুপি টানুন।","en":"Start at the top right and draw a short cap to the left."},{"bn":"টুপির বাঁ মাথায় তীক্ষ্ণ কোণ করে তেরছাভাবে নিচে নামুন।","en":"Make a sharp corner at the cap's left end and slant down."},{"bn":"বাঁ দিকে বড়, গোল পেট টানুন — লাইনের নিচে নেমে তলা ঘুরে ডান দিকে শেষ করুন।","en":"Swing a big round belly to the left, going below the line, and curve round the bottom to finish toward the right."},{"bn":"সবশেষে পেটের ভেতরে মাঝখানে একটি বিন্দু।","en":"Last, one dot in the middle of the belly."}]},{"type":"howto","letter":"ح","steps":[{"bn":"ওপরে ডান দিক থেকে শুরু করে বাঁ দিকে ছোট্ট একটা টুপি টানুন।","en":"Start at the top right and draw a short cap to the left."},{"bn":"টুপির বাঁ মাথায় তীক্ষ্ণ কোণ করে তেরছাভাবে নিচে নামুন।","en":"Make a sharp corner at the cap's left end and slant down."},{"bn":"বাঁ দিকে বড়, গোল পেট টানুন — লাইনের নিচে নেমে তলা ঘুরে ডান দিকে শেষ করুন।","en":"Swing a big round belly to the left, going below the line, and curve round the bottom to finish toward the right."},{"bn":"কোনো বিন্দু নেই — শুধু দেখে নিন পেট গোল ও পরিষ্কার হয়েছে কি না।","en":"No dot — just check that the belly is round and clean."}]},{"type":"howto","letter":"خ","steps":[{"bn":"ওপরে ডান দিক থেকে শুরু করে বাঁ দিকে ছোট্ট একটা টুপি টানুন।","en":"Start at the top right and draw a short cap to the left."},{"bn":"টুপির বাঁ মাথায় তীক্ষ্ণ কোণ করে তেরছাভাবে নিচে নামুন।","en":"Make a sharp corner at the cap's left end and slant down."},{"bn":"বাঁ দিকে বড়, গোল পেট টানুন — লাইনের নিচে নেমে তলা ঘুরে ডান দিকে শেষ করুন।","en":"Swing a big round belly to the left, going below the line, and curve round the bottom to finish toward the right."},{"bn":"সবশেষে টুপির ওপরে একটি বিন্দু।","en":"Last, one dot above the cap."}]},{"type":"tip","kind":"memory","bn":"**জীম জাম গিলেছে** — তাই বিন্দু পেটের ভেতরে! **খা মাথায় খোঁপা বেঁধেছে** — বিন্দু মাথার ওপরে। আর **হা খালি পেটে হাঁপাচ্ছে** — কোনো বিন্দু নেই।","en":"**Jeem swallowed a jam-berry** — so the dot is in its belly! **Khaa wears a bun on its head** — dot on top. And **Ḥaa pants on an empty stomach** — no dot at all.","title":{"bn":"তিন ভাইয়ের গল্প","en":"Story of three brothers"}},{"type":"tip","kind":"tip","bn":"পেট যেন চ্যাপ্টা বা কোণাচে না হয় — বড় অক্ষর 'C'-এর মতো গোল রাখুন, আর লাইনের নিচে প্রায় অর্ধেক আলিফ নামান।","en":"Don't let the belly go flat or pointy — keep it round like a capital 'C', dropping about half an alif below the line."},{"type":"write","level":"letter","items":["ج","ح","خ"],"note":{"bn":"টুপি থেকে পেট পর্যন্ত কলম না তুলে এক টানে লিখুন।","en":"Write from cap to belly in one stroke without lifting the pen."}},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমার বিন্দু সঠিক সংখ্যায় ও সঠিক জায়গায় আছে","en":"My dots are the right number and in the right place"},{"bn":"আমার পেট গোল, চ্যাপ্টা নয়","en":"My bellies are round, not flat"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{ج ح خ}}-এর শরীরকে আমরা কোন চাল বলি?","en":"Which move is the body of {{ج ح خ}}?"},"options":[{"bn":"বড়শি","en":"Hook"},{"bn":"দাঁত","en":"Teeth"},{"bn":"নৌকা","en":"Cup"}],"answer":0},{"q":{"bn":"কোন অক্ষরের বিন্দু পেটের ভেতরে?","en":"Which letter has its dot inside the belly?"},"options":["خ","ح","ج"],"answer":2},{"q":{"bn":"কোন অক্ষরে কোনো বিন্দু নেই?","en":"Which letter has no dot?"},"options":["ح","ج","خ"],"answer":0},{"q":{"bn":"এই অক্ষরগুলো লেখা শুরু হয় কোথা থেকে?","en":"Where do these letters start?"},"options":[{"bn":"পেটের তলা থেকে","en":"From the bottom of the belly"},{"bn":"ওপরে টুপি থেকে","en":"From the cap on top"},{"bn":"বিন্দু থেকে","en":"From the dot"}],"answer":1},{"q":{"bn":"পেট কোথায় থাকে?","en":"Where does the belly go?"},"options":[{"bn":"লাইনের নিচে নেমে যায়","en":"It drops below the line"},{"bn":"পুরোটা লাইনের ওপরে","en":"Entirely above the line"},{"bn":"আলিফের মাথার কাছে","en":"Up near the top of alif"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-dal-ra","icon":"در","title":{"bn":"দাল, রা ও ওয়াও পরিবার","en":"The Daal, Raa and Waaw Family"},"subtitle":{"bn":"د ذ ر ز و — কোণ, লেজ আর ছোট্ট গোল মাথা","en":"د ذ ر ز و — a corner, a tail and a little round head"},"minutes":12,"goals":[{"bn":"{{د}} আর {{ر}}-এর আকৃতির পার্থক্য","en":"The difference in shape between {{د}} and {{ر}}"},{"bn":"লেজ সুন্দরভাবে সরু করে শেষ করা","en":"Finish a tail neatly and thin"},{"bn":"{{و}}-এর গোল মাথা ও লেজ লেখা","en":"Write the round head and tail of {{و}}"}],"blocks":[{"type":"text","bn":"এই পাঁচটি অক্ষর ছোট আর সহজ, কিন্তু সাবধান: {{د}} লাইনের ওপরে বসে থাকে, আর {{ر}} ও {{و}} লাইনের নিচে পিছলে নামে। একটা কোণাচে, অন্যটা গোলগাল।","en":"These five letters are small and easy, but careful: {{د}} sits on the line, while {{ر}} and {{و}} slide down below it. One is angular, the other is rounded."},{"type":"letters","items":["dal","dhal","ra","zay","waw"]},{"type":"howto","letter":"د","steps":[{"bn":"ওপরে ছোট্ট মাথা দিয়ে শুরু করুন — উচ্চতা আলিফের প্রায় অর্ধেক।","en":"Start with a small head at the top — about half an alif high."},{"bn":"তেরছাভাবে নিচে ডান দিকে নেমে লাইন ছুঁয়ে দিন।","en":"Slant down to the right until you touch the line."},{"bn":"কোণ করে লাইনের ওপর দিয়ে বাঁ দিকে ছোট্ট একটা পা টানুন।","en":"Make a corner and draw a short foot to the left along the line."}],"tip":{"bn":"{{د}} লাইনের ওপরেই বসে থাকে — নিচে নামে না।","en":"{{د}} stays sitting on the line — it never drops below."}},{"type":"howto","letter":"ذ","steps":[{"bn":"{{د}}-এর মতো ওপর থেকে তেরছা নামুন।","en":"Slant down from the top just like {{د}}."},{"bn":"কোণ করে বাঁ দিকে ছোট্ট পা টানুন।","en":"Make a corner and draw the short foot to the left."},{"bn":"সবশেষে মাথার ওপরে একটি বিন্দু।","en":"Last, one dot above the head."}]},{"type":"howto","letter":"ر","steps":[{"bn":"লাইনের একটু ওপর থেকে শুরু করুন।","en":"Start a little above the line."},{"bn":"গোল বাঁক নিয়ে লাইন পার হয়ে নিচে নামুন।","en":"Curve down through the line."},{"bn":"বাঁ দিকে স্লিপারের মতো পিছলে যান, কলম আলতো তুলে লেজ সরু করুন।","en":"Slide away to the left like a slide, lifting the pen gently so the tail ends thin."}],"tip":{"bn":"{{ر}} হলো খেলার মাঠের স্লিপার — ওপর থেকে নিচে বাঁ দিকে পিছলে যায়!","en":"{{ر}} is a playground slide — it slips down and away to the left!"}},{"type":"howto","letter":"ز","steps":[{"bn":"{{ر}}-এর মতো লাইনের একটু ওপর থেকে শুরু করুন।","en":"Start a little above the line, like {{ر}}."},{"bn":"লাইন পার হয়ে বাঁ দিকে পিছলে সরু লেজ টানুন।","en":"Curve through the line and slide left into a thin tail."},{"bn":"সবশেষে মাথার ওপরে একটি বিন্দু।","en":"Last, one dot above the head."}]},{"type":"howto","letter":"و","steps":[{"bn":"লাইনের ঠিক ওপরে, মাথার ডান পাশ থেকে শুরু করুন।","en":"Start just above the line, on the right side of the head."},{"bn":"ওপরে উঠে বাঁ দিকে ঘুরে নিচে নামুন, আবার শুরুর জায়গায় ফিরে ছোট্ট গোল মাথা বন্ধ করুন।","en":"Go up, round to the left, down and back to the start to close a small round head."},{"bn":"না থেমে {{ر}}-এর মতো লেজ টেনে লাইনের নিচে বাঁ দিকে নামুন।","en":"Without stopping, pull a {{ر}}-like tail down and to the left below the line."}],"tip":{"bn":"{{و}} = গোল মাথা + {{ر}}-এর লেজ। যেন একটা ছোট্ট ব্যাঙাচি!","en":"{{و}} = a round head + the tail of {{ر}}. Like a little tadpole!"}},{"type":"compare","items":[{"ar":"د","label":{"bn":"দাল","en":"Daal"},"desc":{"bn":"কোণাচে, লাইনের ওপরে বসে থাকে","en":"Angular, sits on the line"}},{"ar":"ر","label":{"bn":"রা","en":"Raa"},"desc":{"bn":"গোলগাল, লাইনের নিচে পিছলে নামে","en":"Rounded, slides below the line"}}]},{"type":"tip","kind":"memory","bn":"**দাল বসে, রা পিছলায়।** {{د}} চেয়ারে বসা মানুষের মতো — হাঁটু ভাঁজ করে লাইনের ওপর। {{ر}} স্লিপারে পিছলে যাওয়া শিশুর মতো — লাইনের নিচে!","en":"**Dal sits, Ra slides.** {{د}} is like someone sitting on a chair — knees bent, on the line. {{ر}} is like a child on a slide — down below the line!","title":{"bn":"দাল বসে, রা পিছলায়","en":"Dal sits, Ra slides"}},{"type":"write","level":"letter","items":["د","ذ","ر","ز","و"]},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমার বিন্দু সঠিক সংখ্যায় ও সঠিক জায়গায় আছে","en":"My dots are the right number and in the right place"},{"bn":"আমার {{د}} লাইনের ওপরে, {{ر}}-এর লেজ লাইনের নিচে","en":"My {{د}} sits on the line; my {{ر}} tail goes below it"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"কোন অক্ষর লাইনের নিচে নামে না?","en":"Which letter does NOT go below the line?"},"options":["ر","د","و"],"answer":1},{"q":{"bn":"{{و}} কোন দুটি চাল দিয়ে তৈরি?","en":"Which two moves make {{و}}?"},"options":[{"bn":"গোল মাথা + লেজ","en":"Loop + tail"},{"bn":"নৌকা + বিন্দু","en":"Cup + dot"},{"bn":"দাঁত + বাটি","en":"Teeth + bowl"}],"answer":0},{"q":{"bn":"{{ر}}-এর লেজ কোন দিকে যায়?","en":"Which way does the tail of {{ر}} go?"},"options":[{"bn":"ওপরে ডানে","en":"Up to the right"},{"bn":"নিচে বাঁ দিকে","en":"Down to the left"},{"bn":"সোজা ওপরে","en":"Straight up"}],"answer":1},{"q":{"bn":"{{ذ}} আর {{د}}-এর পার্থক্য কী?","en":"What is the difference between {{ذ}} and {{د}}?"},"options":[{"bn":"{{ذ}}-এর ওপরে একটি বিন্দু","en":"{{ذ}} has one dot on top"},{"bn":"{{ذ}} বেশি লম্বা","en":"{{ذ}} is taller"},{"bn":"{{ذ}}-এর লেজ আছে","en":"{{ذ}} has a tail"}],"answer":0},{"q":{"bn":"লেজ সুন্দরভাবে শেষ করতে কী করবেন?","en":"How do you finish a tail neatly?"},"options":[{"bn":"জোরে চাপ দিয়ে থামবেন","en":"Press hard and stop"},{"bn":"কলম আলতো তুলে সরু করবেন","en":"Lift the pen gently so it ends thin"},{"bn":"লেজের শেষে বিন্দু দেবেন","en":"Add a dot at the end"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-sin-sad","icon":"س","title":{"bn":"দাঁত ও ডিম পরিবার: সীন, শীন, সোয়াদ, দোয়াদ","en":"The Teeth and Egg Family: Seen, Sheen, Ṣaad, Ḍaad"},"subtitle":{"bn":"س ش ص ض — তিনটি দাঁত, ডিমের মতো গোল আর গভীর বাটি","en":"س ش ص ض — three teeth, an egg-shaped loop and a deep bowl"},"minutes":15,"goals":[{"bn":"সমান মাপের তিনটি দাঁত লেখা","en":"Write three evenly sized teeth"},{"bn":"{{ص}}-এর ডিম-আকৃতির গোল ও ছোট্ট দাঁত লেখা","en":"Write the egg loop and little tooth of {{ص}}"},{"bn":"চার অক্ষরেরই একই বাটি","en":"The same bowl shared by all four letters"}],"blocks":[{"type":"text","bn":"এই পরিবারের সবার পেছনে একই গভীর বাটি — লাইনের নিচে, ঠিক {{ن}}-এর মতো। সামনের অংশ আলাদা: {{س ش}}-এর তিনটি ছোট দাঁত, আর {{ص ض}}-এর ডিমের মতো গোল ও একটা ছোট্ট দাঁত।","en":"Every letter in this family ends with the same deep bowl below the line, just like {{ن}}. The front part differs: three little teeth for {{س ش}}, and an egg-shaped loop plus one tiny tooth for {{ص ض}}."},{"type":"letters","items":["sin","shin","sad","dad"]},{"type":"howto","letter":"س","steps":[{"bn":"ডান দিকে, লাইনের ঠিক ওপর থেকে শুরু করে বাঁ দিকে ছোট্ট তিনটি দাঁত টানুন — ওঠা-নামা, ওঠা-নামা, ওঠা-নামা।","en":"Start on the right just above the line and draw three small teeth to the left — up-down, up-down, up-down."},{"bn":"তৃতীয় দাঁতের পর নিচে নেমে লাইনের নিচে গোল বাটি আঁকুন ({{ن}}-এর মতো)।","en":"After the third tooth, dip down into a round bowl below the line (like {{ن}})."},{"bn":"বাঁ দিকে উঠে কলম তুলুন।","en":"Come up on the left and lift the pen."}],"tip":{"bn":"তিনটি দাঁত সমান ছোট — কোনোটা যেন আলিফের মতো লম্বা না হয়!","en":"Keep all three teeth equally small — none should grow as tall as alif!"}},{"type":"howto","letter":"ش","steps":[{"bn":"ডান দিকে, লাইনের ঠিক ওপর থেকে শুরু করে বাঁ দিকে ছোট্ট তিনটি দাঁত টানুন — ওঠা-নামা, ওঠা-নামা, ওঠা-নামা।","en":"Start on the right just above the line and draw three small teeth to the left — up-down, up-down, up-down."},{"bn":"তৃতীয় দাঁতের পর নিচে নেমে লাইনের নিচে গোল বাটি আঁকুন ({{ن}}-এর মতো)।","en":"After the third tooth, dip down into a round bowl below the line (like {{ن}})."},{"bn":"বাঁ দিকে উঠে কলম তুলুন।","en":"Come up on the left and lift the pen."},{"bn":"সবশেষে দাঁতের ওপরে তিনটি বিন্দু: নিচে দুটি, ওপরে একটি।","en":"Last, three dots over the teeth: two below, one on top."}]},{"type":"howto","letter":"ص","steps":[{"bn":"লাইনের ওপর, ডিমের বাঁ পাশ থেকে শুরু করে ডান দিকে উঠে ডিম-আকৃতির গোলের মাথা আঁকুন।","en":"Start on the line at the left side of the loop; rise up and to the right, drawing the top of an egg-shaped loop."},{"bn":"ডান মাথায় ঘুরে লাইনের ওপর দিয়ে বাঁ দিকে ফিরে গোলটা বন্ধ করুন।","en":"Curve round the right end and come back left along the line to close the loop."},{"bn":"একটা ছোট্ট দাঁত টানুন।","en":"Draw one small tooth."},{"bn":"নিচে নেমে লাইনের নিচে গোল বাটি আঁকুন, বাঁ দিকে উঠে শেষ করুন।","en":"Dip into a round bowl below the line and come up on the left."}],"tip":{"bn":"ডিমটা চ্যাপ্টা ও লম্বাটে — লাইনের ওপর শুয়ে থাকা ডিম।","en":"The loop is flat and long — an egg lying on the line."}},{"type":"howto","letter":"ض","steps":[{"bn":"লাইনের ওপর, ডিমের বাঁ পাশ থেকে শুরু করে ডান দিকে উঠে ডিম-আকৃতির গোলের মাথা আঁকুন।","en":"Start on the line at the left side of the loop; rise up and to the right, drawing the top of an egg-shaped loop."},{"bn":"ডান মাথায় ঘুরে লাইনের ওপর দিয়ে বাঁ দিকে ফিরে গোলটা বন্ধ করুন।","en":"Curve round the right end and come back left along the line to close the loop."},{"bn":"একটা ছোট্ট দাঁত টানুন।","en":"Draw one small tooth."},{"bn":"নিচে নেমে লাইনের নিচে গোল বাটি আঁকুন।","en":"Dip into a round bowl below the line."},{"bn":"সবশেষে ডিমের ওপরে একটি বিন্দু।","en":"Last, one dot above the loop."}]},{"type":"tip","kind":"memory","bn":"**সীনের তিন দাঁত** — হাসলে যেমন দাঁত দেখা যায়! শীন সেই হাসিমুখে তিনটি তারা পরেছে। আর সোয়াদ একটা ডিম পেড়ে পাশে বসে আছে।","en":"**Seen has three teeth** — like a smile showing teeth! Sheen wears three stars over that smile. And Ṣaad has laid an egg and sits beside it.","title":{"bn":"দাঁত আর ডিম","en":"Teeth and egg"}},{"type":"tip","kind":"warn","bn":"{{ص}}-এর ডিমের পরের ছোট্ট দাঁতটা ভুলবেন না — এটা না দিলে অক্ষরটা অসম্পূর্ণ দেখায়।","en":"Don't forget the tiny tooth after the egg of {{ص}} — without it the letter looks unfinished."},{"type":"write","level":"letter","items":["س","ش","ص","ض"]},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমার তিনটি দাঁত সমান ছোট","en":"My three teeth are equally small"},{"bn":"আমার {{ص}}-এর ডিমের পরে ছোট্ট দাঁত আছে","en":"My {{ص}} has its little tooth after the egg"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{س}}-এর কয়টি দাঁত?","en":"How many teeth does {{س}} have?"},"options":[{"bn":"২","en":"2"},{"bn":"৩","en":"3"},{"bn":"৪","en":"4"}],"answer":1},{"q":{"bn":"এই চার অক্ষরের শেষ অংশ কেমন?","en":"What is the last part of these four letters?"},"options":[{"bn":"লাইনের নিচে গোল বাটি","en":"A round bowl below the line"},{"bn":"লাইনের ওপরে চ্যাপ্টা নৌকা","en":"A flat boat on the line"},{"bn":"দাঁড়ানো লাইন","en":"A standing line"}],"answer":0},{"q":{"bn":"{{ش}}-এর বিন্দু কয়টি ও কোথায়?","en":"How many dots does {{ش}} have, and where?"},"options":[{"bn":"একটি, নিচে","en":"One, below"},{"bn":"তিনটি, ওপরে","en":"Three, above"},{"bn":"দুটি, ওপরে","en":"Two, above"}],"answer":1},{"q":{"bn":"{{ص}}-এর ডিম লেখার পরে কী আসে?","en":"What comes right after the egg of {{ص}}?"},"options":[{"bn":"বিন্দু","en":"A dot"},{"bn":"একটি ছোট্ট দাঁত","en":"One small tooth"},{"bn":"তিনটি দাঁত","en":"Three teeth"}],"answer":1},{"q":{"bn":"কোন অক্ষরের ডিমের ওপরে বিন্দু আছে?","en":"Which letter has a dot above its egg?"},"options":["ص","ض","س"],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-ta-ain","icon":"طع","title":{"bn":"ত্বোয়া ও আইন পরিবার","en":"The Ṭaa and 'Ayn Family"},"subtitle":{"bn":"ط ظ ع غ — ডিমের ওপর খুঁটি, আর ছোট মুখের বড় পেট","en":"ط ظ ع غ — a pole on an egg, and a small mouth with a big belly"},"minutes":12,"goals":[{"bn":"{{ط ظ}}-এ দুই টানে লেখা: আগে ডিম, পরে খুঁটি","en":"Write {{ط ظ}} in two strokes: egg first, then the pole"},{"bn":"{{ع غ}}-এর ছোট মুখ আর বড় পেট লেখা","en":"Write the small mouth and big belly of {{ع غ}}"},{"bn":"কোন অক্ষরে কলম তুলতে হয়","en":"Which letters need a pen lift"}],"blocks":[{"type":"text","bn":"{{ط}} দেখতে লাইনের ওপর শোয়ানো ডিম, যার ওপর একটা লম্বা খুঁটি পোঁতা। আর {{ع}}-এর মাথায় ছোট্ট একটা খোলা মুখ, নিচে {{ح}}-এর মতো বড় গোল পেট।","en":"{{ط}} looks like an egg lying on the line with a tall pole planted on it. {{ع}} has a small open mouth on top and a big round belly below, like {{ح}}."},{"type":"letters","items":["tta","zza","ain","ghain"]},{"type":"howto","letter":"ط","steps":[{"bn":"লাইনের ওপর, ডিমের বাঁ পাশ থেকে শুরু করে ডান দিকে উঠে ডিম-আকৃতির গোলের মাথা আঁকুন।","en":"Start on the line at the left side of the loop; rise up and to the right, drawing the top of an egg-shaped loop."},{"bn":"ডান মাথায় ঘুরে লাইনের ওপর দিয়ে বাঁ দিকে ফিরুন, গোল বন্ধ করে একটু বাঁয়ে এগিয়ে থামুন।","en":"Curve round the right end and come back left along the line, closing the loop and running a little past it."},{"bn":"কলম তুলুন। আলিফের উচ্চতা থেকে ওপর থেকে নিচে খুঁটি টেনে ডিমের বাঁ অংশে লাগান।","en":"Lift the pen. From alif height, draw the pole top-down to meet the left part of the egg."}],"tip":{"bn":"খুঁটি সবসময় ডিমের পরে — আগে মাটি, তারপর খুঁটি পোঁতা!","en":"The pole always comes after the egg — first the ground, then plant the pole!"}},{"type":"howto","letter":"ظ","steps":[{"bn":"লাইনের ওপর, ডিমের বাঁ পাশ থেকে শুরু করে ডান দিকে উঠে ডিম-আকৃতির গোলের মাথা আঁকুন।","en":"Start on the line at the left side of the loop; rise up and to the right, drawing the top of an egg-shaped loop."},{"bn":"ঘুরে বাঁ দিকে ফিরে গোল বন্ধ করুন, একটু বাঁয়ে এগিয়ে থামুন।","en":"Curve round and come back left to close the loop, running a little past it."},{"bn":"কলম তুলে ওপর থেকে খুঁটি টানুন।","en":"Lift the pen and draw the pole from the top down."},{"bn":"সবশেষে খুঁটির ডান পাশে, ডিমের ওপরে একটি বিন্দু।","en":"Last, one dot to the right of the pole, above the egg."}]},{"type":"howto","letter":"ع","steps":[{"bn":"ওপরে ডান দিক থেকে শুরু করে বাঁয়ে ঘুরে আবার ডানে ফিরে ছোট্ট খোলা মুখ ('c'-এর মতো) আঁকুন।","en":"Start at the top right, curve left and back right to draw a small open mouth (like a 'c')."},{"bn":"মুখের নিচ থেকে না থেমে বাঁ দিকে নেমে লাইনের নিচে বড় গোল পেট টানুন।","en":"From the bottom of the mouth, without stopping, sweep left and down into a big round belly below the line."},{"bn":"তলা ঘুরে ডান দিকে শেষ করুন — ঠিক {{ح}}-এর পেটের মতো।","en":"Curve round the bottom and finish toward the right — just like the belly of {{ح}}."}],"tip":{"bn":"মুখটা ছোট, পেটটা বড় — মাথা যেন পেটের চেয়ে বড় না হয়।","en":"Small mouth, big belly — never let the head grow bigger than the belly."}},{"type":"howto","letter":"غ","steps":[{"bn":"ওপরে ডান দিক থেকে ছোট্ট খোলা মুখ আঁকুন।","en":"Start at the top right and draw the small open mouth."},{"bn":"নিচে নেমে লাইনের নিচে বড় গোল পেট টানুন, ডান দিকে শেষ করুন।","en":"Sweep down into a big round belly below the line, finishing toward the right."},{"bn":"সবশেষে মুখের ওপরে একটি বিন্দু।","en":"Last, one dot above the mouth."}]},{"type":"tip","kind":"memory","bn":"**ত্বোয়া = ডিমের ওপর পতাকার খুঁটি।** খুঁটির পাশে একটি বিন্দু থাকলে সেটা **যোয়া** — যেন পতাকার পাশে একটা পাখি বসেছে।","en":"**Ṭaa = a flagpole planted on an egg.** Add a dot beside the pole and it's **Ẓaa** — like a bird perched next to the flag.","title":{"bn":"পতাকার খুঁটি","en":"The flagpole"}},{"type":"tip","kind":"fun","bn":"হামযা ({{ء}}) দেখতে আইনের ছোট্ট মাথার মতো — অনেকে বলেন, হামযার চিহ্নটা আইনের মাথা থেকেই এসেছে।","en":"Hamza ({{ء}}) looks like the small head of 'ayn — many say the hamza sign was originally taken from the head of 'ayn."},{"type":"write","level":"letter","items":["ط","ظ","ع","غ"]},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমি {{ط}}-এর খুঁটি ডিমের পরে, ওপর থেকে নিচে টেনেছি","en":"I drew the pole of {{ط}} after the egg, from the top down"},{"bn":"আমার {{ع}}-এর মুখ ছোট, পেট বড় ও গোল","en":"My {{ع}} has a small mouth and a big round belly"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{ط}} লিখতে কোন অংশ আগে?","en":"Which part of {{ط}} comes first?"},"options":[{"bn":"খুঁটি","en":"The pole"},{"bn":"ডিম","en":"The egg"},{"bn":"বিন্দু","en":"The dot"}],"answer":1},{"q":{"bn":"{{ط}}-এর খুঁটি কোন দিকে টানা হয়?","en":"Which way is the pole of {{ط}} drawn?"},"options":[{"bn":"ওপর থেকে নিচে","en":"Top to bottom"},{"bn":"নিচ থেকে ওপরে","en":"Bottom to top"},{"bn":"বাম থেকে ডানে","en":"Left to right"}],"answer":0},{"q":{"bn":"{{ع}}-এর পেট কোন অক্ষরের পেটের মতো?","en":"The belly of {{ع}} is like the belly of which letter?"},"options":["ح","ن","ب"],"answer":0},{"q":{"bn":"কোন অক্ষরের মুখের ওপরে বিন্দু?","en":"Which letter has a dot above its mouth?"},"options":["ع","غ","ط"],"answer":1},{"q":{"bn":"{{ظ}}-এর বিন্দু কোথায়?","en":"Where is the dot of {{ظ}}?"},"options":[{"bn":"খুঁটির ডান পাশে, ডিমের ওপরে","en":"Right of the pole, above the egg"},{"bn":"ডিমের নিচে","en":"Under the egg"},{"bn":"খুঁটির মাথায়","en":"On top of the pole"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-fa-lam","icon":"فك","title":{"bn":"ফা, ক্বাফ, কাফ ও লাম","en":"Faa, Qaaf, Kaaf and Laam"},"subtitle":{"bn":"ف ق ك ل — গোল মাথা, লম্বা খুঁটি আর গভীর বাটি","en":"ف ق ك ل — round heads, tall poles and deep bowls"},"minutes":15,"goals":[{"bn":"{{ف}} আর {{ق}}-এর পার্থক্য: নৌকা না বাটি","en":"Tell {{ف}} from {{ق}}: boat or bowl"},{"bn":"লম্বা অক্ষর {{ك ل}} আলিফের উচ্চতায় লেখা","en":"Write the tall letters {{ك ل}} at alif height"},{"bn":"{{ك}}-এর ভেতরের ছোট চিহ্ন যোগ করা","en":"Add the small mark inside {{ك}}"}],"blocks":[{"type":"text","bn":"{{ف}} আর {{ق}} যেন যমজ — দুজনেরই ছোট্ট গোল মাথা। কিন্তু {{ف}}-এর শরীর লাইনের ওপর লম্বা নৌকা, আর {{ق}}-এর শরীর লাইনের নিচে গভীর বাটি। {{ك}} আর {{ل}} দুজনই আলিফের মতো লম্বা।","en":"{{ف}} and {{ق}} are like twins — both have a small round head. But {{ف}}'s body is a long boat on the line, while {{ق}}'s body is a deep bowl below the line. {{ك}} and {{ل}} are both as tall as alif."},{"type":"letters","items":["fa","qaf","kaf","lam"]},{"type":"howto","letter":"ف","steps":[{"bn":"লাইন থেকে শুরু করে ওপরে উঠে ডান দিকে ঘুরে ছোট্ট গোল মাথা আঁকুন।","en":"Start on the line, go up and round to the right to make a small round head."},{"bn":"লাইনে নেমে বাঁ দিকে লম্বা, চ্যাপ্টা নৌকা টানুন।","en":"Come down to the line and draw a long, flat boat to the left."},{"bn":"বাঁ মাথায় সামান্য ওপরে বাঁক নিন।","en":"Curve up a little at the left end."},{"bn":"সবশেষে মাথার ওপরে একটি বিন্দু।","en":"Last, one dot above the head."}]},{"type":"howto","letter":"ق","steps":[{"bn":"{{ف}}-এর মতো ছোট্ট গোল মাথা আঁকুন।","en":"Draw a small round head, just like {{ف}}."},{"bn":"মাথা থেকে নেমে লাইনের নিচে গভীর গোল বাটি টানুন।","en":"From the head, drop into a deep round bowl below the line."},{"bn":"বাঁ দিকে উঠে শেষ করুন।","en":"Come up on the left to finish."},{"bn":"সবশেষে মাথার ওপরে দুটি বিন্দু।","en":"Last, two dots above the head."}]},{"type":"howto","letter":"ك","steps":[{"bn":"আলিফের উচ্চতায় ওপর থেকে শুরু করে সোজা নিচে লাইন পর্যন্ত নামুন।","en":"Start at alif height and pull straight down to the line."},{"bn":"না থেমে কোণ করে লাইনের ওপর দিয়ে বাঁ দিকে চ্যাপ্টা ভিত টানুন, শেষে সামান্য ওপরে তুলুন।","en":"Without stopping, turn and draw a flat base to the left along the line, lifting slightly at the end."},{"bn":"সবশেষে ভিতের ওপরে, ভেতরে ছোট্ট আঁকাবাঁকা চিহ্নটি দিন (ছোট্ট {{ء}}-এর মতো)।","en":"Last, add the small zigzag mark inside, above the base (like a tiny {{ء}})."}],"tip":{"bn":"শব্দের শুরুতে ও মাঝে {{كـ}}-এর মাথায় তেরছা টান থাকে, তখন ভেতরের চিহ্ন লাগে না।","en":"At the start and middle of a word, {{كـ}} has a slanted stroke on top instead, and needs no inner mark."}},{"type":"howto","letter":"ل","steps":[{"bn":"আলিফের উচ্চতায় ওপর থেকে শুরু করে সোজা নিচে নামুন।","en":"Start at alif height and pull straight down."},{"bn":"লাইনে পৌঁছে গোল হয়ে লাইনের নিচে বাটিতে নামুন।","en":"As you reach the line, curve into a round bowl below it."},{"bn":"বাঁ দিকে উঠে সরু করে শেষ করুন।","en":"Come up on the left and finish thin."}],"tip":{"bn":"{{ل}} = আলিফ + {{ن}}-এর বাটি। যেন একটা হকি স্টিক!","en":"{{ل}} = alif + the bowl of {{ن}}. Like a hockey stick!"}},{"type":"compare","items":[{"ar":"ف","label":{"bn":"ফা","en":"Faa"},"desc":{"bn":"লাইনের ওপরে নৌকা, ১ বিন্দু","en":"Boat on the line, 1 dot"}},{"ar":"ق","label":{"bn":"ক্বাফ","en":"Qaaf"},"desc":{"bn":"লাইনের নিচে বাটি, ২ বিন্দু","en":"Bowl below the line, 2 dots"}}]},{"type":"tip","kind":"memory","bn":"**ফা ভাসে, ক্বাফ ডোবে।** {{ف}}-এর একটা বিন্দু, সে হালকা — তাই লাইনের ওপর নৌকায় ভাসে। {{ق}}-এর দুটি বিন্দু, সে ভারী — তাই বাটিতে করে লাইনের নিচে ডুবে যায়!","en":"**Faa floats, Qaaf sinks.** {{ف}} has one dot, so it's light and floats in a boat on the line. {{ق}} has two dots, so it's heavy and sinks below the line in a bowl!","title":{"bn":"ফা ভাসে, ক্বাফ ডোবে","en":"Faa floats, Qaaf sinks"}},{"type":"tip","kind":"fun","bn":"উত্তর আফ্রিকার মাগরিবি লিপিতে {{ف}}-এর বিন্দু নিচে আর {{ق}}-এর একটি বিন্দু ওপরে দেওয়া হয়! আমরা এখানে পরিচিত নাসখ নিয়ম মানব।","en":"In the Maghribi script of North Africa, {{ف}} takes its dot below and {{ق}} takes just one dot above! Here we follow the familiar Naskh rule."},{"type":"write","level":"letter","items":["ف","ق","ك","ل"]},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"},{"bn":"আমার {{ف}} লাইনের ওপরে, {{ق}} লাইনের নিচে","en":"My {{ف}} sits on the line and my {{ق}} dips below it"},{"bn":"আমার {{ك}} ও {{ل}} আলিফের সমান উঁচু","en":"My {{ك}} and {{ل}} are as tall as alif"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{ف}} আর {{ق}}-এর শরীরের পার্থক্য কী?","en":"How do the bodies of {{ف}} and {{ق}} differ?"},"options":[{"bn":"{{ف}} নৌকা, {{ق}} বাটি","en":"{{ف}} is a boat, {{ق}} is a bowl"},{"bn":"{{ف}} বাটি, {{ق}} নৌকা","en":"{{ف}} is a bowl, {{ق}} is a boat"},{"bn":"কোনো পার্থক্য নেই","en":"No difference"}],"answer":0},{"q":{"bn":"{{ق}}-এর বিন্দু কয়টি?","en":"How many dots does {{ق}} have?"},"options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":1},{"q":{"bn":"{{ل}} কোন দুটি অংশে তৈরি?","en":"Which two parts make {{ل}}?"},"options":[{"bn":"আলিফ + বাটি","en":"Alif + bowl"},{"bn":"দাঁত + নৌকা","en":"Teeth + boat"},{"bn":"গোল মাথা + লেজ","en":"Loop + tail"}],"answer":0},{"q":{"bn":"{{ك}}-এর ভেতরের ছোট চিহ্ন কখন দেবেন?","en":"When do you add the small mark inside {{ك}}?"},"options":[{"bn":"সবার আগে","en":"First of all"},{"bn":"শরীর শেষ হলে, সবশেষে","en":"Last, after the body"},{"bn":"খুঁটির আগে","en":"Before the pole"}],"answer":1},{"q":{"bn":"কোন অক্ষর আলিফের মতো লম্বা?","en":"Which letter is as tall as alif?"},"options":["ف","ل","ق"],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-family-mim-ha","icon":"مه","title":{"bn":"মীম, হা ও হামযা","en":"Meem, Haa and Hamza"},"subtitle":{"bn":"م ه ء — ছোট্ট গোল, গোলগাল হা আর ভাসমান হামযা","en":"م ه ء — a little circle, a round haa and a floating hamza"},"minutes":12,"goals":[{"bn":"{{م}}-এর গোল মাথা ও সোজা লেজ লেখা","en":"Write the round head and straight tail of {{م}}"},{"bn":"গোলগাল {{ه}} লেখা","en":"Write the rounded {{ه}}"},{"bn":"ছোট্ট {{ء}} সঠিক মাপে লেখা","en":"Write a small {{ء}} at the right size"}],"blocks":[{"type":"text","bn":"বর্ণমালার শেষ অক্ষরগুলো! {{م}}-এর ছোট্ট গোল মাথা লাইনে বসে আর লেজ সোজা নিচে নামে। {{ه}} গোলগাল আর বন্ধ। আর {{ء}} এত ছোট যে সে লাইনে বসেই না — একটু ওপরে ভেসে থাকে।","en":"The last letters of the alphabet! {{م}} has a little round head on the line and a tail that drops straight down. {{ه}} is round and closed. And {{ء}} is so small it doesn't even sit on the line — it floats a little above it."},{"type":"letters","items":["mim","ha","hamza"]},{"type":"howto","letter":"م","steps":[{"bn":"মাথার ওপর থেকে শুরু করে ঘুরে লাইনের ওপর ছোট্ট বন্ধ গোল আঁকুন।","en":"Start at the top of the head and go round to make a small closed circle sitting on the line."},{"bn":"গোলের বাঁ পাশ থেকে একটা ছোট লেজ সোজা নিচে লাইনের নিচে নামান।","en":"From the left of the circle, drop a short tail straight down below the line."},{"bn":"মাথা ছোট রাখুন — {{ف}}-এর মাথার মতো।","en":"Keep the head small — like the head of {{ف}}."}],"tip":{"bn":"{{م}}-এর কোনো বিন্দু নেই।","en":"{{م}} has no dots."}},{"type":"howto","letter":"ه","steps":[{"bn":"ওপর থেকে শুরু করে গোল হয়ে নেমে লাইনের ওপর বসুন — ছোট্ট ডিমের মতো।","en":"Start at the top and go round, sitting on the line — like a small egg."},{"bn":"ওপরে ফিরে আসার সময় ভেতরে ছোট্ট একটা প্যাঁচ দিন।","en":"As you come back to the top, curl a small loop inside."},{"bn":"উচ্চতা আলিফের প্রায় অর্ধেক রাখুন।","en":"Keep it about half the height of alif."}],"tip":{"bn":"{{ه}}-এর ওপরে দুটি বিন্দু দিলে হয় গোল তা {{ة}} — শব্দের শেষে খুব দেখা যায়।","en":"Add two dots on top of {{ه}} and it becomes taa marbuta {{ة}} — very common at the end of words."}},{"type":"howto","letter":"ء","steps":[{"bn":"লাইনের একটু ওপরে, ছোট্ট 'c'-এর মতো বাঁক আঁকুন — আইনের মাথার অর্ধেক মাপে।","en":"A little above the line, draw a small curve like a 'c' — half the size of the head of 'ayn."},{"bn":"বাঁকের নিচ থেকে বাঁ দিকে ছোট একটা টান দিন।","en":"From the bottom of the curve, add a short stroke going out to the left."},{"bn":"ছোট রাখুন — হামযা অক্ষরের মাঝামাঝি উচ্চতায় ভাসে।","en":"Keep it small — hamza floats at mid-height."}],"tip":{"bn":"হামযা অনেক সময় চেয়ারে বসে: {{أ}} {{ؤ}} {{ئ}}। তখন আগে চেয়ার (আলিফ/ওয়াও/ইয়া), পরে হামযা।","en":"Hamza often sits on a chair: {{أ}} {{ؤ}} {{ئ}}. Then write the chair (alif/waw/yaa) first, and the hamza after."}},{"type":"tip","kind":"memory","bn":"**মীম = ললিপপ উল্টো করে ধরা!** গোল মিষ্টিটা লাইনে, কাঠিটা লাইনের নিচে।","en":"**Meem = an upside-down lollipop!** The round sweet sits on the line and the stick hangs below it.","title":{"bn":"উল্টো ললিপপ","en":"Upside-down lollipop"}},{"type":"tip","kind":"tip","bn":"ভালো খবর: আপনি এখন আরবির ২৯টি অক্ষরই লিখতে পারেন! পরের পাঠে দেখব শব্দের শুরু, মাঝে আর শেষে অক্ষরগুলো কীভাবে বদলায়।","en":"Great news: you can now write all 29 Arabic letters! In the next lesson we see how letters change at the start, middle and end of a word."},{"type":"write","level":"letter","items":["م","ه","ء","ة"]},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি অক্ষর ডান দিক থেকে শুরু করেছি","en":"I started every letter on the right"},{"bn":"আমার অক্ষর লাইনে বসেছে; লেজ শুধু যেখানে দরকার সেখানে নিচে নেমেছে","en":"My letters sit on the line; tails go below only where they should"},{"bn":"আমার {{م}}-এর মাথা বন্ধ ও ছোট","en":"My {{م}} head is closed and small"},{"bn":"আমার {{ء}} ছোট, বড় অক্ষরের মতো নয়","en":"My {{ء}} is small, not the size of a full letter"},{"bn":"আমি {{ة}}-এর দুটি বিন্দু সবশেষে দিয়েছি","en":"I added the two dots of {{ة}} last"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{م}}-এর লেজ কোন দিকে যায়?","en":"Which way does the tail of {{م}} go?"},"options":[{"bn":"সোজা নিচে, লাইনের নিচে","en":"Straight down, below the line"},{"bn":"ওপরে","en":"Up"},{"bn":"ডানে, লাইনের ওপরে","en":"Right, along the line"}],"answer":0},{"q":{"bn":"{{ه}}-এর ওপর দুটি বিন্দু দিলে কোন অক্ষর হয়?","en":"What does {{ه}} become with two dots on top?"},"options":["ة","ق","ت"],"answer":0},{"q":{"bn":"হামযা ({{ء}}) কতটা বড়?","en":"How big is hamza ({{ء}})?"},"options":[{"bn":"আলিফের সমান","en":"As tall as alif"},{"bn":"ছোট, মাঝামাঝি উচ্চতায় ভাসে","en":"Small, floating at mid-height"},{"bn":"লাইনের নিচে বড়","en":"Large, below the line"}],"answer":1},{"q":{"bn":"{{أ}} লিখতে আগে কী লিখবেন?","en":"When writing {{أ}}, what comes first?"},"options":[{"bn":"হামযা","en":"The hamza"},{"bn":"আলিফ","en":"The alif"},{"bn":"একসাথে দুটো","en":"Both at once"}],"answer":1},{"q":{"bn":"কোন অক্ষরের কোনো বিন্দু নেই?","en":"Which letter has no dots?"},"options":["م","ة","ق"],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-forms","icon":"بـ","title":{"bn":"শুরু, মাঝ আর শেষ","en":"Beginning, Middle and End"},"subtitle":{"bn":"শব্দের ভেতরে জায়গা বদলালে অক্ষরের চেহারাও বদলায়","en":"Letters change their shape depending on where they stand in a word"},"minutes":15,"goals":[{"bn":"প্রতিটি অক্ষরের ৪টি রূপ চেনা ও লেখা","en":"Recognise and write the 4 forms of a letter"},{"bn":"শুরু ও মাঝের রূপে লেজ কেন কেটে যায়","en":"Why tails disappear in start and middle forms"},{"bn":"৬টি অক্ষর যারা বাঁ দিকে জোড়া লাগে না","en":"The 6 letters that never join to the left"}],"blocks":[{"type":"text","bn":"আরবি অক্ষরেরা হাত ধরাধরি করে চলে। কেউ শব্দের শুরুতে, কেউ মাঝে, কেউ শেষে দাঁড়ায় — আর জায়গা অনুযায়ী তাদের চেহারা একটু বদলায়। ছোট্ট টান {{ـ}} দেখায় কোন দিকে হাত ধরা আছে।","en":"Arabic letters walk hand in hand. Some stand at the start of a word, some in the middle, some at the end — and their shape changes a little depending on the spot. The little line {{ـ}} shows which side is holding hands."},{"type":"table","head":[{"bn":"অক্ষর","en":"Letter"},{"bn":"একা","en":"Alone"},{"bn":"শুরু","en":"Start"},{"bn":"মাঝ","en":"Middle"},{"bn":"শেষ","en":"End"}],"rows":[[{"bn":"বা","en":"Baa"},"ب","بـ","ـبـ","ـب"],[{"bn":"জীম","en":"Jeem"},"ج","جـ","ـجـ","ـج"],[{"bn":"সীন","en":"Seen"},"س","سـ","ـسـ","ـس"],[{"bn":"আইন","en":"'Ayn"},"ع","عـ","ـعـ","ـع"],[{"bn":"ফা","en":"Faa"},"ف","فـ","ـفـ","ـف"],[{"bn":"কাফ","en":"Kaaf"},"ك","كـ","ـكـ","ـك"],[{"bn":"লাম","en":"Laam"},"ل","لـ","ـلـ","ـل"],[{"bn":"মীম","en":"Meem"},"م","مـ","ـمـ","ـم"],[{"bn":"হা","en":"Haa"},"ه","هـ","ـهـ","ـه"],[{"bn":"ইয়া","en":"Yaa"},"ي","يـ","ـيـ","ـي"]],"title":{"bn":"এক নজরে চার রূপ","en":"Four forms at a glance"}},{"type":"tip","kind":"memory","bn":"**হাত ধরলে লেজ গুটিয়ে নাও!** শুরু আর মাঝের রূপে অক্ষরেরা লেজ-বাটি গুটিয়ে ছোট হয়ে যায়, কারণ পাশের বন্ধুর হাত ধরতে হবে। লেজ বের হয় শুধু শব্দের শেষে বা একা থাকলে।","en":"**Hold hands, tuck your tail in!** In the start and middle forms, letters tuck away their tails and bowls to hold their neighbour's hand. Tails only come out at the end of a word or when a letter stands alone.","title":{"bn":"লেজ গুটিয়ে নাও","en":"Tuck your tail in"}},{"type":"tip","kind":"tip","bn":"শুরুর রূপে {{ن}} আর {{ي}} দুজনেই ছোট্ট দাঁত হয়ে যায় — ঠিক {{بـ}}-এর মতো। তখন শুধু বিন্দু দেখেই চিনবেন: {{نـ}} (ওপরে ১), {{يـ}} (নিচে ২)।","en":"In the start form, {{ن}} and {{ي}} both shrink into a little tooth — just like {{بـ}}. Then only the dots tell them apart: {{نـ}} (1 above), {{يـ}} (2 below)."},{"type":"write","level":"form","items":["بـ","ـبـ","ـب","نـ","ـنـ","ـن"],"title":{"bn":"নৌকা পরিবার","en":"Boat family"}},{"type":"write","level":"form","items":["عـ","ـعـ","ـع","جـ","ـجـ","ـج"],"note":{"bn":"মাঝের {{ـعـ}} একটা ছোট্ট ভরাট ত্রিভুজের মতো দেখায় — মুখটা বন্ধ হয়ে যায়।","en":"The middle {{ـعـ}} looks like a small filled triangle — the mouth closes up."},"title":{"bn":"আইন ও জীম","en":"'Ayn and Jeem"}},{"type":"write","level":"form","items":["هـ","ـهـ","ـه","مـ","ـمـ","ـم"],"note":{"bn":"{{ه}} সবচেয়ে বেশি চেহারা বদলায় — চারটি রূপ ধীরে ধীরে মিলিয়ে দেখুন।","en":"{{ه}} changes shape the most — compare its forms slowly."},"title":{"bn":"হা ও মীম","en":"Haa and Meem"}},{"type":"write","level":"form","items":["كـ","ـكـ","ـك","لـ","ـلـ","ـل"],"note":{"bn":"শুরু ও মাঝের {{كـ}}-এ খুঁটির ওপরে তেরছা টানটি দিন।","en":"In the start and middle {{كـ}}, add the slanted stroke on top of the pole."},"title":{"bn":"কাফ ও লাম","en":"Kaaf and Laam"}},{"type":"text","bn":"৬টি অক্ষর আছে যারা শুধু ডান দিকের বন্ধুর হাত ধরে, বাঁ দিকের কারও হাত ধরে না: {{ا د ذ ر ز و}}। এদের পরে শব্দটা একটু ফাঁক রেখে নতুন করে শুরু হয়।","en":"There are 6 letters that only hold the hand of the friend on their right, never anyone on their left: {{ا د ذ ر ز و}}. After them, the word takes a small gap and starts afresh.","title":{"bn":"৬টি লাজুক অক্ষর","en":"The 6 shy letters"}},{"type":"letters","items":["alif","dal","dhal","ra","zay","waw"]},{"type":"tip","kind":"memory","bn":"**ছয় লাজুক বন্ধু:** আলিফ, দাল, যাল, রা, যা, ওয়াও। এরা ডান হাত বাড়ায়, কিন্তু বাঁ হাত পকেটে রাখে! তাই এদের দুটিই রূপ: একা আর শেষ।","en":"**Six shy friends:** Alif, Daal, Dhaal, Raa, Zaay, Waaw. They reach out with the right hand but keep the left hand in their pocket! So they only have two forms: alone and end.","title":{"bn":"হাত পকেটে","en":"Hands in pockets"}},{"type":"write","level":"form","items":["ـا","ـد","ـر","ـو"],"title":{"bn":"লাজুক অক্ষরের শেষ রূপ","en":"End forms of the shy letters"}},{"type":"selfcheck","items":[{"bn":"আমার শুরু ও মাঝের রূপে লেজ নেই","en":"My start and middle forms have no tails"},{"bn":"আমার জোড়ার টান লাইনের ওপর দিয়ে গেছে","en":"My joining strokes run along the baseline"},{"bn":"আমি ৬টি লাজুক অক্ষরের বাঁ দিকে জোড়া দিইনি","en":"I did not join the 6 shy letters to the left"},{"bn":"আমি বিন্দু সবশেষে দিয়েছি","en":"I added the dots last"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"এটি কোন রূপ?","en":"Which form is this?"},"options":[{"bn":"শুরু","en":"Start"},{"bn":"মাঝ","en":"Middle"},{"bn":"শেষ","en":"End"}],"answer":1,"ar":"ـبـ"},{"q":{"bn":"কোন অক্ষর বাঁ দিকে জোড়া লাগে না?","en":"Which letter never joins to the left?"},"options":["ب","ر","م"],"answer":1},{"q":{"bn":"শুরুর রূপে {{ن}} দেখতে কার মতো?","en":"In its start form, {{ن}} looks like which form?"},"options":["بـ","هـ","عـ"],"answer":0},{"q":{"bn":"লাজুক অক্ষর কয়টি?","en":"How many shy (non-joining) letters are there?"},"options":[{"bn":"৪","en":"4"},{"bn":"৬","en":"6"},{"bn":"৮","en":"8"}],"answer":1},{"q":{"bn":"লেজ সাধারণত কোন রূপে দেখা যায়?","en":"In which form do tails usually appear?"},"options":[{"bn":"শুরু","en":"Start"},{"bn":"মাঝ","en":"Middle"},{"bn":"শেষ বা একা","en":"End or alone"}],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-joining","icon":"كتب","title":{"bn":"অক্ষর জুড়ে শব্দ লিখি","en":"Joining Letters into Words"},"subtitle":{"bn":"জোড়ার টান, কলম তোলা আর লাজুক অক্ষরের ফাঁক","en":"Joining strokes, pen lifts and the gaps after shy letters"},"minutes":15,"goals":[{"bn":"দুই ও তিন অক্ষরের শব্দ জুড়ে লেখা","en":"Join two- and three-letter words"},{"bn":"জোড়ার টান (কাশিদা) কতটা লম্বা হবে","en":"How long the joining stroke (kashida) should be"},{"bn":"লাজুক অক্ষরের পরে শব্দ কোথায় ভাঙে","en":"Where a word breaks after a shy letter"}],"blocks":[{"type":"text","bn":"এবার আসল মজা — অক্ষর জুড়ে সত্যিকারের শব্দ! প্রথমে হরকত ছাড়া শুধু অক্ষরের শরীর লিখব, যাতে জোড়ায় মন দিতে পারি। হরকত আসবে পরের পাঠে।","en":"Now the real fun — joining letters into real words! First we write only the letter bodies without harakat, so we can focus on the joins. Harakat come in the next lesson."},{"type":"tip","kind":"tip","bn":"অক্ষর জোড়ার টানকে বলে **কাশিদা** — মূল লাইনের ওপর দিয়ে ছোট্ট শোয়ানো লাইন। এক-দুই বিন্দুর সমান লম্বা রাখুন। বেশি লম্বা টানলে শব্দ ভেঙে গেছে মনে হয়।","en":"The joining stroke is called **kashida** — a short lying line along the baseline. Keep it about one or two dots long. Stretch it too far and the word looks broken.","title":{"bn":"জোড়ার টান","en":"The joining stroke"}},{"type":"tip","kind":"memory","bn":"**এক টানে টুকরো, শেষে বিন্দু।** শব্দের প্রতিটি জোড়া-টুকরো কলম না তুলে এক টানে লিখুন। পুরো শব্দের শরীর শেষ হলে তারপর সব বিন্দু দিন — ঠিক যেন মালা গেঁথে শেষে লকেট পরানো!","en":"**One stroke per piece, dots at the end.** Write each connected piece of the word without lifting the pen. When the whole word's body is done, then add all the dots — like threading a necklace and adding the pendant last!","title":{"bn":"মালা গাঁথা","en":"Threading the necklace"}},{"type":"write","level":"word","items":["من","في","لم"],"note":{"bn":"{{من}} = {{مـ}} + {{ـن}}। শুরুর রূপ আর শেষের রূপ জুড়ে দিন।","en":"{{من}} = {{مـ}} + {{ـن}}. Join a start form to an end form."},"title":{"bn":"দুই অক্ষরের শব্দ","en":"Two-letter words"}},{"type":"write","level":"word","items":["قلم","كتب","بيت","نور","باب"],"title":{"bn":"তিন অক্ষরের শব্দ","en":"Three-letter words"}},{"type":"table","head":[{"bn":"শব্দ","en":"Word"},{"bn":"টুকরো","en":"Pieces"},{"bn":"কেন ভাঙল?","en":"Why the break?"}],"rows":[["نور","نو  ر",{"bn":"{{و}} বাঁ দিকে জোড়া লাগে না","en":"{{و}} doesn't join to the left"}],["باب","با  ب",{"bn":"{{ا}} বাঁ দিকে জোড়া লাগে না","en":"{{ا}} doesn't join to the left"}],["كتاب","كتا  ب",{"bn":"আলিফের পরে নতুন টুকরো","en":"A new piece starts after alif"}],["دار","د  ا  ر",{"bn":"তিনটিই লাজুক — তিন টুকরো!","en":"All three are shy — three pieces!"}],["مسجد","مسجد",{"bn":"{{د}} শেষে, তাই কোনো ফাঁক নেই","en":"{{د}} is last, so no gap"}]],"title":{"bn":"শব্দ কোথায় ভাঙে?","en":"Where does the word break?"}},{"type":"tip","kind":"warn","bn":"লাজুক অক্ষরের পরের ফাঁকটা ছোট রাখুন — দুই শব্দের মাঝের ফাঁকের চেয়ে ছোট। না হলে একটা শব্দকে দুটো শব্দ মনে হবে।","en":"Keep the gap after a shy letter small — smaller than the space between two words. Otherwise one word will look like two."},{"type":"tip","kind":"tip","bn":"{{ل}}-এর পরে {{ا}} এলে দুজন মিলে বিশেষ রূপ নেয়: {{لا}}। দুটি বাহু নিচে লাইনের ওপর মিলিত হয় — একে আলাদা একটা আকৃতি হিসেবে অনুশীলন করুন।","en":"When {{ا}} comes after {{ل}}, they team up into a special shape: {{لا}}. The two arms meet at the bottom on the line — practise it as one shape of its own.","title":{"bn":"লাম-আলিফ","en":"Laam-Alif"}},{"type":"write","level":"word","items":["كتاب","مسجد","شمس","سلام","علم","جميل"],"title":{"bn":"আরও লম্বা শব্দ","en":"Longer words"}},{"type":"selfcheck","items":[{"bn":"আমার শব্দ লাইনের ওপর সোজা চলেছে","en":"My words run straight along the line"},{"bn":"আমার জোড়ার টান ছোট ও সমান","en":"My joining strokes are short and even"},{"bn":"লাজুক অক্ষরের পরে আমি ছোট ফাঁক রেখেছি","en":"I left a small gap after each shy letter"},{"bn":"আমি পুরো শব্দের পরে বিন্দু দিয়েছি","en":"I added the dots after finishing the whole word"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"অক্ষর জোড়ার টানকে কী বলে?","en":"What is the joining stroke called?"},"options":[{"bn":"কাশিদা","en":"Kashida"},{"bn":"তানবীন","en":"Tanween"},{"bn":"সুকুন","en":"Sukun"}],"answer":0},{"q":{"bn":"{{نور}} শব্দটি কয় টুকরোয় লেখা হয়?","en":"How many pieces is {{نور}} written in?"},"options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":1,"explain":{"bn":"{{و}}-এর পরে ভাঙে: {{نو}} + {{ر}}।","en":"It breaks after {{و}}: {{نو}} + {{ر}}."}},{"q":{"bn":"শব্দের বিন্দু কখন দেবেন?","en":"When do you add a word's dots?"},"options":[{"bn":"প্রতিটি অক্ষরের আগে","en":"Before each letter"},{"bn":"শব্দের শরীর শেষ হলে","en":"After the word's body is finished"},{"bn":"শুধু প্রথম অক্ষরে","en":"Only on the first letter"}],"answer":1},{"q":{"bn":"{{ل}} + {{ا}} মিলে কোন রূপ হয়?","en":"What do {{ل}} + {{ا}} make together?"},"options":["لا","ال","لل"],"answer":0},{"q":{"bn":"কোন শব্দে কোনো ফাঁক নেই?","en":"Which word has no gap?"},"options":["باب","دار","قلم"],"answer":2}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-harakat","icon":"◌َ","title":{"bn":"হরকত ও চিহ্ন যোগ করি","en":"Adding Harakat and Signs"},"subtitle":{"bn":"যবর, যের, পেশ, জযম, তাশদীদ, তানবীন — কোথায়, কত বড়, কোন ক্রমে","en":"Fatha, kasra, damma, sukun, shaddah, tanween — where, how big, in what order"},"minutes":15,"goals":[{"bn":"হরকতের সঠিক জায়গা ও মাপ","en":"The right place and size for each mark"},{"bn":"লেখার ক্রম: অক্ষর → বিন্দু → হরকত","en":"Writing order: letters → dots → harakat"},{"bn":"পূর্ণ হরকতসহ শব্দ লেখা","en":"Write fully vowelled words"}],"blocks":[{"type":"text","bn":"এবার শব্দগুলোকে কথা বলাই! হরকত ছাড়া শব্দ যেন গলা ছাড়া মানুষ। হরকত ছোট্ট চিহ্ন, কিন্তু ভুল জায়গায় বসলে অর্থ বদলে যেতে পারে — তাই যত্ন করে বসাতে হবে।","en":"Now let's make the words speak! A word without harakat is like a person without a voice. Harakat are tiny marks, but in the wrong place they can change the meaning — so place them with care."},{"type":"steps","items":[{"title":{"bn":"শরীর","en":"Body"},"desc":{"bn":"পুরো শব্দের অক্ষরগুলো জুড়ে লিখুন।","en":"Write all the joined letters of the word."}},{"title":{"bn":"বিন্দু","en":"Dots"},"desc":{"bn":"শব্দের সব বিন্দু দিন।","en":"Add every dot in the word."}},{"title":{"bn":"তাশদীদ","en":"Shaddah"},"desc":{"bn":"যেখানে তাশদীদ আছে, আগে সেটা দিন — হরকত তার সাথে বসবে।","en":"Put any shaddah first — the vowel goes with it."}},{"title":{"bn":"হরকত","en":"Harakat"},"desc":{"bn":"ডান থেকে বামে, অক্ষর ধরে ধরে যবর-যের-পেশ-জযম দিন।","en":"From right to left, add fatha, kasra, damma and sukun letter by letter."}},{"title":{"bn":"মিলিয়ে দেখা","en":"Check"},"desc":{"bn":"মডেলের সাথে মিলিয়ে নিন: প্রতিটি চিহ্ন কি ঠিক নিজের অক্ষরের ওপরে বা নিচে?","en":"Compare with the model: is every mark right above or below its own letter?"}}],"title":{"bn":"লেখার ক্রম","en":"The writing order"}},{"type":"table","head":[{"bn":"চিহ্ন","en":"Mark"},{"bn":"নাম","en":"Name"},{"bn":"কোথায়","en":"Where"},{"bn":"কীভাবে লিখবেন","en":"How to write it"}],"rows":[["بَ",{"bn":"যবর (ফাতহা)","en":"Fatha"},{"bn":"অক্ষরের ওপরে","en":"Above the letter"},{"bn":"ছোট্ট তেরছা টান, ওপরের ডান থেকে নিচে বাঁয়ে","en":"A short slanted dash, from top-right down to the left"}],["بِ",{"bn":"যের (কাসরা)","en":"Kasra"},{"bn":"অক্ষরের নিচে","en":"Below the letter"},{"bn":"যবরের মতোই তেরছা টান, নিচে","en":"The same slanted dash, underneath"}],["بُ",{"bn":"পেশ (যম্মা)","en":"Damma"},{"bn":"অক্ষরের ওপরে","en":"Above the letter"},{"bn":"ছোট্ট একটা {{و}}","en":"A tiny {{و}}"}],["بْ",{"bn":"জযম (সুকুন)","en":"Sukun"},{"bn":"অক্ষরের ওপরে","en":"Above the letter"},{"bn":"ছোট্ট গোল (অনেক মুসহাফে ছোট্ট টুপির মতো)","en":"A tiny circle (a little cap in many mushafs)"}],["بّ",{"bn":"তাশদীদ (শাদ্দাহ)","en":"Shaddah"},{"bn":"অক্ষরের ওপরে","en":"Above the letter"},{"bn":"ছোট্ট তিন দাঁত, যেন খুদে {{س}}","en":"Three tiny teeth, like a mini {{س}}"}],["بٌ",{"bn":"তানবীন","en":"Tanween"},{"bn":"ওপরে বা নিচে","en":"Above or below"},{"bn":"একই চিহ্ন দুবার: {{ـً}} {{ـٍ}} {{ـٌ}}","en":"The same mark twice: {{ـً}} {{ـٍ}} {{ـٌ}}"}]],"title":{"bn":"চিহ্নের মানচিত্র","en":"Map of the marks"}},{"type":"tip","kind":"tip","bn":"হরকত অক্ষরের চেয়ে অনেক ছোট — প্রায় দুই বিন্দুর সমান লম্বা। ঠিক নিজের অক্ষরের মাঝ বরাবর বসান, পাশের অক্ষরের দিকে সরে যেন না যায়।","en":"Harakat are much smaller than letters — about two dots long. Centre each one over or under its own letter so it doesn't drift onto the neighbour.","title":{"bn":"মাপ ও জায়গা","en":"Size and place"}},{"type":"tip","kind":"memory","bn":"**যবর-যের হলো বৃষ্টির ফোঁটা** — দুজনেই একইভাবে কাত হয়ে পড়ে, একটা ছাদে (ওপরে), একটা উঠানে (নিচে)। **পেশ হলো খুদে ওয়াও**, **জযম হলো শূন্য** (কোনো স্বর নেই), আর **তাশদীদ হলো খুদে সীন** — দ্বিগুণ জোর!","en":"**Fatha and kasra are raindrops** — both slant the same way, one lands on the roof (above), one in the yard (below). **Damma is a baby waw**, **sukun is a zero** (no vowel), and **shaddah is a mini seen** — double strength!","title":{"bn":"চিহ্ন চেনার ছড়া","en":"Marks rhyme"}},{"type":"tip","kind":"tip","bn":"যবরের তানবীনের সাথে সাধারণত শেষে একটা আলিফ লেখা হয়: {{كِتَابًا}}। আলিফটা অক্ষর হিসেবে আগে লিখুন, দুই যবর পরে।","en":"Tanween with fatha usually comes with an extra alif at the end: {{كِتَابًا}}. Write the alif as a letter first, and the double fatha afterwards."},{"type":"write","level":"word","items":["كَتَبَ","قَلَمٌ","رَبِّ","مِنْ","بَيْتٌ","نُورٌ","كِتَابًا"],"note":{"bn":"আগে শরীর, তারপর বিন্দু, শেষে হরকত — প্রতিটি শব্দে।","en":"Body, then dots, then harakat — in every word."}},{"type":"selfcheck","items":[{"bn":"আমি হরকত সবশেষে দিয়েছি","en":"I added the harakat last"},{"bn":"আমার হরকত ছোট আর ঠিক নিজের অক্ষরের ওপরে বা নিচে","en":"My harakat are small and right above or below their own letter"},{"bn":"আমি তাশদীদ আগে, তার হরকত পরে দিয়েছি","en":"I put the shaddah first and its vowel after"},{"bn":"আমার যবর আর যের একইভাবে কাত হয়েছে","en":"My fatha and kasra slant the same way"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"কোন ক্রমটি সঠিক?","en":"Which order is correct?"},"options":[{"bn":"অক্ষর → বিন্দু → হরকত","en":"Letters → dots → harakat"},{"bn":"হরকত → অক্ষর → বিন্দু","en":"Harakat → letters → dots"},{"bn":"বিন্দু → হরকত → অক্ষর","en":"Dots → harakat → letters"}],"answer":0},{"q":{"bn":"যের (কাসরা) কোথায় বসে?","en":"Where does kasra go?"},"options":[{"bn":"অক্ষরের ওপরে","en":"Above the letter"},{"bn":"অক্ষরের নিচে","en":"Below the letter"},{"bn":"অক্ষরের পাশে","en":"Beside the letter"}],"answer":1},{"q":{"bn":"পেশ (যম্মা) দেখতে কোন অক্ষরের ছোট রূপ?","en":"Damma looks like a tiny version of which letter?"},"options":["و","ر","س"],"answer":0},{"q":{"bn":"কোন শব্দে তাশদীদ আছে?","en":"Which word has a shaddah?"},"options":["رَبِّ","مِنْ","كَتَبَ"],"answer":0},{"q":{"bn":"হরকত কতটা বড় হবে?","en":"How big should harakat be?"},"options":[{"bn":"অক্ষরের সমান","en":"As big as the letters"},{"bn":"অক্ষরের চেয়ে অনেক ছোট","en":"Much smaller than the letters"},{"bn":"আলিফের সমান","en":"As tall as alif"}],"answer":1},{"q":{"bn":"{{كِتَابًا}}-এর শেষ আলিফটা কখন লিখবেন?","en":"When do you write the final alif of {{كِتَابًا}}?"},"options":[{"bn":"শরীরের সাথে, অক্ষর হিসেবে","en":"With the body, as a letter"},{"bn":"সবার শেষে, হরকতের পরে","en":"At the very end, after the harakat"},{"bn":"লিখতে হয় না","en":"It is not written"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-quran-words","icon":"نور","title":{"bn":"কুরআনের শব্দ লিখি","en":"Copying Quranic Words"},"subtitle":{"bn":"কুরআনে বারবার আসা প্রিয় শব্দগুলো পূর্ণ হরকতসহ লিখি","en":"Write the Quran's most frequent, best-loved words with full harakat"},"minutes":15,"goals":[{"bn":"কুরআনের পরিচিত শব্দ নির্ভুলভাবে লেখা","en":"Write well-known Quranic words accurately"},{"bn":"{{اللّٰه}} শব্দ ও খাড়া যবর লেখার নিয়ম","en":"How to write {{اللّٰه}} and the standing fatha"},{"bn":"গোল তা ({{ة}}) ও মাদ্দ ({{آ}}) লেখা","en":"Write taa marbuta ({{ة}}) and madda ({{آ}})"}],"blocks":[{"type":"text","bn":"এখন আপনি যা লিখবেন, তা কুরআনেই আছে! এই শব্দগুলো কুরআনে বারবার আসে। লিখতে লিখতে অর্থও শিখে নিন — তাহলে তিলাওয়াতের সময় চিনে ফেলবেন।","en":"What you write now is in the Quran itself! These words appear again and again. Learn their meanings as you write them — then you will recognise them when you recite."},{"type":"examples","items":[{"ar":"اللّٰهُ","tr":{"bn":"আল্লাহু","en":"Allāhu"},"mean":{"bn":"আল্লাহ","en":"Allah"}},{"ar":"رَبٌّ","tr":{"bn":"রাব্বুন","en":"rabbun"},"mean":{"bn":"প্রতিপালক, রব","en":"Lord, Sustainer"}},{"ar":"الرَّحْمٰنُ","tr":{"bn":"আর-রাহমানু","en":"ar-raḥmānu"},"mean":{"bn":"পরম দয়াময়","en":"The Most Merciful"}},{"ar":"الرَّحِيمُ","tr":{"bn":"আর-রাহীমু","en":"ar-raḥīmu"},"mean":{"bn":"অতি দয়ালু","en":"The Especially Merciful"}},{"ar":"الْقُرْآنُ","tr":{"bn":"আল-কুরআনু","en":"al-qur'ānu"},"mean":{"bn":"কুরআন","en":"The Quran"}},{"ar":"الْحَمْدُ","tr":{"bn":"আল-হামদু","en":"al-ḥamdu"},"mean":{"bn":"সব প্রশংসা","en":"All praise"}},{"ar":"صَلَاةٌ","tr":{"bn":"সালাতুন","en":"ṣalātun"},"mean":{"bn":"নামায, সালাত","en":"Prayer (salah)"}},{"ar":"كِتَابٌ","tr":{"bn":"কিতাবুন","en":"kitābun"},"mean":{"bn":"বই, কিতাব","en":"Book"}},{"ar":"نُورٌ","tr":{"bn":"নূরুন","en":"nūrun"},"mean":{"bn":"আলো","en":"Light"}},{"ar":"جَنَّةٌ","tr":{"bn":"জান্নাতুন","en":"jannatun"},"mean":{"bn":"বাগান, জান্নাত","en":"Garden, Paradise"}},{"ar":"سَلَامٌ","tr":{"bn":"সালামুন","en":"salāmun"},"mean":{"bn":"শান্তি","en":"Peace"}},{"ar":"عِلْمٌ","tr":{"bn":"ইলমুন","en":"'ilmun"},"mean":{"bn":"জ্ঞান","en":"Knowledge"}}],"title":{"bn":"শব্দ ও অর্থ","en":"Words and meanings"}},{"type":"tip","kind":"tip","bn":"{{اللّٰه}} লিখুন এভাবে: আলিফ, তারপর দুটি লম্বা লাম, শেষে জোড়া {{ـه}}। এরপর দ্বিতীয় লামের ওপরে তাশদীদ, আর তাশদীদের ওপরে ছোট্ট খাড়া আলিফ ({{ٰ}})।","en":"Write {{اللّٰه}} like this: alif, then two tall laams, then a joined {{ـه}} at the end. Then add a shaddah over the second laam, with a small standing alif ({{ٰ}}) on top of it.","title":{"bn":"আল্লাহ শব্দ লেখা","en":"Writing the word Allah"}},{"type":"tip","kind":"memory","bn":"**খাড়া যবর = লুকানো আলিফ।** {{الرَّحْمٰنُ}}-এ মীমের ওপরে ছোট্ট খাড়া আলিফ আছে — এটা পুরো আলিফের কাজ করে ('মা' লম্বা হয়)। তাই এখানে বড় আলিফ লিখবেন না, শুধু ছোট্টটা দিন!","en":"**Standing fatha = a hidden alif.** In {{الرَّحْمٰنُ}}, a small upright alif sits above the meem — it does the job of a full alif (the 'maa' is long). So don't write a big alif here, just the small one!","title":{"bn":"লুকানো আলিফ","en":"The hidden alif"}},{"type":"tip","kind":"tip","bn":"{{صَلَاةٌ}} আর {{جَنَّةٌ}}-এর শেষে গোল তা ({{ة}} / {{ـة}}) — {{ه}}-এর ওপরে দুটি বিন্দু। আর {{الْقُرْآنُ}}-এর {{آ}}: আগে আলিফ, তারপর ওপরে ছোট্ট ঢেউ (মাদ্দ)।","en":"{{صَلَاةٌ}} and {{جَنَّةٌ}} end in taa marbuta ({{ة}} / {{ـة}}) — a {{ه}} with two dots on top. And the {{آ}} in {{الْقُرْآنُ}}: alif first, then the small wave (madda) above it."},{"type":"write","level":"word","items":["اللّٰهُ","رَبٌّ","الرَّحْمٰنُ","الرَّحِيمُ","الْقُرْآنُ","الْحَمْدُ"],"title":{"bn":"আল্লাহর নাম ও প্রশংসা","en":"Allah's names and praise"}},{"type":"write","level":"word","items":["صَلَاةٌ","كِتَابٌ","نُورٌ","جَنَّةٌ","سَلَامٌ","عِلْمٌ"],"title":{"bn":"প্রিয় শব্দ","en":"Beloved words"}},{"type":"tip","kind":"fun","bn":"আপনি যে {{كِتَابٌ}} শব্দ লিখলেন, তার মূল {{ك ت ب}} মানে 'লেখা'। লেখা শেখার পাঠে লেখার শব্দ — চমৎকার না?","en":"The word {{كِتَابٌ}} you just wrote comes from the root {{ك ت ب}}, meaning 'to write'. A writing word in a writing lesson — lovely, isn't it?"},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি শব্দ মডেলের সাথে অক্ষর ধরে মিলিয়েছি","en":"I checked every word against the model, letter by letter"},{"bn":"আমি {{اللّٰه}}-এ তাশদীদ ও খাড়া যবর দিয়েছি","en":"I added the shaddah and standing fatha in {{اللّٰه}}"},{"bn":"আমি {{ة}}-এর দুটি বিন্দু দিয়েছি","en":"I added the two dots of {{ة}}"},{"bn":"আমি প্রতিটি শব্দের অর্থ বলতে পারি","en":"I can say the meaning of every word"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"{{نُورٌ}} মানে কী?","en":"What does {{نُورٌ}} mean?"},"options":[{"bn":"আলো","en":"Light"},{"bn":"বই","en":"Book"},{"bn":"শান্তি","en":"Peace"}],"answer":0},{"q":{"bn":"{{الرَّحْمٰنُ}}-এ মীমের ওপরের ছোট্ট আলিফকে কী বলে?","en":"What is the small alif above the meem in {{الرَّحْمٰنُ}} called?"},"options":[{"bn":"খাড়া যবর","en":"Standing fatha (dagger alif)"},{"bn":"তানবীন","en":"Tanween"},{"bn":"হামযা","en":"Hamza"}],"answer":0},{"q":{"bn":"{{جَنَّةٌ}}-এর শেষ অক্ষর কোনটি?","en":"What is the last letter of {{جَنَّةٌ}}?"},"options":[{"bn":"গোল তা ({{ة}})","en":"Taa marbuta ({{ة}})"},{"bn":"{{ت}}","en":"{{ت}}"},{"bn":"{{ن}}","en":"{{ن}}"}],"answer":0},{"q":{"bn":"{{اللّٰه}} শব্দে কয়টি লাম?","en":"How many laams are in {{اللّٰه}}?"},"options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":1},{"q":{"bn":"{{كِتَابٌ}} মানে কী?","en":"What does {{كِتَابٌ}} mean?"},"options":[{"bn":"কলম","en":"Pen"},{"bn":"বই","en":"Book"},{"bn":"ঘর","en":"House"}],"answer":1}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-ayah-copy","icon":"۝","title":{"bn":"আয়াত লিখি","en":"Copying Ayahs"},"subtitle":{"bn":"বিসমিল্লাহ, সূরা ফাতিহা ও ইখলাসের আয়াত যত্ন করে লেখা","en":"Writing Bismillah and ayahs from al-Fatihah and al-Ikhlas with care"},"minutes":20,"goals":[{"bn":"পুরো লাইন সুন্দরভাবে কপি করার পদ্ধতি","en":"A method for copying a full line neatly"},{"bn":"শব্দের মাঝে সমান ফাঁক রাখা","en":"Keep even spaces between words"},{"bn":"কুরআনের লেখার প্রতি আদব","en":"Respect when writing the Quran"}],"blocks":[{"type":"text","bn":"আজ আপনার জীবনের একটা বিশেষ দিন — আপনি নিজের হাতে কুরআনের আয়াত লিখবেন! ধীরে লিখুন, প্রতিটি শব্দ মডেলের সাথে মিলিয়ে নিন। এখানে গতি নয়, নির্ভুলতাই আসল।","en":"Today is a special day — you will write ayahs of the Quran with your own hand! Write slowly and check every word against the model. Here, accuracy matters, not speed."},{"type":"tip","kind":"tip","bn":"কুরআনের আয়াত লেখা সম্মানের কাজ। অনেক আলেম আয়াত লেখার সময় অযু অবস্থায় থাকাকে উত্তম মনে করেন — সম্ভব হলে অযু করে নিন। পরিষ্কার খাতা ব্যবহার করুন, আর লেখা পাতাটি যত্ন করে রাখুন, মেঝেতে ফেলে রাখবেন না।","en":"Writing ayahs of the Quran is an honourable act. Many scholars consider it best to be in wudu while writing them — do make wudu if you can. Use a clean notebook, and keep the written page with care, not lying on the floor.","title":{"bn":"আদব","en":"With respect"}},{"type":"steps","items":[{"title":{"bn":"পড়ুন","en":"Read"},"desc":{"bn":"আগে পুরো লাইনটা পড়ুন বা শুনুন, অর্থ জেনে নিন।","en":"First read or listen to the whole line and know its meaning."}},{"title":{"bn":"শব্দে ভাগ করুন","en":"Split into words"},"desc":{"bn":"লাইনটা শব্দে ভাগ করুন; একবারে এক শব্দ লিখবেন।","en":"Split the line into words; write one word at a time."}},{"title":{"bn":"শরীর লিখুন","en":"Write the bodies"},"desc":{"bn":"ডান থেকে বামে প্রতিটি শব্দের শরীর লিখুন, শব্দের মাঝে সমান ফাঁক রেখে।","en":"From right to left, write each word's body, leaving even gaps between words."}},{"title":{"bn":"বিন্দু ও হরকত","en":"Dots and harakat"},"desc":{"bn":"পুরো লাইনের শরীর শেষে বিন্দু, তারপর তাশদীদ ও হরকত দিন।","en":"When all the bodies are done, add the dots, then shaddah and harakat."}},{"title":{"bn":"অক্ষর ধরে মিলান","en":"Check letter by letter"},"desc":{"bn":"মডেলের সাথে প্রতিটি অক্ষর, বিন্দু আর হরকত মিলিয়ে নিন। ভুল থাকলে আলতো করে মুছে ঠিক করুন।","en":"Check every letter, dot and mark against the model. If something is wrong, erase gently and fix it."}}],"title":{"bn":"লাইন কপি করার ৫ ধাপ","en":"5 steps to copy a line"}},{"type":"write","level":"line","items":["بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","الْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ"],"reps":3,"note":{"bn":"অর্থ: পরম দয়াময়, অতি দয়ালু আল্লাহর নামে। সব প্রশংসা আল্লাহর, যিনি সমগ্র জগতের প্রতিপালক।","en":"Meaning: In the name of Allah, the Most Merciful, the Especially Merciful. All praise is for Allah, Lord of all the worlds."},"title":{"bn":"বিসমিল্লাহ ও সূরা ফাতিহা (১:২)","en":"Bismillah and al-Fatihah (1:2)"}},{"type":"write","level":"line","items":["قُلْ هُوَ اللّٰهُ أَحَدٌ","اللّٰهُ الصَّمَدُ","لَمْ يَلِدْ وَلَمْ يُولَدْ","وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ"],"reps":3,"note":{"bn":"অর্থ: বলুন, তিনিই আল্লাহ, এক। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি, তাঁকেও জন্ম দেওয়া হয়নি। আর তাঁর সমতুল্য কেউ নেই।","en":"Meaning: Say, He is Allah, the One. Allah, the Self-Sufficient. He neither begets nor was He begotten. And there is none comparable to Him."},"title":{"bn":"সূরা ইখলাস (১১২:১–৪)","en":"Surah al-Ikhlas (112:1–4)"}},{"type":"write","level":"line","items":["رَبِّ زِدْنِي عِلْمًا"],"reps":4,"note":{"bn":"অর্থ: হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন। প্রতিবার লেখার আগে এই দুআটি পড়ে নিন!","en":"Meaning: My Lord, increase me in knowledge. Say this dua each time before you start writing!"},"title":{"bn":"একটি দুআ (২০:১১৪ থেকে)","en":"A dua (from 20:114)"}},{"type":"tip","kind":"memory","bn":"**শব্দেরা যেন মালার পুঁতি** — প্রতিটি পুঁতির মাঝে সমান ফাঁক। শব্দের মাঝে প্রায় একটা ছোট অক্ষরের সমান জায়গা রাখুন, আর কখনো একটা শব্দ ভেঙে দুই লাইনে লিখবেন না।","en":"**Words are beads on a string** — the same gap between every bead. Leave about one small letter's width between words, and never split a word across two lines.","title":{"bn":"মালার পুঁতি","en":"Beads on a string"}},{"type":"tip","kind":"fun","bn":"মুসহাফে প্রতিটি আয়াতের শেষে একটা গোল চিহ্ন থাকে, ভেতরে আয়াতের নম্বর ({{۝}})। আপনিও আপনার লেখা প্রতিটি আয়াতের শেষে ছোট্ট একটা ফুল বা গোল এঁকে নম্বর লিখতে পারেন!","en":"In the mushaf, each ayah ends with a round marker holding its number ({{۝}}). You can draw a small flower or circle with the number at the end of each ayah you write!"},{"type":"selfcheck","items":[{"bn":"আমি প্রতিটি লাইন ডান দিক থেকে শুরু করেছি, লাইন সোজা রেখেছি","en":"I started every line on the right and kept it straight"},{"bn":"আমার শব্দের মাঝে সমান ফাঁক","en":"My spaces between words are even"},{"bn":"আমি প্রতিটি অক্ষর, বিন্দু ও হরকত মডেলের সাথে মিলিয়েছি","en":"I checked every letter, dot and mark against the model"},{"bn":"আমি যত্ন ও সম্মানের সাথে লিখেছি","en":"I wrote with care and respect"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"পুরো লাইন কপি করার সময় বিন্দু আর হরকত কখন দেবেন?","en":"When copying a whole line, when do you add dots and harakat?"},"options":[{"bn":"প্রতিটি অক্ষরের সাথে সাথে","en":"With every letter as you go"},{"bn":"শরীরগুলো লেখা শেষ হলে","en":"After the letter bodies are written"},{"bn":"একদমই দেবেন না","en":"Never"}],"answer":1},{"q":{"bn":"শব্দের মাঝে কতটা ফাঁক রাখবেন?","en":"How much space goes between words?"},"options":[{"bn":"প্রায় একটা ছোট অক্ষরের সমান, সবখানে সমান","en":"About one small letter, the same everywhere"},{"bn":"কোনো ফাঁক নয়","en":"No space"},{"bn":"আধা লাইন","en":"Half a line"}],"answer":0},{"q":{"bn":"{{رَبِّ زِدْنِي عِلْمًا}} মানে কী?","en":"What does {{رَبِّ زِدْنِي عِلْمًا}} mean?"},"options":[{"bn":"হে আমার রব, আমার জ্ঞান বাড়িয়ে দিন","en":"My Lord, increase me in knowledge"},{"bn":"সব প্রশংসা আল্লাহর","en":"All praise is for Allah"},{"bn":"আল্লাহ এক","en":"Allah is One"}],"answer":0},{"q":{"bn":"এই আয়াতটি কোন সূরার?","en":"Which surah is this ayah from?"},"options":[{"bn":"সূরা ফাতিহা","en":"Al-Fatihah"},{"bn":"সূরা ইখলাস","en":"Al-Ikhlas"},{"bn":"সূরা নাস","en":"An-Nas"}],"answer":1,"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ"},{"q":{"bn":"আয়াত লেখার আগে কী করা উত্তম?","en":"What is best to do before writing ayahs?"},"options":[{"bn":"অযু করে নেওয়া","en":"Make wudu"},{"bn":"তাড়াতাড়ি লেখা","en":"Write as fast as possible"},{"bn":"খাতা মেঝেতে রাখা","en":"Put the notebook on the floor"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-dictation","icon":"اسم","title":{"bn":"শুনে লিখি ও নিজের নাম","en":"Listen and Write — and Your Name"},"subtitle":{"bn":"শ্রুতিলিখন: অক্ষর, সিলেবল, শব্দ — আর আরবিতে নিজের নাম","en":"Dictation: letters, syllables, words — and your own name in Arabic"},"minutes":20,"goals":[{"bn":"শুনে অক্ষর ও শব্দ লেখা","en":"Write letters and words from listening"},{"bn":"নিজের ভুল নিজে খুঁজে ঠিক করা","en":"Find and fix your own mistakes"},{"bn":"আরবিতে নিজের নাম লেখা","en":"Write your own name in Arabic"}],"blocks":[{"type":"text","bn":"এতদিন আপনি দেখে দেখে লিখেছেন। এবার চোখ নয়, কান দিয়ে! শুনুন, মনে মনে অক্ষরগুলো ভাবুন, তারপর লিখুন। শেষে উত্তর মিলিয়ে নিজেই নম্বর দিন।","en":"Until now you have written by looking. Now use your ears, not your eyes! Listen, picture the letters in your mind, then write. Finally, check the answer and grade yourself."},{"type":"tip","kind":"tip","bn":"অ্যাপে শব্দটি শুনে লিখুন। বইয়ে কেউ (মা-বাবা, শিক্ষক বা বন্ধু) পড়ে শোনাবেন — উত্তর আছে ইউনিটের শেষে উত্তরমালায়। একেকটা দুবার শুনতে পারেন।","en":"In the app, listen and write. In the book, someone (a parent, teacher or friend) reads aloud — the answers are in the unit's answer key. You may hear each one twice.","title":{"bn":"কীভাবে করবেন","en":"How to do it"}},{"type":"dictation","items":[{"ar":"ج","tr":{"bn":"জীম","en":"jīm"}},{"ar":"ر","tr":{"bn":"রা","en":"rā"}},{"ar":"ص","tr":{"bn":"সোয়াদ","en":"ṣād"}},{"ar":"ع","tr":{"bn":"আইন","en":"'ayn"}},{"ar":"ق","tr":{"bn":"ক্বাফ","en":"qāf"}}],"title":{"bn":"ধাপ ১: অক্ষর","en":"Step 1: Letters"}},{"type":"dictation","items":[{"ar":"بَ","tr":{"bn":"বা","en":"ba"}},{"ar":"تِ","tr":{"bn":"তি","en":"ti"}},{"ar":"نُ","tr":{"bn":"নু","en":"nu"}},{"ar":"مَا","tr":{"bn":"মা","en":"mā"}},{"ar":"لِي","tr":{"bn":"লী","en":"lī"}}],"title":{"bn":"ধাপ ২: সিলেবল","en":"Step 2: Syllables"}},{"type":"dictation","items":[{"ar":"قَلَمٌ","tr":{"bn":"কালামুন","en":"qalamun"},"mean":{"bn":"কলম","en":"pen"}},{"ar":"بَابٌ","tr":{"bn":"বাবুন","en":"bābun"},"mean":{"bn":"দরজা","en":"door"}},{"ar":"نُورٌ","tr":{"bn":"নূরুন","en":"nūrun"},"mean":{"bn":"আলো","en":"light"}},{"ar":"شَمْسٌ","tr":{"bn":"শামসুন","en":"shamsun"},"mean":{"bn":"সূর্য","en":"sun"}},{"ar":"عِلْمٌ","tr":{"bn":"ইলমুন","en":"'ilmun"},"mean":{"bn":"জ্ঞান","en":"knowledge"}},{"ar":"بَيْتٌ","tr":{"bn":"বাইতুন","en":"baytun"},"mean":{"bn":"ঘর","en":"house"}}],"title":{"bn":"ধাপ ৩: শব্দ","en":"Step 3: Words"}},{"type":"tip","kind":"memory","bn":"**শুনুন → ভাঙুন → লিখুন।** শব্দটা শুনে মনে মনে সিলেবলে ভাঙুন ({{قَ}}-{{لَ}}-{{مٌ}}), তারপর এক সিলেবল করে লিখুন। মুখস্থ নয়, কান আর হাতের বন্ধুত্ব!","en":"**Listen → split → write.** Hear the word, split it into syllables in your head ({{قَ}}-{{لَ}}-{{مٌ}}), then write one syllable at a time. Not memorising — a friendship between ear and hand!","title":{"bn":"শোনার কৌশল","en":"Listening trick"}},{"type":"text","bn":"এবার সবচেয়ে মজার কাজ: আরবিতে নিজের নাম! বাংলাদেশের অনেক নামই আরবি থেকে এসেছে। নিচের তালিকায় আপনার নাম খুঁজুন।","en":"Now the most fun part: your name in Arabic! Many Bangladeshi names come from Arabic. Look for your name in the table below.","title":{"bn":"আরবিতে আপনার নাম","en":"Your name in Arabic"}},{"type":"table","head":[{"bn":"বাংলা নাম","en":"Name"},{"bn":"আরবি","en":"Arabic"},{"bn":"পরিচিতি","en":"About"}],"rows":[[{"bn":"মুহাম্মাদ","en":"Muhammad"},"مُحَمَّد",{"bn":"নবীজির (সা.) নাম; অর্থ: প্রশংসিত","en":"Name of the Prophet ﷺ; means 'praised'"}],[{"bn":"আহমাদ","en":"Ahmad"},"أَحْمَد",{"bn":"নবীজির (সা.) আরেক নাম","en":"Another name of the Prophet ﷺ"}],[{"bn":"আব্দুল্লাহ","en":"Abdullah"},"عَبْدُ اللّٰه",{"bn":"অর্থ: আল্লাহর বান্দা","en":"Means 'servant of Allah'"}],[{"bn":"আব্দুর রহমান","en":"Abdur Rahman"},"عَبْدُ الرَّحْمٰن",{"bn":"অর্থ: দয়াময়ের বান্দা","en":"Means 'servant of the Most Merciful'"}],[{"bn":"ইব্রাহিম","en":"Ibrahim"},"إِبْرَاهِيم",{"bn":"একজন মহান নবী (আ.)","en":"A great prophet (peace be upon him)"}],[{"bn":"ইউসুফ","en":"Yusuf"},"يُوسُف",{"bn":"নবী (আ.); কুরআনে তাঁর নামে সূরা আছে","en":"A prophet; a surah of the Quran bears his name"}],[{"bn":"উমার","en":"Umar"},"عُمَر",{"bn":"দ্বিতীয় খলিফা (রা.)","en":"The second caliph"}],[{"bn":"আলী","en":"Ali"},"عَلِيّ",{"bn":"চতুর্থ খলিফা (রা.)","en":"The fourth caliph"}],[{"bn":"হাসান","en":"Hasan"},"حَسَن",{"bn":"নবীজির (সা.) নাতি; অর্থ: সুন্দর","en":"Grandson of the Prophet ﷺ; means 'good, beautiful'"}],[{"bn":"হুসাইন","en":"Husain"},"حُسَيْن",{"bn":"নবীজির (সা.) নাতি","en":"Grandson of the Prophet ﷺ"}],[{"bn":"ফাতিমা","en":"Fatimah"},"فَاطِمَة",{"bn":"নবীজির (সা.) কন্যা (রা.)","en":"Daughter of the Prophet ﷺ"}],[{"bn":"খাদিজা","en":"Khadijah"},"خَدِيجَة",{"bn":"নবীজির (সা.) প্রথম স্ত্রী (রা.)","en":"The Prophet's ﷺ first wife"}],[{"bn":"আয়েশা","en":"Aishah"},"عَائِشَة",{"bn":"উম্মুল মুমিনীন (রা.)","en":"A Mother of the Believers"}],[{"bn":"মারইয়াম","en":"Maryam"},"مَرْيَم",{"bn":"ঈসা (আ.)-এর মা; কুরআনে তাঁর নামে সূরা আছে","en":"Mother of 'Isa; a surah bears her name"}],[{"bn":"যাইনাব","en":"Zaynab"},"زَيْنَب",{"bn":"নবীজির (সা.) কন্যা (রা.)","en":"Daughter of the Prophet ﷺ"}],[{"bn":"রুকাইয়া","en":"Ruqayyah"},"رُقَيَّة",{"bn":"নবীজির (সা.) কন্যা (রা.)","en":"Daughter of the Prophet ﷺ"}],[{"bn":"সুমাইয়া","en":"Sumayyah"},"سُمَيَّة",{"bn":"ইসলামের প্রথম শহীদ (রা.)","en":"The first martyr of Islam"}]],"title":{"bn":"পরিচিত নাম আরবিতে","en":"Familiar names in Arabic"}},{"type":"tip","kind":"tip","bn":"কিছু নাম আরবিতে দুই শব্দ: আব্দুল্লাহ = {{عَبْدُ}} + {{اللّٰه}}। আর অনেক মেয়েদের নামের শেষে গোল তা ({{ة}}) থাকে: {{فَاطِمَة}}, {{خَدِيجَة}}। আপনার নাম তালিকায় না থাকলে শিক্ষকের কাছে সঠিক বানান জেনে নিন।","en":"Some names are two words in Arabic: Abdullah = {{عَبْدُ}} + {{اللّٰه}}. Many girls' names end in taa marbuta ({{ة}}): {{فَاطِمَة}}, {{خَدِيجَة}}. If your name isn't listed, ask a teacher for the correct spelling."},{"type":"write","level":"word","items":["مُحَمَّد","فَاطِمَة","عَبْدُ اللّٰه","عَائِشَة","يُوسُف","مَرْيَم"],"note":{"bn":"শেষ লাইনে নিজের নাম আরবিতে লিখুন!","en":"On the last line, write your own name in Arabic!"},"title":{"bn":"নাম লেখা অনুশীলন","en":"Name writing practice"}},{"type":"selfcheck","items":[{"bn":"আমি শুনে অক্ষর ও শব্দ লিখতে পেরেছি","en":"I could write letters and words from listening"},{"bn":"আমি উত্তর মিলিয়ে নিজের ভুল নিজে ঠিক করেছি","en":"I checked the answers and fixed my own mistakes"},{"bn":"আমি বিন্দু ও হরকত ঠিক জায়গায় দিয়েছি","en":"I put dots and harakat in the right places"},{"bn":"আমি আরবিতে নিজের নাম লিখতে পারি","en":"I can write my own name in Arabic"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"শ্রুতিলিখনে একটা শব্দ লেখার আগে মনে মনে কী করবেন?","en":"Before writing a dictated word, what do you do in your head?"},"options":[{"bn":"সিলেবলে ভাঙব","en":"Split it into syllables"},{"bn":"উত্তর দেখে নেব","en":"Peek at the answer"},{"bn":"শব্দটা বাদ দেব","en":"Skip the word"}],"answer":0},{"q":{"bn":"{{مُحَمَّد}} নামে তাশদীদ কোন অক্ষরে?","en":"In {{مُحَمَّد}}, which letter has the shaddah?"},"options":[{"bn":"দ্বিতীয় মীম","en":"The second meem"},{"bn":"হা","en":"Ḥaa"},{"bn":"দাল","en":"Daal"}],"answer":0},{"q":{"bn":"{{فَاطِمَة}} নামের শেষ অক্ষর কোনটি?","en":"What is the last letter of {{فَاطِمَة}}?"},"options":["ة","ت","ه"],"answer":0},{"q":{"bn":"আব্দুল্লাহ আরবিতে কয় শব্দ?","en":"How many words is Abdullah in Arabic?"},"options":[{"bn":"১","en":"1"},{"bn":"২","en":"2"},{"bn":"৩","en":"3"}],"answer":1},{"q":{"bn":"শুনে লেখা শব্দটি কোনটি হতে পারে — 'শামসুন' (সূর্য)?","en":"Which is the dictated word 'shamsun' (sun)?"},"options":["شَمْسٌ","سَمْعٌ","شَيْءٌ"],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]},{"id":"wr-beautiful","icon":"❀","title":{"bn":"সুন্দর লেখার প্রকল্প","en":"Beautiful Writing Project"},"subtitle":{"bn":"নাসখ ও কুফি লিপি, ছন্দ আর একটি ছোট্ট ক্যালিগ্রাফি প্রকল্প","en":"Naskh and Kufi scripts, rhythm, and a little calligraphy project"},"minutes":25,"goals":[{"bn":"নাসখ আর কুফি লিপির পার্থক্য","en":"The difference between Naskh and Kufi scripts"},{"bn":"সমান ফাঁক ও ছন্দে লেখা","en":"Write with even spacing and rhythm"},{"bn":"নিজের হাতে একটি সাজানো ক্যালিগ্রাফি বানানো","en":"Make your own decorated calligraphy piece"}],"blocks":[{"type":"text","bn":"অভিনন্দন — আপনি এখন আরবি লিখতে পারেন! শেষ পাঠে আমরা লেখাকে **সুন্দর** করব। মুসলিম শিল্পীরা শত শত বছর ধরে আরবি লিপিকে অপূর্ব শিল্পে পরিণত করেছেন — আজ আপনিও ছোট্ট একজন শিল্পী!","en":"Congratulations — you can now write Arabic! In this last lesson we make writing **beautiful**. For centuries, Muslim artists have turned Arabic script into breathtaking art — today you become a little artist too!"},{"type":"table","head":[{"bn":"লিপি","en":"Script"},{"bn":"দেখতে কেমন","en":"What it looks like"},{"bn":"কোথায় দেখবেন","en":"Where you see it"}],"rows":[[{"bn":"নাসখ","en":"Naskh"},{"bn":"গোলগাল, পরিষ্কার, পড়তে সহজ","en":"Rounded, clear, easy to read"},{"bn":"বেশিরভাগ ছাপা মুসহাফ ও বই — এই কোর্সের লেখাও","en":"Most printed mushafs and books — including this course"}],[{"bn":"কুফি","en":"Kufi"},{"bn":"সোজা লাইন, ধারালো কোণ, চারকোনা ভাব","en":"Straight lines, sharp corners, a square feel"},{"bn":"প্রাচীন কুরআনের পাণ্ডুলিপি, মসজিদের দেয়াল, টালি ও নকশা","en":"Early Quran manuscripts, mosque walls, tiles and designs"}]],"title":{"bn":"দুই লিপির গল্প","en":"A tale of two scripts"}},{"type":"tip","kind":"memory","bn":"**নাসখ = নদী, কুফি = ইট।** নাসখ নদীর মতো বাঁক খেয়ে বয়ে চলে; কুফি ইটের মতো সোজা আর চারকোনা, যেন দেয়াল গাঁথা হচ্ছে।","en":"**Naskh = a river, Kufi = bricks.** Naskh flows and curves like a river; Kufi is straight and square like bricks, as if building a wall.","title":{"bn":"নদী আর ইট","en":"River and bricks"}},{"type":"tip","kind":"tip","bn":"সুন্দর লেখার তিন রহস্য: **সমান উচ্চতা** (সব আলিফ সমান), **সমান ফাঁক** (সব শব্দের মাঝে একই জায়গা), আর **সমান বিন্দু** (সব নুকতা একই মাপের)। ঢোলের তালের মতো — একই ছন্দ বারবার!","en":"Three secrets of beautiful writing: **same height** (every alif equal), **same spacing** (the same gap between words), and **same dots** (every nuqta the same size). Like a drum beat — the same rhythm again and again!","title":{"bn":"ছন্দের রহস্য","en":"The secret of rhythm"}},{"type":"steps","items":[{"title":{"bn":"কাগজ তৈরি","en":"Prepare the paper"},"desc":{"bn":"পেনসিলে হালকা দুটি গাইড লাইন টানুন: মূল লাইন আর আলিফের উচ্চতা।","en":"Lightly draw two pencil guide lines: the baseline and alif height."}},{"title":{"bn":"হালকা স্কেচ","en":"Light sketch"},"desc":{"bn":"মাঝখানে {{بِسْمِ اللّٰهِ}} হালকা করে লিখুন, নিচে {{سُبْحَانَ اللّٰهِ}}।","en":"Lightly write {{بِسْمِ اللّٰهِ}} in the middle, and {{سُبْحَانَ اللّٰهِ}} below it."}},{"title":{"bn":"কালি দিন","en":"Ink it"},"desc":{"bn":"কলম বা মার্কার দিয়ে ধীরে ধীরে স্কেচের ওপর লিখুন। চওড়া মাথার মার্কার হলে পুরো সময় একই কোণে ধরে রাখুন।","en":"Go over the sketch slowly with a pen or marker. With a broad-tip marker, keep it at the same angle the whole time."}},{"title":{"bn":"বিন্দু ও হরকত","en":"Dots and harakat"},"desc":{"bn":"শরীর শুকালে বিন্দু দিন, তারপর হরকত — সোনালি নিয়ম এখানেও!","en":"When the bodies are dry, add dots, then harakat — the golden rule applies here too!"}},{"title":{"bn":"নকশার বর্ডার","en":"Decorate a border"},"desc":{"bn":"চারপাশে বর্ডার আঁকুন: তারা, ফুল, লতাপাতা বা জ্যামিতিক নকশা। রং করুন, গাইড লাইন মুছে দিন।","en":"Draw a border all round: stars, flowers, vines or geometric patterns. Colour it in and erase the guide lines."}}],"title":{"bn":"প্রকল্প: আমার ক্যালিগ্রাফি","en":"Project: my calligraphy"}},{"type":"write","level":"line","items":["بِسْمِ اللّٰهِ","سُبْحَانَ اللّٰهِ","الْحَمْدُ لِلّٰهِ","اللّٰهُ أَكْبَرُ"],"reps":3,"note":{"bn":"প্রতিটি লাইনে ধীরে, ছন্দ মেনে লিখুন। সবচেয়ে সুন্দরটায় তারা দিন!","en":"Write each line slowly, keeping the rhythm. Put a star next to your best one!"},"title":{"bn":"সুন্দর করে লিখুন","en":"Write beautifully"}},{"type":"tip","kind":"fun","bn":"ছোট্ট কৌশল: দুটি পেনসিল রাবার ব্যান্ড দিয়ে একসাথে বেঁধে লিখে দেখুন — প্রতিটি অক্ষর দুই লাইনের রূপরেখায় বেরোবে, ঠিক ক্যালিগ্রাফির মতো! ভেতরটা রং করে নিন।","en":"A little trick: tie two pencils together with a rubber band and write — every letter comes out as a double outline, just like calligraphy! Then colour in the middle."},{"type":"tip","kind":"memory","bn":"**মাশাআল্লাহ!** একটা সোজা লাইন থেকে শুরু করে আপনি এখন আল্লাহর কালাম লিখতে পারেন। প্রতিদিন অন্তত একটা লাইন লিখুন — হাতের লেখা প্রতিদিন একটু একটু করে আরও সুন্দর হবে। আপনার কলম চলতে থাকুক!","en":"**Masha'Allah!** You started with a single straight line and now you can write the words of Allah. Write at least one line every day — your handwriting will grow a little more beautiful each day. Keep your pen moving!","title":{"bn":"আপনি পেরেছেন!","en":"You did it!"}},{"type":"selfcheck","items":[{"bn":"আমার সব আলিফ সমান উঁচু","en":"All my alifs are the same height"},{"bn":"আমার শব্দের মাঝে সমান ফাঁক","en":"My spaces between words are even"},{"bn":"আমার সব বিন্দু একই মাপের","en":"All my dots are the same size"},{"bn":"আমি একটি সাজানো ক্যালিগ্রাফি বানিয়েছি","en":"I made a decorated calligraphy piece"}],"title":{"bn":"নিজেকে যাচাই করুন","en":"Check yourself"}},{"type":"quiz","items":[{"q":{"bn":"কোন লিপি গোলগাল ও পড়তে সহজ, বেশিরভাগ মুসহাফে ব্যবহৃত?","en":"Which script is rounded, easy to read and used in most mushafs?"},"options":[{"bn":"নাসখ","en":"Naskh"},{"bn":"কুফি","en":"Kufi"}],"answer":0},{"q":{"bn":"কুফি লিপির বৈশিষ্ট্য কী?","en":"What is special about Kufi script?"},"options":[{"bn":"সোজা লাইন ও ধারালো কোণ","en":"Straight lines and sharp corners"},{"bn":"শুধু গোল আকৃতি","en":"Only round shapes"},{"bn":"কোনো বিন্দু নেই এমন আধুনিক লিপি","en":"A modern script with no dots"}],"answer":0},{"q":{"bn":"সুন্দর লেখার তিন রহস্যের মধ্যে কোনটি নেই?","en":"Which is NOT one of the three secrets of beautiful writing?"},"options":[{"bn":"সমান উচ্চতা","en":"Same height"},{"bn":"সমান ফাঁক","en":"Same spacing"},{"bn":"যত দ্রুত সম্ভব লেখা","en":"Writing as fast as possible"}],"answer":2},{"q":{"bn":"ক্যালিগ্রাফিতেও বিন্দু ও হরকত কখন দেবেন?","en":"In calligraphy too, when do you add dots and harakat?"},"options":[{"bn":"অক্ষরের শরীর শেষ হলে","en":"After the letter bodies"},{"bn":"সবার আগে","en":"First of all"},{"bn":"বর্ডার আঁকার আগে, শরীরের আগে","en":"Before the border and the bodies"}],"answer":0},{"q":{"bn":"{{سُبْحَانَ اللّٰهِ}} মানে কী?","en":"What does {{سُبْحَانَ اللّٰهِ}} mean?"},"options":[{"bn":"আল্লাহ পবিত্র","en":"Glory be to Allah"},{"bn":"আল্লাহ মহান","en":"Allah is the Greatest"},{"bn":"আল্লাহর নামে","en":"In the name of Allah"}],"answer":0}],"title":{"bn":"ছোট্ট কুইজ","en":"Quick quiz"}}]}]});
AQ.units.push({"id":"tajweed","order":3,"icon":"تَ","color":"emerald","title":{"bn":"সুন্দর তিলাওয়াত — তাজবীদ","en":"Beautiful Recitation — Tajweed"},"subtitle":{"bn":"প্রতিটি হরফকে তার হক দিয়ে কুরআন পড়া শিখি","en":"Learn to give every letter its right when reciting the Quran"},"lessons":[{"id":"tj-intro","icon":"۞","title":{"bn":"তাজবীদ কী ও কেন?","en":"What Is Tajweed & Why?"},"subtitle":{"bn":"ভুলের প্রকার, তিলাওয়াতের আদব, আ‘ঊযু ও বিসমিল্লাহ","en":"Types of mistakes, manners of recitation, ta'awwudh and basmalah"},"minutes":10,"goals":[{"bn":"তাজবীদ শব্দের অর্থ ও এর গুরুত্ব বুঝব","en":"Understand what tajweed means and why it matters"},{"bn":"লাহনে জলী (স্পষ্ট ভুল) ও লাহনে খফী (সূক্ষ্ম ভুল) চিনব","en":"Recognise clear mistakes (lahn jali) and hidden mistakes (lahn khafi)"},{"bn":"তিলাওয়াতের আদব জানব","en":"Learn the manners (adab) of recitation"},{"bn":"আ‘ঊযু ও বিসমিল্লাহ কখন কীভাবে পড়তে হয় শিখব","en":"Learn when and how to say the ta'awwudh and basmalah"}],"blocks":[{"type":"text","bn":"আসসালামু আলাইকুম! তুমি এখন আরবি হরফ ও হরকত পড়তে পারো। এবার সময় এসেছে কুরআনকে **সুন্দর ও সঠিকভাবে** পড়ার — ঠিক যেভাবে রাসূলুল্লাহ ﷺ পড়েছেন।","en":"Assalamu alaikum! You can now read Arabic letters and vowels. Now it is time to recite the Quran **correctly and beautifully** — the way the Prophet ﷺ recited it."},{"type":"text","title":{"bn":"তাজবীদ মানে কী?","en":"What does tajweed mean?"},"bn":"{{تَجْوِيد}} শব্দের অর্থ ‘সুন্দর করা, উত্তম করা’। তাজবীদ হলো প্রতিটি হরফকে তার **সঠিক মাখরাজ** (উচ্চারণের জায়গা) ও **সঠিক সিফাত** (গুণ — মোটা/চিকন, গুন্নাহ, টান ইত্যাদি) দিয়ে উচ্চারণ করা।","en":"{{تَجْوِيد}} means ‘to make better, to beautify’. Tajweed is pronouncing every letter from its **correct makhraj** (point of articulation) with its **correct qualities** (heavy/light, nasal sound, length and so on)."},{"type":"ayah","ref":"73:4","ar":"أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا","words":[{"ar":"أَوْ","bn":"অথবা","en":"or"},{"ar":"زِدْ","bn":"বাড়াও","en":"add"},{"ar":"عَلَيْهِ","bn":"তার ওপর","en":"to it"},{"ar":"وَرَتِّلِ","bn":"এবং ধীরে ধীরে স্পষ্ট করে পড়ো","en":"and recite clearly"},{"ar":"الْقُرْآنَ","bn":"কুরআন","en":"the Quran"},{"ar":"تَرْتِيلًا","bn":"সুবিন্যস্তভাবে","en":"in measured recitation"}],"tr":{"bn":"আও যিদ আলাইহি ওয়া রত্তিলিল কুরআ-না তারতীলা","en":"aw zid 'alayhi wa rattilil-qur'aana tarteelaa"},"mean":{"bn":"অথবা তার চেয়ে একটু বাড়াও — আর কুরআন পড়ো ধীরে ধীরে, সুস্পষ্টভাবে।","en":"Or add a little to it, and recite the Quran in a slow, measured way."}},{"type":"tip","kind":"fun","bn":"কুরআনের তিলাওয়াত বই থেকে নয়, **মুখ থেকে কানে** — উস্তাদ থেকে ছাত্রে — পৌঁছেছে। জিবরীল (আ.) রাসূল ﷺ-কে শিখিয়েছেন, তিনি সাহাবিদের, তারপর প্রজন্মের পর প্রজন্ম। এই ধারাকে বলে ‘সনদ’। তাই ভালো কারীর তিলাওয়াত শোনা তাজবীদ শেখার সেরা উপায়!","en":"Quran recitation came to us **mouth to ear** — teacher to student — not just through books. Jibreel taught the Prophet ﷺ, he taught the Companions, and so on, generation after generation. This chain is called a ‘sanad’. That is why listening to a good reciter is the best way to learn tajweed!"},{"type":"text","title":{"bn":"দুই ধরনের ভুল","en":"Two kinds of mistakes"},"bn":"তিলাওয়াতের ভুলকে আরবিতে বলে {{لَحْن}} (লাহন)। ভুল দুই প্রকার:\n**১. লাহনে জলী (স্পষ্ট ভুল):** এক হরফের জায়গায় আরেক হরফ পড়া, হরকত বদলে ফেলা, হরফ বাদ দেওয়া বা বাড়ানো। এতে অনেক সময় **অর্থই বদলে যায়** — এটা হারাম, অবশ্যই এড়াতে হবে।\n**২. লাহনে খফী (সূক্ষ্ম ভুল):** গুন্নাহ না করা, মাদ্দ কম-বেশি টানা, মোটা হরফ চিকন করা ইত্যাদি। অর্থ বদলায় না, কিন্তু সৌন্দর্য নষ্ট হয় — এটাও এড়ানো উচিত।","en":"A mistake in recitation is called {{لَحْن}} (lahn). There are two kinds:\n**1. Lahn jali (clear mistake):** reading one letter in place of another, changing a vowel, dropping or adding a letter. It often **changes the meaning** — this is forbidden and must be avoided.\n**2. Lahn khafi (hidden mistake):** skipping ghunnah, stretching a madd too short or too long, making a heavy letter light, etc. The meaning stays, but the beauty is spoiled — this should also be avoided."},{"type":"compare","title":{"bn":"একটি ছোট হরকত, বিশাল পার্থক্য!","en":"One small vowel, a huge difference!"},"items":[{"ar":"أَنْعَمْتَ","label":{"bn":"সঠিক (তা-তে যবর)","en":"Correct (fatha on ta)"},"desc":{"bn":"‘(হে আল্লাহ) তুমি নিয়ামত দিয়েছ’ — সূরা ফাতিহা","en":"‘You (O Allah) have favoured’ — Surah al-Fatiha"}},{"ar":"أَنْعَمْتُ","label":{"bn":"লাহনে জলী! (তা-তে পেশ)","en":"Clear mistake! (damma on ta)"},"desc":{"bn":"‘আমি নিয়ামত দিয়েছি’ — অর্থ সম্পূর্ণ উল্টে গেল!","en":"‘I have favoured’ — the meaning is completely changed!"}}]},{"type":"text","title":{"bn":"হুকুম (বিধান)","en":"The ruling"},"bn":"তাজবীদের সব নিয়মকানুন বিস্তারিত শেখা **ফরযে কিফায়া** (সমাজের কিছু মানুষ শিখলেই যথেষ্ট)। কিন্তু যে-ই কুরআন পড়ে, তার জন্য **সঠিকভাবে পড়া** — অন্তত স্পষ্ট ভুল থেকে মুক্ত থাকা — জরুরি।","en":"Learning all the detailed rules of tajweed is **fard kifayah** (a community duty). But for anyone who recites, **reciting correctly** — at least free from clear mistakes — is a personal duty."},{"type":"steps","title":{"bn":"তিলাওয়াতের আদব","en":"Manners of recitation"},"items":[{"title":{"bn":"নিয়ত খাঁটি করো","en":"Make a sincere intention"},"desc":{"bn":"শুধু আল্লাহকে খুশি করার জন্য পড়ো, মানুষকে দেখানোর জন্য নয়।","en":"Recite only to please Allah, not to show off."}},{"title":{"bn":"পবিত্র হও","en":"Be clean"},"desc":{"bn":"অযু করে, পরিষ্কার জায়গায় বসো। মুসহাফ ছোঁয়ার জন্য অযু লাগে।","en":"Make wudu and sit in a clean place. Wudu is needed to touch the mushaf."}},{"title":{"bn":"সম্ভব হলে কিবলামুখী হও","en":"Face the qiblah if you can"},"desc":{"bn":"শান্ত হয়ে, সম্মানের সাথে বসো।","en":"Sit calmly and respectfully."}},{"title":{"bn":"আ‘ঊযু পড়ো","en":"Seek refuge"},"ar":"أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":{"bn":"আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বা-নির রজীম","en":"a'oodhu billaahi minash-shayṭaanir-rajeem"},"mean":{"bn":"আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই।","en":"I seek refuge in Allah from Satan, the outcast."}},{"title":{"bn":"সূরার শুরুতে বিসমিল্লাহ পড়ো","en":"Say the basmalah at the start of a surah"},"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","tr":{"bn":"বিসমিল্লা-হির রহ্‌মা-নির রহীম","en":"bismillaahir-raḥmaanir-raḥeem"},"mean":{"bn":"পরম করুণাময়, অতি দয়ালু আল্লাহর নামে।","en":"In the name of Allah, the Most Gracious, the Most Merciful."}},{"title":{"bn":"ধীরে, বুঝে, মন দিয়ে পড়ো","en":"Recite slowly, with attention"},"desc":{"bn":"তাড়াহুড়া নয়। হাই এলে তিলাওয়াত থামিয়ে দাও, পরে আবার শুরু করো।","en":"Do not rush. If you yawn, pause the recitation and continue afterwards."}}]},{"type":"text","title":{"bn":"বিসমিল্লাহর নিয়ম","en":"Rules of the basmalah"},"bn":"• **সূরার শুরু থেকে** পড়লে: আ‘ঊযু + বিসমিল্লাহ দুটোই পড়ো।\n• **সূরার মাঝখান থেকে** পড়লে: আ‘ঊযু পড়ো; বিসমিল্লাহ পড়া ঐচ্ছিক।\n• **সূরা তাওবা (৯ নম্বর)** শুরুতে বিসমিল্লাহ নেই — শুধু আ‘ঊযু পড়ে শুরু করো (যদি এখান থেকেই তিলাওয়াত শুরু করো)।","en":"• **Starting from the beginning of a surah:** say both the ta'awwudh and the basmalah.\n• **Starting from the middle of a surah:** say the ta'awwudh; the basmalah is optional.\n• **Surah at-Tawbah (no. 9)** has no basmalah — begin with just the ta'awwudh (if you start your recitation there)."},{"type":"tip","kind":"warn","bn":"এক সূরা শেষ করে পরের সূরা শুরু করার সময় একটি পদ্ধতি **নিষেধ**: আগের সূরার শেষ শব্দ বিসমিল্লাহর সাথে মিলিয়ে পড়ে তারপর থেমে যাওয়া। এতে মনে হয় বিসমিল্লাহ আগের সূরার অংশ! হয় সব আলাদা পড়ো, নয় বিসমিল্লাহকে পরের সূরার সাথে মেলাও।","en":"When moving from one surah to the next, one way is **not allowed**: joining the last word of the surah to the basmalah and then stopping. It makes the basmalah sound like part of the previous surah! Either read each part separately, or join the basmalah to the next surah."},{"type":"tip","kind":"memory","bn":"মনে রাখো: **আ‘ঊযু = শয়তান থেকে ঢাল, বিসমিল্লাহ = সূরার দরজা।** তাওবা সূরার দরজায় বিসমিল্লাহ নেই।","en":"Remember: **Ta'awwudh = a shield against Satan; basmalah = the door of a surah.** Surah at-Tawbah's door has no basmalah."},{"type":"practice","bn":"ধীরে ধীরে পড়ো। প্রতিটি হরফ স্পষ্ট হচ্ছে কি না খেয়াল করো।","en":"Read slowly. Check that every letter comes out clearly.","lines":["أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا","أَنْعَمْتَ أَنْعَمْتَ أَنْعَمْتَ"]},{"type":"quiz","items":[{"q":{"bn":"‘তাজবীদ’ শব্দের অর্থ কী?","en":"What does the word ‘tajweed’ mean?"},"options":[{"bn":"দ্রুত পড়া","en":"Reading fast"},{"bn":"সুন্দর ও উত্তম করা","en":"Making better and beautiful"},{"bn":"মুখস্থ করা","en":"Memorising"}],"answer":1},{"q":{"bn":"যে ভুলে অর্থ বদলে যেতে পারে, তাকে কী বলে?","en":"What is a mistake that can change the meaning called?"},"options":[{"bn":"লাহনে জলী","en":"Lahn jali"},{"bn":"লাহনে খফী","en":"Lahn khafi"},{"bn":"তারতীল","en":"Tarteel"}],"answer":0},{"q":{"bn":"গুন্নাহ না করা কোন ধরনের ভুল?","en":"Skipping a ghunnah is which type of mistake?"},"options":[{"bn":"লাহনে জলী","en":"Lahn jali"},{"bn":"লাহনে খফী","en":"Lahn khafi"},{"bn":"কোনো ভুল নয়","en":"Not a mistake"}],"answer":1},{"q":{"bn":"কোন সূরার শুরুতে বিসমিল্লাহ নেই?","en":"Which surah has no basmalah at its start?"},"options":[{"bn":"সূরা ফাতিহা","en":"Surah al-Fatiha"},{"bn":"সূরা তাওবা","en":"Surah at-Tawbah"},{"bn":"সূরা ইখলাস","en":"Surah al-Ikhlas"}],"answer":1},{"q":{"bn":"এখানে তা-তে পেশ দিলে অর্থ কী হয়?","en":"If ta is read with damma here, what does it mean?"},"ar":"أَنْعَمْتَ","options":[{"bn":"তুমি নিয়ামত দিয়েছ","en":"You have favoured"},{"bn":"আমি নিয়ামত দিয়েছি","en":"I have favoured"},{"bn":"অর্থ বদলায় না","en":"No change in meaning"}],"answer":1,"explain":{"bn":"{{أَنْعَمْتُ}} মানে ‘আমি দিয়েছি’ — তাই হরকতের ভুল লাহনে জলী।","en":"{{أَنْعَمْتُ}} means ‘I have given’ — so a vowel error is a clear mistake."}},{"q":{"bn":"সূরার মাঝখান থেকে তিলাওয়াত শুরু করলে কী পড়বে?","en":"Starting recitation from the middle of a surah, what do you say?"},"options":[{"bn":"শুধু বিসমিল্লাহ (আ‘ঊযু লাগবে না)","en":"Only the basmalah (no ta'awwudh)"},{"bn":"আ‘ঊযু; বিসমিল্লাহ ঐচ্ছিক","en":"The ta'awwudh; basmalah is optional"},{"bn":"কিছুই না","en":"Nothing"}],"answer":1}]}]},{"id":"tj-makharij","icon":"مخ","title":{"bn":"মাখরাজ — হরফ কোথা থেকে বের হয়","en":"Makharij — Where Letters Come From"},"subtitle":{"bn":"৫টি এলাকা, ১৭টি মাখরাজ এবং নিজে যাচাই করার কৌশল","en":"5 areas, 17 points, and a trick to check yourself"},"minutes":15,"goals":[{"bn":"উচ্চারণের ৫টি প্রধান এলাকা চিনব","en":"Know the 5 main areas of articulation"},{"bn":"১৭টি মাখরাজ ও তাদের হরফ জানব","en":"Learn the 17 points and their letters"},{"bn":"সাকিন হরফ দিয়ে নিজের মাখরাজ নিজে যাচাই করতে শিখব","en":"Use a sukun letter to test your own articulation"}],"blocks":[{"type":"text","bn":"প্রতিটি হরফের মুখের ভেতর একটি নির্দিষ্ট ‘ঠিকানা’ আছে। এই ঠিকানাকে বলে **মাখরাজ** ({{مَخْرَج}} — বের হওয়ার জায়গা)। ঠিকানা ভুল হলে হরফটাই বদলে যায় — যেমন {{ق}} হয়ে যায় {{ك}}।","en":"Every letter has a fixed ‘address’ inside the mouth. This address is called the **makhraj** ({{مَخْرَج}} — the place of exit). Use the wrong address and the letter itself changes — {{ق}} turns into {{ك}}."},{"type":"steps","title":{"bn":"৫টি প্রধান এলাকা","en":"The 5 main areas"},"items":[{"title":{"bn":"জাওফ — মুখ ও গলার ফাঁকা জায়গা","en":"Al-Jawf — the empty space of mouth and throat"},"ar":"الْجَوْف","desc":{"bn":"এখান থেকে তিনটি মাদ্দের হরফ: যবরের পর {{ا}}, পেশের পর সাকিন {{و}}, যেরের পর সাকিন {{ي}}। এগুলো বাতাস যতক্ষণ, ততক্ষণ চলে।","en":"The three madd letters: {{ا}} after fatha, sakin {{و}} after damma, sakin {{ي}} after kasra. They flow as long as your breath."}},{"title":{"bn":"হালক — গলা","en":"Al-Halq — the throat"},"ar":"الْحَلْق","desc":{"bn":"৬টি হরফ: {{ء ه ع ح غ خ}}","en":"6 letters: {{ء ه ع ح غ خ}}"}},{"title":{"bn":"লিসান — জিহ্বা","en":"Al-Lisan — the tongue"},"ar":"اللِّسَان","desc":{"bn":"সবচেয়ে বেশি হরফ — ১৮টি — জিহ্বার বিভিন্ন অংশ থেকে।","en":"The most letters — 18 — come from different parts of the tongue."}},{"title":{"bn":"শাফাতান — দুই ঠোঁট","en":"Ash-Shafatan — the two lips"},"ar":"الشَّفَتَان","desc":{"bn":"৪টি হরফ: {{ف ب م و}}","en":"4 letters: {{ف ب م و}}"}},{"title":{"bn":"খাইশূম — নাকের বাঁশি","en":"Al-Khayshum — the nasal passage"},"ar":"الْخَيْشُوم","desc":{"bn":"এখান থেকে কোনো হরফ নয়, বের হয় **গুন্নাহ** — নূন ও মীমের নাকি সুর।","en":"No letter comes from here — only the **ghunnah**, the nasal hum of noon and meem."}}]},{"type":"table","title":{"bn":"১৭টি মাখরাজ","en":"The 17 points of articulation"},"head":[{"bn":"নং","en":"#"},{"bn":"হরফ","en":"Letters"},{"bn":"কোথা থেকে","en":"Where"}],"rows":[[{"bn":"১","en":"1"},"ـَا ـُو ـِي",{"bn":"জাওফ — মুখ-গলার ফাঁকা জায়গা (মাদ্দের হরফ)","en":"Jawf — the open space of mouth and throat (madd letters)"}],[{"bn":"২","en":"2"},"ء ه",{"bn":"গলার একদম গভীর অংশ (বুকের দিকে)","en":"Deepest part of the throat (near the chest)"}],[{"bn":"৩","en":"3"},"ع ح",{"bn":"গলার মাঝখান","en":"Middle of the throat"}],[{"bn":"৪","en":"4"},"غ خ",{"bn":"গলার উপরের অংশ (মুখের দিকে)","en":"Top of the throat (nearest the mouth)"}],[{"bn":"৫","en":"5"},"ق",{"bn":"জিহ্বার একদম গোড়া + উপরের নরম তালু","en":"Very back of the tongue + the soft palate above"}],[{"bn":"৬","en":"6"},"ك",{"bn":"ক্বাফের একটু সামনে — জিহ্বার গোড়া + তালু","en":"Slightly forward of qaf — back of tongue + palate"}],[{"bn":"৭","en":"7"},"ج ش ي",{"bn":"জিহ্বার মাঝখান + উপরের শক্ত তালু","en":"Middle of the tongue + the hard palate"}],[{"bn":"৮","en":"8"},"ض",{"bn":"জিহ্বার এক বা দুই পাশ + উপরের মাড়ির দাঁত","en":"One or both sides of the tongue + the upper molars"}],[{"bn":"৯","en":"9"},"ل",{"bn":"জিহ্বার আগার কিনারা + উপরের সামনের দাঁতের মাড়ি","en":"Front rim of the tongue + gums of the upper front teeth"}],[{"bn":"১০","en":"10"},"ن",{"bn":"জিহ্বার আগা + উপরের সামনের দুই দাঁতের মাড়ি","en":"Tip of the tongue + gum of the upper front teeth"}],[{"bn":"১১","en":"11"},"ر",{"bn":"নূনের কাছেই, জিহ্বার আগা ও একটু উপরের পিঠ + মাড়ি","en":"Next to noon — tongue tip with a little of its top + the gum"}],[{"bn":"১২","en":"12"},"ط د ت",{"bn":"জিহ্বার আগা + উপরের সামনের দুই দাঁতের গোড়া","en":"Tongue tip + roots of the two upper front teeth"}],[{"bn":"১৩","en":"13"},"ص ز س",{"bn":"জিহ্বার আগা নিচের সামনের দাঁতের কাছে, দাঁতের ফাঁক দিয়ে শিস","en":"Tongue tip near the lower front teeth; air whistles between the teeth"}],[{"bn":"১৪","en":"14"},"ظ ذ ث",{"bn":"জিহ্বার আগা + উপরের সামনের দুই দাঁতের কিনারা","en":"Tongue tip + edges of the two upper front teeth"}],[{"bn":"১৫","en":"15"},"ف",{"bn":"নিচের ঠোঁটের ভেতরের দিক + উপরের সামনের দাঁতের কিনারা","en":"Inner lower lip + edges of the upper front teeth"}],[{"bn":"১৬","en":"16"},"ب م و",{"bn":"দুই ঠোঁট — {{ب}} ভেজা অংশ চেপে, {{م}} হালকা বন্ধ করে, {{و}} গোল করে (বন্ধ নয়)","en":"Both lips — {{ب}} pressing the moist part, {{م}} closing lightly, {{و}} rounding (not closing)"}],[{"bn":"১৭","en":"17"},"نّ مّ",{"bn":"খাইশূম — নাকের বাঁশি (গুন্নাহ)","en":"Khayshum — the nasal passage (ghunnah)"}]]},{"type":"letters","title":{"bn":"গলার ৬টি হরফ — গভীর থেকে উপরে","en":"The 6 throat letters — deep to high"},"items":["hamza","ha","ain","hha","ghain","kha"]},{"type":"tip","kind":"memory","bn":"গলাকে তিন তলার বাড়ি ভাবো: **নিচতলা** {{ء ه}}, **দোতলা** {{ع ح}}, **তিনতলা** {{غ خ}}। নিচ থেকে উপরে উঠতে উঠতে হরফ মুখের কাছে চলে আসে।","en":"Think of the throat as a 3-storey house: **ground floor** {{ء ه}}, **first floor** {{ع ح}}, **top floor** {{غ خ}}. Going up, the letters move closer to the mouth."},{"type":"tip","kind":"tip","title":{"bn":"নিজেই যাচাই করো!","en":"Check yourself!"},"bn":"যে হরফের মাখরাজ খুঁজতে চাও, তার আগে যবরসহ হামযা বসিয়ে হরফটিকে **সাকিন** করে পড়ো: {{أَبْ}}, {{أَقْ}}, {{أَثْ}}। যেখানে আওয়াজ থেমে যায় — সেটাই ঐ হরফের মাখরাজ। সাকিন অবস্থায় হরফ তার জায়গায় ‘বসে’ থাকে, তাই অনুভব করা সহজ।","en":"To find a letter's makhraj, put a hamza with fatha before it and read the letter with **sukun**: {{أَبْ}}, {{أَقْ}}, {{أَثْ}}. Where the sound stops — that is the makhraj. With sukun the letter ‘sits’ in its place, so it is easy to feel."},{"type":"tip","kind":"tip","title":{"bn":"আয়না পরীক্ষা","en":"The mirror test"},"bn":"আয়নার সামনে {{أَثْ}} {{أَذْ}} {{أَظْ}} পড়ো — জিহ্বার আগা সামান্য দেখা যাওয়া উচিত। {{أَفْ}} পড়লে উপরের দাঁত নিচের ঠোঁট আলতো ছোঁবে। {{أَوْ}} পড়লে ঠোঁট গোল হবে, দাঁত ঠোঁটে লাগবে না — এটা বাংলা ‘ভ’ নয়!","en":"In front of a mirror say {{أَثْ}} {{أَذْ}} {{أَظْ}} — the tip of your tongue should just show. For {{أَفْ}} your upper teeth gently touch your lower lip. For {{أَوْ}} your lips round and your teeth do not touch them — it is not a ‘v’!"},{"type":"examples","title":{"bn":"কাছাকাছি মাখরাজ — সাবধান!","en":"Neighbouring points — careful!"},"items":[{"ar":"أَقْ","tr":{"bn":"আক্ব্‌","en":"aq"},"note":{"bn":"জিহ্বার একদম গোড়া, ভারী আওয়াজ","en":"Very back of the tongue, deep sound"}},{"ar":"أَكْ","tr":{"bn":"আক্‌","en":"ak"},"note":{"bn":"একটু সামনে, হালকা আওয়াজ","en":"A little forward, light sound"}},{"ar":"أَنْ","tr":{"bn":"আন্‌","en":"an"},"note":{"bn":"জিহ্বার আগা মাড়িতে","en":"Tongue tip on the gum"}},{"ar":"أَلْ","tr":{"bn":"আল্‌","en":"al"},"note":{"bn":"জিহ্বার আগার কিনারা","en":"Front rim of the tongue"}},{"ar":"أَرْ","tr":{"bn":"আর্‌","en":"ar"},"note":{"bn":"আগা + একটু পিঠ, এক ঝটকা (র-কে কাঁপাবে না)","en":"Tip + a little of the top, a single tap (do not roll it)"}}]},{"type":"practice","bn":"প্রতিটি সাকিন হরফ পড়ে এক মুহূর্ত থামো আর অনুভব করো আওয়াজ কোথায় থামছে।","en":"Read each sukun letter, pause a moment and feel where the sound stops.","lines":["أَهْ أَعْ أَحْ أَغْ أَخْ","أَقْ أَكْ أَجْ أَشْ أَيْ","أَضْ أَلْ أَنْ أَرْ","أَطْ أَدْ أَتْ","أَصْ أَزْ أَسْ","أَظْ أَذْ أَثْ","أَفْ أَبْ أَمْ أَوْ"]},{"type":"quiz","items":[{"q":{"bn":"মোট কয়টি মাখরাজ?","en":"How many points of articulation are there?"},"options":["5","14","17","28"],"answer":2,"explain":{"bn":"৫টি এলাকায় মোট ১৭টি মাখরাজ।","en":"17 points spread over 5 areas."}},{"q":{"bn":"এই দুটি হরফ গলার কোন অংশ থেকে বের হয়?","en":"From which part of the throat do these two letters come?"},"ar":"ع ح","options":[{"bn":"গভীর অংশ","en":"Deepest part"},{"bn":"মাঝখান","en":"Middle"},{"bn":"উপরের অংশ","en":"Top part"}],"answer":1},{"q":{"bn":"{{ض}} কোথা থেকে বের হয়?","en":"Where does {{ض}} come from?"},"options":[{"bn":"ঠোঁট","en":"The lips"},{"bn":"জিহ্বার পাশ + উপরের মাড়ির দাঁত","en":"Side of the tongue + upper molars"},{"bn":"গলার মাঝখান","en":"Middle of the throat"}],"answer":1},{"q":{"bn":"কোন হরফ বলার সময় জিহ্বার আগা উপরের দাঁতের কিনারা ছোঁয়?","en":"For which letter does the tongue tip touch the edges of the upper front teeth?"},"options":["س","ث","ت"],"answer":1},{"q":{"bn":"খাইশূম (নাক) থেকে কী বের হয়?","en":"What comes from the khayshum (nose)?"},"options":[{"bn":"মাদ্দ","en":"Madd"},{"bn":"কলকলা","en":"Qalqalah"},{"bn":"গুন্নাহ","en":"Ghunnah"}],"answer":2},{"q":{"bn":"মাখরাজ যাচাই করতে হরফটিকে কোন অবস্থায় পড়তে হয়?","en":"To test a makhraj, the letter should be read with…"},"options":[{"bn":"যবর","en":"Fatha"},{"bn":"সাকিন (জযম)","en":"Sukun"},{"bn":"তানবীন","en":"Tanween"}],"answer":1,"explain":{"bn":"যেমন {{أَبْ}} — সাকিন হরফ নিজের জায়গায় থেমে থাকে।","en":"Like {{أَبْ}} — a sukun letter stays put in its place."}},{"q":{"bn":"{{و}} (মাদ্দ নয় এমন) উচ্চারণে ঠোঁট কী করে?","en":"What do the lips do for a non-madd {{و}}?"},"options":[{"bn":"গোল হয়, পুরো বন্ধ হয় না","en":"They round, without closing fully"},{"bn":"দাঁত নিচের ঠোঁটে লাগে","en":"Teeth touch the lower lip"},{"bn":"শক্ত করে চেপে বন্ধ হয়","en":"They press shut firmly"}],"answer":0}]}]},{"id":"tj-heavy-light","icon":"طَ","title":{"bn":"মোটা ও চিকন হরফ","en":"Heavy & Light Letters"},"subtitle":{"bn":"তাফখীম ও তারকীক, রা-এর নিয়ম ও আল্লাহ শব্দের লাম","en":"Tafkheem and tarqeeq, the rules of Ra, and the Lam in ‘Allah’"},"minutes":15,"goals":[{"bn":"৭টি সবসময়-মোটা হরফ মুখস্থ করব","en":"Memorise the 7 always-heavy letters"},{"bn":"রা কখন মোটা, কখন চিকন — চিনব","en":"Know when Ra is heavy and when it is light"},{"bn":"{{اللّٰه}} শব্দের লাম মোটা না চিকন — বুঝব","en":"Know when the Lam of {{اللّٰه}} is heavy or light"}],"blocks":[{"type":"text","bn":"কিছু হরফ পড়লে মুখ যেন আওয়াজে **ভরে যায়** — এগুলো মোটা (পুর) হরফ। একে বলে **তাফখীম** ({{تَفْخِيم}})। বাকি হরফগুলো হালকা, পাতলা — একে বলে **তারকীক** ({{تَرْقِيق}})। মোটা হরফ বলার সময় জিহ্বার গোড়া উপরের তালুর দিকে উঠে যায়।","en":"Some letters **fill the mouth** with sound — these are heavy letters. This is called **tafkheem** ({{تَفْخِيم}}). The rest are light and thin — called **tarqeeq** ({{تَرْقِيق}}). For a heavy letter, the back of the tongue rises towards the roof of the mouth."},{"type":"letters","title":{"bn":"সবসময় মোটা ৭টি হরফ (ইসতি‘লা)","en":"The 7 always-heavy letters (isti'la)"},"items":["kha","sad","dad","ghain","tta","qaf","zza"]},{"type":"tip","kind":"memory","bn":"সাতটি মোটা হরফ একটি ছোট্ট বাক্যে: {{خُصَّ ضَغْطٍ قِظْ}} (খুছ্‌ছা দ্বাগত্বিন ক্বিয্‌)। এই বাক্যের প্রতিটি হরফই মোটা!","en":"All 7 heavy letters in one short phrase: {{خُصَّ ضَغْطٍ قِظْ}} (khuṣṣa ḍaghṭin qiẓ). Every letter in it is heavy!"},{"type":"tip","kind":"fun","bn":"এর মধ্যে চারটি — {{ص ض ط ظ}} — সবচেয়ে বেশি মোটা। এদের বলার সময় জিহ্বা তালুর সাথে প্রায় ‘ঢাকনার’ মতো লেগে যায় (ইতবাক)।","en":"Four of them — {{ص ض ط ظ}} — are the heaviest. For these the tongue almost covers the palate like a lid (itbaq)."},{"type":"table","title":{"bn":"মোটা হরফেরও স্তর আছে","en":"Heavy letters have levels too"},"head":[{"bn":"স্তর","en":"Level"},{"bn":"অবস্থা","en":"When"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"১ (সবচেয়ে মোটা)","en":"1 (heaviest)"},{"bn":"যবর, পরে আলিফ","en":"Fatha followed by alif"},"طَا قَا"],[{"bn":"২","en":"2"},{"bn":"যবর","en":"Fatha"},"طَ قَ"],[{"bn":"৩","en":"3"},{"bn":"পেশ","en":"Damma"},"طُ قُ"],[{"bn":"৪","en":"4"},{"bn":"সাকিন","en":"Sukun"},"أَطْ أَقْ"],[{"bn":"৫ (সবচেয়ে কম)","en":"5 (least)"},{"bn":"যের — তবুও মোটা!","en":"Kasra — still heavy!"},"طِ قِ"]]},{"type":"tip","kind":"warn","bn":"মোটা মানে ঠোঁট গোল করা নয়! {{قَالَ}} হবে ‘ক্বা-লা’, ‘কো-লা’ নয়। ঠোঁট স্বাভাবিক রাখো, শুধু জিহ্বার গোড়া উপরে তোলো।","en":"Heavy does not mean rounding the lips! {{قَالَ}} is ‘qaala’, not ‘qoola’. Keep your lips relaxed — just raise the back of the tongue."},{"type":"compare","title":{"bn":"আলিফ আগের হরফকে অনুসরণ করে","en":"Alif follows the letter before it"},"items":[{"ar":"قَالَ","label":{"bn":"মোটা আলিফ","en":"Heavy alif"},"desc":{"bn":"{{ق}} মোটা, তাই পরের আলিফও মোটা","en":"{{ق}} is heavy, so the alif after it is heavy"}},{"ar":"كَانَ","label":{"bn":"চিকন আলিফ","en":"Light alif"},"desc":{"bn":"{{ك}} চিকন, তাই আলিফও চিকন","en":"{{ك}} is light, so the alif is light too"}}]},{"type":"text","title":{"bn":"রা ({{ر}}) — কখনো মোটা, কখনো চিকন","en":"Ra ({{ر}}) — sometimes heavy, sometimes light"},"bn":"সহজ সূত্র: **রা-এর নিজের হরকত দেখো।** যবর বা পেশ হলে মোটা, যের হলে চিকন। রা সাকিন হলে **তার আগের হরফের হরকত** দেখো।","en":"Simple formula: **look at Ra's own vowel.** Fatha or damma → heavy; kasra → light. If Ra has sukun, **look at the vowel of the letter before it**."},{"type":"examples","title":{"bn":"রা মোটা হয় যখন…","en":"Ra is heavy when…"},"items":[{"ar":"رَبِّ","hl":"رَ","tr":{"bn":"রব্বি","en":"rabbi"},"note":{"bn":"রা-তে যবর","en":"Ra has fatha"}},{"ar":"رُزِقُوا","hl":"رُ","tr":{"bn":"রুযিক্বূ","en":"ruziqoo"},"note":{"bn":"রা-তে পেশ","en":"Ra has damma"}},{"ar":"مَرْيَمَ","hl":"رْ","tr":{"bn":"মারইয়ামা","en":"maryama"},"note":{"bn":"রা সাকিন, আগে যবর","en":"Ra sakin after fatha"}},{"ar":"الْقُرْآنَ","hl":"رْ","tr":{"bn":"আলক্বুরআ-না","en":"al-qur'aana"},"note":{"bn":"রা সাকিন, আগে পেশ","en":"Ra sakin after damma"}},{"ar":"ارْجِعِي","hl":"رْ","tr":{"bn":"ইরজি‘ঈ","en":"irji'ee"},"note":{"bn":"আগের যের এসেছে শুরুর হামযা (হামযাতুল ওয়াসল) থেকে — এটা আসল যের নয়","en":"The kasra before it comes from a joining hamza (hamzat al-wasl) — not an original kasra"}},{"ar":"قِرْطَاسٍ","hl":"رْطَ","tr":{"bn":"ক্বিরত্বা-সিন","en":"qirṭaasin"},"note":{"bn":"আগে যের, কিন্তু পরে একই শব্দে মোটা হরফ {{ط}}","en":"Kasra before, but a heavy letter {{ط}} follows in the same word"}},{"ar":"وَالْعَصْرِ","hl":"صْرِ","tr":{"bn":"ওয়াল ‘আছর্‌ (থামলে)","en":"wal-'aṣr (at a stop)"},"note":{"bn":"থামলে রা সাকিন; আগের হরফ সাকিন, তার আগে যবর","en":"Stopping makes Ra sakin; the letter before is sakin, and before that a fatha"}}]},{"type":"examples","title":{"bn":"রা চিকন হয় যখন…","en":"Ra is light when…"},"items":[{"ar":"رِجَالٌ","hl":"رِ","tr":{"bn":"রিজা-লুন","en":"rijaalun"},"note":{"bn":"রা-তে যের","en":"Ra has kasra"}},{"ar":"فِرْعَوْنَ","hl":"رْ","tr":{"bn":"ফির‘আওনা","en":"fir'awna"},"note":{"bn":"রা সাকিন, আগে আসল যের, পরে মোটা হরফ নেই","en":"Ra sakin after an original kasra, no heavy letter after it"}},{"ar":"قَدِيرٌ","hl":"يرٌ","tr":{"bn":"ক্বাদীর্‌ (থামলে)","en":"qadeer (at a stop)"},"note":{"bn":"থামলে রা সাকিন, আগে সাকিন {{ي}}","en":"At a stop Ra is sakin with a sakin {{ي}} before it"}},{"ar":"حِجْرٍ","hl":"رٍ","tr":{"bn":"হিজর্‌ (থামলে)","en":"ḥijr (at a stop)"},"note":{"bn":"আগের হরফ সাকিন, তার আগে যের","en":"The letter before is sakin, and before that a kasra"}}]},{"type":"tip","kind":"memory","bn":"রা-এর ছড়া: **‘যবর-পেশে রা মোটা, যেরে রা চিকন; সাকিন হলে পেছন ফিরে দেখো তার আপনজন।’**","en":"Ra rhyme: **‘Fatha or damma — Ra is strong; kasra makes it thin; with sukun, look back one step to the vowel before it.’**"},{"type":"text","title":{"bn":"{{اللّٰه}} শব্দের লাম","en":"The Lam in {{اللّٰه}}"},"bn":"আল্লাহ শব্দের লাম সাধারণত চিকন হরফ, কিন্তু এখানে বিশেষ নিয়ম: আগে **যবর বা পেশ** থাকলে লাম **মোটা**; আগে **যের** থাকলে লাম **চিকন**। শব্দটি দিয়ে তিলাওয়াত শুরু করলেও (শুরুর হামযায় যবর) লাম মোটা।","en":"Lam is normally light, but ‘Allah’ has a special rule: after **fatha or damma** the Lam is **heavy**; after **kasra** it is **light**. When you start with the word (the opening hamza has fatha), the Lam is also heavy."},{"type":"compare","items":[{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","label":{"bn":"মোটা লাম","en":"Heavy Lam"},"desc":{"bn":"আগে {{وَ}}-তে যবর — ভরাট, গাঢ় আওয়াজ (কিন্তু ঠোঁট গোল নয়)","en":"Fatha on {{وَ}} before it — a full, deep sound (but no lip-rounding)"}},{"ar":"بِسْمِ اللّٰهِ","label":{"bn":"চিকন লাম","en":"Light Lam"},"desc":{"bn":"আগে {{مِ}}-তে যের — হালকা ‘লা’","en":"Kasra on {{مِ}} before it — a light ‘la’"}}]},{"type":"examples","items":[{"ar":"نَصْرُ اللّٰهِ","hl":"اللّٰهِ","tr":{"bn":"নাছরুল্লা-হ","en":"naṣrullaah"},"note":{"bn":"আগে পেশ → মোটা","en":"Damma before → heavy"}},{"ar":"شَهِدَ اللّٰهُ","hl":"اللّٰهُ","tr":{"bn":"শাহিদাল্লা-হু","en":"shahidallaahu"},"note":{"bn":"আগে যবর → মোটা","en":"Fatha before → heavy"}},{"ar":"الْحَمْدُ لِلّٰهِ","hl":"لِلّٰهِ","tr":{"bn":"আলহামদু লিল্লা-হ","en":"al-ḥamdu lillaah"},"note":{"bn":"আগে যের → চিকন","en":"Kasra before → light"}},{"ar":"بِاللّٰهِ","hl":"اللّٰهِ","tr":{"bn":"বিল্লা-হ","en":"billaah"},"note":{"bn":"আগে যের → চিকন","en":"Kasra before → light"}}]},{"type":"practice","bn":"প্রথমে মোটা হরফের স্তরগুলো, তারপর রা ও আল্লাহ শব্দের লাম অনুশীলন করো।","en":"First practise the levels of heavy letters, then Ra and the Lam of Allah.","lines":["خَا صَا ضَا غَا طَا قَا ظَا","خَ صَ ضَ غَ طَ قَ ظَ","خُ صُ ضُ غُ طُ قُ ظُ","خِ صِ ضِ غِ طِ قِ ظِ","رَبِّ رُزِقُوا مَرْيَمَ الْقُرْآنَ","رِجَالٌ فِرْعَوْنَ","قُلْ هُوَ اللّٰهُ بِسْمِ اللّٰهِ الْحَمْدُ لِلّٰهِ"]},{"type":"quiz","items":[{"q":{"bn":"নিচের কোনটি সবসময় মোটা হরফ?","en":"Which of these is always heavy?"},"options":["ك","ق","ت","س"],"answer":1},{"q":{"bn":"মোটা হরফের মনে রাখার বাক্যটি কোনটি?","en":"Which phrase holds all the heavy letters?"},"options":["خُصَّ ضَغْطٍ قِظْ","قُطْبُ جَدٍّ","يَرْمَلُونَ"],"answer":0},{"q":{"bn":"এখানে রা মোটা না চিকন?","en":"Is the Ra heavy or light here?"},"ar":"رِجَالٌ","options":[{"bn":"মোটা","en":"Heavy"},{"bn":"চিকন","en":"Light"}],"answer":1,"explain":{"bn":"রা-তে যের, তাই চিকন।","en":"Ra has kasra, so it is light."}},{"q":{"bn":"এখানে রা মোটা না চিকন?","en":"Is the Ra heavy or light here?"},"ar":"مَرْيَمَ","options":[{"bn":"মোটা","en":"Heavy"},{"bn":"চিকন","en":"Light"}],"answer":0,"explain":{"bn":"রা সাকিন, আগে যবর — তাই মোটা।","en":"Ra is sakin after fatha — so heavy."}},{"q":{"bn":"{{بِسْمِ اللّٰهِ}}-তে আল্লাহ শব্দের লাম কেমন?","en":"In {{بِسْمِ اللّٰهِ}}, how is the Lam of Allah?"},"options":[{"bn":"মোটা","en":"Heavy"},{"bn":"চিকন","en":"Light"}],"answer":1,"explain":{"bn":"আগে যের, তাই চিকন।","en":"Kasra before it, so light."}},{"q":{"bn":"যেরযুক্ত মোটা হরফ (যেমন {{قِ}}) কেমন হবে?","en":"A heavy letter with kasra (like {{قِ}}) is…"},"options":[{"bn":"চিকন হয়ে যায়","en":"Becomes light"},{"bn":"তবুও মোটা, তবে সবচেয়ে কম স্তরে","en":"Still heavy, at the lowest level"},{"bn":"গুন্নাহসহ পড়তে হয়","en":"Read with ghunnah"}],"answer":1},{"q":{"bn":"{{قَالَ}} শব্দের আলিফ কেমন?","en":"How is the alif in {{قَالَ}}?"},"options":[{"bn":"মোটা — আগের ক্বাফকে অনুসরণ করে","en":"Heavy — it follows the qaf"},{"bn":"সবসময় চিকন","en":"Always light"},{"bn":"উচ্চারণ হয় না","en":"Not pronounced"}],"answer":0}]}]},{"id":"tj-noon-sakinah","icon":"نْ","title":{"bn":"নূন সাকিন ও তানবীন","en":"Noon Sakinah & Tanween"},"subtitle":{"bn":"ইযহার, ইদগাম, ইকলাব, ইখফা — চারটি নিয়ম","en":"Izhar, Idgham, Iqlab, Ikhfa — the four rules"},"minutes":20,"goals":[{"bn":"বুঝব তানবীন আসলে একটি লুকানো নূন সাকিন","en":"Understand that tanween is really a hidden noon sakinah"},{"bn":"চারটি নিয়মের হরফগুলো চিনব","en":"Know the trigger letters of the four rules"},{"bn":"প্রতিটি নিয়ম কুরআনের শব্দে সঠিকভাবে পড়ব","en":"Apply each rule correctly in Quranic words"}],"blocks":[{"type":"text","bn":"তাজবীদের সবচেয়ে বেশি ব্যবহৃত নিয়ম এটি! **নূন সাকিন** মানে জযমওয়ালা নূন: {{نْ}}। **তানবীন** ({{ـً ـٍ ـٌ}}) লেখায় নূন নেই, কিন্তু উচ্চারণে শব্দের শেষে একটি নূন সাকিন লুকিয়ে থাকে। তাই দুটোর নিয়ম একই।","en":"This is the most-used tajweed rule! **Noon sakinah** is a noon with sukun: {{نْ}}. **Tanween** ({{ـً ـٍ ـٌ}}) has no noon in writing, but a noon sakinah hides at the end of the word when you say it. So both follow the same rules."},{"type":"compare","items":[{"ar":"عَلِيمٌ","label":{"bn":"যেভাবে লেখা","en":"As written"},"desc":{"bn":"শেষে দুই পেশ (তানবীন)","en":"Double damma (tanween) at the end"}},{"ar":"عَلِيمُنْ","label":{"bn":"যেভাবে শোনা যায়","en":"As it sounds"},"desc":{"bn":"পেশ + নূন সাকিন — ‘আলীমুন্‌’","en":"Damma + noon sakinah — ‘'aleemun’"}}]},{"type":"text","bn":"নূন সাকিন বা তানবীনের **পরের হরফটি** দেখে ঠিক করো কোন নিয়ম হবে। আরবির ২৮টি হরফ চার দলে ভাগ:","en":"Look at the **next letter** after the noon sakinah or tanween to decide the rule. The 28 Arabic letters fall into four groups:"},{"type":"table","head":[{"bn":"নিয়ম","en":"Rule"},{"bn":"হরফ","en":"Letters"},{"bn":"সংখ্যা","en":"Count"},{"bn":"কী হয়","en":"What happens"}],"rows":[[{"bn":"ইযহার (বেগুনি)","en":"Izhar (purple)"},"ء ه ع ح غ خ",{"bn":"৬","en":"6"},{"bn":"নূন স্পষ্ট","en":"Noon is clear"}],[{"bn":"ইদগাম (ধূসর)","en":"Idgham (gray)"},"ي ر م ل و ن",{"bn":"৬","en":"6"},{"bn":"নূন পরের হরফে মিশে যায়","en":"Noon merges into the next letter"}],[{"bn":"ইকলাব (নীল)","en":"Iqlab (blue)"},"ب",{"bn":"১","en":"1"},{"bn":"নূন মীমে বদলে যায়","en":"Noon turns into meem"}],[{"bn":"ইখফা (সবুজ)","en":"Ikhfa (green)"},"ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك",{"bn":"১৫","en":"15"},{"bn":"নূন লুকিয়ে নাকি সুরে","en":"Noon is hidden with a nasal hum"}]]},{"type":"tip","kind":"memory","bn":"অঙ্কটা মনে রাখো: **৬ + ৬ + ১ + ১৫ = ২৮** — সব হরফ ভাগ হয়ে গেল! গলার ৬টি হরফ হলে ইযহার, {{يَرْمَلُونَ}} শব্দের ৬টি হলে ইদগাম, {{ب}} হলে ইকলাব — বাকি সব ইখফা।","en":"Remember the sum: **6 + 6 + 1 + 15 = 28** — every letter is covered! Throat letters → Izhar; the 6 letters of {{يَرْمَلُونَ}} → Idgham; {{ب}} → Iqlab; everything else → Ikhfa."},{"type":"rule","name":{"bn":"ইযহার হালকী — স্পষ্ট করে পড়া","en":"Izhar Halqi — Clear Pronunciation"},"ar":"إِظْهَار حَلْقِي","color":"purple","letters":"ء ه ع ح غ خ","desc":{"bn":"নূন সাকিন বা তানবীনের পর গলার ৬টি হরফের কোনোটি এলে নূন **স্পষ্ট** উচ্চারণ হয়। গলার হরফ নূনের মাখরাজ থেকে অনেক দূরে, তাই মেশে না।","en":"When a noon sakinah or tanween is followed by one of the 6 throat letters, the noon is said **clearly**. Throat letters are far from noon's makhraj, so they do not blend."},"how":{"bn":"জিহ্বার আগা মাড়িতে লাগিয়ে পরিষ্কার ‘ন্‌’ বলো, গুন্নাহ টানবে না, থামবেও না — সোজা গলার হরফে চলে যাও।","en":"Touch the tongue tip to the gum and say a clean ‘n’ — no stretched ghunnah, no pause — then move straight to the throat letter."},"examples":[{"ar":"مَنْ آمَنَ","hl":"نْ آ","tr":{"bn":"মান আ-মানা","en":"man aamana"}},{"ar":"أَنْعَمْتَ","hl":"نْع","tr":{"bn":"আন‘আমতা","en":"an'amta"}},{"ar":"مِنْ خَوْفٍ","hl":"نْ خ","tr":{"bn":"মিন খাওফ","en":"min khawf"}},{"ar":"عَلِيمٌ حَكِيمٌ","hl":"مٌ ح","tr":{"bn":"‘আলীমুন হাকীম","en":"'aleemun ḥakeem"}},{"ar":"مِنْ غِلٍّ","hl":"نْ غ","tr":{"bn":"মিন গিল্ল","en":"min ghill"}}]},{"type":"rule","name":{"bn":"ইদগাম বা-গুন্নাহ — গুন্নাহসহ মিশিয়ে পড়া","en":"Idgham with Ghunnah — Merging with a Nasal Sound"},"ar":"إِدْغَام بِغُنَّة","color":"gray","letters":"ي ن م و","desc":{"bn":"পরে {{ي ن م و}} (মনে রাখো: {{يَنْمُو}} — ‘সে বাড়ে’) এলে নূন পরের হরফে **মিশে যায়**, আর দুই হরকত পরিমাণ গুন্নাহ হয়। শর্ত: নূন এক শব্দের শেষে, পরের হরফ পরের শব্দের শুরুতে।","en":"When followed by {{ي ن م و}} (remember {{يَنْمُو}} — ‘it grows’), the noon **merges** into the next letter with a ghunnah of 2 counts. Condition: the noon ends one word and the letter starts the next word."},"how":{"bn":"নূনকে আলাদা বলবে না। পরের হরফটি যেন তাশদীদওয়ালা — নাকে দুই হরকত সুর রেখে সেটিতে ঢুকে যাও।","en":"Do not say the noon separately. Treat the next letter as if it had shaddah — hum through the nose for 2 counts as you enter it."},"examples":[{"ar":"مَنْ يَقُولُ","hl":"نْ ي","tr":{"bn":"মাইঁ ইয়াক্বূলু","en":"may-yaqoolu"}},{"ar":"مِنْ نِعْمَةٍ","hl":"نْ ن","tr":{"bn":"মিনঁ নি‘মাতিন","en":"min-ni'matin"}},{"ar":"مِنْ مَاءٍ","hl":"نْ م","tr":{"bn":"মিমঁ মা-ইন","en":"mim-maa'in"}},{"ar":"مِنْ وَالٍ","hl":"نْ و","tr":{"bn":"মিওঁ ওয়া-ল","en":"miw-waal"}},{"ar":"خَيْرًا يَرَهُ","hl":"رًا ي","tr":{"bn":"খাইরাইঁ ইয়ারাহ","en":"khayray-yarah"}}]},{"type":"tip","kind":"warn","bn":"**ব্যতিক্রম:** নূন সাকিন আর {{ي}} বা {{و}} **একই শব্দে** থাকলে ইদগাম হয় না, নূন স্পষ্ট পড়তে হয়। কুরআনে এমন শব্দ মাত্র চারটি: {{الدُّنْيَا}}, {{بُنْيَانٌ}}, {{قِنْوَانٌ}}, {{صِنْوَانٌ}}। ‘দুনইয়া’ — ‘দুইঁয়া’ নয়!","en":"**Exception:** if the noon sakinah and {{ي}} or {{و}} are in the **same word**, there is no idgham — the noon stays clear. Only four such words occur in the Quran: {{الدُّنْيَا}}, {{بُنْيَانٌ}}, {{قِنْوَانٌ}}, {{صِنْوَانٌ}}. Say ‘dunyaa’, not ‘duyyaa’!"},{"type":"rule","name":{"bn":"ইদগাম বিলা-গুন্নাহ — গুন্নাহ ছাড়া মিশিয়ে পড়া","en":"Idgham without Ghunnah — Merging Without Nasal Sound"},"ar":"إِدْغَام بِلَا غُنَّة","color":"gray","letters":"ل ر","desc":{"bn":"পরে {{ل}} বা {{ر}} এলে নূন **পুরোপুরি** মিশে যায়, কোনো গুন্নাহ থাকে না। পরের হরফ তাশদীদসহ পড়া হয়।","en":"When followed by {{ل}} or {{ر}}, the noon merges **completely** with no ghunnah at all. The next letter is read with shaddah."},"how":{"bn":"নূনের কোনো চিহ্নই রাখবে না — সরাসরি দ্বিগুণ লাম বা দ্বিগুণ রা বলো।","en":"Leave no trace of the noon — go straight to a doubled lam or a doubled ra."},"examples":[{"ar":"مِنْ رَبِّهِمْ","hl":"نْ ر","tr":{"bn":"মির রব্বিহিম","en":"mir-rabbihim"}},{"ar":"هُدًى لِلْمُتَّقِينَ","hl":"دًى ل","tr":{"bn":"হুদাল লিলমুত্তাক্বীন","en":"hudal-lil-muttaqeen"}},{"ar":"غَفُورٌ رَحِيمٌ","hl":"رٌ ر","tr":{"bn":"গাফূরুর রহীম","en":"ghafoorur-raḥeem"}},{"ar":"وَلٰكِنْ لَا يَشْعُرُونَ","hl":"نْ ل","tr":{"bn":"ওয়ালা-কিল লা ইয়াশ‘উরূন","en":"wa laakil-laa yash'uroon"}}]},{"type":"tip","kind":"tip","title":{"bn":"মুসহাফ নিজেই ইশারা দেয়","en":"The mushaf gives you hints"},"bn":"আমাদের দেশের মুসহাফে ইযহারের নূনে জযম থাকে। ইদগামে নূনে জযম থাকে না, আর পরের হরফে তাশদীদ থাকে — যেমন {{مِنْ رَبِّهِمْ}} লেখা থাকে {{مِن رَّبِّهِمْ}}। ইকলাবে নূনের উপর ছোট্ট মীম থাকে। এই বইয়ে শেখার সুবিধার জন্য আমরা সব নূনে জযম দেখিয়েছি।","en":"In the mushaf used in our region, an izhar noon carries a sukun. For idgham the noon has no sukun and the next letter carries a shaddah — {{مِنْ رَبِّهِمْ}} appears as {{مِن رَّبِّهِمْ}}. For iqlab a tiny meem sits on the noon. In this book we show the sukun on every noon to make learning easier."},{"type":"tip","kind":"fun","bn":"হাফস রিওয়ায়াতে দুটি জায়গায় নূনের পরে {{و}} থাকলেও ইদগাম হয় না, ইযহার হয়: {{يٰسٓ وَالْقُرْآنِ}} ও {{نٓ وَالْقَلَمِ}} — সূরার শুরুর বিচ্ছিন্ন হরফে।","en":"In the Hafs reading there are two places where a noon is followed by {{و}} yet read with izhar, not idgham: {{يٰسٓ وَالْقُرْآنِ}} and {{نٓ وَالْقَلَمِ}} — in the disjointed letters at the start of those surahs."},{"type":"rule","name":{"bn":"ইকলাব — নূনকে মীমে বদলানো","en":"Iqlab — Turning Noon into Meem"},"ar":"إِقْلَاب","color":"blue","letters":"ب","desc":{"bn":"নূন সাকিন বা তানবীনের পর {{ب}} এলে নূন বদলে **মীম** হয়ে যায়, সাথে দুই হরকত গুন্নাহ।","en":"When a noon sakinah or tanween is followed by {{ب}}, the noon changes into a **meem**, with a 2-count ghunnah."},"how":{"bn":"‘ন্‌’-এর জায়গায় ‘ম্‌’ বলো, ঠোঁট আলতো করে মেলাও (চেপে নয়), নাকে দুই হরকত গুন্নাহ রাখো, তারপর {{ب}}।","en":"Say ‘m’ instead of ‘n’: close the lips gently (do not press), hum 2 counts through the nose, then say {{ب}}."},"examples":[{"ar":"مِنْ بَعْدِ","hl":"نْ ب","tr":{"bn":"মিমঁ বা‘দি","en":"mim-ba'di"}},{"ar":"أَنْبِئُونِي","hl":"نْب","tr":{"bn":"আমঁবিঊনী","en":"ambi'oonee"}},{"ar":"سَمِيعٌ بَصِيرٌ","hl":"عٌ ب","tr":{"bn":"সামী‘উমঁ বাছীর","en":"samee'um-baṣeer"}},{"ar":"لَيُنْبَذَنَّ","hl":"نْب","tr":{"bn":"লাইয়ুমঁবাযান্না","en":"layumbadhanna"}}]},{"type":"rule","name":{"bn":"ইখফা হাকীকী — লুকিয়ে পড়া","en":"Ikhfa Haqiqi — Hiding the Noon"},"ar":"إِخْفَاء حَقِيقِي","color":"green","letters":"ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك","desc":{"bn":"বাকি ১৫টি হরফের কোনোটি পরে এলে নূন পুরো স্পষ্টও না, পুরো মিশেও না — মাঝামাঝি **লুকানো** অবস্থায়, দুই হরকত গুন্নাহসহ পড়া হয়।","en":"Before any of the remaining 15 letters, the noon is neither fully clear nor fully merged — it is **hidden** in between, with a 2-count ghunnah."},"how":{"bn":"জিহ্বা নূনের জায়গায় শক্ত করে লাগাবে না; বরং পরের হরফের জায়গার দিকে তৈরি হয়ে যাও, নাকে দুই হরকত ‘ঁ’ সুর রাখো, তারপর হরফটি বলো।","en":"Do not press the tongue onto noon's place; get ready for the next letter's position, hum ‘ng-like’ through the nose for 2 counts, then say the letter."},"examples":[{"ar":"أَنْتَ","hl":"نْت","tr":{"bn":"আঁনতা","en":"anta (nasal)"}},{"ar":"يُنْفِقُونَ","hl":"نْف","tr":{"bn":"ইউঁনফিক্বূন","en":"yunfiqoon (nasal)"}},{"ar":"مِنْ قَبْلِ","hl":"نْ ق","tr":{"bn":"মিঁন ক্বাবলি","en":"min qabli (nasal)"}},{"ar":"مَنْ ذَا","hl":"نْ ذ","tr":{"bn":"মাঁন যা","en":"man dhaa (nasal)"}},{"ar":"رِيحًا صَرْصَرًا","hl":"حًا ص","tr":{"bn":"রীহাঁন ছারছারা","en":"reeḥan ṣarṣaraa (nasal)"}},{"ar":"يَنْطِقُ","hl":"نْط","tr":{"bn":"ইয়াঁনত্বিক্বু","en":"yanṭiqu (nasal)"}}]},{"type":"tip","kind":"memory","bn":"ইখফার ১৫টি হরফ একটি পুরনো আরবি পঙ্‌ক্তির প্রতিটি শব্দের প্রথম হরফে লুকানো: {{صِفْ ذَا ثَنَا كَمْ جَادَ شَخْصٌ قَدْ سَمَا دُمْ طَيِّبًا زِدْ فِي تُقًى ضَعْ ظَالِمَا}}। সহজ উপায়: ‘গলার নয়, {{يَرْمَلُونَ}}-এর নয়, {{ب}}-ও নয়? — তাহলে ইখফা!’","en":"The 15 ikhfa letters hide in the first letter of each word of a classic Arabic line: {{صِفْ ذَا ثَنَا كَمْ جَادَ شَخْصٌ قَدْ سَمَا دُمْ طَيِّبًا زِدْ فِي تُقًى ضَعْ ظَالِمَا}}. Easy way: ‘Not a throat letter, not in {{يَرْمَلُونَ}}, not {{ب}}? — then it's Ikhfa!’"},{"type":"compare","title":{"bn":"ইখফার গুন্নাহও মোটা-চিকন হয়","en":"Ikhfa's ghunnah can be heavy or light"},"items":[{"ar":"يَنْطِقُ","label":{"bn":"মোটা গুন্নাহ","en":"Heavy ghunnah"},"desc":{"bn":"পরে মোটা হরফ {{ط}} — গুন্নাহও গাঢ়, ভরাট","en":"A heavy letter {{ط}} follows — the hum is deep and full"}},{"ar":"أَنْتَ","label":{"bn":"চিকন গুন্নাহ","en":"Light ghunnah"},"desc":{"bn":"পরে চিকন হরফ {{ت}} — গুন্নাহও হালকা","en":"A light letter {{ت}} follows — the hum is light"}}]},{"type":"practice","bn":"প্রতিটি লাইনে একটি করে নিয়ম। আগে নিয়মটি বলো, তারপর পড়ো।","en":"One rule per line. Name the rule first, then read.","lines":["مَنْ آمَنَ أَنْعَمْتَ مِنْ خَوْفٍ عَلِيمٌ حَكِيمٌ","مَنْ يَقُولُ مِنْ مَاءٍ مِنْ وَالٍ خَيْرًا يَرَهُ","مِنْ رَبِّهِمْ غَفُورٌ رَحِيمٌ هُدًى لِلْمُتَّقِينَ","مِنْ بَعْدِ سَمِيعٌ بَصِيرٌ أَنْبِئُونِي","أَنْتَ يُنْفِقُونَ مِنْ قَبْلِ يَنْطِقُ","الدُّنْيَا بُنْيَانٌ قِنْوَانٌ صِنْوَانٌ"]},{"type":"quiz","items":[{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule applies here?"},"ar":"مِنْ بَعْدِ","options":[{"bn":"ইযহার","en":"Izhar"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"ইখফা","en":"Ikhfa"},{"bn":"ইদগাম","en":"Idgham"}],"answer":1},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule applies here?"},"ar":"مَنْ آمَنَ","options":[{"bn":"ইযহার","en":"Izhar"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"ইখফা","en":"Ikhfa"},{"bn":"ইদগাম","en":"Idgham"}],"answer":0,"explain":{"bn":"হামযা গলার হরফ।","en":"Hamza is a throat letter."}},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule applies here?"},"ar":"مِنْ قَبْلِ","options":[{"bn":"ইযহার","en":"Izhar"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"ইখফা","en":"Ikhfa"},{"bn":"ইদগাম","en":"Idgham"}],"answer":2},{"q":{"bn":"{{غَفُورٌ رَحِيمٌ}}-এ কী হয়?","en":"What happens in {{غَفُورٌ رَحِيمٌ}}?"},"options":[{"bn":"গুন্নাহসহ ইদগাম","en":"Idgham with ghunnah"},{"bn":"গুন্নাহ ছাড়া ইদগাম","en":"Idgham without ghunnah"},{"bn":"ইখফা","en":"Ikhfa"}],"answer":1,"explain":{"bn":"{{ر}} ও {{ل}}-এ গুন্নাহ ছাড়া ইদগাম।","en":"{{ر}} and {{ل}} take idgham without ghunnah."}},{"q":{"bn":"ইদগামের হরফ কোন শব্দে জমা?","en":"Which word gathers the idgham letters?"},"options":["يَرْمَلُونَ","قُطْبُ جَدٍّ","خُصَّ ضَغْطٍ قِظْ"],"answer":0},{"q":{"bn":"{{الدُّنْيَا}} শব্দে নূন কীভাবে পড়বে?","en":"How is the noon read in {{الدُّنْيَا}}?"},"options":[{"bn":"ইদগাম করে","en":"With idgham"},{"bn":"স্পষ্ট করে (ইযহার)","en":"Clearly (izhar)"},{"bn":"মীমে বদলে","en":"Changed to meem"}],"answer":1,"explain":{"bn":"নূন ও {{ي}} একই শব্দে — তাই ইদগাম নয়।","en":"Noon and {{ي}} are in the same word — so no idgham."}},{"q":{"bn":"ইখফার হরফ কয়টি?","en":"How many ikhfa letters are there?"},"options":["6","1","15","17"],"answer":2},{"q":{"bn":"তানবীনের পরে {{ي}} এলে কী হয়? যেমন {{خَيْرًا يَرَهُ}}","en":"What happens when tanween is followed by {{ي}}, as in {{خَيْرًا يَرَهُ}}?"},"options":[{"bn":"গুন্নাহসহ ইদগাম","en":"Idgham with ghunnah"},{"bn":"ইযহার","en":"Izhar"},{"bn":"ইকলাব","en":"Iqlab"}],"answer":0}]}]},{"id":"tj-meem-sakinah","icon":"مْ","title":{"bn":"মীম সাকিন","en":"Meem Sakinah"},"subtitle":{"bn":"ইখফা শাফাবী, ইদগাম শাফাবী ও ইযহার শাফাবী","en":"Ikhfa shafawi, idgham shafawi and izhar shafawi"},"minutes":12,"goals":[{"bn":"মীম সাকিনের তিনটি নিয়ম শিখব","en":"Learn the three rules of meem sakinah"},{"bn":"{{و}} ও {{ف}}-এর আগে মীম স্পষ্ট রাখতে শিখব","en":"Keep meem clear before {{و}} and {{ف}}"},{"bn":"সূরা ফীলে নিয়মগুলো খুঁজে বের করব","en":"Spot the rules in Surah al-Fil"}],"blocks":[{"type":"text","bn":"নূনের পর এবার মীমের পালা! **মীম সাকিন** ({{مْ}}) ঠোঁট থেকে বের হয়, তাই এর নিয়মগুলোর নামের সাথে ‘শাফাবী’ ({{شَفَوِي}} — ঠোঁটের) শব্দটি যুক্ত। মাত্র তিনটি নিয়ম — নূনের চেয়েও সহজ।","en":"After noon, it's meem's turn! **Meem sakinah** ({{مْ}}) comes from the lips, so its rules carry the word ‘shafawi’ ({{شَفَوِي}} — of the lips). Only three rules — even easier than noon."},{"type":"table","head":[{"bn":"পরের হরফ","en":"Next letter"},{"bn":"নিয়ম","en":"Rule"},{"bn":"রং","en":"Colour"}],"rows":[["ب",{"bn":"ইখফা শাফাবী — গুন্নাহসহ লুকানো","en":"Ikhfa shafawi — hidden with ghunnah"},{"bn":"সবুজ","en":"Green"}],["م",{"bn":"ইদগাম শাফাবী — মিশে এক মীম, গুন্নাহসহ","en":"Idgham shafawi — merged into one meem, with ghunnah"},{"bn":"ধূসর","en":"Gray"}],[{"bn":"বাকি ২৬টি হরফ","en":"The other 26 letters"},{"bn":"ইযহার শাফাবী — স্পষ্ট","en":"Izhar shafawi — clear"},{"bn":"বেগুনি","en":"Purple"}]]},{"type":"tip","kind":"memory","bn":"এক লাইনে: **‘বা এলে লুকাও, মীম এলে মেলাও, বাকি সবেতে স্পষ্ট দেখাও।’**","en":"In one line: **‘Ba? Hide it. Meem? Merge it. Anything else? Make it clear.’**"},{"type":"rule","name":{"bn":"ইখফা শাফাবী","en":"Ikhfa Shafawi"},"ar":"إِخْفَاء شَفَوِي","color":"green","letters":"ب","desc":{"bn":"মীম সাকিনের পর {{ب}} এলে মীমকে হালকাভাবে লুকিয়ে দুই হরকত গুন্নাহসহ পড়া হয়।","en":"When meem sakinah is followed by {{ب}}, the meem is gently hidden and read with a 2-count ghunnah."},"how":{"bn":"ঠোঁট আলতো করে মেলাও — চেপে ধরবে না। নাকে দুই হরকত সুর রেখে {{ب}}-এ যাও।","en":"Close the lips softly — do not press. Hum through the nose for 2 counts, then go to {{ب}}."},"examples":[{"ar":"تَرْمِيهِمْ بِحِجَارَةٍ","hl":"مْ ب","tr":{"bn":"তারমীহিমঁ বিহিজা-রাতিন","en":"tarmeehim biḥijaaratin"}},{"ar":"وَمَا هُمْ بِمُؤْمِنِينَ","hl":"مْ ب","tr":{"bn":"ওয়ামা হুমঁ বিমু'মিনীন","en":"wa maa hum bimu'mineen"}},{"ar":"يَعْتَصِمْ بِاللّٰهِ","hl":"مْ ب","tr":{"bn":"ইয়া‘তাছিমঁ বিল্লা-হ","en":"ya'taṣim billaah"}}]},{"type":"rule","name":{"bn":"ইদগাম শাফাবী (ইদগাম মিসলাইন)","en":"Idgham Shafawi (Idgham Mithlayn)"},"ar":"إِدْغَام شَفَوِي","color":"gray","letters":"م","desc":{"bn":"মীম সাকিনের পর আরেকটি মীম এলে দুটো মিশে একটি তাশদীদওয়ালা মীম হয়, দুই হরকত গুন্নাহসহ। একই হরফ দুবার — তাই একে ‘মিসলাইন’ (দুই সমান) বলে।","en":"When meem sakinah is followed by another meem, they merge into one meem with shaddah and a 2-count ghunnah. Two identical letters — hence ‘mithlayn’ (two alike)."},"how":{"bn":"ঠোঁট একবার মেলাও, নাকে দুই হরকত গুন্নাহ রাখো, তারপর ঠোঁট খুলে দ্বিতীয় মীমের হরকত বলো।","en":"Close the lips once, hum 2 counts, then open them with the second meem's vowel."},"examples":[{"ar":"فِي قُلُوبِهِمْ مَرَضٌ","hl":"مْ م","tr":{"bn":"ফী ক্বুলূবিহিমঁ মারাদ্বুন","en":"fee quloobihim-maraḍun"}},{"ar":"كَمْ مِنْ فِئَةٍ","hl":"مْ م","tr":{"bn":"কামঁ মিন ফিআতিন","en":"kam-min fi'atin"}},{"ar":"لَهُمْ مَا يَشَاءُونَ","hl":"مْ م","tr":{"bn":"লাহুমঁ মা ইয়াশা-ঊন","en":"lahum-maa yashaa'oon"}}]},{"type":"rule","name":{"bn":"ইযহার শাফাবী","en":"Izhar Shafawi"},"ar":"إِظْهَار شَفَوِي","color":"purple","letters":"ء ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل ن ه و ي","desc":{"bn":"{{ب}} ও {{م}} ছাড়া অন্য যেকোনো হরফ পরে এলে মীম **স্পষ্ট** পড়া হয়, কোনো অতিরিক্ত গুন্নাহ নেই।","en":"Before any letter other than {{ب}} and {{م}}, the meem is read **clearly**, with no extra ghunnah."},"how":{"bn":"ঠোঁট মিলিয়ে পরিষ্কার ‘ম্‌’ বলো, তারপর ঠোঁট খুলে পরের হরফে যাও। থামবে না, টানবে না।","en":"Close the lips for a clean ‘m’, then open them for the next letter. No pause, no stretch."},"examples":[{"ar":"الْحَمْدُ","hl":"مْد","tr":{"bn":"আলহামদু","en":"al-ḥamdu"}},{"ar":"أَنْعَمْتَ","hl":"مْت","tr":{"bn":"আন‘আমতা","en":"an'amta"}},{"ar":"هُمْ فِيهَا خَالِدُونَ","hl":"مْ ف","tr":{"bn":"হুম ফীহা খা-লিদূন","en":"hum feehaa khaalidoon"}},{"ar":"عَلَيْهِمْ وَلَا الضَّالِّينَ","hl":"مْ و","tr":{"bn":"‘আলাইহিম ওয়ালাদ্ দ্বা-ল্লীন","en":"'alayhim wa laḍ-ḍaalleen"}},{"ar":"لَمْ يَلِدْ","hl":"مْ ي","tr":{"bn":"লাম ইয়ালিদ","en":"lam yalid"}}]},{"type":"tip","kind":"warn","bn":"**সবচেয়ে বেশি সাবধান {{و}} ও {{ف}}-এর আগে!** {{و}} মীমের মতোই ঠোঁট থেকে আসে, আর {{ف}} খুব কাছের। তাই অনেকে এখানে মীম লুকিয়ে বা গুন্নাহ করে ফেলে — এটা ভুল। {{عَلَيْهِمْ وَلَا}}-তে মীম পরিষ্কার শোনাতে হবে।","en":"**Be most careful before {{و}} and {{ف}}!** {{و}} comes from the lips like meem, and {{ف}} is very close. Many people hide the meem or add ghunnah here — that is wrong. In {{عَلَيْهِمْ وَلَا}} the meem must be heard clearly."},{"type":"table","title":{"bn":"সূরা ফীলে নিয়ম খোঁজো","en":"Rule hunt in Surah al-Fil"},"head":[{"bn":"অংশ","en":"Phrase"},{"bn":"নিয়ম","en":"Rule"}],"rows":[["أَلَمْ تَرَ",{"bn":"ইযহার শাফাবী","en":"Izhar shafawi"}],["كَيْدَهُمْ فِي",{"bn":"ইযহার শাফাবী ({{ف}}-এর আগে!)","en":"Izhar shafawi (before {{ف}}!)"}],["طَيْرًا أَبَابِيلَ",{"bn":"ইযহার (তানবীন + হামযা)","en":"Izhar (tanween + hamza)"}],["تَرْمِيهِمْ بِحِجَارَةٍ",{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"}],["بِحِجَارَةٍ مِنْ",{"bn":"গুন্নাহসহ ইদগাম (তানবীন + মীম)","en":"Idgham with ghunnah (tanween + meem)"}],["مِنْ سِجِّيلٍ",{"bn":"ইখফা (নূন + সীন)","en":"Ikhfa (noon + seen)"}],["كَعَصْفٍ مَأْكُولٍ",{"bn":"গুন্নাহসহ ইদগাম","en":"Idgham with ghunnah"}]]},{"type":"practice","bn":"সূরা ফীল পড়ো। প্রতিটি মীম সাকিন ও নূন সাকিনে থেমে নিয়মটি মনে মনে বলো।","en":"Read Surah al-Fil. At every meem and noon sakinah, name the rule in your head.","lines":["أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ","أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ","وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","تَرْمِيهِمْ بِحِجَارَةٍ مِنْ سِجِّيلٍ","فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ"]},{"type":"quiz","items":[{"q":{"bn":"মীম সাকিনের নিয়ম কয়টি?","en":"How many rules does meem sakinah have?"},"options":["2","3","4"],"answer":1},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule applies here?"},"ar":"تَرْمِيهِمْ بِحِجَارَةٍ","options":[{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"},{"bn":"ইযহার শাফাবী","en":"Izhar shafawi"},{"bn":"ইকলাব","en":"Iqlab"}],"answer":0},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule applies here?"},"ar":"فِي قُلُوبِهِمْ مَرَضٌ","options":[{"bn":"ইযহার শাফাবী","en":"Izhar shafawi"},{"bn":"ইদগাম শাফাবী","en":"Idgham shafawi"},{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"}],"answer":1},{"q":{"bn":"{{هُمْ فِيهَا}}-তে মীম কীভাবে পড়বে?","en":"How is the meem read in {{هُمْ فِيهَا}}?"},"options":[{"bn":"লুকিয়ে, গুন্নাহসহ","en":"Hidden, with ghunnah"},{"bn":"পরিষ্কার, গুন্নাহ ছাড়া","en":"Clearly, without ghunnah"},{"bn":"ফা-এর সাথে মিশিয়ে","en":"Merged into the fa"}],"answer":1,"explain":{"bn":"{{ف}}-এর আগে ইযহার শাফাবী — বিশেষভাবে সাবধান!","en":"Before {{ف}} it is izhar shafawi — take extra care!"}},{"q":{"bn":"ইখফা শাফাবীতে ঠোঁট কেমন থাকে?","en":"In ikhfa shafawi, what do the lips do?"},"options":[{"bn":"আলতো করে মেলানো","en":"Closed gently"},{"bn":"শক্ত করে চাপা","en":"Pressed hard"},{"bn":"পুরো খোলা","en":"Wide open"}],"answer":0},{"q":{"bn":"‘শাফাবী’ শব্দের অর্থ কী?","en":"What does ‘shafawi’ mean?"},"options":[{"bn":"গলার","en":"Of the throat"},{"bn":"ঠোঁটের","en":"Of the lips"},{"bn":"নাকের","en":"Of the nose"}],"answer":1}]}]},{"id":"tj-ghunnah","icon":"نّ","title":{"bn":"গুন্নাহ — নাকের মধুর সুর","en":"Ghunnah — The Nasal Hum"},"subtitle":{"bn":"তাশদীদওয়ালা নূন ও মীম, দুই হরকত এবং নাক-চাপা পরীক্ষা","en":"Noon and meem with shaddah, two counts, and the nose-pinch test"},"minutes":10,"goals":[{"bn":"গুন্নাহ কী এবং কোথা থেকে বের হয় বুঝব","en":"Understand what ghunnah is and where it comes from"},{"bn":"{{نّ}} ও {{مّ}}-এ দুই হরকত গুন্নাহ করব","en":"Hold a 2-count ghunnah on {{نّ}} and {{مّ}}"},{"bn":"নিজের গুন্নাহ নিজে পরীক্ষা করতে শিখব","en":"Learn to test your own ghunnah"}],"blocks":[{"type":"text","bn":"**গুন্নাহ** ({{غُنَّة}}) হলো নাকের বাঁশি (খাইশূম) থেকে আসা মিষ্টি গুনগুন সুর। নূন ও মীমের মধ্যে এই সুর সবসময় একটু থাকে, কিন্তু যখন নূন বা মীমে **তাশদীদ** থাকে, তখন গুন্নাহ হয় পূর্ণ — **দুই হরকত** পরিমাণ।","en":"**Ghunnah** ({{غُنَّة}}) is the sweet humming sound from the nasal passage (khayshum). Noon and meem always carry a little of it, but when noon or meem has a **shaddah**, the ghunnah is full — **two counts** long."},{"type":"rule","name":{"bn":"গুন্নাহ মুশাদ্দাদ — তাশদীদওয়ালা নূন ও মীম","en":"Ghunnah Mushaddadah — Noon and Meem with Shaddah"},"ar":"غُنَّة مُشَدَّدَة","color":"green","letters":"نّ مّ","desc":{"bn":"যেখানেই {{نّ}} বা {{مّ}} দেখবে, সেখানে দুই হরকত গুন্নাহ — শব্দের মাঝে হোক বা শেষে, মিলিয়ে পড়ো বা থামো।","en":"Wherever you see {{نّ}} or {{مّ}}, hold a 2-count ghunnah — in the middle or end of a word, when joining or stopping."},"how":{"bn":"নূনের জন্য জিহ্বার আগা মাড়িতে, মীমের জন্য দুই ঠোঁট মিলিয়ে রাখো; আওয়াজ নাক দিয়ে দুই হরকত চলবে, তারপর পরের হরকতে ছেড়ে দাও।","en":"For noon keep the tongue tip on the gum, for meem keep the lips together; let the sound flow through the nose for 2 counts, then release into the next vowel."},"examples":[{"ar":"إِنَّ","hl":"نَّ","tr":{"bn":"ইন্‌ঁনা","en":"inna"}},{"ar":"ثُمَّ","hl":"مَّ","tr":{"bn":"ছুম্‌ঁমা","en":"thumma"}},{"ar":"النَّاسِ","hl":"نَّ","tr":{"bn":"আন্‌ঁনা-স","en":"an-naas"}},{"ar":"عَمَّ يَتَسَاءَلُونَ","hl":"مَّ","tr":{"bn":"‘আম্‌ঁমা ইয়াতাসা-আলূন","en":"'amma yatasaa'aloon"}},{"ar":"فَأُمُّهُ هَاوِيَةٌ","hl":"مُّ","tr":{"bn":"ফাউম্‌ঁমুহূ হা-ওইয়াহ","en":"fa ummuhoo haawiyah"}},{"ar":"الْجَنَّةَ","hl":"نَّ","tr":{"bn":"আলজান্‌ঁনাহ","en":"al-jannah"}}]},{"type":"text","title":{"bn":"দুই হরকত কতক্ষণ?","en":"How long is 2 counts?"},"bn":"এক **হরকত** = একটি ছোট হরকত (যেমন {{بَ}}) বলতে যতটুকু সময় লাগে। স্বাভাবিক গতিতে একটি আঙুল ভাঁজ করতে যে সময় লাগে, তা-ই এক হরকত। তাই গুন্নাহ = দুটি আঙুল ভাঁজ করার সময়। আমাদের দেশে অনেকে বলেন ‘এক আলিফ’ — এক আলিফ = দুই হরকত।","en":"One **count** (harakah) = the time it takes to say one short vowel (like {{بَ}}). Folding one finger at a normal pace takes about one count. So a ghunnah = the time to fold two fingers. In our region many teachers say ‘one alif’ — one alif = two counts."},{"type":"tip","kind":"tip","title":{"bn":"নাক-চাপা পরীক্ষা","en":"The nose-pinch test"},"bn":"{{إِنَّ}} বলতে বলতে গুন্নাহর সময় আঙুল দিয়ে নাক চেপে ধরো। আওয়াজ যদি **আটকে যায়** — অভিনন্দন, গুন্নাহ ঠিক নাক দিয়ে আসছে! আর যদি আওয়াজ বদলায় না, তার মানে তুমি গুন্নাহ করছ না।","en":"Say {{إِنَّ}} and pinch your nose during the hum. If the sound **gets blocked** — congratulations, your ghunnah really comes through the nose! If the sound does not change, you are not making a ghunnah."},{"type":"table","title":{"bn":"গুন্নাহ কখন পূর্ণ, কখন সামান্য","en":"When ghunnah is full and when it is slight"},"head":[{"bn":"অবস্থা","en":"Situation"},{"bn":"উদাহরণ","en":"Example"},{"bn":"গুন্নাহ","en":"Ghunnah"}],"rows":[[{"bn":"তাশদীদওয়ালা নূন/মীম","en":"Noon/meem with shaddah"},"إِنَّ ثُمَّ",{"bn":"পূর্ণ — ২ হরকত","en":"Full — 2 counts"}],[{"bn":"গুন্নাহসহ ইদগাম ও ইদগাম শাফাবী","en":"Idgham with ghunnah & idgham shafawi"},"مَنْ يَقُولُ",{"bn":"পূর্ণ — ২ হরকত","en":"Full — 2 counts"}],[{"bn":"ইখফা, ইকলাব, ইখফা শাফাবী","en":"Ikhfa, iqlab, ikhfa shafawi"},"أَنْتَ مِنْ بَعْدِ",{"bn":"পূর্ণ — ২ হরকত","en":"Full — 2 counts"}],[{"bn":"ইযহারের নূন/মীম সাকিন","en":"Noon/meem sakinah with izhar"},"مِنْ خَوْفٍ",{"bn":"সামান্য — টান নেই","en":"Slight — no holding"}],[{"bn":"হরকতওয়ালা নূন/মীম","en":"Noon/meem with a vowel"},"نَ مَ",{"bn":"সামান্য — টান নেই","en":"Slight — no holding"}]]},{"type":"compare","title":{"bn":"তাশদীদ থাকলেই কি গুন্নাহ?","en":"Does every shaddah get ghunnah?"},"items":[{"ar":"إِنَّ","label":{"bn":"হ্যাঁ — নূনে তাশদীদ","en":"Yes — shaddah on noon"},"desc":{"bn":"দ্বিগুণ নূন + দুই হরকত নাকি সুর","en":"Doubled noon + 2-count nasal hum"}},{"ar":"الَّذِينَ","label":{"bn":"না — লামে তাশদীদ","en":"No — shaddah on lam"},"desc":{"bn":"শুধু লাম দ্বিগুণ হবে, নাকে কোনো সুর নয়","en":"Just a doubled lam, no nasal hum"}}]},{"type":"tip","kind":"memory","bn":"**তাশদীদ + ন বা ম = নাকে দুই হরকতের গান।** অন্য হরফে তাশদীদ = শুধু দ্বিগুণ, গান নেই।","en":"**Shaddah + noon or meem = a 2-count song in the nose.** Shaddah on any other letter = just doubled, no song."},{"type":"compare","title":{"bn":"বাংলাভাষীদের সাধারণ ভুল","en":"A common slip for Bangla speakers"},"items":[{"ar":"ثُمَّ","label":{"bn":"সঠিক","en":"Correct"},"desc":{"bn":"‘ছুম্‌ঁমা’ — মীম দ্বিগুণ, গুন্নাহসহ","en":"‘thum-ma’ — doubled meem with ghunnah"}},{"ar":"ثُمَ","label":{"bn":"ভুল","en":"Wrong"},"desc":{"bn":"‘সুমা’ — তাশদীদ ও গুন্নাহ দুটোই হারিয়ে গেছে","en":"‘suma’ — both the shaddah and the ghunnah are lost"}}]},{"type":"tip","kind":"warn","bn":"গুন্নাহ দুই হরকতের বেশি টানবে না, আর গুন্নাহর আগের-পরের হরকতকেও নাকি করবে না। ‘ইন্না’ বলতে গিয়ে ‘ইঁইঁন্না’ নয়!","en":"Do not stretch the ghunnah beyond 2 counts, and do not nasalise the vowels around it. Not ‘iiin-na’!"},{"type":"practice","bn":"সূরা নাস পড়ো — প্রতিটি {{نَّ}}-তে দুই আঙুল ভাঁজ করো।","en":"Read Surah an-Nas — fold two fingers on every {{نَّ}}.","lines":["إِنَّ ثُمَّ عَمَّ لَمَّا جَنَّةٍ","قُلْ أَعُوذُ بِرَبِّ النَّاسِ","مَلِكِ النَّاسِ","إِلٰهِ النَّاسِ","مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ","الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ","مِنَ الْجِنَّةِ وَالنَّاسِ"]},{"type":"quiz","items":[{"q":{"bn":"গুন্নাহ কোথা থেকে বের হয়?","en":"Where does ghunnah come from?"},"options":[{"bn":"গলা","en":"The throat"},{"bn":"নাকের বাঁশি (খাইশূম)","en":"The nasal passage (khayshum)"},{"bn":"ঠোঁট","en":"The lips"}],"answer":1},{"q":{"bn":"তাশদীদওয়ালা নূনে গুন্নাহ কতক্ষণ?","en":"How long is the ghunnah on a noon with shaddah?"},"options":[{"bn":"১ হরকত","en":"1 count"},{"bn":"২ হরকত","en":"2 counts"},{"bn":"৬ হরকত","en":"6 counts"}],"answer":1},{"q":{"bn":"কোন শব্দে পূর্ণ গুন্নাহ আছে?","en":"Which word has a full ghunnah?"},"options":["الَّذِينَ","ثُمَّ","رَبِّ"],"answer":1,"explain":{"bn":"{{ثُمَّ}}-এ তাশদীদওয়ালা মীম।","en":"{{ثُمَّ}} has a meem with shaddah."}},{"q":{"bn":"নাক চেপে ধরলে গুন্নাহর আওয়াজ কী হওয়া উচিত?","en":"When you pinch your nose, what should happen to the ghunnah?"},"options":[{"bn":"আটকে যাবে","en":"It gets blocked"},{"bn":"কোনো পরিবর্তন হবে না","en":"Nothing changes"},{"bn":"আরও জোরে হবে","en":"It gets louder"}],"answer":0},{"q":{"bn":"এক আলিফ সমান কত হরকত?","en":"One ‘alif’ equals how many counts?"},"options":["1","2","4"],"answer":1},{"q":{"bn":"{{مِنْ خَوْفٍ}}-এর নূনে গুন্নাহ কেমন?","en":"How is the ghunnah on the noon in {{مِنْ خَوْفٍ}}?"},"options":[{"bn":"পূর্ণ, ২ হরকত","en":"Full, 2 counts"},{"bn":"সামান্য, টান নেই","en":"Slight, not held"},{"bn":"মীমে বদলে যায়","en":"Turns into meem"}],"answer":1,"explain":{"bn":"{{خ}} গলার হরফ — ইযহার।","en":"{{خ}} is a throat letter — izhar."}}]}]},{"id":"tj-qalqalah","icon":"قْ","title":{"bn":"কলকলা — প্রতিধ্বনির হরফ","en":"Qalqalah — The Echoing Letters"},"subtitle":{"bn":"{{قُطْبُ جَدٍّ}}-এর পাঁচ হরফ, ছোট ও বড় কলকলা","en":"The five letters of {{قُطْبُ جَدٍّ}}, minor and major qalqalah"},"minutes":10,"goals":[{"bn":"কলকলার ৫টি হরফ মুখস্থ করব","en":"Memorise the 5 qalqalah letters"},{"bn":"ছোট (সুগরা) ও বড় (কুবরা) কলকলার পার্থক্য বুঝব","en":"Tell minor (sughra) from major (kubra) qalqalah"},{"bn":"হরকত যোগ না করে প্রতিধ্বনি দিতে শিখব","en":"Make the echo without adding a vowel"}],"blocks":[{"type":"text","bn":"কিছু হরফ সাকিন হলে মুখে আটকে গিয়ে প্রায় হারিয়ে যায়। তাই এদের একটু **ঝাঁকুনি / প্রতিধ্বনি** দিয়ে পড়তে হয় — যেন বল মাটিতে পড়ে একটু লাফিয়ে ওঠে। একে বলে **কলকলা** ({{قَلْقَلَة}})।","en":"Some letters, when they have sukun, get trapped in the mouth and almost disappear. So we give them a little **bounce / echo** — like a ball that hits the ground and springs up slightly. This is called **qalqalah** ({{قَلْقَلَة}})."},{"type":"letters","title":{"bn":"কলকলার ৫টি হরফ","en":"The 5 qalqalah letters"},"items":["qaf","tta","ba","jim","dal"]},{"type":"tip","kind":"memory","bn":"পাঁচটি হরফ এক শব্দজোড়ায়: {{قُطْبُ جَدٍّ}} (ক্বুত্বুবু জাদ্দিন)। বাংলায় মনে রাখো: **‘কলকলা = বল লাফানো’**।","en":"All five in one phrase: {{قُطْبُ جَدٍّ}} (quṭbu jaddin). Picture it: **‘qalqalah = a bouncing ball’**."},{"type":"tip","kind":"fun","bn":"কেন এই পাঁচটি? এদের উচ্চারণে বাতাসও আটকে যায়, আওয়াজও আটকে যায়। সাকিন অবস্থায় প্রতিধ্বনি না দিলে এরা শোনাই যেত না!","en":"Why these five? When you say them, both the air and the voice are blocked. With sukun and no echo, you would hardly hear them at all!"},{"type":"rule","name":{"bn":"কলকলা সুগরা — ছোট কলকলা","en":"Qalqalah Sughra — Minor Echo"},"ar":"قَلْقَلَة صُغْرٰى","color":"orange","letters":"ق ط ب ج د","desc":{"bn":"হরফটি শব্দের মাঝে সাকিন, অথবা শব্দের শেষে সাকিন কিন্তু তুমি থামছ না — তখন হালকা প্রতিধ্বনি।","en":"The letter has sukun in the middle of a word, or at the end of a word while you keep reading — a light echo."},"how":{"bn":"হরফটি তার মাখরাজে আটকাও, তারপর হালকা ঝটকায় ছেড়ে দাও — ছোট্ট একটি প্রতিধ্বনি, সাথে সাথে পরের হরফ।","en":"Close the letter at its makhraj, then release it with a light snap — a tiny echo, straight into the next letter."},"examples":[{"ar":"خَلَقْنَا","hl":"قْ","tr":{"bn":"খালাক্ব্‌না","en":"khalaqnaa"}},{"ar":"يَجْعَلُونَ","hl":"جْ","tr":{"bn":"ইয়াজ্‌‘আলূন","en":"yaj'aloon"}},{"ar":"قَدْ أَفْلَحَ","hl":"دْ","tr":{"bn":"ক্বাদ্‌ আফলাহা","en":"qad aflaḥa"}},{"ar":"أَطْعَمَهُمْ","hl":"طْ","tr":{"bn":"আত্ব্‌‘আমাহুম","en":"aṭ'amahum"}},{"ar":"سُبْحَانَ","hl":"بْ","tr":{"bn":"সুব্‌হা-না","en":"subḥaana"}}]},{"type":"rule","name":{"bn":"কলকলা কুবরা — বড় কলকলা","en":"Qalqalah Kubra — Major Echo"},"ar":"قَلْقَلَة كُبْرٰى","color":"orange","letters":"ق ط ب ج د","desc":{"bn":"শব্দের শেষে কলকলার হরফে **থামলে** হরফটি সাকিন হয়, আর প্রতিধ্বনি হয় আরও স্পষ্ট। হরফে তাশদীদ থাকলে (যেমন {{وَتَبَّ}}) প্রতিধ্বনি সবচেয়ে জোরালো।","en":"When you **stop** on a qalqalah letter at the end of a word, it becomes sakin and the echo is stronger. If the letter has shaddah (like {{وَتَبَّ}}), the echo is the strongest of all."},"how":{"bn":"থামার সময় শেষ হরফটি স্পষ্ট লাফিয়ে ছাড়ো — কিন্তু কোনো যবর/যের/পেশ যোগ করবে না।","en":"As you stop, release the last letter with a clear bounce — but add no fatha, kasra or damma."},"examples":[{"ar":"الْفَلَقِ","hl":"قِ","tr":{"bn":"আলফালাক্ব্‌","en":"al-falaq"}},{"ar":"أَحَدٌ","hl":"دٌ","tr":{"bn":"আহাদ্‌","en":"aḥad"}},{"ar":"مُحِيطٌ","hl":"طٌ","tr":{"bn":"মুহীত্ব্‌","en":"muḥeeṭ"}},{"ar":"الْبُرُوجِ","hl":"جِ","tr":{"bn":"আলবুরূজ্‌","en":"al-burooj"}},{"ar":"وَتَبَّ","hl":"بَّ","tr":{"bn":"ওয়াতাব্ব্‌","en":"wa tabb"}}]},{"type":"compare","title":{"bn":"থামার সময় {{أَحَدٌ}} কীভাবে?","en":"Stopping on {{أَحَدٌ}} — how?"},"items":[{"ar":"أَحَدْ","label":{"bn":"সঠিক","en":"Correct"},"desc":{"bn":"‘আহাদ্‌’ — দাল-এ ছোট্ট লাফ, কোনো স্বর নেই","en":"‘aḥad’ — a small bounce on dal, no vowel"}},{"ar":"أَحَدَا","label":{"bn":"ভুল — স্বর যোগ","en":"Wrong — vowel added"},"desc":{"bn":"‘আহাদা’ বা ‘আহাদে’ — প্রতিধ্বনিকে পুরো হরকত বানিয়ে ফেলা","en":"‘aḥada’ or ‘aḥade’ — turning the echo into a full vowel"}},{"ar":"أَحَدْ","label":{"bn":"ভুল — গিলে ফেলা","en":"Wrong — swallowed"},"desc":{"bn":"দাল আটকে রেখে ছাড়া হয়নি — শেষটা শোনাই যায় না","en":"Dal is held and never released — the ending is lost"}}]},{"type":"tip","kind":"fun","bn":"সূরা ফালাকের প্রতিটি আয়াতের শেষ হরফ কলকলার হরফ: {{الْفَلَقِ}}, {{خَلَقَ}}, {{وَقَبَ}}, {{الْعُقَدِ}}, {{حَسَدَ}}। আর সূরা ইখলাসের চারটি আয়াতই শেষ হয় {{د}} দিয়ে! থামার সময় প্রতিটিতে বড় কলকলা।","en":"Every ayah of Surah al-Falaq ends in a qalqalah letter: {{الْفَلَقِ}}, {{خَلَقَ}}, {{وَقَبَ}}, {{الْعُقَدِ}}, {{حَسَدَ}}. And all four ayahs of Surah al-Ikhlas end in {{د}}! Each stop gets a major qalqalah."},{"type":"ayah","ref":"113:1","ar":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","words":[{"ar":"قُلْ","bn":"বলো","en":"say"},{"ar":"أَعُوذُ","bn":"আমি আশ্রয় চাই","en":"I seek refuge"},{"ar":"بِرَبِّ","bn":"রবের কাছে","en":"in the Lord of"},{"ar":"الْفَلَقِ","bn":"প্রভাতের","en":"the daybreak"}],"tr":{"bn":"ক্বুল আ‘ঊযু বিরব্বিল ফালাক্ব্‌","en":"qul a'oodhu birabbil-falaq"},"mean":{"bn":"বলো, আমি আশ্রয় চাই প্রভাতের রবের কাছে।","en":"Say: I seek refuge in the Lord of the daybreak."}},{"type":"practice","bn":"সূরা ফালাক ও ইখলাস পড়ো। প্রতিটি আয়াতের শেষে থেমে বড় কলকলা দাও।","en":"Read Surahs al-Falaq and al-Ikhlas. Stop at the end of each ayah with a major qalqalah.","lines":["أَقْ أَطْ أَبْ أَجْ أَدْ","قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","مِنْ شَرِّ مَا خَلَقَ","وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ","وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ","وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ","قُلْ هُوَ اللّٰهُ أَحَدٌ اللّٰهُ الصَّمَدُ","لَمْ يَلِدْ وَلَمْ يُولَدْ"]},{"type":"quiz","items":[{"q":{"bn":"কোনটি কলকলার হরফ নয়?","en":"Which is NOT a qalqalah letter?"},"options":["ق","ط","ك","د"],"answer":2},{"q":{"bn":"কলকলা কখন হয়?","en":"When does qalqalah happen?"},"options":[{"bn":"হরফে যবর থাকলে","en":"When the letter has fatha"},{"bn":"হরফ সাকিন হলে (বা থামলে)","en":"When the letter has sukun (or at a stop)"},{"bn":"হরফে তানবীন থাকলে","en":"When the letter has tanween"}],"answer":1},{"q":{"bn":"{{قَدْ أَفْلَحَ}}-এ কোন কলকলা?","en":"Which qalqalah is in {{قَدْ أَفْلَحَ}}?"},"options":[{"bn":"সুগরা (ছোট)","en":"Sughra (minor)"},{"bn":"কুবরা (বড়)","en":"Kubra (major)"},{"bn":"কলকলা নেই","en":"No qalqalah"}],"answer":0,"explain":{"bn":"দাল সাকিন, কিন্তু আমরা থামছি না।","en":"Dal has sukun, but we are not stopping."}},{"q":{"bn":"{{الْفَلَقِ}}-এ থামলে কী হবে?","en":"What happens when you stop on {{الْفَلَقِ}}?"},"options":[{"bn":"বড় কলকলা","en":"Major qalqalah"},{"bn":"গুন্নাহ","en":"Ghunnah"},{"bn":"ছয় হরকত মাদ্দ","en":"A 6-count madd"}],"answer":0},{"q":{"bn":"কলকলার সবচেয়ে জোরালো রূপ কোনটিতে?","en":"Where is qalqalah strongest?"},"options":["يَجْعَلُونَ","أَحَدٌ","وَتَبَّ"],"answer":2,"explain":{"bn":"থামার সময় তাশদীদওয়ালা কলকলার হরফ।","en":"A qalqalah letter with shaddah at a stop."}},{"q":{"bn":"কলকলা করার সময় কোন ভুলটি সবচেয়ে বেশি হয়?","en":"What is the most common qalqalah mistake?"},"options":[{"bn":"শেষে যবর/যের যোগ করে ফেলা","en":"Adding a fatha/kasra at the end"},{"bn":"গুন্নাহ না করা","en":"Skipping ghunnah"},{"bn":"রা মোটা করা","en":"Making ra heavy"}],"answer":0}]}]},{"id":"tj-madd","icon":"ـٓا","title":{"bn":"মাদ্দ — টেনে পড়ার নিয়ম","en":"Madd — The Rules of Stretching"},"subtitle":{"bn":"২, ৪–৫ নাকি ৬ হরকত? মাদ্দের প্রকারভেদ","en":"2, 4–5 or 6 counts? The types of madd"},"minutes":20,"goals":[{"bn":"মাদ্দের হরফ ও লীনের হরফ চিনব","en":"Recognise the madd letters and the leen letters"},{"bn":"ছয় ধরনের মাদ্দ ও তাদের দৈর্ঘ্য জানব","en":"Learn six types of madd and their lengths"},{"bn":"হরকত গুনে সমান মাপে টানতে শিখব","en":"Stretch evenly by counting"}],"blocks":[{"type":"text","bn":"**মাদ্দ** ({{مَدّ}}) মানে টেনে লম্বা করা। আরবিতে তিনটি **মাদ্দের হরফ**: যবরের পর {{ا}}, পেশের পর সাকিন {{و}}, যেরের পর সাকিন {{ي}}। আর যবরের পর সাকিন {{و}} বা {{ي}}-কে বলে **লীনের হরফ** (নরম হরফ) — যেমন {{خَوْفٍ}}, {{بَيْتِ}}।","en":"**Madd** ({{مَدّ}}) means stretching. Arabic has three **madd letters**: {{ا}} after fatha, sakin {{و}} after damma, and sakin {{ي}} after kasra. A sakin {{و}} or {{ي}} after fatha is called a **leen letter** (soft letter) — as in {{خَوْفٍ}}, {{بَيْتِ}}."},{"type":"text","bn":"মাদ্দ কতটা লম্বা হবে তা ঠিক করে মাদ্দের হরফের **পরে কী আছে**: কিছু না থাকলে ২ হরকত; পরে **হামযা** থাকলে ৪–৫; পরে **সুকুন** থাকলে ৬ (স্থায়ী) বা ২/৪/৬ (থামার কারণে)।","en":"The length of a madd depends on **what comes after** the madd letter: nothing special → 2 counts; a **hamza** → 4–5; a **sukun** → 6 (permanent) or 2/4/6 (caused by stopping)."},{"type":"table","title":{"bn":"মাদ্দের মানচিত্র","en":"The madd map"},"head":[{"bn":"মাদ্দ","en":"Madd"},{"bn":"কারণ","en":"Cause"},{"bn":"উদাহরণ","en":"Example"},{"bn":"হরকত","en":"Counts"}],"rows":[[{"bn":"তবঈ (স্বাভাবিক)","en":"Tabee'i (natural)"},{"bn":"পরে হামযা বা সুকুন নেই","en":"No hamza or sukun after"},"قَالَ قِيلَ يَقُولُ",{"bn":"২ (১ আলিফ)","en":"2 (1 alif)"}],[{"bn":"মুত্তাসিল (ওয়াজিব)","en":"Muttasil (obligatory)"},{"bn":"একই শব্দে পরে হামযা","en":"Hamza after it in the same word"},"جَاءَ السَّمَاءِ",{"bn":"৪–৫","en":"4–5"}],[{"bn":"মুনফাসিল (জায়েয)","en":"Munfasil (permissible)"},{"bn":"শব্দের শেষে মাদ্দ, পরের শব্দের শুরুতে হামযা","en":"Madd ends a word, hamza starts the next"},"يَا أَيُّهَا",{"bn":"৪–৫","en":"4–5"}],[{"bn":"লাযিম (আবশ্যিক)","en":"Lazim (necessary)"},{"bn":"পরে স্থায়ী সুকুন বা তাশদীদ","en":"Permanent sukun or shaddah after"},"الضَّالِّينَ الٓمٓ",{"bn":"৬ (৩ আলিফ)","en":"6 (3 alif)"}],[{"bn":"আরিদ লিস-সুকুন","en":"'Arid lis-sukun"},{"bn":"থামার কারণে শেষ হরফ সাকিন","en":"Last letter made sakin by stopping"},"نَسْتَعِينُ",{"bn":"২, ৪ বা ৬","en":"2, 4 or 6"}],[{"bn":"লীন","en":"Leen"},{"bn":"লীনের হরফের পর থামা","en":"Stopping after a leen letter"},"خَوْفٍ الْبَيْتِ",{"bn":"২, ৪ বা ৬ (শুধু থামলে)","en":"2, 4 or 6 (only at a stop)"}]]},{"type":"tip","kind":"memory","bn":"সহজ মাপ: **কিছু নেই → ২, হামযা → ৪–৫, সুকুন → ৬।** আর এক আলিফ = দুই হরকত, তাই ৬ হরকত = ‘তিন আলিফ’।","en":"Quick measure: **nothing → 2, hamza → 4–5, sukun → 6.** And one alif = two counts, so 6 counts = ‘three alifs’."},{"type":"rule","name":{"bn":"মাদ্দ তবঈ — স্বাভাবিক মাদ্দ","en":"Madd Tabee'i — Natural Madd"},"ar":"مَدّ طَبِيعِي","color":"red","letters":"ا و ي","desc":{"bn":"মাদ্দের হরফের পরে হামযা বা সুকুন নেই — শুধু ২ হরকত। খাড়া যবরও ({{ـٰ}}) এই মাদ্দ, যেমন {{الرَّحْمٰنِ}}।","en":"No hamza or sukun after the madd letter — just 2 counts. A standing fatha ({{ـٰ}}) is also this madd, as in {{الرَّحْمٰنِ}}."},"how":{"bn":"ঠিক দুই হরকত — এর কম হলে হরফ হারিয়ে যায় (লাহনে জলী!), বেশি হলে টান অসুন্দর।","en":"Exactly 2 counts — shorter and the letter disappears (a clear mistake!), longer and it sounds unnatural."},"examples":[{"ar":"قَالَ","hl":"قَا","tr":{"bn":"ক্বা-লা","en":"qaala"}},{"ar":"قِيلَ","hl":"قِي","tr":{"bn":"ক্বী-লা","en":"qeela"}},{"ar":"يَقُولُ","hl":"قُو","tr":{"bn":"ইয়াক্বূ-লু","en":"yaqoolu"}},{"ar":"الرَّحْمٰنِ","hl":"مٰ","tr":{"bn":"আররহমা-নি","en":"ar-raḥmaani"}}]},{"type":"rule","name":{"bn":"মাদ্দ মুত্তাসিল — যুক্ত মাদ্দ","en":"Madd Muttasil — Connected Madd"},"ar":"مَدّ مُتَّصِل","color":"red","desc":{"bn":"মাদ্দের হরফ আর হামযা **একই শব্দে**। সব কারীর মতেই এটা লম্বা করা ওয়াজিব — হাফসে ৪ বা ৫ হরকত।","en":"The madd letter and hamza are in the **same word**. All reciters lengthen it, so it is called obligatory — 4 or 5 counts in Hafs."},"how":{"bn":"হামযার আগে মাদ্দ ৪–৫ হরকত টানো, তারপর হামযা পরিষ্কার উচ্চারণ করো।","en":"Stretch 4–5 counts before the hamza, then pronounce the hamza cleanly."},"examples":[{"ar":"جَاءَ","hl":"جَاء","tr":{"bn":"জা----আ","en":"jaaaa'a"}},{"ar":"السَّمَاءِ","hl":"مَاء","tr":{"bn":"আসসামা----ই","en":"as-samaaaa'i"}},{"ar":"سُوءَ","hl":"سُوء","tr":{"bn":"সূ----আ","en":"soooo'a"}},{"ar":"وَجِيءَ","hl":"جِيء","tr":{"bn":"ওয়াজী----আ","en":"wa jeeee'a"}}]},{"type":"rule","name":{"bn":"মাদ্দ মুনফাসিল — বিচ্ছিন্ন মাদ্দ","en":"Madd Munfasil — Separated Madd"},"ar":"مَدّ مُنْفَصِل","color":"red","desc":{"bn":"মাদ্দের হরফ এক শব্দের **শেষে**, হামযা পরের শব্দের **শুরুতে**। আমাদের দেশে প্রচলিত হাফস তিলাওয়াতে ৪ বা ৫ হরকত।","en":"The madd letter **ends** one word and the hamza **starts** the next. In the Hafs recitation common in our region: 4 or 5 counts."},"how":{"bn":"দুই শব্দ মিলিয়ে পড়ার সময় টানো; প্রথম শব্দে থামলে এটা সাধারণ ২ হরকত হয়ে যায়।","en":"Stretch it when joining the two words; if you stop on the first word it becomes a normal 2-count madd."},"examples":[{"ar":"يَا أَيُّهَا","hl":"يَا أَ","tr":{"bn":"ইয়া----আইয়ুহা","en":"yaaaa ayyuhaa"}},{"ar":"إِنَّا أَعْطَيْنَاكَ","hl":"نَّا أَ","tr":{"bn":"ইন্না----আ‘ত্বাইনা-কা","en":"innaaaa a'ṭaynaaka"}},{"ar":"قُوا أَنْفُسَكُمْ","hl":"قُوا أَ","tr":{"bn":"ক্বূ----আনফুসাকুম","en":"qoooo anfusakum"}},{"ar":"وَفِي أَنْفُسِكُمْ","hl":"فِي أَ","tr":{"bn":"ওয়াফী----আনফুসিকুম","en":"wa feeee anfusikum"}}]},{"type":"tip","kind":"tip","bn":"মুসহাফে মাদ্দের হরফের উপর ঢেউ-চিহ্ন ({{ـٓ}}) মানে ‘দুই হরকতের বেশি টানো’। যেমন {{جَآءَ}}, {{يٰٓأَيُّهَا}}। চিহ্ন দেখলেই সতর্ক হও!","en":"In the mushaf, a wavy sign ({{ـٓ}}) over a madd letter means ‘stretch more than 2 counts’. For example {{جَآءَ}}, {{يٰٓأَيُّهَا}}. When you see it, get ready!"},{"type":"rule","name":{"bn":"মাদ্দ লাযিম — আবশ্যিক মাদ্দ","en":"Madd Lazim — Necessary Madd"},"ar":"مَدّ لَازِم","color":"red","desc":{"bn":"মাদ্দের হরফের পরে **স্থায়ী** সুকুন বা তাশদীদ — মিলিয়ে পড়ো বা থামো, সবসময় থাকে। দৈর্ঘ্য পুরো ৬ হরকত। কিছু সূরার শুরুর বিচ্ছিন্ন হরফেও (যেমন {{الٓمٓ}}) এই মাদ্দ হয়।","en":"A **permanent** sukun or shaddah follows the madd letter — it is there whether you join or stop. Length: a full 6 counts. It also occurs in the disjointed letters at the start of some surahs (like {{الٓمٓ}})."},"how":{"bn":"তিন আলিফ — ছয়টি আঙুল গুনে টানো, তারপর তাশদীদওয়ালা হরফে চাপ দাও।","en":"Three alifs — count six fingers, then press into the doubled letter."},"examples":[{"ar":"الضَّالِّينَ","hl":"ضَّا","tr":{"bn":"আদ্দ্বা------ল্লীন","en":"aḍ-ḍaaaaaal-leen"}},{"ar":"الطَّامَّةُ","hl":"طَّا","tr":{"bn":"আত্তা------ম্মাহ","en":"aṭ-ṭaaaaaam-mah"}},{"ar":"الْحَاقَّةُ","hl":"حَا","tr":{"bn":"আলহা------ক্বক্বাহ","en":"al-ḥaaaaaaq-qah"}},{"ar":"الٓمٓ","hl":"لٓ","tr":{"bn":"আলিফ লা------ম মী------ম","en":"alif laaaaaam meeeeeem"}}]},{"type":"rule","name":{"bn":"মাদ্দ আরিদ লিস-সুকুন — থামার মাদ্দ","en":"Madd 'Arid lis-Sukun — Madd at a Stop"},"ar":"مَدّ عَارِض لِلسُّكُون","color":"red","desc":{"bn":"শেষ হরফের আগে মাদ্দের হরফ, আর তুমি সেই শব্দে **থামলে** শেষ হরফ সাকিন হয় — সুকুনটা ‘অস্থায়ী’। তখন ২, ৪ বা ৬ হরকত টানা যায়। মিলিয়ে পড়লে এটা সাধারণ ২ হরকত।","en":"A madd letter comes before the last letter, and when you **stop** on that word the last letter becomes sakin — a ‘temporary’ sukun. You may stretch 2, 4 or 6 counts. When joining, it is just 2."},"how":{"bn":"যে দৈর্ঘ্যই বেছে নাও, পুরো তিলাওয়াতে সেটিই রাখো — এক আয়াতে ২, পরের আয়াতে ৬ নয়।","en":"Whatever length you choose, keep it the same throughout — not 2 in one ayah and 6 in the next."},"examples":[{"ar":"الرَّحِيمِ","hl":"حِيمِ","tr":{"bn":"আররহী----ম্‌ (থামলে)","en":"ar-raḥeeeem (stop)"}},{"ar":"نَسْتَعِينُ","hl":"عِينُ","tr":{"bn":"নাসতা‘ঈ----ন্‌ (থামলে)","en":"nasta'eeeen (stop)"}},{"ar":"يَعْلَمُونَ","hl":"مُونَ","tr":{"bn":"ইয়া‘লামূ----ন্‌ (থামলে)","en":"ya'lamoooon (stop)"}}]},{"type":"rule","name":{"bn":"মাদ্দ লীন — নরম মাদ্দ","en":"Madd Leen — Soft Madd"},"ar":"مَدّ لِين","color":"red","letters":"و ي","desc":{"bn":"যবরের পর সাকিন {{و}} বা {{ي}}, আর তার পরের হরফে থামলে — ২, ৪ বা ৬ হরকত। মিলিয়ে পড়লে লীনে কোনো টান নেই।","en":"A sakin {{و}} or {{ي}} after fatha, when you stop on the letter after it — 2, 4 or 6 counts. When joining, a leen letter is not stretched at all."},"how":{"bn":"ঠোঁট গোল করে ‘আও’ বা হালকা ‘আই’ — নরমভাবে টানো, তারপর শেষ হরফ সাকিন করে থামো।","en":"A soft ‘aw’ or ‘ay’ — stretch it gently, then stop with the last letter sakin."},"examples":[{"ar":"قُرَيْشٍ","hl":"رَيْ","tr":{"bn":"ক্বুরাই---শ্‌ (থামলে)","en":"qurayyysh (stop)"}},{"ar":"خَوْفٍ","hl":"خَوْ","tr":{"bn":"খাও---ফ্‌ (থামলে)","en":"khawwwf (stop)"}},{"ar":"الْبَيْتِ","hl":"بَيْ","tr":{"bn":"আলবাই---ত্‌ (থামলে)","en":"al-bayyyt (stop)"}}]},{"type":"tip","kind":"fun","title":{"bn":"আরও দুটি ছোট মাদ্দ","en":"Two more little madds"},"bn":"**মাদ্দ বাদাল:** হামযার **পরে** মাদ্দের হরফ, যেমন {{آمَنُوا}}, {{إِيمَانًا}}, {{أُوتُوا}} — হাফসে মাত্র ২ হরকত। **মাদ্দ সিলা:** দুই হরকতওয়ালা হরফের মাঝে সর্বনামের {{ـهُ}}/{{ـهِ}} একটু টেনে পড়া হয় — {{إِنَّهُ كَانَ}} = ‘ইন্নাহূ কা-না’ (২ হরকত)। পরে হামযা থাকলে ৪–৫: {{مَالَهُ أَخْلَدَهُ}}।","en":"**Madd badal:** a madd letter **after** a hamza, like {{آمَنُوا}}, {{إِيمَانًا}}, {{أُوتُوا}} — only 2 counts in Hafs. **Madd silah:** the pronoun {{ـهُ}}/{{ـهِ}} between two voweled letters is stretched a little — {{إِنَّهُ كَانَ}} = ‘innahoo kaana’ (2 counts). With a hamza after it, 4–5: {{مَالَهُ أَخْلَدَهُ}}."},{"type":"tip","kind":"warn","bn":"বাংলাভাষীদের বড় ভুল: লম্বা স্বরকে ছোট করা আর ছোট স্বরকে লম্বা করা। {{قَالَ}} (সে বলল) ‘কালা’ নয়, ‘ক্বা-লা’; আর {{قُلْ}} (বলো) ‘কূল’ নয়, ছোট ‘ক্বুল’। টান কমবেশি হলে অনেক সময় অর্থ বদলে যায়।","en":"A big slip for Bangla speakers: shortening long vowels and lengthening short ones. {{قَالَ}} (he said) is ‘qaa-la’, and {{قُلْ}} (say!) is a short ‘qul’, not ‘qool’. Wrong lengths can change the meaning."},{"type":"practice","bn":"সূরা ফাতিহা পড়ো। প্রতিটি মাদ্দে আঙুলে হরকত গুনে নাও: তবঈ ২, আয়াতের শেষে আরিদ ৪, {{الضَّالِّينَ}}-এ ৬।","en":"Read Surah al-Fatiha. Count each madd on your fingers: natural 2, 'arid at ayah ends 4, and 6 on {{الضَّالِّينَ}}.","lines":["بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","الرَّحْمٰنِ الرَّحِيمِ","مَالِكِ يَوْمِ الدِّينِ","إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ"]},{"type":"quiz","items":[{"q":{"bn":"স্বাভাবিক মাদ্দ কত হরকত?","en":"How many counts is a natural madd?"},"options":["1","2","4","6"],"answer":1},{"q":{"bn":"এখানে কোন মাদ্দ?","en":"Which madd is this?"},"ar":"السَّمَاءِ","options":[{"bn":"মুত্তাসিল","en":"Muttasil"},{"bn":"মুনফাসিল","en":"Munfasil"},{"bn":"লাযিম","en":"Lazim"}],"answer":0,"explain":{"bn":"আলিফ আর হামযা একই শব্দে।","en":"Alif and hamza are in the same word."}},{"q":{"bn":"এখানে কোন মাদ্দ?","en":"Which madd is this?"},"ar":"يَا أَيُّهَا","options":[{"bn":"মুত্তাসিল","en":"Muttasil"},{"bn":"মুনফাসিল","en":"Munfasil"},{"bn":"তবঈ","en":"Tabee'i"}],"answer":1},{"q":{"bn":"{{الضَّالِّينَ}}-এ মাদ্দ কত হরকত?","en":"How long is the madd in {{الضَّالِّينَ}}?"},"options":["2","4","6"],"answer":2,"explain":{"bn":"আলিফের পরে স্থায়ী তাশদীদ — মাদ্দ লাযিম।","en":"A permanent shaddah after the alif — madd lazim."}},{"q":{"bn":"{{نَسْتَعِينُ}}-এ থামলে কত টানা যায়?","en":"Stopping on {{نَسْتَعِينُ}}, how long may you stretch?"},"options":[{"bn":"শুধু ২","en":"Only 2"},{"bn":"২, ৪ বা ৬","en":"2, 4 or 6"},{"bn":"শুধু ৬","en":"Only 6"}],"answer":1},{"q":{"bn":"লীনের হরফ কোনটি?","en":"Which is a leen letter?"},"options":[{"bn":"{{خَوْفٍ}}-এর ওয়াও","en":"The waw in {{خَوْفٍ}}"},{"bn":"{{يَقُولُ}}-এর ওয়াও","en":"The waw in {{يَقُولُ}}"},{"bn":"{{وَ}}-এর ওয়াও","en":"The waw in {{وَ}}"}],"answer":0,"explain":{"bn":"যবরের পর সাকিন ওয়াও = লীন।","en":"Sakin waw after fatha = leen."}},{"q":{"bn":"মাদ্দ লীনে কখন টান হয়?","en":"When is a madd leen stretched?"},"options":[{"bn":"সবসময়","en":"Always"},{"bn":"শুধু থামলে","en":"Only at a stop"},{"bn":"কখনো না","en":"Never"}],"answer":1}]}]},{"id":"tj-waqf","icon":"۝","title":{"bn":"ওয়াকফ — থামা ও আবার শুরু করা","en":"Waqf — Stopping & Starting"},"subtitle":{"bn":"শব্দের শেষে কীভাবে থামবে, কোথায় থামবে, মুসহাফের চিহ্ন","en":"How to stop on a word, where to stop, and the mushaf stop signs"},"minutes":15,"goals":[{"bn":"শব্দের শেষে সঠিকভাবে থামতে শিখব","en":"Stop correctly at the end of a word"},{"bn":"অর্থ ঠিক রেখে কোথায় থামতে ও কোথা থেকে শুরু করতে হয় বুঝব","en":"Choose where to stop and restart without spoiling the meaning"},{"bn":"মুসহাফের ওয়াকফের চিহ্নগুলো চিনব","en":"Recognise the stop signs in the mushaf"}],"blocks":[{"type":"text","bn":"এক নিঃশ্বাসে পুরো সূরা পড়া যায় না — মাঝে মাঝে থামতেই হয়। থেমে শ্বাস নেওয়াকে বলে **ওয়াকফ** ({{وَقْف}}), আর আবার শুরু করাকে বলে **ইবতিদা** ({{اِبْتِدَاء}})। ভুল জায়গায় থামলে অর্থ উল্টে যেতে পারে, আর ভুলভাবে থামলে শব্দ বিকৃত হয়।","en":"You cannot recite a whole surah in one breath — you must stop now and then. Stopping to take a breath is called **waqf** ({{وَقْف}}), and starting again is **ibtida** ({{اِبْتِدَاء}}). Stopping in the wrong place can flip the meaning, and stopping the wrong way distorts the word."},{"type":"steps","title":{"bn":"শব্দের শেষে কীভাবে থামবে","en":"How to stop on a word"},"items":[{"title":{"bn":"শেষ হরকত বা তানবীন → সাকিন","en":"Last vowel or tanween → sukun"},"ar":"نَسْتَعِينُ ← نَسْتَعِينْ","tr":{"bn":"নাসতা‘ঈন্‌","en":"nasta'een"},"desc":{"bn":"যবর, যের, পেশ, দুই যের বা দুই পেশ — সবই সাকিন হয়ে যায়। {{عَظِيمٌ}} → ‘আযীম্‌’।","en":"Fatha, kasra, damma, double kasra or double damma — all become sukun. {{عَظِيمٌ}} → ‘'aẓeem’."}},{"title":{"bn":"দুই যবর ({{ـًا}}) → আলিফের টান","en":"Double fatha ({{ـًا}}) → an alif sound"},"ar":"تَرْتِيلًا ← تَرْتِيلَا","tr":{"bn":"তারতীলা-","en":"tarteelaa"},"desc":{"bn":"তানবীনের নূন বাদ, যবরটি ২ হরকত আলিফ হয়ে যায় (মাদ্দ ইওয়াদ)। {{حَكِيمًا}} → ‘হাকীমা-’।","en":"The tanween's noon drops and the fatha becomes a 2-count alif (madd 'iwad). {{حَكِيمًا}} → ‘ḥakeemaa’."}},{"title":{"bn":"গোল তা ({{ة}}) → হা সাকিন","en":"Round ta ({{ة}}) → sakin ha"},"ar":"الْقَارِعَةُ ← الْقَارِعَهْ","tr":{"bn":"আলক্বা-রি‘আহ্‌","en":"al-qaari'ah"},"desc":{"bn":"দুই যবর থাকলেও আলিফ হয় না: {{رَحْمَةً}} → ‘রহমাহ্‌’, ‘রহমাতা’ নয়।","en":"Even with double fatha there is no alif: {{رَحْمَةً}} → ‘raḥmah’, not ‘raḥmataa’."}},{"title":{"bn":"সর্বনামের {{ـهُ}} / {{ـهِ}} → হা সাকিন","en":"Pronoun {{ـهُ}} / {{ـهِ}} → sakin ha"},"ar":"يَرَهُ ← يَرَهْ","tr":{"bn":"ইয়ারাহ্‌","en":"yarah"},"desc":{"bn":"মাদ্দ সিলার টানও থাকে না।","en":"The silah stretch also disappears."}},{"title":{"bn":"আগে থেকেই সাকিন বা আলিফ → যেমন আছে","en":"Already sakin or alif → no change"},"ar":"لَمْ يُولَدْ","tr":{"bn":"লাম ইউলাদ্‌","en":"lam yoolad"},"desc":{"bn":"কিছুই বদলাবে না (এখানে কলকলা মনে রাখো!)।","en":"Nothing changes (remember the qalqalah here!)."}},{"title":{"bn":"শেষে তাশদীদ → দ্বিগুণ ভাবটা রাখো","en":"Final shaddah → keep it doubled"},"ar":"وَتَبَّ","tr":{"bn":"ওয়াতাব্ব্‌","en":"wa tabb"},"desc":{"bn":"তাশদীদ হারাবে না, শেষ হরফে একটু চাপ থাকবে।","en":"Do not lose the shaddah — keep a little pressure on the last letter."}}]},{"type":"examples","title":{"bn":"থেমে পড়ো","en":"Read them with a stop"},"items":[{"ar":"الرَّحِيمِ","tr":{"bn":"আররহীম্‌","en":"ar-raḥeem"},"note":{"bn":"যের → সাকিন (আরিদ মাদ্দ ২/৪/৬)","en":"Kasra → sukun ('arid madd 2/4/6)"}},{"ar":"عَلِيمًا حَكِيمًا","tr":{"bn":"‘আলীমান হাকীমা-","en":"'aleeman ḥakeemaa"},"note":{"bn":"শেষের দুই যবর → আলিফ","en":"Final double fatha → alif"}},{"ar":"جَنَّةٍ","tr":{"bn":"জান্নাহ্‌","en":"jannah"},"note":{"bn":"গোল তা → হা সাকিন","en":"Round ta → sakin ha"}},{"ar":"أَحَدٌ","tr":{"bn":"আহাদ্‌","en":"aḥad"},"note":{"bn":"দুই পেশ → সাকিন + বড় কলকলা","en":"Double damma → sukun + major qalqalah"}}]},{"type":"text","title":{"bn":"কোথায় থামবে?","en":"Where to stop?"},"bn":"সবচেয়ে ভালো জায়গা **আয়াতের শেষ** — রাসূলুল্লাহ ﷺ প্রতিটি আয়াতের শেষে থেমে থেমে পড়তেন। আয়াতের মাঝে থামতে হলে এমন জায়গায় থামো যেখানে **অর্থ পূর্ণ** হয়। এমন জায়গায় থামবে না যেখানে অর্থ ভুল দাঁড়ায়।","en":"The best place is **the end of an ayah** — the Prophet ﷺ used to pause at the end of each ayah. If you must stop inside an ayah, choose a place where **the meaning is complete**. Never stop where the meaning comes out wrong."},{"type":"compare","title":{"bn":"ভুল জায়গায় থামলে কী হয়?","en":"What happens if you stop in the wrong place?"},"items":[{"ar":"لَا تَقْرَبُوا الصَّلَاةَ","label":{"bn":"এখানে থেমো না!","en":"Do not stop here!"},"desc":{"bn":"অর্থ দাঁড়ায় ‘সালাতের কাছেও যেয়ো না’ — সম্পূর্ণ ভুল বার্তা","en":"It says ‘do not go near the prayer’ — a completely wrong message"}},{"ar":"لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارٰى","label":{"bn":"পুরোটা পড়ো","en":"Read it through"},"desc":{"bn":"‘নেশাগ্রস্ত অবস্থায় সালাতের কাছে যেয়ো না’ (৪:৪৩) — সঠিক অর্থ","en":"‘Do not approach prayer while intoxicated’ (4:43) — the true meaning"}}]},{"type":"text","title":{"bn":"আবার শুরু করা (ইবতিদা)","en":"Starting again (ibtida)"},"bn":"শ্বাসের অভাবে বাক্যের মাঝখানে থেমে গেলে, এক-দুই শব্দ **পেছন থেকে** আবার শুরু করো, যাতে অর্থ জুড়ে যায়। শুরুর শব্দটি যদি হামযাতুল ওয়াসল (জোড়া-হামযা {{ا}}) দিয়ে শুরু হয়, তাকে একটি হরকত দিয়ে পড়তে হয়:","en":"If you run out of breath mid-sentence, go **back** a word or two and start again so the meaning connects. If the first word begins with a joining hamza (hamzat al-wasl, {{ا}}), give it a vowel like this:"},{"type":"table","head":[{"bn":"অবস্থা","en":"Case"},{"bn":"শুরু করো","en":"Start with"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"{{ال}} (আলিফ-লাম)","en":"{{ال}} (the article)"},{"bn":"যবর — ‘আ’","en":"Fatha — ‘a’"},"الْحَمْدُ"],[{"bn":"ক্রিয়ার তৃতীয় হরফে পেশ","en":"Verb with damma on its 3rd letter"},{"bn":"পেশ — ‘উ’","en":"Damma — ‘u’"},"انْظُرْ"],[{"bn":"ক্রিয়ার তৃতীয় হরফে যবর/যের","en":"Verb with fatha/kasra on its 3rd letter"},{"bn":"যের — ‘ই’","en":"Kasra — ‘i’"},"اهْدِنَا"]]},{"type":"table","title":{"bn":"মুসহাফের ওয়াকফের চিহ্ন (আমাদের দেশের মুসহাফ)","en":"Stop signs in the mushaf (as printed in our region)"},"head":[{"bn":"চিহ্ন","en":"Sign"},{"bn":"নাম","en":"Name"},{"bn":"কী করবে","en":"What to do"}],"rows":[["۝",{"bn":"আয়াতের শেষ","en":"End of ayah"},{"bn":"থামা সুন্নাত ও উত্তম","en":"Stopping is sunnah and best"}],["م",{"bn":"ওয়াকফে লাযিম","en":"Waqf lazim"},{"bn":"অবশ্যই থামো — না থামলে অর্থ বিকৃত হতে পারে","en":"Must stop — joining may distort the meaning"}],["ط",{"bn":"ওয়াকফে মুতলাক","en":"Waqf mutlaq"},{"bn":"থামো","en":"Stop"}],["ج",{"bn":"ওয়াকফে জায়েয","en":"Waqf ja'iz"},{"bn":"থামা-মেলানো দুটোই চলে, থামা ভালো","en":"Both allowed; stopping is better"}],["ز",{"bn":"মুজাওয়ায","en":"Mujawwaz"},{"bn":"থামা চলে, তবে মিলিয়ে পড়া ভালো","en":"Stopping allowed, joining is better"}],["ص",{"bn":"মুরাখখাস","en":"Murakhkhas"},{"bn":"মিলিয়ে পড়ো; শ্বাস না থাকলে থামতে পারো","en":"Join; you may stop if out of breath"}],["قلى",{"bn":"আল-ওয়াকফু আওলা","en":"Al-waqfu awla"},{"bn":"থামা উত্তম","en":"Stopping is better"}],["صلى",{"bn":"আল-ওয়াসলু আওলা","en":"Al-waslu awla"},{"bn":"মিলিয়ে পড়া উত্তম","en":"Joining is better"}],["ق",{"bn":"কীলা আলাইহিল ওয়াকফ","en":"Qeela 'alayhil-waqf"},{"bn":"মিলিয়ে পড়ো (কেউ কেউ থামতে বলেছেন)","en":"Join (some scholars said stop)"}],["قف",{"bn":"কিফ","en":"Qif"},{"bn":"থামো","en":"Stop"}],["لا",{"bn":"লা ওয়াকফা","en":"La waqf"},{"bn":"থেমো না; থেমে গেলে পেছন থেকে মিলিয়ে পড়ো","en":"Do not stop; if you did, go back and rejoin"}],[{"bn":"∴ … ∴","en":"∴ … ∴"},{"bn":"মু‘আনাকা (জোড়া চিহ্ন)","en":"Mu'anaqah (paired dots)"},{"bn":"দুটির যেকোনো একটিতে থামো, দুটোতেই নয়","en":"Stop at one of the two, not both"}],["س",{"bn":"সাকতা","en":"Saktah"},{"bn":"শ্বাস না নিয়ে মুহূর্তের জন্য থামো","en":"Pause briefly without taking a breath"}],["وقفة",{"bn":"ওয়াকফা","en":"Waqfah"},{"bn":"শ্বাস না নিয়ে সাকতার চেয়ে একটু বেশি থামো","en":"Pause a little longer than saktah, without breathing"}]]},{"type":"tip","kind":"fun","bn":"হাফস রিওয়ায়াতে চারটি জায়গায় সাকতা করতেই হয়: {{عِوَجًا}} (১৮:১), {{مَرْقَدِنَا}} (৩৬:৫২), {{مَنْ رَاقٍ}} (৭৫:২৭) ও {{بَلْ رَانَ}} (৮৩:১৪)। মজার ব্যাপার: শেষ দুটিতে সাকতার কারণে নূন/লাম রা-এর সাথে মিশে যায় না — ‘মান্‌ — রা-ক্ব’, ‘বাল্‌ — রা-না’।","en":"In Hafs there are four places where a saktah is required: {{عِوَجًا}} (18:1), {{مَرْقَدِنَا}} (36:52), {{مَنْ رَاقٍ}} (75:27) and {{بَلْ رَانَ}} (83:14). Fun fact: in the last two, the pause stops the noon/lam from merging into the ra — ‘man — raaq’, ‘bal — raana’."},{"type":"tip","kind":"warn","bn":"থামার সময় দম ফুরিয়ে শব্দের শেষটা গিলে ফেলবে না। আর শ্বাস নিতে হলে শব্দের মাঝখানে কখনো নয় — শুধু শব্দের শেষে।","en":"When stopping, do not swallow the end of the word because you ran out of breath. And never take a breath in the middle of a word — only at the end of one."},{"type":"practice","bn":"প্রতিটি শব্দে আলাদা করে থামো এবং থামার নিয়মটি প্রয়োগ করো।","en":"Stop on each word separately and apply the stopping rule.","lines":["نَسْتَعِينُ الرَّحِيمِ عَظِيمٌ","تَرْتِيلًا حَكِيمًا أَبَدًا","رَحْمَةً الْقَارِعَةُ جَنَّةٍ","يَرَهُ أَحَدٌ وَتَبَّ","الْحَمْدُ انْظُرْ اهْدِنَا"]},{"type":"quiz","items":[{"q":{"bn":"{{تَرْتِيلًا}}-এ থামলে কীভাবে পড়বে?","en":"How do you stop on {{تَرْتِيلًا}}?"},"options":[{"bn":"তারতীলান","en":"tarteelan"},{"bn":"তারতীলা-","en":"tarteelaa"},{"bn":"তারতীল্‌","en":"tarteel"}],"answer":1,"explain":{"bn":"দুই যবর থামার সময় আলিফ হয়।","en":"Double fatha becomes an alif at a stop."}},{"q":{"bn":"{{رَحْمَةً}}-এ থামলে কীভাবে পড়বে?","en":"How do you stop on {{رَحْمَةً}}?"},"options":[{"bn":"রহমাতা-","en":"raḥmataa"},{"bn":"রহমাহ্‌","en":"raḥmah"},{"bn":"রহমাতান","en":"raḥmatan"}],"answer":1,"explain":{"bn":"গোল তা সবসময় হা সাকিন হয়।","en":"Round ta always becomes a sakin ha."}},{"q":{"bn":"এই চিহ্নের অর্থ কী?","en":"What does this sign mean?"},"ar":"م","options":[{"bn":"অবশ্যই থামো","en":"You must stop"},{"bn":"থেমো না","en":"Do not stop"},{"bn":"মিলিয়ে পড়া উত্তম","en":"Joining is better"}],"answer":0},{"q":{"bn":"এই চিহ্নের অর্থ কী?","en":"What does this sign mean?"},"ar":"لا","options":[{"bn":"অবশ্যই থামো","en":"You must stop"},{"bn":"থেমো না","en":"Do not stop"},{"bn":"থামা উত্তম","en":"Stopping is better"}],"answer":1},{"q":{"bn":"{{قلى}} দেখলে কী করবে?","en":"What do you do at {{قلى}}?"},"options":[{"bn":"থামা উত্তম","en":"Stopping is better"},{"bn":"মিলিয়ে পড়া উত্তম","en":"Joining is better"},{"bn":"সাকতা করো","en":"Make a saktah"}],"answer":0},{"q":{"bn":"{{اهْدِنَا}} দিয়ে শুরু করলে প্রথমে কী বলবে?","en":"Starting with {{اهْدِنَا}}, how does it begin?"},"options":[{"bn":"আহদিনা","en":"ahdinaa"},{"bn":"ইহদিনা","en":"ihdinaa"},{"bn":"উহদিনা","en":"uhdinaa"}],"answer":1,"explain":{"bn":"তৃতীয় হরফ {{د}}-তে যের, তাই শুরুতে ‘ই’।","en":"The 3rd letter {{د}} has kasra, so start with ‘i’."}},{"q":{"bn":"সাকতা মানে কী?","en":"What is a saktah?"},"options":[{"bn":"শ্বাস নিয়ে লম্বা বিরতি","en":"A long pause with a breath"},{"bn":"শ্বাস না নিয়ে মুহূর্তের বিরতি","en":"A brief pause without a breath"},{"bn":"ছয় হরকত টান","en":"A 6-count stretch"}],"answer":1}]}]},{"id":"tj-bangla-mistakes","icon":"ض","title":{"bn":"বাংলাভাষীদের সাধারণ ভুল","en":"Common Mistakes of Bangla Speakers"},"subtitle":{"bn":"কাছাকাছি হরফ, স্বরের দৈর্ঘ্য আর হারানো গুন্নাহ — ভুল ধরো, ঠিক করো","en":"Look-alike sounds, vowel length and lost ghunnah — spot them, fix them"},"minutes":20,"goals":[{"bn":"বাংলায় নেই এমন আরবি আওয়াজগুলো আলাদা করতে শিখব","en":"Separate Arabic sounds that Bangla does not have"},{"bn":"যে ভুলে অর্থ বদলে যায় সেগুলো চিনব","en":"Recognise mistakes that change the meaning"},{"bn":"প্রতিদিন ৫ মিনিটের নিজে-যাচাই অভ্যাস গড়ব","en":"Build a 5-minute daily self-check habit"}],"blocks":[{"type":"text","bn":"বাংলা সুন্দর ভাষা, কিন্তু এতে আরবির অনেক আওয়াজ নেই। তাই আমরা না বুঝেই কাছের বাংলা আওয়াজ বসিয়ে দিই — {{ث}}, {{س}}, {{ص}} তিনটিকেই ‘স/ছ’, আর {{ذ}}, {{ز}}, {{ظ}}, {{ض}} চারটিকেই ‘জ/য’। এই পাঠে আমরা সবচেয়ে বেশি হওয়া ভুলগুলো একটি একটি করে ধরব — সাথে ঠিক করার কৌশল।","en":"Bangla is a beautiful language, but it lacks many Arabic sounds. So without noticing we substitute the nearest Bangla sound — saying {{ث}}, {{س}}, {{ص}} all as ‘s’, and {{ذ}}, {{ز}}, {{ظ}}, {{ض}} all as ‘j/z’. In this lesson we catch the most common mistakes one by one — with a fix for each."},{"type":"compare","title":{"bn":"ভুল ১: তিনটি ‘স’ — {{ث}} {{س}} {{ص}}","en":"Mistake 1: three ‘s’ sounds — {{ث}} {{س}} {{ص}}"},"items":[{"ar":"ثَ","label":{"bn":"ছা — জিহ্বা দাঁতের আগায়","en":"tha — tongue at the teeth"},"desc":{"bn":"জিহ্বার আগা উপরের দাঁতের কিনারায় লাগাও, বাতাস ছাড়ো — ইংরেজি ‘think’-এর th। যেমন {{ثُمَّ}}","en":"Tongue tip on the edges of the upper teeth, let air out — the ‘th’ of ‘think’. E.g. {{ثُمَّ}}"}},{"ar":"سَ","label":{"bn":"সা — হালকা শিস","en":"sa — light whistle"},"desc":{"bn":"জিহ্বা দাঁতের পেছনে, চিকন শিসের মতো আওয়াজ। যেমন {{سَمِيعٌ}}","en":"Tongue behind the teeth, a thin whistling sound. E.g. {{سَمِيعٌ}}"}},{"ar":"صَ","label":{"bn":"ছা — মোটা শিস","en":"ṣa — heavy whistle"},"desc":{"bn":"সীনের জায়গা, কিন্তু জিহ্বার গোড়া উপরে তুলে মুখ ভরে — ভারী আওয়াজ। যেমন {{الصِّرَاطَ}}","en":"Same place as seen, but raise the back of the tongue to fill the mouth — a heavy sound. E.g. {{الصِّرَاطَ}}"}}]},{"type":"compare","title":{"bn":"অর্থ বদলে যায়: {{ص}} বনাম {{س}}","en":"Meaning changes: {{ص}} vs {{س}}"},"items":[{"ar":"عَصٰى","label":{"bn":"‘আছা — অবাধ্য হলো","en":"'aṣaa — disobeyed"},"desc":{"bn":"মোটা {{ص}} — {{وَعَصٰى آدَمُ رَبَّهُ}} (২০:১২১)","en":"Heavy {{ص}} — {{وَعَصٰى آدَمُ رَبَّهُ}} (20:121)"}},{"ar":"عَسٰى","label":{"bn":"‘আসা — হয়তো / আশা করা যায়","en":"'asaa — perhaps"},"desc":{"bn":"চিকন {{س}} — সম্পূর্ণ ভিন্ন শব্দ!","en":"Light {{س}} — a completely different word!"}}]},{"type":"compare","title":{"bn":"ভুল ২: চারটি ‘জ’ — {{ذ}} {{ز}} {{ظ}} {{ض}}","en":"Mistake 2: four ‘j’ sounds — {{ذ}} {{ز}} {{ظ}} {{ض}}"},"items":[{"ar":"ذَ","label":{"bn":"যা — নরম, জিহ্বা দাঁতে","en":"dha — soft, tongue at teeth"},"desc":{"bn":"{{ث}}-এর জায়গা, কিন্তু গলায় আওয়াজ সহ — ইংরেজি ‘this’-এর th। যেমন {{ذٰلِكَ}}","en":"Same place as {{ث}}, but voiced — the ‘th’ of ‘this’. E.g. {{ذٰلِكَ}}"}},{"ar":"زَ","label":{"bn":"যা — ভোঁ ভোঁ শিস","en":"za — buzzing"},"desc":{"bn":"{{س}}-এর জায়গা, কিন্তু মৌমাছির মতো ভনভনে — ইংরেজি ‘zoo’-র z। ‘জাকাত’ নয়, {{زَكَاةَ}}","en":"Same place as {{س}}, but buzzing like a bee — the ‘z’ of ‘zoo’. Not ‘jakat’ but {{زَكَاةَ}}"}},{"ar":"ظَ","label":{"bn":"যা — মোটা, জিহ্বা দাঁতে","en":"ẓa — heavy, tongue at teeth"},"desc":{"bn":"{{ذ}}-এর মোটা রূপ: জিহ্বার আগা দাঁতে, গোড়া উপরে। যেমন {{ظَلَمُوا}}","en":"The heavy form of {{ذ}}: tip at the teeth, back raised. E.g. {{ظَلَمُوا}}"}},{"ar":"ضَ","label":{"bn":"দ্বা — জিহ্বার পাশ","en":"ḍa — side of the tongue"},"desc":{"bn":"জিহ্বার পাশ উপরের মাড়ির দাঁতে চেপে, মোটা করে। ‘দোয়াল্লীন’ বা ‘যোয়াল্লীন’ নয় — {{الضَّالِّينَ}}","en":"Press the side of the tongue against the upper molars, heavy. Not ‘doalleen’ or ‘zoalleen’ — {{الضَّالِّينَ}}"}}]},{"type":"compare","title":{"bn":"একই সূরায় দুই শব্দ: {{ظ}} বনাম {{ذ}}","en":"Two words in one surah: {{ظ}} vs {{ذ}}"},"items":[{"ar":"مَحْظُورًا","label":{"bn":"মাহযূরা — বাধাগ্রস্ত / সীমিত","en":"maḥẓooraa — restricted"},"desc":{"bn":"মোটা {{ظ}} — {{وَمَا كَانَ عَطَاءُ رَبِّكَ مَحْظُورًا}} (১৭:২০) ‘তোমার রবের দান সীমাবদ্ধ নয়’","en":"Heavy {{ظ}} — (17:20) ‘the gift of your Lord is not restricted’"}},{"ar":"مَحْذُورًا","label":{"bn":"মাহযূরা — ভয় করার মতো","en":"maḥdhooraa — to be feared"},"desc":{"bn":"চিকন {{ذ}} — {{إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا}} (১৭:৫৭) ‘তোমার রবের শাস্তি ভয়ংকর’","en":"Light {{ذ}} — (17:57) ‘the punishment of your Lord is to be feared’"}}]},{"type":"tip","kind":"warn","bn":"দেখলে তো? বাংলায় দুটোই ‘মাহযূরা’ লেখা হয়, কিন্তু একটি আল্লাহর **দান** সম্পর্কে, অন্যটি তাঁর **শাস্তি** সম্পর্কে! তাই বাংলা উচ্চারণ-লেখার ওপর ভরসা না করে হরফটির মাখরাজ শেখো।","en":"See? In Bangla script both look like ‘maḥzoora’, yet one is about Allah's **gift** and the other about His **punishment**! So do not rely on Bangla transliteration — learn each letter's makhraj."},{"type":"compare","title":{"bn":"ভুল ৩: দুই ‘হ’ — {{ح}} {{ه}}","en":"Mistake 3: two ‘h’ sounds — {{ح}} {{ه}}"},"items":[{"ar":"حَ","label":{"bn":"হা — গলার মাঝখান চেপে","en":"ḥa — squeeze mid-throat"},"desc":{"bn":"গলার মাঝখান সরু করে গরম বাতাস ছাড়ো — যেন খুব ঝাল খাওয়ার পর ‘হাহ্‌’। যেমন {{الرَّحْمٰنِ}}","en":"Narrow the middle of the throat and push out warm air — like the ‘haah’ after something very spicy. E.g. {{الرَّحْمٰنِ}}"}},{"ar":"هَ","label":{"bn":"হা — বুকের গভীর থেকে হালকা","en":"ha — light, from deep down"},"desc":{"bn":"গলার একদম নিচ থেকে আলতো নিঃশ্বাস, কোনো চাপ নেই — বাংলা ‘হ’-এর কাছাকাছি। যেমন {{هُدًى}}","en":"A gentle breath from the very bottom of the throat, no squeeze — close to the Bangla ‘h’. E.g. {{هُدًى}}"}}]},{"type":"compare","title":{"bn":"ভুল ৪: {{خ}} বাংলা ‘খ’ নয়, {{غ}} বাংলা ‘গ’ নয়","en":"Mistake 4: {{خ}} is not Bangla ‘kh’, {{غ}} is not ‘g’"},"items":[{"ar":"خَ","label":{"bn":"খা — গলার উপরে ঘষা","en":"kha — a scrape at the top of the throat"},"desc":{"bn":"বাংলা ‘খ’ হলো ক+হ; আরবি {{خ}} হলো গলার উপরের দিকে খসখসে ঘষা, জিহ্বা কোথাও ঠেকে না। মোটা হরফ। যেমন {{خَلَقَ}}","en":"Bangla ‘kh’ is k+h; Arabic {{خ}} is a raspy scrape at the top of the throat, the tongue touches nothing. A heavy letter. E.g. {{خَلَقَ}}"}},{"ar":"غَ","label":{"bn":"গা — গড়গড়া করার মতো","en":"gha — like gargling"},"desc":{"bn":"{{خ}}-এর জায়গা, কিন্তু গলায় আওয়াজসহ — কুলি করার সময়ের গড়গড় শব্দ। যেমন {{غَيْرِ الْمَغْضُوبِ}}","en":"Same place as {{خ}}, but voiced — the gurgle of gargling. E.g. {{غَيْرِ الْمَغْضُوبِ}}"}}]},{"type":"compare","title":{"bn":"ভুল ৫: {{ع}} বনাম {{ء}} — অর্থ বদলে যায়!","en":"Mistake 5: {{ع}} vs {{ء}} — the meaning changes!"},"items":[{"ar":"عَلِيمٌ","label":{"bn":"‘আলীম — সর্বজ্ঞ","en":"'aleem — All-Knowing"},"desc":{"bn":"{{ع}}: গলার মাঝখান চেপে কণ্ঠস্বর — আল্লাহর গুণবাচক নাম","en":"{{ع}}: a voiced squeeze in mid-throat — a name of Allah"}},{"ar":"أَلِيمٌ","label":{"bn":"আলীম — যন্ত্রণাদায়ক","en":"aleem — painful"},"desc":{"bn":"{{ء}}: গলার নিচে পরিষ্কার এক ঝটকা — {{عَذَابٌ أَلِيمٌ}} ‘যন্ত্রণাদায়ক শাস্তি’","en":"{{ء}}: a clean catch deep in the throat — {{عَذَابٌ أَلِيمٌ}} ‘a painful punishment’"}}]},{"type":"compare","title":{"bn":"ভুল ৬: {{ق}} বনাম {{ك}}","en":"Mistake 6: {{ق}} vs {{ك}}"},"items":[{"ar":"قَلْبٌ","label":{"bn":"ক্বালব — হৃদয়","en":"qalb — heart"},"desc":{"bn":"জিহ্বার একদম গোড়া, মোটা ও গভীর — কাকের ডাকের মতো গলার পেছনে","en":"The very back of the tongue, heavy and deep — far back like a crow's caw"}},{"ar":"كَلْبٌ","label":{"bn":"কালব — কুকুর!","en":"kalb — dog!"},"desc":{"bn":"একটু সামনে, চিকন — ‘হৃদয়’ বলতে গিয়ে ‘কুকুর’ বলে ফেলো না!","en":"A little forward, light — do not say ‘dog’ when you mean ‘heart’!"}}]},{"type":"compare","title":{"bn":"ভুল ৭: {{ط}} বনাম {{ت}}","en":"Mistake 7: {{ط}} vs {{ت}}"},"items":[{"ar":"طِينٍ","label":{"bn":"ত্বীন — কাদামাটি","en":"ṭeen — clay"},"desc":{"bn":"মোটা {{ط}}: জিহ্বা তালুতে ঢাকনার মতো — {{خَلَقَكُمْ مِنْ طِينٍ}}","en":"Heavy {{ط}}: the tongue covers the palate like a lid — {{خَلَقَكُمْ مِنْ طِينٍ}}"}},{"ar":"التِّينِ","label":{"bn":"তীন — ডুমুর","en":"teen — fig"},"desc":{"bn":"চিকন {{ت}} — {{وَالتِّينِ وَالزَّيْتُونِ}}","en":"Light {{ت}} — {{وَالتِّينِ وَالزَّيْتُونِ}}"}}]},{"type":"compare","title":{"bn":"ভুল ৮: যবরকে বাংলা ‘অ’ বানানো","en":"Mistake 8: turning fatha into a Bangla ‘o’"},"items":[{"ar":"رَحْمَةٌ","label":{"bn":"ঠিক: ‘রাহমাহ’","en":"Right: ‘raḥmah’"},"desc":{"bn":"যবর মানে খোলা ‘আ’-এর মতো ছোট আওয়াজ — মুখ খোলা, ঠোঁট গোল নয়","en":"Fatha is a short open ‘a’ — mouth open, lips not rounded"}},{"ar":"رَحْمَةٌ","label":{"bn":"ভুল: ‘রোহমোত’","en":"Wrong: ‘rohmot’"},"desc":{"bn":"বাংলা ‘অ’ (ও-ঘেঁষা) — আরবিতে এমন স্বর নেই। পেশকেও ‘ও’ বানাবে না: {{يَقُولُ}} ‘ইয়াকোলো’ নয়","en":"The Bangla ‘o’-like vowel does not exist in Arabic. Do not turn damma into ‘o’ either: {{يَقُولُ}} is not ‘yakolo’"}}]},{"type":"compare","title":{"bn":"ভুল ৯: ছোট-বড় স্বর গুলিয়ে ফেলা","en":"Mistake 9: mixing short and long vowels"},"items":[{"ar":"مَلِكِ النَّاسِ","label":{"bn":"মালিকি — ছোট ‘মা’","en":"maliki — short ‘ma’"},"desc":{"bn":"‘মানুষের বাদশাহ’ (১১৪:২)","en":"‘King of mankind’ (114:2)"}},{"ar":"مَالِكِ يَوْمِ الدِّينِ","label":{"bn":"মা-লিকি — লম্বা ‘মা-’","en":"maaliki — long ‘maa’"},"desc":{"bn":"‘বিচার দিবসের মালিক’ (১:৪) — হাফসে এখানে আলিফসহ, তাই টান দিতেই হবে","en":"‘Master of the Day of Judgement’ (1:4) — Hafs reads it with alif here, so it must be stretched"}}]},{"type":"compare","title":{"bn":"ভুল ১০: তাশদীদ ও গুন্নাহ হারিয়ে ফেলা","en":"Mistake 10: dropping shaddah and ghunnah"},"items":[{"ar":"رَبِّ","label":{"bn":"ঠিক: ‘রব্‌বি’","en":"Right: ‘rab-bi’"},"desc":{"bn":"বা দুবার — প্রথমটি সাকিন, দ্বিতীয়টি যেরসহ","en":"Ba twice — first sakin, then with kasra"}},{"ar":"رَبِ","label":{"bn":"ভুল: ‘রবি’","en":"Wrong: ‘rabi’"},"desc":{"bn":"তাশদীদ হারালে শব্দ বিকৃত। একইভাবে {{إِنَّ}}, {{ثُمَّ}}-এ গুন্নাহ বাদ দিয়ো না","en":"Losing the shaddah distorts the word. Likewise never skip the ghunnah in {{إِنَّ}}, {{ثُمَّ}}"}}]},{"type":"tip","kind":"warn","title":{"bn":"আরও দুটি ছোট ফাঁদ","en":"Two more little traps"},"bn":"**{{و}} বাংলা ‘ভ’ নয়:** ঠোঁট গোল করো, দাঁত ঠোঁটে লাগবে না — {{وَ}} = ‘ওয়া’, ‘ভা’ নয়। **{{ر}} কাঁপাবে না:** জিহ্বার একটি মাত্র টোকা, বিশেষ করে তাশদীদে ({{الرَّحِيمِ}}) ‘ররর’ করে কাঁপানো ভুল।","en":"**{{و}} is not a ‘v’:** round your lips and keep your teeth off them — {{وَ}} = ‘wa’, not ‘va’. **Do not roll {{ر}}:** just one tap of the tongue; trilling ‘rrr’, especially with shaddah ({{الرَّحِيمِ}}), is wrong."},{"type":"table","title":{"bn":"এক নজরে: বাংলা ফাঁদ → সমাধান","en":"At a glance: the Bangla trap → the fix"},"head":[{"bn":"হরফ","en":"Letter"},{"bn":"সাধারণ ভুল","en":"Common slip"},{"bn":"সমাধান","en":"Fix"}],"rows":[["ث",{"bn":"স/ছ","en":"s"},{"bn":"জিহ্বার আগা দাঁতের কিনারায়","en":"Tongue tip on the teeth edges"}],["ذ",{"bn":"জ/য","en":"j/z"},{"bn":"{{ث}}-এর জায়গা + কণ্ঠস্বর","en":"{{ث}}'s place + voice"}],["ز",{"bn":"জ","en":"j"},{"bn":"মৌমাছির ভনভনে শিস","en":"A bee-like buzz"}],["ظ",{"bn":"জ/য","en":"j/z"},{"bn":"{{ذ}} + মোটা","en":"{{ذ}} + heavy"}],["ض",{"bn":"দ/জ","en":"d/z"},{"bn":"জিহ্বার পাশ মাড়ির দাঁতে, মোটা","en":"Side of tongue on molars, heavy"}],["ص",{"bn":"স","en":"s"},{"bn":"{{س}} + মোটা","en":"{{س}} + heavy"}],["ح",{"bn":"হ","en":"h"},{"bn":"গলার মাঝখান চেপে","en":"Squeeze mid-throat"}],["ع",{"bn":"আ/অ","en":"a"},{"bn":"গলার মাঝখান, কণ্ঠস্বরসহ","en":"Mid-throat, voiced"}],["ق",{"bn":"ক","en":"k"},{"bn":"জিহ্বার একদম গোড়া, মোটা","en":"Very back of tongue, heavy"}],["ط",{"bn":"ত","en":"t"},{"bn":"{{ت}} + মোটা","en":"{{ت}} + heavy"}],["خ",{"bn":"খ (ক+হ)","en":"k+h"},{"bn":"গলার উপরে খসখসে ঘষা","en":"A raspy scrape high in the throat"}],["غ",{"bn":"গ","en":"g"},{"bn":"গড়গড়া করার আওয়াজ","en":"A gargling sound"}]]},{"type":"steps","title":{"bn":"প্রতিদিন ৫ মিনিট: নিজের কারী নিজে হও","en":"5 minutes a day: be your own coach"},"items":[{"title":{"bn":"শোনো","en":"Listen"},"desc":{"bn":"একজন ভালো কারীর তিলাওয়াতে একটি ছোট সূরা শোনো।","en":"Listen to a short surah by a good reciter."}},{"title":{"bn":"রেকর্ড করো","en":"Record"},"desc":{"bn":"ফোনে নিজের তিলাওয়াত রেকর্ড করো।","en":"Record yourself reciting it on your phone."}},{"title":{"bn":"মিলিয়ে দেখো","en":"Compare"},"desc":{"bn":"দুটো পাশাপাশি শোনো — কোথায় আলাদা? ভুলের তালিকা লেখো।","en":"Play both side by side — where do they differ? Write down your slips."}},{"title":{"bn":"আয়না ও নাক পরীক্ষা","en":"Mirror and nose tests"},"desc":{"bn":"আয়নায় {{ث ذ ظ}}-এ জিহ্বা দেখো; নাক চেপে গুন্নাহ পরীক্ষা করো; আঙুলে মাদ্দ গোনো।","en":"Watch your tongue on {{ث ذ ظ}} in a mirror; pinch your nose to test ghunnah; count madd on your fingers."}},{"title":{"bn":"একটি ভুল, একটি সপ্তাহ","en":"One mistake, one week"},"desc":{"bn":"সব একসাথে নয় — প্রতি সপ্তাহে একটি ভুল ঠিক করার লক্ষ্য নাও।","en":"Not everything at once — aim to fix one mistake each week."}}]},{"type":"practice","bn":"জোড়ায় জোড়ায় পড়ো — প্রতিটি জোড়ার পার্থক্য যেন স্পষ্ট শোনা যায়।","en":"Read in pairs — make sure the difference in each pair is clearly heard.","lines":["ثَ سَ صَ — ذَ زَ ظَ ضَ","حَ هَ — خَ غَ — عَ أَ","قَلْبٌ كَلْبٌ — طِينٍ التِّينِ","عَلِيمٌ أَلِيمٌ — عَصٰى عَسٰى","مَحْظُورًا مَحْذُورًا","مَلِكِ مَالِكِ — رَبِّ إِنَّ ثُمَّ"]},{"type":"quiz","items":[{"q":{"bn":"{{قَلْبٌ}}-কে {{كَلْبٌ}} পড়লে অর্থ কী হয়?","en":"If {{قَلْبٌ}} is read as {{كَلْبٌ}}, what does it mean?"},"options":[{"bn":"হৃদয়","en":"Heart"},{"bn":"কুকুর","en":"Dog"},{"bn":"অর্থ বদলায় না","en":"No change"}],"answer":1},{"q":{"bn":"কোন হরফ উচ্চারণে জিহ্বার আগা দাঁতের কিনারায় যায় এবং কণ্ঠস্বর থাকে?","en":"Which letter puts the tongue tip on the teeth edges, with voice?"},"options":["ز","ذ","ج"],"answer":1},{"q":{"bn":"{{ض}} কোথা থেকে উচ্চারিত হয়?","en":"Where is {{ض}} pronounced?"},"options":[{"bn":"জিহ্বার পাশ + উপরের মাড়ির দাঁত","en":"Side of the tongue + upper molars"},{"bn":"জিহ্বার আগা + দাঁতের কিনারা","en":"Tongue tip + teeth edges"},{"bn":"দুই ঠোঁট","en":"Both lips"}],"answer":0},{"q":{"bn":"{{عَلِيمٌ}} ও {{أَلِيمٌ}}-এর অর্থ কী?","en":"What do {{عَلِيمٌ}} and {{أَلِيمٌ}} mean?"},"options":[{"bn":"দুটোই ‘সর্বজ্ঞ’","en":"Both ‘All-Knowing’"},{"bn":"সর্বজ্ঞ / যন্ত্রণাদায়ক","en":"All-Knowing / painful"},{"bn":"যন্ত্রণাদায়ক / সর্বজ্ঞ","en":"Painful / All-Knowing"}],"answer":1},{"q":{"bn":"যবরের সঠিক আওয়াজ কোনটি?","en":"What is the correct sound of fatha?"},"options":[{"bn":"বাংলা ‘অ’ (ও-ঘেঁষা)","en":"The Bangla ‘o’-like vowel"},{"bn":"খোলা ছোট ‘আ’","en":"A short open ‘a’"},{"bn":"‘এ’","en":"‘e’"}],"answer":1},{"q":{"bn":"{{و}} উচ্চারণে কোনটি ঠিক?","en":"Which is right for {{و}}?"},"options":[{"bn":"দাঁত নিচের ঠোঁটে (ভ)","en":"Teeth on the lower lip (v)"},{"bn":"ঠোঁট গোল, দাঁত লাগবে না (ওয়া)","en":"Round lips, teeth off (wa)"},{"bn":"জিহ্বা দাঁতে","en":"Tongue at the teeth"}],"answer":1},{"q":{"bn":"{{طِينٍ}} মানে কাদামাটি। {{التِّينِ}} মানে কী?","en":"{{طِينٍ}} means clay. What does {{التِّينِ}} mean?"},"options":[{"bn":"ডুমুর","en":"Fig"},{"bn":"পানি","en":"Water"},{"bn":"একই — কাদামাটি","en":"The same — clay"}],"answer":0},{"q":{"bn":"{{خ}}-এর সঠিক বর্ণনা কোনটি?","en":"Which best describes {{خ}}?"},"options":[{"bn":"বাংলা ‘খ’ (ক+হ)","en":"Bangla ‘kh’ (k+h)"},{"bn":"গলার উপরে খসখসে ঘষা, মোটা","en":"A raspy scrape high in the throat, heavy"},{"bn":"ঠোঁটের হরফ","en":"A lip letter"}],"answer":1}]}]},{"id":"tj-colour-map","icon":"لون","title":{"bn":"তাজবীদের রঙের মানচিত্র","en":"The Tajweed Colour Map"},"subtitle":{"bn":"সব নিয়ম এক নজরে — রং দেখে নিয়ম চেনো, তারপর বড় পরীক্ষা","en":"Every rule at a glance — know each rule by its colour, then the big quiz"},"minutes":20,"goals":[{"bn":"প্রতিটি নিয়মকে তার রঙের সাথে মিলিয়ে মনে রাখব","en":"Link every rule with its colour"},{"bn":"ছোট সূরায় একসাথে সব নিয়ম চিনব","en":"Spot all the rules together in short surahs"},{"bn":"বড় মিশ্র পরীক্ষায় নিজেকে যাচাই করব","en":"Test yourself with a big mixed quiz"}],"blocks":[{"type":"text","bn":"মাশাআল্লাহ! তুমি তাজবীদের মূল নিয়মগুলো শিখে ফেলেছ। এই কোর্সে প্রতিটি নিয়মের একটি নির্দিষ্ট **রং** আছে। রং দেখলেই যেন নিয়মটা মাথায় আসে — এটাই এই পাঠের লক্ষ্য।","en":"MashaAllah! You have learned the core rules of tajweed. In this course every rule has its own **colour**. The goal of this lesson: see the colour, recall the rule."},{"type":"table","title":{"bn":"রঙের মানচিত্র","en":"The colour map"},"head":[{"bn":"রং","en":"Colour"},{"bn":"নিয়ম","en":"Rule"},{"bn":"কখন","en":"When"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"সবুজ","en":"Green"},{"bn":"গুন্নাহ","en":"Ghunnah"},{"bn":"{{نّ}} বা {{مّ}}","en":"{{نّ}} or {{مّ}}"},"إِنَّ ثُمَّ"],[{"bn":"সবুজ","en":"Green"},{"bn":"ইখফা","en":"Ikhfa"},{"bn":"নূন সাকিন/তানবীন + ১৫ হরফ","en":"Noon sakinah/tanween + 15 letters"},"أَنْتَ مِنْ قَبْلِ"],[{"bn":"সবুজ","en":"Green"},{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"},{"bn":"মীম সাকিন + {{ب}}","en":"Meem sakinah + {{ب}}"},"تَرْمِيهِمْ بِحِجَارَةٍ"],[{"bn":"ধূসর","en":"Gray"},{"bn":"ইদগাম","en":"Idgham"},{"bn":"নূন সাকিন/তানবীন + {{يَرْمَلُونَ}}","en":"Noon sakinah/tanween + {{يَرْمَلُونَ}}"},"مَنْ يَقُولُ مِنْ رَبِّهِمْ"],[{"bn":"ধূসর","en":"Gray"},{"bn":"ইদগাম শাফাবী","en":"Idgham shafawi"},{"bn":"মীম সাকিন + {{م}}","en":"Meem sakinah + {{م}}"},"لَهُمْ مَا"],[{"bn":"নীল","en":"Blue"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"নূন সাকিন/তানবীন + {{ب}}","en":"Noon sakinah/tanween + {{ب}}"},"مِنْ بَعْدِ"],[{"bn":"বেগুনি","en":"Purple"},{"bn":"ইযহার","en":"Izhar"},{"bn":"নূন সাকিন/তানবীন + গলার ৬ হরফ","en":"Noon sakinah/tanween + 6 throat letters"},"مَنْ آمَنَ"],[{"bn":"বেগুনি","en":"Purple"},{"bn":"ইযহার শাফাবী","en":"Izhar shafawi"},{"bn":"মীম সাকিন + বাকি ২৬ হরফ","en":"Meem sakinah + the other 26 letters"},"هُمْ فِيهَا"],[{"bn":"কমলা","en":"Orange"},{"bn":"কলকলা","en":"Qalqalah"},{"bn":"{{قُطْبُ جَدٍّ}} সাকিন বা থামলে","en":"{{قُطْبُ جَدٍّ}} with sukun or at a stop"},"قَدْ أَفْلَحَ الْفَلَقِ"],[{"bn":"লাল","en":"Red"},{"bn":"মাদ্দ","en":"Madd"},{"bn":"মাদ্দের হরফ + হামযা/সুকুন (২–৬ হরকত)","en":"Madd letter + hamza/sukun (2–6 counts)"},"جَاءَ الضَّالِّينَ"]]},{"type":"tip","kind":"memory","bn":"রঙের গল্প: **সবুজ** — নাকে গুনগুন, যেন সবুজ পাতায় বাতাস। **ধূসর** — হরফটি মিশে ফিকে হয়ে যায়। **নীল** — নূন রূপ বদলে মীম। **বেগুনি** — স্পষ্ট, পরিষ্কার। **কমলা** — কমলা রঙের বলের মতো লাফ। **লাল** — রাবার ব্যান্ডের মতো টেনে লম্বা।","en":"The colour story: **Green** — a hum in the nose, like wind in green leaves. **Gray** — the letter merges and fades. **Blue** — noon transforms into meem. **Purple** — clear and visible. **Orange** — bounces like an orange ball. **Red** — stretches like a red rubber band."},{"type":"rule","name":{"bn":"সবুজ পরিবার — নাকের সুর","en":"The Green Family — Nasal Hum"},"ar":"غُنَّة • إِخْفَاء","color":"green","letters":"نّ مّ • ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك • مْ + ب","desc":{"bn":"গুন্নাহ, ইখফা ও ইখফা শাফাবী — তিনটিতেই দুই হরকত নাকি সুর।","en":"Ghunnah, ikhfa and ikhfa shafawi — all three carry a 2-count nasal hum."},"how":{"bn":"নাক দিয়ে দুই হরকত গুনগুন; নাক চাপলে আওয়াজ আটকে যাবে।","en":"Hum through the nose for 2 counts; pinching the nose should block it."},"examples":[{"ar":"إِنَّ","hl":"نَّ","tr":{"bn":"ইন্‌ঁনা","en":"inna"}},{"ar":"يُنْفِقُونَ","hl":"نْف","tr":{"bn":"ইউঁনফিক্বূন","en":"yunfiqoon"}},{"ar":"وَمَا هُمْ بِمُؤْمِنِينَ","hl":"مْ ب","tr":{"bn":"ওয়ামা হুমঁ বিমু'মিনীন","en":"wa maa hum bimu'mineen"}}]},{"type":"rule","name":{"bn":"ধূসর পরিবার — মিশে যাওয়া","en":"The Gray Family — Merging"},"ar":"إِدْغَام","color":"gray","letters":"ي ر م ل و ن • مْ + م","desc":{"bn":"নূন সাকিন/তানবীন বা মীম সাকিন পরের হরফে মিশে অদৃশ্য — {{ي ن م و}} ও {{م}}-এ গুন্নাহসহ, {{ل ر}}-এ গুন্নাহ ছাড়া।","en":"Noon sakinah/tanween or meem sakinah vanishes into the next letter — with ghunnah before {{ي ن م و}} and {{م}}, without ghunnah before {{ل ر}}."},"how":{"bn":"প্রথম হরফটি বলবে না; পরের হরফকে তাশদীদসহ পড়ো।","en":"Skip the first letter; read the next one with shaddah."},"examples":[{"ar":"مِنْ وَالٍ","hl":"نْ و","tr":{"bn":"মিওঁ ওয়া-ল","en":"miw-waal"}},{"ar":"غَفُورٌ رَحِيمٌ","hl":"رٌ ر","tr":{"bn":"গাফূরুর রহীম","en":"ghafoorur-raḥeem"}},{"ar":"كَمْ مِنْ فِئَةٍ","hl":"مْ م","tr":{"bn":"কামঁ মিন ফিআতিন","en":"kam-min fi'atin"}}]},{"type":"rule","name":{"bn":"নীল — রূপ বদল","en":"Blue — Transformation"},"ar":"إِقْلَاب","color":"blue","letters":"ب","desc":{"bn":"নূন সাকিন/তানবীনের পর {{ب}} — নূন হয়ে যায় মীম, সাথে গুন্নাহ।","en":"Noon sakinah/tanween before {{ب}} — the noon becomes a meem, with ghunnah."},"how":{"bn":"ঠোঁট আলতো মিলিয়ে ‘ম্‌’ + দুই হরকত গুন্নাহ।","en":"Close the lips gently for ‘m’ + a 2-count hum."},"examples":[{"ar":"سَمِيعٌ بَصِيرٌ","hl":"عٌ ب","tr":{"bn":"সামী‘উমঁ বাছীর","en":"samee'um-baṣeer"}}]},{"type":"rule","name":{"bn":"বেগুনি — স্পষ্ট","en":"Purple — Clarity"},"ar":"إِظْهَار","color":"purple","letters":"ء ه ع ح غ خ","desc":{"bn":"গলার হরফের আগে নূন সাকিন/তানবীন, আর {{ب}} ও {{م}} ছাড়া সব হরফের আগে মীম সাকিন — পরিষ্কার পড়ো, গুন্নাহ টানবে না।","en":"Noon sakinah/tanween before a throat letter, and meem sakinah before any letter except {{ب}} and {{م}} — read clearly, no held ghunnah."},"how":{"bn":"পরিষ্কার ‘ন্‌’ বা ‘ম্‌’, তারপর সোজা পরের হরফ।","en":"A clean ‘n’ or ‘m’, then straight on."},"examples":[{"ar":"عَلِيمٌ حَكِيمٌ","hl":"مٌ ح","tr":{"bn":"‘আলীমুন হাকীম","en":"'aleemun ḥakeem"}},{"ar":"عَلَيْهِمْ وَلَا","hl":"مْ و","tr":{"bn":"‘আলাইহিম ওয়ালা","en":"'alayhim wa laa"}}]},{"type":"rule","name":{"bn":"কমলা — লাফ","en":"Orange — Bounce"},"ar":"قَلْقَلَة","color":"orange","letters":"ق ط ب ج د","desc":{"bn":"{{قُطْبُ جَدٍّ}}-এর হরফ সাকিন হলে প্রতিধ্বনি — শব্দের মাঝে ছোট, থামলে বড়।","en":"When a letter of {{قُطْبُ جَدٍّ}} has sukun it echoes — small mid-word, bigger at a stop."},"how":{"bn":"হালকা লাফ, কিন্তু কোনো হরকত যোগ নয়।","en":"A light bounce, but never add a vowel."},"examples":[{"ar":"يَدْخُلُونَ","hl":"دْ","tr":{"bn":"ইয়াদ্‌খুলূন","en":"yadkhuloon"}},{"ar":"الْفَلَقِ","hl":"قِ","tr":{"bn":"আলফালাক্ব্‌","en":"al-falaq"}}]},{"type":"rule","name":{"bn":"লাল — টান","en":"Red — Stretch"},"ar":"مَدّ","color":"red","letters":"ا و ي","desc":{"bn":"তবঈ ২; মুত্তাসিল ও মুনফাসিল ৪–৫; লাযিম ৬; আরিদ ও লীন থামলে ২/৪/৬।","en":"Natural 2; muttasil and munfasil 4–5; lazim 6; 'arid and leen at a stop 2/4/6."},"how":{"bn":"আঙুলে হরকত গুনে সমান মাপে টানো, পুরো তিলাওয়াতে একই মাপ রাখো।","en":"Count on your fingers, stretch evenly, and keep the same length throughout."},"examples":[{"ar":"قَالَ","hl":"قَا","tr":{"bn":"ক্বা-লা","en":"qaala"}},{"ar":"السَّمَاءِ","hl":"مَاء","tr":{"bn":"আসসামা----ই","en":"as-samaaaa'i"}},{"ar":"الضَّالِّينَ","hl":"ضَّا","tr":{"bn":"আদ্দ্বা------ল্লীন","en":"aḍ-ḍaaaaaal-leen"}}]},{"type":"tip","kind":"tip","bn":"যেসব নিয়মের রং নেই সেগুলোও ভুলবে না: **মোটা-চিকন হরফ**, **রা-এর নিয়ম**, **আল্লাহ শব্দের লাম** আর **থামার নিয়ম**। এগুলো চোখে নয়, কানে ধরা পড়ে — তাই ভালো কারীর তিলাওয়াত বেশি বেশি শোনো।","en":"Don't forget the rules that have no colour: **heavy and light letters**, **the Ra rules**, **the Lam of Allah** and **the stopping rules**. You catch these with your ears, not your eyes — so listen to good reciters often."},{"type":"table","title":{"bn":"রং খোঁজো: সূরা ইখলাস","en":"Colour hunt: Surah al-Ikhlas"},"head":[{"bn":"অংশ","en":"Phrase"},{"bn":"রং ও নিয়ম","en":"Colour and rule"}],"rows":[["قُلْ هُوَ اللّٰهُ",{"bn":"রং নেই — আল্লাহ শব্দের লাম মোটা (আগে যবর)","en":"No colour — heavy Lam of Allah (fatha before)"}],["أَحَدٌ",{"bn":"কমলা — থামলে বড় কলকলা","en":"Orange — major qalqalah at the stop"}],["لَمْ يَلِدْ",{"bn":"বেগুনি (মীম + {{ي}}) ও কমলা ({{دْ}})","en":"Purple (meem + {{ي}}) and orange ({{دْ}})"}],["وَلَمْ يُولَدْ",{"bn":"বেগুনি, লাল ({{يُو}} — ২ হরকত) ও কমলা","en":"Purple, red ({{يُو}} — 2 counts) and orange"}],["وَلَمْ يَكُنْ لَهُ",{"bn":"বেগুনি (মীম + {{ي}}) ও ধূসর (নূন + {{ل}}, গুন্নাহ ছাড়া)","en":"Purple (meem + {{ي}}) and gray (noon + {{ل}}, no ghunnah)"}],["كُفُوًا أَحَدٌ",{"bn":"বেগুনি (তানবীন + হামযা) ও কমলা","en":"Purple (tanween + hamza) and orange"}]]},{"type":"practice","bn":"তিনটি ছোট সূরা পড়ো। প্রতিটি শব্দে থেমে ভাবো: কোন রং? তারপর সুন্দর করে মিলিয়ে পড়ো।","en":"Read three short surahs. On each word ask: which colour? Then recite them smoothly.","lines":["قُلْ هُوَ اللّٰهُ أَحَدٌ","اللّٰهُ الصَّمَدُ","لَمْ يَلِدْ وَلَمْ يُولَدْ","وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ","فَصَلِّ لِرَبِّكَ وَانْحَرْ","إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ","وَالْعَصْرِ","إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ","إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ"]},{"type":"quiz","title":{"bn":"বড় মিশ্র পরীক্ষা","en":"The big mixed quiz"},"items":[{"q":{"bn":"এই কোর্সে ইখফার রং কী?","en":"In this course, what colour is ikhfa?"},"options":[{"bn":"সবুজ","en":"Green"},{"bn":"নীল","en":"Blue"},{"bn":"লাল","en":"Red"}],"answer":0},{"q":{"bn":"নীল রং কোন নিয়মের?","en":"Which rule is blue?"},"options":[{"bn":"ইদগাম","en":"Idgham"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"কলকলা","en":"Qalqalah"}],"answer":1},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule is here?"},"ar":"مِنْ نِعْمَةٍ","options":[{"bn":"গুন্নাহসহ ইদগাম","en":"Idgham with ghunnah"},{"bn":"ইযহার","en":"Izhar"},{"bn":"ইখফা","en":"Ikhfa"}],"answer":0},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule is here?"},"ar":"يَنْهَوْنَ","options":[{"bn":"ইখফা","en":"Ikhfa"},{"bn":"ইযহার","en":"Izhar"},{"bn":"ইদগাম","en":"Idgham"}],"answer":1,"explain":{"bn":"নূন সাকিনের পর গলার হরফ {{ه}}।","en":"Noon sakinah followed by the throat letter {{ه}}."}},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule is here?"},"ar":"كُنْتُمْ","options":[{"bn":"ইখফা","en":"Ikhfa"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"ইযহার","en":"Izhar"}],"answer":0,"explain":{"bn":"নূন সাকিন + {{ت}} = ইখফা।","en":"Noon sakinah + {{ت}} = ikhfa."}},{"q":{"bn":"এখানে কোন নিয়ম?","en":"Which rule is here?"},"ar":"أَنْبِئُونِي","options":[{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"},{"bn":"ইকলাব","en":"Iqlab"},{"bn":"গুন্নাহসহ ইদগাম","en":"Idgham with ghunnah"}],"answer":1},{"q":{"bn":"{{عَلَيْهِمْ وَلَا}}-তে মীম কেমন?","en":"How is the meem in {{عَلَيْهِمْ وَلَا}}?"},"options":[{"bn":"ইযহার শাফাবী — স্পষ্ট","en":"Izhar shafawi — clear"},{"bn":"ইদগাম শাফাবী","en":"Idgham shafawi"},{"bn":"ইখফা শাফাবী","en":"Ikhfa shafawi"}],"answer":0},{"q":{"bn":"{{يَا أَيُّهَا}}-তে মাদ্দ কত হরকত?","en":"How long is the madd in {{يَا أَيُّهَا}}?"},"options":["2","4–5","6"],"answer":1,"explain":{"bn":"মাদ্দ মুনফাসিল।","en":"Madd munfasil."}},{"q":{"bn":"{{الْحَاقَّةُ}}-তে মাদ্দ কত হরকত?","en":"How long is the madd in {{الْحَاقَّةُ}}?"},"options":["2","4","6"],"answer":2,"explain":{"bn":"আলিফের পর স্থায়ী তাশদীদ — মাদ্দ লাযিম।","en":"A permanent shaddah after the alif — madd lazim."}},{"q":{"bn":"কোন শব্দে কলকলা আছে?","en":"Which word has qalqalah?"},"options":["يَجْعَلُونَ","يَعْلَمُونَ","يَسْمَعُونَ"],"answer":0,"explain":{"bn":"{{جْ}} — সাকিন জীম।","en":"{{جْ}} — a sakin jim."}},{"q":{"bn":"{{شَهِدَ اللّٰهُ}}-তে আল্লাহ শব্দের লাম কেমন?","en":"In {{شَهِدَ اللّٰهُ}}, how is the Lam of Allah?"},"options":[{"bn":"মোটা","en":"Heavy"},{"bn":"চিকন","en":"Light"}],"answer":0},{"q":{"bn":"{{فِرْعَوْنَ}}-এ রা কেমন?","en":"How is the Ra in {{فِرْعَوْنَ}}?"},"options":[{"bn":"মোটা","en":"Heavy"},{"bn":"চিকন","en":"Light"}],"answer":1,"explain":{"bn":"রা সাকিন, আগে আসল যের, পরে মোটা হরফ নেই।","en":"Sakin Ra after an original kasra, with no heavy letter after it."}},{"q":{"bn":"{{حَكِيمًا}}-তে থামলে কীভাবে পড়বে?","en":"How do you stop on {{حَكِيمًا}}?"},"options":[{"bn":"হাকীমা-","en":"ḥakeemaa"},{"bn":"হাকীমান","en":"ḥakeeman"},{"bn":"হাকীমাহ","en":"ḥakeemah"}],"answer":0},{"q":{"bn":"কোন হরফটি সবসময় মোটা?","en":"Which letter is always heavy?"},"options":["ظ","ذ","ز"],"answer":0},{"q":{"bn":"{{ثُمَّ}}-এ কী করতে হবে?","en":"What must you do in {{ثُمَّ}}?"},"options":[{"bn":"দুই হরকত গুন্নাহ","en":"A 2-count ghunnah"},{"bn":"ছয় হরকত মাদ্দ","en":"A 6-count madd"},{"bn":"কলকলা","en":"Qalqalah"}],"answer":0},{"q":{"bn":"এই চিহ্ন দেখলে কী করবে?","en":"What do you do at this sign?"},"ar":"م","options":[{"bn":"অবশ্যই থামবে","en":"Must stop"},{"bn":"থামবে না","en":"Do not stop"},{"bn":"সাকতা করবে","en":"Make a saktah"}],"answer":0}]}]}]});
AQ.units.push({"id":"vocab","order":4,"icon":"ك","color":"amber","title":{"bn":"কুরআনের শব্দভাণ্ডার","en":"Quranic Vocabulary"},"subtitle":{"bn":"বারবার আসা শব্দগুলো শিখে কুরআন বোঝার দরজা খুলি","en":"Learn the words that repeat most and open the door to understanding"},"lessons":[{"id":"vocab-why","icon":"قُ","title":{"bn":"শব্দ জানলেই কুরআন খোলে","en":"Why Vocabulary Unlocks the Quran"},"subtitle":{"bn":"অল্প কিছু শব্দ বারবার ফিরে আসে — সেখান থেকেই শুরু","en":"A small set of words keeps coming back — start there"},"minutes":12,"goals":[{"bn":"বুঝব কেন অল্প শব্দ শিখলেই কুরআনের বড় অংশ চেনা যায়","en":"See why a few words cover a big part of the Quran"},{"bn":"শব্দ শেখার সহজ ও কার্যকর পদ্ধতি জানব","en":"Learn a simple, effective way to study words"},{"bn":"১৬টি ‘সুপার শব্দ’ মুখস্থ করব","en":"Memorise 16 ‘super words’"}],"blocks":[{"type":"text","bn":"কুরআন পড়তে পারা এক জিনিস, আর **বুঝতে** পারা আরেক জিনিস। সুখবর হলো, কুরআনে কিছু শব্দ বারবার, শত শত — এমনকি হাজার হাজার বার ফিরে আসে। যেমন {{اللّٰه}} শব্দটি কুরআনে হাজারেরও বেশি বার এসেছে, আর {{مِنْ}} বা {{فِي}}-এর মতো ছোট শব্দ তো প্রায় প্রতিটি পৃষ্ঠায়।","en":"Reading the Quran is one thing; **understanding** it is another. The good news: some words come back again and again — hundreds, even thousands of times. The word {{اللّٰه}} alone appears well over a thousand times, and little words like {{مِنْ}} and {{فِي}} show up on almost every page."},{"type":"text","bn":"তাই আমরা শুরু করব সবচেয়ে বেশি আসা শব্দ দিয়ে। প্রতিটি নতুন শব্দ শেখার পর যখন তুমি সালাতে বা তিলাওয়াতে তাকে চিনে ফেলবে, তখন আয়াতগুলো তোমার সাথে ‘কথা বলতে’ শুরু করবে।","en":"So we begin with the most frequent words. Each time you recognise a newly learned word in salah or recitation, the verses start to ‘speak’ to you."},{"type":"steps","title":{"bn":"কীভাবে শব্দ শিখবে","en":"How to study words"},"items":[{"title":{"bn":"প্রতিদিন অল্প করে","en":"A little every day"},"desc":{"bn":"দিনে ৫–১০ মিনিট ফ্ল্যাশকার্ড দেখো। একদিনে অনেক শেখার চেয়ে প্রতিদিন অল্প শেখা অনেক বেশি কাজের।","en":"Review flashcards for 5–10 minutes a day. A little daily beats a lot at once."}},{"title":{"bn":"জোরে উচ্চারণ করো","en":"Say it aloud"},"desc":{"bn":"প্রতিটি শব্দ শুনে নিজে জোরে বলো। চোখ, কান আর জিহ্বা — তিনটিই কাজে লাগাও।","en":"Listen and repeat each word aloud. Use your eyes, ears and tongue together."}},{"title":{"bn":"মূল অক্ষর (রুট) খেয়াল করো","en":"Notice the root"},"desc":{"bn":"বেশিরভাগ আরবি শব্দের ভেতরে তিনটি মূল অক্ষর থাকে। একটি রুট চিনলে পুরো একটি শব্দ-পরিবার চেনা যায়।","en":"Most Arabic words are built on three root letters. Know one root and you recognise a whole word family."}},{"title":{"bn":"সালাতে শব্দ খোঁজো","en":"Spot words in salah"},"desc":{"bn":"সালাতে যা পড়ো, তার মধ্যে আজকের শেখা শব্দটি খুঁজে বের করো। এতে মনোযোগ (খুশু) বাড়ে, শব্দও মনে থাকে।","en":"Find today's word in what you recite in salah. It deepens focus (khushoo') and makes the word stick."}}]},{"type":"vocab","title":{"bn":"১৬টি সুপার শব্দ","en":"16 super words"},"items":[{"ar":"اللّٰه","tr":{"bn":"আল্লাহ","en":"Allaah"},"mean":{"bn":"আল্লাহ (একমাত্র সত্য উপাস্যের নাম)","en":"Allah (the name of the one true God)"},"example":{"ar":"اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ","mean":{"bn":"আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই","en":"Allah — there is no god but He"},"ref":"2:255"}},{"ar":"رَبّ","tr":{"bn":"রব্ব","en":"rabb"},"mean":{"bn":"রব, প্রতিপালক, মালিক","en":"Lord, Sustainer, Master"},"root":"ر ب ب","example":{"ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি সৃষ্টিজগতের রব","en":"All praise is for Allah, Lord of all the worlds"},"ref":"1:2"}},{"ar":"إِلٰه","tr":{"bn":"ইলাহ","en":"ilaah"},"mean":{"bn":"উপাস্য, মাবুদ","en":"god, one who is worshipped"},"root":"أ ل ه","example":{"ar":"وَإِلٰهُكُمْ إِلٰهٌ وَاحِدٌ","mean":{"bn":"আর তোমাদের ইলাহ একজনই ইলাহ","en":"And your God is one God"},"ref":"2:163"}},{"ar":"قَالَ","tr":{"bn":"ক্বালা","en":"qaala"},"mean":{"bn":"সে বলল","en":"he said"},"root":"ق و ل","example":{"ar":"قَالَ رَبِّ اشْرَحْ لِي صَدْرِي","mean":{"bn":"সে বলল, হে আমার রব, আমার বুক প্রশস্ত করে দিন","en":"He said, ‘My Lord, open up my chest for me’"},"ref":"20:25"}},{"ar":"قُلْ","tr":{"bn":"ক্বুল","en":"qul"},"mean":{"bn":"বলো (আদেশ)","en":"say! (command)"},"root":"ق و ل","example":{"ar":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","mean":{"bn":"বলো, আমি আশ্রয় চাই ভোরের রবের কাছে","en":"Say, ‘I seek refuge with the Lord of daybreak’"},"ref":"113:1"}},{"ar":"مِنْ","tr":{"bn":"মিন","en":"min"},"mean":{"bn":"থেকে, হতে, -এর মধ্য থেকে","en":"from, of"},"example":{"ar":"مِنْ شَرِّ مَا خَلَقَ","mean":{"bn":"তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে","en":"from the evil of what He created"},"ref":"113:2"}},{"ar":"فِي","tr":{"bn":"ফী","en":"fee"},"mean":{"bn":"-এ, -তে, মধ্যে","en":"in"},"example":{"ar":"فِي جِيدِهَا حَبْلٌ مِنْ مَسَدٍ","mean":{"bn":"তার গলায় খেজুর-আঁশের পাকানো দড়ি","en":"around her neck a rope of palm fibre"},"ref":"111:5"}},{"ar":"عَلَى","tr":{"bn":"'আলা","en":"'alaa"},"mean":{"bn":"উপর, -এর উপরে","en":"on, upon, over"},"example":{"ar":"الرَّحْمٰنُ عَلَى الْعَرْشِ اسْتَوَى","mean":{"bn":"দয়াময় আরশের উপর সমুন্নত","en":"The Most Merciful rose over the Throne"},"ref":"20:5"}},{"ar":"إِلَى","tr":{"bn":"ইলা","en":"ilaa"},"mean":{"bn":"-এর দিকে, পর্যন্ত","en":"to, towards"},"example":{"ar":"إِنَّ إِلَى رَبِّكَ الرُّجْعَى","mean":{"bn":"নিশ্চয়ই তোমার রবের দিকেই ফিরে যাওয়া","en":"Indeed, to your Lord is the return"},"ref":"96:8"}},{"ar":"مَا","tr":{"bn":"মা","en":"maa"},"mean":{"bn":"যা / কী / না (প্রসঙ্গ অনুযায়ী)","en":"what / that which / not (by context)"},"example":{"ar":"مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ","mean":{"bn":"তার কোনো কাজে আসেনি তার সম্পদ, আর যা সে উপার্জন করেছে","en":"His wealth did not avail him, nor what he earned"},"ref":"111:2"}},{"ar":"لَا","tr":{"bn":"লা","en":"laa"},"mean":{"bn":"না, নেই","en":"no, not"},"example":{"ar":"ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ","mean":{"bn":"এই সেই কিতাব, এতে কোনো সন্দেহ নেই","en":"That is the Book, no doubt in it"},"ref":"2:2"}},{"ar":"إِنَّ","tr":{"bn":"ইন্না","en":"inna"},"mean":{"bn":"নিশ্চয়ই","en":"indeed, surely"},"example":{"ar":"إِنَّ مَعَ الْعُسْرِ يُسْرًا","mean":{"bn":"নিশ্চয়ই কষ্টের সাথে আছে স্বস্তি","en":"Indeed, with hardship comes ease"},"ref":"94:6"}},{"ar":"الَّذِي","tr":{"bn":"আল্লাযী","en":"alladhee"},"mean":{"bn":"যে, যিনি (পুরুষ, একবচন)","en":"who, the one who (masc. sing.)"},"example":{"ar":"الَّذِي عَلَّمَ بِالْقَلَمِ","mean":{"bn":"যিনি কলমের সাহায্যে শিখিয়েছেন","en":"who taught by the pen"},"ref":"96:4"}},{"ar":"هُوَ","tr":{"bn":"হুওয়া","en":"huwa"},"mean":{"bn":"সে, তিনি (পুরুষ)","en":"he, it"},"example":{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","mean":{"bn":"বলো, তিনিই আল্লাহ, এক-অদ্বিতীয়","en":"Say, ‘He is Allah, the One’"},"ref":"112:1"}},{"ar":"كُلّ","tr":{"bn":"কুল্ল","en":"kull"},"mean":{"bn":"প্রত্যেক, সব","en":"every, all"},"root":"ك ل ل","example":{"ar":"كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ","mean":{"bn":"প্রত্যেক প্রাণ মৃত্যুর স্বাদ গ্রহণ করবে","en":"Every soul will taste death"},"ref":"3:185"}},{"ar":"شَيْء","tr":{"bn":"শাই","en":"shay'"},"mean":{"bn":"বস্তু, কিছু","en":"thing, anything"},"root":"ش ي أ","example":{"ar":"إِنَّ اللّٰهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","mean":{"bn":"নিশ্চয়ই আল্লাহ সব কিছুর উপর ক্ষমতাবান","en":"Indeed, Allah has power over all things"},"ref":"2:20"}}]},{"type":"tip","kind":"memory","bn":"তুমি আসলে অনেক আরবি শব্দ আগে থেকেই জানো! বাংলায় আমরা রোজ বলি **কিতাব, কলম, দুনিয়া, আখিরাত, জান্নাত, রহমত, ইলম, হিসাব, খবর** — এগুলো সবই আরবি থেকে এসেছে। এই কোর্সে প্রতিটি পাঠে এমন ‘চেনা শব্দ’ খুঁজে দেব, যাতে মনে রাখা সহজ হয়।","en":"You already know lots of Arabic! Everyday Bangla words like **kitab, kalam, duniya, akhirat, jannat, rahmat, ilm, hisab, khabar** all come from Arabic. In every lesson we'll point out such ‘familiar words’ to make memorising easier."},{"type":"tip","kind":"tip","bn":"{{قَالَ}} (সে বলল) আর {{قُلْ}} (বলো!) একই মূল {{ق و ل}} থেকে। বাংলায় ‘কওল দেওয়া’ (কথা দেওয়া) — এই ‘কওল’ শব্দটিও এখান থেকেই।","en":"{{قَالَ}} (he said) and {{قُلْ}} (say!) share the root {{ق و ل}}. The Bangla phrase ‘kowl dewa’ (to give one's word) comes from the same root."},{"type":"examples","title":{"bn":"সুপার শব্দ দিয়ে তৈরি বাক্য","en":"Phrases made of super words"},"items":[{"ar":"لَا إِلٰهَ إِلَّا اللّٰهُ","tr":{"bn":"লা ইলাহা ইল্লাল্লাহ","en":"laa ilaaha illallaah"},"mean":{"bn":"আল্লাহ ছাড়া কোনো ইলাহ নেই","en":"There is no god but Allah"},"note":{"bn":"{{إِلَّا}} মানে ‘ছাড়া’ — পরের পাঠগুলোতে আবার আসবে","en":"{{إِلَّا}} means ‘except’ — you'll meet it again soon"},"hl":"إِلٰهَ"},{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","tr":{"bn":"ক্বুল হুওয়াল্লাহু আহাদ","en":"qul huwallaahu aḥad"},"mean":{"bn":"বলো, তিনিই আল্লাহ, এক-অদ্বিতীয়","en":"Say, He is Allah, the One"},"note":{"bn":"সূরা ইখলাস ১১২:১","en":"Al-Ikhlas 112:1"},"hl":"هُوَ"},{"ar":"إِنَّ اللّٰهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":{"bn":"ইন্নাল্লাহা 'আলা কুল্লি শাইয়িন ক্বাদীর","en":"innallaaha 'alaa kulli shay'in qadeer"},"mean":{"bn":"নিশ্চয়ই আল্লাহ সব কিছুর উপর ক্ষমতাবান","en":"Indeed, Allah has power over all things"},"note":{"bn":"এই বাক্যটি কুরআনে বহুবার এসেছে, যেমন ২:২০","en":"This sentence appears many times, e.g. 2:20"},"hl":"كُلِّ شَيْءٍ"},{"ar":"إِنَّ إِلَى رَبِّكَ الرُّجْعَى","tr":{"bn":"ইন্না ইলা রব্বিকার রুজ'আ","en":"inna ilaa rabbikar-ruj'aa"},"mean":{"bn":"নিশ্চয়ই তোমার রবের দিকেই ফিরে যাওয়া","en":"Indeed, to your Lord is the return"},"note":{"bn":"সূরা আলাক ৯৬:৮","en":"Al-'Alaq 96:8"},"hl":"إِلَى"}]},{"type":"quiz","items":[{"q":{"bn":"{{رَبّ}} শব্দের অর্থ কী?","en":"What does {{رَبّ}} mean?"},"ar":"رَبّ","options":[{"bn":"রব, প্রতিপালক","en":"Lord, Sustainer"},{"bn":"কিতাব","en":"book"},{"bn":"দিন","en":"day"},{"bn":"নবী","en":"prophet"}],"answer":0},{"q":{"bn":"{{قَالَ}} মানে কী?","en":"What does {{قَالَ}} mean?"},"ar":"قَالَ","options":[{"bn":"বলো!","en":"say!"},{"bn":"সে বলল","en":"he said"},{"bn":"সে শুনল","en":"he heard"}],"answer":1,"explain":{"bn":"{{قَالَ}} অতীত কাল — ‘সে বলল’। আদেশ ‘বলো!’ হলো {{قُلْ}}।","en":"{{قَالَ}} is past tense — ‘he said’. The command ‘say!’ is {{قُلْ}}."}},{"q":{"bn":"‘-এর দিকে’ বোঝাতে কোন শব্দ?","en":"Which word means ‘to, towards’?"},"options":["مِنْ","فِي","إِلَى","عَلَى"],"answer":2},{"q":{"bn":"{{فِي}} শব্দের অর্থ —","en":"{{فِي}} means —"},"ar":"فِي","options":[{"bn":"থেকে","en":"from"},{"bn":"-এ, মধ্যে","en":"in"},{"bn":"উপরে","en":"on"}],"answer":1},{"q":{"bn":"{{إِنَّ}} মানে কী?","en":"What does {{إِنَّ}} mean?"},"ar":"إِنَّ","options":[{"bn":"নিশ্চয়ই","en":"indeed"},{"bn":"না","en":"no"},{"bn":"যদি","en":"if"}],"answer":0},{"q":{"bn":"‘প্রত্যেক, সব’ — আরবিতে?","en":"‘Every, all’ in Arabic?"},"options":["شَيْء","كُلّ","مَا","هُوَ"],"answer":1},{"q":{"bn":"{{قَالَ}} আর {{قُلْ}} — দুটোর মূল অক্ষর কী?","en":"What root do {{قَالَ}} and {{قُلْ}} share?"},"options":["ق و ل","ق ل ب","ك ل م"],"answer":0},{"q":{"bn":"শব্দ শেখার সবচেয়ে ভালো অভ্যাস কোনটি?","en":"What is the best word-learning habit?"},"options":[{"bn":"মাসে একদিন অনেকক্ষণ","en":"One long session a month"},{"bn":"প্রতিদিন অল্প সময়","en":"A little every day"},{"bn":"শুধু পরীক্ষার আগে","en":"Only before exams"}],"answer":1}]}]},{"id":"vocab-fatiha","icon":"ف","title":{"bn":"সূরা ফাতিহা ও সালাতের শব্দ","en":"Words of Al-Fatiha & Salah"},"subtitle":{"bn":"যে শব্দগুলো তুমি দিনে বহুবার পড়ো, আজ সেগুলোর অর্থ জানো","en":"Finally understand the words you recite many times every day"},"minutes":18,"goals":[{"bn":"সূরা ফাতিহার প্রতিটি শব্দের অর্থ জানব","en":"Know the meaning of every word in Al-Fatiha"},{"bn":"রুকু, সিজদা ও তাশাহহুদের মূল শব্দগুলো চিনব","en":"Recognise the key words of ruku', sujood and tashahhud"},{"bn":"সালাতে মনোযোগ (খুশু) বাড়ানোর সহজ উপায় পাব","en":"Find an easy way to add focus (khushoo') to salah"}],"blocks":[{"type":"text","bn":"একজন মুসলিম দৈনিক ফরজ সালাতেই কমপক্ষে ১৭ বার সূরা ফাতিহা পড়ে। কল্পনা করো — প্রতিবার যদি প্রতিটি শব্দ বুঝে পড়ো, সালাতের স্বাদই বদলে যাবে! চলো আয়াত ধরে ধরে শব্দগুলো দেখি।","en":"In the obligatory prayers alone, a Muslim recites Al-Fatiha at least 17 times a day. Imagine understanding every word each time — salah will feel completely different! Let's go through it verse by verse."},{"type":"ayah","ref":"1:1","ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","words":[{"ar":"بِسْمِ","bn":"নামে","en":"In the name"},{"ar":"اللّٰهِ","bn":"আল্লাহর","en":"of Allah"},{"ar":"الرَّحْمٰنِ","bn":"পরম দয়াময়","en":"the Most Merciful"},{"ar":"الرَّحِيمِ","bn":"পরম দয়ালু","en":"the Especially Merciful"}],"tr":{"bn":"বিসমিল্লাহির রাহমানির রাহীম","en":"bismillaahir-raḥmaanir-raḥeem"},"mean":{"bn":"পরম দয়াময়, পরম দয়ালু আল্লাহর নামে।","en":"In the name of Allah, the Most Merciful, the Especially Merciful."}},{"type":"ayah","ref":"1:2","ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","words":[{"ar":"الْحَمْدُ","bn":"সব প্রশংসা","en":"All praise"},{"ar":"لِلّٰهِ","bn":"আল্লাহর জন্য","en":"is for Allah"},{"ar":"رَبِّ","bn":"রব","en":"Lord"},{"ar":"الْعَالَمِينَ","bn":"সৃষ্টিজগতের","en":"of the worlds"}],"tr":{"bn":"আলহামদু লিল্লাহি রব্বিল 'আলামীন","en":"al-ḥamdu lillaahi rabbil-'aalameen"},"mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি সৃষ্টিজগতের রব।","en":"All praise is for Allah, Lord of all the worlds."}},{"type":"text","bn":"৩ নম্বর আয়াত {{الرَّحْمٰنِ الرَّحِيمِ}} — এই দুটি নাম আমরা পরের পাঠে আল্লাহর অন্যান্য সুন্দর নামের সাথে শিখব।","en":"Verse 3, {{الرَّحْمٰنِ الرَّحِيمِ}}, repeats two names of Allah — we'll learn them in the next lesson with His other beautiful names."},{"type":"ayah","ref":"1:4","ar":"مَالِكِ يَوْمِ الدِّينِ","words":[{"ar":"مَالِكِ","bn":"মালিক","en":"Master"},{"ar":"يَوْمِ","bn":"দিনের","en":"of the Day"},{"ar":"الدِّينِ","bn":"প্রতিদানের","en":"of Judgement"}],"tr":{"bn":"মালিকি ইয়াওমিদ দীন","en":"maaliki yawmid-deen"},"mean":{"bn":"প্রতিদান দিবসের মালিক।","en":"Master of the Day of Judgement."}},{"type":"ayah","ref":"1:5","ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","words":[{"ar":"إِيَّاكَ","bn":"কেবল তোমারই","en":"You alone"},{"ar":"نَعْبُدُ","bn":"আমরা ইবাদত করি","en":"we worship"},{"ar":"وَإِيَّاكَ","bn":"এবং কেবল তোমারই কাছে","en":"and You alone"},{"ar":"نَسْتَعِينُ","bn":"আমরা সাহায্য চাই","en":"we ask for help"}],"tr":{"bn":"ইয়্যাকা না'বুদু ওয়া ইয়্যাকা নাসতা'ঈন","en":"iyyaaka na'budu wa iyyaaka nasta'een"},"mean":{"bn":"আমরা কেবল তোমারই ইবাদত করি এবং কেবল তোমারই কাছে সাহায্য চাই।","en":"You alone we worship, and You alone we ask for help."}},{"type":"ayah","ref":"1:6","ar":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","words":[{"ar":"اهْدِنَا","bn":"আমাদের পথ দেখাও","en":"Guide us"},{"ar":"الصِّرَاطَ","bn":"পথ","en":"the path"},{"ar":"الْمُسْتَقِيمَ","bn":"সরল, সোজা","en":"the straight"}],"tr":{"bn":"ইহদিনাস সিরাত্বাল মুসতাক্বীম","en":"ihdinaṣ-ṣiraaṭal-mustaqeem"},"mean":{"bn":"আমাদের সরল পথ দেখাও।","en":"Guide us to the straight path."}},{"type":"ayah","ref":"1:7","ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ","words":[{"ar":"صِرَاطَ","bn":"পথ","en":"The path"},{"ar":"الَّذِينَ","bn":"তাদের, যাদের","en":"of those"},{"ar":"أَنْعَمْتَ","bn":"তুমি অনুগ্রহ করেছ","en":"You have blessed"},{"ar":"عَلَيْهِمْ","bn":"তাদের উপর","en":"upon them"},{"ar":"غَيْرِ","bn":"নয়","en":"not"},{"ar":"الْمَغْضُوبِ","bn":"যাদের উপর ক্রোধ পড়েছে","en":"of those who earned anger"},{"ar":"عَلَيْهِمْ","bn":"তাদের উপর","en":"upon them"},{"ar":"وَلَا","bn":"আর না","en":"and not"},{"ar":"الضَّالِّينَ","bn":"পথভ্রষ্টদের","en":"of those who went astray"}],"tr":{"bn":"সিরাত্বাল্লাযীনা আন'আমতা 'আলাইহিম, গাইরিল মাগদ্বূবি 'আলাইহিম ওয়ালাদ্ দ্বাল্লীন","en":"ṣiraaṭalladheena an'amta 'alayhim, ghayril-maghḍoobi 'alayhim wa laḍ-ḍaalleen"},"mean":{"bn":"তাদের পথ, যাদের তুমি অনুগ্রহ করেছ — তাদের নয় যাদের উপর ক্রোধ পড়েছে, আর তাদেরও নয় যারা পথভ্রষ্ট।","en":"The path of those You have blessed — not of those who earned anger, nor of those who went astray."}},{"type":"vocab","title":{"bn":"ফাতিহার শব্দ (মূল রূপে)","en":"Al-Fatiha words (base forms)"},"items":[{"ar":"اِسْم","tr":{"bn":"ইসম","en":"ism"},"mean":{"bn":"নাম","en":"name"},"root":"س م و","example":{"ar":"اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ","mean":{"bn":"পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন","en":"Read in the name of your Lord who created"},"ref":"96:1"}},{"ar":"حَمْد","tr":{"bn":"হামদ","en":"ḥamd"},"mean":{"bn":"প্রশংসা (কৃতজ্ঞতাসহ)","en":"praise (with gratitude)"},"root":"ح م د","example":{"ar":"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ","mean":{"bn":"অতএব তোমার রবের প্রশংসাসহ তাসবীহ পড়ো ও তাঁর কাছে ক্ষমা চাও","en":"So glorify your Lord with praise and ask His forgiveness"},"ref":"110:3"}},{"ar":"عَالَمِين","tr":{"bn":"'আলামীন","en":"'aalameen"},"mean":{"bn":"জগৎসমূহ, সমগ্র সৃষ্টিজগৎ","en":"the worlds, all of creation"},"root":"ع ل م","example":{"ar":"وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ","mean":{"bn":"আমি তোমাকে সৃষ্টিজগতের জন্য রহমত হিসেবেই পাঠিয়েছি","en":"We have not sent you except as a mercy to the worlds"},"ref":"21:107"}},{"ar":"مَالِك","tr":{"bn":"মালিক","en":"maalik"},"mean":{"bn":"মালিক, অধিপতি","en":"owner, master"},"root":"م ل ك","example":{"ar":"مَالِكِ يَوْمِ الدِّينِ","mean":{"bn":"প্রতিদান দিবসের মালিক","en":"Master of the Day of Judgement"},"ref":"1:4"}},{"ar":"يَوْم","tr":{"bn":"ইয়াওম","en":"yawm"},"mean":{"bn":"দিন, দিবস","en":"day"},"root":"ي و م","example":{"ar":"يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ","mean":{"bn":"যেদিন মানুষ দাঁড়াবে সৃষ্টিজগতের রবের সামনে","en":"the Day people will stand before the Lord of the worlds"},"ref":"83:6"}},{"ar":"دِين","tr":{"bn":"দীন","en":"deen"},"mean":{"bn":"প্রতিদান, বিচার; দ্বীন (জীবনব্যবস্থা)","en":"judgement, recompense; religion, way of life"},"root":"د ي ن","example":{"ar":"لَكُمْ دِينُكُمْ وَلِيَ دِينِ","mean":{"bn":"তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন","en":"To you your religion, and to me mine"},"ref":"109:6"}},{"ar":"إِيَّاكَ","tr":{"bn":"ইয়্যাকা","en":"iyyaaka"},"mean":{"bn":"কেবল তোমাকেই","en":"You alone"},"example":{"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","mean":{"bn":"কেবল তোমারই ইবাদত করি, কেবল তোমারই কাছে সাহায্য চাই","en":"You alone we worship, You alone we ask for help"},"ref":"1:5"}},{"ar":"نَعْبُدُ","tr":{"bn":"না'বুদু","en":"na'budu"},"mean":{"bn":"আমরা ইবাদত করি","en":"we worship"},"root":"ع ب د"},{"ar":"نَسْتَعِينُ","tr":{"bn":"নাসতা'ঈনু","en":"nasta'eenu"},"mean":{"bn":"আমরা সাহায্য চাই","en":"we ask for help"},"root":"ع و ن"},{"ar":"اهْدِنَا","tr":{"bn":"ইহদিনা","en":"ihdinaa"},"mean":{"bn":"আমাদের পথ দেখাও, হিদায়াত দাও","en":"guide us"},"root":"ه د ي","example":{"ar":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","mean":{"bn":"আমাদের সরল পথ দেখাও","en":"Guide us to the straight path"},"ref":"1:6"}},{"ar":"صِرَاط","tr":{"bn":"সিরাত্ব","en":"ṣiraaṭ"},"mean":{"bn":"পথ, রাস্তা","en":"path, way"},"root":"ص ر ط"},{"ar":"مُسْتَقِيم","tr":{"bn":"মুসতাক্বীম","en":"mustaqeem"},"mean":{"bn":"সরল, সোজা","en":"straight"},"root":"ق و م"},{"ar":"أَنْعَمْتَ","tr":{"bn":"আন'আমতা","en":"an'amta"},"mean":{"bn":"তুমি অনুগ্রহ করেছ","en":"You have blessed / favoured"},"root":"ن ع م","example":{"ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","mean":{"bn":"তাদের পথ, যাদের তুমি অনুগ্রহ করেছ","en":"the path of those You have blessed"},"ref":"1:7"}},{"ar":"عَلَيْهِمْ","tr":{"bn":"'আলাইহিম","en":"'alayhim"},"mean":{"bn":"তাদের উপর ({{عَلَى}} + {{هِمْ}})","en":"upon them ({{عَلَى}} + {{هِمْ}})"}},{"ar":"غَيْر","tr":{"bn":"গাইর","en":"ghayr"},"mean":{"bn":"ছাড়া, ভিন্ন, নয়","en":"other than, not"},"root":"غ ي ر"},{"ar":"مَغْضُوب","tr":{"bn":"মাগদ্বূব","en":"maghḍoob"},"mean":{"bn":"যার উপর ক্রোধ পড়েছে","en":"one who has earned anger"},"root":"غ ض ب"},{"ar":"ضَالِّين","tr":{"bn":"দ্বাল্লীন","en":"ḍaalleen"},"mean":{"bn":"পথভ্রষ্টরা","en":"those who went astray"},"root":"ض ل ل","example":{"ar":"غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ","mean":{"bn":"তাদের নয় যাদের উপর ক্রোধ পড়েছে, আর পথভ্রষ্টদেরও নয়","en":"not of those who earned anger, nor of those astray"},"ref":"1:7"}}]},{"type":"tip","kind":"memory","bn":"চেনা শব্দ খোঁজো: **মালিক** (মালিক), **দ্বীন** (দীন), **হেদায়েত** ({{اهْدِنَا}}-এর মূল ه د ي), **পুলসিরাত**-এর ‘সিরাত’ ({{صِرَاط}}), **নিয়ামত** ({{أَنْعَمْتَ}}-এর মূল ن ع م), **ইবাদত** ({{نَعْبُدُ}}-এর মূল ع ب د), আর বাংলায় যে **গজব** বলি — সেটি {{مَغْضُوب}}-এর মূল غ ض ب (ক্রোধ) থেকে!","en":"Familiar words: **malik** (owner), **deen**, **hedayet** (root ه د ي of {{اهْدِنَا}}), the ‘sirat’ in **pulsirat** ({{صِرَاط}}), **niyamat** (root ن ع م of {{أَنْعَمْتَ}}), **ibadat** (root ع ب د of {{نَعْبُدُ}}) — and Bangla **gojob** (wrath) comes from غ ض ب, the root of {{مَغْضُوب}}!"},{"type":"vocab","title":{"bn":"সালাতের অন্যান্য শব্দ","en":"Other words of salah"},"items":[{"ar":"أَكْبَر","tr":{"bn":"আকবার","en":"akbar"},"mean":{"bn":"সবচেয়ে বড়, সর্বশ্রেষ্ঠ","en":"greatest, greater"},"root":"ك ب ر","example":{"ar":"وَلَذِكْرُ اللّٰهِ أَكْبَرُ","mean":{"bn":"আর আল্লাহর স্মরণই সবচেয়ে বড়","en":"And the remembrance of Allah is greatest"},"ref":"29:45"}},{"ar":"سُبْحَانَ","tr":{"bn":"সুবহানা","en":"subḥaana"},"mean":{"bn":"পবিত্র, মহিমা (সব দোষ-ত্রুটি থেকে মুক্ত)","en":"glory be to, exalted (free of all faults)"},"root":"س ب ح","example":{"ar":"سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ","mean":{"bn":"পবিত্র তোমার রব, সম্মানের রব — তারা যা বলে তা থেকে","en":"Exalted is your Lord, Lord of might, above what they describe"},"ref":"37:180"}},{"ar":"عَظِيم","tr":{"bn":"'আযীম","en":"'aẓeem"},"mean":{"bn":"মহান, বিশাল","en":"great, mighty, tremendous"},"root":"ع ظ م","example":{"ar":"فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ","mean":{"bn":"অতএব তোমার মহান রবের নামে তাসবীহ পড়ো","en":"So glorify the name of your Lord, the Most Great"},"ref":"56:74"}},{"ar":"أَعْلَى","tr":{"bn":"আ'লা","en":"a'laa"},"mean":{"bn":"সর্বোচ্চ, সবার উপরে","en":"the Most High, highest"},"root":"ع ل و","example":{"ar":"سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى","mean":{"bn":"তোমার সর্বোচ্চ রবের নামের তাসবীহ পড়ো","en":"Glorify the name of your Lord, the Most High"},"ref":"87:1"}},{"ar":"سَمِعَ","tr":{"bn":"সামি'আ","en":"sami'a"},"mean":{"bn":"সে শুনল","en":"he heard"},"root":"س م ع","example":{"ar":"قَدْ سَمِعَ اللّٰهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا","mean":{"bn":"আল্লাহ অবশ্যই শুনেছেন সেই নারীর কথা, যে তার স্বামীর ব্যাপারে তোমার সাথে কথা বলছিল","en":"Allah has indeed heard the words of the woman who pleaded with you about her husband"},"ref":"58:1"}},{"ar":"حَمِدَ","tr":{"bn":"হামিদা","en":"ḥamida"},"mean":{"bn":"সে প্রশংসা করল","en":"he praised"},"root":"ح م د","example":{"ar":"سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ","mean":{"bn":"যে আল্লাহর প্রশংসা করে, আল্লাহ তার কথা শোনেন (রুকু থেকে ওঠার সময় বলা হয়)","en":"Allah hears the one who praises Him (said when rising from ruku')"}}},{"ar":"رَبَّنَا","tr":{"bn":"রব্বানা","en":"rabbanaa"},"mean":{"bn":"হে আমাদের রব","en":"our Lord"},"root":"ر ب ب","example":{"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً","mean":{"bn":"হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দাও এবং আখিরাতেও কল্যাণ দাও","en":"Our Lord, give us good in this world and good in the Hereafter"},"ref":"2:201"}},{"ar":"أَشْهَدُ","tr":{"bn":"আশহাদু","en":"ash-hadu"},"mean":{"bn":"আমি সাক্ষ্য দিই","en":"I bear witness"},"root":"ش ه د","example":{"ar":"أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ","mean":{"bn":"আমি সাক্ষ্য দিই যে আল্লাহ ছাড়া কোনো ইলাহ নেই (আজান ও তাশাহহুদে)","en":"I bear witness that there is no god but Allah (in the adhan and tashahhud)"}}},{"ar":"آمِين","tr":{"bn":"আমীন","en":"aameen"},"mean":{"bn":"হে আল্লাহ, কবুল করো (ফাতিহার পরে বলা হয়; এটি কুরআনের অংশ নয়)","en":"O Allah, accept (said after Al-Fatiha; not part of the Quran)"}}]},{"type":"examples","title":{"bn":"রুকু ও সিজদার তাসবীহ — এখন বুঝে পড়ো","en":"Ruku' and sujood glorifications — now with meaning"},"items":[{"ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","tr":{"bn":"সুবহানা রব্বিয়াল 'আযীম","en":"subḥaana rabbiyal-'aẓeem"},"mean":{"bn":"পবিত্র আমার মহান রব","en":"Glory be to my Lord, the Most Great"},"note":{"bn":"রুকুতে বলা হয়","en":"said in ruku'"},"hl":"الْعَظِيمِ"},{"ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى","tr":{"bn":"সুবহানা রব্বিয়াল আ'লা","en":"subḥaana rabbiyal-a'laa"},"mean":{"bn":"পবিত্র আমার সর্বোচ্চ রব","en":"Glory be to my Lord, the Most High"},"note":{"bn":"সিজদায় বলা হয় — মাথা সবচেয়ে নিচে, আর মুখে ‘সর্বোচ্চ’!","en":"said in sujood — head at its lowest, tongue saying ‘Most High’!"},"hl":"الْأَعْلَى"},{"ar":"رَبَّنَا وَلَكَ الْحَمْدُ","tr":{"bn":"রব্বানা ওয়া লাকাল হামদ","en":"rabbanaa wa lakal-ḥamd"},"mean":{"bn":"হে আমাদের রব, সব প্রশংসা তোমারই","en":"Our Lord, and to You belongs all praise"},"note":{"bn":"রুকু থেকে উঠে বলা হয়","en":"said after rising from ruku'"},"hl":"الْحَمْدُ"},{"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},"note":{"bn":"সালাতের প্রতিটি ওঠা-নামায়","en":"at each movement of salah"},"hl":"أَكْبَرُ"}]},{"type":"tip","kind":"tip","bn":"আজ থেকে একটা অভ্যাস করো: সালাতে {{إِيَّاكَ نَعْبُدُ}} পড়ার সময় মনে মনে বলো ‘কেবল তোমারই ইবাদত করি’। প্রতিদিন একটি করে শব্দের অর্থ মনে আনলে এক সপ্তাহেই পুরো ফাতিহা অর্থসহ মনে থাকবে।","en":"Start a habit today: when you recite {{إِيَّاكَ نَعْبُدُ}} in salah, think ‘You alone we worship’. Recall one word's meaning each day, and within a week you'll pray all of Al-Fatiha with its meaning."},{"type":"quiz","items":[{"q":{"bn":"{{اهْدِنَا}} মানে কী?","en":"What does {{اهْدِنَا}} mean?"},"ar":"اهْدِنَا","options":[{"bn":"আমাদের ক্ষমা করো","en":"forgive us"},{"bn":"আমাদের পথ দেখাও","en":"guide us"},{"bn":"আমাদের রিজিক দাও","en":"provide for us"}],"answer":1},{"q":{"bn":"{{صِرَاط}} শব্দের অর্থ —","en":"{{صِرَاط}} means —"},"ar":"صِرَاط","options":[{"bn":"পথ","en":"path"},{"bn":"দিন","en":"day"},{"bn":"নাম","en":"name"},{"bn":"রব","en":"Lord"}],"answer":0},{"q":{"bn":"{{يَوْمِ الدِّينِ}} — এখানে {{يَوْم}} মানে কী?","en":"In {{يَوْمِ الدِّينِ}}, what does {{يَوْم}} mean?"},"options":[{"bn":"রাত","en":"night"},{"bn":"দিন","en":"day"},{"bn":"মাস","en":"month"}],"answer":1},{"q":{"bn":"{{نَسْتَعِينُ}} মানে —","en":"{{نَسْتَعِينُ}} means —"},"ar":"نَسْتَعِينُ","options":[{"bn":"আমরা ইবাদত করি","en":"we worship"},{"bn":"আমরা সাহায্য চাই","en":"we ask for help"},{"bn":"আমরা সাক্ষ্য দিই","en":"we bear witness"}],"answer":1},{"q":{"bn":"রুকুতে আমরা আল্লাহকে কোন গুণে ডাকি?","en":"Which quality of Allah do we mention in ruku'?"},"options":["الْعَظِيم","الْأَعْلَى","الضَّالِّين"],"answer":0,"explain":{"bn":"রুকুতে {{سُبْحَانَ رَبِّيَ الْعَظِيمِ}}, সিজদায় {{سُبْحَانَ رَبِّيَ الْأَعْلَى}}।","en":"Ruku': {{سُبْحَانَ رَبِّيَ الْعَظِيمِ}}; sujood: {{سُبْحَانَ رَبِّيَ الْأَعْلَى}}."}},{"q":{"bn":"বাংলা ‘গজব’ শব্দটি কোন আরবি শব্দের পরিবারের?","en":"Bangla ‘gojob’ (wrath) belongs to the family of which word?"},"options":["مَغْضُوب","مُسْتَقِيم","عَالَمِين"],"answer":0},{"q":{"bn":"{{أَكْبَر}} মানে কী?","en":"What does {{أَكْبَر}} mean?"},"ar":"أَكْبَر","options":[{"bn":"সবচেয়ে বড়","en":"greatest"},{"bn":"সবচেয়ে দয়ালু","en":"most merciful"},{"bn":"সর্বোচ্চ","en":"highest"}],"answer":0},{"q":{"bn":"{{آمِين}} সম্পর্কে কোনটি সঠিক?","en":"Which is true about {{آمِين}}?"},"options":[{"bn":"এটি ফাতিহার ৮ম আয়াত","en":"It is the 8th verse of Al-Fatiha"},{"bn":"এটি দোয়া কবুলের আবেদন, কুরআনের অংশ নয়","en":"It asks Allah to accept; it is not part of the Quran"},{"bn":"এর অর্থ ‘সব প্রশংসা’","en":"It means ‘all praise’"}],"answer":1}]}]},{"id":"vocab-names","icon":"ح","title":{"bn":"আল্লাহ ও তাঁর সুন্দর নামসমূহ","en":"Allah & His Beautiful Names"},"subtitle":{"bn":"আয়াতের শেষে বারবার ফিরে আসা নামগুলো চিনে নিই","en":"Recognise the names that close so many verses"},"minutes":20,"goals":[{"bn":"আল্লাহর ৩৬টি সুন্দর নাম (আসমাউল হুসনা) অর্থসহ শিখব","en":"Learn 36 of Allah's beautiful names (al-asmaa' al-ḥusnaa) with meanings"},{"bn":"আয়াতের শেষে আসা নামের জোড়া (যেমন {{غَفُورٌ رَحِيمٌ}}) চিনব","en":"Recognise the name-pairs that end verses (like {{غَفُورٌ رَحِيمٌ}})"},{"bn":"{{فَعِيل}} ও {{فَعُول}} — নামের দুটি জনপ্রিয় ছাঁচ দেখব","en":"See two popular name patterns: {{فَعِيل}} and {{فَعُول}}"}],"blocks":[{"type":"text","bn":"কুরআনের অনেক আয়াত শেষ হয় আল্লাহর এক বা দুটি নাম দিয়ে — যেমন {{وَاللّٰهُ غَفُورٌ رَحِيمٌ}}। এই নামগুলো আয়াতের ‘সারকথা’র মতো: আয়াতে যা বলা হলো, তার পেছনে আল্লাহর কোন গুণ কাজ করছে, তা জানিয়ে দেয়। তাই এগুলো চিনলে প্রায় প্রতি পৃষ্ঠায় কিছু না কিছু বুঝতে পারবে।","en":"Many verses end with one or two names of Allah — like {{وَاللّٰهُ غَفُورٌ رَحِيمٌ}}. These names act like the verse's ‘summary’, showing which quality of Allah lies behind what was just said. Know them and you'll understand something on almost every page."},{"type":"vocab","title":{"bn":"একত্ব ও মহিমা","en":"Oneness & majesty"},"items":[{"ar":"أَحَد","tr":{"bn":"আহাদ","en":"aḥad"},"mean":{"bn":"এক, অদ্বিতীয়","en":"the One, unique"},"root":"أ ح د","example":{"ar":"وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","mean":{"bn":"আর তাঁর সমতুল্য কেউ নেই","en":"and there is none comparable to Him"},"ref":"112:4"}},{"ar":"وَاحِد","tr":{"bn":"ওয়াহিদ","en":"waaḥid"},"mean":{"bn":"এক, একক","en":"one, the One"},"root":"و ح د","example":{"ar":"لِلّٰهِ الْوَاحِدِ الْقَهَّارِ","mean":{"bn":"এক, পরাক্রমশালী আল্লাহর জন্য","en":"to Allah, the One, the Prevailing"},"ref":"40:16"}},{"ar":"صَمَد","tr":{"bn":"সামাদ","en":"ṣamad"},"mean":{"bn":"অমুখাপেক্ষী; সবাই যাঁর মুখাপেক্ষী","en":"the Self-Sufficient, on whom all depend"},"root":"ص م د","example":{"ar":"اللّٰهُ الصَّمَدُ","mean":{"bn":"আল্লাহ অমুখাপেক্ষী","en":"Allah, the Eternal Refuge"},"ref":"112:2"}},{"ar":"حَيّ","tr":{"bn":"হাইয়্য","en":"ḥayy"},"mean":{"bn":"চিরঞ্জীব","en":"the Ever-Living"},"root":"ح ي ي","example":{"ar":"وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ","mean":{"bn":"আর ভরসা করো সেই চিরঞ্জীবের উপর, যিনি কখনো মরবেন না","en":"And rely on the Ever-Living who never dies"},"ref":"25:58"}},{"ar":"قَيُّوم","tr":{"bn":"ক্বাইয়্যূম","en":"qayyoom"},"mean":{"bn":"চিরস্থায়ী, সবকিছুর ধারক","en":"the Self-Subsisting, Sustainer of all"},"root":"ق و م","example":{"ar":"اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ","mean":{"bn":"আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই, তিনি চিরঞ্জীব, সবকিছুর ধারক","en":"Allah — no god but He, the Ever-Living, the Sustainer"},"ref":"2:255"}},{"ar":"مَلِك","tr":{"bn":"মালিক","en":"malik"},"mean":{"bn":"বাদশাহ, রাজা","en":"King"},"root":"م ل ك","example":{"ar":"مَلِكِ النَّاسِ","mean":{"bn":"মানুষের বাদশাহ","en":"the King of mankind"},"ref":"114:2"}},{"ar":"قُدُّوس","tr":{"bn":"ক্বুদ্দূস","en":"quddoos"},"mean":{"bn":"মহাপবিত্র","en":"the Most Holy, Pure"},"root":"ق د س","example":{"ar":"الْمَلِكُ الْقُدُّوسُ السَّلَامُ","mean":{"bn":"বাদশাহ, মহাপবিত্র, শান্তিময়","en":"the King, the Most Holy, the Source of Peace"},"ref":"59:23"}},{"ar":"خَالِق","tr":{"bn":"খালিক্ব","en":"khaaliq"},"mean":{"bn":"স্রষ্টা","en":"the Creator"},"root":"خ ل ق","example":{"ar":"هُوَ اللّٰهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ","mean":{"bn":"তিনিই আল্লাহ — স্রষ্টা, উদ্ভাবক, আকৃতিদাতা","en":"He is Allah, the Creator, the Originator, the Fashioner"},"ref":"59:24"}},{"ar":"رَزَّاق","tr":{"bn":"রায্যাক্ব","en":"razzaaq"},"mean":{"bn":"রিজিকদাতা","en":"the Provider"},"root":"ر ز ق","example":{"ar":"إِنَّ اللّٰهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ","mean":{"bn":"নিশ্চয়ই আল্লাহই রিজিকদাতা, প্রবল শক্তির অধিকারী, সুদৃঢ়","en":"Indeed, Allah is the Provider, Lord of power, the Firm"},"ref":"51:58"}},{"ar":"أَوَّل","tr":{"bn":"আওয়াল","en":"awwal"},"mean":{"bn":"প্রথম (যাঁর আগে কিছু নেই)","en":"the First"},"root":"أ و ل","example":{"ar":"هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ","mean":{"bn":"তিনিই প্রথম ও শেষ, প্রকাশ্য ও গোপন","en":"He is the First and the Last, the Manifest and the Hidden"},"ref":"57:3"}},{"ar":"آخِر","tr":{"bn":"আখির","en":"aakhir"},"mean":{"bn":"শেষ (যাঁর পরে কিছু নেই)","en":"the Last"},"root":"أ خ ر"},{"ar":"ظَاهِر","tr":{"bn":"যাহির","en":"ẓaahir"},"mean":{"bn":"প্রকাশ্য, সবকিছুর উপরে","en":"the Manifest, the Uppermost"},"root":"ظ ه ر"},{"ar":"بَاطِن","tr":{"bn":"বাতিন","en":"baaṭin"},"mean":{"bn":"গোপন, অন্তর্নিহিত","en":"the Hidden, the Innermost"},"root":"ب ط ن"}]},{"type":"tip","kind":"memory","bn":"{{مَالِك}} (মালিক) আর {{مَلِك}} (বাদশাহ) — দুটো একই মূল م ل ك থেকে। ফাতিহায় {{مَالِكِ}}, আর সূরা নাসে {{مَلِكِ النَّاسِ}}। বাংলার **মুলুক** (দেশ, রাজ্য) শব্দটিও এই পরিবারের!","en":"{{مَالِك}} (owner) and {{مَلِك}} (king) share the root م ل ك. Al-Fatiha has {{مَالِكِ}}; Surah An-Nas has {{مَلِكِ النَّاسِ}}. Bangla **muluk** (country, realm) belongs to this family too!"},{"type":"vocab","title":{"bn":"দয়া, ক্ষমা ও ভালোবাসা","en":"Mercy, forgiveness & love"},"items":[{"ar":"رَحْمٰن","tr":{"bn":"রাহমান","en":"raḥmaan"},"mean":{"bn":"পরম দয়াময় (যাঁর দয়া সবার জন্য, সীমাহীন)","en":"the Most Merciful (mercy vast, for all)"},"root":"ر ح م","example":{"ar":"الرَّحْمٰنِ الرَّحِيمِ","mean":{"bn":"পরম দয়াময়, পরম দয়ালু","en":"the Most Merciful, the Especially Merciful"},"ref":"1:3"}},{"ar":"رَحِيم","tr":{"bn":"রাহীম","en":"raḥeem"},"mean":{"bn":"পরম দয়ালু (যাঁর দয়া নিরবচ্ছিন্ন)","en":"the Especially Merciful (ever-merciful)"},"root":"ر ح م","example":{"ar":"إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ","mean":{"bn":"নিশ্চয়ই তিনিই ক্ষমাশীল, পরম দয়ালু","en":"Indeed, He is the Forgiving, the Merciful"},"ref":"39:53"}},{"ar":"غَفُور","tr":{"bn":"গাফূর","en":"ghafoor"},"mean":{"bn":"অতি ক্ষমাশীল","en":"the Ever-Forgiving"},"root":"غ ف ر","example":{"ar":"إِنَّ اللّٰهَ غَفُورٌ رَحِيمٌ","mean":{"bn":"নিশ্চয়ই আল্লাহ অতি ক্ষমাশীল, পরম দয়ালু","en":"Indeed, Allah is Forgiving and Merciful"},"ref":"2:173"}},{"ar":"تَوَّاب","tr":{"bn":"তাওয়াব","en":"tawwaab"},"mean":{"bn":"তাওবা কবুলকারী (বারবার)","en":"the Accepter of repentance (again and again)"},"root":"ت و ب","example":{"ar":"إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ","mean":{"bn":"নিশ্চয়ই তিনিই তাওবা কবুলকারী, পরম দয়ালু","en":"Indeed, He is the Accepter of repentance, the Merciful"},"ref":"2:37"}},{"ar":"وَدُود","tr":{"bn":"ওয়াদূদ","en":"wadood"},"mean":{"bn":"প্রেমময়, ভালোবাসেন","en":"the Loving"},"root":"و د د","example":{"ar":"وَهُوَ الْغَفُورُ الْوَدُودُ","mean":{"bn":"আর তিনি ক্ষমাশীল, প্রেমময়","en":"And He is the Forgiving, the Loving"},"ref":"85:14"}},{"ar":"رَءُوف","tr":{"bn":"রাউফ","en":"ra'oof"},"mean":{"bn":"অতি স্নেহশীল, কোমল","en":"the Most Kind, Compassionate"},"root":"ر أ ف","example":{"ar":"إِنَّ اللّٰهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ","mean":{"bn":"নিশ্চয়ই আল্লাহ মানুষের প্রতি অতি স্নেহশীল, পরম দয়ালু","en":"Indeed, Allah is Kind and Merciful to people"},"ref":"2:143"}},{"ar":"حَلِيم","tr":{"bn":"হালীম","en":"ḥaleem"},"mean":{"bn":"সহনশীল (সাথে সাথে শাস্তি দেন না)","en":"the Forbearing (does not hasten punishment)"},"root":"ح ل م","example":{"ar":"وَاللّٰهُ غَنِيٌّ حَلِيمٌ","mean":{"bn":"আর আল্লাহ অভাবমুক্ত, সহনশীল","en":"And Allah is Free of need, Forbearing"},"ref":"2:263"}},{"ar":"كَرِيم","tr":{"bn":"কারীম","en":"kareem"},"mean":{"bn":"মহানুভব, দানশীল","en":"the Generous, Noble"},"root":"ك ر م","example":{"ar":"يَا أَيُّهَا الْإِنْسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ","mean":{"bn":"হে মানুষ, কিসে তোমাকে তোমার মহানুভব রব সম্পর্কে ধোঁকায় ফেলল?","en":"O mankind, what has deceived you about your Lord, the Generous?"},"ref":"82:6"}},{"ar":"لَطِيف","tr":{"bn":"লাত্বীফ","en":"laṭeef"},"mean":{"bn":"সূক্ষ্মদর্শী, কোমল দয়ালু","en":"the Subtle, the Gentle"},"root":"ل ط ف","example":{"ar":"اللّٰهُ لَطِيفٌ بِعِبَادِهِ","mean":{"bn":"আল্লাহ তাঁর বান্দাদের প্রতি কোমল দয়ালু","en":"Allah is Gentle with His servants"},"ref":"42:19"}},{"ar":"وَلِيّ","tr":{"bn":"ওয়ালিয়্য","en":"waliyy"},"mean":{"bn":"অভিভাবক, বন্ধু","en":"Protector, Ally, Friend"},"root":"و ل ي","example":{"ar":"اللّٰهُ وَلِيُّ الَّذِينَ آمَنُوا","mean":{"bn":"আল্লাহ মুমিনদের অভিভাবক","en":"Allah is the Protector of those who believe"},"ref":"2:257"}}]},{"type":"vocab","title":{"bn":"জ্ঞান, প্রজ্ঞা ও ক্ষমতা","en":"Knowledge, wisdom & power"},"items":[{"ar":"عَلِيم","tr":{"bn":"'আলীম","en":"'aleem"},"mean":{"bn":"সর্বজ্ঞ","en":"the All-Knowing"},"root":"ع ل م","example":{"ar":"إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ","mean":{"bn":"নিশ্চয়ই তুমিই সর্বজ্ঞ, প্রজ্ঞাময়","en":"Indeed, You are the All-Knowing, the All-Wise"},"ref":"2:32"}},{"ar":"حَكِيم","tr":{"bn":"হাকীম","en":"ḥakeem"},"mean":{"bn":"প্রজ্ঞাময়","en":"the All-Wise"},"root":"ح ك م","example":{"ar":"وَاللّٰهُ عَلِيمٌ حَكِيمٌ","mean":{"bn":"আর আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়","en":"And Allah is All-Knowing, All-Wise"},"ref":"9:60"}},{"ar":"سَمِيع","tr":{"bn":"সামী'","en":"samee'"},"mean":{"bn":"সর্বশ্রোতা","en":"the All-Hearing"},"root":"س م ع","example":{"ar":"إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ","mean":{"bn":"নিশ্চয়ই তুমিই সর্বশ্রোতা, সর্বজ্ঞ","en":"Indeed, You are the All-Hearing, the All-Knowing"},"ref":"2:127"}},{"ar":"بَصِير","tr":{"bn":"বাসীর","en":"baṣeer"},"mean":{"bn":"সর্বদ্রষ্টা","en":"the All-Seeing"},"root":"ب ص ر","example":{"ar":"لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ","mean":{"bn":"তাঁর মতো কিছুই নেই, আর তিনি সর্বশ্রোতা, সর্বদ্রষ্টা","en":"Nothing is like Him, and He is the All-Hearing, the All-Seeing"},"ref":"42:11"}},{"ar":"خَبِير","tr":{"bn":"খাবীর","en":"khabeer"},"mean":{"bn":"সব খবর রাখেন, পূর্ণ অবগত","en":"the All-Aware"},"root":"خ ب ر","example":{"ar":"أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ","mean":{"bn":"যিনি সৃষ্টি করেছেন তিনি কি জানবেন না? অথচ তিনি সূক্ষ্মদর্শী, সব খবর রাখেন","en":"Does He who created not know, while He is the Subtle, the All-Aware?"},"ref":"67:14"}},{"ar":"شَهِيد","tr":{"bn":"শাহীদ","en":"shaheed"},"mean":{"bn":"সাক্ষী, সবকিছু প্রত্যক্ষকারী","en":"the Witness"},"root":"ش ه د","example":{"ar":"وَكَفَى بِاللّٰهِ شَهِيدًا","mean":{"bn":"আর সাক্ষী হিসেবে আল্লাহই যথেষ্ট","en":"And sufficient is Allah as Witness"},"ref":"4:79"}},{"ar":"قَدِير","tr":{"bn":"ক্বাদীর","en":"qadeer"},"mean":{"bn":"সর্বশক্তিমান","en":"the All-Powerful"},"root":"ق د ر","example":{"ar":"تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","mean":{"bn":"বরকতময় তিনি, যাঁর হাতে রাজত্ব; আর তিনি সব কিছুর উপর ক্ষমতাবান","en":"Blessed is He in whose hand is dominion, and He has power over all things"},"ref":"67:1"}},{"ar":"عَزِيز","tr":{"bn":"'আযীয","en":"'azeez"},"mean":{"bn":"পরাক্রমশালী, মহাসম্মানিত","en":"the Almighty, the Mighty"},"root":"ع ز ز","example":{"ar":"إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ","mean":{"bn":"নিশ্চয়ই তুমিই পরাক্রমশালী, প্রজ্ঞাময়","en":"Indeed, You are the Almighty, the All-Wise"},"ref":"2:129"}},{"ar":"قَوِيّ","tr":{"bn":"ক্বাউয়িয়্য","en":"qawiyy"},"mean":{"bn":"মহাশক্তিমান","en":"the Strong"},"root":"ق و ي","example":{"ar":"إِنَّ اللّٰهَ لَقَوِيٌّ عَزِيزٌ","mean":{"bn":"নিশ্চয়ই আল্লাহ মহাশক্তিমান, পরাক্রমশালী","en":"Indeed, Allah is Strong and Mighty"},"ref":"22:40"}},{"ar":"كَبِير","tr":{"bn":"কাবীর","en":"kabeer"},"mean":{"bn":"মহান, সবচেয়ে বড়","en":"the Great"},"root":"ك ب ر","example":{"ar":"عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ","mean":{"bn":"অদৃশ্য ও দৃশ্যের জ্ঞানী, মহান, সর্বোচ্চ","en":"Knower of the unseen and the seen, the Great, the Most High"},"ref":"13:9"}},{"ar":"عَلِيّ","tr":{"bn":"'আলিয়্য","en":"'aliyy"},"mean":{"bn":"সমুচ্চ, সর্বোচ্চ","en":"the Most High"},"root":"ع ل و","example":{"ar":"وَهُوَ الْعَلِيُّ الْعَظِيمُ","mean":{"bn":"আর তিনি সমুচ্চ, মহান","en":"And He is the Most High, the Most Great"},"ref":"2:255"}},{"ar":"غَنِيّ","tr":{"bn":"গানিয়্য","en":"ghaniyy"},"mean":{"bn":"অভাবমুক্ত, ধনী","en":"the Free of all need, the Rich"},"root":"غ ن ي","example":{"ar":"وَاللّٰهُ هُوَ الْغَنِيُّ الْحَمِيدُ","mean":{"bn":"আর আল্লাহই অভাবমুক্ত, প্রশংসিত","en":"And Allah is the Free of need, the Praiseworthy"},"ref":"35:15"}},{"ar":"حَمِيد","tr":{"bn":"হামীদ","en":"ḥameed"},"mean":{"bn":"প্রশংসিত","en":"the Praiseworthy"},"root":"ح م د","example":{"ar":"إِلَى صِرَاطِ الْعَزِيزِ الْحَمِيدِ","mean":{"bn":"পরাক্রমশালী, প্রশংসিত সত্তার পথের দিকে","en":"to the path of the Almighty, the Praiseworthy"},"ref":"14:1"}}]},{"type":"table","title":{"bn":"আয়াতের শেষে প্রিয় নামের জোড়া","en":"Favourite name-pairs at the end of verses"},"head":[{"bn":"জোড়া","en":"Pair"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["غَفُورٌ رَحِيمٌ",{"bn":"অতি ক্ষমাশীল, পরম দয়ালু","en":"Forgiving, Merciful"}],["عَلِيمٌ حَكِيمٌ",{"bn":"সর্বজ্ঞ, প্রজ্ঞাময়","en":"All-Knowing, All-Wise"}],["عَزِيزٌ حَكِيمٌ",{"bn":"পরাক্রমশালী, প্রজ্ঞাময়","en":"Almighty, All-Wise"}],["سَمِيعٌ عَلِيمٌ",{"bn":"সর্বশ্রোতা, সর্বজ্ঞ","en":"All-Hearing, All-Knowing"}],["السَّمِيعُ الْبَصِيرُ",{"bn":"সর্বশ্রোতা, সর্বদ্রষ্টা","en":"All-Hearing, All-Seeing"}],["اللَّطِيفُ الْخَبِيرُ",{"bn":"সূক্ষ্মদর্শী, সব খবর রাখেন","en":"Subtle, All-Aware"}],["الْحَيُّ الْقَيُّومُ",{"bn":"চিরঞ্জীব, সবকিছুর ধারক","en":"Ever-Living, Sustainer"}]]},{"type":"tip","kind":"tip","bn":"ছাঁচ লক্ষ করো: {{عَلِيم}}, {{رَحِيم}}, {{حَكِيم}}, {{سَمِيع}}, {{بَصِير}} — সবই {{فَعِيل}} ছাঁচে; আর {{غَفُور}}, {{وَدُود}} — {{فَعُول}} ছাঁচে। এই ছাঁচগুলো বোঝায় গুণটি **স্থায়ী ও প্রবল**। আবার {{تَوَّاب}}, {{رَزَّاق}} — {{فَعَّال}} ছাঁচ, মানে **বারবার, অনেক বেশি** করেন।","en":"Spot the patterns: {{عَلِيم}}, {{رَحِيم}}, {{حَكِيم}}, {{سَمِيع}}, {{بَصِير}} follow {{فَعِيل}}; {{غَفُور}}, {{وَدُود}} follow {{فَعُول}}. These patterns show a quality that is **lasting and intense**. And {{تَوَّاب}}, {{رَزَّاق}} follow {{فَعَّال}} — doing something **again and again, abundantly**."},{"type":"tip","kind":"memory","bn":"আমাদের চারপাশের নামগুলোই তোমার শিক্ষক! **আব্দুর রহমান, আব্দুর রহিম, আব্দুল করিম, আব্দুল আজিজ, আব্দুল কাদির, আব্দুল খালেক, আব্দুর রাজ্জাক, আব্দুল হাই, আব্দুস সামাদ** — ‘আব্দ’ মানে বান্দা, তারপর আল্লাহর একটি নাম। আরও চেনা শব্দ: **হাকিম** (প্রজ্ঞাবান) ← {{حَكِيم}}, **খবর** ← {{خَبِير}}, **কুদরত** ← {{قَدِير}}-এর মূল ق د ر, **জাহির করা** (প্রকাশ করা) ← {{ظَاهِر}}, **রিজিক** ← {{رَزَّاق}}।","en":"The names around you are your teachers! **Abdur Rahman, Abdur Rahim, Abdul Karim, Abdul Aziz, Abdul Qadir, Abdul Khaleq, Abdur Razzaq, Abdul Hai, Abdus Samad** — ‘Abd’ means servant, followed by a name of Allah. More familiar words: **hakim** (wise person) ← {{حَكِيم}}, **khobor** (news) ← {{خَبِير}}, **kudrot** (power) ← root ق د ر of {{قَدِير}}, **jahir kora** (to show) ← {{ظَاهِر}}, **rizik** ← {{رَزَّاق}}."},{"type":"examples","title":{"bn":"সূরা ইখলাস — চারটি আয়াতে আল্লাহর পরিচয়","en":"Surah Al-Ikhlas — Allah introduced in four verses"},"items":[{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","tr":{"bn":"ক্বুল হুওয়াল্লাহু আহাদ","en":"qul huwallaahu aḥad"},"mean":{"bn":"বলো, তিনিই আল্লাহ, এক-অদ্বিতীয়","en":"Say, He is Allah, the One"},"note":{"bn":"১১২:১","en":"112:1"},"hl":"أَحَدٌ"},{"ar":"اللّٰهُ الصَّمَدُ","tr":{"bn":"আল্লাহুস সামাদ","en":"allaahuṣ-ṣamad"},"mean":{"bn":"আল্লাহ অমুখাপেক্ষী","en":"Allah, the Eternal Refuge"},"note":{"bn":"১১২:২","en":"112:2"},"hl":"الصَّمَدُ"},{"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","tr":{"bn":"লাম ইয়ালিদ ওয়া লাম ইউলাদ","en":"lam yalid wa lam yoolad"},"mean":{"bn":"তিনি কাউকে জন্ম দেননি, তাঁকেও জন্ম দেওয়া হয়নি","en":"He neither begets nor is born"},"note":{"bn":"১১২:৩","en":"112:3"},"hl":"لَمْ"},{"ar":"وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":{"bn":"ওয়া লাম ইয়াকুল লাহূ কুফুওয়ান আহাদ","en":"wa lam yakul-lahoo kufuwan aḥad"},"mean":{"bn":"আর তাঁর সমতুল্য কেউ নেই","en":"And there is none comparable to Him"},"note":{"bn":"১১২:৪","en":"112:4"},"hl":"أَحَدٌ"}]},{"type":"quiz","items":[{"q":{"bn":"{{غَفُور}} মানে কী?","en":"What does {{غَفُور}} mean?"},"ar":"غَفُور","options":[{"bn":"অতি ক্ষমাশীল","en":"Ever-Forgiving"},{"bn":"সর্বশ্রোতা","en":"All-Hearing"},{"bn":"স্রষ্টা","en":"Creator"}],"answer":0},{"q":{"bn":"‘সর্বজ্ঞ’ — কোন নাম?","en":"Which name means ‘All-Knowing’?"},"options":["حَكِيم","عَلِيم","حَلِيم","كَرِيم"],"answer":1,"explain":{"bn":"{{عَلِيم}} এসেছে ع ل م থেকে — ‘ইলম’ (জ্ঞান) শব্দের পরিবার।","en":"{{عَلِيم}} comes from ع ل م — the family of ‘ilm’ (knowledge)."}},{"q":{"bn":"{{سَمِيع}} ও {{بَصِير}} — অর্থ কী?","en":"{{سَمِيع}} and {{بَصِير}} mean —"},"options":[{"bn":"সর্বশ্রোতা ও সর্বদ্রষ্টা","en":"All-Hearing and All-Seeing"},{"bn":"এক ও অদ্বিতীয়","en":"One and Unique"},{"bn":"প্রথম ও শেষ","en":"First and Last"}],"answer":0},{"q":{"bn":"{{تَوَّاب}} মানে —","en":"{{تَوَّاب}} means —"},"ar":"تَوَّاب","options":[{"bn":"রিজিকদাতা","en":"Provider"},{"bn":"তাওবা কবুলকারী","en":"Accepter of repentance"},{"bn":"বাদশাহ","en":"King"}],"answer":1},{"q":{"bn":"সূরা নাসে {{مَلِكِ النَّاسِ}} — {{مَلِك}} মানে কী?","en":"In {{مَلِكِ النَّاسِ}}, what does {{مَلِك}} mean?"},"options":[{"bn":"ফেরেশতা","en":"angel"},{"bn":"বাদশাহ","en":"King"},{"bn":"সম্পদ","en":"wealth"}],"answer":1},{"q":{"bn":"বাংলা ‘খবর’ শব্দটি কোন নামের পরিবারের?","en":"Bangla ‘khobor’ (news) is related to which name?"},"options":["خَبِير","كَبِير","قَدِير"],"answer":0},{"q":{"bn":"{{حَيّ}} শব্দের অর্থ —","en":"{{حَيّ}} means —"},"ar":"حَيّ","options":[{"bn":"চিরঞ্জীব","en":"Ever-Living"},{"bn":"মহাপবিত্র","en":"Most Holy"},{"bn":"প্রেমময়","en":"Loving"}],"answer":0},{"q":{"bn":"{{رَحِيم}}, {{عَلِيم}}, {{حَكِيم}} — কোন ছাঁচে?","en":"{{رَحِيم}}, {{عَلِيم}}, {{حَكِيم}} follow which pattern?"},"options":["فَعِيل","فَعُول","فَعَّال"],"answer":0}]}]},{"id":"vocab-particles","icon":"مِن","title":{"bn":"ছোট শব্দ, বড় শক্তি","en":"Little Words, Big Power"},"subtitle":{"bn":"অব্যয়, সংযোজক, প্রশ্ন ও না-বোধক শব্দ","en":"Prepositions, connectors, questions and negatives"},"minutes":20,"goals":[{"bn":"সবচেয়ে বেশি আসা ছোট শব্দগুলো (অব্যয়) চিনব","en":"Recognise the most frequent little words (particles)"},{"bn":"শব্দের সাথে লেগে থাকা এক-অক্ষরের শব্দ ({{بِـ}}, {{لِـ}}, {{وَ}}, {{فَـ}}) আলাদা করতে শিখব","en":"Split off one-letter words that stick to the next word ({{بِـ}}, {{لِـ}}, {{وَ}}, {{فَـ}})"},{"bn":"{{لَا}}, {{لَمْ}}, {{لَنْ}}, {{لَيْسَ}} — না-বোধক শব্দের পার্থক্য বুঝব","en":"Tell apart the negatives {{لَا}}, {{لَمْ}}, {{لَنْ}}, {{لَيْسَ}}"}],"blocks":[{"type":"text","bn":"{{مِنْ}}, {{فِي}}, {{عَلَى}}, {{إِلَى}} তুমি প্রথম পাঠেই শিখেছ। এমন ছোট শব্দগুলো বাক্যের ‘কব্জা’র মতো — নিজেরা ছোট, কিন্তু পুরো বাক্যকে জুড়ে রাখে। কুরআনের প্রায় প্রতিটি আয়াতে এগুলোর কোনো না কোনোটি আছে। আজ আরও অনেকগুলো শিখব।","en":"You met {{مِنْ}}, {{فِي}}, {{عَلَى}} and {{إِلَى}} in the first lesson. Little words like these are the ‘hinges’ of a sentence — small, yet they hold everything together. Almost every verse has some of them. Today we add many more."},{"type":"tip","kind":"warn","bn":"কিছু শব্দ মাত্র এক অক্ষরের, আর লেখার সময় পরের শব্দের সাথে **জুড়ে** যায়: {{بِسْمِ}} = {{بِـ}} + {{اسْم}}; {{لِلّٰهِ}} = {{لِـ}} + {{اللّٰه}}; {{فَصَلِّ}} = {{فَـ}} + {{صَلِّ}}। অচেনা শব্দ দেখলে আগে খেয়াল করো — শুরুতে {{بِـ}}, {{لِـ}}, {{كَـ}}, {{وَ}}, {{فَـ}} লুকিয়ে আছে কি না!","en":"Some words are just one letter and are written **joined** to the next word: {{بِسْمِ}} = {{بِـ}} + {{اسْم}}; {{لِلّٰهِ}} = {{لِـ}} + {{اللّٰه}}; {{فَصَلِّ}} = {{فَـ}} + {{صَلِّ}}. When a word looks unfamiliar, first check whether {{بِـ}}, {{لِـ}}, {{كَـ}}, {{وَ}} or {{فَـ}} is hiding at the start!"},{"type":"vocab","title":{"bn":"অব্যয় ও সংযোজক","en":"Prepositions & connectors"},"items":[{"ar":"عَنْ","tr":{"bn":"'আন","en":"'an"},"mean":{"bn":"সম্পর্কে, থেকে (দূরে)","en":"about, from (away)"},"example":{"ar":"عَنِ النَّبَإِ الْعَظِيمِ","mean":{"bn":"মহা সংবাদ সম্পর্কে","en":"about the great news"},"ref":"78:2"}},{"ar":"بِـ","tr":{"bn":"বি","en":"bi"},"mean":{"bn":"দিয়ে, সাথে, -এর কাছে, -এর নামে","en":"with, by, in"},"example":{"ar":"قُلْ أَعُوذُ بِرَبِّ النَّاسِ","mean":{"bn":"বলো, আমি আশ্রয় চাই মানুষের রবের কাছে","en":"Say, ‘I seek refuge with the Lord of mankind’"},"ref":"114:1"}},{"ar":"لِـ","tr":{"bn":"লি","en":"li"},"mean":{"bn":"জন্য, -এর (মালিকানা)","en":"for, to, belongs to"},"example":{"ar":"لِلّٰهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ","mean":{"bn":"আসমানসমূহ ও জমিনে যা আছে সব আল্লাহরই","en":"To Allah belongs whatever is in the heavens and the earth"},"ref":"2:284"}},{"ar":"كَـ","tr":{"bn":"কা","en":"ka"},"mean":{"bn":"মতো","en":"like, as"},"example":{"ar":"يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ","mean":{"bn":"যেদিন মানুষ হবে ছড়িয়ে পড়া পতঙ্গের মতো","en":"the Day people will be like scattered moths"},"ref":"101:4"}},{"ar":"مَعَ","tr":{"bn":"মা'আ","en":"ma'a"},"mean":{"bn":"সাথে","en":"with, together with"},"example":{"ar":"إِنَّ اللّٰهَ مَعَ الصَّابِرِينَ","mean":{"bn":"নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন","en":"Indeed, Allah is with the patient"},"ref":"2:153"}},{"ar":"عِنْدَ","tr":{"bn":"'ইনদা","en":"'inda"},"mean":{"bn":"কাছে, নিকটে","en":"with, near, in the sight of"},"example":{"ar":"إِنَّ الدِّينَ عِنْدَ اللّٰهِ الْإِسْلَامُ","mean":{"bn":"নিশ্চয়ই আল্লাহর কাছে দ্বীন হলো ইসলাম","en":"Indeed, the religion with Allah is Islam"},"ref":"3:19"}},{"ar":"بَيْنَ","tr":{"bn":"বাইনা","en":"bayna"},"mean":{"bn":"মাঝে, মধ্যে","en":"between"},"example":{"ar":"يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ","mean":{"bn":"তিনি জানেন যা তাদের সামনে আছে এবং যা পেছনে","en":"He knows what is before them and what is behind them"},"ref":"2:255"}},{"ar":"قَبْلَ","tr":{"bn":"ক্বাবলা","en":"qabla"},"mean":{"bn":"আগে, পূর্বে","en":"before"},"example":{"ar":"قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ","mean":{"bn":"সূর্য ওঠার আগে এবং অস্ত যাওয়ার আগে","en":"before sunrise and before sunset"},"ref":"50:39"}},{"ar":"بَعْدَ","tr":{"bn":"বা'দা","en":"ba'da"},"mean":{"bn":"পরে","en":"after"},"example":{"ar":"وَالْأَرْضَ بَعْدَ ذٰلِكَ دَحَاهَا","mean":{"bn":"আর এরপর তিনি জমিনকে বিস্তৃত করেছেন","en":"And after that He spread out the earth"},"ref":"79:30"}},{"ar":"فَوْقَ","tr":{"bn":"ফাওক্বা","en":"fawqa"},"mean":{"bn":"উপরে","en":"above, over"},"example":{"ar":"وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا","mean":{"bn":"আর আমি তোমাদের উপরে সাতটি মজবুত (আকাশ) নির্মাণ করেছি","en":"And We built above you seven strong (heavens)"},"ref":"78:12"}},{"ar":"تَحْتَ","tr":{"bn":"তাহতা","en":"taḥta"},"mean":{"bn":"নিচে","en":"under, beneath"},"example":{"ar":"جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ","mean":{"bn":"এমন জান্নাত, যার নিচ দিয়ে নদী বয়ে যায়","en":"gardens beneath which rivers flow"},"ref":"2:25"}},{"ar":"دُونِ","tr":{"bn":"দূনি","en":"dooni"},"mean":{"bn":"ছাড়া, বাদে ({{مِنْ دُونِ}} — ‘ছাড়া’)","en":"other than, besides ({{مِنْ دُونِ}} — ‘besides’)"},"example":{"ar":"وَمَا لَكُمْ مِنْ دُونِ اللّٰهِ مِنْ وَلِيٍّ وَلَا نَصِيرٍ","mean":{"bn":"আর আল্লাহ ছাড়া তোমাদের কোনো অভিভাবক নেই, কোনো সাহায্যকারীও নেই","en":"And you have no protector or helper besides Allah"},"ref":"2:107"}},{"ar":"حَتَّى","tr":{"bn":"হাত্তা","en":"ḥattaa"},"mean":{"bn":"পর্যন্ত, যতক্ষণ না","en":"until"},"example":{"ar":"حَتَّى زُرْتُمُ الْمَقَابِرَ","mean":{"bn":"যতক্ষণ না তোমরা কবরে পৌঁছে যাও","en":"until you visit the graves"},"ref":"102:2"}},{"ar":"وَ","tr":{"bn":"ওয়া","en":"wa"},"mean":{"bn":"এবং; শপথ অর্থেও (‘কসম’)","en":"and; also used for oaths (‘by…’)"},"example":{"ar":"وَاللَّيْلِ إِذَا سَجَى","mean":{"bn":"কসম রাতের, যখন তা নিঝুম হয়","en":"By the night when it grows still"},"ref":"93:2"}},{"ar":"فَـ","tr":{"bn":"ফা","en":"fa"},"mean":{"bn":"তারপর, সুতরাং, অতএব","en":"so, then, therefore"},"example":{"ar":"فَصَلِّ لِرَبِّكَ وَانْحَرْ","mean":{"bn":"অতএব তোমার রবের জন্য সালাত পড়ো ও কুরবানি করো","en":"So pray to your Lord and sacrifice"},"ref":"108:2"}},{"ar":"ثُمَّ","tr":{"bn":"সুম্মা","en":"thumma"},"mean":{"bn":"তারপর (কিছু সময় পরে)","en":"then (after a while)"},"example":{"ar":"ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ","mean":{"bn":"তারপর সেদিন অবশ্যই তোমাদের নিয়ামত সম্পর্কে জিজ্ঞেস করা হবে","en":"Then on that Day you will surely be asked about the pleasures"},"ref":"102:8"}},{"ar":"أَوْ","tr":{"bn":"আও","en":"aw"},"mean":{"bn":"অথবা","en":"or"},"example":{"ar":"أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا","mean":{"bn":"অথবা তার চেয়ে বাড়াও, আর কুরআন ধীরে ধীরে স্পষ্ট করে পড়ো","en":"or add to it, and recite the Quran with measured recitation"},"ref":"73:4"}},{"ar":"بَلْ","tr":{"bn":"বাল","en":"bal"},"mean":{"bn":"বরং","en":"rather, but"},"example":{"ar":"بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا","mean":{"bn":"বরং তোমরা দুনিয়ার জীবনকেই প্রাধান্য দাও","en":"But you prefer the life of this world"},"ref":"87:16"}},{"ar":"لٰكِنَّ","tr":{"bn":"লাকিন্না","en":"laakinna"},"mean":{"bn":"কিন্তু","en":"but, however"},"example":{"ar":"وَلٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ","mean":{"bn":"কিন্তু অধিকাংশ মানুষ জানে না (কুরআনে কয়েকবার এসেছে)","en":"but most people do not know (appears several times)"}}}]},{"type":"tip","kind":"memory","bn":"বাংলায় যে বলি ‘**লেকিন**’ (কিন্তু) — তা এসেছে {{لٰكِنْ}} থেকে। আর গ্রামে যে বলে ‘আসরের **বাদ**’ (আসরের পরে) — সেই ‘বাদ’ হলো {{بَعْدَ}}!","en":"The Bangla word ‘**lekin**’ (but) comes from {{لٰكِنْ}}. And when people say ‘Asr-er **bad**’ (after Asr), that ‘bad’ is {{بَعْدَ}}!"},{"type":"vocab","title":{"bn":"না, প্রশ্ন, শর্ত ও জোর","en":"Negation, questions, conditions & emphasis"},"items":[{"ar":"لَمْ","tr":{"bn":"লাম","en":"lam"},"mean":{"bn":"না (অতীতে করেনি)","en":"did not"},"example":{"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","mean":{"bn":"তিনি জন্ম দেননি, তাঁকেও জন্ম দেওয়া হয়নি","en":"He did not beget, nor was He begotten"},"ref":"112:3"}},{"ar":"لَنْ","tr":{"bn":"লান","en":"lan"},"mean":{"bn":"কখনো না (ভবিষ্যতে)","en":"will never"},"example":{"ar":"لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ","mean":{"bn":"তোমরা কখনো পুণ্য লাভ করবে না, যতক্ষণ না প্রিয় জিনিস থেকে খরচ করো","en":"You will never attain righteousness until you spend from what you love"},"ref":"3:92"}},{"ar":"لَيْسَ","tr":{"bn":"লাইসা","en":"laysa"},"mean":{"bn":"নয়, নেই","en":"is not"},"example":{"ar":"لَيْسَ كَمِثْلِهِ شَيْءٌ","mean":{"bn":"তাঁর মতো কিছুই নেই","en":"There is nothing like Him"},"ref":"42:11"}},{"ar":"إِلَّا","tr":{"bn":"ইল্লা","en":"illaa"},"mean":{"bn":"ছাড়া, ব্যতীত","en":"except, but"},"example":{"ar":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ","mean":{"bn":"তারা ছাড়া, যারা ঈমান এনেছে ও সৎকাজ করেছে","en":"except those who believe and do righteous deeds"},"ref":"103:3"}},{"ar":"قَدْ","tr":{"bn":"ক্বাদ","en":"qad"},"mean":{"bn":"অবশ্যই, নিশ্চয়ই (অতীত ক্রিয়ার আগে)","en":"indeed, certainly (before past verbs)"},"example":{"ar":"قَدْ أَفْلَحَ مَنْ زَكَّاهَا","mean":{"bn":"সে অবশ্যই সফল, যে নিজেকে পবিত্র করেছে","en":"He has indeed succeeded who purifies it"},"ref":"91:9"}},{"ar":"سَوْفَ","tr":{"bn":"সাওফা","en":"sawfa"},"mean":{"bn":"শীঘ্রই, অচিরেই (ভবিষ্যৎ)","en":"will, soon (future)"},"example":{"ar":"كَلَّا سَوْفَ تَعْلَمُونَ","mean":{"bn":"কখনো না! শীঘ্রই তোমরা জানতে পারবে","en":"No! You will soon know"},"ref":"102:3"}},{"ar":"كَلَّا","tr":{"bn":"কাল্লা","en":"kallaa"},"mean":{"bn":"কখনো না! কক্ষনো নয়!","en":"No indeed! By no means!"},"example":{"ar":"كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَى","mean":{"bn":"কখনো না! মানুষ তো সীমালঙ্ঘন করেই","en":"No! Indeed, man transgresses"},"ref":"96:6"}},{"ar":"أَنْ","tr":{"bn":"আন","en":"an"},"mean":{"bn":"যে, -তে (ক্রিয়ার আগে)","en":"to, that (before a verb)"},"example":{"ar":"إِلَّا أَنْ يَشَاءَ اللّٰهُ","mean":{"bn":"তবে আল্লাহ চাইলে (তা আলাদা)","en":"except if Allah wills"},"ref":"18:24"}},{"ar":"أَنَّ","tr":{"bn":"আন্না","en":"anna"},"mean":{"bn":"যে (নিশ্চয়তার সাথে)","en":"that (with certainty)"},"example":{"ar":"أَلَمْ تَعْلَمْ أَنَّ اللّٰهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","mean":{"bn":"তুমি কি জানো না যে আল্লাহ সব কিছুর উপর ক্ষমতাবান?","en":"Do you not know that Allah has power over all things?"},"ref":"2:106"}},{"ar":"إِنَّمَا","tr":{"bn":"ইন্নামা","en":"innamaa"},"mean":{"bn":"কেবল, শুধুমাত্র","en":"only, indeed only"},"example":{"ar":"إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ","mean":{"bn":"মুমিনরা তো পরস্পর ভাই ভাই","en":"The believers are but brothers"},"ref":"49:10"}},{"ar":"لَعَلَّ","tr":{"bn":"লা'আল্লা","en":"la'alla"},"mean":{"bn":"যাতে, হয়তো","en":"so that, perhaps"},"example":{"ar":"لَعَلَّكُمْ تَتَّقُونَ","mean":{"bn":"যাতে তোমরা তাকওয়া অর্জন করো","en":"so that you may become mindful of Allah"},"ref":"2:183"}},{"ar":"إِنْ","tr":{"bn":"ইন","en":"in"},"mean":{"bn":"যদি","en":"if"},"example":{"ar":"إِنْ كُنْتُمْ صَادِقِينَ","mean":{"bn":"যদি তোমরা সত্যবাদী হও","en":"if you are truthful"},"ref":"2:23"}},{"ar":"إِذَا","tr":{"bn":"ইযা","en":"idhaa"},"mean":{"bn":"যখন","en":"when"},"example":{"ar":"إِذَا جَاءَ نَصْرُ اللّٰهِ وَالْفَتْحُ","mean":{"bn":"যখন আসবে আল্লাহর সাহায্য ও বিজয়","en":"When the help of Allah and the victory come"},"ref":"110:1"}},{"ar":"إِذْ","tr":{"bn":"ইয","en":"idh"},"mean":{"bn":"যখন (অতীতের ঘটনা — ‘স্মরণ করো, যখন…’)","en":"when (in the past — ‘recall when…’)"},"example":{"ar":"وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ","mean":{"bn":"আর (স্মরণ করো) যখন তোমার রব ফেরেশতাদের বললেন","en":"And when your Lord said to the angels"},"ref":"2:30"}},{"ar":"لَوْ","tr":{"bn":"লাও","en":"law"},"mean":{"bn":"যদি (কাল্পনিক — ‘যদি হতো’)","en":"if (imagined — ‘if only’)"},"example":{"ar":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ","mean":{"bn":"কখনো না! যদি তোমরা নিশ্চিত জ্ঞানে জানতে!","en":"No! If only you knew with certain knowledge!"},"ref":"102:5"}},{"ar":"هَلْ","tr":{"bn":"হাল","en":"hal"},"mean":{"bn":"কি? (হ্যাঁ/না প্রশ্ন)","en":"is? does? (yes/no question)"},"example":{"ar":"هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ","mean":{"bn":"তোমার কাছে কি আচ্ছন্নকারী (কিয়ামতের) খবর পৌঁছেছে?","en":"Has the news of the Overwhelming reached you?"},"ref":"88:1"}},{"ar":"أَلَمْ","tr":{"bn":"আলাম","en":"alam"},"mean":{"bn":"…নি কি? (প্রশ্ন + না)","en":"did … not? (question + not)"},"example":{"ar":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","mean":{"bn":"আমি কি তোমার বুক প্রশস্ত করে দিইনি?","en":"Did We not expand your chest for you?"},"ref":"94:1"}},{"ar":"كَيْفَ","tr":{"bn":"কাইফা","en":"kayfa"},"mean":{"bn":"কীভাবে, কেমন","en":"how"},"example":{"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ","mean":{"bn":"তুমি কি দেখোনি, তোমার রব হাতিওয়ালাদের সাথে কী করেছিলেন?","en":"Have you not seen how your Lord dealt with the people of the elephant?"},"ref":"105:1"}},{"ar":"أَيْنَ","tr":{"bn":"আইনা","en":"ayna"},"mean":{"bn":"কোথায়","en":"where"},"example":{"ar":"فَأَيْنَ تَذْهَبُونَ","mean":{"bn":"তবে তোমরা কোথায় যাচ্ছ?","en":"So where are you going?"},"ref":"81:26"}},{"ar":"مَتَى","tr":{"bn":"মাতা","en":"mataa"},"mean":{"bn":"কখন","en":"when? (question)"},"example":{"ar":"مَتَى نَصْرُ اللّٰهِ","mean":{"bn":"কখন আসবে আল্লাহর সাহায্য?","en":"When is the help of Allah?"},"ref":"2:214"}},{"ar":"يَا","tr":{"bn":"ইয়া","en":"yaa"},"mean":{"bn":"হে (সম্বোধন)","en":"O (calling someone)"},"example":{"ar":"يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ","mean":{"bn":"হে মানুষ, তোমাদের রবের ইবাদত করো","en":"O mankind, worship your Lord"},"ref":"2:21"}}]},{"type":"table","title":{"bn":"‘না’ বলার পাঁচ উপায়","en":"Five ways to say ‘not’"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"কখন ব্যবহার","en":"Used for"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["لَا",{"bn":"বর্তমান/সাধারণ ‘না’; নিষেধ","en":"present/general ‘not’; prohibition"},"لَا أَعْبُدُ مَا تَعْبُدُونَ"],["مَا",{"bn":"অতীত বা সাধারণ ‘না’","en":"past or general ‘not’"},"مَا أَغْنَى عَنْهُ مَالُهُ"],["لَمْ",{"bn":"অতীতে ‘করেনি’ (পরে বর্তমান কালের ক্রিয়া)","en":"‘did not’ (followed by a present-tense verb)"},"لَمْ يَلِدْ"],["لَنْ",{"bn":"ভবিষ্যতে ‘কখনো করবে না’","en":"‘will never’ (future)"},"لَنْ تَنَالُوا الْبِرَّ"],["لَيْسَ",{"bn":"‘নয়’ (নাম-বাক্যে)","en":"‘is not’ (in noun sentences)"},"لَيْسَ كَمِثْلِهِ شَيْءٌ"]]},{"type":"compare","title":{"bn":"দেখতে কাছাকাছি, অর্থ আলাদা","en":"Look alike, mean different things"},"items":[{"ar":"إِنْ","label":{"bn":"যদি","en":"if"},"desc":{"bn":"হামযার নিচে যের, নূনে সুকুন — শর্ত","en":"kasra under hamza, sukoon on noon — a condition"}},{"ar":"إِنَّ","label":{"bn":"নিশ্চয়ই","en":"indeed"},"desc":{"bn":"নূনে তাশদীদ — জোর দেওয়া","en":"shadda on noon — emphasis"}},{"ar":"أَنْ","label":{"bn":"যে / -তে","en":"to / that"},"desc":{"bn":"হামযার উপর যবর — সাধারণত ক্রিয়ার আগে","en":"fatha on hamza — usually before a verb"}},{"ar":"أَنَّ","label":{"bn":"যে (নিশ্চিতভাবে)","en":"that (certainly)"},"desc":{"bn":"যবর + তাশদীদ — সাধারণত নামের আগে","en":"fatha + shadda — usually before a noun"}}]},{"type":"examples","title":{"bn":"এক আয়াতে অনেক ছোট শব্দ","en":"Many little words in one verse"},"items":[{"ar":"إِنَّ اللّٰهَ مَعَ الصَّابِرِينَ","tr":{"bn":"ইন্নাল্লাহা মা'আস সাবিরীন","en":"innallaaha ma'aṣ-ṣaabireen"},"mean":{"bn":"নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন","en":"Indeed, Allah is with the patient"},"note":{"bn":"২:১৫৩","en":"2:153"},"hl":"مَعَ"},{"ar":"ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ","tr":{"bn":"সুম্মা লাতুসআলুন্না ইয়াওমাইযিন 'আনিন না'ঈম","en":"thumma latus'alunna yawma'idhin 'anin-na'eem"},"mean":{"bn":"তারপর সেদিন অবশ্যই নিয়ামত সম্পর্কে জিজ্ঞাসিত হবে","en":"Then on that Day you will surely be asked about the pleasures"},"note":{"bn":"১০২:৮ — {{ثُمَّ}} ও {{عَنْ}} খুঁজে নাও","en":"102:8 — find {{ثُمَّ}} and {{عَنْ}}"},"hl":"ثُمَّ"},{"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ","tr":{"bn":"আলাম তারা কাইফা ফা'আলা রব্বুক","en":"alam tara kayfa fa'ala rabbuk"},"mean":{"bn":"তুমি কি দেখোনি, তোমার রব কী করেছিলেন?","en":"Have you not seen how your Lord dealt…?"},"note":{"bn":"১০৫:১","en":"105:1"},"hl":"كَيْفَ"}]},{"type":"quiz","items":[{"q":{"bn":"{{ثُمَّ}} মানে কী?","en":"What does {{ثُمَّ}} mean?"},"ar":"ثُمَّ","options":[{"bn":"তারপর","en":"then"},{"bn":"অথবা","en":"or"},{"bn":"কিন্তু","en":"but"}],"answer":0},{"q":{"bn":"{{مَعَ}} শব্দের অর্থ —","en":"{{مَعَ}} means —"},"ar":"مَعَ","options":[{"bn":"সাথে","en":"with"},{"bn":"নিচে","en":"under"},{"bn":"আগে","en":"before"}],"answer":0},{"q":{"bn":"‘কখনো না (ভবিষ্যতে)’ — কোন শব্দ?","en":"Which word means ‘will never’?"},"options":["لَمْ","لَنْ","لَا","مَا"],"answer":1},{"q":{"bn":"{{بِسْمِ}} শব্দের শুরুতে কোন ছোট শব্দ লুকিয়ে আছে?","en":"Which little word hides at the start of {{بِسْمِ}}?"},"options":["بِـ","لِـ","فَـ"],"answer":0,"explain":{"bn":"{{بِسْمِ}} = {{بِـ}} (দিয়ে/নামে) + {{اسْم}} (নাম)","en":"{{بِسْمِ}} = {{بِـ}} (with/in) + {{اسْم}} (name)"}},{"q":{"bn":"{{إِنْ}} আর {{إِنَّ}} — কোনটি ‘যদি’?","en":"{{إِنْ}} or {{إِنَّ}} — which one means ‘if’?"},"options":["إِنْ","إِنَّ"],"answer":0},{"q":{"bn":"{{كَيْفَ}} মানে কী?","en":"What does {{كَيْفَ}} mean?"},"ar":"كَيْفَ","options":[{"bn":"কোথায়","en":"where"},{"bn":"কখন","en":"when"},{"bn":"কীভাবে","en":"how"}],"answer":2},{"q":{"bn":"{{يَا أَيُّهَا النَّاسُ}} — {{يَا}} এখানে কী বোঝায়?","en":"In {{يَا أَيُّهَا النَّاسُ}}, what does {{يَا}} do?"},"options":[{"bn":"সম্বোধন: ‘হে’","en":"calls: ‘O’"},{"bn":"প্রশ্ন: ‘কি?’","en":"asks: ‘is?’"},{"bn":"না-বোধক","en":"negates"}],"answer":0},{"q":{"bn":"{{إِلَّا}} শব্দের অর্থ —","en":"{{إِلَّا}} means —"},"ar":"إِلَّا","options":[{"bn":"ছাড়া","en":"except"},{"bn":"যখন","en":"when"},{"bn":"বরং","en":"rather"}],"answer":0},{"q":{"bn":"বাংলা ‘লেকিন’ কোন আরবি শব্দ থেকে?","en":"Bangla ‘lekin’ comes from which Arabic word?"},"options":["لٰكِنْ","لَكُمْ","لَيْسَ"],"answer":0}]}]},{"id":"vocab-pronouns","icon":"هو","title":{"bn":"সর্বনাম ও ইঙ্গিতবাচক শব্দ","en":"Pronouns & Pointing Words"},"subtitle":{"bn":"সে, তুমি, আমরা, এই, ওই, যে — কে কাকে বোঝায়","en":"He, you, we, this, that, who — who is meant?"},"minutes":16,"goals":[{"bn":"আলাদা সর্বনাম ({{أَنَا}}, {{نَحْنُ}}, {{هُمْ}} …) শিখব","en":"Learn the separate pronouns ({{أَنَا}}, {{نَحْنُ}}, {{هُمْ}} …)"},{"bn":"শব্দের শেষে লেগে থাকা সর্বনাম ({{ـهُ}}, {{ـكَ}}, {{ـنَا}} …) চিনব","en":"Recognise pronouns attached to word endings ({{ـهُ}}, {{ـكَ}}, {{ـنَا}} …)"},{"bn":"{{هٰذَا}}, {{ذٰلِكَ}}, {{الَّذِينَ}} ইত্যাদি ইঙ্গিত ও সম্বন্ধবাচক শব্দ বুঝব","en":"Understand pointing and linking words like {{هٰذَا}}, {{ذٰلِكَ}}, {{الَّذِينَ}}"}],"blocks":[{"type":"text","bn":"কুরআনে কে কথা বলছেন আর কাকে বলছেন — সেটা বোঝার চাবি হলো সর্বনাম। {{هُوَ}} (তিনি) তুমি আগেই শিখেছ। আরবিতে সর্বনাম দুই রকম: **আলাদা** (নিজেই একটি শব্দ) আর **সংযুক্ত** (অন্য শব্দের শেষে লেগে থাকে)।","en":"Pronouns are the key to knowing who is speaking in the Quran and to whom. You already know {{هُوَ}} (he). Arabic pronouns come in two kinds: **separate** (a word on its own) and **attached** (stuck to the end of another word)."},{"type":"vocab","title":{"bn":"আলাদা সর্বনাম","en":"Separate pronouns"},"items":[{"ar":"هِيَ","tr":{"bn":"হিয়া","en":"hiya"},"mean":{"bn":"সে (স্ত্রী), এটি","en":"she, it"},"example":{"ar":"قَالَ هِيَ عَصَايَ","mean":{"bn":"সে বলল, এটি আমার লাঠি","en":"He said, ‘It is my staff’"},"ref":"20:18"}},{"ar":"هُمْ","tr":{"bn":"হুম","en":"hum"},"mean":{"bn":"তারা","en":"they"},"example":{"ar":"وَأُولٰئِكَ هُمُ الْمُفْلِحُونَ","mean":{"bn":"আর তারাই সফলকাম","en":"and it is they who are the successful"},"ref":"2:5"}},{"ar":"أَنْتَ","tr":{"bn":"আনতা","en":"anta"},"mean":{"bn":"তুমি (পুরুষ)","en":"you (masc. sing.)"},"example":{"ar":"أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","mean":{"bn":"তুমিই আমাদের অভিভাবক, তাই কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করো","en":"You are our Protector, so help us against the disbelieving people"},"ref":"2:286"}},{"ar":"أَنْتُمْ","tr":{"bn":"আনতুম","en":"antum"},"mean":{"bn":"তোমরা","en":"you (plural)"},"example":{"ar":"يَا أَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللّٰهِ","mean":{"bn":"হে মানুষ, তোমরাই আল্লাহর মুখাপেক্ষী","en":"O mankind, it is you who are in need of Allah"},"ref":"35:15"}},{"ar":"أَنَا","tr":{"bn":"আনা","en":"anaa"},"mean":{"bn":"আমি","en":"I"},"example":{"ar":"إِنَّنِي أَنَا اللّٰهُ لَا إِلٰهَ إِلَّا أَنَا","mean":{"bn":"নিশ্চয়ই আমিই আল্লাহ, আমি ছাড়া কোনো ইলাহ নেই","en":"Indeed, I am Allah; there is no god but Me"},"ref":"20:14"}},{"ar":"نَحْنُ","tr":{"bn":"নাহনু","en":"naḥnu"},"mean":{"bn":"আমরা","en":"we"},"example":{"ar":"إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ","mean":{"bn":"নিশ্চয়ই আমিই এই উপদেশবাণী (কুরআন) নাজিল করেছি এবং আমিই এর সংরক্ষক","en":"Indeed, it is We who sent down the Reminder, and We are its Guardian"},"ref":"15:9"}}]},{"type":"tip","kind":"fun","bn":"আল্লাহ অনেক আয়াতে নিজের জন্য {{نَحْنُ}} (আমরা) বা {{ـنَا}} ব্যবহার করেছেন। এটি সংখ্যা বোঝায় না — আল্লাহ এক! এটি **মহিমা ও সম্মানের বহুবচন**, যেমন বাংলায় সম্মান দেখাতে ‘তুমি’র বদলে ‘আপনি’ বলি। তাই অনুবাদে অনেক সময় ‘আমি’ লেখা হয়।","en":"In many verses Allah uses {{نَحْنُ}} (We) or {{ـنَا}} for Himself. This is not about number — Allah is One! It is the **plural of majesty**, a bit like how Bangla uses respectful ‘apni’ instead of ‘tumi’. That is why translations often render it as ‘I’."},{"type":"vocab","title":{"bn":"সংযুক্ত সর্বনাম (শব্দের শেষে)","en":"Attached pronouns (word endings)"},"items":[{"ar":"ـهُ","tr":{"bn":"-হু","en":"-hu"},"mean":{"bn":"তার, তাকে (পুরুষ)","en":"his, him, its"},"example":{"ar":"لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ","mean":{"bn":"আসমানসমূহ ও জমিনে যা আছে সবই তাঁর","en":"To Him belongs whatever is in the heavens and the earth"},"ref":"2:255"}},{"ar":"ـهَا","tr":{"bn":"-হা","en":"-haa"},"mean":{"bn":"তার, তাকে (স্ত্রী)","en":"her, its"},"example":{"ar":"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا","mean":{"bn":"অতঃপর তিনি তাকে তার পাপ ও তাকওয়ার জ্ঞান দিয়েছেন","en":"and inspired it with its wickedness and its righteousness"},"ref":"91:8"}},{"ar":"ـهُمْ","tr":{"bn":"-হুম","en":"-hum"},"mean":{"bn":"তাদের, তাদেরকে","en":"their, them"},"example":{"ar":"جَزَاؤُهُمْ عِنْدَ رَبِّهِمْ جَنَّاتُ عَدْنٍ","mean":{"bn":"তাদের রবের কাছে তাদের প্রতিদান হলো স্থায়ী জান্নাত","en":"Their reward with their Lord is gardens of eternity"},"ref":"98:8"}},{"ar":"ـكَ","tr":{"bn":"-কা","en":"-ka"},"mean":{"bn":"তোমার, তোমাকে","en":"your, you"},"example":{"ar":"وَرَفَعْنَا لَكَ ذِكْرَكَ","mean":{"bn":"আর আমি তোমার জন্য তোমার স্মরণকে উঁচু করেছি","en":"And We raised high your mention for you"},"ref":"94:4"}},{"ar":"ـكُمْ","tr":{"bn":"-কুম","en":"-kum"},"mean":{"bn":"তোমাদের, তোমাদেরকে","en":"your, you (plural)"},"example":{"ar":"وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ","mean":{"bn":"আর তোমরা যেখানেই থাকো, তিনি তোমাদের সাথে আছেন","en":"And He is with you wherever you are"},"ref":"57:4"}},{"ar":"ـي","tr":{"bn":"-ঈ","en":"-ee"},"mean":{"bn":"আমার, আমাকে","en":"my, me"},"example":{"ar":"وَيَسِّرْ لِي أَمْرِي","mean":{"bn":"আর আমার কাজ আমার জন্য সহজ করে দাও","en":"and make my task easy for me"},"ref":"20:26"}},{"ar":"ـنَا","tr":{"bn":"-না","en":"-naa"},"mean":{"bn":"আমাদের, আমাদেরকে","en":"our, us"},"example":{"ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا","mean":{"bn":"হে আমাদের রব, হিদায়াত দেওয়ার পর আমাদের অন্তরকে বাঁকা করো না","en":"Our Lord, do not let our hearts deviate after You have guided us"},"ref":"3:8"}}]},{"type":"table","title":{"bn":"এক শব্দ, সাত মালিক: {{رَبّ}} + সর্বনাম","en":"One word, seven owners: {{رَبّ}} + pronoun"},"head":[{"bn":"আলাদা","en":"Separate"},{"bn":"সংযুক্ত","en":"Attached"},{"bn":"উদাহরণ","en":"Example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["هُوَ","ـهُ","رَبُّهُ",{"bn":"তার রব","en":"his Lord"}],["هِيَ","ـهَا","رَبُّهَا",{"bn":"তার (স্ত্রী) রব","en":"her Lord"}],["هُمْ","ـهُمْ","رَبُّهُمْ",{"bn":"তাদের রব","en":"their Lord"}],["أَنْتَ","ـكَ","رَبُّكَ",{"bn":"তোমার রব","en":"your Lord"}],["أَنْتُمْ","ـكُمْ","رَبُّكُمْ",{"bn":"তোমাদের রব","en":"your (pl.) Lord"}],["أَنَا","ـي","رَبِّي",{"bn":"আমার রব","en":"my Lord"}],["نَحْنُ","ـنَا","رَبُّنَا",{"bn":"আমাদের রব","en":"our Lord"}]]},{"type":"tip","kind":"memory","bn":"মনে রাখার কৌশল: **ক = তুমি** ({{رَبُّكَ}} তোমার রব), **না = আমরা** ({{رَبَّنَا}} আমাদের রব), **হু = সে** ({{رَبُّهُ}} তার রব), **ঈ = আমি** ({{رَبِّي}} আমার রব)। সালাতের {{سُبْحَانَ رَبِّيَ}} — ‘আমার রব’, আর {{رَبَّنَا وَلَكَ الْحَمْدُ}} — ‘আমাদের রব… তোমার জন্য প্রশংসা’!","en":"Memory trick: **ka = you** ({{رَبُّكَ}} your Lord), **naa = we** ({{رَبَّنَا}} our Lord), **hu = he** ({{رَبُّهُ}} his Lord), **ee = I** ({{رَبِّي}} my Lord). In salah, {{سُبْحَانَ رَبِّيَ}} is ‘my Lord’, and {{رَبَّنَا وَلَكَ الْحَمْدُ}} is ‘our Lord… to You be praise’!"},{"type":"vocab","title":{"bn":"ইঙ্গিত ও সম্বন্ধবাচক শব্দ","en":"Pointing & linking words"},"items":[{"ar":"هٰذَا","tr":{"bn":"হাযা","en":"haadhaa"},"mean":{"bn":"এই, এটি (পুরুষ)","en":"this (masc.)"},"example":{"ar":"فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِ","mean":{"bn":"সুতরাং তারা যেন এই ঘরের রবের ইবাদত করে","en":"So let them worship the Lord of this House"},"ref":"106:3"}},{"ar":"هٰذِهِ","tr":{"bn":"হাযিহী","en":"haadhihi"},"mean":{"bn":"এই, এটি (স্ত্রী)","en":"this (fem.)"},"example":{"ar":"وَلَا تَقْرَبَا هٰذِهِ الشَّجَرَةَ","mean":{"bn":"আর তোমরা দুজন এই গাছের কাছে যেয়ো না","en":"And do not approach this tree"},"ref":"2:35"}},{"ar":"ذٰلِكَ","tr":{"bn":"যালিকা","en":"dhaalika"},"mean":{"bn":"ওই, সেই (পুরুষ)","en":"that (masc.)"},"example":{"ar":"ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ","mean":{"bn":"এই সেই কিতাব, এতে কোনো সন্দেহ নেই","en":"That is the Book, no doubt in it"},"ref":"2:2"}},{"ar":"تِلْكَ","tr":{"bn":"তিলকা","en":"tilka"},"mean":{"bn":"ওই, সেই (স্ত্রী)","en":"that (fem.)"},"example":{"ar":"تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ","mean":{"bn":"এগুলো প্রজ্ঞাময় কিতাবের আয়াত","en":"These are the verses of the wise Book"},"ref":"31:2"}},{"ar":"هٰؤُلَاءِ","tr":{"bn":"হা-উলা-ই","en":"haa'ulaa'i"},"mean":{"bn":"এরা, এগুলো","en":"these (plural)"},"example":{"ar":"أَنْبِئُونِي بِأَسْمَاءِ هٰؤُلَاءِ","mean":{"bn":"আমাকে এগুলোর নাম বলো","en":"Tell Me the names of these"},"ref":"2:31"}},{"ar":"أُولٰئِكَ","tr":{"bn":"উলা-ইকা","en":"ulaa'ika"},"mean":{"bn":"ওরা, তারা","en":"those (plural)"},"example":{"ar":"أُولٰئِكَ عَلَى هُدًى مِنْ رَبِّهِمْ","mean":{"bn":"তারাই তাদের রবের পক্ষ থেকে হিদায়াতের উপর আছে","en":"Those are upon guidance from their Lord"},"ref":"2:5"}},{"ar":"الَّذِينَ","tr":{"bn":"আল্লাযীনা","en":"alladheena"},"mean":{"bn":"যারা (বহুবচন)","en":"those who"},"example":{"ar":"الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ","mean":{"bn":"যারা অদৃশ্যে ঈমান আনে","en":"who believe in the unseen"},"ref":"2:3"}},{"ar":"الَّتِي","tr":{"bn":"আল্লাতী","en":"allatee"},"mean":{"bn":"যে, যা (স্ত্রী)","en":"who, which (fem.)"},"example":{"ar":"فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجَارَةُ","mean":{"bn":"তাহলে সেই আগুনকে ভয় করো, যার জ্বালানি মানুষ ও পাথর","en":"then fear the Fire whose fuel is people and stones"},"ref":"2:24"}},{"ar":"مَنْ","tr":{"bn":"মান","en":"man"},"mean":{"bn":"কে? / যে, যারা","en":"who? / whoever"},"example":{"ar":"مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ","mean":{"bn":"কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে?","en":"Who could intercede with Him except by His permission?"},"ref":"2:255"}}]},{"type":"table","title":{"bn":"কাছের ও দূরের ইঙ্গিত","en":"Near and far pointing"},"head":[{"bn":"ধরন","en":"Type"},{"bn":"কাছে (এই)","en":"Near (this)"},{"bn":"দূরে (ওই)","en":"Far (that)"}],"rows":[[{"bn":"পুরুষ","en":"Masculine"},"هٰذَا","ذٰلِكَ"],[{"bn":"স্ত্রী","en":"Feminine"},"هٰذِهِ","تِلْكَ"],[{"bn":"বহুবচন","en":"Plural"},"هٰؤُلَاءِ","أُولٰئِكَ"]]},{"type":"tip","kind":"warn","bn":"{{مَنْ}} (কে/যে) আর {{مِنْ}} (থেকে) — লেখা একই, শুধু হরকত আলাদা! {{مَنْ}}-এ যবর, {{مِنْ}}-এ যের। হরকত ভালো করে দেখে পড়ো।","en":"{{مَنْ}} (who) and {{مِنْ}} (from) are spelled the same — only the vowel differs! Fatha in {{مَنْ}}, kasra in {{مِنْ}}. Always check the harakat."},{"type":"quiz","items":[{"q":{"bn":"{{نَحْنُ}} মানে কী?","en":"What does {{نَحْنُ}} mean?"},"ar":"نَحْنُ","options":[{"bn":"আমরা","en":"we"},{"bn":"তারা","en":"they"},{"bn":"তোমরা","en":"you (pl.)"}],"answer":0},{"q":{"bn":"{{رَبُّكَ}} — অর্থ কী?","en":"What does {{رَبُّكَ}} mean?"},"ar":"رَبُّكَ","options":[{"bn":"আমার রব","en":"my Lord"},{"bn":"তোমার রব","en":"your Lord"},{"bn":"তাদের রব","en":"their Lord"}],"answer":1},{"q":{"bn":"‘আমাদের রব’ আরবিতে —","en":"‘Our Lord’ in Arabic —"},"options":["رَبِّي","رَبُّهُمْ","رَبَّنَا","رَبُّكُمْ"],"answer":2},{"q":{"bn":"{{ذٰلِكَ}} শব্দের অর্থ —","en":"{{ذٰلِكَ}} means —"},"ar":"ذٰلِكَ","options":[{"bn":"এই (কাছে)","en":"this (near)"},{"bn":"ওই, সেই (দূরে)","en":"that (far)"},{"bn":"যারা","en":"those who"}],"answer":1},{"q":{"bn":"{{الَّذِينَ}} মানে —","en":"{{الَّذِينَ}} means —"},"ar":"الَّذِينَ","options":[{"bn":"যারা","en":"those who"},{"bn":"এরা","en":"these"},{"bn":"তোমরা","en":"you (pl.)"}],"answer":0},{"q":{"bn":"{{هٰذِهِ}} কোন ধরনের শব্দের জন্য?","en":"{{هٰذِهِ}} is used for —"},"options":[{"bn":"স্ত্রীলিঙ্গ, কাছে","en":"feminine, near"},{"bn":"পুরুষ, দূরে","en":"masculine, far"},{"bn":"বহুবচন, দূরে","en":"plural, far"}],"answer":0},{"q":{"bn":"আল্লাহ নিজের জন্য {{نَحْنُ}} বলেন — কারণ?","en":"Allah says {{نَحْنُ}} about Himself — why?"},"options":[{"bn":"মহিমা ও সম্মান বোঝাতে","en":"to express majesty"},{"bn":"তিনি একাধিক বলে","en":"because He is many"},{"bn":"ভুল করে","en":"by mistake"}],"answer":0},{"q":{"bn":"{{مَنْ}} আর {{مِنْ}} — কোনটি ‘কে/যে’?","en":"{{مَنْ}} or {{مِنْ}} — which means ‘who’?"},"options":["مَنْ","مِنْ"],"answer":0}]}]},{"id":"vocab-people","icon":"ن","title":{"bn":"মানুষ ও সম্পর্ক","en":"People & Relationships"},"subtitle":{"bn":"মানুষ, জাতি, নবী, মুমিন, পরিবার — কুরআনের চরিত্রেরা","en":"Mankind, nations, prophets, believers, family — the Quran's characters"},"minutes":16,"goals":[{"bn":"মানুষ ও বিভিন্ন দলের নাম শিখব (মুমিন, কাফির, মুনাফিক …)","en":"Learn words for people and groups (believer, disbeliever, hypocrite …)"},{"bn":"পরিবার ও আত্মীয়তার শব্দ চিনব","en":"Recognise family and relationship words"},{"bn":"{{مُـ}} দিয়ে শুরু ‘কর্তা’ শব্দের ছাঁচ লক্ষ করব","en":"Notice the ‘doer’ words that begin with {{مُـ}}"}],"blocks":[{"type":"text","bn":"কুরআন মানুষের সাথে কথা বলে, মানুষের গল্প বলে। কখনো ডাকে {{يَا أَيُّهَا النَّاسُ}} (হে মানুষ), কখনো {{يَا أَيُّهَا الَّذِينَ آمَنُوا}} (হে মুমিনগণ)। এই পাঠে আমরা কুরআনের ‘চরিত্রদের’ নাম শিখব।","en":"The Quran speaks to people and tells their stories. Sometimes it calls {{يَا أَيُّهَا النَّاسُ}} (O mankind), sometimes {{يَا أَيُّهَا الَّذِينَ آمَنُوا}} (O you who believe). In this lesson we learn the names of the Quran's ‘characters’."},{"type":"vocab","title":{"bn":"মানুষ, জাতি ও বিশ্বাসের দল","en":"Mankind, nations & groups by belief"},"items":[{"ar":"نَاس","tr":{"bn":"নাস","en":"naas"},"mean":{"bn":"মানুষ (সকল মানুষ)","en":"people, mankind"},"root":"ن و س","example":{"ar":"مِنَ الْجِنَّةِ وَالنَّاسِ","mean":{"bn":"জিন ও মানুষের মধ্য থেকে","en":"from among jinn and mankind"},"ref":"114:6"}},{"ar":"إِنْسَان","tr":{"bn":"ইনসান","en":"insaan"},"mean":{"bn":"মানুষ (একজন), মানবজাতি","en":"human being, man"},"root":"أ ن س","example":{"ar":"إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ","mean":{"bn":"নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে","en":"Indeed, mankind is in loss"},"ref":"103:2"}},{"ar":"بَشَر","tr":{"bn":"বাশার","en":"bashar"},"mean":{"bn":"মানুষ (রক্ত-মাংসের)","en":"human (being of flesh)"},"root":"ب ش ر","example":{"ar":"قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَى إِلَيَّ","mean":{"bn":"বলো, আমি তো তোমাদের মতোই একজন মানুষ, আমার কাছে ওহি আসে","en":"Say, ‘I am only a human like you, to whom revelation comes’"},"ref":"18:110"}},{"ar":"قَوْم","tr":{"bn":"ক্বাওম","en":"qawm"},"mean":{"bn":"জাতি, সম্প্রদায়","en":"people, nation, community"},"root":"ق و م","example":{"ar":"يَا قَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِنْ إِلٰهٍ غَيْرُهُ","mean":{"bn":"হে আমার জাতি, আল্লাহর ইবাদত করো, তিনি ছাড়া তোমাদের কোনো ইলাহ নেই","en":"O my people, worship Allah; you have no god other than Him"},"ref":"7:59"}},{"ar":"أُمَّة","tr":{"bn":"উম্মাহ","en":"ummah"},"mean":{"bn":"উম্মত, জাতি","en":"nation, community"},"root":"أ م م","example":{"ar":"كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ","mean":{"bn":"তোমরাই শ্রেষ্ঠ উম্মত, যাদের বের করা হয়েছে মানুষের কল্যাণে","en":"You are the best nation brought forth for mankind"},"ref":"3:110"}},{"ar":"رَسُول","tr":{"bn":"রাসূল","en":"rasool"},"mean":{"bn":"রাসূল, বার্তাবাহক","en":"messenger"},"root":"ر س ل","example":{"ar":"مُحَمَّدٌ رَسُولُ اللّٰهِ","mean":{"bn":"মুহাম্মাদ আল্লাহর রাসূল","en":"Muhammad is the Messenger of Allah"},"ref":"48:29"}},{"ar":"نَبِيّ","tr":{"bn":"নাবিয়্য","en":"nabiyy"},"mean":{"bn":"নবী","en":"prophet"},"root":"ن ب أ","example":{"ar":"إِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ","mean":{"bn":"নিশ্চয়ই আল্লাহ ও তাঁর ফেরেশতারা নবীর উপর দরুদ পাঠান","en":"Indeed, Allah and His angels send blessings upon the Prophet"},"ref":"33:56"}},{"ar":"مُؤْمِن","tr":{"bn":"মু'মিন","en":"mu'min"},"mean":{"bn":"মুমিন, বিশ্বাসী","en":"believer"},"root":"أ م ن","example":{"ar":"قَدْ أَفْلَحَ الْمُؤْمِنُونَ","mean":{"bn":"মুমিনরা অবশ্যই সফল হয়েছে","en":"The believers have certainly succeeded"},"ref":"23:1"}},{"ar":"مُسْلِم","tr":{"bn":"মুসলিম","en":"muslim"},"mean":{"bn":"মুসলিম, আত্মসমর্পণকারী","en":"Muslim, one who submits"},"root":"س ل م","example":{"ar":"وَأَنَا أَوَّلُ الْمُسْلِمِينَ","mean":{"bn":"আর আমিই প্রথম আত্মসমর্পণকারী","en":"and I am the first of those who submit"},"ref":"6:163"}},{"ar":"مُتَّقِين","tr":{"bn":"মুত্তাক্বীন","en":"muttaqeen"},"mean":{"bn":"মুত্তাকিরা, আল্লাহভীরুরা","en":"the God-conscious, the righteous"},"root":"و ق ي","example":{"ar":"ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ هُدًى لِلْمُتَّقِينَ","mean":{"bn":"এই সেই কিতাব, এতে সন্দেহ নেই, মুত্তাকিদের জন্য হিদায়াত","en":"That is the Book, no doubt in it, guidance for the God-conscious"},"ref":"2:2"}},{"ar":"مُحْسِن","tr":{"bn":"মুহসিন","en":"muḥsin"},"mean":{"bn":"সৎকর্মশীল, যে সুন্দরভাবে কাজ করে","en":"one who does good, excellent in deeds"},"root":"ح س ن","example":{"ar":"إِنَّ اللّٰهَ يُحِبُّ الْمُحْسِنِينَ","mean":{"bn":"নিশ্চয়ই আল্লাহ সৎকর্মশীলদের ভালোবাসেন","en":"Indeed, Allah loves those who do good"},"ref":"2:195"}},{"ar":"كَافِر","tr":{"bn":"কাফির","en":"kaafir"},"mean":{"bn":"কাফির, অবিশ্বাসী (যে সত্য অস্বীকার করে)","en":"disbeliever (one who rejects the truth)"},"root":"ك ف ر","example":{"ar":"قُلْ يَا أَيُّهَا الْكَافِرُونَ","mean":{"bn":"বলো, হে কাফিররা","en":"Say, ‘O disbelievers’"},"ref":"109:1"}},{"ar":"مُشْرِك","tr":{"bn":"মুশরিক","en":"mushrik"},"mean":{"bn":"মুশরিক, যে আল্লাহর সাথে শরিক করে","en":"one who associates partners with Allah"},"root":"ش ر ك","example":{"ar":"وَمَا أَنَا مِنَ الْمُشْرِكِينَ","mean":{"bn":"আর আমি মুশরিকদের অন্তর্ভুক্ত নই","en":"and I am not of those who associate partners"},"ref":"6:79"}},{"ar":"مُنَافِق","tr":{"bn":"মুনাফিক্ব","en":"munaafiq"},"mean":{"bn":"মুনাফিক, কপট","en":"hypocrite"},"root":"ن ف ق","example":{"ar":"إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ","mean":{"bn":"নিশ্চয়ই মুনাফিকরা জাহান্নামের সবচেয়ে নিচের স্তরে থাকবে","en":"Indeed, the hypocrites will be in the lowest depth of the Fire"},"ref":"4:145"}},{"ar":"ظَالِم","tr":{"bn":"যালিম","en":"ẓaalim"},"mean":{"bn":"জালিম, অন্যায়কারী","en":"wrongdoer, oppressor"},"root":"ظ ل م","example":{"ar":"لَا إِلٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","mean":{"bn":"তুমি ছাড়া কোনো ইলাহ নেই, তুমি পবিত্র; আমি তো জালিমদের অন্তর্ভুক্ত ছিলাম","en":"There is no god but You, glory be to You; I was among the wrongdoers"},"ref":"21:87"}}]},{"type":"tip","kind":"tip","bn":"খেয়াল করো: {{مُؤْمِن}}, {{مُسْلِم}}, {{مُحْسِن}}, {{مُشْرِك}}, {{مُنَافِق}} — সবগুলো {{مُـ}} দিয়ে শুরু। {{مُـ}} দিয়ে শুরু অনেক শব্দ বোঝায় ‘যে কাজটি করে’। আর বহুবচনে শেষে আসে {{ـُونَ}} বা {{ـِينَ}}: {{الْمُؤْمِنُونَ}}, {{الْمُسْلِمِينَ}}।","en":"Notice: {{مُؤْمِن}}, {{مُسْلِم}}, {{مُحْسِن}}, {{مُشْرِك}}, {{مُنَافِق}} all start with {{مُـ}}. Many words starting with {{مُـ}} mean ‘one who does’ the action. Their plurals end in {{ـُونَ}} or {{ـِينَ}}: {{الْمُؤْمِنُونَ}}, {{الْمُسْلِمِينَ}}."},{"type":"vocab","title":{"bn":"পরিবার, সমাজ ও অদৃশ্য সৃষ্টি","en":"Family, society & unseen beings"},"items":[{"ar":"أَب","tr":{"bn":"আব","en":"ab"},"mean":{"bn":"বাবা, পিতা","en":"father"},"root":"أ ب و","example":{"ar":"وَأُمِّهِ وَأَبِيهِ","mean":{"bn":"আর তার মা ও তার বাবা (থেকে পালাবে)","en":"and (flee from) his mother and his father"},"ref":"80:35"}},{"ar":"أُمّ","tr":{"bn":"উম্ম","en":"umm"},"mean":{"bn":"মা, মাতা","en":"mother"},"root":"أ م م"},{"ar":"وَالِدَيْن","tr":{"bn":"ওয়ালিদাইন","en":"waalidayn"},"mean":{"bn":"বাবা-মা (দুজন)","en":"parents (both)"},"root":"و ل د","example":{"ar":"وَبِالْوَالِدَيْنِ إِحْسَانًا","mean":{"bn":"আর বাবা-মায়ের সাথে সদ্ব্যবহার করো","en":"and be good to parents"},"ref":"17:23"}},{"ar":"اِبْن","tr":{"bn":"ইবন","en":"ibn"},"mean":{"bn":"ছেলে, পুত্র","en":"son"},"root":"ب ن ي","example":{"ar":"وَإِذْ قَالَ عِيسَى ابْنُ مَرْيَمَ يَا بَنِي إِسْرَائِيلَ","mean":{"bn":"আর যখন মারইয়ামের ছেলে ঈসা বলল, হে বনি ইসরাইল","en":"And when Jesus, son of Mary, said, ‘O Children of Israel’"},"ref":"61:6"}},{"ar":"أَخ","tr":{"bn":"আখ","en":"akh"},"mean":{"bn":"ভাই","en":"brother"},"root":"أ خ و","example":{"ar":"يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ","mean":{"bn":"যেদিন মানুষ পালাবে তার ভাই থেকে","en":"the Day a man will flee from his brother"},"ref":"80:34"}},{"ar":"زَوْج","tr":{"bn":"যাওজ","en":"zawj"},"mean":{"bn":"স্বামী/স্ত্রী, জোড়া","en":"spouse, pair"},"root":"ز و ج","example":{"ar":"اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ","mean":{"bn":"তুমি ও তোমার স্ত্রী জান্নাতে বসবাস করো","en":"Dwell, you and your wife, in Paradise"},"ref":"2:35"}},{"ar":"وَلَد","tr":{"bn":"ওয়ালাদ","en":"walad"},"mean":{"bn":"সন্তান","en":"child, offspring"},"root":"و ل د","example":{"ar":"مَا اتَّخَذَ اللّٰهُ مِنْ وَلَدٍ","mean":{"bn":"আল্লাহ কোনো সন্তান গ্রহণ করেননি","en":"Allah has not taken any son"},"ref":"23:91"}},{"ar":"ذُرِّيَّة","tr":{"bn":"যুররিয়্যাহ","en":"dhurriyyah"},"mean":{"bn":"বংশধর, সন্তান-সন্ততি","en":"descendants, offspring"},"example":{"ar":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ","mean":{"bn":"হে আমাদের রব, আমাদের স্ত্রী ও সন্তানদের আমাদের চোখের শীতলতা বানিয়ে দাও","en":"Our Lord, grant us from our spouses and offspring comfort to our eyes"},"ref":"25:74"}},{"ar":"رَجُل","tr":{"bn":"রাজুল","en":"rajul"},"mean":{"bn":"পুরুষ, লোক","en":"man"},"root":"ر ج ل","example":{"ar":"وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَى","mean":{"bn":"আর নগরের দূরপ্রান্ত থেকে এক লোক ছুটে এল","en":"And a man came running from the far end of the city"},"ref":"36:20"}},{"ar":"اِمْرَأَة","tr":{"bn":"ইমরাআহ","en":"imra'ah"},"mean":{"bn":"নারী, স্ত্রী","en":"woman, wife"},"root":"م ر أ","example":{"ar":"إِنِّي وَجَدْتُ امْرَأَةً تَمْلِكُهُمْ","mean":{"bn":"আমি দেখলাম এক নারী তাদের উপর রাজত্ব করছে","en":"I found a woman ruling over them"},"ref":"27:23"}},{"ar":"عَبْد","tr":{"bn":"'আবদ","en":"'abd"},"mean":{"bn":"বান্দা, দাস","en":"servant, slave (of Allah)"},"root":"ع ب د","example":{"ar":"سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا","mean":{"bn":"পবিত্র তিনি, যিনি তাঁর বান্দাকে রাতে ভ্রমণ করিয়েছেন","en":"Exalted is He who took His servant by night"},"ref":"17:1"}},{"ar":"أَهْل","tr":{"bn":"আহল","en":"ahl"},"mean":{"bn":"পরিবার, অধিবাসী, অনুসারী","en":"family, people of"},"root":"أ ه ل","example":{"ar":"قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ","mean":{"bn":"বলো, হে কিতাবধারীরা, এসো এমন এক কথার দিকে যা আমাদের ও তোমাদের মধ্যে সমান","en":"Say, ‘O People of the Book, come to a word common between us and you’"},"ref":"3:64"}},{"ar":"صَاحِب","tr":{"bn":"সাহিব","en":"ṣaaḥib"},"mean":{"bn":"সাথী, সঙ্গী, অধিকারী","en":"companion, owner"},"root":"ص ح ب","example":{"ar":"مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى","mean":{"bn":"তোমাদের সাথী (রাসূল) পথভ্রষ্ট হননি, বিপথগামীও হননি","en":"Your companion has not strayed, nor has he erred"},"ref":"53:2"}},{"ar":"يَتِيم","tr":{"bn":"ইয়াতীম","en":"yateem"},"mean":{"bn":"এতিম","en":"orphan"},"root":"ي ت م","example":{"ar":"فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ","mean":{"bn":"সুতরাং এতিমের প্রতি কঠোর হয়ো না","en":"So as for the orphan, do not oppress him"},"ref":"93:9"}},{"ar":"مِسْكِين","tr":{"bn":"মিসকীন","en":"miskeen"},"mean":{"bn":"মিসকিন, অভাবী","en":"needy, poor person"},"root":"س ك ن","example":{"ar":"وَلَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ","mean":{"bn":"আর মিসকিনকে খাবার দিতে উৎসাহ দেয় না","en":"and does not encourage feeding the needy"},"ref":"107:3"}},{"ar":"مَلَك","tr":{"bn":"মালাক","en":"malak"},"mean":{"bn":"ফেরেশতা (বহুবচন {{مَلَائِكَة}})","en":"angel (plural {{مَلَائِكَة}})"},"root":"م ل ك","example":{"ar":"وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا","mean":{"bn":"আর তোমার রব আসবেন, আর ফেরেশতারা সারি সারি","en":"And your Lord comes, with the angels rank upon rank"},"ref":"89:22"}},{"ar":"شَيْطَان","tr":{"bn":"শাইত্বান","en":"shayṭaan"},"mean":{"bn":"শয়তান","en":"Satan, devil"},"root":"ش ط ن","example":{"ar":"إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا","mean":{"bn":"নিশ্চয়ই শয়তান তোমাদের শত্রু, তাই তাকে শত্রু হিসেবেই নাও","en":"Indeed, Satan is an enemy to you, so take him as an enemy"},"ref":"35:6"}},{"ar":"جِنّ","tr":{"bn":"জিন্ন","en":"jinn"},"mean":{"bn":"জিন","en":"jinn"},"root":"ج ن ن","example":{"ar":"وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ","mean":{"bn":"আমি জিন ও মানুষকে কেবল আমার ইবাদতের জন্যই সৃষ্টি করেছি","en":"I did not create jinn and mankind except to worship Me"},"ref":"51:56"}},{"ar":"نَفْس","tr":{"bn":"নাফস","en":"nafs"},"mean":{"bn":"প্রাণ, আত্মা, নিজ","en":"soul, self"},"root":"ن ف س","example":{"ar":"يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ","mean":{"bn":"হে প্রশান্ত আত্মা","en":"O tranquil soul"},"ref":"89:27"}}]},{"type":"tip","kind":"memory","bn":"বাংলায় এগুলো তো রোজকার শব্দ! **ইনসান, কওম, উম্মত, রাসূল, নবী, মুমিন, কাফের, মুনাফেক, জালিম, এতিম, মিসকিন, শয়তান, জিন, নফস**। আরও মজার: **সাহেব** এসেছে {{صَاحِب}} থেকে, **আওলাদ** (সন্তানাদি) হলো {{وَلَد}}-এর বহুবচন {{أَوْلَاد}}, আর ‘আব্দুল্লাহ’ মানে ‘আল্লাহর বান্দা’ ({{عَبْد}} + {{اللّٰه}})।","en":"These are everyday Bangla words! **insan, kowm, ummot, rasul, nobi, mumin, kafer, munafek, jalim, etim, miskin, shoytan, jin, nofs**. Even better: **saheb** comes from {{صَاحِب}}, **awlad** (children) is {{أَوْلَاد}}, the plural of {{وَلَد}}, and ‘Abdullah’ means ‘servant of Allah’ ({{عَبْد}} + {{اللّٰه}})."},{"type":"examples","title":{"bn":"কিয়ামতের দিন — পরিবারও আলাদা হয়ে যাবে","en":"On the Last Day — even families part"},"items":[{"ar":"يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ","tr":{"bn":"ইয়াওমা ইয়াফির্রুল মারউ মিন আখীহ","en":"yawma yafirrul-mar'u min akheeh"},"mean":{"bn":"যেদিন মানুষ পালাবে তার ভাই থেকে","en":"the Day a man will flee from his brother"},"note":{"bn":"৮০:৩৪","en":"80:34"},"hl":"أَخِيهِ"},{"ar":"وَأُمِّهِ وَأَبِيهِ","tr":{"bn":"ওয়া উম্মিহী ওয়া আবীহ","en":"wa ummihee wa abeeh"},"mean":{"bn":"আর তার মা ও বাবা থেকে","en":"and his mother and his father"},"note":{"bn":"৮০:৩৫","en":"80:35"},"hl":"أُمِّهِ"},{"ar":"وَصَاحِبَتِهِ وَبَنِيهِ","tr":{"bn":"ওয়া সাহিবাতিহী ওয়া বানীহ","en":"wa ṣaaḥibatihee wa baneeh"},"mean":{"bn":"আর তার স্ত্রী ও সন্তানদের থেকে","en":"and his wife and his children"},"note":{"bn":"৮০:৩৬ — {{صَاحِبَة}} এখানে ‘স্ত্রী’","en":"80:36 — {{صَاحِبَة}} here means ‘wife’"},"hl":"صَاحِبَتِهِ"}]},{"type":"quiz","items":[{"q":{"bn":"{{رَسُول}} মানে কী?","en":"What does {{رَسُول}} mean?"},"ar":"رَسُول","options":[{"bn":"রাসূল, বার্তাবাহক","en":"messenger"},{"bn":"ফেরেশতা","en":"angel"},{"bn":"জাতি","en":"nation"}],"answer":0},{"q":{"bn":"{{قَوْم}} শব্দের অর্থ —","en":"{{قَوْم}} means —"},"ar":"قَوْم","options":[{"bn":"ভাই","en":"brother"},{"bn":"জাতি, সম্প্রদায়","en":"people, nation"},{"bn":"এতিম","en":"orphan"}],"answer":1},{"q":{"bn":"‘মুনাফিক’ আরবিতে —","en":"‘Hypocrite’ in Arabic —"},"options":["مُؤْمِن","مُنَافِق","مُسْلِم","مُحْسِن"],"answer":1},{"q":{"bn":"{{أُمّ}} মানে —","en":"{{أُمّ}} means —"},"ar":"أُمّ","options":[{"bn":"বাবা","en":"father"},{"bn":"মা","en":"mother"},{"bn":"ভাই","en":"brother"}],"answer":1},{"q":{"bn":"{{إِنَّ اللّٰهَ يُحِبُّ الْمُحْسِنِينَ}} — আল্লাহ কাদের ভালোবাসেন?","en":"{{إِنَّ اللّٰهَ يُحِبُّ الْمُحْسِنِينَ}} — whom does Allah love?"},"options":[{"bn":"সৎকর্মশীলদের","en":"those who do good"},{"bn":"ধনীদের","en":"the rich"},{"bn":"জালিমদের","en":"wrongdoers"}],"answer":0},{"q":{"bn":"বাংলা ‘সাহেব’ শব্দটি কোন আরবি শব্দ থেকে?","en":"Bangla ‘saheb’ comes from which Arabic word?"},"options":["صَاحِب","صَابِر","صَالِح"],"answer":0},{"q":{"bn":"{{نَفْس}} শব্দের অর্থ —","en":"{{نَفْس}} means —"},"ar":"نَفْس","options":[{"bn":"প্রাণ, আত্মা","en":"soul, self"},{"bn":"মানুষ (সকল)","en":"mankind"},{"bn":"নারী","en":"woman"}],"answer":0},{"q":{"bn":"{{مُـ}} দিয়ে শুরু {{مُؤْمِن}}, {{مُسْلِم}} — সাধারণত কী বোঝায়?","en":"Words like {{مُؤْمِن}}, {{مُسْلِم}} starting with {{مُـ}} usually mean —"},"options":[{"bn":"যে কাজটি করে (কর্তা)","en":"the one who does it (doer)"},{"bn":"জায়গার নাম","en":"a place name"},{"bn":"অতীত কাল","en":"past tense"}],"answer":0}]}]},{"id":"vocab-verbs","icon":"فعل","title":{"bn":"বারবার আসা ক্রিয়া","en":"Frequent Verbs"},"subtitle":{"bn":"করল, বানাল, ঈমান আনল, দেখল — কুরআনের ‘কাজের শব্দ’","en":"Did, made, believed, saw — the Quran's ‘action words’"},"minutes":22,"goals":[{"bn":"কুরআনের সবচেয়ে প্রচলিত ৩৮টি ক্রিয়া অতীত কালে (মূল রূপে) শিখব","en":"Learn 38 of the most common Quranic verbs in their past (base) form"},{"bn":"অতীত ও বর্তমান কালের রূপ মিলিয়ে চিনব","en":"Match past and present-tense forms"},{"bn":"{{ـُوا}}, {{ـنَا}}, {{نَـ}}, {{يَـ}} — কে কাজটি করছে তা ধরতে শিখব","en":"Use {{ـُوا}}, {{ـنَا}}, {{نَـ}}, {{يَـ}} to see who is doing the action"}],"blocks":[{"type":"text","bn":"আরবি অভিধানে ক্রিয়া সাধারণত লেখা হয় **অতীত কালের ‘সে’ রূপে** — যেমন {{خَلَقَ}} ‘সে সৃষ্টি করল’। এটাই ক্রিয়ার মূল রূপ, এতে সাধারণত তিনটি মূল অক্ষরই থাকে। তুমি {{قَالَ}} (সে বলল) আর {{سَمِعَ}} (সে শুনল) আগেই শিখেছ। এবার আরও অনেক!","en":"Arabic dictionaries list verbs in the **past tense ‘he’ form** — e.g. {{خَلَقَ}} ‘he created’. This is the verb's base form and usually shows all three root letters. You already know {{قَالَ}} (he said) and {{سَمِعَ}} (he heard). Now for many more!"},{"type":"vocab","title":{"bn":"সবচেয়ে প্রয়োজনীয় ক্রিয়া","en":"Essential verbs"},"items":[{"ar":"كَانَ","tr":{"bn":"কানা","en":"kaana"},"mean":{"bn":"সে ছিল, হলো","en":"he was, became"},"root":"ك و ن","example":{"ar":"إِنَّهُ كَانَ تَوَّابًا","mean":{"bn":"নিশ্চয়ই তিনি তাওবা কবুলকারী","en":"Indeed, He is ever accepting of repentance"},"ref":"110:3"}},{"ar":"آمَنَ","tr":{"bn":"আমানা","en":"aamana"},"mean":{"bn":"সে ঈমান আনল, বিশ্বাস করল","en":"he believed"},"root":"أ م ن","example":{"ar":"آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ","mean":{"bn":"রাসূল ঈমান এনেছেন তাঁর রবের পক্ষ থেকে তাঁর প্রতি যা নাজিল হয়েছে তাতে","en":"The Messenger believed in what was revealed to him from his Lord"},"ref":"2:285"}},{"ar":"عَمِلَ","tr":{"bn":"'আমিলা","en":"'amila"},"mean":{"bn":"সে কাজ করল, আমল করল","en":"he did, worked"},"root":"ع م ل","example":{"ar":"وَقُلِ اعْمَلُوا فَسَيَرَى اللّٰهُ عَمَلَكُمْ","mean":{"bn":"আর বলো, তোমরা কাজ করো, আল্লাহ তোমাদের কাজ দেখবেন","en":"And say, ‘Work, for Allah will see your deeds’"},"ref":"9:105"}},{"ar":"جَعَلَ","tr":{"bn":"জা'আলা","en":"ja'ala"},"mean":{"bn":"সে বানাল, করল, স্থাপন করল","en":"he made, placed"},"root":"ج ع ل","example":{"ar":"فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ","mean":{"bn":"তারপর তিনি তাদের বানালেন চিবানো ভুসির মতো","en":"and He made them like eaten straw"},"ref":"105:5"}},{"ar":"عَلِمَ","tr":{"bn":"'আলিমা","en":"'alima"},"mean":{"bn":"সে জানল","en":"he knew"},"root":"ع ل م","example":{"ar":"أَلَمْ يَعْلَمْ بِأَنَّ اللّٰهَ يَرَى","mean":{"bn":"সে কি জানে না যে আল্লাহ দেখছেন?","en":"Does he not know that Allah sees?"},"ref":"96:14"}},{"ar":"خَلَقَ","tr":{"bn":"খালাক্বা","en":"khalaqa"},"mean":{"bn":"সে সৃষ্টি করল","en":"he created"},"root":"خ ل ق","example":{"ar":"خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ","mean":{"bn":"তিনি মানুষকে সৃষ্টি করেছেন জমাট রক্তপিণ্ড থেকে","en":"He created man from a clinging clot"},"ref":"96:2"}},{"ar":"أَنْزَلَ","tr":{"bn":"আনযালা","en":"anzala"},"mean":{"bn":"সে নাজিল করল, নামাল","en":"he sent down, revealed"},"root":"ن ز ل","example":{"ar":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ","mean":{"bn":"নিশ্চয়ই আমি এটি নাজিল করেছি কদরের রাতে","en":"Indeed, We sent it down on the Night of Decree"},"ref":"97:1"}},{"ar":"هَدَى","tr":{"bn":"হাদা","en":"hadaa"},"mean":{"bn":"সে পথ দেখাল, হিদায়াত দিল","en":"he guided"},"root":"ه د ي","example":{"ar":"وَوَجَدَكَ ضَالًّا فَهَدَى","mean":{"bn":"আর তিনি তোমাকে পেয়েছেন পথ না-জানা অবস্থায়, তারপর পথ দেখিয়েছেন","en":"And He found you lost and guided you"},"ref":"93:7"}},{"ar":"كَفَرَ","tr":{"bn":"কাফারা","en":"kafara"},"mean":{"bn":"সে অস্বীকার করল, কুফরি করল; অকৃতজ্ঞ হলো","en":"he disbelieved; was ungrateful"},"root":"ك ف ر","example":{"ar":"إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ","mean":{"bn":"নিশ্চয়ই যারা কুফরি করেছে, তাদের জন্য সমান","en":"Indeed, those who disbelieve — it is all the same to them"},"ref":"2:6"}},{"ar":"رَأَى","tr":{"bn":"রাআ","en":"ra'aa"},"mean":{"bn":"সে দেখল","en":"he saw"},"root":"ر أ ي","example":{"ar":"أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ","mean":{"bn":"তুমি কি দেখেছ তাকে, যে প্রতিদান দিবসকে মিথ্যা বলে?","en":"Have you seen the one who denies the Recompense?"},"ref":"107:1"}},{"ar":"جَاءَ","tr":{"bn":"জাআ","en":"jaa'a"},"mean":{"bn":"সে এল","en":"he came"},"root":"ج ي أ","example":{"ar":"وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ","mean":{"bn":"আর বলো, সত্য এসেছে আর মিথ্যা বিলুপ্ত হয়েছে","en":"And say, ‘Truth has come and falsehood has vanished’"},"ref":"17:81"}},{"ar":"أَتَى","tr":{"bn":"আতা","en":"ataa"},"mean":{"bn":"সে এল, নিয়ে এল","en":"he came, brought"},"root":"أ ت ي","example":{"ar":"أَتَى أَمْرُ اللّٰهِ فَلَا تَسْتَعْجِلُوهُ","mean":{"bn":"আল্লাহর আদেশ এসে গেছে, তাই তা নিয়ে তাড়াহুড়া কোরো না","en":"The command of Allah has come, so do not hasten it"},"ref":"16:1"}},{"ar":"عَبَدَ","tr":{"bn":"'আবাদা","en":"'abada"},"mean":{"bn":"সে ইবাদত করল","en":"he worshipped"},"root":"ع ب د","example":{"ar":"لَا أَعْبُدُ مَا تَعْبُدُونَ","mean":{"bn":"তোমরা যার ইবাদত করো, আমি তার ইবাদত করি না","en":"I do not worship what you worship"},"ref":"109:2"}},{"ar":"أَرْسَلَ","tr":{"bn":"আরসালা","en":"arsala"},"mean":{"bn":"সে পাঠাল","en":"he sent"},"root":"ر س ل","example":{"ar":"هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ","mean":{"bn":"তিনিই তাঁর রাসূলকে পাঠিয়েছেন হিদায়াত ও সত্য দ্বীনসহ","en":"It is He who sent His Messenger with guidance and the religion of truth"},"ref":"61:9"}},{"ar":"ذَكَرَ","tr":{"bn":"যাকারা","en":"dhakara"},"mean":{"bn":"সে স্মরণ করল, উল্লেখ করল","en":"he remembered, mentioned"},"root":"ذ ك ر","example":{"ar":"فَاذْكُرُونِي أَذْكُرْكُمْ","mean":{"bn":"সুতরাং তোমরা আমাকে স্মরণ করো, আমিও তোমাদের স্মরণ করব","en":"So remember Me; I will remember you"},"ref":"2:152"}},{"ar":"دَعَا","tr":{"bn":"দা'আ","en":"da'aa"},"mean":{"bn":"সে ডাকল, দোয়া করল","en":"he called, prayed (supplicated)"},"root":"د ع و","example":{"ar":"وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ","mean":{"bn":"আর তোমাদের রব বলেন, আমাকে ডাকো, আমি তোমাদের ডাকে সাড়া দেব","en":"And your Lord says, ‘Call upon Me; I will respond to you’"},"ref":"40:60"}},{"ar":"شَاءَ","tr":{"bn":"শাআ","en":"shaa'a"},"mean":{"bn":"সে চাইল, ইচ্ছা করল","en":"he willed"},"root":"ش ي أ","example":{"ar":"سَتَجِدُنِي إِنْ شَاءَ اللّٰهُ صَابِرًا","mean":{"bn":"আল্লাহ চাইলে তুমি আমাকে ধৈর্যশীল পাবে","en":"You will find me, if Allah wills, patient"},"ref":"18:69"}},{"ar":"أَرَادَ","tr":{"bn":"আরাদা","en":"araada"},"mean":{"bn":"সে ইচ্ছা করল, চাইল","en":"he wanted, intended"},"root":"ر و د","example":{"ar":"إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ","mean":{"bn":"তাঁর ব্যাপার তো এই যে, তিনি কোনো কিছু চাইলে বলেন ‘হও’, আর তা হয়ে যায়","en":"His command, when He wills a thing, is only to say to it ‘Be’, and it is"},"ref":"36:82"}}]},{"type":"tip","kind":"memory","bn":"চেনা শব্দ দিয়ে মনে রাখো: **আমল** ← {{عَمِلَ}}, **ইলম, মালুম** ← {{عَلِمَ}}, **মাখলুক** ← {{خَلَقَ}}, **নাজিল** ← {{أَنْزَلَ}}, **হেদায়েত** ← {{هَدَى}}, **কুফর** ← {{كَفَرَ}}, আদালতের **রায়** ← {{رَأَى}}-এর মূল ر أ ي, **ইবাদত** ← {{عَبَدَ}}, **রাসূল** ← {{أَرْسَلَ}}, **জিকির** ← {{ذَكَرَ}}, **দোয়া, দাওয়াত** ← {{دَعَا}}, **ইনশাআল্লাহ, মাশাআল্লাহ** ← {{شَاءَ}}, **এরাদা** (ইচ্ছা) ← {{أَرَادَ}}।","en":"Anchor them with familiar words: **amol** ← {{عَمِلَ}}, **ilm, malum** ← {{عَلِمَ}}, **makhluk** ← {{خَلَقَ}}, **najil** ← {{أَنْزَلَ}}, **hedayet** ← {{هَدَى}}, **kufr** ← {{كَفَرَ}}, a court's **ray** (verdict) ← root ر أ ي of {{رَأَى}}, **ibadat** ← {{عَبَدَ}}, **rasul** ← {{أَرْسَلَ}}, **jikir** ← {{ذَكَرَ}}, **doa, dawat** ← {{دَعَا}}, **insha'Allah, masha'Allah** ← {{شَاءَ}}, **erada** (intention) ← {{أَرَادَ}}."},{"type":"vocab","title":{"bn":"আরও প্রচলিত ক্রিয়া","en":"More common verbs"},"items":[{"ar":"كَذَّبَ","tr":{"bn":"কায্যাবা","en":"kadhdhaba"},"mean":{"bn":"সে মিথ্যা বলে প্রত্যাখ্যান করল","en":"he denied, called a lie"},"root":"ك ذ ب","example":{"ar":"فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ","mean":{"bn":"সুতরাং তোমরা দুজন তোমাদের রবের কোন কোন নিয়ামত অস্বীকার করবে?","en":"So which of the favours of your Lord would you both deny?"},"ref":"55:13"}},{"ar":"اتَّقَى","tr":{"bn":"ইত্তাক্বা","en":"ittaqaa"},"mean":{"bn":"সে তাকওয়া অবলম্বন করল, আল্লাহকে ভয় করল","en":"he feared Allah, was God-conscious"},"root":"و ق ي","example":{"ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللّٰهَ حَقَّ تُقَاتِهِ","mean":{"bn":"হে মুমিনগণ, আল্লাহকে যথাযথভাবে ভয় করো","en":"O you who believe, fear Allah as He should be feared"},"ref":"3:102"}},{"ar":"أَطَاعَ","tr":{"bn":"আত্বা'আ","en":"aṭaa'a"},"mean":{"bn":"সে আনুগত্য করল","en":"he obeyed"},"root":"ط و ع","example":{"ar":"أَطِيعُوا اللّٰهَ وَأَطِيعُوا الرَّسُولَ","mean":{"bn":"আল্লাহর আনুগত্য করো এবং রাসূলের আনুগত্য করো","en":"Obey Allah and obey the Messenger"},"ref":"4:59"}},{"ar":"تَابَ","tr":{"bn":"তাবা","en":"taaba"},"mean":{"bn":"সে তাওবা করল, ফিরে এল","en":"he repented, turned back"},"root":"ت و ب","example":{"ar":"إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا","mean":{"bn":"তবে সে নয়, যে তাওবা করে, ঈমান আনে ও সৎকাজ করে","en":"except one who repents, believes and does righteous work"},"ref":"25:70"}},{"ar":"غَفَرَ","tr":{"bn":"গাফারা","en":"ghafara"},"mean":{"bn":"সে ক্ষমা করল","en":"he forgave"},"root":"غ ف ر","example":{"ar":"رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ","mean":{"bn":"হে আমাদের রব, যেদিন হিসাব হবে, সেদিন আমাকে, আমার বাবা-মাকে ও মুমিনদের ক্ষমা করো","en":"Our Lord, forgive me, my parents and the believers on the Day the reckoning is held"},"ref":"14:41"}},{"ar":"رَزَقَ","tr":{"bn":"রাযাক্বা","en":"razaqa"},"mean":{"bn":"সে রিজিক দিল","en":"he provided"},"root":"ر ز ق","example":{"ar":"وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ","mean":{"bn":"আর আমি তাদের যা রিজিক দিয়েছি তা থেকে তারা খরচ করে","en":"and spend from what We have provided them"},"ref":"2:3"}},{"ar":"أَخَذَ","tr":{"bn":"আখাযা","en":"akhadha"},"mean":{"bn":"সে নিল, ধরল","en":"he took, seized"},"root":"أ خ ذ","example":{"ar":"لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ","mean":{"bn":"তাঁকে তন্দ্রাও স্পর্শ করে না, ঘুমও না","en":"Neither drowsiness nor sleep overtakes Him"},"ref":"2:255"}},{"ar":"أَكَلَ","tr":{"bn":"আকালা","en":"akala"},"mean":{"bn":"সে খেল","en":"he ate"},"root":"أ ك ل","example":{"ar":"وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا","mean":{"bn":"আর খাও ও পান করো, কিন্তু অপচয় কোরো না","en":"and eat and drink, but do not be excessive"},"ref":"7:31"}},{"ar":"ظَلَمَ","tr":{"bn":"যালামা","en":"ẓalama"},"mean":{"bn":"সে জুলুম করল, অন্যায় করল","en":"he wronged, did injustice"},"root":"ظ ل م","example":{"ar":"رَبَّنَا ظَلَمْنَا أَنْفُسَنَا","mean":{"bn":"হে আমাদের রব, আমরা নিজেদের উপর জুলুম করেছি","en":"Our Lord, we have wronged ourselves"},"ref":"7:23"}},{"ar":"نَصَرَ","tr":{"bn":"নাসারা","en":"naṣara"},"mean":{"bn":"সে সাহায্য করল","en":"he helped, gave victory"},"root":"ن ص ر","example":{"ar":"إِنْ تَنْصُرُوا اللّٰهَ يَنْصُرْكُمْ","mean":{"bn":"যদি তোমরা আল্লাহকে (তাঁর দ্বীনকে) সাহায্য করো, তিনি তোমাদের সাহায্য করবেন","en":"If you support Allah, He will support you"},"ref":"47:7"}},{"ar":"وَجَدَ","tr":{"bn":"ওয়াজাদা","en":"wajada"},"mean":{"bn":"সে পেল","en":"he found"},"root":"و ج د","example":{"ar":"أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى","mean":{"bn":"তিনি কি তোমাকে এতিম পাননি, তারপর আশ্রয় দেননি?","en":"Did He not find you an orphan and give you shelter?"},"ref":"93:6"}},{"ar":"دَخَلَ","tr":{"bn":"দাখালা","en":"dakhala"},"mean":{"bn":"সে প্রবেশ করল","en":"he entered"},"root":"د خ ل","example":{"ar":"فَادْخُلِي فِي عِبَادِي","mean":{"bn":"অতএব আমার বান্দাদের মধ্যে প্রবেশ করো","en":"So enter among My servants"},"ref":"89:29"}},{"ar":"رَجَعَ","tr":{"bn":"রাজা'আ","en":"raja'a"},"mean":{"bn":"সে ফিরে গেল","en":"he returned"},"root":"ر ج ع","example":{"ar":"ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً","mean":{"bn":"ফিরে চলো তোমার রবের দিকে, সন্তুষ্ট ও সন্তোষভাজন হয়ে","en":"Return to your Lord, well-pleased and pleasing"},"ref":"89:28"}},{"ar":"صَبَرَ","tr":{"bn":"সাবারা","en":"ṣabara"},"mean":{"bn":"সে ধৈর্য ধরল","en":"he was patient"},"root":"ص ب ر","example":{"ar":"وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللّٰهِ","mean":{"bn":"আর ধৈর্য ধরো; তোমার ধৈর্য তো আল্লাহরই সাহায্যে","en":"And be patient; your patience is only by Allah"},"ref":"16:127"}},{"ar":"شَكَرَ","tr":{"bn":"শাকারা","en":"shakara"},"mean":{"bn":"সে কৃতজ্ঞতা জানাল, শোকর করল","en":"he thanked, was grateful"},"root":"ش ك ر","example":{"ar":"وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ","mean":{"bn":"আর আমার প্রতি কৃতজ্ঞ হও, অকৃতজ্ঞ হয়ো না","en":"and be grateful to Me and do not be ungrateful"},"ref":"2:152"}},{"ar":"أَحَبَّ","tr":{"bn":"আহাব্বা","en":"aḥabba"},"mean":{"bn":"সে ভালোবাসল","en":"he loved"},"root":"ح ب ب","example":{"ar":"قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللّٰهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّٰهُ","mean":{"bn":"বলো, যদি তোমরা আল্লাহকে ভালোবাসো, তবে আমার অনুসরণ করো, আল্লাহ তোমাদের ভালোবাসবেন","en":"Say, ‘If you love Allah, follow me; Allah will love you’"},"ref":"3:31"}},{"ar":"أَمَرَ","tr":{"bn":"আমারা","en":"amara"},"mean":{"bn":"সে আদেশ করল","en":"he commanded"},"root":"أ م ر","example":{"ar":"إِنَّ اللّٰهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ","mean":{"bn":"নিশ্চয়ই আল্লাহ ন্যায়বিচার ও সদাচরণের আদেশ দেন","en":"Indeed, Allah commands justice and excellence"},"ref":"16:90"}},{"ar":"قَرَأَ","tr":{"bn":"ক্বারাআ","en":"qara'a"},"mean":{"bn":"সে পড়ল, তিলাওয়াত করল","en":"he read, recited"},"root":"ق ر أ","example":{"ar":"فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","mean":{"bn":"যখন তুমি কুরআন পড়বে, তখন বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাও","en":"When you recite the Quran, seek refuge with Allah from Satan, the outcast"},"ref":"16:98"}},{"ar":"سَأَلَ","tr":{"bn":"সাআলা","en":"sa'ala"},"mean":{"bn":"সে জিজ্ঞেস করল, চাইল","en":"he asked"},"root":"س أ ل","example":{"ar":"وَيَسْأَلُونَكَ عَنِ الرُّوحِ","mean":{"bn":"আর তারা তোমাকে রূহ সম্পর্কে জিজ্ঞেস করে","en":"And they ask you about the soul"},"ref":"17:85"}},{"ar":"فَعَلَ","tr":{"bn":"ফা'আলা","en":"fa'ala"},"mean":{"bn":"সে করল","en":"he did"},"root":"ف ع ل","example":{"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","mean":{"bn":"তুমি কি দেখোনি, তোমার রব আদ জাতির সাথে কী করেছিলেন?","en":"Have you not seen how your Lord dealt with ‘Aad?"},"ref":"89:6"}}]},{"type":"table","title":{"bn":"অতীত ও বর্তমান কাল — জোড়ায় শেখো","en":"Past and present — learn them in pairs"},"head":[{"bn":"অতীত (সে করল)","en":"Past (he did)"},{"bn":"বর্তমান (সে করে)","en":"Present (he does)"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["قَالَ","يَقُولُ",{"bn":"বলা","en":"say"}],["كَانَ","يَكُونُ",{"bn":"হওয়া, থাকা","en":"be"}],["عَلِمَ","يَعْلَمُ",{"bn":"জানা","en":"know"}],["عَمِلَ","يَعْمَلُ",{"bn":"কাজ করা","en":"do, work"}],["جَعَلَ","يَجْعَلُ",{"bn":"বানানো","en":"make"}],["خَلَقَ","يَخْلُقُ",{"bn":"সৃষ্টি করা","en":"create"}],["آمَنَ","يُؤْمِنُ",{"bn":"ঈমান আনা","en":"believe"}],["كَفَرَ","يَكْفُرُ",{"bn":"অস্বীকার করা","en":"disbelieve"}],["هَدَى","يَهْدِي",{"bn":"পথ দেখানো","en":"guide"}],["رَأَى","يَرَى",{"bn":"দেখা","en":"see"}],["عَبَدَ","يَعْبُدُ",{"bn":"ইবাদত করা","en":"worship"}],["ذَكَرَ","يَذْكُرُ",{"bn":"স্মরণ করা","en":"remember"}],["غَفَرَ","يَغْفِرُ",{"bn":"ক্ষমা করা","en":"forgive"}],["شَاءَ","يَشَاءُ",{"bn":"চাওয়া","en":"will"}]]},{"type":"tip","kind":"tip","bn":"**কে করল?** অতীত কালে শেষের অংশ দেখো: {{آمَنُوا}} (তারা ঈমান আনল, {{ـُوا}}), {{ظَلَمْنَا}} (আমরা জুলুম করলাম, {{ـنَا}}), {{أَنْعَمْتَ}} (তুমি অনুগ্রহ করলে, {{ـتَ}})। বর্তমান কালে শুরুর অক্ষর দেখো: {{يَعْلَمُ}} (সে জানে, {{يَـ}}), {{نَعْبُدُ}} (আমরা ইবাদত করি, {{نَـ}}), {{أَعْبُدُ}} (আমি ইবাদত করি, {{أَ}}), {{تَعْبُدُونَ}} (তোমরা ইবাদত করো, {{تَـ}})।","en":"**Who did it?** In the past tense, look at the ending: {{آمَنُوا}} (they believed, {{ـُوا}}), {{ظَلَمْنَا}} (we wronged, {{ـنَا}}), {{أَنْعَمْتَ}} (you blessed, {{ـتَ}}). In the present tense, look at the first letter: {{يَعْلَمُ}} (he knows, {{يَـ}}), {{نَعْبُدُ}} (we worship, {{نَـ}}), {{أَعْبُدُ}} (I worship, {{أَ}}), {{تَعْبُدُونَ}} (you all worship, {{تَـ}})."},{"type":"tip","kind":"memory","bn":"আরও চেনা শব্দ: **তওবা** ← {{تَابَ}}, **মাগফিরাত** ← {{غَفَرَ}}, **রিজিক** ← {{رَزَقَ}}, **জুলুম** ← {{ظَلَمَ}}, **নুসরাত** (নাম) ← {{نَصَرَ}}, ‘দরখাস্ত **দাখিল**’ ← {{دَخَلَ}}, ‘মামলা **রুজু**’ ← {{رَجَعَ}}, **সবর** ← {{صَبَرَ}}, **শোকর, শুকরিয়া** ← {{شَكَرَ}}, **মুহাব্বত** ← {{أَحَبَّ}}, **আমির** (নেতা) ← {{أَمَرَ}}, **কেরাত, কারী** ← {{قَرَأَ}}, **সওয়াল**-জবাব ← {{سَأَلَ}}।","en":"More familiar words: **towba** ← {{تَابَ}}, **magfirat** ← {{غَفَرَ}}, **rizik** ← {{رَزَقَ}}, **julum** ← {{ظَلَمَ}}, **Nusrat** (a name) ← {{نَصَرَ}}, ‘**dakhil** an application’ ← {{دَخَلَ}}, ‘**ruju** a case’ ← {{رَجَعَ}}, **sobor** ← {{صَبَرَ}}, **shokor, shukriya** ← {{شَكَرَ}}, **muhabbat** ← {{أَحَبَّ}}, **amir** (leader) ← {{أَمَرَ}}, **kerat, qari** ← {{قَرَأَ}}, **sowal**-jowab ← {{سَأَلَ}}."},{"type":"examples","title":{"bn":"ক্রিয়া চিনে আয়াত বুঝি","en":"Spot the verbs, understand the verse"},"items":[{"ar":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ","tr":{"bn":"ইল্লাল্লাযীনা আমানূ ওয়া 'আমিলুস সালিহাত","en":"illalladheena aamanoo wa 'amiluṣ-ṣaaliḥaat"},"mean":{"bn":"তারা ছাড়া, যারা ঈমান এনেছে ও সৎকাজ করেছে","en":"except those who believe and do righteous deeds"},"note":{"bn":"১০৩:৩ — কুরআনে এই জুটি ({{آمَنُوا وَعَمِلُوا}}) বহুবার এসেছে","en":"103:3 — this pair ({{آمَنُوا وَعَمِلُوا}}) appears many times"},"hl":"آمَنُوا"},{"ar":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ","tr":{"bn":"ইন্না আনযালনাহু ফী লাইলাতিল ক্বাদর","en":"innaa anzalnaahu fee laylatil-qadr"},"mean":{"bn":"নিশ্চয়ই আমি এটি নাজিল করেছি কদরের রাতে","en":"Indeed, We sent it down on the Night of Decree"},"note":{"bn":"৯৭:১ — {{أَنْزَلْنَا}} = {{أَنْزَلَ}} + {{ـنَا}} (আমরা)","en":"97:1 — {{أَنْزَلْنَا}} = {{أَنْزَلَ}} + {{ـنَا}} (We)"},"hl":"أَنْزَلْنَاهُ"},{"ar":"فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ","tr":{"bn":"ফাযকুরূনী আযকুরকুম ওয়াশকুরূ লী ওয়ালা তাকফুরূন","en":"fadhkuroonee adhkurkum washkuroo lee wa laa takfuroon"},"mean":{"bn":"সুতরাং আমাকে স্মরণ করো, আমি তোমাদের স্মরণ করব; আমার প্রতি কৃতজ্ঞ হও, অকৃতজ্ঞ হয়ো না","en":"So remember Me; I will remember you. Be grateful to Me and do not be ungrateful"},"note":{"bn":"২:১৫২ — তিনটি ক্রিয়া: ذ ك ر, ش ك ر, ك ف ر","en":"2:152 — three verbs: ذ ك ر, ش ك ر, ك ف ر"},"hl":"فَاذْكُرُونِي"}]},{"type":"quiz","items":[{"q":{"bn":"{{خَلَقَ}} মানে কী?","en":"What does {{خَلَقَ}} mean?"},"ar":"خَلَقَ","options":[{"bn":"সে সৃষ্টি করল","en":"he created"},{"bn":"সে দেখল","en":"he saw"},{"bn":"সে খেল","en":"he ate"}],"answer":0},{"q":{"bn":"{{جَعَلَ}} শব্দের অর্থ —","en":"{{جَعَلَ}} means —"},"ar":"جَعَلَ","options":[{"bn":"সে এল","en":"he came"},{"bn":"সে বানাল","en":"he made"},{"bn":"সে জানল","en":"he knew"}],"answer":1},{"q":{"bn":"‘সে এল’ — কোন ক্রিয়া?","en":"Which verb means ‘he came’?"},"options":["جَاءَ","شَاءَ","رَأَى","دَعَا"],"answer":0},{"q":{"bn":"{{آمَنُوا}} — কারা কাজটি করল?","en":"{{آمَنُوا}} — who did the action?"},"ar":"آمَنُوا","options":[{"bn":"সে (একজন)","en":"he"},{"bn":"তারা","en":"they"},{"bn":"আমি","en":"I"}],"answer":1,"explain":{"bn":"শেষে {{ـُوا}} মানে ‘তারা’: ‘তারা ঈমান আনল’।","en":"The ending {{ـُوا}} means ‘they’: ‘they believed’."}},{"q":{"bn":"{{يَعْلَمُ}} কোন ক্রিয়ার বর্তমান রূপ?","en":"{{يَعْلَمُ}} is the present form of which verb?"},"options":["عَلِمَ","عَمِلَ","جَعَلَ"],"answer":0},{"q":{"bn":"{{غَفَرَ}} মানে —","en":"{{غَفَرَ}} means —"},"ar":"غَفَرَ","options":[{"bn":"সে ক্ষমা করল","en":"he forgave"},{"bn":"সে অস্বীকার করল","en":"he disbelieved"},{"bn":"সে সাহায্য করল","en":"he helped"}],"answer":0},{"q":{"bn":"‘ইনশাআল্লাহ’-তে কোন ক্রিয়া লুকিয়ে আছে?","en":"Which verb hides inside ‘insha'Allah’?"},"options":["شَاءَ","جَاءَ","سَأَلَ"],"answer":0,"explain":{"bn":"{{إِنْ شَاءَ اللّٰهُ}} = যদি আল্লাহ চান।","en":"{{إِنْ شَاءَ اللّٰهُ}} = if Allah wills."}},{"q":{"bn":"{{نَعْبُدُ}} — শুরুর {{نَـ}} কী বোঝায়?","en":"In {{نَعْبُدُ}}, what does the opening {{نَـ}} show?"},"options":[{"bn":"আমরা","en":"we"},{"bn":"তারা","en":"they"},{"bn":"সে","en":"he"}],"answer":0},{"q":{"bn":"{{أَنْزَلَ}} মানে কী?","en":"What does {{أَنْزَلَ}} mean?"},"ar":"أَنْزَلَ","options":[{"bn":"সে পাঠাল (রাসূল)","en":"he sent (a messenger)"},{"bn":"সে নাজিল করল","en":"he sent down, revealed"},{"bn":"সে প্রবেশ করল","en":"he entered"}],"answer":1}]}]},{"id":"vocab-hereafter","icon":"ج","title":{"bn":"ঈমান, ইবাদত ও আখিরাত","en":"Belief, Worship & the Hereafter"},"subtitle":{"bn":"জান্নাত, জাহান্নাম, রহমত, সালাত — কুরআনের মূল বার্তার শব্দ","en":"Paradise, Fire, mercy, prayer — the words of the Quran's core message"},"minutes":20,"goals":[{"bn":"ঈমান ও ইবাদতের মূল শব্দগুলো শিখব","en":"Learn the key words of faith and worship"},{"bn":"আখিরাত, প্রতিদান ও শাস্তির শব্দ চিনব","en":"Recognise words about the Hereafter, reward and punishment"},{"bn":"কুরআনের ‘জোড়া শব্দ’ (বিপরীত শব্দ) দিয়ে মনে রাখার কৌশল জানব","en":"Use the Quran's opposite-pairs as a memory tool"}],"blocks":[{"type":"text","bn":"কুরআনের মূল বার্তা তিনটি বড় বিষয় ঘিরে: আল্লাহর একত্ব, রাসূলের প্রতি ঈমান, আর আখিরাত। এই পাঠের শব্দগুলো সেই বার্তার ভাষা। মজার ব্যাপার, এগুলোর অনেকগুলো তুমি বাংলায় আগে থেকেই ব্যবহার করো!","en":"The Quran's core message centres on three big themes: the Oneness of Allah, belief in the Messenger, and the Hereafter. The words in this lesson are the language of that message — and you already use many of them in Bangla!"},{"type":"vocab","title":{"bn":"ঈমান ও ইবাদত","en":"Faith & worship"},"items":[{"ar":"إِيمَان","tr":{"bn":"ঈমান","en":"eemaan"},"mean":{"bn":"ঈমান, বিশ্বাস","en":"faith, belief"},"root":"أ م ن","example":{"ar":"وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ","mean":{"bn":"আর ঈমান এখনো তোমাদের অন্তরে প্রবেশ করেনি","en":"and faith has not yet entered your hearts"},"ref":"49:14"}},{"ar":"إِسْلَام","tr":{"bn":"ইসলাম","en":"islaam"},"mean":{"bn":"ইসলাম, আল্লাহর কাছে আত্মসমর্পণ","en":"Islam, submission to Allah"},"root":"س ل م","example":{"ar":"وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ","mean":{"bn":"আর যে ইসলাম ছাড়া অন্য কোনো দ্বীন চায়, তার থেকে তা কখনো গ্রহণ করা হবে না","en":"Whoever seeks a religion other than Islam, it will never be accepted from him"},"ref":"3:85"}},{"ar":"تَقْوَى","tr":{"bn":"তাক্বওয়া","en":"taqwaa"},"mean":{"bn":"তাকওয়া, আল্লাহভীতি","en":"God-consciousness, piety"},"root":"و ق ي","example":{"ar":"وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى","mean":{"bn":"আর পাথেয় সংগ্রহ করো; নিশ্চয়ই সবচেয়ে উত্তম পাথেয় হলো তাকওয়া","en":"And take provisions; the best provision is God-consciousness"},"ref":"2:197"}},{"ar":"قُرْآن","tr":{"bn":"ক্বুরআন","en":"qur'aan"},"mean":{"bn":"কুরআন; যা পাঠ করা হয়","en":"the Quran; that which is recited"},"root":"ق ر أ","example":{"ar":"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ","mean":{"bn":"রমজান মাস, যাতে কুরআন নাজিল হয়েছে","en":"The month of Ramadan, in which the Quran was revealed"},"ref":"2:185"}},{"ar":"آيَة","tr":{"bn":"আয়াহ","en":"aayah"},"mean":{"bn":"আয়াত; নিদর্শন","en":"verse; sign"},"example":{"ar":"كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ","mean":{"bn":"এক বরকতময় কিতাব, যা আমি তোমার প্রতি নাজিল করেছি, যাতে মানুষ এর আয়াতগুলো নিয়ে চিন্তা করে","en":"A blessed Book We revealed to you, so that they may reflect on its verses"},"ref":"38:29"}},{"ar":"هُدًى","tr":{"bn":"হুদা","en":"hudaa"},"mean":{"bn":"হিদায়াত, পথনির্দেশ","en":"guidance"},"root":"ه د ي","example":{"ar":"هُدًى لِلنَّاسِ وَبَيِّنَاتٍ مِنَ الْهُدَى وَالْفُرْقَانِ","mean":{"bn":"মানুষের জন্য হিদায়াত, এবং হিদায়াত ও সত্য-মিথ্যার পার্থক্যকারী স্পষ্ট প্রমাণ","en":"guidance for people, and clear proofs of guidance and the Criterion"},"ref":"2:185"}},{"ar":"صَلَاة","tr":{"bn":"সালাহ","en":"ṣalaah"},"mean":{"bn":"সালাত, নামাজ","en":"prayer (salah)"},"root":"ص ل و","example":{"ar":"وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ","mean":{"bn":"আর সালাত কায়েম করো ও জাকাত দাও","en":"And establish prayer and give zakah"},"ref":"2:43"}},{"ar":"زَكَاة","tr":{"bn":"যাকাহ","en":"zakaah"},"mean":{"bn":"জাকাত; পবিত্রতা","en":"zakah (obligatory charity); purification"},"root":"ز ك و","example":{"ar":"الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ","mean":{"bn":"যারা সালাত কায়েম করে ও জাকাত দেয়","en":"who establish prayer and give zakah"},"ref":"31:4"}},{"ar":"صِيَام","tr":{"bn":"সিয়াম","en":"ṣiyaam"},"mean":{"bn":"সিয়াম, রোজা","en":"fasting"},"root":"ص و م","example":{"ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ","mean":{"bn":"হে মুমিনগণ, তোমাদের উপর রোজা ফরজ করা হয়েছে","en":"O you who believe, fasting has been prescribed for you"},"ref":"2:183"}},{"ar":"حَجّ","tr":{"bn":"হাজ্জ","en":"ḥajj"},"mean":{"bn":"হজ","en":"Hajj (pilgrimage)"},"root":"ح ج ج","example":{"ar":"وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلّٰهِ","mean":{"bn":"আর আল্লাহর জন্য হজ ও উমরা পূর্ণ করো","en":"And complete the Hajj and ‘Umrah for Allah"},"ref":"2:196"}},{"ar":"ذِكْر","tr":{"bn":"যিকর","en":"dhikr"},"mean":{"bn":"জিকির, স্মরণ; উপদেশ","en":"remembrance; reminder"},"root":"ذ ك ر","example":{"ar":"أَلَا بِذِكْرِ اللّٰهِ تَطْمَئِنُّ الْقُلُوبُ","mean":{"bn":"জেনে রাখো, আল্লাহর স্মরণেই অন্তর প্রশান্ত হয়","en":"Verily, in the remembrance of Allah do hearts find rest"},"ref":"13:28"}},{"ar":"دُعَاء","tr":{"bn":"দু'আ","en":"du'aa'"},"mean":{"bn":"দোয়া, প্রার্থনা, ডাক","en":"supplication, call"},"root":"د ع و","example":{"ar":"إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ","mean":{"bn":"নিশ্চয়ই আমার রব দোয়া শোনেন","en":"Indeed, my Lord is the Hearer of supplication"},"ref":"14:39"}},{"ar":"حَقّ","tr":{"bn":"হাক্ক","en":"ḥaqq"},"mean":{"bn":"সত্য, হক, অধিকার","en":"truth, right"},"root":"ح ق ق","example":{"ar":"وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ","mean":{"bn":"আর একে অপরকে সত্যের উপদেশ দেয় এবং ধৈর্যের উপদেশ দেয়","en":"and urge one another to truth and urge one another to patience"},"ref":"103:3"}},{"ar":"سَبِيل","tr":{"bn":"সাবীল","en":"sabeel"},"mean":{"bn":"পথ","en":"way, path"},"root":"س ب ل","example":{"ar":"وَأَنْفِقُوا فِي سَبِيلِ اللّٰهِ","mean":{"bn":"আর আল্লাহর পথে খরচ করো","en":"And spend in the way of Allah"},"ref":"2:195"}},{"ar":"نِعْمَة","tr":{"bn":"নি'মাহ","en":"ni'mah"},"mean":{"bn":"নিয়ামত, অনুগ্রহ","en":"blessing, favour"},"root":"ن ع م","example":{"ar":"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","mean":{"bn":"আর তোমার রবের নিয়ামতের কথা বলো","en":"And as for the favour of your Lord, proclaim it"},"ref":"93:11"}}]},{"type":"tip","kind":"fun","bn":"জানো কি? আমরা বাংলায় যে **নামাজ, রোজা, বেহেশত, দোজখ, খোদা** বলি — এগুলো ফারসি শব্দ! কুরআনের আরবি শব্দগুলো হলো {{صَلَاة}} (সালাত), {{صِيَام}} (সিয়াম), {{جَنَّة}} (জান্নাত), {{جَهَنَّم}} (জাহান্নাম) আর {{اللّٰه}}। কুরআন বুঝতে হলে আরবি শব্দগুলোই চিনতে হবে।","en":"Did you know? The Bangla words **namaj, roja, behesht, dojokh, khoda** are Persian! The Quran's Arabic words are {{صَلَاة}} (salah), {{صِيَام}} (siyam), {{جَنَّة}} (jannah), {{جَهَنَّم}} (jahannam) and {{اللّٰه}}. To understand the Quran, it's the Arabic words you need to recognise."},{"type":"vocab","title":{"bn":"আখিরাত, আমল ও প্রতিদান","en":"The Hereafter, deeds & recompense"},"items":[{"ar":"آخِرَة","tr":{"bn":"আখিরাহ","en":"aakhirah"},"mean":{"bn":"আখিরাত, পরকাল","en":"the Hereafter"},"root":"أ خ ر","example":{"ar":"وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الْأُولَى","mean":{"bn":"আর তোমার জন্য পরবর্তী সময় (আখিরাত) প্রথমটির চেয়ে উত্তম","en":"And the Hereafter is better for you than the first (life)"},"ref":"93:4"}},{"ar":"دُنْيَا","tr":{"bn":"দুনইয়া","en":"dunyaa"},"mean":{"bn":"দুনিয়া, পার্থিব জীবন (শব্দগত অর্থ ‘নিকটতম’)","en":"this world (literally ‘the nearest’)"},"root":"د ن و","example":{"ar":"وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ","mean":{"bn":"আর দুনিয়ার জীবন তো ধোঁকার সামগ্রী ছাড়া কিছু নয়","en":"And the life of this world is nothing but the enjoyment of delusion"},"ref":"3:185"}},{"ar":"قِيَامَة","tr":{"bn":"ক্বিয়ামাহ","en":"qiyaamah"},"mean":{"bn":"কিয়ামত, পুনরুত্থান","en":"Resurrection"},"root":"ق و م","example":{"ar":"لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ","mean":{"bn":"আমি শপথ করছি কিয়ামত দিবসের","en":"I swear by the Day of Resurrection"},"ref":"75:1"}},{"ar":"سَاعَة","tr":{"bn":"সা'আহ","en":"saa'ah"},"mean":{"bn":"কিয়ামতের সময়; মুহূর্ত","en":"the Hour (of Judgement); hour"},"root":"س و ع","example":{"ar":"إِنَّ السَّاعَةَ آتِيَةٌ","mean":{"bn":"নিশ্চয়ই কিয়ামত আসবেই","en":"Indeed, the Hour is coming"},"ref":"20:15"}},{"ar":"حِسَاب","tr":{"bn":"হিসাব","en":"ḥisaab"},"mean":{"bn":"হিসাব","en":"reckoning, account"},"root":"ح س ب","example":{"ar":"فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا","mean":{"bn":"তার হিসাব নেওয়া হবে সহজ হিসাব","en":"he will be judged with an easy reckoning"},"ref":"84:8"}},{"ar":"جَنَّة","tr":{"bn":"জান্নাহ","en":"jannah"},"mean":{"bn":"জান্নাত; বাগান","en":"Paradise; garden"},"root":"ج ن ن","example":{"ar":"وَادْخُلِي جَنَّتِي","mean":{"bn":"আর আমার জান্নাতে প্রবেশ করো","en":"and enter My Paradise"},"ref":"89:30"}},{"ar":"نَار","tr":{"bn":"নার","en":"naar"},"mean":{"bn":"আগুন; জাহান্নাম","en":"fire; Hellfire"},"root":"ن و ر","example":{"ar":"نَارٌ حَامِيَةٌ","mean":{"bn":"জ্বলন্ত আগুন","en":"a blazing fire"},"ref":"101:11"}},{"ar":"جَهَنَّم","tr":{"bn":"জাহান্নাম","en":"jahannam"},"mean":{"bn":"জাহান্নাম","en":"Hell"},"example":{"ar":"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا","mean":{"bn":"নিশ্চয়ই জাহান্নাম ওত পেতে আছে","en":"Indeed, Hell is lying in wait"},"ref":"78:21"}},{"ar":"رَحْمَة","tr":{"bn":"রাহমাহ","en":"raḥmah"},"mean":{"bn":"রহমত, দয়া","en":"mercy"},"root":"ر ح م","example":{"ar":"وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ","mean":{"bn":"আর আমার রহমত সব কিছুকে ঘিরে আছে","en":"And My mercy encompasses all things"},"ref":"7:156"}},{"ar":"عَذَاب","tr":{"bn":"'আযাব","en":"'adhaab"},"mean":{"bn":"আজাব, শাস্তি","en":"punishment, torment"},"root":"ع ذ ب","example":{"ar":"وَقِنَا عَذَابَ النَّارِ","mean":{"bn":"আর আমাদের আগুনের শাস্তি থেকে বাঁচাও","en":"and protect us from the punishment of the Fire"},"ref":"2:201"}},{"ar":"أَجْر","tr":{"bn":"আজর","en":"ajr"},"mean":{"bn":"প্রতিদান, পুরস্কার","en":"reward, wage"},"root":"أ ج ر","example":{"ar":"فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","mean":{"bn":"তাদের জন্য আছে অফুরন্ত প্রতিদান","en":"for them is a reward never ending"},"ref":"95:6"}},{"ar":"خَيْر","tr":{"bn":"খাইর","en":"khayr"},"mean":{"bn":"কল্যাণ, ভালো; উত্তম","en":"good; better"},"root":"خ ي ر","example":{"ar":"فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ","mean":{"bn":"যে অণু পরিমাণ ভালো কাজ করবে, সে তা দেখবে","en":"Whoever does an atom's weight of good will see it"},"ref":"99:7"}},{"ar":"شَرّ","tr":{"bn":"শার্র","en":"sharr"},"mean":{"bn":"মন্দ, অনিষ্ট","en":"evil, harm"},"root":"ش ر ر","example":{"ar":"وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ","mean":{"bn":"আর যে অণু পরিমাণ মন্দ কাজ করবে, সে-ও তা দেখবে","en":"And whoever does an atom's weight of evil will see it"},"ref":"99:8"}},{"ar":"ذَنْب","tr":{"bn":"যানব","en":"dhanb"},"mean":{"bn":"গুনাহ, পাপ","en":"sin"},"root":"ذ ن ب","example":{"ar":"إِنَّ اللّٰهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا","mean":{"bn":"নিশ্চয়ই আল্লাহ সব গুনাহ ক্ষমা করেন","en":"Indeed, Allah forgives all sins"},"ref":"39:53"}},{"ar":"مَغْفِرَة","tr":{"bn":"মাগফিরাহ","en":"maghfirah"},"mean":{"bn":"মাগফিরাত, ক্ষমা","en":"forgiveness"},"root":"غ ف ر","example":{"ar":"وَسَارِعُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ","mean":{"bn":"আর তোমাদের রবের ক্ষমা ও জান্নাতের দিকে দ্রুত এগিয়ে যাও","en":"And hasten to forgiveness from your Lord and a Garden"},"ref":"3:133"}},{"ar":"مَوْت","tr":{"bn":"মাওত","en":"mawt"},"mean":{"bn":"মৃত্যু","en":"death"},"root":"م و ت","example":{"ar":"الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ","mean":{"bn":"যিনি মৃত্যু ও জীবন সৃষ্টি করেছেন তোমাদের পরীক্ষা করার জন্য","en":"who created death and life to test you"},"ref":"67:2"}},{"ar":"حَيَاة","tr":{"bn":"হায়াহ","en":"ḥayaah"},"mean":{"bn":"জীবন, হায়াত","en":"life"},"root":"ح ي ي","example":{"ar":"يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي","mean":{"bn":"সে বলবে, হায়! যদি আমি আমার (আসল) জীবনের জন্য কিছু আগে পাঠাতাম!","en":"He will say, ‘Oh, I wish I had sent ahead for my life!’"},"ref":"89:24"}},{"ar":"غَيْب","tr":{"bn":"গাইব","en":"ghayb"},"mean":{"bn":"অদৃশ্য, গায়েব","en":"the unseen"},"root":"غ ي ب","example":{"ar":"وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَا إِلَّا هُوَ","mean":{"bn":"আর অদৃশ্যের চাবিগুলো তাঁরই কাছে, তিনি ছাড়া কেউ তা জানে না","en":"And with Him are the keys of the unseen; none knows them but He"},"ref":"6:59"}},{"ar":"نُور","tr":{"bn":"নূর","en":"noor"},"mean":{"bn":"আলো, নূর","en":"light"},"root":"ن و ر","example":{"ar":"اللّٰهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ","mean":{"bn":"আল্লাহ আসমানসমূহ ও জমিনের আলো","en":"Allah is the Light of the heavens and the earth"},"ref":"24:35"}},{"ar":"حَسَنَة","tr":{"bn":"হাসানাহ","en":"ḥasanah"},"mean":{"bn":"ভালো কাজ, কল্যাণ, নেকি","en":"good deed, good"},"root":"ح س ن","example":{"ar":"مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا","mean":{"bn":"যে একটি ভালো কাজ নিয়ে আসবে, তার জন্য থাকবে তার দশগুণ","en":"Whoever comes with a good deed will have ten like it"},"ref":"6:160"}},{"ar":"سَيِّئَة","tr":{"bn":"সাইয়িআহ","en":"sayyi'ah"},"mean":{"bn":"মন্দ কাজ, গুনাহ","en":"bad deed, evil"},"root":"س و أ","example":{"ar":"وَمَنْ جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى إِلَّا مِثْلَهَا","mean":{"bn":"আর যে একটি মন্দ কাজ নিয়ে আসবে, তাকে শুধু তার সমান প্রতিফলই দেওয়া হবে","en":"and whoever comes with a bad deed will be repaid only its like"},"ref":"6:160"}}]},{"type":"table","title":{"bn":"কুরআনের প্রিয় জোড়া — বিপরীত শব্দ","en":"The Quran's favourite pairs — opposites"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"বিপরীত","en":"Opposite"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["دُنْيَا","آخِرَة",{"bn":"দুনিয়া ↔ আখিরাত","en":"this world ↔ the Hereafter"}],["جَنَّة","نَار",{"bn":"জান্নাত ↔ আগুন","en":"Paradise ↔ the Fire"}],["رَحْمَة","عَذَاب",{"bn":"রহমত ↔ আজাব","en":"mercy ↔ punishment"}],["خَيْر","شَرّ",{"bn":"ভালো ↔ মন্দ","en":"good ↔ evil"}],["حَسَنَة","سَيِّئَة",{"bn":"ভালো কাজ ↔ মন্দ কাজ","en":"good deed ↔ bad deed"}],["حَيَاة","مَوْت",{"bn":"জীবন ↔ মৃত্যু","en":"life ↔ death"}],["إِيمَان","كُفْر",{"bn":"ঈমান ↔ কুফর","en":"faith ↔ disbelief"}],["نُور","ظُلُمَات",{"bn":"আলো ↔ অন্ধকার","en":"light ↔ darkness"}]]},{"type":"tip","kind":"memory","bn":"বাংলায় এদের চেনো: **ঈমান, ইসলাম, তাকওয়া, আয়াত, হেদায়েত, জাকাত, হজ, জিকির, দোয়া, হক, নিয়ামত, আখিরাত, দুনিয়া, কিয়ামত, হিসাব, জান্নাত, জাহান্নাম, রহমত, আজাব, মাগফিরাত, মউত, হায়াত, নূর**। আর কেউ হঠাৎ উধাও হলে বলি ‘**গায়েব** হয়ে গেছে’ — সেটি {{غَيْب}} (অদৃশ্য) থেকে!","en":"Spot them in Bangla: **iman, islam, taqwa, ayat, hedayet, jakat, hojj, jikir, doa, hok, niyamat, akhirat, duniya, kiyamot, hisab, jannat, jahannam, rohmot, ajab, magfirat, mout, hayat, nur**. And when something vanishes we say it went ‘**gayeb**’ — from {{غَيْب}} (the unseen)!"},{"type":"examples","title":{"bn":"সূরা যিলযাল — অণু পরিমাণ আমলও হারাবে না","en":"Surah Az-Zalzalah — not even an atom's weight is lost"},"items":[{"ar":"فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ","tr":{"bn":"ফামাই ইয়া'মাল মিসক্বালা যাররাতিন খাইরাই ইয়ারাহ","en":"famay ya'mal mithqaala dharratin khayray yarah"},"mean":{"bn":"যে অণু পরিমাণ ভালো কাজ করবে, সে তা দেখবে","en":"Whoever does an atom's weight of good will see it"},"note":{"bn":"৯৯:৭","en":"99:7"},"hl":"خَيْرًا"},{"ar":"وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ","tr":{"bn":"ওয়া মাই ইয়া'মাল মিসক্বালা যাররাতিন শাররাই ইয়ারাহ","en":"wa may ya'mal mithqaala dharratin sharray yarah"},"mean":{"bn":"আর যে অণু পরিমাণ মন্দ কাজ করবে, সে-ও তা দেখবে","en":"And whoever does an atom's weight of evil will see it"},"note":{"bn":"৯৯:৮","en":"99:8"},"hl":"شَرًّا"}]},{"type":"quiz","items":[{"q":{"bn":"{{آخِرَة}} মানে কী?","en":"What does {{آخِرَة}} mean?"},"ar":"آخِرَة","options":[{"bn":"আখিরাত, পরকাল","en":"the Hereafter"},{"bn":"দুনিয়া","en":"this world"},{"bn":"দিন","en":"day"}],"answer":0},{"q":{"bn":"{{رَحْمَة}} শব্দের অর্থ —","en":"{{رَحْمَة}} means —"},"ar":"رَحْمَة","options":[{"bn":"শাস্তি","en":"punishment"},{"bn":"রহমত, দয়া","en":"mercy"},{"bn":"হিসাব","en":"reckoning"}],"answer":1},{"q":{"bn":"{{جَنَّة}} শব্দের বিপরীত কোনটি?","en":"Which is the opposite of {{جَنَّة}}?"},"options":["نَار","نُور","خَيْر"],"answer":0},{"q":{"bn":"‘সালাত’ আরবিতে —","en":"‘Prayer’ in Arabic —"},"options":["زَكَاة","صَلَاة","صِيَام","حَجّ"],"answer":1},{"q":{"bn":"{{غَيْب}} মানে —","en":"{{غَيْب}} means —"},"ar":"غَيْب","options":[{"bn":"অদৃশ্য","en":"the unseen"},{"bn":"আলো","en":"light"},{"bn":"পথ","en":"path"}],"answer":0},{"q":{"bn":"কোনটি ফারসি শব্দ, কুরআনের আরবি নয়?","en":"Which is a Persian word, not Quranic Arabic?"},"options":[{"bn":"নামাজ","en":"namaj"},{"bn":"সালাত","en":"salat"},{"bn":"জান্নাত","en":"jannat"}],"answer":0},{"q":{"bn":"{{ذَنْب}} মানে কী?","en":"What does {{ذَنْب}} mean?"},"ar":"ذَنْب","options":[{"bn":"পুরস্কার","en":"reward"},{"bn":"গুনাহ","en":"sin"},{"bn":"স্মরণ","en":"remembrance"}],"answer":1},{"q":{"bn":"{{أَلَا بِذِكْرِ اللّٰهِ تَطْمَئِنُّ الْقُلُوبُ}} — অন্তর কিসে প্রশান্ত হয়?","en":"{{أَلَا بِذِكْرِ اللّٰهِ تَطْمَئِنُّ الْقُلُوبُ}} — hearts find rest in what?"},"options":[{"bn":"আল্লাহর স্মরণে","en":"the remembrance of Allah"},{"bn":"সম্পদে","en":"wealth"},{"bn":"ঘুমে","en":"sleep"}],"answer":0}]}]},{"id":"vocab-nature","icon":"س","title":{"bn":"সৃষ্টি ও প্রকৃতি","en":"Creation & Nature"},"subtitle":{"bn":"আসমান, জমিন, সূর্য, চাঁদ, পাহাড়, সাগর — আল্লাহর নিদর্শন","en":"Sky, earth, sun, moon, mountains, seas — the signs of Allah"},"minutes":16,"goals":[{"bn":"আকাশ, সময় ও প্রকৃতির ৩০টি শব্দ শিখব","en":"Learn 30 words for the sky, time and nature"},{"bn":"আমপারার শপথের আয়াতগুলো ({{وَالشَّمْسِ}}, {{وَالْفَجْرِ}} …) বুঝব","en":"Understand the oath verses of Juz 'Amma ({{وَالشَّمْسِ}}, {{وَالْفَجْرِ}} …)"},{"bn":"সালাতের ওয়াক্ত ও পরিচিত নামের সাথে শব্দ মেলাব","en":"Link words to prayer times and familiar names"}],"blocks":[{"type":"text","bn":"কুরআন বারবার বলে — চারপাশে তাকাও! আকাশ, সূর্য, রাত-দিন, বৃষ্টি, পাহাড় — সবই আল্লাহর {{آيَات}} (নিদর্শন)। আমপারার অনেক সূরা শুরু হয় প্রকৃতির শপথ দিয়ে: {{وَالشَّمْسِ}} (সূর্যের কসম), {{وَاللَّيْلِ}} (রাতের কসম)। তাই এই শব্দগুলো জানলে ছোট সূরাগুলো খুব সহজে বুঝবে।","en":"The Quran keeps saying: look around you! The sky, the sun, night and day, rain, mountains — all are {{آيَات}} (signs) of Allah. Many surahs of Juz 'Amma open with oaths by nature: {{وَالشَّمْسِ}} (by the sun), {{وَاللَّيْلِ}} (by the night). Learn these words and the short surahs open up easily."},{"type":"vocab","title":{"bn":"আকাশ ও সময়","en":"Sky & time"},"items":[{"ar":"سَمَاء","tr":{"bn":"সামা","en":"samaa'"},"mean":{"bn":"আকাশ, আসমান (বহুবচন {{سَمَاوَات}})","en":"sky, heaven (plural {{سَمَاوَات}})"},"root":"س م و","example":{"ar":"إِذَا السَّمَاءُ انْشَقَّتْ","mean":{"bn":"যখন আকাশ ফেটে যাবে","en":"When the sky is split open"},"ref":"84:1"}},{"ar":"أَرْض","tr":{"bn":"আরদ্ব","en":"arḍ"},"mean":{"bn":"জমিন, পৃথিবী, ভূমি","en":"earth, land"},"root":"أ ر ض","example":{"ar":"إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا","mean":{"bn":"যখন পৃথিবী তার প্রবল কম্পনে কেঁপে উঠবে","en":"When the earth is shaken with its quake"},"ref":"99:1"}},{"ar":"شَمْس","tr":{"bn":"শামস","en":"shams"},"mean":{"bn":"সূর্য","en":"sun"},"root":"ش م س","example":{"ar":"وَالشَّمْسِ وَضُحَاهَا","mean":{"bn":"কসম সূর্যের ও তার উজ্জ্বল আলোর","en":"By the sun and its morning brightness"},"ref":"91:1"}},{"ar":"قَمَر","tr":{"bn":"ক্বামার","en":"qamar"},"mean":{"bn":"চাঁদ","en":"moon"},"root":"ق م ر","example":{"ar":"وَالْقَمَرِ إِذَا تَلَاهَا","mean":{"bn":"কসম চাঁদের, যখন তা সূর্যের পরে আসে","en":"And by the moon when it follows it"},"ref":"91:2"}},{"ar":"نَجْم","tr":{"bn":"নাজম","en":"najm"},"mean":{"bn":"তারা, নক্ষত্র","en":"star"},"root":"ن ج م","example":{"ar":"وَالنَّجْمِ إِذَا هَوَى","mean":{"bn":"কসম তারার, যখন তা অস্ত যায়","en":"By the star when it descends"},"ref":"53:1"}},{"ar":"لَيْل","tr":{"bn":"লাইল","en":"layl"},"mean":{"bn":"রাত","en":"night"},"root":"ل ي ل","example":{"ar":"وَاللَّيْلِ إِذَا يَغْشَى","mean":{"bn":"কসম রাতের, যখন তা ঢেকে দেয়","en":"By the night when it covers"},"ref":"92:1"}},{"ar":"نَهَار","tr":{"bn":"নাহার","en":"nahaar"},"mean":{"bn":"দিন (দিনের আলো)","en":"day (daytime)"},"root":"ن ه ر","example":{"ar":"وَالنَّهَارِ إِذَا تَجَلَّى","mean":{"bn":"কসম দিনের, যখন তা উজ্জ্বল হয়","en":"And by the day when it shines bright"},"ref":"92:2"}},{"ar":"لَيْلَة","tr":{"bn":"লাইলাহ","en":"laylah"},"mean":{"bn":"একটি রাত","en":"a night"},"root":"ل ي ل","example":{"ar":"لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ","mean":{"bn":"কদরের রাত হাজার মাসের চেয়েও উত্তম","en":"The Night of Decree is better than a thousand months"},"ref":"97:3"}},{"ar":"فَجْر","tr":{"bn":"ফাজর","en":"fajr"},"mean":{"bn":"ভোর, ফজর","en":"dawn"},"root":"ف ج ر","example":{"ar":"وَالْفَجْرِ","mean":{"bn":"কসম ভোরের","en":"By the dawn"},"ref":"89:1"}},{"ar":"صُبْح","tr":{"bn":"সুবহ","en":"ṣubḥ"},"mean":{"bn":"সকাল, প্রভাত","en":"morning, daybreak"},"root":"ص ب ح","example":{"ar":"وَالصُّبْحِ إِذَا تَنَفَّسَ","mean":{"bn":"কসম প্রভাতের, যখন তা শ্বাস নেয় (আলো ছড়ায়)","en":"And by the morning when it breathes"},"ref":"81:18"}},{"ar":"ضُحَى","tr":{"bn":"দ্বুহা","en":"ḍuḥaa"},"mean":{"bn":"পূর্বাহ্ন, সকালের উজ্জ্বল সময়","en":"forenoon, morning brightness"},"root":"ض ح و","example":{"ar":"وَالضُّحَى","mean":{"bn":"কসম পূর্বাহ্নের","en":"By the morning brightness"},"ref":"93:1"}},{"ar":"عَصْر","tr":{"bn":"'আসর","en":"'aṣr"},"mean":{"bn":"সময়, যুগ; বিকেল","en":"time, age; afternoon"},"root":"ع ص ر","example":{"ar":"وَالْعَصْرِ","mean":{"bn":"কসম সময়ের","en":"By time"},"ref":"103:1"}},{"ar":"شَهْر","tr":{"bn":"শাহর","en":"shahr"},"mean":{"bn":"মাস","en":"month"},"root":"ش ه ر","example":{"ar":"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ","mean":{"bn":"রমজান মাস, যাতে কুরআন নাজিল হয়েছে","en":"The month of Ramadan, in which the Quran was revealed"},"ref":"2:185"}},{"ar":"سَنَة","tr":{"bn":"সানাহ","en":"sanah"},"mean":{"bn":"বছর","en":"year"},"example":{"ar":"فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا","mean":{"bn":"তিনি তাদের মধ্যে পঞ্চাশ কম এক হাজার বছর ছিলেন","en":"He remained among them a thousand years less fifty"},"ref":"29:14"}}]},{"type":"tip","kind":"memory","bn":"আমাদের নামেই লুকিয়ে আছে! **শামসুল** হক ← {{شَمْس}}, **কামরুল** হাসান ← {{قَمَر}}, **নাজমুল** ← {{نَجْم}}, **লায়লা** ← {{لَيْل}}-এর পরিবার। আর সালাতের ওয়াক্ত: **ফজর** ← {{فَجْر}}, **আসর** ← {{عَصْر}}, **সুবহে সাদিক** ← {{صُبْح}}, **দোহা/চাশতের সালাত** ← {{ضُحَى}}।","en":"They hide in our names! **Shamsul** Haque ← {{شَمْس}}, **Kamrul** Hasan ← {{قَمَر}}, **Najmul** ← {{نَجْم}}, **Laila** ← family of {{لَيْل}}. And prayer times: **Fajr** ← {{فَجْر}}, **Asr** ← {{عَصْر}}, **subhe sadiq** (true dawn) ← {{صُبْح}}, **Duha** prayer ← {{ضُحَى}}."},{"type":"vocab","title":{"bn":"জমিন, পানি ও জীবজগৎ","en":"Land, water & living things"},"items":[{"ar":"مَاء","tr":{"bn":"মা","en":"maa'"},"mean":{"bn":"পানি","en":"water"},"root":"م و ه","example":{"ar":"وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ","mean":{"bn":"আর আমি পানি থেকে সব প্রাণবান জিনিস সৃষ্টি করেছি","en":"And We made from water every living thing"},"ref":"21:30"}},{"ar":"بَحْر","tr":{"bn":"বাহর","en":"baḥr"},"mean":{"bn":"সাগর, সমুদ্র","en":"sea"},"root":"ب ح ر","example":{"ar":"مَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِ","mean":{"bn":"তিনি দুই সাগরকে প্রবাহিত করেছেন, যারা পরস্পর মিলিত হয় ({{الْبَحْرَيْنِ}} = দুই সাগর)","en":"He released the two seas, meeting one another ({{الْبَحْرَيْنِ}} = two seas)"},"ref":"55:19"}},{"ar":"نَهَر","tr":{"bn":"নাহার","en":"nahar"},"mean":{"bn":"নদী, নহর (বহুবচন {{أَنْهَار}})","en":"river (plural {{أَنْهَار}})"},"root":"ن ه ر","example":{"ar":"إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ","mean":{"bn":"নিশ্চয়ই মুত্তাকিরা থাকবে বাগান ও নদীর মাঝে","en":"Indeed, the righteous will be among gardens and rivers"},"ref":"54:54"}},{"ar":"جَبَل","tr":{"bn":"জাবাল","en":"jabal"},"mean":{"bn":"পাহাড়, পর্বত (বহুবচন {{جِبَال}})","en":"mountain (plural {{جِبَال}})"},"root":"ج ب ل","example":{"ar":"وَالْجِبَالَ أَوْتَادًا","mean":{"bn":"আর পাহাড়গুলোকে (করেছি) খুঁটি","en":"and the mountains as pegs"},"ref":"78:7"}},{"ar":"رِيح","tr":{"bn":"রীহ","en":"reeḥ"},"mean":{"bn":"বাতাস (বহুবচন {{رِيَاح}})","en":"wind (plural {{رِيَاح}})"},"root":"ر و ح","example":{"ar":"وَتَصْرِيفِ الرِّيَاحِ","mean":{"bn":"আর বাতাসের দিক পরিবর্তনে (নিদর্শন আছে)","en":"and in the directing of the winds (are signs)"},"ref":"2:164"}},{"ar":"شَجَرَة","tr":{"bn":"শাজারাহ","en":"shajarah"},"mean":{"bn":"গাছ, বৃক্ষ","en":"tree"},"root":"ش ج ر","example":{"ar":"كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ","mean":{"bn":"একটি পবিত্র কথা, একটি পবিত্র গাছের মতো","en":"a good word like a good tree"},"ref":"14:24"}},{"ar":"ثَمَرَات","tr":{"bn":"সামারাত","en":"thamaraat"},"mean":{"bn":"ফলমূল","en":"fruits"},"root":"ث م ر","example":{"ar":"فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَكُمْ","mean":{"bn":"তারপর তা দিয়ে তোমাদের রিজিক হিসেবে নানা ফল বের করেছেন","en":"and brought forth by it fruits as provision for you"},"ref":"2:22"}},{"ar":"نَخْل","tr":{"bn":"নাখল","en":"nakhl"},"mean":{"bn":"খেজুর গাছ","en":"date palms"},"root":"ن خ ل","example":{"ar":"وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ","mean":{"bn":"আর উঁচু উঁচু খেজুর গাছ, যাতে আছে থরে থরে সাজানো ফলের গুচ্ছ","en":"and tall palm trees with clusters arranged in layers"},"ref":"50:10"}},{"ar":"زَيْتُون","tr":{"bn":"যাইতূন","en":"zaytoon"},"mean":{"bn":"জলপাই, জয়তুন","en":"olive"},"example":{"ar":"وَالتِّينِ وَالزَّيْتُونِ","mean":{"bn":"কসম ডুমুরের ও জয়তুনের","en":"By the fig and the olive"},"ref":"95:1"}},{"ar":"دَابَّة","tr":{"bn":"দাব্বাহ","en":"daabbah"},"mean":{"bn":"প্রাণী, যে কোনো জীবজন্তু","en":"living creature, animal"},"root":"د ب ب","example":{"ar":"وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللّٰهِ رِزْقُهَا","mean":{"bn":"পৃথিবীতে এমন কোনো প্রাণী নেই, যার রিজিকের দায়িত্ব আল্লাহর উপর নয়","en":"There is no creature on earth but that its provision is upon Allah"},"ref":"11:6"}},{"ar":"طَيْر","tr":{"bn":"ত্বাইর","en":"ṭayr"},"mean":{"bn":"পাখি","en":"birds"},"root":"ط ي ر","example":{"ar":"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","mean":{"bn":"আর তিনি তাদের উপর ঝাঁকে ঝাঁকে পাখি পাঠালেন","en":"And He sent against them birds in flocks"},"ref":"105:3"}},{"ar":"إِبِل","tr":{"bn":"ইবিল","en":"ibil"},"mean":{"bn":"উট","en":"camels"},"example":{"ar":"أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ","mean":{"bn":"তারা কি উটের দিকে তাকায় না, কীভাবে তা সৃষ্টি করা হয়েছে?","en":"Do they not look at the camels — how they are created?"},"ref":"88:17"}},{"ar":"تُرَاب","tr":{"bn":"তুরাব","en":"turaab"},"mean":{"bn":"মাটি, ধুলো","en":"dust, soil"},"root":"ت ر ب","example":{"ar":"وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنْتُ تُرَابًا","mean":{"bn":"আর কাফির বলবে, হায়! আমি যদি মাটি হয়ে যেতাম!","en":"And the disbeliever will say, ‘Oh, I wish I were dust!’"},"ref":"78:40"}},{"ar":"طِين","tr":{"bn":"ত্বীন","en":"ṭeen"},"mean":{"bn":"কাদামাটি","en":"clay"},"root":"ط ي ن","example":{"ar":"إِنِّي خَالِقٌ بَشَرًا مِنْ طِينٍ","mean":{"bn":"আমি কাদামাটি থেকে মানুষ সৃষ্টি করতে যাচ্ছি","en":"I am going to create a human from clay"},"ref":"38:71"}},{"ar":"بَلَد","tr":{"bn":"বালাদ","en":"balad"},"mean":{"bn":"নগর, দেশ","en":"city, land"},"root":"ب ل د","example":{"ar":"لَا أُقْسِمُ بِهٰذَا الْبَلَدِ","mean":{"bn":"আমি শপথ করছি এই নগরের","en":"I swear by this city"},"ref":"90:1"}},{"ar":"بَيْت","tr":{"bn":"বাইত","en":"bayt"},"mean":{"bn":"ঘর; কাবাঘর","en":"house; the Ka'bah"},"root":"ب ي ت","example":{"ar":"وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ","mean":{"bn":"আর যখন ইবরাহিম ও ইসমাইল কাবাঘরের ভিত্তি উঠাচ্ছিলেন","en":"And when Ibrahim was raising the foundations of the House, with Isma'il"},"ref":"2:127"}}]},{"type":"examples","title":{"bn":"সূরা গাশিয়াহ — চোখ মেলে দেখো","en":"Surah Al-Ghashiyah — open your eyes and look"},"items":[{"ar":"أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ","tr":{"bn":"আফালা ইয়ানযুরূনা ইলাল ইবিলি কাইফা খুলিক্বাত","en":"afalaa yanẓuroona ilal-ibili kayfa khuliqat"},"mean":{"bn":"তারা কি উটের দিকে তাকায় না, কীভাবে তা সৃষ্টি করা হয়েছে?","en":"Do they not look at the camels — how they are created?"},"note":{"bn":"৮৮:১৭","en":"88:17"},"hl":"الْإِبِلِ"},{"ar":"وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ","tr":{"bn":"ওয়া ইলাস সামাই কাইফা রুফি'আত","en":"wa ilas-samaa'i kayfa rufi'at"},"mean":{"bn":"আর আকাশের দিকে, কীভাবে তা উঁচু করা হয়েছে?","en":"And at the sky — how it is raised?"},"note":{"bn":"৮৮:১৮","en":"88:18"},"hl":"السَّمَاءِ"},{"ar":"وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ","tr":{"bn":"ওয়া ইলাল জিবালি কাইফা নুসিবাত","en":"wa ilal-jibaali kayfa nuṣibat"},"mean":{"bn":"আর পাহাড়ের দিকে, কীভাবে তা স্থাপন করা হয়েছে?","en":"And at the mountains — how they are set firm?"},"note":{"bn":"৮৮:১৯","en":"88:19"},"hl":"الْجِبَالِ"},{"ar":"وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ","tr":{"bn":"ওয়া ইলাল আরদ্বি কাইফা সুত্বিহাত","en":"wa ilal-arḍi kayfa suṭiḥat"},"mean":{"bn":"আর জমিনের দিকে, কীভাবে তা বিছানো হয়েছে?","en":"And at the earth — how it is spread out?"},"note":{"bn":"৮৮:২০","en":"88:20"},"hl":"الْأَرْضِ"}]},{"type":"tip","kind":"fun","bn":"অনেক সূরার নামই প্রকৃতির শব্দ! {{الشَّمْس}} (সূর্য), {{الْقَمَر}} (চাঁদ), {{النَّجْم}} (তারা), {{الْفَجْر}} (ভোর), {{اللَّيْل}} (রাত), {{الضُّحَى}} (পূর্বাহ্ন), {{الْعَصْر}} (সময়), {{التِّين}} (ডুমুর), {{الْبَلَد}} (নগর)। সূরার নাম জানলে শব্দও জানা হয়ে গেল! আর বাংলায় খালকে যে ‘**নহর**’ বলে — সেটি {{نَهَر}} (নদী) থেকে।","en":"Many surahs are named after nature! {{الشَّمْس}} (sun), {{الْقَمَر}} (moon), {{النَّجْم}} (star), {{الْفَجْر}} (dawn), {{اللَّيْل}} (night), {{الضُّحَى}} (forenoon), {{الْعَصْر}} (time), {{التِّين}} (fig), {{الْبَلَد}} (city). Know the surah names and you know the words! And the Bangla word ‘**nohor**’ (canal) comes from {{نَهَر}} (river)."},{"type":"quiz","items":[{"q":{"bn":"{{سَمَاء}} মানে কী?","en":"What does {{سَمَاء}} mean?"},"ar":"سَمَاء","options":[{"bn":"আকাশ","en":"sky"},{"bn":"পানি","en":"water"},{"bn":"জমিন","en":"earth"}],"answer":0},{"q":{"bn":"{{قَمَر}} শব্দের অর্থ —","en":"{{قَمَر}} means —"},"ar":"قَمَر","options":[{"bn":"সূর্য","en":"sun"},{"bn":"চাঁদ","en":"moon"},{"bn":"তারা","en":"star"}],"answer":1},{"q":{"bn":"‘রাত’ আরবিতে —","en":"‘Night’ in Arabic —"},"options":["نَهَار","لَيْل","فَجْر","شَهْر"],"answer":1},{"q":{"bn":"{{جَبَل}} মানে —","en":"{{جَبَل}} means —"},"ar":"جَبَل","options":[{"bn":"সাগর","en":"sea"},{"bn":"পাহাড়","en":"mountain"},{"bn":"গাছ","en":"tree"}],"answer":1},{"q":{"bn":"{{وَالْعَصْرِ}} — {{عَصْر}} এখানে কী অর্থে?","en":"In {{وَالْعَصْرِ}}, what does {{عَصْر}} mean?"},"options":[{"bn":"সময়, যুগ","en":"time, age"},{"bn":"সূর্য","en":"sun"},{"bn":"ঘর","en":"house"}],"answer":0},{"q":{"bn":"নাম ‘কামরুল’-এর মধ্যে কোন আরবি শব্দ আছে?","en":"Which Arabic word is inside the name ‘Kamrul’?"},"options":["قَمَر","شَمْس","نَجْم"],"answer":0},{"q":{"bn":"{{مَاء}} মানে কী?","en":"What does {{مَاء}} mean?"},"ar":"مَاء","options":[{"bn":"আগুন","en":"fire"},{"bn":"পানি","en":"water"},{"bn":"বাতাস","en":"wind"}],"answer":1},{"q":{"bn":"{{بَيْت}} শব্দের অর্থ —","en":"{{بَيْت}} means —"},"ar":"بَيْت","options":[{"bn":"ঘর","en":"house"},{"bn":"নগর","en":"city"},{"bn":"বছর","en":"year"}],"answer":0,"explain":{"bn":"বাইতুল্লাহ = আল্লাহর ঘর (কাবা); বায়তুল মোকাররম = সম্মানিত ঘর।","en":"Baytullah = the House of Allah (Ka'bah); Baitul Mukarram = the honoured house."}}]}]},{"id":"vocab-roots","icon":"كتب","title":{"bn":"মূল অক্ষরের জাদু","en":"The Root Power"},"subtitle":{"bn":"তিনটি অক্ষর থেকে একটি পুরো শব্দ-পরিবার","en":"One three-letter root, a whole family of words"},"minutes":22,"goals":[{"bn":"বুঝব কীভাবে তিন অক্ষরের একটি মূল (রুট) থেকে অনেক শব্দ তৈরি হয়","en":"See how one three-letter root produces many words"},{"bn":"ك ت ب, ع ل م, ح م د, ر ح م, س ل م — পাঁচটি শব্দ-পরিবার চিনব","en":"Meet five word families: ك ت ب, ع ل م, ح م د, ر ح م, س ل م"},{"bn":"{{فَاعِل}} (কর্তা) ও {{مَفْعُول}} (কর্ম) ছাঁচ চিনে নতুন শব্দের অর্থ আন্দাজ করব","en":"Use the patterns {{فَاعِل}} (doer) and {{مَفْعُول}} (done-to) to guess new words"}],"blocks":[{"type":"text","bn":"আরবি ভাষার সবচেয়ে সুন্দর রহস্য হলো **মূল অক্ষর** (রুট)। বেশিরভাগ শব্দের ভেতরে তিনটি মূল অক্ষর থাকে, যা একটি মৌলিক অর্থ বহন করে। যেমন ك ت ب = ‘লেখা’। এর আগে-পরে-মাঝে কিছু অক্ষর ও হরকত যোগ করলে তৈরি হয় লেখক, বই, লেখা হয়েছে এমন — পুরো একটি পরিবার!","en":"The most beautiful secret of Arabic is the **root**. Most words carry three root letters holding a core meaning. For example ك ت ب = ‘writing’. Add letters and vowels before, after or between them and you get writer, book, something written — a whole family!"},{"type":"text","bn":"এর মানে, একটি নতুন শব্দ দেখলে আগে তার তিনটি মূল অক্ষর খুঁজে বের করো। মূলটি চেনা হলে অর্থের অর্ধেক কাজ শেষ! আগের পাঠগুলোর প্রতিটি শব্দের পাশে আমরা যে ‘রুট’ দিয়েছি, এখন সেগুলো কাজে লাগবে।","en":"So when you meet a new word, first find its three root letters. Recognise the root and half the meaning is done! The roots we listed beside words in earlier lessons now come into play."},{"type":"table","title":{"bn":"পরিবার ১: ك ت ب (লেখা)","en":"Family 1: ك ت ب (writing)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"ছাঁচ","en":"Pattern"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كَتَبَ","فَعَلَ",{"bn":"সে লিখল","en":"he wrote"}],["يَكْتُبُ","يَفْعُلُ",{"bn":"সে লেখে","en":"he writes"}],["كِتَاب","فِعَال",{"bn":"বই, কিতাব","en":"book"}],["كُتُب","فُعُل",{"bn":"বইসমূহ","en":"books"}],["كَاتِب","فَاعِل",{"bn":"লেখক","en":"writer"}],["مَكْتُوب","مَفْعُول",{"bn":"লিখিত","en":"written"}],["مَكْتَب","مَفْعَل",{"bn":"লেখার জায়গা, দপ্তর (কুরআনে নেই)","en":"place of writing, office (not in the Quran)"}]]},{"type":"vocab","title":{"bn":"ك ت ب পরিবার","en":"The ك ت ب family"},"items":[{"ar":"كَتَبَ","tr":{"bn":"কাতাবা","en":"kataba"},"mean":{"bn":"সে লিখল; নির্ধারণ করল","en":"he wrote; prescribed, decreed"},"root":"ك ت ب","example":{"ar":"كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ","mean":{"bn":"তোমাদের রব নিজের উপর দয়াকে অবধারিত করে নিয়েছেন","en":"Your Lord has decreed mercy upon Himself"},"ref":"6:54"}},{"ar":"كِتَاب","tr":{"bn":"কিতাব","en":"kitaab"},"mean":{"bn":"কিতাব, বই, গ্রন্থ","en":"book, scripture"},"root":"ك ت ب","example":{"ar":"كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ","mean":{"bn":"এক কিতাব, যা আমি তোমার প্রতি নাজিল করেছি, যাতে তুমি মানুষকে অন্ধকার থেকে আলোর দিকে বের করে আনো","en":"A Book We revealed to you so that you may bring people out of darkness into light"},"ref":"14:1"}},{"ar":"كُتُب","tr":{"bn":"কুতুব","en":"kutub"},"mean":{"bn":"কিতাবসমূহ","en":"books, scriptures"},"root":"ك ت ب","example":{"ar":"كُلٌّ آمَنَ بِاللّٰهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ","mean":{"bn":"সবাই ঈমান এনেছে আল্লাহ, তাঁর ফেরেশতা, তাঁর কিতাবসমূহ ও তাঁর রাসূলদের প্রতি","en":"All believe in Allah, His angels, His books and His messengers"},"ref":"2:285"}},{"ar":"كَاتِب","tr":{"bn":"কাতিব","en":"kaatib"},"mean":{"bn":"লেখক","en":"writer, scribe"},"root":"ك ت ب","example":{"ar":"وَلْيَكْتُبْ بَيْنَكُمْ كَاتِبٌ بِالْعَدْلِ","mean":{"bn":"আর তোমাদের মধ্যে একজন লেখক যেন ন্যায়ের সাথে লিখে দেয়","en":"and let a scribe write it between you in justice"},"ref":"2:282"}},{"ar":"مَكْتُوب","tr":{"bn":"মাকতূব","en":"maktoob"},"mean":{"bn":"লিখিত","en":"written"},"root":"ك ت ب","example":{"ar":"يَجِدُونَهُ مَكْتُوبًا عِنْدَهُمْ فِي التَّوْرَاةِ وَالْإِنْجِيلِ","mean":{"bn":"যাঁর কথা তারা তাদের কাছে থাকা তাওরাত ও ইনজিলে লিখিত পায়","en":"whom they find written with them in the Torah and the Gospel"},"ref":"7:157"}}]},{"type":"tip","kind":"memory","bn":"বাংলায় **কিতাব** (বই) আর **মক্তব** (ছোটদের আরবি পড়ার স্কুল) — দুটোই ك ت ب পরিবারের! মক্তব মানে আসলে ‘লেখার জায়গা’ ({{مَكْتَب}})। একইভাবে **মসজিদ** ({{مَسْجِد}}) মানে ‘সিজদার জায়গা’ — {{مَفْعَل}} ছাঁচ প্রায়ই জায়গা বোঝায়।","en":"In Bangla, **kitab** (book) and **moktob** (children's Quran school) both belong to the ك ت ب family! Moktob literally means ‘place of writing’ ({{مَكْتَب}}). Likewise **masjid** ({{مَسْجِد}}) means ‘place of prostration’ — the {{مَفْعَل}} pattern often names a place."},{"type":"table","title":{"bn":"পরিবার ২: ع ل م (জানা)","en":"Family 2: ع ل م (knowing)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["عَلِمَ",{"bn":"সে জানল","en":"he knew"}],["يَعْلَمُ",{"bn":"সে জানে","en":"he knows"}],["عِلْم",{"bn":"জ্ঞান, ইলম","en":"knowledge"}],["عَالِم",{"bn":"জ্ঞানী, যে জানে","en":"knower, scholar"}],["عُلَمَاء",{"bn":"জ্ঞানীরা, আলেমগণ","en":"scholars"}],["عَلِيم",{"bn":"সর্বজ্ঞ (আল্লাহর নাম)","en":"All-Knowing (name of Allah)"}],["عَلَّمَ",{"bn":"সে শেখাল","en":"he taught"}],["مَعْلُوم",{"bn":"জানা, নির্দিষ্ট","en":"known, appointed"}]]},{"type":"vocab","title":{"bn":"ع ل م পরিবার","en":"The ع ل م family"},"items":[{"ar":"عَلَّمَ","tr":{"bn":"'আল্লামা","en":"'allama"},"mean":{"bn":"সে শেখাল","en":"he taught"},"root":"ع ل م","example":{"ar":"عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ","mean":{"bn":"তিনি মানুষকে শিখিয়েছেন যা সে জানত না","en":"He taught man what he did not know"},"ref":"96:5"}},{"ar":"عِلْم","tr":{"bn":"'ইলম","en":"'ilm"},"mean":{"bn":"জ্ঞান, ইলম","en":"knowledge"},"root":"ع ل م","example":{"ar":"وَقُلْ رَبِّ زِدْنِي عِلْمًا","mean":{"bn":"আর বলো, হে আমার রব, আমার জ্ঞান বাড়িয়ে দাও","en":"And say, ‘My Lord, increase me in knowledge’"},"ref":"20:114"}},{"ar":"عَالِم","tr":{"bn":"'আলিম","en":"'aalim"},"mean":{"bn":"জ্ঞানী, যিনি জানেন","en":"knower, one who knows"},"root":"ع ل م","example":{"ar":"عَالِمُ الْغَيْبِ وَالشَّهَادَةِ","mean":{"bn":"অদৃশ্য ও দৃশ্য সবকিছুর জ্ঞানী","en":"Knower of the unseen and the witnessed"},"ref":"59:22"}},{"ar":"عُلَمَاء","tr":{"bn":"'উলামা","en":"'ulamaa'"},"mean":{"bn":"আলেমগণ, জ্ঞানীরা","en":"scholars, people of knowledge"},"root":"ع ل م","example":{"ar":"إِنَّمَا يَخْشَى اللّٰهَ مِنْ عِبَادِهِ الْعُلَمَاءُ","mean":{"bn":"আল্লাহর বান্দাদের মধ্যে জ্ঞানীরাই কেবল তাঁকে ভয় করে","en":"Only those of His servants who have knowledge truly fear Allah"},"ref":"35:28"}},{"ar":"مَعْلُوم","tr":{"bn":"মা'লূম","en":"ma'loom"},"mean":{"bn":"জানা, নির্দিষ্ট","en":"known, appointed"},"root":"ع ل م","example":{"ar":"وَمَا مِنَّا إِلَّا لَهُ مَقَامٌ مَعْلُومٌ","mean":{"bn":"আমাদের প্রত্যেকেরই একটি নির্দিষ্ট স্থান আছে","en":"There is none of us but has a known position"},"ref":"37:164"}}]},{"type":"tip","kind":"memory","bn":"বাংলায় **ইলম, আলেম, উলামা, তালিম** তো আছেই — আর ‘ব্যাপারটা **মালুম** হলো’ (জানা গেল) কথাটির ‘মালুম’ হলো {{مَعْلُوم}}! আরও মজা: ফাতিহার {{عَالَمِين}} (জগৎসমূহ) শব্দেও এই একই তিন অক্ষর ع ل م।","en":"Bangla has **ilm, alem, ulama, talim** — and in the phrase ‘it became **malum**’ (it became known), ‘malum’ is {{مَعْلُوم}}! Bonus: {{عَالَمِين}} (the worlds) in Al-Fatiha uses the very same three letters ع ل م."},{"type":"table","title":{"bn":"পরিবার ৩: ح م د (প্রশংসা)","en":"Family 3: ح م د (praise)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["حَمِدَ",{"bn":"সে প্রশংসা করল","en":"he praised"}],["حَمْد",{"bn":"প্রশংসা","en":"praise"}],["حَامِد",{"bn":"প্রশংসাকারী","en":"one who praises"}],["مَحْمُود",{"bn":"প্রশংসিত","en":"praised"}],["حَمِيد",{"bn":"প্রশংসার যোগ্য (আল্লাহর নাম)","en":"Praiseworthy (name of Allah)"}],["أَحْمَد",{"bn":"সবচেয়ে বেশি প্রশংসাকারী/প্রশংসিত (নবীজির নাম)","en":"most praising / most praised (a name of the Prophet)"}],["مُحَمَّد",{"bn":"বারবার প্রশংসিত (নবীজির নাম)","en":"the much-praised (the Prophet's name)"}]]},{"type":"vocab","title":{"bn":"ح م د পরিবার","en":"The ح م د family"},"items":[{"ar":"مُحَمَّد","tr":{"bn":"মুহাম্মাদ","en":"muḥammad"},"mean":{"bn":"মুহাম্মাদ ﷺ — বারবার প্রশংসিত","en":"Muhammad ﷺ — the much-praised"},"root":"ح م د","example":{"ar":"مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلٰكِنْ رَسُولَ اللّٰهِ وَخَاتَمَ النَّبِيِّينَ","mean":{"bn":"মুহাম্মাদ তোমাদের কোনো পুরুষের পিতা নন, বরং তিনি আল্লাহর রাসূল ও শেষ নবী","en":"Muhammad is not the father of any of your men, but the Messenger of Allah and the Seal of the Prophets"},"ref":"33:40"}},{"ar":"أَحْمَد","tr":{"bn":"আহমাদ","en":"aḥmad"},"mean":{"bn":"আহমাদ — নবীজির আরেক নাম","en":"Ahmad — another name of the Prophet"},"root":"ح م د","example":{"ar":"وَمُبَشِّرًا بِرَسُولٍ يَأْتِي مِنْ بَعْدِي اسْمُهُ أَحْمَدُ","mean":{"bn":"আর এমন এক রাসূলের সুসংবাদদাতা, যিনি আমার পরে আসবেন, তাঁর নাম আহমাদ","en":"and bringing good news of a messenger after me whose name is Ahmad"},"ref":"61:6"}},{"ar":"مَحْمُود","tr":{"bn":"মাহমূদ","en":"maḥmood"},"mean":{"bn":"প্রশংসিত","en":"praised, praiseworthy"},"root":"ح م د","example":{"ar":"عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا","mean":{"bn":"আশা করা যায়, তোমার রব তোমাকে এক প্রশংসিত স্থানে পৌঁছাবেন","en":"It is expected that your Lord will raise you to a praised station"},"ref":"17:79"}}]},{"type":"table","title":{"bn":"পরিবার ৪: ر ح م (দয়া)","en":"Family 4: ر ح م (mercy)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["رَحِمَ",{"bn":"সে দয়া করল","en":"he had mercy"}],["رَحْمَة",{"bn":"দয়া, রহমত","en":"mercy"}],["رَحْمٰن",{"bn":"পরম দয়াময়","en":"the Most Merciful"}],["رَحِيم",{"bn":"পরম দয়ালু","en":"the Especially Merciful"}],["أَرْحَم",{"bn":"সবচেয়ে দয়ালু","en":"most merciful"}],["رَاحِمِين",{"bn":"দয়াশীলরা","en":"those who show mercy"}],["أَرْحَام",{"bn":"মাতৃগর্ভ; আত্মীয়তার বন্ধন","en":"wombs; ties of kinship"}]]},{"type":"vocab","title":{"bn":"ر ح م পরিবার","en":"The ر ح م family"},"items":[{"ar":"رَحِمَ","tr":{"bn":"রাহিমা","en":"raḥima"},"mean":{"bn":"সে দয়া করল","en":"he had mercy"},"root":"ر ح م","example":{"ar":"إِلَّا مَنْ رَحِمَ رَبُّكَ","mean":{"bn":"তবে তারা ছাড়া, যাদের প্রতি তোমার রব দয়া করেছেন","en":"except those on whom your Lord has mercy"},"ref":"11:119"}},{"ar":"أَرْحَم","tr":{"bn":"আরহাম","en":"arḥam"},"mean":{"bn":"সবচেয়ে দয়ালু","en":"most merciful"},"root":"ر ح م","example":{"ar":"وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","mean":{"bn":"আর তুমিই দয়ালুদের মধ্যে সবচেয়ে দয়ালু","en":"and You are the Most Merciful of the merciful"},"ref":"21:83"}},{"ar":"رَاحِمِين","tr":{"bn":"রাহিমীন","en":"raaḥimeen"},"mean":{"bn":"দয়াশীলরা","en":"those who show mercy"},"root":"ر ح م","example":{"ar":"وَقُلْ رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرَّاحِمِينَ","mean":{"bn":"আর বলো, হে আমার রব, ক্ষমা করো ও দয়া করো, তুমিই শ্রেষ্ঠ দয়ালু","en":"And say, ‘My Lord, forgive and have mercy, for You are the best of the merciful’"},"ref":"23:118"}}]},{"type":"tip","kind":"fun","bn":"{{رَحِم}} শব্দের এক অর্থ **মাতৃগর্ভ**। মায়ের গর্ভ যেভাবে সন্তানকে ঘিরে রাখে, রক্ষা করে, যত্ন দেয় — ‘রহমত’ শব্দের ভেতরে সেই কোমলতার ছোঁয়া আছে। আর আল্লাহর রহমত তার চেয়েও অনেক অনেক বেশি!","en":"One meaning of {{رَحِم}} is **womb**. Just as a mother's womb surrounds, protects and nurtures a child, the word ‘mercy’ carries that tenderness — and Allah's mercy is far, far greater still!"},{"type":"table","title":{"bn":"পরিবার ৫: س ل م (শান্তি, নিরাপত্তা, আত্মসমর্পণ)","en":"Family 5: س ل م (peace, safety, submission)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["سَلَام",{"bn":"শান্তি, সালাম","en":"peace, greeting of peace"}],["سَلِيم",{"bn":"নিরাপদ, নিখুঁত, সুস্থ","en":"sound, safe, pure"}],["أَسْلَمَ",{"bn":"সে আত্মসমর্পণ করল","en":"he submitted"}],["إِسْلَام",{"bn":"আত্মসমর্পণ, ইসলাম","en":"submission, Islam"}],["مُسْلِم",{"bn":"আত্মসমর্পণকারী, মুসলিম","en":"one who submits, Muslim"}]]},{"type":"vocab","title":{"bn":"س ل م পরিবার","en":"The س ل م family"},"items":[{"ar":"سَلَام","tr":{"bn":"সালাম","en":"salaam"},"mean":{"bn":"শান্তি, সালাম","en":"peace"},"root":"س ل م","example":{"ar":"سَلَامٌ هِيَ حَتَّى مَطْلَعِ الْفَجْرِ","mean":{"bn":"শান্তিময় সেই রাত, ফজর উদয় পর্যন্ত","en":"Peace it is, until the rise of dawn"},"ref":"97:5"}},{"ar":"أَسْلَمَ","tr":{"bn":"আসলামা","en":"aslama"},"mean":{"bn":"সে আত্মসমর্পণ করল, ইসলাম গ্রহণ করল","en":"he submitted, accepted Islam"},"root":"س ل م","example":{"ar":"إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ","mean":{"bn":"যখন তার রব তাকে বললেন, আত্মসমর্পণ করো; সে বলল, আমি সৃষ্টিজগতের রবের কাছে আত্মসমর্পণ করলাম","en":"When his Lord said to him, ‘Submit’, he said, ‘I submit to the Lord of the worlds’"},"ref":"2:131"}},{"ar":"سَلِيم","tr":{"bn":"সালীম","en":"saleem"},"mean":{"bn":"নিরাপদ, পরিশুদ্ধ, সুস্থ","en":"sound, pure"},"root":"س ل م","example":{"ar":"إِلَّا مَنْ أَتَى اللّٰهَ بِقَلْبٍ سَلِيمٍ","mean":{"bn":"তবে সে ছাড়া, যে আল্লাহর কাছে পরিশুদ্ধ অন্তর নিয়ে আসবে","en":"except one who comes to Allah with a sound heart"},"ref":"26:89"}}]},{"type":"text","title":{"bn":"ছাঁচের শক্তি: {{فَاعِل}} ও {{مَفْعُول}}","en":"Pattern power: {{فَاعِل}} and {{مَفْعُول}}"},"bn":"আরবি ব্যাকরণে মূল অক্ষর বোঝাতে ف ع ل (করা) ব্যবহার করা হয়। মূল অক্ষর তিনটিকে {{فَاعِل}} ছাঁচে বসালে পাই **যে করে** (কর্তা), আর {{مَفْعُول}} ছাঁচে বসালে পাই **যার উপর করা হয়েছে** (কর্ম)। একবার ছাঁচ চিনলে অচেনা শব্দেরও অর্থ আন্দাজ করা যায়! (নিচের টেবিলের কিছু রূপ — যেমন {{مَخْلُوق}}, {{مَعْبُود}}, {{غَاضِب}} — কুরআনে এভাবে আসেনি; শুধু ছাঁচ বোঝাতে দেওয়া হলো।)","en":"Arabic grammar uses ف ع ل (to do) to stand for any three root letters. Put a root into the {{فَاعِل}} pattern and you get **the one who does** (doer); put it into {{مَفْعُول}} and you get **the one it is done to** (done-to). Once you know the pattern, you can guess the meaning of new words! (A few forms in the table below — such as {{مَخْلُوق}}, {{مَعْبُود}}, {{غَاضِب}} — do not occur in the Quran in this form; they are shown only to illustrate the pattern.)"},{"type":"table","title":{"bn":"এক মূল, দুই ছাঁচ","en":"One root, two patterns"},"head":[{"bn":"মূল","en":"Root"},{"bn":"فَاعِل (যে করে)","en":"فَاعِل (doer)"},{"bn":"مَفْعُول (যাকে করা হয়)","en":"مَفْعُول (done-to)"}],"rows":[["ك ت ب","كَاتِب","مَكْتُوب"],["ع ل م","عَالِم","مَعْلُوم"],["خ ل ق","خَالِق","مَخْلُوق"],["ح م د","حَامِد","مَحْمُود"],["ش ك ر","شَاكِر","مَشْكُور"],["ظ ل م","ظَالِم","مَظْلُوم"],["ع ب د","عَابِد","مَعْبُود"],["غ ض ب","غَاضِب","مَغْضُوب"]]},{"type":"vocab","title":{"bn":"ছাঁচ চিনে নাও","en":"Recognise the patterns"},"items":[{"ar":"شَاكِر","tr":{"bn":"শাকির","en":"shaakir"},"mean":{"bn":"কৃতজ্ঞ, যে শোকর করে","en":"grateful, one who thanks"},"root":"ش ك ر","example":{"ar":"إِنَّا هَدَيْنَاهُ السَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا","mean":{"bn":"আমি তাকে পথ দেখিয়েছি — হয় সে কৃতজ্ঞ হবে, নয়তো অকৃতজ্ঞ","en":"We guided him to the way, be he grateful or ungrateful"},"ref":"76:3"}},{"ar":"مَشْكُور","tr":{"bn":"মাশকূর","en":"mashkoor"},"mean":{"bn":"যার কদর করা হয়েছে, গৃহীত","en":"appreciated, accepted with thanks"},"root":"ش ك ر","example":{"ar":"إِنَّ هٰذَا كَانَ لَكُمْ جَزَاءً وَكَانَ سَعْيُكُمْ مَشْكُورًا","mean":{"bn":"নিশ্চয়ই এটি তোমাদের প্রতিদান, আর তোমাদের চেষ্টা কবুল হয়েছে","en":"Indeed, this is a reward for you, and your effort has been appreciated"},"ref":"76:22"}}]},{"type":"tip","kind":"tip","bn":"এখন ফাতিহার {{مَغْضُوب}} শব্দটি আবার দেখো: মূল غ ض ب (রাগ), ছাঁচ {{مَفْعُول}} — তাই অর্থ ‘যার উপর রাগ করা হয়েছে’। আর বাংলার **মাখলুক** (সৃষ্টি) = {{مَخْلُوق}}, **খালিক** (স্রষ্টা) = {{خَالِق}}, **জালিম-মজলুম** = {{ظَالِم}}-{{مَظْلُوم}}, **মাবুদ** = {{مَعْبُود}}। দেখলে তো, ছাঁচ জানলে শব্দ নিজেই অর্থ বলে দেয়!","en":"Now look again at {{مَغْضُوب}} from Al-Fatiha: root غ ض ب (anger), pattern {{مَفْعُول}} — so it means ‘one who has been angered against’. And Bangla **makhluk** (creation) = {{مَخْلُوق}}, **khalik** (Creator) = {{خَالِق}}, **jalim–majlum** (oppressor–oppressed) = {{ظَالِم}}–{{مَظْلُوم}}, **mabud** = {{مَعْبُود}}. See? Know the pattern and the word tells you its meaning!"},{"type":"practice","bn":"প্রতিটি সারিতে একই মূলের শব্দগুলো জোরে পড়ো এবং মনে মনে অর্থ বলো।","en":"Read each row of same-root words aloud and recall the meanings.","lines":["كَتَبَ كِتَاب كُتُب كَاتِب مَكْتُوب","عَلِمَ عِلْم عَالِم عُلَمَاء عَلِيم مَعْلُوم","حَمِدَ حَمْد مَحْمُود حَمِيد أَحْمَد مُحَمَّد","رَحِمَ رَحْمَة رَحْمٰن رَحِيم أَرْحَم","سَلَام سَلِيم أَسْلَمَ إِسْلَام مُسْلِم"]},{"type":"quiz","items":[{"q":{"bn":"{{مَكْتُوب}} মানে কী?","en":"What does {{مَكْتُوب}} mean?"},"ar":"مَكْتُوب","options":[{"bn":"লেখক","en":"writer"},{"bn":"লিখিত","en":"written"},{"bn":"বই","en":"book"}],"answer":1},{"q":{"bn":"‘লেখক’ আরবিতে —","en":"‘Writer’ in Arabic —"},"options":["كِتَاب","كَاتِب","كُتُب","مَكْتُوب"],"answer":1},{"q":{"bn":"{{رَحْمَة}}, {{رَحِيم}}, {{أَرْحَم}} — মূল অক্ষর কী?","en":"What root do {{رَحْمَة}}, {{رَحِيم}}, {{أَرْحَم}} share?"},"options":["ر ح م","ح م د","ر ب ب"],"answer":0},{"q":{"bn":"{{فَاعِل}} ছাঁচ সাধারণত কী বোঝায়?","en":"What does the {{فَاعِل}} pattern usually mean?"},"options":[{"bn":"যে কাজটি করে","en":"the one who does"},{"bn":"যার উপর কাজ করা হয়েছে","en":"the one it is done to"},{"bn":"কাজের জায়গা","en":"place of the action"}],"answer":0},{"q":{"bn":"{{خَالِق}} = স্রষ্টা। তাহলে {{مَخْلُوق}} = ?","en":"{{خَالِق}} = Creator. So {{مَخْلُوق}} = ?"},"options":[{"bn":"সৃষ্টি (যাকে সৃষ্টি করা হয়েছে)","en":"created being"},{"bn":"সৃষ্টি করা (কাজ)","en":"the act of creating"},{"bn":"আরেক স্রষ্টা","en":"another creator"}],"answer":0},{"q":{"bn":"{{عُلَمَاء}} মানে —","en":"{{عُلَمَاء}} means —"},"ar":"عُلَمَاء","options":[{"bn":"জগৎসমূহ","en":"worlds"},{"bn":"আলেমগণ, জ্ঞানীরা","en":"scholars"},{"bn":"জ্ঞান","en":"knowledge"}],"answer":1},{"q":{"bn":"‘মুহাম্মাদ’ নামটি কোন মূল থেকে?","en":"The name ‘Muhammad’ comes from which root?"},"options":["ح م د","م ح ن","ح م ل"],"answer":0,"explain":{"bn":"{{مُحَمَّد}}, {{أَحْمَد}}, {{مَحْمُود}}, {{حَمْد}} — সবই ح م د (প্রশংসা)।","en":"{{مُحَمَّد}}, {{أَحْمَد}}, {{مَحْمُود}}, {{حَمْد}} — all from ح م د (praise)."}},{"q":{"bn":"বাংলা ‘মক্তব’ শব্দটি কোন পরিবারের?","en":"Bangla ‘moktob’ belongs to which family?"},"options":["ك ت ب","ع ل م","س ل م"],"answer":0},{"q":{"bn":"{{سَلِيم}} — {{بِقَلْبٍ سَلِيمٍ}} মানে কেমন অন্তর?","en":"{{بِقَلْبٍ سَلِيمٍ}} — what kind of heart?"},"options":[{"bn":"পরিশুদ্ধ, সুস্থ অন্তর","en":"a sound, pure heart"},{"bn":"কঠিন অন্তর","en":"a hard heart"},{"bn":"দুঃখী অন্তর","en":"a sad heart"}],"answer":0},{"q":{"bn":"{{شَاكِر}} মানে কী?","en":"What does {{شَاكِر}} mean?"},"ar":"شَاكِر","options":[{"bn":"কৃতজ্ঞ","en":"grateful"},{"bn":"অকৃতজ্ঞ","en":"ungrateful"},{"bn":"ধৈর্যশীল","en":"patient"}],"answer":0}]}]}]});
AQ.units.push({"id":"grammar","order":5,"icon":"ن","color":"indigo","title":{"bn":"সহজ আরবি ব্যাকরণ","en":"Grammar Made Easy"},"subtitle":{"bn":"কুরআনের বাক্য কীভাবে গঠিত হয় — ধাপে ধাপে, সহজ উদাহরণে","en":"How Quranic sentences are built — step by step, with easy examples"},"lessons":[{"id":"g-word-types","icon":"ك","title":{"bn":"শব্দের তিন জাত: ইসম, ফে'ল, হরফ","en":"Three Kinds of Words: Ism, Fi'l, Harf"},"subtitle":{"bn":"আরবির প্রতিটি শব্দ এই তিন দলের কোনো একটিতে পড়ে","en":"Every Arabic word belongs to one of three families"},"minutes":12,"goals":[{"bn":"ইসম, ফে'ল ও হরফ কী — তা জানবে","en":"Know what ism, fi'l and harf are"},{"bn":"প্রতিটি চেনার সহজ আলামত (চিহ্ন) শিখবে","en":"Learn easy signs to recognise each one"},{"bn":"কুরআনের আয়াতের শব্দগুলোকে তিন দলে ভাগ করতে পারবে","en":"Sort the words of a real ayah into their families"}],"blocks":[{"type":"text","bn":"স্বাগতম ব্যাকরণের জগতে! ভয় পাওয়ার কিছু নেই — আরবি ব্যাকরণের শুরুটা খুব সহজ। বাংলায় আমরা বিশেষ্য, বিশেষণ, সর্বনাম, ক্রিয়া, অব্যয় — কত ভাগ শিখি! আরবিতে শব্দের ভাগ মাত্র **তিনটি**: **ইসম**, **ফে'ল** আর **হরফ**।","en":"Welcome to grammar! Nothing to fear — Arabic grammar starts very simply. In English we learn nouns, adjectives, pronouns, verbs, prepositions... Arabic has only **three** word families: **ism**, **fi'l** and **harf**."},{"type":"table","title":{"bn":"এক নজরে তিন জাত","en":"The three families at a glance"},"head":[{"bn":"জাত","en":"Family"},{"bn":"আরবি নাম","en":"Arabic name"},{"bn":"কী বোঝায়","en":"What it is"},{"bn":"উদাহরণ","en":"Examples"}],"rows":[[{"bn":"ইসম","en":"Ism"},"اِسْمٌ",{"bn":"নাম-শব্দ: ব্যক্তি, বস্তু, স্থান, গুণ (বাংলার বিশেষ্য, বিশেষণ, সর্বনাম — সব এখানে)","en":"Naming word: person, thing, place, quality (nouns, adjectives and pronouns all live here)"},"اللّٰهُ ، كِتَابٌ ، رَحِيمٌ ، هُوَ"],[{"bn":"ফে'ল","en":"Fi'l"},"فِعْلٌ",{"bn":"কাজ-শব্দ, যার ভেতরে সময় (অতীত / বর্তমান / আদেশ) লুকানো থাকে","en":"Action word with time built in (past / present / command)"},"خَلَقَ ، يَعْلَمُ ، اِقْرَأْ"],[{"bn":"হরফ","en":"Harf"},"حَرْفٌ",{"bn":"সংযোগ-শব্দ; একা পূর্ণ অর্থ দেয় না, অন্য শব্দকে জুড়ে দেয়","en":"Linking word; no full meaning alone, it connects other words"},"فِي ، مِنْ ، عَلٰى ، وَ ، لَمْ"]]},{"type":"tip","kind":"memory","bn":"একটা ঘর বানানোর কথা ভাবো: **ইসম** হলো ইট (জিনিস), **ফে'ল** হলো মিস্ত্রির কাজ (ঘটনা), আর **হরফ** হলো সিমেন্ট — যা ইটগুলোকে জুড়ে রাখে।","en":"Think of building a house: **ism** is the bricks (things), **fi'l** is the builder's work (events), and **harf** is the cement that holds the bricks together."},{"type":"examples","title":{"bn":"ইসম চেনার আলামত","en":"Signs of an ism"},"items":[{"ar":"اَلْكِتَابُ","tr":{"bn":"আল-কিতাবু","en":"al-kitābu"},"mean":{"bn":"বইটি","en":"the book"},"note":{"bn":"শুরুতে {{اَلْ}} বসতে পারে — তাই ইসম","en":"It can take {{اَلْ}} 'the' — so it is an ism"},"hl":"اَلْ"},{"ar":"كِتَابٌ","tr":{"bn":"কিতাবুন","en":"kitābun"},"mean":{"bn":"একটি বই","en":"a book"},"note":{"bn":"শেষে তানবীন আছে — তাই ইসম","en":"It ends in tanween — so it is an ism"},"hl":"بٌ"},{"ar":"فِي الْأَرْضِ","tr":{"bn":"ফিল-আরদ্বি","en":"fil-arḍi"},"mean":{"bn":"পৃথিবীতে","en":"in the earth"},"note":{"bn":"{{فِي}}-এর মতো হরফে জারের পরে এসেছে — তাই ইসম","en":"It comes after a preposition like {{فِي}} — so it is an ism"},"hl":"الْأَرْضِ"},{"ar":"يَا أَيُّهَا النَّاسُ","tr":{"bn":"ইয়া আইয়ুহান-নাস","en":"yā ayyuhan-nās"},"mean":{"bn":"হে মানুষ!","en":"O mankind!"},"note":{"bn":"ডাকার শব্দ {{يَا}}-এর পরে আসে — তাই ইসম","en":"It is called with {{يَا}} 'O' — so it is an ism"},"hl":"النَّاسُ"}]},{"type":"examples","title":{"bn":"ফে'ল চেনার আলামত","en":"Signs of a fi'l"},"items":[{"ar":"قَدْ أَفْلَحَ الْمُؤْمِنُونَ","tr":{"bn":"কদ আফলাহাল মু'মিনূন","en":"qad aflaḥal-mu'minūn"},"mean":{"bn":"অবশ্যই মুমিনরা সফল হয়েছে (২৩:১)","en":"The believers have certainly succeeded (23:1)"},"note":{"bn":"আগে {{قَدْ}} বসেছে — এটি শুধু ফে'লের আগে বসে","en":"{{قَدْ}} comes before it — it only sits before verbs"},"hl":"أَفْلَحَ"},{"ar":"كَلَّا سَوْفَ تَعْلَمُونَ","tr":{"bn":"কাল্লা সাওফা তা'লামূন","en":"kallā sawfa ta'lamūn"},"mean":{"bn":"কখনো না, শীঘ্রই তোমরা জানবে (১০২:৩)","en":"No! You will soon know (102:3)"},"note":{"bn":"আগে {{سَوْفَ}} (ভবিষ্যৎ) — তাই ফে'ল","en":"{{سَوْفَ}} (future) before it — so it is a verb"},"hl":"تَعْلَمُونَ"},{"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","tr":{"bn":"লাম ইয়ালিদ ওয়া লাম ইউলাদ","en":"lam yalid wa lam yūlad"},"mean":{"bn":"তিনি জন্ম দেননি, জন্মও নেননি (১১২:৩)","en":"He neither begets nor was begotten (112:3)"},"note":{"bn":"আগে {{لَمْ}} — এটিও শুধু ফে'লের আগে বসে","en":"{{لَمْ}} before it — it only comes before verbs"},"hl":"يَلِدْ"},{"ar":"كَذَّبَتْ ثَمُودُ","tr":{"bn":"কাযযাবাত সামূদ","en":"kadhdhabat thamūd"},"mean":{"bn":"সামূদ জাতি অস্বীকার করেছিল (৯১:১১)","en":"Thamud denied (91:11)"},"note":{"bn":"শেষে সাকিন {{تْ}} (স্ত্রীলিঙ্গের চিহ্ন) — অতীত ফে'ল","en":"Ends in a still {{تْ}} (feminine sign) — a past verb"},"hl":"كَذَّبَتْ"}]},{"type":"text","title":{"bn":"হরফ চেনার উপায়","en":"How to spot a harf"},"bn":"যে শব্দে ইসমের কোনো আলামত নেই, ফে'লেরও কোনো আলামত নেই — সেটাই **হরফ**। হরফে {{اَلْ}} বসে না, তানবীন হয় না, সময়ও বোঝায় না। যেমন: {{فِي}} (মধ্যে), {{مِنْ}} (থেকে), {{إِلٰى}} (দিকে), {{عَلٰى}} (উপর), {{وَ}} (এবং), {{ثُمَّ}} (তারপর), {{إِنَّ}} (নিশ্চয়ই), {{لَمْ}} (না), {{هَلْ}} (কি?)।","en":"A word with no sign of an ism and no sign of a verb is a **harf**. It never takes {{اَلْ}}, never takes tanween and carries no time. For example: {{فِي}} (in), {{مِنْ}} (from), {{إِلٰى}} (to), {{عَلٰى}} (on), {{وَ}} (and), {{ثُمَّ}} (then), {{إِنَّ}} (indeed), {{لَمْ}} (did not), {{هَلْ}} (is it?)."},{"type":"tip","kind":"warn","bn":"কিছু হরফ এক অক্ষরের, আর সেগুলো পরের শব্দের সঙ্গে **জোড়া লেগে** থাকে: {{بِـ}} (দিয়ে), {{لِـ}} (জন্য), {{وَ}} (এবং), {{فَـ}} (তাই), {{كَـ}} (মতো)। যেমন {{بِسْمِ}} = {{بِ}} + {{اسْمِ}}। তাই একটা শব্দের মতো দেখালেও ভেতরে দুটো শব্দ থাকতে পারে!","en":"Some harfs are a single letter and stay **glued** to the next word: {{بِـ}} (with), {{لِـ}} (for), {{وَ}} (and), {{فَـ}} (so), {{كَـ}} (like). For example {{بِسْمِ}} = {{بِ}} + {{اسْمِ}}. So one 'word' on the page can hide two words inside!"},{"type":"table","title":{"bn":"একটি আয়াত ভেঙে দেখি (৯৬:২)","en":"Let's split an ayah (96:2)"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"},{"bn":"জাত","en":"Family"}],"rows":[["خَلَقَ",{"bn":"তিনি সৃষ্টি করেছেন","en":"He created"},{"bn":"ফে'ল (অতীত কাজ)","en":"Fi'l (past action)"}],["الْإِنْسَانَ",{"bn":"মানুষকে","en":"man / mankind"},{"bn":"ইসম ({{الْ}} আছে)","en":"Ism (has {{الْ}})"}],["مِنْ",{"bn":"থেকে","en":"from"},{"bn":"হরফ","en":"Harf"}],["عَلَقٍ",{"bn":"জমাট রক্তপিণ্ড","en":"a clinging clot"},{"bn":"ইসম (তানবীন আছে)","en":"Ism (has tanween)"}]]},{"type":"tip","kind":"fun","bn":"কুরআনের প্রথম শব্দগুলোর একটি {{بِسْمِ}}-এর ভেতরেই {{اِسْم}} শব্দটি লুকিয়ে আছে — যার অর্থ ‘নাম’। তাই ইসম মানে আক্ষরিক অর্থেই ‘নাম-শব্দ’!","en":"Hidden inside {{بِسْمِ}}, at the very start of the Quran, is the word {{اِسْم}} — meaning 'name'. So an ism is literally a 'name-word'!"},{"type":"quiz","items":[{"q":{"bn":"আরবিতে শব্দ মোট কয় প্রকার?","en":"How many kinds of words are there in Arabic?"},"options":[{"bn":"পাঁচ","en":"Five"},{"bn":"দুই","en":"Two"},{"bn":"তিন","en":"Three"},{"bn":"আট","en":"Eight"}],"answer":2},{"q":{"bn":"এই শব্দটি কোন জাতের?","en":"Which family is this word?"},"ar":"اَلرَّحِيمُ","options":[{"bn":"হরফ","en":"Harf"},{"bn":"ইসম","en":"Ism"},{"bn":"ফে'ল","en":"Fi'l"}],"answer":1,"explain":{"bn":"শুরুতে {{اَلْ}} আছে — এটি ইসমের আলামত।","en":"It starts with {{اَلْ}} — a sign of an ism."}},{"q":{"bn":"এই শব্দটি কোন জাতের?","en":"Which family is this word?"},"ar":"عَلَّمَ","options":[{"bn":"ইসম","en":"Ism"},{"bn":"হরফ","en":"Harf"},{"bn":"ফে'ল","en":"Fi'l"}],"answer":2,"explain":{"bn":"অর্থ ‘তিনি শিখিয়েছেন’ — অতীত কালের কাজ, তাই ফে'ল।","en":"It means 'he taught' — an action in past time, so a fi'l."}},{"q":{"bn":"এই শব্দটি কোন জাতের?","en":"Which family is this word?"},"ar":"عَلٰى","options":[{"bn":"হরফ","en":"Harf"},{"bn":"ফে'ল","en":"Fi'l"},{"bn":"ইসম","en":"Ism"}],"answer":0,"explain":{"bn":"{{عَلٰى}} মানে ‘উপর’ — একা পূর্ণ অর্থ দেয় না, তাই হরফ।","en":"{{عَلٰى}} means 'on' — no full meaning alone, so a harf."}},{"q":{"bn":"কোনটি ফে'লের আলামত?","en":"Which one is a sign of a verb?"},"options":[{"bn":"আগে {{قَدْ}} বা {{لَمْ}}","en":"{{قَدْ}} or {{لَمْ}} before it"},{"bn":"শেষে তানবীন","en":"Tanween at the end"},{"bn":"শুরুতে {{اَلْ}}","en":"{{اَلْ}} at the start"},{"bn":"আগে {{فِي}}","en":"{{فِي}} before it"}],"answer":0},{"q":{"bn":"{{بِسْمِ}} শব্দে কয়টি শব্দ লুকিয়ে আছে?","en":"How many words are hidden in {{بِسْمِ}}?"},"ar":"بِسْمِ","options":[{"bn":"একটি","en":"One"},{"bn":"দুটি: হরফ + ইসম","en":"Two: harf + ism"},{"bn":"দুটি: ফে'ল + ইসম","en":"Two: fi'l + ism"}],"answer":1,"explain":{"bn":"{{بِ}} (দিয়ে) হরফ + {{اسْمِ}} (নাম) ইসম।","en":"{{بِ}} (with) is a harf + {{اسْمِ}} (name) is an ism."}}]}]},{"id":"g-gender","icon":"ة","title":{"bn":"লিঙ্গ: পুরুষবাচক ও স্ত্রীবাচক","en":"Gender: Masculine and Feminine"},"subtitle":{"bn":"আরবিতে প্রতিটি ইসম হয় মুযাক্কার, নয়তো মুআন্নাস","en":"Every Arabic noun is either masculine or feminine"},"minutes":12,"goals":[{"bn":"মুযাক্কার (পুং) ও মুআন্নাস (স্ত্রী) চিনবে","en":"Recognise masculine (mudhakkar) and feminine (mu'annath) words"},{"bn":"গোল তা {{ة}} ও অন্যান্য স্ত্রীলিঙ্গ চিহ্ন জানবে","en":"Know round tā {{ة}} and other feminine signs"},{"bn":"চিহ্ন ছাড়া স্ত্রীলিঙ্গ শব্দও চিনবে","en":"Spot feminine words that have no sign"}],"blocks":[{"type":"text","bn":"বাংলায় আমরা বলি ছাত্র – ছাত্রী, শিক্ষক – শিক্ষিকা। আরবিতেও ঠিক তেমন — তবে আরবিতে **প্রতিটি** ইসমেরই লিঙ্গ আছে, এমনকি বই, সূর্য, আগুনেরও! পুরুষবাচককে বলে **মুযাক্কার** ({{مُذَكَّرٌ}}), স্ত্রীবাচককে বলে **মুআন্নাস** ({{مُؤَنَّثٌ}})।","en":"In English we have actor – actress, prince – princess. Arabic does the same — but in Arabic **every** noun has a gender, even a book, the sun or fire! Masculine is called **mudhakkar** ({{مُذَكَّرٌ}}), feminine is **mu'annath** ({{مُؤَنَّثٌ}})."},{"type":"tip","kind":"memory","bn":"সহজ সূত্র: মুযাক্কার শব্দের শেষে **গোল তা** {{ة}} লাগালেই সাধারণত মুআন্নাস হয়ে যায় — যেমন বাংলায় ‘ছাত্র’-এর সঙ্গে ‘ী’ লাগালে ‘ছাত্রী’।","en":"Easy rule: add a **round tā** {{ة}} to a masculine word and it usually becomes feminine — like adding '-ess' to 'prince' to get 'princess'."},{"type":"table","title":{"bn":"জোড়ায় জোড়ায় দেখি","en":"Pairs side by side"},"head":[{"bn":"মুযাক্কার (পুং)","en":"Masculine"},{"bn":"মুআন্নাস (স্ত্রী)","en":"Feminine"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["مُسْلِمٌ","مُسْلِمَةٌ",{"bn":"মুসলিম পুরুষ / মুসলিম নারী","en":"Muslim man / Muslim woman"}],["مُؤْمِنٌ","مُؤْمِنَةٌ",{"bn":"মুমিন পুরুষ / মুমিন নারী","en":"believing man / believing woman"}],["صَالِحٌ","صَالِحَةٌ",{"bn":"নেককার (পুং / স্ত্রী)","en":"righteous (m / f)"}],["كَبِيرٌ","كَبِيرَةٌ",{"bn":"বড় (পুং / স্ত্রী)","en":"big (m / f)"}],["مَلِكٌ","مَلِكَةٌ",{"bn":"রাজা / রানি","en":"king / queen"}]]},{"type":"tip","kind":"tip","bn":"গোল তা {{ة}} পড়ার নিয়ম: শব্দে **থামলে** ‘হ’ পড়ো — {{جَنَّةٌ}} → ‘জান্নাহ’। **মিলিয়ে পড়লে** ‘ত’ পড়ো — {{سُورَةُ الْفَاتِحَةِ}} → ‘সূরাতুল ফাতিহাহ’।","en":"Reading the round tā {{ة}}: when you **stop** on it, say 'h' — {{جَنَّةٌ}} → 'jannah'. When you **connect**, say 't' — {{سُورَةُ الْفَاتِحَةِ}} → 'sūratul-fātiḥah'."},{"type":"table","title":{"bn":"মুআন্নাস চেনার তিন পথ","en":"Three ways a word is feminine"},"head":[{"bn":"ধরন","en":"Type"},{"bn":"উদাহরণ","en":"Examples"},{"bn":"ব্যাখ্যা","en":"Explanation"}],"rows":[[{"bn":"১. চিহ্ন আছে","en":"1. Has a sign"},"جَنَّةٌ ، رَحْمَةٌ ، أُنْثٰى ، الْحُسْنٰى",{"bn":"শেষে {{ة}}, কখনো {{ـٰى}} বা {{ـَاءُ}}","en":"Ends in {{ة}}, sometimes {{ـٰى}} or {{ـَاءُ}}"}],[{"bn":"২. স্বভাবগত নারী","en":"2. Naturally female"},"أُمٌّ ، مَرْيَمُ ، زَيْنَبُ",{"bn":"চিহ্ন নেই, কিন্তু অর্থেই নারী","en":"No sign, but female by meaning"}],[{"bn":"৩. প্রচলনে মুআন্নাস","en":"3. Feminine by usage"},"شَمْسٌ ، أَرْضٌ ، نَارٌ ، نَفْسٌ ، دَارٌ",{"bn":"চিহ্ন নেই; আরবরা এগুলোকে স্ত্রীলিঙ্গ ধরে — মুখস্থ রাখতে হয়","en":"No sign; Arabs treat them as feminine — just memorise them"}]]},{"type":"tip","kind":"memory","bn":"চিহ্নহীন মুআন্নাস মনে রাখার ছড়া: **সূর্য, মাটি, আগুন, প্রাণ — ঘর আর হাত, চোখ সমান।** অর্থাৎ {{شَمْسٌ}}, {{أَرْضٌ}}, {{نَارٌ}}, {{نَفْسٌ}}, {{دَارٌ}}, {{يَدٌ}}, {{عَيْنٌ}} — সবাই মুআন্নাস। (শরীরের জোড়া অঙ্গগুলো সাধারণত মুআন্নাস।)","en":"A rhyme for sign-less feminines: **sun and earth and fire and soul, home and hand and eye — the whole!** That is {{شَمْسٌ}}, {{أَرْضٌ}}, {{نَارٌ}}, {{نَفْسٌ}}, {{دَارٌ}}, {{يَدٌ}}, {{عَيْنٌ}} — all feminine. (Paired body parts are usually feminine.)"},{"type":"examples","title":{"bn":"কুরআনে লিঙ্গের মিল","en":"Gender agreement in the Quran"},"items":[{"ar":"كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ","tr":{"bn":"কুল্লু নাফসিন যা-ইকাতুল মাওত","en":"kullu nafsin dhā'iqatul-mawt"},"mean":{"bn":"প্রত্যেক প্রাণ মৃত্যুর স্বাদ গ্রহণকারী (৩:১৮৫)","en":"Every soul will taste death (3:185)"},"note":{"bn":"{{نَفْسٌ}} মুআন্নাস, তাই {{ذَائِقَةُ}}-তেও {{ة}} এসেছে","en":"{{نَفْسٌ}} is feminine, so {{ذَائِقَةُ}} also takes {{ة}}"},"hl":"ذَائِقَةُ"},{"ar":"نَارٌ حَامِيَةٌ","tr":{"bn":"নারুন হামিয়াহ","en":"nārun ḥāmiyah"},"mean":{"bn":"উত্তপ্ত আগুন (১০১:১১)","en":"A blazing fire (101:11)"},"note":{"bn":"{{نَارٌ}} চিহ্নহীন মুআন্নাস, তাই বিশেষণ {{حَامِيَةٌ}} স্ত্রীলিঙ্গ","en":"{{نَارٌ}} is feminine without a sign, so the adjective {{حَامِيَةٌ}} is feminine"},"hl":"حَامِيَةٌ"},{"ar":"يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ","tr":{"bn":"ইয়া আইয়াতুহান নাফসুল মুত্বমা-ইন্নাহ","en":"yā ayyatuhan-nafsul-muṭma'innah"},"mean":{"bn":"হে প্রশান্ত আত্মা! (৮৯:২৭)","en":"O soul at peace! (89:27)"},"note":{"bn":"ডাকার শব্দও স্ত্রীলিঙ্গ হয়েছে: {{أَيُّهَا}} নয়, {{أَيَّتُهَا}}","en":"Even the calling word turned feminine: {{أَيَّتُهَا}} instead of {{أَيُّهَا}}"},"hl":"أَيَّتُهَا"},{"ar":"وَالشَّمْسِ وَضُحٰهَا","tr":{"bn":"ওয়াশ-শামসি ওয়া দুহা-হা","en":"wash-shamsi wa ḍuḥāhā"},"mean":{"bn":"শপথ সূর্যের ও তার আলোর (৯১:১)","en":"By the sun and its morning brightness (91:1)"},"note":{"bn":"সূর্যকে বোঝাতে {{هَا}} (তার — স্ত্রী) এসেছে, কারণ {{شَمْسٌ}} মুআন্নাস","en":"The sun is referred to with {{هَا}} ('her'), because {{شَمْسٌ}} is feminine"},"hl":"هَا"},{"ar":"إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ","tr":{"bn":"ইন্নাল মুসলিমীনা ওয়াল মুসলিমাত","en":"innal-muslimīna wal-muslimāt"},"mean":{"bn":"নিশ্চয়ই মুসলিম পুরুষ ও মুসলিম নারী… (৩৩:৩৫)","en":"Indeed, Muslim men and Muslim women... (33:35)"},"note":{"bn":"একই শব্দের পুং ও স্ত্রী রূপ পাশাপাশি","en":"Masculine and feminine forms of the same word side by side"}}]},{"type":"tip","kind":"tip","bn":"লিঙ্গ জানা জরুরি কেন? কারণ ইসম মুআন্নাস হলে তার বিশেষণ, সর্বনাম, এমনকি ক্রিয়াও বদলে যায়: {{هُوَ}} (সে – পুং) / {{هِيَ}} (সে – স্ত্রী), {{كَتَبَ}} (সে লিখল – পুং) / {{كَتَبَتْ}} (সে লিখল – স্ত্রী)।","en":"Why does gender matter? Because when a noun is feminine, its adjective, pronoun and even its verb change: {{هُوَ}} (he) / {{هِيَ}} (she), {{كَتَبَ}} (he wrote) / {{كَتَبَتْ}} (she wrote)."},{"type":"quiz","items":[{"q":{"bn":"{{مُؤْمِنٌ}}-এর স্ত্রীলিঙ্গ কোনটি?","en":"What is the feminine of {{مُؤْمِنٌ}}?"},"options":["مُؤْمِنُونَ","اَلْمُؤْمِنُ","مُؤْمِنَانِ","مُؤْمِنَةٌ"],"answer":3},{"q":{"bn":"স্ত্রীলিঙ্গের সবচেয়ে পরিচিত চিহ্ন কোনটি?","en":"What is the most common feminine sign?"},"options":[{"bn":"শুরুতে {{اَلْ}}","en":"{{اَلْ}} at the start"},{"bn":"শেষে {{ـُونَ}}","en":"{{ـُونَ}} at the end"},{"bn":"শেষে গোল তা {{ة}}","en":"Round tā {{ة}} at the end"}],"answer":2},{"q":{"bn":"কোনটি চিহ্ন ছাড়াই মুআন্নাস?","en":"Which one is feminine without any sign?"},"options":["بَيْتٌ","شَمْسٌ","كِتَابٌ","قَلَمٌ"],"answer":1,"explain":{"bn":"{{شَمْسٌ}} (সূর্য) প্রচলনে মুআন্নাস।","en":"{{شَمْسٌ}} (sun) is feminine by usage."}},{"q":{"bn":"{{جَنَّةٌ}} শব্দে থামলে শেষটা কীভাবে পড়বে?","en":"How do you pronounce the end of {{جَنَّةٌ}} when you stop?"},"ar":"جَنَّةٌ","options":[{"bn":"জান্নাহ","en":"jannah"},{"bn":"জান্নাতুন","en":"jannatun"},{"bn":"জান্নাত","en":"jannat"}],"answer":0},{"q":{"bn":"{{كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ}} — {{ذَائِقَةُ}}-তে {{ة}} কেন?","en":"In {{كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ}}, why does {{ذَائِقَةُ}} have {{ة}}?"},"options":[{"bn":"কারণ এটি বহুবচন","en":"Because it is plural"},{"bn":"কারণ {{نَفْسٌ}} মুআন্নাস","en":"Because {{نَفْسٌ}} is feminine"},{"bn":"কারণ এটি ফে'ল","en":"Because it is a verb"}],"answer":1},{"q":{"bn":"{{أُمٌّ}} (মা) শব্দটি কেমন?","en":"What is {{أُمٌّ}} (mother)?"},"options":[{"bn":"হরফ","en":"A harf"},{"bn":"মুযাক্কার","en":"Masculine"},{"bn":"স্বভাবগত মুআন্নাস","en":"Naturally feminine"}],"answer":2}]}]},{"id":"g-number","icon":"٣","title":{"bn":"বচন: এক, দুই, বহু","en":"Number: One, Two, Many"},"subtitle":{"bn":"আরবিতে ‘দুই’-এর জন্য আলাদা রূপ আছে!","en":"Arabic has a special form just for 'two'!"},"minutes":15,"goals":[{"bn":"মুফরাদ (এক), মুসান্না (দুই) ও জমা (বহু) চিনবে","en":"Recognise singular, dual and plural"},{"bn":"সালিম বহুবচনের শেষাংশ {{ـُونَ / ـِينَ}} ও {{ـَاتٌ}} চিনবে","en":"Spot sound plural endings {{ـُونَ / ـِينَ}} and {{ـَاتٌ}}"},{"bn":"কুরআনের পরিচিত ভাঙা বহুবচন শিখবে","en":"Learn common Quranic broken plurals"}],"blocks":[{"type":"text","bn":"বাংলায় আছে দুটি বচন: ‘মুসলিম’ আর ‘মুসলিমরা’। আরবিতে আছে **তিনটি**: একজন — **মুফরাদ** ({{مُفْرَدٌ}}), দুজন — **মুসান্না** ({{مُثَنًّى}}), আর তিন বা তার বেশি — **জমা** ({{جَمْعٌ}})।","en":"English has two numbers: 'Muslim' and 'Muslims'. Arabic has **three**: one — **mufrad** ({{مُفْرَدٌ}}), exactly two — **muthanna** ({{مُثَنًّى}}), and three or more — **jam'** ({{جَمْعٌ}})."},{"type":"table","title":{"bn":"দ্বিবচন (মুসান্না): শেষে {{ـَانِ}} বা {{ـَيْنِ}}","en":"The dual: add {{ـَانِ}} or {{ـَيْنِ}}"},"head":[{"bn":"এক","en":"One"},{"bn":"দুই (কর্তা হলে)","en":"Two (as subject)"},{"bn":"দুই (হরফের পরে / কর্ম হলে)","en":"Two (after a preposition / as object)"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["مُسْلِمٌ","مُسْلِمَانِ","مُسْلِمَيْنِ",{"bn":"মুসলিম","en":"Muslim"}],["كِتَابٌ","كِتَابَانِ","كِتَابَيْنِ",{"bn":"বই","en":"book"}],["جَنَّةٌ","جَنَّتَانِ","جَنَّتَيْنِ",{"bn":"বাগান / জান্নাত","en":"garden"}]]},{"type":"tip","kind":"warn","bn":"{{ة}} যুক্ত শব্দের দ্বিবচন করার সময় গোল তা খুলে **লম্বা ত** {{ت}} হয়ে যায়: {{جَنَّةٌ}} → {{جَنَّتَانِ}}।","en":"When a word with {{ة}} becomes dual, the round tā opens into a normal {{ت}}: {{جَنَّةٌ}} → {{جَنَّتَانِ}}."},{"type":"examples","title":{"bn":"সূরা আর-রহমানে দ্বিবচন","en":"Duals in Surah Ar-Rahman"},"items":[{"ar":"وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ","tr":{"bn":"ওয়া লিমান খাফা মাকামা রব্বিহী জান্নাতান","en":"wa liman khāfa maqāma rabbihī jannatān"},"mean":{"bn":"যে তার রবের সামনে দাঁড়ানোর ভয় করে, তার জন্য আছে দুটি জান্নাত (৫৫:৪৬)","en":"For whoever fears standing before his Lord are two gardens (55:46)"},"hl":"جَنَّتَانِ"},{"ar":"رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ","tr":{"bn":"রব্বুল মাশরিকাইনি ওয়া রব্বুল মাগরিবাইন","en":"rabbul-mashriqayni wa rabbul-maghribayn"},"mean":{"bn":"তিনি দুই উদয়াচল ও দুই অস্তাচলের রব (৫৫:১৭)","en":"Lord of the two easts and Lord of the two wests (55:17)"},"note":{"bn":"এখানে {{ـَيْنِ}} রূপ, কারণ শব্দটি মুযাফ ইলাইহি (যের অবস্থা)","en":"The {{ـَيْنِ}} form, because the word is in the genitive (after rabb)"},"hl":"الْمَشْرِقَيْنِ"}]},{"type":"table","title":{"bn":"সালিম (অক্ষত) বহুবচন — শুধু শেষে যোগ","en":"Sound plurals — just add an ending"},"head":[{"bn":"ধরন","en":"Type"},{"bn":"কর্তা হলে","en":"As subject"},{"bn":"হরফের পরে / কর্ম হলে","en":"After a preposition / as object"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"পুরুষ বহুবচন","en":"Masculine plural"},"ـُونَ","ـِينَ","مُسْلِمُونَ / مُسْلِمِينَ"],[{"bn":"স্ত্রী বহুবচন","en":"Feminine plural"},"ـَاتٌ","ـَاتٍ","مُسْلِمَاتٌ / مُسْلِمَاتٍ"]]},{"type":"examples","title":{"bn":"এই শব্দগুলো তুমি নামাজেই রোজ পড়ো!","en":"You read these every day in salah!"},"items":[{"ar":"رَبِّ الْعٰلَمِينَ","tr":{"bn":"রব্বিল আলামীন","en":"rabbil-'ālamīn"},"mean":{"bn":"সকল জগতের রব (১:২)","en":"Lord of all the worlds (1:2)"},"note":{"bn":"{{ـِينَ}} — পুরুষ সালিম বহুবচন","en":"{{ـِينَ}} — sound masculine plural"},"hl":"الْعٰلَمِينَ"},{"ar":"وَلَا الضَّالِّينَ","tr":{"bn":"ওয়ালাদ-দ্বাল্লীন","en":"wa laḍ-ḍāllīn"},"mean":{"bn":"এবং পথভ্রষ্টদের (পথও) নয় (১:৭)","en":"nor of those astray (1:7)"},"hl":"الضَّالِّينَ"},{"ar":"هُدًى لِلْمُتَّقِينَ","tr":{"bn":"হুদাল লিল মুত্তাকীন","en":"hudal-lil-muttaqīn"},"mean":{"bn":"মুত্তাকীদের জন্য পথনির্দেশ (২:২)","en":"guidance for the God-conscious (2:2)"},"hl":"لِلْمُتَّقِينَ"},{"ar":"وَأُولٰئِكَ هُمُ الْمُفْلِحُونَ","tr":{"bn":"ওয়া উলা-ইকা হুমুল মুফলিহূন","en":"wa ulā'ika humul-mufliḥūn"},"mean":{"bn":"আর তারাই সফলকাম (২:৫)","en":"and it is they who are the successful (2:5)"},"note":{"bn":"{{ـُونَ}} — কর্তা/খবর অবস্থায়","en":"{{ـُونَ}} — subject/predicate position"},"hl":"الْمُفْلِحُونَ"},{"ar":"وَعَمِلُوا الصَّالِحَاتِ","tr":{"bn":"ওয়া আমিলুস সা-লিহাত","en":"wa 'amiluṣ-ṣāliḥāt"},"mean":{"bn":"এবং সৎকর্ম করেছে (১০৩:৩)","en":"and did righteous deeds (103:3)"},"note":{"bn":"{{ـَاتِ}} — স্ত্রী সালিম বহুবচন","en":"{{ـَاتِ}} — sound feminine plural"},"hl":"الصَّالِحَاتِ"}]},{"type":"tip","kind":"memory","bn":"‘উন’ উঁচুতে, ‘ঈন’ নিচে: কর্তা (রাজার আসনে) থাকলে পেশ-এর {{ـُونَ}}; হরফের নিচে বা কর্ম হলে যের-এর {{ـِينَ}}। দ্বিবচনেও তাই: {{ـَانِ}} উপরে, {{ـَيْنِ}} নিচে।","en":"'-ūn' up, '-īn' down: as the subject (on the throne) use {{ـُونَ}}; after a preposition or as an object use {{ـِينَ}}. Same with duals: {{ـَانِ}} up, {{ـَيْنِ}} down."},{"type":"text","title":{"bn":"ভাঙা বহুবচন (জমা মুকাসসার)","en":"Broken plurals (jam' mukassar)"},"bn":"কুরআনের অনেক বহুবচন শেষে কিছু যোগ করে হয় না — শব্দের **ভেতরটা ভেঙে নতুন ছাঁচে** গড়া হয়। ইংরেজির man → men, child → children-এর মতো। এগুলো দেখে দেখে চিনতে হয়; মূল তিন অক্ষর (রুট) একই থাকে।","en":"Many Quranic plurals don't add an ending — the word is **broken inside and re-moulded**, like English man → men, child → children. You learn these by sight; the three root letters stay the same."},{"type":"table","title":{"bn":"কুরআনের পরিচিত ভাঙা বহুবচন","en":"Common Quranic broken plurals"},"head":[{"bn":"এক","en":"Singular"},{"bn":"বহু","en":"Plural"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كِتَابٌ","كُتُبٌ",{"bn":"বই / কিতাব","en":"book(s)"}],["رَسُولٌ","رُسُلٌ",{"bn":"রাসূল","en":"messenger(s)"}],["قَلْبٌ","قُلُوبٌ",{"bn":"অন্তর","en":"heart(s)"}],["بَيْتٌ","بُيُوتٌ",{"bn":"ঘর","en":"house(s)"}],["عَبْدٌ","عِبَادٌ",{"bn":"বান্দা","en":"servant(s)"}],["يَوْمٌ","أَيَّامٌ",{"bn":"দিন","en":"day(s)"}],["رَجُلٌ","رِجَالٌ",{"bn":"পুরুষ","en":"man / men"}],["جَبَلٌ","جِبَالٌ",{"bn":"পাহাড়","en":"mountain(s)"}],["وَلَدٌ","أَوْلَادٌ",{"bn":"সন্তান","en":"child(ren)"}],["نَفْسٌ","أَنْفُسٌ",{"bn":"প্রাণ / নিজ","en":"soul(s) / self"}],["صَاحِبٌ","أَصْحَابٌ",{"bn":"সঙ্গী / অধিবাসী","en":"companion(s)"}],["نَبِيٌّ","أَنْبِيَاءُ",{"bn":"নবী","en":"prophet(s)"}]]},{"type":"tip","kind":"fun","bn":"{{اِمْرَأَةٌ}} (নারী)-এর বহুবচন একদম ভিন্ন শব্দ: {{نِسَاءٌ}} — কুরআনের একটি সূরার নামই {{النِّسَاءُ}}! ঠিক ইংরেজির person → people-এর মতো।","en":"The plural of {{اِمْرَأَةٌ}} (woman) is a totally different word: {{نِسَاءٌ}} — a whole surah is named {{النِّسَاءُ}}! Just like English person → people."},{"type":"quiz","items":[{"q":{"bn":"‘দুটি বই’ আরবিতে কোনটি?","en":"Which means 'two books'?"},"options":["كُتُبٌ","كِتَابٌ","كِتَابَانِ","كَاتِبُونَ"],"answer":2},{"q":{"bn":"{{الْمُفْلِحُونَ}} কোন বচন?","en":"What number is {{الْمُفْلِحُونَ}}?"},"ar":"الْمُفْلِحُونَ","options":[{"bn":"পুরুষ সালিম বহুবচন","en":"Sound masculine plural"},{"bn":"দ্বিবচন","en":"Dual"},{"bn":"একবচন","en":"Singular"},{"bn":"স্ত্রী সালিম বহুবচন","en":"Sound feminine plural"}],"answer":0},{"q":{"bn":"{{الصَّالِحَاتِ}}-এর শেষাংশ কী বোঝায়?","en":"What does the ending of {{الصَّالِحَاتِ}} show?"},"ar":"الصَّالِحَاتِ","options":[{"bn":"স্ত্রী সালিম বহুবচন","en":"Sound feminine plural"},{"bn":"দ্বিবচন","en":"Dual"},{"bn":"ভাঙা বহুবচন","en":"Broken plural"}],"answer":0},{"q":{"bn":"{{قَلْبٌ}}-এর বহুবচন কোনটি?","en":"What is the plural of {{قَلْبٌ}}?"},"options":["قَلْبَانِ","قَلْبَاتٌ","قَلْبُونَ","قُلُوبٌ"],"answer":3},{"q":{"bn":"{{رَبِّ الْعٰلَمِينَ}} — এখানে {{ـُونَ}} না হয়ে {{ـِينَ}} কেন?","en":"In {{رَبِّ الْعٰلَمِينَ}}, why {{ـِينَ}} and not {{ـُونَ}}?"},"options":[{"bn":"শব্দটি স্ত্রীলিঙ্গ","en":"The word is feminine"},{"bn":"শব্দটি এখানে যের অবস্থায় (মুযাফ ইলাইহি)","en":"The word is in the genitive here"},{"bn":"শব্দটি দ্বিবচন","en":"The word is dual"}],"answer":1},{"q":{"bn":"{{جَنَّةٌ}}-এর দ্বিবচন কোনটি?","en":"What is the dual of {{جَنَّةٌ}}?"},"options":["جَنَّاتٌ","جَنَّةَانِ","جَنَّتَانِ"],"answer":2,"explain":{"bn":"গোল তা খুলে {{ت}} হয়: {{جَنَّتَانِ}} (৫৫:৪৬)।","en":"The round tā opens to {{ت}}: {{جَنَّتَانِ}} (55:46)."}}]}]},{"id":"g-definite","icon":"ال","title":{"bn":"নির্দিষ্ট ও অনির্দিষ্ট: {{اَلْ}} বনাম তানবীন","en":"Definite and Indefinite: {{اَلْ}} vs Tanween"},"subtitle":{"bn":"‘একটি বই’ আর ‘বইটি’-র পার্থক্য","en":"The difference between 'a book' and 'the book'"},"minutes":12,"goals":[{"bn":"{{اَلْ}} দিয়ে নির্দিষ্ট (মা'রিফা) শব্দ চিনবে","en":"Recognise definite words made with {{اَلْ}} (ma'rifa)"},{"bn":"তানবীন দিয়ে অনির্দিষ্ট (নাকিরা) শব্দ চিনবে","en":"Recognise indefinite words marked with tanween (nakira)"},{"bn":"জানবে কেন {{اَلْ}} ও তানবীন একসঙ্গে বসে না","en":"Know why {{اَلْ}} and tanween never sit together"}],"blocks":[{"type":"text","bn":"বাংলায় ‘একটি বই’ বললে যেকোনো একটা বই বোঝায়, আর ‘বইটি’ বললে নির্দিষ্ট একটা বই। বাংলায় ‘-টি/-টা’ বসে শেষে; আরবিতে নির্দিষ্ট করার জন্য {{اَلْ}} বসে **শুরুতে**। আর অনির্দিষ্ট শব্দের শেষে সাধারণত থাকে **তানবীন** (দুই যবর/যের/পেশ)।","en":"In English 'a book' means any book, 'the book' means a specific one. Arabic puts {{اَلْ}} ('the') at the **front** to make a word definite. An indefinite word usually ends in **tanween** (doubled vowel)."},{"type":"table","title":{"bn":"অনির্দিষ্ট → নির্দিষ্ট","en":"Indefinite → Definite"},"head":[{"bn":"নাকিরা (অনির্দিষ্ট)","en":"Nakira (indefinite)"},{"bn":"মা'রিফা (নির্দিষ্ট)","en":"Ma'rifa (definite)"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كِتَابٌ","اَلْكِتَابُ",{"bn":"একটি বই → বইটি","en":"a book → the book"}],["رَسُولٌ","اَلرَّسُولُ",{"bn":"একজন রাসূল → রাসূলটি (সেই রাসূল)","en":"a messenger → the messenger"}],["بَيْتٌ","اَلْبَيْتُ",{"bn":"একটি ঘর → ঘরটি","en":"a house → the house"}],["قَمَرٌ","اَلْقَمَرُ",{"bn":"একটি চাঁদ → চাঁদটি","en":"a moon → the moon"}],["شَمْسٌ","اَلشَّمْسُ",{"bn":"একটি সূর্য → সূর্যটি","en":"a sun → the sun"}]]},{"type":"tip","kind":"warn","bn":"**{{اَلْ}} আর তানবীন কখনো একসাথে বসে না!** {{اَلْ}} এলেই তানবীন বিদায় নেয়, শুধু এক হরকত থাকে: {{كِتَابٌ}} → {{اَلْكِتَابُ}}। ভুল: ‘اَلْكِتَابٌ’ ✗","en":"**{{اَلْ}} and tanween never sit together!** When {{اَلْ}} arrives, tanween leaves and a single vowel stays: {{كِتَابٌ}} → {{اَلْكِتَابُ}}. Wrong: 'اَلْكِتَابٌ' ✗"},{"type":"tip","kind":"memory","bn":"ভাবো তানবীন হলো ‘একটি’ — আর {{اَلْ}} হলো ‘টি’। একই বইকে একসঙ্গে ‘একটি বইটি’ বলা যায় না, তাই দুটো একসঙ্গে বসে না!","en":"Think of tanween as 'a' and {{اَلْ}} as 'the'. You can't say 'a the book' — so they never come together!"},{"type":"table","title":{"bn":"তানবীনের তিন চেহারা","en":"The three faces of tanween"},"head":[{"bn":"রূপ","en":"Form"},{"bn":"উচ্চারণ","en":"Sound"},{"bn":"কখন (সংক্ষেপে)","en":"When (in short)"}],"rows":[["كِتَابٌ",{"bn":"কিতাবুন","en":"kitābun"},{"bn":"পেশ অবস্থা — সাধারণত কর্তা/উদ্দেশ্য","en":"Raf' — usually the subject"}],["كِتَابًا",{"bn":"কিতাবান","en":"kitāban"},{"bn":"যবর অবস্থা — সাধারণত কর্ম","en":"Nasb — usually the object"}],["كِتَابٍ",{"bn":"কিতাবিন","en":"kitābin"},{"bn":"যের অবস্থা — হরফে জারের পরে বা মালিকানায়","en":"Jarr — after a preposition or in possession"}]]},{"type":"tip","kind":"tip","bn":"শব্দের শেষের এই হরকত বদলকে বলে **ই'রাব** ({{إِعْرَابٌ}})। ঘাবড়ানোর কিছু নেই — সামনের পাঠগুলোতে একটু একটু করে শিখব। আপাতত শুধু মনে রাখো: শেষ হরকত শব্দের ‘ভূমিকা’ বলে দেয়।","en":"This change in the final vowel is called **i'rab** ({{إِعْرَابٌ}}). Don't worry — we'll learn it bit by bit in the coming lessons. For now just remember: the last vowel tells you the word's 'job'."},{"type":"examples","title":{"bn":"কুরআনে নির্দিষ্ট ও অনির্দিষ্ট","en":"Definite and indefinite in the Quran"},"items":[{"ar":"ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ","tr":{"bn":"যালিকাল কিতাবু লা রইবা ফীহ","en":"dhālikal-kitābu lā rayba fīh"},"mean":{"bn":"এটি সেই কিতাব, যাতে কোনো সন্দেহ নেই (২:২)","en":"That is the Book, no doubt in it (2:2)"},"note":{"bn":"{{الْكِتَابُ}} — নির্দিষ্ট: সেই কিতাব","en":"{{الْكِتَابُ}} — definite: THE Book"},"hl":"الْكِتَابُ"},{"ar":"قَدْ جَاءَكُمْ مِنَ اللّٰهِ نُورٌ وَكِتَابٌ مُبِينٌ","tr":{"bn":"কদ জা-আকুম মিনাল্লাহি নূরুঁও ওয়া কিতাবুম মুবীন","en":"qad jā'akum minallāhi nūruñw-wa kitābum-mubīn"},"mean":{"bn":"তোমাদের কাছে আল্লাহর পক্ষ থেকে এসেছে এক আলো ও এক স্পষ্ট কিতাব (৫:১৫)","en":"There has come to you from Allah a light and a clear Book (5:15)"},"note":{"bn":"{{كِتَابٌ}} — তানবীন: ‘একটি’ কিতাব","en":"{{كِتَابٌ}} — tanween: 'a' Book"},"hl":"كِتَابٌ"},{"ar":"لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ","tr":{"bn":"লাকদ জা-আকুম রাসূলুম মিন আনফুসিকুম","en":"laqad jā'akum rasūlum-min anfusikum"},"mean":{"bn":"তোমাদের কাছে তোমাদের মধ্য থেকেই একজন রাসূল এসেছেন (৯:১২৮)","en":"A messenger from among yourselves has come to you (9:128)"},"hl":"رَسُولٌ"},{"ar":"أَطِيعُوا اللّٰهَ وَأَطِيعُوا الرَّسُولَ","tr":{"bn":"আত্বীউল্লাহা ওয়া আত্বীউর রাসূল","en":"aṭī'ullāha wa aṭī'ur-rasūl"},"mean":{"bn":"আল্লাহর আনুগত্য করো এবং রাসূলের আনুগত্য করো (৪:৫৯)","en":"Obey Allah and obey the Messenger (4:59)"},"note":{"bn":"{{الرَّسُولَ}} — নির্দিষ্ট: সেই রাসূল ﷺ","en":"{{الرَّسُولَ}} — definite: THE Messenger ﷺ"},"hl":"الرَّسُولَ"},{"ar":"إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ","tr":{"bn":"ইন্নাল ইনসানা লাফী খুসর","en":"innal-insāna lafī khusr"},"mean":{"bn":"নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে (১০৩:২)","en":"Indeed, mankind is in loss (103:2)"},"note":{"bn":"{{الْإِنْسَانَ}} নির্দিষ্ট, {{خُسْرٍ}} অনির্দিষ্ট (তানবীন)","en":"{{الْإِنْسَانَ}} is definite, {{خُسْرٍ}} is indefinite (tanween)"}}]},{"type":"tip","kind":"tip","bn":"শামসী-কামারী মনে আছে? {{اَلْقَمَرُ}}-তে {{ل}} পড়া হয় (আল-কামারু), কিন্তু {{اَلشَّمْسُ}}-তে {{ل}} চুপ, পরের অক্ষরে তাশদীদ (আশ-শামসু)। আর আগে কোনো শব্দ থাকলে {{ا}} উচ্চারিত হয় না: {{وَالْعَصْرِ}} = ‘ওয়াল আসর’।","en":"Remember sun and moon letters? In {{اَلْقَمَرُ}} the {{ل}} is said (al-qamaru), but in {{اَلشَّمْسُ}} it is silent and the next letter is doubled (ash-shamsu). And when a word comes before, the {{ا}} is skipped: {{وَالْعَصْرِ}} = 'wal-'aṣr'."},{"type":"tip","kind":"warn","bn":"{{لِـ}} (জন্য) + {{اَلْ}} মিলে হয় {{لِلْ}} — আলিফ লেখাই হয় না: {{لِلْمُتَّقِينَ}} (মুত্তাকীদের জন্য), {{لِلنَّاسِ}} (মানুষের জন্য)। {{لِلّٰهِ}} (আল্লাহর জন্য)-ও এভাবেই।","en":"{{لِـ}} (for) + {{اَلْ}} becomes {{لِلْ}} — the alif isn't even written: {{لِلْمُتَّقِينَ}} (for the God-conscious), {{لِلنَّاسِ}} (for people). {{لِلّٰهِ}} (for Allah) works the same way."},{"type":"text","title":{"bn":"{{اَلْ}} ছাড়াও নির্দিষ্ট হওয়ার উপায়","en":"Other ways to be definite"},"bn":"{{اَلْ}} ছাড়াও শব্দ নির্দিষ্ট হয়: (১) নাম — {{اللّٰهُ}}, {{مُحَمَّدٌ}}, {{مُوسٰى}}; (২) সর্বনাম যুক্ত হলে — {{كِتَابُهُ}} (তার বই); (৩) নির্দিষ্ট শব্দের সাথে সম্বন্ধ হলে — {{كِتَابُ اللّٰهِ}} (আল্লাহর কিতাব)। এগুলো পরের পাঠে আসছে।","en":"Besides {{اَلْ}}, a word is definite when it is: (1) a name — {{اللّٰهُ}}, {{مُحَمَّدٌ}}, {{مُوسٰى}}; (2) joined to a pronoun — {{كِتَابُهُ}} (his book); (3) possessed by a definite word — {{كِتَابُ اللّٰهِ}} (the Book of Allah). These come in later lessons."},{"type":"quiz","items":[{"q":{"bn":"‘বইটি’ (নির্দিষ্ট) কোনটি?","en":"Which means 'the book'?"},"options":["كِتَابٌ","اَلْكِتَابُ","كِتَابًا","اَلْكِتَابٌ"],"answer":1},{"q":{"bn":"কোনটি ভুল লেখা?","en":"Which one is written wrongly?"},"options":["اَلْبَيْتُ","بَيْتٌ","اَلْبَيْتٌ","بَيْتًا"],"answer":2,"explain":{"bn":"{{اَلْ}} আর তানবীন একসঙ্গে বসে না।","en":"{{اَلْ}} and tanween never come together."}},{"q":{"bn":"{{خُسْرٍ}} শব্দটি কেমন?","en":"What is {{خُسْرٍ}}?"},"ar":"خُسْرٍ","options":[{"bn":"অনির্দিষ্ট (নাকিরা)","en":"Indefinite"},{"bn":"ফে'ল","en":"A verb"},{"bn":"নির্দিষ্ট (মা'রিফা)","en":"Definite"}],"answer":0},{"q":{"bn":"{{اَلشَّمْسُ}} কীভাবে পড়বে?","en":"How do you read {{اَلشَّمْسُ}}?"},"ar":"اَلشَّمْسُ","options":[{"bn":"আল-শামসু","en":"al-shamsu"},{"bn":"আশ-শামসু","en":"ash-shamsu"},{"bn":"শামসুন","en":"shamsun"}],"answer":1},{"q":{"bn":"{{لِـ}} + {{النَّاسِ}} মিলে কী হয়?","en":"{{لِـ}} + {{النَّاسِ}} becomes?"},"options":["لَنَّاسِ","لِالنَّاسِ","لِلنَّاسِ"],"answer":2},{"q":{"bn":"কোনটি {{اَلْ}} ছাড়াই নির্দিষ্ট?","en":"Which one is definite without {{اَلْ}}?"},"options":["كِتَابُهُ","كِتَابٌ","رَسُولٌ"],"answer":0,"explain":{"bn":"সর্বনাম যুক্ত হলে শব্দ নির্দিষ্ট হয়: {{كِتَابُهُ}} = তার বই।","en":"A word joined to a pronoun is definite: {{كِتَابُهُ}} = his book."}}]}]},{"id":"g-pronouns","icon":"هو","title":{"bn":"আলাদা সর্বনাম: আমি, তুমি, সে…","en":"Detached Pronouns: I, You, He..."},"subtitle":{"bn":"১৪টি যমীর — বাংলার তিন পুরুষের মতো সাজানো","en":"The 14 pronouns — arranged like the three 'persons'"},"minutes":15,"goals":[{"bn":"১৪টি আলাদা সর্বনাম (যমীর মুনফাসিল) চিনবে","en":"Recognise the 14 detached pronouns"},{"bn":"নাম পুরুষ, মধ্যম পুরুষ ও উত্তম পুরুষ ভাগ বুঝবে","en":"Understand 3rd, 2nd and 1st person"},{"bn":"কুরআনের আয়াতে সর্বনাম খুঁজে পাবে","en":"Find pronouns in Quranic ayahs"}],"blocks":[{"type":"text","bn":"বাংলা ব্যাকরণে পড়েছ — **নাম পুরুষ** (সে, তারা), **মধ্যম পুরুষ** (তুমি, তোমরা), **উত্তম পুরুষ** (আমি, আমরা)। আরবিতেও ঠিক এই তিন ভাগ! পার্থক্য শুধু এই: আরবি নারী-পুরুষ আলাদা করে, আর ‘দুজন’-এর জন্যও আলাদা শব্দ রাখে। তাই মোট সর্বনাম **১৪টি**। এদের বলে **যমীর** ({{ضَمِيرٌ}})।","en":"You know the three persons — **3rd person** (he, they), **2nd person** (you), **1st person** (I, we). Arabic has the same three! The difference: Arabic separates male and female, and has special words for 'two'. So there are **14** pronouns in total, called **ḍamīr** ({{ضَمِيرٌ}})."},{"type":"table","title":{"bn":"নাম পুরুষ — অনুপস্থিত (গায়েব)","en":"3rd person — absent (ghā'ib)"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"},{"bn":"লিঙ্গ · বচন","en":"Gender · number"}],"rows":[["هُوَ",{"bn":"হুয়া","en":"huwa"},{"bn":"সে / তিনি","en":"he / it"},{"bn":"পুং · এক","en":"m · one"}],["هُمَا",{"bn":"হুমা","en":"humā"},{"bn":"তারা দুজন","en":"they two"},{"bn":"পুং · দুই","en":"m · two"}],["هُمْ",{"bn":"হুম","en":"hum"},{"bn":"তারা সবাই","en":"they (all)"},{"bn":"পুং · বহু","en":"m · many"}],["هِيَ",{"bn":"হিয়া","en":"hiya"},{"bn":"সে (নারী)","en":"she / it"},{"bn":"স্ত্রী · এক","en":"f · one"}],["هُمَا",{"bn":"হুমা","en":"humā"},{"bn":"তারা দুজন (নারী)","en":"they two (f)"},{"bn":"স্ত্রী · দুই","en":"f · two"}],["هُنَّ",{"bn":"হুন্না","en":"hunna"},{"bn":"তারা সবাই (নারী)","en":"they (f, all)"},{"bn":"স্ত্রী · বহু","en":"f · many"}]]},{"type":"table","title":{"bn":"মধ্যম পুরুষ — সামনে যাকে বলছি (মুখাতাব)","en":"2nd person — the one spoken to (mukhāṭab)"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"},{"bn":"লিঙ্গ · বচন","en":"Gender · number"}],"rows":[["أَنْتَ",{"bn":"আনতা","en":"anta"},{"bn":"তুমি","en":"you"},{"bn":"পুং · এক","en":"m · one"}],["أَنْتُمَا",{"bn":"আনতুমা","en":"antumā"},{"bn":"তোমরা দুজন","en":"you two"},{"bn":"পুং · দুই","en":"m · two"}],["أَنْتُمْ",{"bn":"আনতুম","en":"antum"},{"bn":"তোমরা সবাই","en":"you (all)"},{"bn":"পুং · বহু","en":"m · many"}],["أَنْتِ",{"bn":"আনতি","en":"anti"},{"bn":"তুমি (নারী)","en":"you (f)"},{"bn":"স্ত্রী · এক","en":"f · one"}],["أَنْتُمَا",{"bn":"আনতুমা","en":"antumā"},{"bn":"তোমরা দুজন (নারী)","en":"you two (f)"},{"bn":"স্ত্রী · দুই","en":"f · two"}],["أَنْتُنَّ",{"bn":"আনতুন্না","en":"antunna"},{"bn":"তোমরা সবাই (নারী)","en":"you (f, all)"},{"bn":"স্ত্রী · বহু","en":"f · many"}]]},{"type":"table","title":{"bn":"উত্তম পুরুষ — যে বলছে (মুতাকাল্লিম)","en":"1st person — the speaker (mutakallim)"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"},{"bn":"লিঙ্গ · বচন","en":"Gender · number"}],"rows":[["أَنَا",{"bn":"আনা","en":"anā"},{"bn":"আমি","en":"I"},{"bn":"নারী-পুরুষ উভয় · এক","en":"m/f · one"}],["نَحْنُ",{"bn":"নাহনু","en":"naḥnu"},{"bn":"আমরা","en":"we"},{"bn":"উভয় · দুই বা বহু","en":"m/f · two or more"}]]},{"type":"tip","kind":"memory","bn":"তিনটি মজার প্যাটার্ন: (১) **দ্বিবচন সবসময় ‘-মা’** দিয়ে শেষ: {{هُمَا}}, {{أَنْتُمَا}}। (২) **পুরুষ বহুবচন ‘-ম’**: {{هُمْ}}, {{أَنْتُمْ}}। (৩) **নারী বহুবচন ‘-ন্না’**: {{هُنَّ}}, {{أَنْتُنَّ}}। এই তিনটি সূত্র মনে রাখলে অর্ধেক কাজ শেষ!","en":"Three handy patterns: (1) **duals always end in '-mā'**: {{هُمَا}}, {{أَنْتُمَا}}. (2) **masculine plurals end in '-m'**: {{هُمْ}}, {{أَنْتُمْ}}. (3) **feminine plurals end in '-nna'**: {{هُنَّ}}, {{أَنْتُنَّ}}. Remember these and you're halfway there!"},{"type":"tip","kind":"tip","bn":"{{أَنْتَ}} আর {{أَنْتِ}}-এর পার্থক্য শুধু শেষ হরকতে: যবর হলে পুরুষ, যের হলে নারী। বাংলায় ‘তুমি’ দুজনের জন্যই এক — কিন্তু আরবি সাবধানে আলাদা করে।","en":"{{أَنْتَ}} and {{أَنْتِ}} differ only in the last vowel: fatha for a man, kasra for a woman. English 'you' is the same for both — Arabic is more careful."},{"type":"examples","title":{"bn":"কুরআনে সর্বনাম","en":"Pronouns in the Quran"},"items":[{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","tr":{"bn":"কুল হুওয়াল্লাহু আহাদ","en":"qul huwallāhu aḥad"},"mean":{"bn":"বলো, তিনিই আল্লাহ, এক (১১২:১)","en":"Say: He is Allah, the One (112:1)"},"hl":"هُوَ"},{"ar":"إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ","tr":{"bn":"ইন্নাকা আনতাস সামী'উল আলীম","en":"innaka antas-samī'ul-'alīm"},"mean":{"bn":"নিশ্চয়ই তুমিই সর্বশ্রোতা, সর্বজ্ঞ (২:১২৭)","en":"Indeed You are the All-Hearing, the All-Knowing (2:127)"},"hl":"أَنْتَ"},{"ar":"إِنِّي أَنَا رَبُّكَ","tr":{"bn":"ইন্নী আনা রব্বুকা","en":"innī anā rabbuka"},"mean":{"bn":"নিশ্চয়ই আমিই তোমার রব (২০:১২)","en":"Indeed, I am your Lord (20:12)"},"hl":"أَنَا"},{"ar":"إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ","tr":{"bn":"ইন্না নাহনু নাযযালনায যিকরা","en":"innā naḥnu nazzalnadh-dhikra"},"mean":{"bn":"নিশ্চয়ই আমরাই এই উপদেশ (কুরআন) নাযিল করেছি (১৫:৯)","en":"Indeed, it is We who sent down the Reminder (15:9)"},"note":{"bn":"সম্মান বোঝাতে আল্লাহ নিজের জন্য {{نَحْنُ}} (আমরা) ব্যবহার করেছেন","en":"Allah uses {{نَحْنُ}} ('We') for Himself to show majesty"},"hl":"نَحْنُ"},{"ar":"وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ","tr":{"bn":"ওয়া লা আনতুম আবিদূনা মা আ'বুদ","en":"wa lā antum 'ābidūna mā a'bud"},"mean":{"bn":"আর তোমরাও তার ইবাদতকারী নও, যার ইবাদত আমি করি (১০৯:৩)","en":"Nor are you worshippers of what I worship (109:3)"},"hl":"أَنْتُمْ"},{"ar":"سَلَامٌ هِيَ حَتّٰى مَطْلَعِ الْفَجْرِ","tr":{"bn":"সালামুন হিয়া হাত্তা মাত্বলা'ইল ফাজর","en":"salāmun hiya ḥattā maṭla'il-fajr"},"mean":{"bn":"শান্তিময় সেই রাত, ফজর উদয় পর্যন্ত (৯৭:৫)","en":"Peace it is, until the rising of dawn (97:5)"},"note":{"bn":"{{هِيَ}} = সে (লাইলাতুল কদর — {{لَيْلَةٌ}} মুআন্নাস)","en":"{{هِيَ}} = 'it/she' (the Night — {{لَيْلَةٌ}} is feminine)"},"hl":"هِيَ"},{"ar":"هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ","tr":{"bn":"হুন্না লিবাসুল লাকুম ওয়া আনতুম লিবাসুল লাহুন্ন","en":"hunna libāsul-lakum wa antum libāsul-lahunn"},"mean":{"bn":"তারা (স্ত্রীরা) তোমাদের পোশাক, আর তোমরা তাদের পোশাক (২:১৮৭)","en":"They are a garment for you and you are a garment for them (2:187)"},"hl":"هُنَّ"}]},{"type":"tip","kind":"warn","bn":"{{هُمْ}}-এর পরে {{اَلْ}} এলে মিলিয়ে পড়ার জন্য {{م}}-এ পেশ বসে: {{هُمُ الْمُفْلِحُونَ}} (হুমুল মুফলিহূন)। এটা নতুন শব্দ নয় — একই {{هُمْ}}।","en":"When {{اَلْ}} follows {{هُمْ}}, the {{م}} gets a damma to connect: {{هُمُ الْمُفْلِحُونَ}} (humul-mufliḥūn). It's not a new word — still {{هُمْ}}."},{"type":"practice","bn":"সর্বনামগুলো তিন পুরুষ অনুযায়ী জোরে পড়ো।","en":"Read the pronouns aloud, person by person.","lines":["هُوَ هُمَا هُمْ هِيَ هُمَا هُنَّ","أَنْتَ أَنْتُمَا أَنْتُمْ أَنْتِ أَنْتُمَا أَنْتُنَّ","أَنَا نَحْنُ"]},{"type":"quiz","items":[{"q":{"bn":"{{نَحْنُ}} অর্থ কী?","en":"What does {{نَحْنُ}} mean?"},"ar":"نَحْنُ","options":[{"bn":"আমরা","en":"we"},{"bn":"আমি","en":"I"},{"bn":"তোমরা","en":"you all"},{"bn":"তারা","en":"they"}],"answer":0},{"q":{"bn":"একজন নারীকে ‘তুমি’ বলতে কোনটি?","en":"Which is 'you' for one woman?"},"options":["أَنْتَ","أَنْتُمْ","هِيَ","أَنْتِ"],"answer":3},{"q":{"bn":"{{هُمْ}} কাকে বোঝায়?","en":"Who does {{هُمْ}} refer to?"},"ar":"هُمْ","options":[{"bn":"সে (একজন পুরুষ)","en":"he"},{"bn":"তারা সবাই (পুরুষ বা মিশ্র)","en":"they (m or mixed group)"},{"bn":"তারা দুজন","en":"they two"},{"bn":"তারা সবাই (শুধু নারী)","en":"they (only women)"}],"answer":1},{"q":{"bn":"কোন সর্বনামটি দ্বিবচন?","en":"Which pronoun is dual?"},"options":["هُنَّ","نَحْنُ","أَنْتُمَا","أَنْتُمْ"],"answer":2,"explain":{"bn":"দ্বিবচন সবসময় ‘-মা’ দিয়ে শেষ।","en":"Duals always end in '-mā'."}},{"q":{"bn":"{{قُلْ هُوَ اللّٰهُ أَحَدٌ}} — এখানে সর্বনাম কোনটি?","en":"In {{قُلْ هُوَ اللّٰهُ أَحَدٌ}}, which word is the pronoun?"},"options":["هُوَ","اللّٰهُ","قُلْ","أَحَدٌ"],"answer":0},{"q":{"bn":"{{أَنَا}} কোন পুরুষ?","en":"Which person is {{أَنَا}}?"},"options":[{"bn":"মধ্যম পুরুষ","en":"2nd person"},{"bn":"উত্তম পুরুষ","en":"1st person"},{"bn":"নাম পুরুষ","en":"3rd person"}],"answer":1},{"q":{"bn":"‘তারা সবাই (নারী)’ কোনটি?","en":"Which is 'they (women)'?"},"options":["هُمْ","هُمَا","هِيَ","هُنَّ"],"answer":3}]}]},{"id":"g-attached","icon":"ـهُ","title":{"bn":"জোড়া সর্বনাম: আমার, তোমার, তার","en":"Attached Pronouns: My, Your, His"},"subtitle":{"bn":"শব্দের শেষে লেগে থাকা ছোট্ট সর্বনাম — কুরআনে সবচেয়ে বেশি দেখা যায়","en":"Tiny pronouns glued to the end of words — everywhere in the Quran"},"minutes":18,"goals":[{"bn":"১৪টি জোড়া সর্বনাম (যমীর মুত্তাসিল) চিনবে","en":"Recognise the 14 attached pronouns"},{"bn":"ইসমের সাথে ({{كِتَابُهُ}}) ও হরফের সাথে ({{لَهُ}}, {{عَلَيْهِمْ}}) ব্যবহার বুঝবে","en":"Use them on nouns ({{كِتَابُهُ}}) and prepositions ({{لَهُ}}, {{عَلَيْهِمْ}})"},{"bn":"{{ـهُ}} কখন {{ـهِ}} হয় — জানবে","en":"Know when {{ـهُ}} becomes {{ـهِ}}"}],"blocks":[{"type":"text","bn":"বাংলায় আমরা ‘আমার বই’ বলতে দুটো শব্দ বলি। আরবিতে সর্বনামটা ছোট হয়ে শব্দের **শেষে লেগে যায়**: {{كِتَابِي}} = আমার বই, {{كِتَابُكَ}} = তোমার বই। এদের বলে **যমীর মুত্তাসিল** (জোড়া সর্বনাম)। কুরআন পড়তে গেলে প্রায় প্রতিটি আয়াতেই এদের দেখা পাবে!","en":"In English 'my book' is two words. In Arabic the pronoun shrinks and **sticks to the end** of the word: {{كِتَابِي}} = my book, {{كِتَابُكَ}} = your book. These are **attached pronouns** (ḍamīr muttaṣil). You'll meet them in almost every ayah!"},{"type":"table","title":{"bn":"১৪টি জোড়া সর্বনাম — {{كِتَابٌ}} দিয়ে","en":"The 14 attached pronouns — with {{كِتَابٌ}}"},"head":[{"bn":"আলাদা","en":"Detached"},{"bn":"জোড়া","en":"Attached"},{"bn":"উদাহরণ","en":"Example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["هُوَ","ـهُ","كِتَابُهُ",{"bn":"তার (পুং) বই","en":"his book"}],["هُمَا","ـهُمَا","كِتَابُهُمَا",{"bn":"তাদের দুজনের বই","en":"their (two) book"}],["هُمْ","ـهُمْ","كِتَابُهُمْ",{"bn":"তাদের বই","en":"their book"}],["هِيَ","ـهَا","كِتَابُهَا",{"bn":"তার (স্ত্রী) বই","en":"her book"}],["هُمَا","ـهُمَا","كِتَابُهُمَا",{"bn":"তাদের দুজনের (স্ত্রী) বই","en":"their (two, f) book"}],["هُنَّ","ـهُنَّ","كِتَابُهُنَّ",{"bn":"তাদের (নারীদের) বই","en":"their (f) book"}],["أَنْتَ","ـكَ","كِتَابُكَ",{"bn":"তোমার বই","en":"your book"}],["أَنْتُمَا","ـكُمَا","كِتَابُكُمَا",{"bn":"তোমাদের দুজনের বই","en":"your (two) book"}],["أَنْتُمْ","ـكُمْ","كِتَابُكُمْ",{"bn":"তোমাদের বই","en":"your (all) book"}],["أَنْتِ","ـكِ","كِتَابُكِ",{"bn":"তোমার (নারী) বই","en":"your (f) book"}],["أَنْتُمَا","ـكُمَا","كِتَابُكُمَا",{"bn":"তোমাদের দুজনের (নারী) বই","en":"your (two, f) book"}],["أَنْتُنَّ","ـكُنَّ","كِتَابُكُنَّ",{"bn":"তোমাদের (নারীদের) বই","en":"your (f, all) book"}],["أَنَا","ـي","كِتَابِي",{"bn":"আমার বই","en":"my book"}],["نَحْنُ","ـنَا","كِتَابُنَا",{"bn":"আমাদের বই","en":"our book"}]]},{"type":"tip","kind":"memory","bn":"সহজ চাবি: **হ = সে/তারা**, **ক = তুমি/তোমরা**, **ই = আমি**, **না = আমরা**। বাকিটা আগের পাঠের মতোই: ‘-মা’ দ্বিবচন, ‘-ম’ পুরুষ বহু, ‘-ন্না’ নারী বহু।","en":"Easy key: **h = he/they**, **k = you**, **ī = me**, **nā = us**. The rest follows the last lesson: '-mā' dual, '-m' masculine plural, '-nna' feminine plural."},{"type":"examples","title":{"bn":"‘রব’ শব্দের সাথে — কুরআন ও দোয়ায় বারবার আসে","en":"With 'Rabb' — again and again in the Quran and du'a"},"items":[{"ar":"رَبِّي","tr":{"bn":"রব্বী","en":"rabbī"},"mean":{"bn":"আমার রব","en":"my Lord"},"note":{"bn":"{{ـي}}-এর আগের অক্ষরে সবসময় যের","en":"The letter before {{ـي}} always takes kasra"}},{"ar":"رَبُّكَ","tr":{"bn":"রব্বুকা","en":"rabbuka"},"mean":{"bn":"তোমার রব","en":"your Lord"}},{"ar":"رَبُّكُمْ","tr":{"bn":"রব্বুকুম","en":"rabbukum"},"mean":{"bn":"তোমাদের রব","en":"your (all) Lord"}},{"ar":"رَبُّنَا","tr":{"bn":"রব্বুনা","en":"rabbunā"},"mean":{"bn":"আমাদের রব","en":"our Lord"}},{"ar":"رَبُّهُ","tr":{"bn":"রব্বুহূ","en":"rabbuhū"},"mean":{"bn":"তার রব","en":"his Lord"}},{"ar":"رَبُّهُمْ","tr":{"bn":"রব্বুহুম","en":"rabbuhum"},"mean":{"bn":"তাদের রব","en":"their Lord"}}]},{"type":"table","title":{"bn":"হরফের সাথে জোড়া সর্বনাম","en":"Attached pronouns on prepositions"},"head":[{"bn":"হরফ","en":"Preposition"},{"bn":"তার / তাদের","en":"him / them"},{"bn":"তোমার / তোমাদের","en":"you / you all"},{"bn":"আমার / আমাদের","en":"me / us"}],"rows":[["لِـ","لَهُ ، لَهُمْ","لَكَ ، لَكُمْ","لِي ، لَنَا"],["عَلٰى","عَلَيْهِ ، عَلَيْهِمْ","عَلَيْكَ ، عَلَيْكُمْ","عَلَيَّ ، عَلَيْنَا"],["مِنْ","مِنْهُ ، مِنْهُمْ","مِنْكَ ، مِنْكُمْ","مِنِّي ، مِنَّا"],["فِي","فِيهِ ، فِيهِمْ","فِيكَ ، فِيكُمْ","فِيَّ ، فِينَا"],["إِلٰى","إِلَيْهِ ، إِلَيْهِمْ","إِلَيْكَ ، إِلَيْكُمْ","إِلَيَّ ، إِلَيْنَا"],["بِـ","بِهِ ، بِهِمْ","بِكَ ، بِكُمْ","بِي ، بِنَا"]]},{"type":"tip","kind":"warn","bn":"তিনটি ছোট্ট পরিবর্তন খেয়াল করো: (১) {{لِـ}} সর্বনামের আগে {{لَـ}} হয়ে যায় ({{لَهُ}}, {{لَكُمْ}}) — শুধু {{لِي}} ছাড়া। (২) {{عَلٰى}} ও {{إِلٰى}}-এর আলিফ {{ي}} হয়ে যায়: {{عَلَيْ}}، {{إِلَيْ}}। (৩) {{مِنْ}} + {{ـي}} = {{مِنِّي}}, {{مِنْ}} + {{ـنَا}} = {{مِنَّا}}।","en":"Notice three small changes: (1) {{لِـ}} becomes {{لَـ}} before pronouns ({{لَهُ}}, {{لَكُمْ}}) — except {{لِي}}. (2) The alif of {{عَلٰى}} and {{إِلٰى}} turns into {{ي}}: {{عَلَيْ}}, {{إِلَيْ}}. (3) {{مِنْ}} + {{ـي}} = {{مِنِّي}}, {{مِنْ}} + {{ـنَا}} = {{مِنَّا}}."},{"type":"tip","kind":"tip","bn":"**{{ـهُ}} কখন {{ـهِ}} হয়?** আগে যের বা {{ي}} থাকলে উচ্চারণ সহজ করতে পেশ যের হয়ে যায়: {{بِهِ}}, {{فِيهِ}}, {{عَلَيْهِ}}, {{رَبِّهِ}}। একইভাবে {{ـهُمْ}} → {{ـهِمْ}}: {{عَلَيْهِمْ}}, {{رَبِّهِمْ}}। অর্থ একদম একই!","en":"**When does {{ـهُ}} become {{ـهِ}}?** After a kasra or a {{ي}}, the damma turns to kasra for easy flow: {{بِهِ}}, {{فِيهِ}}, {{عَلَيْهِ}}, {{رَبِّهِ}}. Likewise {{ـهُمْ}} → {{ـهِمْ}}: {{عَلَيْهِمْ}}, {{رَبِّهِمْ}}. The meaning is exactly the same!"},{"type":"examples","title":{"bn":"কুরআনে জোড়া সর্বনাম","en":"Attached pronouns in the Quran"},"items":[{"ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","tr":{"bn":"সিরাত্বাল্লাযীনা আন'আমতা আলাইহিম","en":"ṣirāṭal-ladhīna an'amta 'alayhim"},"mean":{"bn":"তাদের পথ, যাদের উপর তুমি অনুগ্রহ করেছ (১:৭)","en":"The path of those You have blessed (1:7)"},"note":{"bn":"{{عَلٰى}} + {{ـهِمْ}} = তাদের উপর","en":"{{عَلٰى}} + {{ـهِمْ}} = upon them"},"hl":"عَلَيْهِمْ"},{"ar":"لَكُمْ دِينُكُمْ وَلِيَ دِينِ","tr":{"bn":"লাকুম দীনুকুম ওয়া লিয়া দীন","en":"lakum dīnukum wa liya dīn"},"mean":{"bn":"তোমাদের জন্য তোমাদের দ্বীন, আর আমার জন্য আমার দ্বীন (১০৯:৬)","en":"For you your religion, and for me mine (109:6)"},"note":{"bn":"{{لَكُمْ}} = তোমাদের জন্য, {{دِينُكُمْ}} = তোমাদের দ্বীন, {{لِيَ}} = আমার জন্য","en":"{{لَكُمْ}} = for you, {{دِينُكُمْ}} = your religion, {{لِيَ}} = for me"},"hl":"دِينُكُمْ"},{"ar":"أُولٰئِكَ عَلٰى هُدًى مِنْ رَبِّهِمْ","tr":{"bn":"উলা-ইকা আলা হুদাম মির রব্বিহিম","en":"ulā'ika 'alā hudam-mir-rabbihim"},"mean":{"bn":"তারাই তাদের রবের পক্ষ থেকে হিদায়াতের উপর আছে (২:৫)","en":"They are upon guidance from their Lord (2:5)"},"note":{"bn":"{{رَبِّ}} + {{ـهِمْ}} — আগে যের, তাই {{ـهِمْ}}","en":"{{رَبِّ}} + {{ـهِمْ}} — kasra before, so {{ـهِمْ}}"},"hl":"رَبِّهِمْ"},{"ar":"وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","tr":{"bn":"ওয়া লাম ইয়াকুল লাহূ কুফুওয়ান আহাদ","en":"wa lam yakul-lahū kufuwan aḥad"},"mean":{"bn":"এবং তাঁর সমতুল্য কেউ নেই (১১২:৪)","en":"And there is none equal to Him (112:4)"},"hl":"لَهُ"},{"ar":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","tr":{"bn":"আলাম নাশরাহ লাকা সদরাক","en":"alam nashraḥ laka ṣadrak"},"mean":{"bn":"আমি কি তোমার জন্য তোমার বক্ষ প্রশস্ত করে দিইনি? (৯৪:১)","en":"Did We not expand for you your chest? (94:1)"},"hl":"صَدْرَكَ"},{"ar":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ","tr":{"bn":"ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজি'ঊন","en":"innā lillāhi wa innā ilayhi rāji'ūn"},"mean":{"bn":"নিশ্চয়ই আমরা আল্লাহর জন্য, এবং নিশ্চয়ই আমরা তাঁর দিকেই ফিরে যাব (২:১৫৬)","en":"Indeed we belong to Allah, and to Him we return (2:156)"},"note":{"bn":"{{إِنَّا}} = {{إِنَّ}} + {{ـنَا}} (নিশ্চয়ই আমরা); {{إِلَيْهِ}} = তাঁর দিকে","en":"{{إِنَّا}} = {{إِنَّ}} + {{ـنَا}} (indeed we); {{إِلَيْهِ}} = to Him"},"hl":"إِلَيْهِ"},{"ar":"كُتِبَ عَلَيْكُمُ الصِّيَامُ","tr":{"bn":"কুতিবা আলাইকুমুস সিয়াম","en":"kutiba 'alaykumuṣ-ṣiyām"},"mean":{"bn":"তোমাদের উপর রোজা ফরজ করা হয়েছে (২:১৮৩)","en":"Fasting has been prescribed for you (2:183)"},"hl":"عَلَيْكُمُ"},{"ar":"تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ","tr":{"bn":"তাবারাকাল্লাযী বিইয়াদিহিল মুলক","en":"tabārakal-ladhī biyadihil-mulk"},"mean":{"bn":"বরকতময় তিনি, যাঁর হাতে সার্বভৌমত্ব (৬৭:১)","en":"Blessed is He in whose hand is the dominion (67:1)"},"note":{"bn":"{{بِـ}} + {{يَدِ}} + {{ـهِ}} — এক শব্দে তিন অংশ!","en":"{{بِـ}} + {{يَدِ}} + {{ـهِ}} — three parts in one word!"},"hl":"بِيَدِهِ"}]},{"type":"text","title":{"bn":"ফে'লের সাথে: ‘আমাকে’, ‘তাদেরকে’","en":"On verbs: 'me', 'them'"},"bn":"ফে'লের শেষে লাগলে জোড়া সর্বনাম **কর্ম** বোঝায় (‘-কে’)। শুধু ‘আমাকে’-র জন্য {{ـي}}-এর বদলে আসে {{ـنِي}}। যেমন: {{اِهْدِنَا}} = আমাদেরকে পথ দেখাও (১:৬), {{أَطْعَمَهُمْ}} = তাদেরকে খাইয়েছেন (১০৬:৪), {{اُدْعُونِي}} = আমাকে ডাকো (৪০:৬০)।","en":"On the end of a verb, an attached pronoun is the **object** ('me', 'them'). Only 'me' uses {{ـنِي}} instead of {{ـي}}. For example: {{اِهْدِنَا}} = guide us (1:6), {{أَطْعَمَهُمْ}} = He fed them (106:4), {{اُدْعُونِي}} = call on me (40:60)."},{"type":"tip","kind":"fun","bn":"জোড়া সর্বনাম লাগলে শব্দ নিজেই নির্দিষ্ট হয়ে যায় — তাই {{اَلْ}} আর তানবীন দুটোই চলে যায়: {{كِتَابٌ}} → {{كِتَابُهُ}}। ‘তার বই’ তো নির্দিষ্ট বই-ই!","en":"With an attached pronoun the word becomes definite by itself — so both {{اَلْ}} and tanween disappear: {{كِتَابٌ}} → {{كِتَابُهُ}}. 'His book' is a specific book, after all!"},{"type":"quiz","items":[{"q":{"bn":"{{كِتَابُنَا}} অর্থ কী?","en":"What does {{كِتَابُنَا}} mean?"},"ar":"كِتَابُنَا","options":[{"bn":"আমার বই","en":"my book"},{"bn":"আমাদের বই","en":"our book"},{"bn":"তোমাদের বই","en":"your book"},{"bn":"তাদের বই","en":"their book"}],"answer":1},{"q":{"bn":"‘তোমাদের রব’ আরবিতে কোনটি?","en":"Which means 'your (pl.) Lord'?"},"options":["رَبُّهُمْ","رَبُّكَ","رَبُّكُمْ","رَبِّي"],"answer":2},{"q":{"bn":"{{عَلَيْهِمْ}} অর্থ কী?","en":"What does {{عَلَيْهِمْ}} mean?"},"ar":"عَلَيْهِمْ","options":[{"bn":"তার উপর","en":"upon him"},{"bn":"আমাদের উপর","en":"upon us"},{"bn":"তাদের উপর","en":"upon them"}],"answer":2},{"q":{"bn":"{{بِهِ}}-তে {{ـهُ}} কেন {{ـهِ}} হলো?","en":"Why is it {{ـهِ}} and not {{ـهُ}} in {{بِهِ}}?"},"options":[{"bn":"আগে যের আছে, তাই উচ্চারণ সহজ করতে","en":"There is a kasra before it, for easy flow"},{"bn":"এটি স্ত্রীলিঙ্গ","en":"It is feminine"},{"bn":"এটি বহুবচন","en":"It is plural"}],"answer":0},{"q":{"bn":"{{لَكُمْ دِينُكُمْ}} — {{دِينُكُمْ}} অর্থ কী?","en":"In {{لَكُمْ دِينُكُمْ}}, what does {{دِينُكُمْ}} mean?"},"options":[{"bn":"আমার দ্বীন","en":"my religion"},{"bn":"তোমাদের দ্বীন","en":"your religion"},{"bn":"তাদের দ্বীন","en":"their religion"}],"answer":1},{"q":{"bn":"{{اِهْدِنَا}}-তে {{ـنَا}} কী বোঝায়?","en":"In {{اِهْدِنَا}}, what does {{ـنَا}} show?"},"ar":"اِهْدِنَا","options":[{"bn":"তাদেরকে","en":"them"},{"bn":"আমরা","en":"we (subject)"},{"bn":"আমাদেরকে","en":"us"}],"answer":2},{"q":{"bn":"{{إِلٰى}} + {{ـهِ}} মিলে কী হয়?","en":"{{إِلٰى}} + {{ـهِ}} becomes?"},"options":["إِلَيْهِ","إِلٰىهِ","إِلَهُ"],"answer":0}]}]},{"id":"g-pointing","icon":"هذا","title":{"bn":"ইশারা ও সংযোগ শব্দ: এই, ওই, যে","en":"Pointing and Linking Words: This, That, Who"},"subtitle":{"bn":"{{هٰذَا}}, {{ذٰلِكَ}}, {{الَّذِي}} — কুরআনের প্রিয় শব্দগুলো","en":"{{هٰذَا}}, {{ذٰلِكَ}}, {{الَّذِي}} — favourite words of the Quran"},"minutes":15,"goals":[{"bn":"কাছের ও দূরের ইশারা শব্দ (ইসমে ইশারা) চিনবে","en":"Recognise near and far pointing words (ism al-ishāra)"},{"bn":"{{هٰذَا كِتَابٌ}} ও {{هٰذَا الْكِتَابُ}}-এর পার্থক্য বুঝবে","en":"Tell {{هٰذَا كِتَابٌ}} from {{هٰذَا الْكِتَابُ}}"},{"bn":"{{الَّذِي}}, {{الَّتِي}}, {{الَّذِينَ}} (যে / যারা) চিনবে","en":"Recognise {{الَّذِي}}, {{الَّتِي}}, {{الَّذِينَ}} (who / which)"}],"blocks":[{"type":"text","bn":"আঙুল দিয়ে কিছু দেখিয়ে আমরা বলি ‘এটা’ বা ‘ওটা’। আরবিতে এগুলোকে বলে **ইসমে ইশারা** ({{اِسْمُ الْإِشَارَةِ}})। আরবিতে এখানেও লিঙ্গ ও বচন অনুযায়ী আলাদা শব্দ আছে — তবে মাত্র ছয়টি মুখস্থ করলেই কুরআনের প্রায় সব জায়গা বুঝে যাবে।","en":"When we point at something we say 'this' or 'that'. In Arabic these are **pointing words** ({{اِسْمُ الْإِشَارَةِ}}). Here too gender and number matter — but just six words cover almost all of the Quran."},{"type":"table","title":{"bn":"কাছে ও দূরে","en":"Near and far"},"head":[{"bn":"কার জন্য","en":"For"},{"bn":"কাছে (এই)","en":"Near (this/these)"},{"bn":"দূরে (ওই / সেই)","en":"Far (that/those)"}],"rows":[[{"bn":"পুং · এক","en":"m · one"},"هٰذَا","ذٰلِكَ"],[{"bn":"স্ত্রী · এক","en":"f · one"},"هٰذِهِ","تِلْكَ"],[{"bn":"বহু (নারী-পুরুষ)","en":"plural (m/f)"},"هٰؤُلَاءِ","أُولٰئِكَ"]]},{"type":"tip","kind":"memory","bn":"**‘হা’ মানে হাতের কাছে!** কাছের শব্দগুলো {{هٰ}} দিয়ে শুরু: {{هٰذَا}}, {{هٰذِهِ}}, {{هٰؤُلَاءِ}}। আর **‘ক’ মানে কতদূর!** দূরের শব্দগুলোতে {{ك}} আছে: {{ذٰلِكَ}}, {{تِلْكَ}}, {{أُولٰئِكَ}}।","en":"**'Hā' is for 'here'!** Near words start with {{هٰ}}: {{هٰذَا}}, {{هٰذِهِ}}, {{هٰؤُلَاءِ}}. **'K' is for 'kept far'!** Far words contain {{ك}}: {{ذٰلِكَ}}, {{تِلْكَ}}, {{أُولٰئِكَ}}."},{"type":"tip","kind":"warn","bn":"উচ্চারণ খেয়াল করো: {{هٰذَا}}-তে খাড়া যবর আছে, তাই ‘হা-যা’ (লম্বা)। {{ذٰلِكَ}} = ‘যা-লিকা’, {{أُولٰئِكَ}} = ‘উলা-ইকা’ — এখানে {{و}} পড়া হয় না!","en":"Watch the pronunciation: {{هٰذَا}} has a dagger alif, so 'hādhā' (long). {{ذٰلِكَ}} = 'dhālika', {{أُولٰئِكَ}} = 'ulā'ika' — the {{و}} is not pronounced!"},{"type":"compare","title":{"bn":"একটি {{اَلْ}}-এর জাদু","en":"The magic of one {{اَلْ}}"},"items":[{"ar":"هٰذَا كِتَابٌ","label":{"bn":"পূর্ণ বাক্য","en":"Full sentence"},"desc":{"bn":"‘এটি একটি বই।’ — পরের শব্দে তানবীন","en":"'This is a book.' — next word has tanween"}},{"ar":"هٰذَا الْكِتَابُ","label":{"bn":"শুধু শব্দগুচ্ছ","en":"Just a phrase"},"desc":{"bn":"‘এই বইটি…’ — পরের শব্দে {{اَلْ}}; বাক্য এখনো শেষ হয়নি","en":"'This book...' — next word has {{اَلْ}}; the sentence isn't finished"}}]},{"type":"examples","title":{"bn":"কুরআনে ইশারা শব্দ","en":"Pointing words in the Quran"},"items":[{"ar":"ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ","tr":{"bn":"যালিকাল কিতাবু লা রইবা ফীহ","en":"dhālikal-kitābu lā rayba fīh"},"mean":{"bn":"সেই কিতাব — এতে কোনো সন্দেহ নেই (২:২)","en":"That Book — no doubt is in it (2:2)"},"note":{"bn":"{{ذٰلِكَ}} = সেই (দূরের) — কুরআনের উচ্চ মর্যাদা বোঝাতে","en":"{{ذٰلِكَ}} = that (far) — showing the Book's lofty rank"},"hl":"ذٰلِكَ"},{"ar":"هٰذَا يَوْمُ الْفَصْلِ","tr":{"bn":"হা-যা ইয়াওমুল ফাসল","en":"hādhā yawmul-faṣl"},"mean":{"bn":"এটিই ফয়সালার দিন (৭৭:৩৮)","en":"This is the Day of Judgement (77:38)"},"hl":"هٰذَا"},{"ar":"تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ","tr":{"bn":"তিলকা আ-ইয়াতুল কিতাবিল মুবীন","en":"tilka āyātul-kitābil-mubīn"},"mean":{"bn":"এগুলো সুস্পষ্ট কিতাবের আয়াত (১২:১)","en":"These are the verses of the clear Book (12:1)"},"note":{"bn":"মানুষ নয় এমন জিনিসের বহুবচনে ({{آيَاتٌ}}) প্রায়ই স্ত্রী-একবচন {{تِلْكَ}} আসে","en":"Non-human plurals ({{آيَاتٌ}}) often take feminine singular {{تِلْكَ}}"},"hl":"تِلْكَ"},{"ar":"هٰذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ","tr":{"bn":"হা-যিহী জাহান্নামুল্লাতী কুনতুম তূ'আদূন","en":"hādhihī jahannamul-latī kuntum tū'adūn"},"mean":{"bn":"এই সেই জাহান্নাম, যার প্রতিশ্রুতি তোমাদের দেওয়া হতো (৩৬:৬৩)","en":"This is Hell which you were promised (36:63)"},"hl":"هٰذِهِ"},{"ar":"هٰؤُلَاءِ قَوْمُنَا","tr":{"bn":"হা-উলা-ই কওমুনা","en":"hā'ulā'i qawmunā"},"mean":{"bn":"এরা আমাদের জাতি (১৮:১৫)","en":"These are our people (18:15)"},"hl":"هٰؤُلَاءِ"},{"ar":"وَأُولٰئِكَ هُمُ الْمُفْلِحُونَ","tr":{"bn":"ওয়া উলা-ইকা হুমুল মুফলিহূন","en":"wa ulā'ika humul-mufliḥūn"},"mean":{"bn":"আর ওরাই সফলকাম (২:৫)","en":"And those are the successful (2:5)"},"hl":"أُولٰئِكَ"},{"ar":"فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِ","tr":{"bn":"ফালইয়া'বুদূ রব্বা হা-যাল বাইত","en":"falya'budū rabba hādhal-bayt"},"mean":{"bn":"সুতরাং তারা যেন এই ঘরের রবের ইবাদত করে (১০৬:৩)","en":"So let them worship the Lord of this House (106:3)"},"note":{"bn":"{{هٰذَا الْبَيْتِ}} = এই ঘর (শব্দগুচ্ছ, বাক্য নয়)","en":"{{هٰذَا الْبَيْتِ}} = this House (a phrase, not a sentence)"},"hl":"هٰذَا الْبَيْتِ"}]},{"type":"tip","kind":"fun","bn":"দুজনের জন্যও ইশারা শব্দ আছে: {{هٰذَانِ}} (এই দুজন – পুং), {{هٰتَانِ}} (এই দুজন – স্ত্রী)। কুরআনে কম আসে, তবে দেখলে চিনতে পারবে — শেষে সেই পরিচিত {{ـَانِ}}!","en":"There are pointing words for two as well: {{هٰذَانِ}} (these two, m), {{هٰتَانِ}} (these two, f). Rare in the Quran, but you'll recognise the familiar {{ـَانِ}} ending!"},{"type":"text","title":{"bn":"সংযোগ শব্দ: যে, যিনি, যারা","en":"Linking words: who, which"},"bn":"বাংলায় বলি — ‘**যিনি** সৃষ্টি করেছেন’, ‘**যারা** ঈমান এনেছে’। আরবিতে এই ‘যে/যিনি/যারা’-কে বলে **ইসমে মাওসূল** ({{اِسْمٌ مَوْصُولٌ}})। এরা দুটো কথাকে জুড়ে দেয়।","en":"We say 'the One **who** created', 'those **who** believe'. In Arabic these 'who/which' words are called **relative nouns** ({{اِسْمٌ مَوْصُولٌ}}). They link two ideas together."},{"type":"table","head":[{"bn":"আরবি","en":"Arabic"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"},{"bn":"কার জন্য","en":"For"}],"rows":[["الَّذِي",{"bn":"আল্লাযী","en":"alladhī"},{"bn":"যে / যিনি","en":"who / which"},{"bn":"পুং · এক","en":"m · one"}],["الَّتِي",{"bn":"আল্লাতী","en":"allatī"},{"bn":"যে / যিনি (স্ত্রী)","en":"who / which (f)"},{"bn":"স্ত্রী · এক","en":"f · one"}],["الَّذِينَ",{"bn":"আল্লাযীনা","en":"alladhīna"},{"bn":"যারা","en":"those who"},{"bn":"পুং · বহু","en":"m · many"}]]},{"type":"examples","items":[{"ar":"اِقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ","tr":{"bn":"ইকরা' বিসমি রব্বিকাল্লাযী খালাক","en":"iqra' bismi rabbikal-ladhī khalaq"},"mean":{"bn":"পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন (৯৬:১)","en":"Read in the name of your Lord who created (96:1)"},"hl":"الَّذِي"},{"ar":"الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ","tr":{"bn":"আল্লাযীনা ইউ'মিনূনা বিল গাইব","en":"alladhīna yu'minūna bil-ghayb"},"mean":{"bn":"যারা অদৃশ্যে বিশ্বাস করে (২:৩)","en":"Those who believe in the unseen (2:3)"},"hl":"الَّذِينَ"},{"ar":"فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجَارَةُ","tr":{"bn":"ফাত্তাকুন নারাল্লাতী ওয়াকূদুহান নাসু ওয়াল হিজারাহ","en":"fattaqun-nāral-latī waqūduhan-nāsu wal-ḥijārah"},"mean":{"bn":"সেই আগুনকে ভয় করো, যার জ্বালানি মানুষ ও পাথর (২:২৪)","en":"Fear the Fire whose fuel is people and stones (2:24)"},"note":{"bn":"{{النَّارَ}} মুআন্নাস, তাই {{الَّتِي}}","en":"{{النَّارَ}} is feminine, so {{الَّتِي}}"},"hl":"الَّتِي"},{"ar":"الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ","tr":{"bn":"আল্লাযী আত্ব'আমাহুম মিন জূ'ইন","en":"alladhī aṭ'amahum min jū'in"},"mean":{"bn":"যিনি তাদের ক্ষুধায় খাবার দিয়েছেন (১০৬:৪)","en":"Who fed them against hunger (106:4)"},"hl":"الَّذِي"}]},{"type":"quiz","items":[{"q":{"bn":"‘এই’ (কাছের, স্ত্রীলিঙ্গ) কোনটি?","en":"Which is 'this' (near, feminine)?"},"options":["هٰذِهِ","ذٰلِكَ","تِلْكَ","هٰذَا"],"answer":0},{"q":{"bn":"{{أُولٰئِكَ}} অর্থ কী?","en":"What does {{أُولٰئِكَ}} mean?"},"ar":"أُولٰئِكَ","options":[{"bn":"এরা","en":"these"},{"bn":"ওরা / তারা (দূরের)","en":"those"},{"bn":"সে","en":"he"}],"answer":1},{"q":{"bn":"‘এটি একটি ঘর।’ — পূর্ণ বাক্য কোনটি?","en":"Which is the full sentence 'This is a house.'?"},"options":["بَيْتُ هٰذَا","هٰذَا الْبَيْتُ","هٰذَا بَيْتٌ"],"answer":2,"explain":{"bn":"{{هٰذَا}}-এর পরে তানবীনযুক্ত শব্দ = পূর্ণ বাক্য।","en":"{{هٰذَا}} + a word with tanween = full sentence."}},{"q":{"bn":"{{الَّذِينَ}} অর্থ কী?","en":"What does {{الَّذِينَ}} mean?"},"ar":"الَّذِينَ","options":[{"bn":"যারা","en":"those who"},{"bn":"এরা","en":"these"},{"bn":"যিনি","en":"the one who"}],"answer":0},{"q":{"bn":"{{النَّارَ ... وَقُودُهَا}} — এখানে {{الَّتِي}} কেন, {{الَّذِي}} নয়?","en":"Why {{الَّتِي}} and not {{الَّذِي}} with {{النَّارَ}}?"},"options":[{"bn":"{{نَارٌ}} বহুবচন","en":"{{نَارٌ}} is plural"},{"bn":"{{نَارٌ}} মুআন্নাস","en":"{{نَارٌ}} is feminine"},{"bn":"{{نَارٌ}} ফে'ল","en":"{{نَارٌ}} is a verb"}],"answer":1},{"q":{"bn":"দূরের ইশারা শব্দগুলোর মধ্যে কোন অক্ষরটি সাধারণ?","en":"Which letter do the 'far' pointing words share?"},"options":["م","ه","ك"],"answer":2}]}]},{"id":"g-nominal","icon":"جملة","title":{"bn":"নামবাচক বাক্য: মুবতাদা + খবর","en":"The Nominal Sentence: Mubtada + Khabar"},"subtitle":{"bn":"‘বইটি নতুন’ — আরবিতে ‘হয়/is’ লাগে না!","en":"'The book is new' — Arabic needs no 'is'!"},"minutes":15,"goals":[{"bn":"জুমলা ইসমিয়্যা (নামবাচক বাক্য) চিনবে","en":"Recognise the nominal sentence (jumla ismiyya)"},{"bn":"মুবতাদা ও খবর আলাদা করতে পারবে","en":"Separate the mubtada (subject) and khabar (predicate)"},{"bn":"‘বইটি নতুন’ বনাম ‘নতুন বইটি’-র পার্থক্য বুঝবে","en":"Tell 'the book is new' from 'the new book'"}],"blocks":[{"type":"text","bn":"একটা মজার কথা: বাংলায় আমরা বলি ‘আমি ছাত্র’, ‘আকাশ নীল’ — মাঝে ‘হই’ বা ‘হয়’ লাগে না! আরবিও ঠিক তেমন: {{اَلْكِتَابُ جَدِيدٌ}} = ‘বইটি নতুন’। ইসম দিয়ে শুরু হওয়া এমন বাক্যকে বলে **জুমলা ইসমিয়্যা** ({{جُمْلَةٌ اِسْمِيَّةٌ}})।","en":"Here's a fun fact: Arabic has no word for 'is/are' in the present. {{اَلْكِتَابُ جَدِيدٌ}} = 'The book (is) new'. A sentence that starts with a noun like this is a **nominal sentence** ({{جُمْلَةٌ اِسْمِيَّةٌ}})."},{"type":"table","title":{"bn":"দুটি অংশ","en":"Two parts"},"head":[{"bn":"অংশ","en":"Part"},{"bn":"কাজ","en":"Job"},{"bn":"সাধারণ চেহারা","en":"Usual look"}],"rows":[[{"bn":"মুবতাদা ({{مُبْتَدَأٌ}})","en":"Mubtada ({{مُبْتَدَأٌ}})"},{"bn":"যার কথা বলছি (উদ্দেশ্য)","en":"What we talk about (subject)"},{"bn":"নির্দিষ্ট, শেষে পেশ: {{اَلْكِتَابُ}}","en":"Definite, ends in damma: {{اَلْكِتَابُ}}"}],[{"bn":"খবর ({{خَبَرٌ}})","en":"Khabar ({{خَبَرٌ}})"},{"bn":"তার সম্পর্কে খবর (বিধেয়)","en":"The news about it (predicate)"},{"bn":"প্রায়ই অনির্দিষ্ট, শেষে দুই পেশ: {{جَدِيدٌ}}","en":"Often indefinite, ends in ٌ: {{جَدِيدٌ}}"}]]},{"type":"examples","title":{"bn":"সহজ বাক্য","en":"Simple sentences"},"items":[{"ar":"اَلْكِتَابُ جَدِيدٌ","tr":{"bn":"আল-কিতাবু জাদীদুন","en":"al-kitābu jadīdun"},"mean":{"bn":"বইটি নতুন।","en":"The book is new."},"hl":"جَدِيدٌ"},{"ar":"اَلْبَيْتُ كَبِيرٌ","tr":{"bn":"আল-বাইতু কাবীরুন","en":"al-baytu kabīrun"},"mean":{"bn":"ঘরটি বড়।","en":"The house is big."},"hl":"كَبِيرٌ"},{"ar":"أَنَا مُسْلِمٌ","tr":{"bn":"আনা মুসলিমুন","en":"anā muslimun"},"mean":{"bn":"আমি মুসলিম।","en":"I am a Muslim."},"note":{"bn":"সর্বনামও মুবতাদা হতে পারে","en":"A pronoun can be the mubtada"},"hl":"مُسْلِمٌ"},{"ar":"نَحْنُ مُسْلِمُونَ","tr":{"bn":"নাহনু মুসলিমূন","en":"naḥnu muslimūn"},"mean":{"bn":"আমরা মুসলিম।","en":"We are Muslims."},"hl":"مُسْلِمُونَ"},{"ar":"اَللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"allāhu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়।","en":"Allah is the Greatest."},"note":{"bn":"আজানের প্রথম কথাটিই একটি জুমলা ইসমিয়্যা!","en":"The very first words of the adhan are a nominal sentence!"},"hl":"أَكْبَرُ"}]},{"type":"compare","title":{"bn":"সবচেয়ে গুরুত্বপূর্ণ পার্থক্য","en":"The most important difference"},"items":[{"ar":"اَلْكِتَابُ جَدِيدٌ","label":{"bn":"বাক্য ✓","en":"Sentence ✓"},"desc":{"bn":"‘বইটি নতুন।’ — দ্বিতীয় শব্দে {{اَلْ}} নেই","en":"'The book is new.' — 2nd word has no {{اَلْ}}"}},{"ar":"اَلْكِتَابُ الْجَدِيدُ","label":{"bn":"শব্দগুচ্ছ","en":"Phrase"},"desc":{"bn":"‘নতুন বইটি…’ — দুটোতেই {{اَلْ}}; কথা শেষ হয়নি","en":"'The new book...' — both have {{اَلْ}}; not finished yet"}}]},{"type":"tip","kind":"memory","bn":"সূত্র: **{{اَلْ}} + {{اَلْ}} = জোড়া (বিশেষণ)**; **{{اَلْ}} + তানবীন = বাক্য**। দ্বিতীয় শব্দে {{اَلْ}} না দেখলেই মনে মনে মাঝে ‘হলো’ বসিয়ে নাও!","en":"Rule of thumb: **{{اَلْ}} + {{اَلْ}} = a pair (adjective)**; **{{اَلْ}} + tanween = a sentence**. If the second word has no {{اَلْ}}, mentally slip in 'is'!"},{"type":"examples","title":{"bn":"কুরআনের জুমলা ইসমিয়্যা","en":"Nominal sentences in the Quran"},"items":[{"ar":"اَللّٰهُ الصَّمَدُ","tr":{"bn":"আল্লাহুস সামাদ","en":"allāhuṣ-ṣamad"},"mean":{"bn":"আল্লাহ অমুখাপেক্ষী (১১২:২)","en":"Allah is the Eternal Refuge (112:2)"},"note":{"bn":"এখানে খবরেও {{اَلْ}} — অর্থ: ‘একমাত্র তিনিই’ সামাদ","en":"Here the khabar also has {{اَلْ}} — meaning 'He alone' is aṣ-Ṣamad"}},{"ar":"مُحَمَّدٌ رَسُولُ اللّٰهِ","tr":{"bn":"মুহাম্মাদুর রাসূলুল্লাহ","en":"muḥammadur-rasūlullāh"},"mean":{"bn":"মুহাম্মাদ আল্লাহর রাসূল (৪৮:২৯)","en":"Muhammad is the Messenger of Allah (48:29)"},"hl":"رَسُولُ اللّٰهِ"},{"ar":"وَاللّٰهُ غَفُورٌ رَحِيمٌ","tr":{"bn":"ওয়াল্লাহু গাফূরুর রাহীম","en":"wallāhu ghafūrur-raḥīm"},"mean":{"bn":"আর আল্লাহ ক্ষমাশীল, পরম দয়ালু (২:২১৮)","en":"And Allah is Forgiving, Merciful (2:218)"},"note":{"bn":"একই মুবতাদার দুটি খবর","en":"One mubtada with two khabars"},"hl":"غَفُورٌ رَحِيمٌ"},{"ar":"لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ","tr":{"bn":"লাইলাতুল কদরি খাইরুম মিন আলফি শাহর","en":"laylatul-qadri khayrum-min alfi shahr"},"mean":{"bn":"কদরের রাত হাজার মাসের চেয়েও উত্তম (৯৭:৩)","en":"The Night of Decree is better than a thousand months (97:3)"},"hl":"خَيْرٌ"},{"ar":"اَللّٰهُ نُورُ السَّمٰوَاتِ وَالْأَرْضِ","tr":{"bn":"আল্লাহু নূরুস সামা-ওয়াতি ওয়াল আরদ্ব","en":"allāhu nūrus-samāwāti wal-arḍ"},"mean":{"bn":"আল্লাহ আসমান ও জমিনের নূর (২৪:৩৫)","en":"Allah is the Light of the heavens and the earth (24:35)"},"hl":"نُورُ"}]},{"type":"text","title":{"bn":"খবর যখন হরফসহ শব্দগুচ্ছ","en":"When the khabar is a preposition phrase"},"bn":"খবর সবসময় একটা শব্দ হয় না; ‘কোথায়/কার জন্য’ বলা একটি শব্দগুচ্ছও খবর হতে পারে: {{اَلْحَمْدُ لِلّٰهِ}} = সব প্রশংসা **আল্লাহর জন্য**। আর মুবতাদা অনির্দিষ্ট হলে খবর **আগে** চলে আসে: {{فِي قُلُوبِهِمْ مَرَضٌ}} = তাদের অন্তরে (আছে) রোগ (২:১০)।","en":"The khabar isn't always one word; a 'where/for whom' phrase can be the khabar: {{اَلْحَمْدُ لِلّٰهِ}} = all praise is **for Allah**. And when the mubtada is indefinite, the khabar comes **first**: {{فِي قُلُوبِهِمْ مَرَضٌ}} = in their hearts is a disease (2:10)."},{"type":"tip","kind":"warn","bn":"আগাম খবর: বাক্যের শুরুতে {{إِنَّ}} (নিশ্চয়ই) বসলে মুবতাদার পেশ **যবর** হয়ে যায়, খবর পেশই থাকে: {{اَللّٰهُ غَفُورٌ}} → {{إِنَّ اللّٰهَ غَفُورٌ رَحِيمٌ}} (২:১৭৩)। অর্থ শুধু জোরালো হয়।","en":"Sneak peek: when {{إِنَّ}} (indeed) starts the sentence, the mubtada's damma turns into **fatha**, while the khabar keeps its damma: {{اَللّٰهُ غَفُورٌ}} → {{إِنَّ اللّٰهَ غَفُورٌ رَحِيمٌ}} (2:173). The meaning just gets stronger."},{"type":"quiz","items":[{"q":{"bn":"{{اَلْبَيْتُ كَبِيرٌ}} অর্থ কী?","en":"What does {{اَلْبَيْتُ كَبِيرٌ}} mean?"},"ar":"اَلْبَيْتُ كَبِيرٌ","options":[{"bn":"ঘরটি বড়।","en":"The house is big."},{"bn":"একটি বড় ঘর","en":"a big house"},{"bn":"বড় ঘরটি","en":"the big house"}],"answer":0},{"q":{"bn":"কোনটি পূর্ণ বাক্য?","en":"Which one is a full sentence?"},"options":["اَلْقَلَمُ الْجَدِيدُ","اَلْقَلَمُ جَدِيدٌ","قَلَمٌ جَدِيدٌ"],"answer":1,"explain":{"bn":"{{اَلْ}} + তানবীন = বাক্য: ‘কলমটি নতুন।’","en":"{{اَلْ}} + tanween = sentence: 'The pen is new.'"}},{"q":{"bn":"{{مُحَمَّدٌ رَسُولُ اللّٰهِ}} — মুবতাদা কোনটি?","en":"In {{مُحَمَّدٌ رَسُولُ اللّٰهِ}}, which is the mubtada?"},"options":["اللّٰهِ","رَسُولُ","مُحَمَّدٌ"],"answer":2},{"q":{"bn":"আরবিতে বর্তমান কালে ‘হয়/is’-এর জন্য আলাদা শব্দ…","en":"In the present tense, Arabic's word for 'is'..."},"options":[{"bn":"লাগে না","en":"is not needed"},{"bn":"সবসময় লাগে","en":"is always needed"},{"bn":"শুধু প্রশ্নে লাগে","en":"is only used in questions"}],"answer":0},{"q":{"bn":"মুবতাদা ও খবরের শেষে সাধারণত কোন হরকত?","en":"What ending do mubtada and khabar usually have?"},"options":[{"bn":"যের","en":"kasra"},{"bn":"পেশ","en":"damma"},{"bn":"যবর","en":"fatha"}],"answer":1},{"q":{"bn":"{{اَلْحَمْدُ لِلّٰهِ}} — খবর কোনটি?","en":"In {{اَلْحَمْدُ لِلّٰهِ}}, what is the khabar?"},"options":["اَلْحَمْدُ",{"bn":"খবর নেই","en":"There is none"},"لِلّٰهِ"],"answer":2,"explain":{"bn":"হরফসহ শব্দগুচ্ছ {{لِلّٰهِ}} (আল্লাহর জন্য) হলো খবর।","en":"The phrase {{لِلّٰهِ}} (for Allah) is the khabar."}}]}]},{"id":"g-prepositions","icon":"فِي","title":{"bn":"হরফে জার ও যের","en":"Prepositions and the Kasra"},"subtitle":{"bn":"যে ছোট্ট শব্দগুলো পরের শব্দকে ‘যের’-এ টেনে নামায়","en":"Little words that pull the next word down to kasra"},"minutes":15,"goals":[{"bn":"কুরআনের প্রধান হরফে জার ও তাদের অর্থ শিখবে","en":"Learn the main Quranic prepositions and their meanings"},{"bn":"জানবে হরফে জারের পরের ইসম কেন যের পায় (মাজরূর)","en":"Know why the noun after them takes kasra (majrūr)"},{"bn":"ই'রাবের তিন অবস্থা — পেশ, যবর, যের — এক নজরে দেখবে","en":"See the three case endings — damma, fatha, kasra — at a glance"}],"blocks":[{"type":"text","bn":"বাংলায় বলি ‘ঘরে’, ‘ঘর থেকে’, ‘ঘরের দিকে’ — এখানে ‘-এ’, ‘থেকে’, ‘দিকে’ বসে শব্দের **পরে**। আরবিতে এমন শব্দ বসে **আগে**: {{فِي الْبَيْتِ}} (ঘরের মধ্যে)। এদের বলে **হরফে জার** ({{حُرُوفُ الْجَرِّ}})। ‘জার’ মানে টানা — এরা পরের শব্দের শেষ হরকতকে টেনে **যের** বানিয়ে দেয়!","en":"English has words like 'in', 'from', 'to' — and Arabic has them too, placed **before** the noun: {{فِي الْبَيْتِ}} (in the house). They are called **ḥurūf al-jarr**. 'Jarr' means pulling — they pull the next word's ending down to **kasra**!"},{"type":"table","title":{"bn":"কুরআনের প্রধান হরফে জার","en":"Main prepositions of the Quran"},"head":[{"bn":"হরফ","en":"Preposition"},{"bn":"অর্থ","en":"Meaning"},{"bn":"উদাহরণ","en":"Example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["بِـ",{"bn":"দিয়ে, দ্বারা, সাথে","en":"with, by"},"بِسْمِ اللّٰهِ",{"bn":"আল্লাহর নামে","en":"in the name of Allah"}],["لِـ",{"bn":"জন্য, -এর","en":"for, belongs to"},"لِلّٰهِ",{"bn":"আল্লাহর জন্য","en":"for Allah"}],["فِي",{"bn":"মধ্যে, -তে","en":"in"},"فِي الْأَرْضِ",{"bn":"পৃথিবীতে","en":"in the earth"}],["مِنْ",{"bn":"থেকে","en":"from, of"},"مِنَ السَّمَاءِ",{"bn":"আকাশ থেকে","en":"from the sky"}],["إِلٰى",{"bn":"দিকে, পর্যন্ত","en":"to, towards"},"إِلَى اللّٰهِ",{"bn":"আল্লাহর দিকে","en":"to Allah"}],["عَلٰى",{"bn":"উপরে","en":"on, upon"},"عَلَى اللّٰهِ",{"bn":"আল্লাহর উপর","en":"upon Allah"}],["عَنْ",{"bn":"সম্পর্কে, থেকে (দূরে)","en":"about, away from"},"عَنِ النَّبَإِ",{"bn":"সংবাদ সম্পর্কে","en":"about the news"}],["كَـ",{"bn":"মতো","en":"like"},"كَالْعِهْنِ",{"bn":"পশমের মতো","en":"like wool"}],["حَتّٰى",{"bn":"পর্যন্ত","en":"until"},"حَتّٰى مَطْلَعِ الْفَجْرِ",{"bn":"ফজর উদয় পর্যন্ত","en":"until the rise of dawn"}]]},{"type":"table","title":{"bn":"আগে ও পরে: শেষ হরকত বদল","en":"Before and after: the ending changes"},"head":[{"bn":"একা","en":"Alone"},{"bn":"হরফে জারের পরে","en":"After a preposition"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كِتَابٌ","فِي كِتَابٍ",{"bn":"একটি কিতাবে","en":"in a book"}],["اَلْبَيْتُ","فِي الْبَيْتِ",{"bn":"ঘরটিতে","en":"in the house"}],["اللّٰهُ","بِاللّٰهِ",{"bn":"আল্লাহর প্রতি / আল্লাহ দিয়ে","en":"in / by Allah"}],["اَلْمُسْلِمُونَ","مِنَ الْمُسْلِمِينَ",{"bn":"মুসলিমদের মধ্য থেকে","en":"from among the Muslims"}],["مُسْلِمَاتٌ","لِمُسْلِمَاتٍ",{"bn":"মুসলিম নারীদের জন্য","en":"for Muslim women"}]]},{"type":"tip","kind":"memory","bn":"হরফে জারকে ভাবো একটা **চুম্বক**: পরের শব্দের শেষ হরকতকে নিচে টেনে **যের** বানায়। বহুবচনে {{ـُونَ}} টেনে {{ـِينَ}}, দ্বিবচনে {{ـَانِ}} টেনে {{ـَيْنِ}} — সবই এই চুম্বকের কাজ!","en":"Think of a preposition as a **magnet**: it pulls the next word's ending down to **kasra**. It pulls {{ـُونَ}} down to {{ـِينَ}}, and {{ـَانِ}} down to {{ـَيْنِ}} — all the magnet's work!"},{"type":"tip","kind":"tip","bn":"উচ্চারণের ছোট নিয়ম: {{اَلْ}}-এর আগে {{مِنْ}} হয়ে যায় {{مِنَ}} (মিনাস-সামা), {{عَنْ}} হয়ে যায় {{عَنِ}}। আর {{فِي}}, {{إِلٰى}}, {{عَلٰى}}-র লম্বা টান {{اَلْ}}-এর আগে ছোট হয়ে যায়: {{فِي الْأَرْضِ}} = ‘ফিল আরদ্ব’।","en":"Small pronunciation rules: before {{اَلْ}}, {{مِنْ}} becomes {{مِنَ}} (minas-samā') and {{عَنْ}} becomes {{عَنِ}}. And the long vowel of {{فِي}}, {{إِلٰى}}, {{عَلٰى}} is shortened before {{اَلْ}}: {{فِي الْأَرْضِ}} = 'fil-arḍ'."},{"type":"examples","title":{"bn":"কুরআনে হরফে জার","en":"Prepositions in the Quran"},"items":[{"ar":"مِنْ شَرِّ مَا خَلَقَ","tr":{"bn":"মিন শাররি মা খালাক","en":"min sharri mā khalaq"},"mean":{"bn":"তিনি যা সৃষ্টি করেছেন তার অনিষ্ট থেকে (১১৩:২)","en":"From the evil of what He created (113:2)"},"note":{"bn":"{{مِنْ}}-এর পরে {{شَرِّ}} — যের","en":"After {{مِنْ}}, {{شَرِّ}} takes kasra"},"hl":"شَرِّ"},{"ar":"وَإِلٰى رَبِّكَ فَارْغَبْ","tr":{"bn":"ওয়া ইলা রব্বিকা ফারগাব","en":"wa ilā rabbika farghab"},"mean":{"bn":"আর তোমার রবের দিকেই মনোযোগী হও (৯৪:৮)","en":"And to your Lord turn with longing (94:8)"},"hl":"رَبِّكَ"},{"ar":"عَنِ النَّبَإِ الْعَظِيمِ","tr":{"bn":"আনিন নাবাইল আযীম","en":"'anin-naba'il-'aẓīm"},"mean":{"bn":"মহা সংবাদ সম্পর্কে (৭৮:২)","en":"About the great news (78:2)"},"hl":"عَنِ"},{"ar":"وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ","tr":{"bn":"ওয়া তাকূনুল জিবালু কাল ইহনিল মানফূশ","en":"wa takūnul-jibālu kal-'ihnil-manfūsh"},"mean":{"bn":"আর পাহাড়গুলো হবে ধুনা পশমের মতো (১০১:৫)","en":"And the mountains will be like fluffed-up wool (101:5)"},"hl":"كَالْعِهْنِ"},{"ar":"فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ","tr":{"bn":"ফাজা'আলাহুম কা'আসফিম মা'কূল","en":"faja'alahum ka'aṣfim-ma'kūl"},"mean":{"bn":"তারপর তিনি তাদের করে দিলেন চিবানো ভুসির মতো (১০৫:৫)","en":"Then He made them like chewed-up straw (105:5)"},"note":{"bn":"{{كَـ}}-এর পরে তানবীনসহ যের: {{عَصْفٍ}}","en":"After {{كَـ}}: kasra with tanween, {{عَصْفٍ}}"},"hl":"كَعَصْفٍ"},{"ar":"وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ","tr":{"bn":"ওয়া আলাল্লাহি ফালইয়াতাওয়াক্কালিল মু'মিনূন","en":"wa 'alallāhi falyatawakkalil-mu'minūn"},"mean":{"bn":"আর মুমিনরা যেন আল্লাহর উপরই ভরসা করে (৩:১২২)","en":"And upon Allah let the believers rely (3:122)"},"hl":"عَلَى اللّٰهِ"}]},{"type":"tip","kind":"fun","bn":"{{وَالْعَصْرِ}}, {{وَالشَّمْسِ}}, {{وَالْفَجْرِ}} — শপথের {{وَ}} ‘এবং’ নয়, ‘শপথ!’। এটিও এক ধরনের হরফে জার, তাই পরের শব্দে যের!","en":"{{وَالْعَصْرِ}}, {{وَالشَّمْسِ}}, {{وَالْفَجْرِ}} — this {{وَ}} isn't 'and' but 'By...!' (an oath). It also works like a preposition, so the next word takes kasra!"},{"type":"table","title":{"bn":"ই'রাব এক নজরে: শেষ হরকত = শব্দের কাজ","en":"Case endings at a glance: last vowel = the word's job"},"head":[{"bn":"অবস্থা","en":"Case"},{"bn":"চিহ্ন","en":"Sign"},{"bn":"সাধারণ কাজ","en":"Typical job"},{"bn":"উদাহরণ","en":"Example"}],"rows":[[{"bn":"রফ' (পেশ অবস্থা)","en":"Raf'"},"ـُ ـٌ",{"bn":"মুবতাদা, খবর, কর্তা","en":"Subject, predicate, doer"},"قُلْ هُوَ اللّٰهُ أَحَدٌ"],[{"bn":"নাসব (যবর অবস্থা)","en":"Naṣb"},"ـَ ـً",{"bn":"কর্ম; {{إِنَّ}}-এর পরের ইসম","en":"Object; the noun after {{إِنَّ}}"},"إِنَّ اللّٰهَ"],[{"bn":"জার (যের অবস্থা)","en":"Jarr"},"ـِ ـٍ",{"bn":"হরফে জারের পরে; মালিকানায় দ্বিতীয় শব্দ","en":"After a preposition; 2nd word of possession"},"بِسْمِ اللّٰهِ"]]},{"type":"tip","kind":"warn","bn":"{{مَعَ}} (সাথে) ব্যাকরণে আসলে হরফ নয়, একটি ইসম (যরফ) — কিন্তু এর পরের শব্দও যের পায়: {{إِنَّ اللّٰهَ مَعَ الصَّابِرِينَ}} (নিশ্চয়ই আল্লাহ ধৈর্যশীলদের সাথে আছেন, ২:১৫৩)।","en":"{{مَعَ}} (with) is technically a noun of place/time, not a harf — but the word after it also takes kasra: {{إِنَّ اللّٰهَ مَعَ الصَّابِرِينَ}} (Indeed Allah is with the patient, 2:153)."},{"type":"quiz","items":[{"q":{"bn":"{{عَلٰى}} অর্থ কী?","en":"What does {{عَلٰى}} mean?"},"ar":"عَلٰى","options":[{"bn":"থেকে","en":"from"},{"bn":"মতো","en":"like"},{"bn":"মধ্যে","en":"in"},{"bn":"উপরে","en":"on / upon"}],"answer":3},{"q":{"bn":"‘ঘরটিতে’ সঠিকভাবে কোনটি?","en":"Which correctly says 'in the house'?"},"options":["فِي الْبَيْتِ","فِي الْبَيْتَ","فِي الْبَيْتُ"],"answer":0,"explain":{"bn":"হরফে জারের পরে ইসম যের পায়।","en":"A noun after a preposition takes kasra."}},{"q":{"bn":"{{مِنْ}} + {{الْمُؤْمِنُونَ}} = ?","en":"{{مِنْ}} + {{الْمُؤْمِنُونَ}} = ?"},"options":["مِنَ الْمُؤْمِنُونَ","مِنَ الْمُؤْمِنِينَ","مِنْ الْمُؤْمِنَانِ"],"answer":1},{"q":{"bn":"{{كَعَصْفٍ}}-এ {{كَـ}} অর্থ কী?","en":"In {{كَعَصْفٍ}}, what does {{كَـ}} mean?"},"ar":"كَعَصْفٍ","options":[{"bn":"দিয়ে","en":"with"},{"bn":"জন্য","en":"for"},{"bn":"মতো","en":"like"}],"answer":2},{"q":{"bn":"‘জার’ শব্দের অর্থ কী?","en":"What does 'jarr' mean?"},"options":[{"bn":"টানা","en":"pulling"},{"bn":"ঠেলা","en":"pushing"},{"bn":"থামা","en":"stopping"}],"answer":0},{"q":{"bn":"{{وَالْعَصْرِ}}-এর {{وَ}} এখানে কী অর্থে?","en":"What does {{وَ}} mean in {{وَالْعَصْرِ}}?"},"options":[{"bn":"এবং","en":"and"},{"bn":"শপথ","en":"by (an oath)"},{"bn":"অথবা","en":"or"}],"answer":1},{"q":{"bn":"{{بِسْمِ اللّٰهِ}}-তে {{اللّٰهِ}}-এর শেষে যের কেন?","en":"Why does {{اللّٰهِ}} end in kasra in {{بِسْمِ اللّٰهِ}}?"},"options":[{"bn":"এটি মুবতাদা","en":"It is the mubtada"},{"bn":"এটি কর্ম","en":"It is the object"},{"bn":"এটি মালিকানার দ্বিতীয় শব্দ (নামটি আল্লাহর)","en":"It is the 2nd word of a possession (the name of Allah)"}],"answer":2,"explain":{"bn":"{{اسْمِ}} যের পেয়েছে {{بِ}}-এর কারণে; আর {{اللّٰهِ}} যের পেয়েছে মালিকানার কারণে — পরের পাঠে বিস্তারিত।","en":"{{اسْمِ}} has kasra because of {{بِ}}; {{اللّٰهِ}} has kasra because of possession — details in the next lesson."}}]}]},{"id":"g-idafa","icon":"ـِ","title":{"bn":"মালিকানা: ইযাফা (আল্লাহর রাসূল)","en":"Possession: Idafa (the Messenger of Allah)"},"subtitle":{"bn":"দুটি ইসম পাশাপাশি বসে ‘-এর’ অর্থ তৈরি করে","en":"Two nouns side by side make an 'of' phrase"},"minutes":15,"goals":[{"bn":"ইযাফা — মুযাফ ও মুযাফ ইলাইহি চিনবে","en":"Recognise idafa — the mudaf and mudaf ilayh"},{"bn":"ইযাফার দুটি সোনালি নিয়ম মনে রাখবে","en":"Remember the two golden rules of idafa"},{"bn":"{{مٰلِكِ يَوْمِ الدِّينِ}}-এর মতো লম্বা শিকল বুঝবে","en":"Understand longer chains like {{مٰلِكِ يَوْمِ الدِّينِ}}"}],"blocks":[{"type":"text","bn":"বাংলায় বলি ‘আল্লাহ**র** রাসূল’ — মালিক আগে, তার সাথে ‘-র’। আরবিতে উল্টো: আগে জিনিস, পরে মালিক — {{رَسُولُ اللّٰهِ}} (রাসূল + আল্লাহর)। আর বাংলার সেই ‘-র’-এর কাজ করে মালিক-শব্দের শেষের **যের**! এই গঠনের নাম **ইযাফা** ({{إِضَافَةٌ}})।","en":"English says 'the Messenger **of** Allah'. Arabic simply puts two nouns side by side — the thing first, the owner second: {{رَسُولُ اللّٰهِ}}. The word 'of' is shown by the **kasra** on the owner word! This structure is called **idafa** ({{إِضَافَةٌ}})."},{"type":"table","head":[{"bn":"অংশ","en":"Part"},{"bn":"উদাহরণ","en":"Example"},{"bn":"নিয়ম","en":"Rule"}],"rows":[[{"bn":"মুযাফ (যার মালিকানা)","en":"Mudaf (the thing owned)"},"رَسُولُ",{"bn":"{{اَلْ}} নেই, তানবীন নেই","en":"No {{اَلْ}}, no tanween"}],[{"bn":"মুযাফ ইলাইহি (মালিক)","en":"Mudaf ilayh (the owner)"},"اللّٰهِ",{"bn":"সবসময় যের অবস্থায় (মাজরূর)","en":"Always in the kasra case (majrūr)"}]]},{"type":"tip","kind":"memory","bn":"পড়ার কৌশল: **উল্টো দিক থেকে পড়ো, আর যেরকে ‘-র/-এর’ ভাবো।** {{بَيْتُ اللّٰهِ}} → ‘আল্লাহ-**র** ঘর’। {{يَوْمِ الدِّينِ}} → ‘বিচার-**এর** দিন’।","en":"Reading trick: **read the first word, then say 'of', then the second.** {{بَيْتُ اللّٰهِ}} → 'house **of** Allah'. {{يَوْمِ الدِّينِ}} → 'Day **of** Judgement'."},{"type":"examples","title":{"bn":"কুরআনের পরিচিত ইযাফা","en":"Familiar idafas from the Quran"},"items":[{"ar":"رَسُولُ اللّٰهِ","tr":{"bn":"রাসূলুল্লাহ","en":"rasūlullāh"},"mean":{"bn":"আল্লাহর রাসূল (৪৮:২৯)","en":"the Messenger of Allah (48:29)"}},{"ar":"بَيْتُ اللّٰهِ","tr":{"bn":"বাইতুল্লাহ","en":"baytullāh"},"mean":{"bn":"আল্লাহর ঘর (কা'বা)","en":"the House of Allah (the Ka'bah)"}},{"ar":"رَبِّ الْعٰلَمِينَ","tr":{"bn":"রব্বিল আলামীন","en":"rabbil-'ālamīn"},"mean":{"bn":"সকল জগতের রব (১:২)","en":"Lord of the worlds (1:2)"}},{"ar":"نَصْرُ اللّٰهِ","tr":{"bn":"নাসরুল্লাহ","en":"naṣrullāh"},"mean":{"bn":"আল্লাহর সাহায্য (১১০:১)","en":"the help of Allah (110:1)"}},{"ar":"بِأَصْحَابِ الْفِيلِ","tr":{"bn":"বিআসহাবিল ফীল","en":"bi-aṣḥābil-fīl"},"mean":{"bn":"হাতিওয়ালাদের সাথে (১০৫:১)","en":"with the companions of the elephant (105:1)"},"hl":"أَصْحَابِ الْفِيلِ"},{"ar":"لَيْلَةُ الْقَدْرِ","tr":{"bn":"লাইলাতুল কদর","en":"laylatul-qadr"},"mean":{"bn":"কদরের রাত (৯৭:৩)","en":"the Night of Decree (97:3)"}},{"ar":"فِي دِينِ اللّٰهِ أَفْوَاجًا","tr":{"bn":"ফী দীনিল্লাহি আফওয়াজা","en":"fī dīnillāhi afwājā"},"mean":{"bn":"দলে দলে আল্লাহর দ্বীনে (১১০:২)","en":"into the religion of Allah in crowds (110:2)"},"hl":"دِينِ اللّٰهِ"}]},{"type":"tip","kind":"warn","bn":"মুযাফে কখনো {{اَلْ}} বা তানবীন বসে না: ‘اَلرَّسُولُ اللّٰهِ’ ✗ বা ‘رَسُولٌ اللّٰهِ’ ✗ — সঠিক শুধু {{رَسُولُ اللّٰهِ}} ✓। কারণ মালিকের নাম যুক্ত হলেই সে নির্দিষ্ট হয়ে যায়।","en":"The mudaf never takes {{اَلْ}} or tanween: 'اَلرَّسُولُ اللّٰهِ' ✗ or 'رَسُولٌ اللّٰهِ' ✗ — only {{رَسُولُ اللّٰهِ}} ✓. Adding the owner already makes it definite."},{"type":"table","title":{"bn":"একই {{رَبّ}} — তিন অবস্থায়","en":"The same {{رَبّ}} — in three cases"},"head":[{"bn":"আয়াত","en":"Ayah"},{"bn":"{{رَبّ}}-এর শেষ","en":"Ending of {{رَبّ}}"},{"bn":"কারণ","en":"Why"}],"rows":[["رَبُّ الْمَشْرِقَيْنِ",{"bn":"পেশ — (৫৫:১৭)","en":"damma — (55:17)"},{"bn":"তিনি (রব) — খবর/রফ'","en":"(He is the) Lord — raf'"}],["فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِ",{"bn":"যবর — (১০৬:৩)","en":"fatha — (106:3)"},{"bn":"ইবাদতের কর্ম — নাসব","en":"Object of 'worship' — naṣb"}],["قُلْ أَعُوذُ بِرَبِّ النَّاسِ",{"bn":"যের — (১১৪:১)","en":"kasra — (114:1)"},{"bn":"{{بِـ}}-এর পরে — জার","en":"After {{بِـ}} — jarr"}]]},{"type":"tip","kind":"tip","bn":"দেখলে তো? **মুযাফের** শেষ হরকত বাক্যে তার কাজ অনুযায়ী বদলায়; কিন্তু **মুযাফ ইলাইহি** ({{الْمَشْرِقَيْنِ}}, {{هٰذَا}}, {{النَّاسِ}}) সবসময় যের অবস্থায় থাকে।","en":"See? The **mudaf**'s ending changes with its job in the sentence; but the **mudaf ilayh** ({{الْمَشْرِقَيْنِ}}, {{هٰذَا}}, {{النَّاسِ}}) always stays in the kasra case."},{"type":"steps","title":{"bn":"তিন শব্দের শিকল: {{مٰلِكِ يَوْمِ الدِّينِ}} (১:৪)","en":"A three-word chain: {{مٰلِكِ يَوْمِ الدِّينِ}} (1:4)"},"items":[{"title":{"bn":"মালিক","en":"Master"},"ar":"مٰلِكِ","tr":{"bn":"মালিকি","en":"māliki"},"desc":{"bn":"মুযাফ — {{اَلْ}} বা তানবীন নেই; আগের {{اللّٰهِ}}-এর সাথে মিল রেখে যের","en":"Mudaf — no {{اَلْ}} or tanween; kasra to match {{اللّٰهِ}} before it"}},{"title":{"bn":"…দিনের","en":"...of the Day"},"ar":"يَوْمِ","tr":{"bn":"ইয়াওমি","en":"yawmi"},"desc":{"bn":"প্রথমটির মুযাফ ইলাইহি (যের), আবার পরেরটির মুযাফ — তাই {{اَلْ}} নেই","en":"Mudaf ilayh of the first (kasra), and mudaf of the next — so no {{اَلْ}}"}},{"title":{"bn":"…বিচারের","en":"...of Judgement"},"ar":"الدِّينِ","tr":{"bn":"আদ-দীন","en":"ad-dīn"},"desc":{"bn":"শেষ মুযাফ ইলাইহি — {{اَلْ}} আছে, যের অবস্থা","en":"Final mudaf ilayh — has {{اَلْ}}, kasra case"}}]},{"type":"text","title":{"bn":"জোড়া সর্বনামও ইযাফা!","en":"Attached pronouns are idafa too!"},"bn":"{{كِتَابُهُ}} (তার বই), {{رَبُّنَا}} (আমাদের রব) — এগুলোও আসলে ইযাফা: প্রথমটি মুযাফ, জোড়া সর্বনামটি মুযাফ ইলাইহি। তাই এখানেও প্রথম শব্দে {{اَلْ}} ও তানবীন থাকে না।","en":"{{كِتَابُهُ}} (his book), {{رَبُّنَا}} (our Lord) — these are idafa too: the noun is the mudaf, the attached pronoun is the mudaf ilayh. That's why the first word drops {{اَلْ}} and tanween."},{"type":"tip","kind":"fun","bn":"দ্বিবচন বা {{ـُونَ}} বহুবচন মুযাফ হলে শেষের {{ن}} ঝরে পড়ে: {{يَدَانِ}} (দুই হাত) → {{تَبَّتْ يَدَا أَبِي لَهَبٍ}} (ধ্বংস হোক আবু লাহাবের দুই হাত, ১১১:১)।","en":"When a dual or {{ـُونَ}} plural is a mudaf, its final {{ن}} drops off: {{يَدَانِ}} (two hands) → {{تَبَّتْ يَدَا أَبِي لَهَبٍ}} (Perish the two hands of Abu Lahab, 111:1)."},{"type":"quiz","items":[{"q":{"bn":"{{كِتَابُ اللّٰهِ}} অর্থ কী?","en":"What does {{كِتَابُ اللّٰهِ}} mean?"},"ar":"كِتَابُ اللّٰهِ","options":[{"bn":"আল্লাহর কিতাব","en":"the Book of Allah"},{"bn":"কিতাবের আল্লাহ","en":"the Allah of the book"},{"bn":"আল্লাহ একটি কিতাব","en":"Allah is a book"}],"answer":0},{"q":{"bn":"মুযাফ ইলাইহি সবসময় কোন অবস্থায় থাকে?","en":"What case is the mudaf ilayh always in?"},"options":[{"bn":"পেশ (রফ')","en":"Raf' (damma)"},{"bn":"যের (জার)","en":"Jarr (kasra)"},{"bn":"যবর (নাসব)","en":"Naṣb (fatha)"}],"answer":1},{"q":{"bn":"কোনটি সঠিক ইযাফা?","en":"Which idafa is correct?"},"options":["اَلْبَيْتُ اللّٰهِ","بَيْتٌ اللّٰهِ","بَيْتُ اللّٰهِ"],"answer":2,"explain":{"bn":"মুযাফে {{اَلْ}} বা তানবীন বসে না।","en":"The mudaf takes no {{اَلْ}} and no tanween."}},{"q":{"bn":"{{يَوْمِ الدِّينِ}} অর্থ কী?","en":"What does {{يَوْمِ الدِّينِ}} mean?"},"options":[{"bn":"বিচারের দিন","en":"the Day of Judgement"},{"bn":"দ্বীনের রাত","en":"the night of religion"},{"bn":"আজকের দিন","en":"today"}],"answer":0},{"q":{"bn":"{{رَبِّ النَّاسِ}} — মুযাফ কোনটি?","en":"In {{رَبِّ النَّاسِ}}, which is the mudaf?"},"options":["النَّاسِ","رَبِّ"],"answer":1},{"q":{"bn":"{{تَبَّتْ يَدَا}}-তে {{يَدَانِ}}-এর {{ن}} কোথায় গেল?","en":"In {{تَبَّتْ يَدَا}}, where did the {{ن}} of {{يَدَانِ}} go?"},"options":[{"bn":"ভুল করে বাদ পড়েছে","en":"Left out by mistake"},{"bn":"মুযাফ হওয়ায় ঝরে গেছে","en":"Dropped because it is a mudaf"},{"bn":"এটি একবচন","en":"It is singular"}],"answer":1}]}]},{"id":"g-adjectives","icon":"صفة","title":{"bn":"বিশেষণ: সিফাত ও মাওসূফের মিল","en":"Adjectives: Noun–Adjective Agreement"},"subtitle":{"bn":"বিশেষণ বিশেষ্যের ছায়া — চারটি জিনিসে হুবহু মিলে চলে","en":"The adjective is the noun's shadow — matching it in four ways"},"minutes":15,"goals":[{"bn":"মাওসূফ (বিশেষ্য) ও সিফাত (বিশেষণ) চিনবে","en":"Recognise the noun (mawṣūf) and adjective (ṣifa)"},{"bn":"চারটি মিলের নিয়ম শিখবে","en":"Learn the four agreement rules"},{"bn":"{{الصِّرَاطَ الْمُسْتَقِيمَ}}-এর মতো কুরআনি জোড়া বুঝবে","en":"Understand Quranic pairs like {{الصِّرَاطَ الْمُسْتَقِيمَ}}"}],"blocks":[{"type":"text","bn":"বাংলায় বিশেষণ আগে বসে: ‘সরল পথ’। আরবিতে বিশেষণ বসে **পরে**: {{الصِّرَاطَ الْمُسْتَقِيمَ}} (পথ — সরল)। বিশেষ্যকে বলে **মাওসূফ** ({{مَوْصُوفٌ}}), বিশেষণকে বলে **সিফাত** ({{صِفَةٌ}})।","en":"In English the adjective comes first: 'the straight path'. In Arabic it comes **after**: {{الصِّرَاطَ الْمُسْتَقِيمَ}} (the path — the straight). The noun is the **mawṣūf** ({{مَوْصُوفٌ}}), the adjective is the **ṣifa** ({{صِفَةٌ}})."},{"type":"tip","kind":"memory","bn":"**সিফাত হলো মাওসূফের ছায়া।** ছায়া যেমন তোমার সব নড়াচড়া নকল করে, সিফাতও মাওসূফের **চারটি** জিনিস হুবহু নকল করে: নির্দিষ্টতা, লিঙ্গ, বচন আর শেষ হরকত।","en":"**The adjective is the noun's shadow.** Just as your shadow copies every move, the adjective copies **four** things from its noun: definiteness, gender, number and case ending."},{"type":"table","title":{"bn":"চারটি মিল","en":"The four agreements"},"head":[{"bn":"মিল","en":"Agreement"},{"bn":"উদাহরণ","en":"Example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[[{"bn":"১. নির্দিষ্টতা","en":"1. Definiteness"},"كِتَابٌ كَبِيرٌ / اَلْكِتَابُ الْكَبِيرُ",{"bn":"একটি বড় বই / বড় বইটি","en":"a big book / the big book"}],[{"bn":"২. লিঙ্গ","en":"2. Gender"},"رَجُلٌ صَالِحٌ / اِمْرَأَةٌ صَالِحَةٌ",{"bn":"একজন নেককার পুরুষ / নারী","en":"a righteous man / woman"}],[{"bn":"৩. বচন","en":"3. Number"},"مُسْلِمَانِ صَالِحَانِ / مُسْلِمُونَ صَالِحُونَ",{"bn":"দুজন / অনেক নেককার মুসলিম","en":"two / many righteous Muslims"}],[{"bn":"৪. শেষ হরকত","en":"4. Case"},"كِتَابٌ كَبِيرٌ / فِي كِتَابٍ كَبِيرٍ",{"bn":"একটি বড় বই / একটি বড় বইয়ে","en":"a big book / in a big book"}]]},{"type":"examples","title":{"bn":"কুরআনের মাওসূফ–সিফাত","en":"Noun–adjective pairs in the Quran"},"items":[{"ar":"اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","tr":{"bn":"ইহদিনাস সিরাত্বাল মুস্তাকীম","en":"ihdinaṣ-ṣirāṭal-mustaqīm"},"mean":{"bn":"আমাদের সরল পথ দেখাও (১:৬)","en":"Guide us to the straight path (1:6)"},"note":{"bn":"দুটোতেই {{اَلْ}}, দুটোই পুং-একবচন, দুটোই যবর (কর্ম)","en":"Both have {{اَلْ}}, both masculine singular, both fatha (object)"},"hl":"الصِّرَاطَ الْمُسْتَقِيمَ"},{"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","tr":{"bn":"বিসমিল্লাহির রাহমানির রাহীম","en":"bismillāhir-raḥmānir-raḥīm"},"mean":{"bn":"পরম করুণাময়, অতি দয়ালু আল্লাহর নামে (১:১)","en":"In the name of Allah, the Most Gracious, the Most Merciful (1:1)"},"note":{"bn":"{{اللّٰهِ}} যের, তাই দুই সিফাতও যের","en":"{{اللّٰهِ}} has kasra, so both adjectives have kasra"},"hl":"الرَّحْمٰنِ الرَّحِيمِ"},{"ar":"وَكِتَابٌ مُبِينٌ","tr":{"bn":"ওয়া কিতাবুম মুবীন","en":"wa kitābum-mubīn"},"mean":{"bn":"এবং একটি সুস্পষ্ট কিতাব (৫:১৫)","en":"and a clear Book (5:15)"},"note":{"bn":"দুটোই অনির্দিষ্ট, দুটোই দুই পেশ","en":"Both indefinite, both with ٌ"},"hl":"كِتَابٌ مُبِينٌ"},{"ar":"وَلَهُمْ عَذَابٌ عَظِيمٌ","tr":{"bn":"ওয়া লাহুম আযাবুন আযীম","en":"wa lahum 'adhābun 'aẓīm"},"mean":{"bn":"আর তাদের জন্য আছে মহা শাস্তি (২:৭)","en":"And for them is a great punishment (2:7)"},"hl":"عَذَابٌ عَظِيمٌ"},{"ar":"فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ","tr":{"bn":"ফাহুওয়া ফী ঈশাতির রা-দ্বিয়াহ","en":"fahuwa fī 'īshatir-rāḍiyah"},"mean":{"bn":"সে থাকবে সন্তোষজনক জীবনে (১০১:৭)","en":"He will be in a pleasant life (101:7)"},"note":{"bn":"স্ত্রীলিঙ্গ + অনির্দিষ্ট + যের — চারটিই মিলেছে","en":"Feminine + indefinite + kasra — all four match"},"hl":"عِيشَةٍ رَاضِيَةٍ"},{"ar":"وَنَزَّلْنَا مِنَ السَّمَاءِ مَاءً مُبَارَكًا","tr":{"bn":"ওয়া নাযযালনা মিনাস সামা-ই মা-আম মুবারাকা","en":"wa nazzalnā minas-samā'i mā'am-mubārakā"},"mean":{"bn":"আর আমি আকাশ থেকে বরকতময় পানি বর্ষণ করেছি (৫০:৯)","en":"And We sent down blessed water from the sky (50:9)"},"note":{"bn":"কর্ম, তাই দুটোই দুই যবর","en":"An object, so both take ً"},"hl":"مَاءً مُبَارَكًا"},{"ar":"فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ","tr":{"bn":"ফাওয়াল্লি ওয়াজহাকা শাতরাল মাসজিদিল হারাম","en":"fawalli wajhaka shaṭral-masjidil-ḥarām"},"mean":{"bn":"তোমার মুখ মসজিদুল হারামের দিকে ফেরাও (২:১৪৪)","en":"Turn your face toward al-Masjid al-Haram (2:144)"},"hl":"الْمَسْجِدِ الْحَرَامِ"}]},{"type":"compare","title":{"bn":"আবার মনে করি","en":"Remember again"},"items":[{"ar":"اَلرَّسُولُ الْكَرِيمُ","label":{"bn":"মাওসূফ + সিফাত","en":"Noun + adjective"},"desc":{"bn":"‘সম্মানিত রাসূলটি’ — দুটোতেই {{اَلْ}}","en":"'The noble messenger' — both have {{اَلْ}}"}},{"ar":"اَلرَّسُولُ كَرِيمٌ","label":{"bn":"মুবতাদা + খবর","en":"Mubtada + khabar"},"desc":{"bn":"‘রাসূলটি সম্মানিত।’ — পূর্ণ বাক্য","en":"'The messenger is noble.' — a full sentence"}},{"ar":"رَسُولُ اللّٰهِ","label":{"bn":"ইযাফা","en":"Idafa"},"desc":{"bn":"‘আল্লাহর রাসূল’ — প্রথমটিতে {{اَلْ}} নেই, দ্বিতীয়টি যের","en":"'Messenger of Allah' — 1st has no {{اَلْ}}, 2nd has kasra"}}]},{"type":"tip","kind":"tip","bn":"সর্বনামযুক্ত শব্দ নির্দিষ্ট, তাই তার সিফাতে {{اَلْ}} বসে: {{اِقْرَأْ وَرَبُّكَ الْأَكْرَمُ}} — পড়ো, আর তোমার রব মহা সম্মানিত (৯৬:৩)। এখানে {{رَبُّكَ}} নির্দিষ্ট, তাই {{الْأَكْرَمُ}}।","en":"A word with a pronoun is definite, so its adjective takes {{اَلْ}}: {{اِقْرَأْ وَرَبُّكَ الْأَكْرَمُ}} — Read, and your Lord is the Most Generous (96:3). {{رَبُّكَ}} is definite, hence {{الْأَكْرَمُ}}."},{"type":"tip","kind":"fun","bn":"মজার ব্যতিক্রম: মানুষ নয় এমন জিনিসের বহুবচনের সিফাত প্রায়ই **স্ত্রী-একবচন** হয়: {{فِيهَا سُرُرٌ مَرْفُوعَةٌ}} — সেখানে আছে উঁচু উঁচু আসন (৮৮:১৩)। {{سُرُرٌ}} বহুবচন, কিন্তু {{مَرْفُوعَةٌ}} একবচন-স্ত্রী!","en":"A fun exception: plurals of non-human things often take a **feminine singular** adjective: {{فِيهَا سُرُرٌ مَرْفُوعَةٌ}} — in it are raised couches (88:13). {{سُرُرٌ}} is plural, but {{مَرْفُوعَةٌ}} is feminine singular!"},{"type":"quiz","items":[{"q":{"bn":"আরবিতে বিশেষণ কোথায় বসে?","en":"Where does the adjective go in Arabic?"},"options":[{"bn":"বিশেষ্যের আগে","en":"Before the noun"},{"bn":"বাক্যের শেষে","en":"At the end of the sentence"},{"bn":"বিশেষ্যের পরে","en":"After the noun"}],"answer":2},{"q":{"bn":"‘একটি বড় ঘর’ — সঠিক কোনটি?","en":"Which correctly says 'a big house'?"},"options":["بَيْتٌ كَبِيرٌ","بَيْتٌ الْكَبِيرُ","اَلْبَيْتُ كَبِيرٌ"],"answer":0},{"q":{"bn":"{{نَارٌ}}-এর সাথে কোন বিশেষণ সঠিক?","en":"Which adjective fits {{نَارٌ}}?"},"options":["حَامٍ","حَامِيَةٌ","اَلْحَامِيَةُ"],"answer":1,"explain":{"bn":"{{نَارٌ}} মুআন্নাস ও অনির্দিষ্ট — {{نَارٌ حَامِيَةٌ}} (১০১:১১)।","en":"{{نَارٌ}} is feminine and indefinite — {{نَارٌ حَامِيَةٌ}} (101:11)."}},{"q":{"bn":"{{الصِّرَاطَ الْمُسْتَقِيمَ}} — দুটো শব্দের শেষে যবর কেন?","en":"Why do both words in {{الصِّرَاطَ الْمُسْتَقِيمَ}} end in fatha?"},"options":[{"bn":"এরা মুবতাদা ও খবর","en":"They are mubtada and khabar"},{"bn":"এরা ইযাফা","en":"They are an idafa"},{"bn":"এরা {{اِهْدِنَا}}-এর কর্ম, আর সিফাত মাওসূফের হরকত নকল করে","en":"It's the object of {{اِهْدِنَا}}, and the adjective copies the noun's case"}],"answer":2},{"q":{"bn":"{{اَلرَّسُولُ كَرِيمٌ}} কী?","en":"What is {{اَلرَّسُولُ كَرِيمٌ}}?"},"options":[{"bn":"রাসূলটি সম্মানিত। (বাক্য)","en":"The messenger is noble. (sentence)"},{"bn":"সম্মানিত রাসূলটি (শব্দগুচ্ছ)","en":"the noble messenger (phrase)"},{"bn":"আল্লাহর রাসূল","en":"the Messenger of Allah"}],"answer":0},{"q":{"bn":"সিফাত মাওসূফের সাথে কয়টি জিনিসে মেলে?","en":"In how many things does the adjective match the noun?"},"options":[{"bn":"দুটি","en":"Two"},{"bn":"চারটি","en":"Four"},{"bn":"তিনটি","en":"Three"}],"answer":1}]}]},{"id":"g-past","icon":"فعل","title":{"bn":"অতীত কালের ক্রিয়া (ফে'লে মাযী)","en":"The Past-Tense Verb (al-Madi)"},"subtitle":{"bn":"{{كَتَبَ}} — সে লিখেছে; শেষাংশ বলে দেয় কে করেছে","en":"{{كَتَبَ}} — he wrote; the ending tells you who did it"},"minutes":18,"goals":[{"bn":"তিন অক্ষরের মূল (রুট) ও {{فَعَلَ}} ছাঁচ বুঝবে","en":"Understand the 3-letter root and the {{فَعَلَ}} pattern"},{"bn":"{{كَتَبَ}}-এর ১৪টি রূপ চিনবে","en":"Recognise all 14 forms of {{كَتَبَ}}"},{"bn":"শেষাংশ দেখেই কর্তা চিনবে: {{ـتُ}}, {{ـنَا}}, {{ـوا}}…","en":"Spot the doer from the ending: {{ـتُ}}, {{ـنَا}}, {{ـوا}}..."}],"blocks":[{"type":"text","bn":"বাংলায় ‘লিখল, লিখলাম, লিখলে’ — একই কাজ, কিন্তু কে করেছে তা অনুযায়ী শেষটা বদলায়। আরবিতেও তাই! অতীত কালের ক্রিয়াকে বলে **ফে'লে মাযী** ({{اَلْفِعْلُ الْمَاضِي}})। মূল রূপটি হলো ‘সে (একজন পুরুষ) করেছে’: {{كَتَبَ}} = সে লিখেছে।","en":"In English 'wrote' stays the same for everyone, but Arabic changes the ending depending on who did it! The past-tense verb is called **al-fi'l al-māḍī** ({{اَلْفِعْلُ الْمَاضِي}}). Its basic form means 'he did': {{كَتَبَ}} = he wrote."},{"type":"tip","kind":"tip","bn":"বেশিরভাগ আরবি শব্দ তিন অক্ষরের **মূল** (রুট) থেকে আসে। {{ك ت ب}} মূলে ‘লেখা’র ভাব: {{كَتَبَ}} (লিখেছে), {{كِتَابٌ}} (বই), {{كَاتِبٌ}} (লেখক)। ব্যাকরণবিদরা ছাঁচ বোঝাতে {{ف ع ل}} ব্যবহার করেন — তাই {{فَعَلَ}} মানে ‘সে করেছে’।","en":"Most Arabic words come from a 3-letter **root**. The root {{ك ت ب}} carries the idea of 'writing': {{كَتَبَ}} (wrote), {{كِتَابٌ}} (book), {{كَاتِبٌ}} (writer). Grammarians use {{ف ع ل}} as the template — so {{فَعَلَ}} means 'he did'."},{"type":"table","title":{"bn":"{{كَتَبَ}}-এর ১৪টি রূপ","en":"The 14 forms of {{كَتَبَ}}"},"head":[{"bn":"কে","en":"Who"},{"bn":"ক্রিয়া","en":"Verb"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["هُوَ","كَتَبَ",{"bn":"কাতাবা","en":"kataba"},{"bn":"সে লিখেছে","en":"he wrote"}],["هُمَا","كَتَبَا",{"bn":"কাতাবা (লম্বা)","en":"katabā"},{"bn":"তারা দুজন লিখেছে","en":"they two wrote"}],["هُمْ","كَتَبُوا",{"bn":"কাতাবূ","en":"katabū"},{"bn":"তারা লিখেছে","en":"they wrote"}],["هِيَ","كَتَبَتْ",{"bn":"কাতাবাত","en":"katabat"},{"bn":"সে (নারী) লিখেছে","en":"she wrote"}],["هُمَا","كَتَبَتَا",{"bn":"কাতাবাতা","en":"katabatā"},{"bn":"তারা দুজন (নারী) লিখেছে","en":"they two (f) wrote"}],["هُنَّ","كَتَبْنَ",{"bn":"কাতাবনা","en":"katabna"},{"bn":"তারা (নারীরা) লিখেছে","en":"they (f) wrote"}],["أَنْتَ","كَتَبْتَ",{"bn":"কাতাবতা","en":"katabta"},{"bn":"তুমি লিখেছ","en":"you wrote"}],["أَنْتُمَا","كَتَبْتُمَا",{"bn":"কাতাবতুমা","en":"katabtumā"},{"bn":"তোমরা দুজন লিখেছ","en":"you two wrote"}],["أَنْتُمْ","كَتَبْتُمْ",{"bn":"কাতাবতুম","en":"katabtum"},{"bn":"তোমরা লিখেছ","en":"you (all) wrote"}],["أَنْتِ","كَتَبْتِ",{"bn":"কাতাবতি","en":"katabti"},{"bn":"তুমি (নারী) লিখেছ","en":"you (f) wrote"}],["أَنْتُمَا","كَتَبْتُمَا",{"bn":"কাতাবতুমা","en":"katabtumā"},{"bn":"তোমরা দুজন (নারী) লিখেছ","en":"you two (f) wrote"}],["أَنْتُنَّ","كَتَبْتُنَّ",{"bn":"কাতাবতুন্না","en":"katabtunna"},{"bn":"তোমরা (নারীরা) লিখেছ","en":"you (f, all) wrote"}],["أَنَا","كَتَبْتُ",{"bn":"কাতাবতু","en":"katabtu"},{"bn":"আমি লিখেছি","en":"I wrote"}],["نَحْنُ","كَتَبْنَا",{"bn":"কাতাবনা (লম্বা)","en":"katabnā"},{"bn":"আমরা লিখেছি","en":"we wrote"}]]},{"type":"table","title":{"bn":"সবচেয়ে কাজের ৬টি শেষাংশ","en":"The 6 most useful endings"},"head":[{"bn":"শেষাংশ","en":"Ending"},{"bn":"কে করেছে","en":"Who did it"},{"bn":"উদাহরণ","en":"Example"}],"rows":[["ـتُ",{"bn":"আমি","en":"I"},"كَتَبْتُ"],["ـنَا",{"bn":"আমরা","en":"we"},"كَتَبْنَا"],["ـتَ",{"bn":"তুমি (পুং)","en":"you (m)"},"كَتَبْتَ"],["ـتُمْ",{"bn":"তোমরা","en":"you all"},"كَتَبْتُمْ"],["ـتْ",{"bn":"সে (নারী)","en":"she"},"كَتَبَتْ"],["ـُوا",{"bn":"তারা","en":"they"},"كَتَبُوا"]]},{"type":"tip","kind":"memory","bn":"মনে রাখো: **‘তু’-তে তুমি নও, আমি!** {{كَتَبْتُ}} (পেশ) = আমি লিখেছি; {{كَتَبْتَ}} (যবর) = তুমি লিখেছ। আর {{ـتْ}} (সাকিন) = সে-নারী। একটা হরকতের পার্থক্যে অর্থ পুরো বদলে যায়!","en":"Remember: **'-tu' is me, not you!** {{كَتَبْتُ}} (damma) = I wrote; {{كَتَبْتَ}} (fatha) = you wrote. And {{ـتْ}} (sukun) = she. One vowel changes the whole meaning!"},{"type":"tip","kind":"warn","bn":"{{كَتَبُوا}}-এর শেষের আলিফ শুধু লেখা হয়, পড়া হয় না: ‘কাতাবূ’। এই আলিফ দেখলেই বুঝবে — ‘তারা’ করেছে।","en":"The final alif in {{كَتَبُوا}} is written but not read: 'katabū'. When you see this alif, think 'they' did it."},{"type":"practice","bn":"{{فَتَحَ}} (খুলেছে) দিয়ে একই নিয়মে পড়ো।","en":"Read the same pattern with {{فَتَحَ}} (opened).","lines":["فَتَحَ فَتَحَا فَتَحُوا","فَتَحَتْ فَتَحَتَا فَتَحْنَ","فَتَحْتَ فَتَحْتُمَا فَتَحْتُمْ","فَتَحْتِ فَتَحْتُنَّ","فَتَحْتُ فَتَحْنَا"]},{"type":"examples","title":{"bn":"কুরআনে অতীত ক্রিয়া","en":"Past verbs in the Quran"},"items":[{"ar":"خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ","tr":{"bn":"খালাকাল ইনসানা মিন আলাক","en":"khalaqal-insāna min 'alaq"},"mean":{"bn":"তিনি মানুষকে সৃষ্টি করেছেন জমাট রক্ত থেকে (৯৬:২)","en":"He created man from a clinging clot (96:2)"},"note":{"bn":"{{هُوَ}} রূপ — কোনো শেষাংশ নেই","en":"{{هُوَ}} form — no ending"},"hl":"خَلَقَ"},{"ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","tr":{"bn":"সিরাত্বাল্লাযীনা আন'আমতা আলাইহিম","en":"ṣirāṭal-ladhīna an'amta 'alayhim"},"mean":{"bn":"যাদের তুমি অনুগ্রহ করেছ, তাদের পথ (১:৭)","en":"The path of those You have blessed (1:7)"},"note":{"bn":"{{ـتَ}} = তুমি","en":"{{ـتَ}} = you"},"hl":"أَنْعَمْتَ"},{"ar":"وَقَالُوا سَمِعْنَا وَأَطَعْنَا","tr":{"bn":"ওয়া কালূ সামি'না ওয়া আত্বা'না","en":"wa qālū sami'nā wa aṭa'nā"},"mean":{"bn":"আর তারা বলল: আমরা শুনলাম ও মানলাম (২:২৮৫)","en":"And they said: we hear and we obey (2:285)"},"note":{"bn":"{{قَالُوا}} = তারা বলল ({{ـُوا}}), {{سَمِعْنَا}} = আমরা শুনলাম ({{ـنَا}})","en":"{{قَالُوا}} = they said ({{ـُوا}}), {{سَمِعْنَا}} = we heard ({{ـنَا}})"},"hl":"سَمِعْنَا"},{"ar":"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي","tr":{"bn":"রব্বি ইন্নী যালামতু নাফসী","en":"rabbi innī ẓalamtu nafsī"},"mean":{"bn":"হে আমার রব, আমি নিজের উপর জুলুম করেছি (২৮:১৬)","en":"My Lord, I have wronged myself (28:16)"},"note":{"bn":"{{ـتُ}} = আমি","en":"{{ـتُ}} = I"},"hl":"ظَلَمْتُ"},{"ar":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ","tr":{"bn":"ইল্লাল্লাযীনা আ-মানূ ওয়া আমিলুস সা-লিহাত","en":"illal-ladhīna āmanū wa 'amiluṣ-ṣāliḥāt"},"mean":{"bn":"তবে তারা নয়, যারা ঈমান এনেছে ও সৎকাজ করেছে (১০৩:৩)","en":"Except those who believed and did righteous deeds (103:3)"},"note":{"bn":"{{ـُوا}} = তারা","en":"{{ـُوا}} = they"},"hl":"آمَنُوا"},{"ar":"كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا","tr":{"bn":"কাযযাবাত সামূদু বিত্বাগওয়া-হা","en":"kadhdhabat thamūdu biṭaghwāhā"},"mean":{"bn":"সামূদ জাতি অবাধ্যতার কারণে অস্বীকার করেছিল (৯১:১১)","en":"Thamud denied out of their transgression (91:11)"},"note":{"bn":"{{ـتْ}} — জাতিকে স্ত্রীলিঙ্গ ধরা হয়েছে","en":"{{ـتْ}} — the tribe is treated as feminine"},"hl":"كَذَّبَتْ"},{"ar":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ","tr":{"bn":"ইন্না আনযালনা-হু ফী লাইলাতিল কদর","en":"innā anzalnāhu fī laylatil-qadr"},"mean":{"bn":"নিশ্চয়ই আমি এটি কদরের রাতে নাযিল করেছি (৯৭:১)","en":"Indeed We sent it down in the Night of Decree (97:1)"},"note":{"bn":"{{أَنْزَلْ + نَا + هُ}} = নাযিল করলাম + আমরা + এটিকে","en":"{{أَنْزَلْ + نَا + هُ}} = sent down + We + it"},"hl":"أَنْزَلْنَاهُ"}]},{"type":"text","title":{"bn":"ক্রিয়াবাচক বাক্য: ক্রিয়া → কর্তা → কর্ম","en":"The verbal sentence: verb → doer → object"},"bn":"ফে'ল দিয়ে শুরু হওয়া বাক্যকে বলে **জুমলা ফে'লিয়্যা**। ক্রম সাধারণত: ক্রিয়া, তারপর **কর্তা** (পেশ), তারপর **কর্ম** (যবর)। যেমন {{وَعَصٰى آدَمُ رَبَّهُ}} = আর আদম তার রবের অবাধ্য হলেন (২০:১২১) — {{آدَمُ}} পেশ (কর্তা), {{رَبَّهُ}} যবর (কর্ম)।","en":"A sentence starting with a verb is a **verbal sentence**. The usual order: verb, then **doer** (damma), then **object** (fatha). E.g. {{وَعَصٰى آدَمُ رَبَّهُ}} = And Adam disobeyed his Lord (20:121) — {{آدَمُ}} has damma (doer), {{رَبَّهُ}} has fatha (object)."},{"type":"tip","kind":"fun","bn":"এক শব্দেই পুরো বাক্য! {{رَزَقْنَاهُمْ}} = ‘আমরা তাদেরকে রিজিক দিয়েছি’ (২:৩) — ক্রিয়া {{رَزَقْ}} + কর্তা {{نَا}} + কর্ম {{هُمْ}}। বাংলায় চার শব্দ, আরবিতে এক!","en":"A whole sentence in one word! {{رَزَقْنَاهُمْ}} = 'We provided them' (2:3) — verb {{رَزَقْ}} + doer {{نَا}} + object {{هُمْ}}. Three words in English, one in Arabic!"},{"type":"quiz","items":[{"q":{"bn":"{{كَتَبْتُ}} অর্থ কী?","en":"What does {{كَتَبْتُ}} mean?"},"ar":"كَتَبْتُ","options":[{"bn":"তুমি লিখেছ","en":"you wrote"},{"bn":"আমি লিখেছি","en":"I wrote"},{"bn":"সে (নারী) লিখেছে","en":"she wrote"},{"bn":"তারা লিখেছে","en":"they wrote"}],"answer":1},{"q":{"bn":"‘আমরা খুলেছি’ কোনটি?","en":"Which means 'we opened'?"},"options":["فَتَحُوا","فَتَحْتُمْ","فَتَحْنَا","فَتَحَتْ"],"answer":2},{"q":{"bn":"{{سَمِعْنَا}}-তে কে শুনেছে?","en":"In {{سَمِعْنَا}}, who heard?"},"ar":"سَمِعْنَا","options":[{"bn":"আমি","en":"I"},{"bn":"তারা","en":"they"},{"bn":"আমরা","en":"we"}],"answer":2},{"q":{"bn":"{{كَذَّبَتْ}}-এর শেষের {{ـتْ}} কী বোঝায়?","en":"What does the final {{ـتْ}} in {{كَذَّبَتْ}} show?"},"options":[{"bn":"সে (নারী / স্ত্রীলিঙ্গ কর্তা)","en":"she (a feminine doer)"},{"bn":"তুমি","en":"you"},{"bn":"আমি","en":"I"}],"answer":0},{"q":{"bn":"{{آمَنُوا}} অর্থ কী?","en":"What does {{آمَنُوا}} mean?"},"ar":"آمَنُوا","options":[{"bn":"সে ঈমান এনেছে","en":"he believed"},{"bn":"তারা ঈমান এনেছে","en":"they believed"},{"bn":"ঈমান আনো","en":"believe!"}],"answer":1},{"q":{"bn":"{{كَتَبَ}}, {{كِتَابٌ}}, {{كَاتِبٌ}} — এদের মূল (রুট) কী?","en":"What root do {{كَتَبَ}}, {{كِتَابٌ}}, {{كَاتِبٌ}} share?"},"options":["ف ع ل","ك ب ر","ك ت ب"],"answer":2},{"q":{"bn":"{{وَعَصٰى آدَمُ رَبَّهُ}} — কর্তা কে?","en":"In {{وَعَصٰى آدَمُ رَبَّهُ}}, who is the doer?"},"options":["آدَمُ","عَصٰى","رَبَّهُ"],"answer":0,"explain":{"bn":"কর্তা পেশ পায়: {{آدَمُ}}; কর্ম যবর পায়: {{رَبَّهُ}}।","en":"The doer takes damma: {{آدَمُ}}; the object takes fatha: {{رَبَّهُ}}."}}]}]},{"id":"g-present","icon":"يَـ","title":{"bn":"বর্তমান-ভবিষ্যৎ, আদেশ ও নিষেধ","en":"Present/Future, Command and Prohibition"},"subtitle":{"bn":"{{يَفْعَلُ}} — সামনে চার অক্ষর {{أ ن ي ت}} বসিয়ে ক্রিয়া","en":"{{يَفْعَلُ}} — verbs made with four front letters {{أ ن ي ت}}"},"minutes":20,"goals":[{"bn":"ফে'লে মুযারি' (বর্তমান/ভবিষ্যৎ) চিনবে","en":"Recognise the present/future verb (al-mudari')"},{"bn":"{{سَـ}} ও {{سَوْفَ}} দিয়ে ভবিষ্যৎ বুঝবে","en":"Understand the future with {{سَـ}} and {{سَوْفَ}}"},{"bn":"আদেশ ({{اُكْتُبْ}}) ও নিষেধ ({{لَا تَكْتُبْ}}) বানাতে ও চিনতে পারবে","en":"Form and recognise commands ({{اُكْتُبْ}}) and prohibitions ({{لَا تَكْتُبْ}})"}],"blocks":[{"type":"text","bn":"অতীত ক্রিয়ায় পরিবর্তন হতো **শেষে**। বর্তমান ক্রিয়ায় পরিবর্তন হয় মূলত **শুরুতে**! এই ক্রিয়াকে বলে **ফে'লে মুযারি'** ({{اَلْفِعْلُ الْمُضَارِعُ}}) — এটি ‘করে / করছে’ আবার ‘করবে’ দুটোই বোঝাতে পারে। মূল রূপ: {{يَكْتُبُ}} = সে লেখে / লিখছে।","en":"In the past tense, the change came at the **end**. In the present tense, the change mainly comes at the **front**! This verb is called **al-fi'l al-muḍāri'** ({{اَلْفِعْلُ الْمُضَارِعُ}}) — it can mean 'does / is doing' and also 'will do'. Basic form: {{يَكْتُبُ}} = he writes / is writing."},{"type":"table","title":{"bn":"চারটি সামনের অক্ষর","en":"The four front letters"},"head":[{"bn":"অক্ষর","en":"Prefix"},{"bn":"কে","en":"Who"},{"bn":"উদাহরণ","en":"Example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["أَ",{"bn":"আমি","en":"I"},"أَكْتُبُ",{"bn":"আমি লিখি","en":"I write"}],["نَ",{"bn":"আমরা","en":"we"},"نَكْتُبُ",{"bn":"আমরা লিখি","en":"we write"}],["يَ",{"bn":"সে (পুং) / তারা","en":"he / they"},"يَكْتُبُ",{"bn":"সে লেখে","en":"he writes"}],["تَ",{"bn":"তুমি / সে (নারী)","en":"you / she"},"تَكْتُبُ",{"bn":"তুমি লেখো / সে (নারী) লেখে","en":"you write / she writes"}]]},{"type":"tip","kind":"memory","bn":"চারটি অক্ষর মিলিয়ে একটা শব্দ বানাও: **{{أَنَيْتُ}}** (আনাইতু) — অ = আমি, ন = আমরা (নাহনু), ই = সে (হুয়া), ত = তুমি। মুযারি' চেনার চাবি এই চার অক্ষর!","en":"Put the four letters together into one word: **{{أَنَيْتُ}}** (anaytu) — a = I (anā), n = we (naḥnu), y = he, t = you. These four letters are the key to spotting a present verb!"},{"type":"table","title":{"bn":"{{يَكْتُبُ}}-এর ১৪টি রূপ","en":"The 14 forms of {{يَكْتُبُ}}"},"head":[{"bn":"কে","en":"Who"},{"bn":"ক্রিয়া","en":"Verb"},{"bn":"উচ্চারণ","en":"Say"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["هُوَ","يَكْتُبُ",{"bn":"ইয়াকতুবু","en":"yaktubu"},{"bn":"সে লেখে","en":"he writes"}],["هُمَا","يَكْتُبَانِ",{"bn":"ইয়াকতুবানি","en":"yaktubāni"},{"bn":"তারা দুজন লেখে","en":"they two write"}],["هُمْ","يَكْتُبُونَ",{"bn":"ইয়াকতুবূনা","en":"yaktubūna"},{"bn":"তারা লেখে","en":"they write"}],["هِيَ","تَكْتُبُ",{"bn":"তাকতুবু","en":"taktubu"},{"bn":"সে (নারী) লেখে","en":"she writes"}],["هُمَا","تَكْتُبَانِ",{"bn":"তাকতুবানি","en":"taktubāni"},{"bn":"তারা দুজন (নারী) লেখে","en":"they two (f) write"}],["هُنَّ","يَكْتُبْنَ",{"bn":"ইয়াকতুবনা","en":"yaktubna"},{"bn":"তারা (নারীরা) লেখে","en":"they (f) write"}],["أَنْتَ","تَكْتُبُ",{"bn":"তাকতুবু","en":"taktubu"},{"bn":"তুমি লেখো","en":"you write"}],["أَنْتُمَا","تَكْتُبَانِ",{"bn":"তাকতুবানি","en":"taktubāni"},{"bn":"তোমরা দুজন লেখো","en":"you two write"}],["أَنْتُمْ","تَكْتُبُونَ",{"bn":"তাকতুবূনা","en":"taktubūna"},{"bn":"তোমরা লেখো","en":"you (all) write"}],["أَنْتِ","تَكْتُبِينَ",{"bn":"তাকতুবীনা","en":"taktubīna"},{"bn":"তুমি (নারী) লেখো","en":"you (f) write"}],["أَنْتُمَا","تَكْتُبَانِ",{"bn":"তাকতুবানি","en":"taktubāni"},{"bn":"তোমরা দুজন (নারী) লেখো","en":"you two (f) write"}],["أَنْتُنَّ","تَكْتُبْنَ",{"bn":"তাকতুবনা","en":"taktubna"},{"bn":"তোমরা (নারীরা) লেখো","en":"you (f, all) write"}],["أَنَا","أَكْتُبُ",{"bn":"আকতুবু","en":"aktubu"},{"bn":"আমি লিখি","en":"I write"}],["نَحْنُ","نَكْتُبُ",{"bn":"নাকতুবু","en":"naktubu"},{"bn":"আমরা লিখি","en":"we write"}]]},{"type":"tip","kind":"tip","bn":"শেষে {{ـُونَ}} দেখলে = ‘তারা’ বা ‘তোমরা’ (বহু)। সামনে {{يَـ}} থাকলে ‘তারা’ ({{يَعْلَمُونَ}}), সামনে {{تَـ}} থাকলে ‘তোমরা’ ({{تَعْلَمُونَ}})। কুরআনে এই দুটো রূপ সবচেয়ে বেশি আসে!","en":"An ending of {{ـُونَ}} = 'they' or 'you all'. With {{يَـ}} in front it's 'they' ({{يَعْلَمُونَ}}); with {{تَـ}} it's 'you all' ({{تَعْلَمُونَ}}). These two forms are the most common in the Quran!"},{"type":"tip","kind":"warn","bn":"মাঝের অক্ষরের হরকত সব ক্রিয়ায় এক নয়: {{يَكْتُبُ}} (পেশ), {{يَفْتَحُ}} (যবর), {{يَضْرِبُ}} (যের)। এটা অভিধান দেখে বা শুনে শিখতে হয়।","en":"The middle vowel isn't the same for every verb: {{يَكْتُبُ}} (u), {{يَفْتَحُ}} (a), {{يَضْرِبُ}} (i). You learn it from a dictionary or by hearing it."},{"type":"examples","title":{"bn":"কুরআনে মুযারি'","en":"Present verbs in the Quran"},"items":[{"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","tr":{"bn":"ইয়্যাকা না'বুদু ওয়া ইয়্যাকা নাসতা'ঈন","en":"iyyāka na'budu wa iyyāka nasta'īn"},"mean":{"bn":"আমরা শুধু তোমারই ইবাদত করি এবং শুধু তোমারই কাছে সাহায্য চাই (১:৫)","en":"You alone we worship and You alone we ask for help (1:5)"},"note":{"bn":"{{نَـ}} = আমরা","en":"{{نَـ}} = we"},"hl":"نَعْبُدُ"},{"ar":"لَا أَعْبُدُ مَا تَعْبُدُونَ","tr":{"bn":"লা আ'বুদু মা তা'বুদূন","en":"lā a'budu mā ta'budūn"},"mean":{"bn":"তোমরা যার ইবাদত করো, আমি তার ইবাদত করি না (১০৯:২)","en":"I do not worship what you worship (109:2)"},"note":{"bn":"{{أَعْبُدُ}} = আমি ({{أَ}}), {{تَعْبُدُونَ}} = তোমরা ({{تَـ...ـُونَ}})","en":"{{أَعْبُدُ}} = I ({{أَ}}), {{تَعْبُدُونَ}} = you all ({{تَـ...ـُونَ}})"},"hl":"تَعْبُدُونَ"},{"ar":"الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ","tr":{"bn":"আল্লাযীনা ইউ'মিনূনা বিল গাইবি ওয়া ইউকীমূনাস সালাহ","en":"alladhīna yu'minūna bil-ghaybi wa yuqīmūnaṣ-ṣalāh"},"mean":{"bn":"যারা অদৃশ্যে বিশ্বাস করে এবং সালাত কায়েম করে (২:৩)","en":"Who believe in the unseen and establish prayer (2:3)"},"note":{"bn":"{{يُـ...ـُونَ}} = তারা","en":"{{يُـ...ـُونَ}} = they"},"hl":"يُؤْمِنُونَ"},{"ar":"فَأَيْنَ تَذْهَبُونَ","tr":{"bn":"ফাআইনা তাযহাবূন","en":"fa-ayna tadh-habūn"},"mean":{"bn":"তাহলে তোমরা কোথায় যাচ্ছ? (৮১:২৬)","en":"So where are you going? (81:26)"},"hl":"تَذْهَبُونَ"},{"ar":"فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ","tr":{"bn":"ফাবিআইয়ি আ-লা-ই রব্বিকুমা তুকাযযিবান","en":"fabi-ayyi ālā'i rabbikumā tukadhdhibān"},"mean":{"bn":"অতএব তোমরা দুজন তোমাদের রবের কোন কোন নিয়ামত অস্বীকার করবে? (৫৫:১৩)","en":"So which of the favours of your Lord will you two deny? (55:13)"},"note":{"bn":"দ্বিবচন! {{تُـ...ـَانِ}} = তোমরা দুজন (মানুষ ও জিন)","en":"A dual! {{تُـ...ـَانِ}} = you two (mankind and jinn)"},"hl":"تُكَذِّبَانِ"}]},{"type":"table","title":{"bn":"ভবিষ্যৎ: {{سَـ}} ও {{سَوْفَ}}","en":"The future: {{سَـ}} and {{سَوْفَ}}"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"},{"bn":"কুরআনের উদাহরণ","en":"Quranic example"}],"rows":[["سَـ",{"bn":"শীঘ্রই (কাছের ভবিষ্যৎ)","en":"soon (near future)"},"سَيَقُولُ السُّفَهَاءُ مِنَ النَّاسِ (٢:١٤٢)"],["سَوْفَ",{"bn":"অচিরেই / পরে (একটু দূরের ভবিষ্যৎ)","en":"will (a bit further future)"},"كَلَّا سَوْفَ تَعْلَمُونَ (١٠٢:٣)"]]},{"type":"tip","kind":"memory","bn":"{{سَـ}} ছোট, তাই ভবিষ্যৎও কাছে; {{سَوْفَ}} লম্বা, তাই ভবিষ্যৎও একটু দূরে! দুটোই সবসময় মুযারি'-র আগে বসে: {{سَيَقُولُ}} = সে বলবে।","en":"{{سَـ}} is short, so the future is near; {{سَوْفَ}} is long, so the future is a bit further! Both always come before a present verb: {{سَيَقُولُ}} = he will say."},{"type":"steps","title":{"bn":"আদেশ (আমর) বানানোর তিন ধাপ","en":"Three steps to make a command (amr)"},"items":[{"title":{"bn":"‘তুমি’ রূপ নাও","en":"Take the 'you' form"},"ar":"تَكْتُبُ","tr":{"bn":"তাকতুবু","en":"taktubu"},"mean":{"bn":"তুমি লেখো","en":"you write"}},{"title":{"bn":"সামনের {{تَـ}} ফেলে দাও, শেষে জযম দাও","en":"Drop the {{تَـ}}, put sukun at the end"},"ar":"كْتُبْ","desc":{"bn":"শুরুতে সাকিন — এভাবে পড়া যায় না!","en":"It starts with a sukun — impossible to pronounce!"}},{"title":{"bn":"সামনে একটি হামযা যোগ করো","en":"Add a hamza in front"},"ar":"اُكْتُبْ","tr":{"bn":"উকতুব","en":"uktub"},"mean":{"bn":"লেখো!","en":"Write!"},"desc":{"bn":"মাঝের অক্ষরে পেশ হলে হামযায় পেশ ({{اُكْتُبْ}}), নইলে যের ({{اِفْتَحْ}} খোলো!, {{اِضْرِبْ}} মারো!)","en":"If the middle letter has damma, the hamza gets damma ({{اُكْتُبْ}}); otherwise kasra ({{اِفْتَحْ}} open!, {{اِضْرِبْ}} strike!)"}}]},{"type":"table","title":{"bn":"কাকে আদেশ দিচ্ছ?","en":"Who are you commanding?"},"head":[{"bn":"কাকে","en":"To whom"},{"bn":"আদেশ","en":"Command"},{"bn":"অর্থ","en":"Meaning"}],"rows":[[{"bn":"একজন পুরুষ","en":"one man"},"اُكْتُبْ",{"bn":"লেখো","en":"write (m)"}],[{"bn":"একজন নারী","en":"one woman"},"اُكْتُبِي",{"bn":"লেখো (নারী)","en":"write (f)"}],[{"bn":"অনেকজন","en":"a group"},"اُكْتُبُوا",{"bn":"তোমরা লেখো","en":"write (pl)"}]]},{"type":"examples","title":{"bn":"কুরআনের আদেশ","en":"Commands in the Quran"},"items":[{"ar":"اِقْرَأْ بِاسْمِ رَبِّكَ","tr":{"bn":"ইকরা' বিসমি রব্বিক","en":"iqra' bismi rabbik"},"mean":{"bn":"পড়ো তোমার রবের নামে (৯৬:১)","en":"Read in the name of your Lord (96:1)"},"note":{"bn":"{{يَقْرَأُ}} → {{اِقْرَأْ}} (মাঝে যবর, তাই হামযায় যের)","en":"{{يَقْرَأُ}} → {{اِقْرَأْ}} (middle fatha, so hamza takes kasra)"},"hl":"اِقْرَأْ"},{"ar":"فَصَلِّ لِرَبِّكَ وَانْحَرْ","tr":{"bn":"ফাসাল্লি লিরব্বিকা ওয়ানহার","en":"faṣalli lirabbika wanḥar"},"mean":{"bn":"সুতরাং তোমার রবের জন্য নামাজ পড়ো ও কুরবানি করো (১০৮:২)","en":"So pray to your Lord and sacrifice (108:2)"},"hl":"وَانْحَرْ"},{"ar":"يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ","tr":{"bn":"ইয়া আইয়ুহান না-সু'বুদূ রব্বাকুম","en":"yā ayyuhan-nāsu'budū rabbakum"},"mean":{"bn":"হে মানুষ, তোমাদের রবের ইবাদত করো (২:২১)","en":"O mankind, worship your Lord (2:21)"},"note":{"bn":"বহুবচনের আদেশ: {{ـُوا}}","en":"Plural command: {{ـُوا}}"},"hl":"اعْبُدُوا"},{"ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","tr":{"bn":"কুল হুওয়াল্লাহু আহাদ","en":"qul huwallāhu aḥad"},"mean":{"bn":"বলো, তিনিই আল্লাহ, এক (১১২:১)","en":"Say: He is Allah, the One (112:1)"},"note":{"bn":"{{يَقُولُ}} থেকে ছোট্ট আদেশ {{قُلْ}} — এখানে হামযা লাগেনি, কারণ শুরুতে সাকিন নেই","en":"{{قُلْ}} comes from {{يَقُولُ}} — no hamza needed, as it doesn't start with a sukun"},"hl":"قُلْ"}]},{"type":"text","title":{"bn":"নিষেধ (নাহী): {{لَا}} + জযম","en":"Prohibition (nahy): {{لَا}} + sukun"},"bn":"‘করো না!’ বলতে ‘তুমি’ রূপের আগে {{لَا}} বসাও আর শেষে জযম দাও: {{تَكْتُبُ}} → {{لَا تَكْتُبْ}} (লিখো না!)। বহুবচনে: {{لَا تَكْتُبُوا}} (তোমরা লিখো না!)।","en":"To say 'don't!', put {{لَا}} before the 'you' form and give the end a sukun: {{تَكْتُبُ}} → {{لَا تَكْتُبْ}} (don't write!). Plural: {{لَا تَكْتُبُوا}} (don't write, all of you!)."},{"type":"examples","items":[{"ar":"لَا تَحْزَنْ إِنَّ اللّٰهَ مَعَنَا","tr":{"bn":"লা তাহযান ইন্নাল্লাহা মা'আনা","en":"lā taḥzan innallāha ma'anā"},"mean":{"bn":"দুঃখ করো না, নিশ্চয়ই আল্লাহ আমাদের সাথে আছেন (৯:৪০)","en":"Do not grieve; indeed Allah is with us (9:40)"},"hl":"لَا تَحْزَنْ"},{"ar":"يَا بُنَيَّ لَا تُشْرِكْ بِاللّٰهِ","tr":{"bn":"ইয়া বুনাইয়া লা তুশরিক বিল্লাহ","en":"yā bunayya lā tushrik billāh"},"mean":{"bn":"হে আমার ছোট্ট ছেলে, আল্লাহর সাথে শিরক করো না (৩১:১৩)","en":"O my son, do not associate anything with Allah (31:13)"},"hl":"لَا تُشْرِكْ"},{"ar":"وَلَا تَقْرَبُوا الزِّنَا","tr":{"bn":"ওয়া লা তাকরাবুয যিনা","en":"wa lā taqrabuz-zinā"},"mean":{"bn":"আর তোমরা ব্যভিচারের কাছেও যেয়ো না (১৭:৩২)","en":"And do not go near adultery (17:32)"},"note":{"bn":"বহুবচনের নিষেধ: {{ـُوا}} (শেষের {{ن}} ঝরে গেছে)","en":"Plural prohibition: {{ـُوا}} (the final {{ن}} has dropped)"},"hl":"لَا تَقْرَبُوا"},{"ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا","tr":{"bn":"রব্বানা লা তুআ-খিযনা ইন নাসীনা আও আখত্বা'না","en":"rabbanā lā tu'ākhidhnā in nasīnā aw akhṭa'nā"},"mean":{"bn":"হে আমাদের রব, আমরা ভুলে গেলে বা ভুল করলে আমাদের পাকড়াও করো না (২:২৮৬)","en":"Our Lord, do not take us to task if we forget or err (2:286)"},"note":{"bn":"আল্লাহর কাছে হলে এটি নিষেধ নয়, বিনীত দোয়া","en":"Addressed to Allah, it's not a prohibition but a humble du'a"},"hl":"لَا تُؤَاخِذْنَا"}]},{"type":"compare","title":{"bn":"একটি হরকতের পার্থক্য","en":"One vowel makes the difference"},"items":[{"ar":"لَا تَكْتُبُ","label":{"bn":"না-বাচক বাক্য","en":"Negative statement"},"desc":{"bn":"শেষে পেশ: ‘তুমি লেখো না।’ (খবর দেওয়া)","en":"Ends in damma: 'You don't write.' (a fact)"}},{"ar":"لَا تَكْتُبْ","label":{"bn":"নিষেধ","en":"Prohibition"},"desc":{"bn":"শেষে জযম: ‘লিখো না!’ (বারণ করা)","en":"Ends in sukun: 'Don't write!' (an order)"}}]},{"type":"quiz","items":[{"q":{"bn":"{{نَكْتُبُ}} অর্থ কী?","en":"What does {{نَكْتُبُ}} mean?"},"ar":"نَكْتُبُ","options":[{"bn":"আমরা লিখি","en":"we write"},{"bn":"আমরা লিখেছি","en":"we wrote"},{"bn":"আমি লিখি","en":"I write"},{"bn":"লেখো!","en":"write!"}],"answer":0},{"q":{"bn":"‘তারা জানে’ কোনটি?","en":"Which means 'they know'?"},"options":["أَعْلَمُ","تَعْلَمُونَ","نَعْلَمُ","يَعْلَمُونَ"],"answer":3},{"q":{"bn":"{{سَوْفَ تَعْلَمُونَ}} — কোন কাল?","en":"What time is {{سَوْفَ تَعْلَمُونَ}}?"},"options":[{"bn":"বর্তমান","en":"Present"},{"bn":"ভবিষ্যৎ","en":"Future"},{"bn":"অতীত","en":"Past"}],"answer":1},{"q":{"bn":"{{تَفْتَحُ}} থেকে আদেশ কী হবে?","en":"What is the command from {{تَفْتَحُ}}?"},"options":["اُفْتُحْ","اِفْتَحْ","فَتَحَ","لَا تَفْتَحْ"],"answer":1,"explain":{"bn":"মাঝে যবর, তাই হামযায় যের: {{اِفْتَحْ}}।","en":"Middle vowel is fatha, so the hamza takes kasra: {{اِفْتَحْ}}."}},{"q":{"bn":"{{لَا تَحْزَنْ}} অর্থ কী?","en":"What does {{لَا تَحْزَنْ}} mean?"},"ar":"لَا تَحْزَنْ","options":[{"bn":"আমি দুঃখ করিনি","en":"I didn't grieve"},{"bn":"সে দুঃখ করে না","en":"he doesn't grieve"},{"bn":"দুঃখ করো না!","en":"Do not grieve!"}],"answer":2},{"q":{"bn":"{{اِقْرَأْ}} কী ধরনের ক্রিয়া?","en":"What kind of verb is {{اِقْرَأْ}}?"},"options":[{"bn":"আদেশ","en":"Command"},{"bn":"নিষেধ","en":"Prohibition"},{"bn":"অতীত","en":"Past"}],"answer":0},{"q":{"bn":"মুযারি'-র চার সামনের অক্ষর কোনগুলো?","en":"What are the four prefixes of the present verb?"},"options":["ب ت ث ج","أ ن ي ت","ل م ن و"],"answer":1},{"q":{"bn":"{{تُكَذِّبَانِ}}-এ কতজনকে বলা হচ্ছে?","en":"How many people does {{تُكَذِّبَانِ}} address?"},"ar":"تُكَذِّبَانِ","options":[{"bn":"অনেকজন","en":"Many"},{"bn":"একজন","en":"One"},{"bn":"দুজন","en":"Two"}],"answer":2}]}]},{"id":"g-negation-questions","icon":"؟","title":{"bn":"না-বাচক, প্রশ্ন ও একটি আয়াত বিশ্লেষণ","en":"Negation, Questions and Decoding an Ayah"},"subtitle":{"bn":"{{لَا}}, {{لَمْ}}, {{لَنْ}}, {{لَيْسَ}} আর {{هَلْ}}, {{مَنْ}}, {{كَيْفَ}} — তারপর পুরো আয়াত নিজে ভাঙো!","en":"{{لَا}}, {{لَمْ}}, {{لَنْ}}, {{لَيْسَ}} and {{هَلْ}}, {{مَنْ}}, {{كَيْفَ}} — then break down a whole ayah yourself!"},"minutes":22,"goals":[{"bn":"পাঁচটি না-বাচক শব্দের পার্থক্য বুঝবে","en":"Tell apart the five negation words"},{"bn":"কুরআনের প্রশ্নবোধক শব্দগুলো চিনবে","en":"Recognise the Quran's question words"},{"bn":"শেখা সব ব্যাকরণ দিয়ে একটি আয়াত শব্দে শব্দে বিশ্লেষণ করবে","en":"Use all your grammar to decode an ayah word by word"}],"blocks":[{"type":"text","bn":"এটাই এই ইউনিটের শেষ পাঠ — অভিনন্দন! আজ শিখব কীভাবে ‘না’ বলতে হয় আর কীভাবে প্রশ্ন করতে হয়। বাংলায় ‘না’ একটাই, কিন্তু আরবিতে কালের ওপর নির্ভর করে আলাদা ‘না’ আছে।","en":"This is the last lesson of the unit — congratulations! Today we learn how to say 'not' and how to ask questions. English mostly uses 'not', but Arabic picks a different 'not' depending on the time."},{"type":"table","title":{"bn":"পাঁচটি ‘না’","en":"The five 'nots'"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"কিসের আগে","en":"Used with"},{"bn":"অর্থ","en":"Meaning"},{"bn":"কুরআনের উদাহরণ","en":"Quranic example"}],"rows":[["لَا",{"bn":"মুযারি' (বর্তমান)","en":"present verb"},{"bn":"করে না","en":"does not"},"لَا أَعْبُدُ مَا تَعْبُدُونَ"],["مَا",{"bn":"মাযী (অতীত)","en":"past verb"},{"bn":"করেনি","en":"did not"},"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰى"],["لَمْ",{"bn":"মুযারি' + জযম","en":"present verb + sukun"},{"bn":"করেনি (অতীত অর্থ!)","en":"did not (past meaning!)"},"لَمْ يَلِدْ وَلَمْ يُولَدْ"],["لَنْ",{"bn":"মুযারি' + যবর","en":"present verb + fatha"},{"bn":"কখনো করবে না","en":"will never"},"لَنْ تَنَالُوا الْبِرَّ"],["لَيْسَ",{"bn":"নামবাচক বাক্য","en":"nominal sentence"},{"bn":"নয় / নেই","en":"is not"},"لَيْسَ كَمِثْلِهِ شَيْءٌ"]]},{"type":"examples","title":{"bn":"আয়াতগুলোর অর্থ","en":"What those ayahs mean"},"items":[{"ar":"لَا أَعْبُدُ مَا تَعْبُدُونَ","tr":{"bn":"লা আ'বুদু মা তা'বুদূন","en":"lā a'budu mā ta'budūn"},"mean":{"bn":"তোমরা যার ইবাদত করো, আমি তার ইবাদত করি না (১০৯:২)","en":"I do not worship what you worship (109:2)"},"hl":"لَا"},{"ar":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٰى","tr":{"bn":"মা ওয়াদ্দা'আকা রব্বুকা ওয়া মা কলা","en":"mā wadda'aka rabbuka wa mā qalā"},"mean":{"bn":"তোমার রব তোমাকে ছেড়ে যাননি, অসন্তুষ্টও হননি (৯৩:৩)","en":"Your Lord has not forsaken you, nor is He displeased (93:3)"},"hl":"مَا وَدَّعَكَ"},{"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","tr":{"bn":"লাম ইয়ালিদ ওয়া লাম ইউলাদ","en":"lam yalid wa lam yūlad"},"mean":{"bn":"তিনি কাউকে জন্ম দেননি, কেউ তাঁকে জন্ম দেয়নি (১১২:৩)","en":"He neither begot nor was begotten (112:3)"},"note":{"bn":"{{يَلِدُ}} → {{لَمْ يَلِدْ}}: শেষে জযম","en":"{{يَلِدُ}} → {{لَمْ يَلِدْ}}: sukun at the end"},"hl":"لَمْ يَلِدْ"},{"ar":"عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ","tr":{"bn":"আল্লামাল ইনসানা মা লাম ইয়া'লাম","en":"'allamal-insāna mā lam ya'lam"},"mean":{"bn":"তিনি মানুষকে শিখিয়েছেন যা সে জানত না (৯৬:৫)","en":"He taught man what he did not know (96:5)"},"note":{"bn":"এখানে {{مَا}} = ‘যা’, আর {{لَمْ يَعْلَمْ}} = জানত না","en":"Here {{مَا}} = 'what', and {{لَمْ يَعْلَمْ}} = did not know"},"hl":"لَمْ يَعْلَمْ"},{"ar":"لَنْ تَنَالُوا الْبِرَّ حَتّٰى تُنْفِقُوا مِمَّا تُحِبُّونَ","tr":{"bn":"লান তানালুল বিররা হাত্তা তুনফিকূ মিম্মা তুহিব্বূন","en":"lan tanālul-birra ḥattā tunfiqū mimmā tuḥibbūn"},"mean":{"bn":"তোমরা যা ভালোবাসো তা থেকে ব্যয় না করা পর্যন্ত কখনো পুণ্য লাভ করবে না (৩:৯২)","en":"You will never attain righteousness until you spend from what you love (3:92)"},"hl":"لَنْ تَنَالُوا"},{"ar":"لَيْسَ كَمِثْلِهِ شَيْءٌ","tr":{"bn":"লাইসা কামিসলিহী শাইউন","en":"laysa kamithlihī shay'un"},"mean":{"bn":"তাঁর মতো কোনো কিছুই নেই (৪২:১১)","en":"There is nothing like Him (42:11)"},"hl":"لَيْسَ"},{"ar":"لَسْتَ عَلَيْهِمْ بِمُصَيْطِرٍ","tr":{"bn":"লাসতা আলাইহিম বিমুসাইত্বির","en":"lasta 'alayhim bimuṣayṭir"},"mean":{"bn":"তুমি তাদের উপর জবরদস্তিকারী নও (৮৮:২২)","en":"You are not a controller over them (88:22)"},"note":{"bn":"{{لَيْسَ}} অতীত ক্রিয়ার মতো রূপ বদলায়: {{لَسْتَ}} = তুমি নও, {{لَسْتُ}} = আমি নই","en":"{{لَيْسَ}} changes like a past verb: {{لَسْتَ}} = you are not, {{لَسْتُ}} = I am not"},"hl":"لَسْتَ"}]},{"type":"tip","kind":"memory","bn":"**লাম-এ ‘ম’ — মাযী (অতীত); লান-এ ‘ন’ — না কখনো (ভবিষ্যৎ)!** দুটোই মুযারি'-র আগে বসে, কিন্তু {{لَمْ}} অর্থকে পেছনে (অতীতে) টানে, আর {{لَنْ}} সামনে (ভবিষ্যতে) ঠেলে।","en":"**'Lam' looks back, 'lan' looks ahead!** Both sit before a present verb, but {{لَمْ}} pulls the meaning into the past, while {{لَنْ}} pushes it into the future (never)."},{"type":"tip","kind":"tip","bn":"আরেকটি বিশেষ {{لَا}}: ইসমের আগে বসে ‘কোনো… নেই’ বোঝায়, আর ইসমের শেষে এক যবর দেয়: {{لَا رَيْبَ فِيهِ}} (এতে কোনো সন্দেহ নেই, ২:২), {{لَا إِلٰهَ إِلَّا اللّٰهُ}} (আল্লাহ ছাড়া কোনো ইলাহ নেই)।","en":"One more special {{لَا}}: before a noun it means 'there is no... at all', and gives the noun a single fatha: {{لَا رَيْبَ فِيهِ}} (no doubt in it, 2:2), {{لَا إِلٰهَ إِلَّا اللّٰهُ}} (there is no god but Allah)."},{"type":"table","title":{"bn":"প্রশ্নবোধক শব্দ","en":"Question words"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"অর্থ","en":"Meaning"},{"bn":"কুরআনের উদাহরণ","en":"Quranic example"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["هَلْ",{"bn":"কি? (হ্যাঁ/না প্রশ্ন)","en":"is/does...? (yes/no)"},"هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ",{"bn":"তোমার কাছে কি আচ্ছন্নকারীর খবর এসেছে? (৮৮:১)","en":"Has the news of the Overwhelming reached you? (88:1)"}],["أَ",{"bn":"কি? (হ্যাঁ/না প্রশ্ন)","en":"is/does...? (yes/no)"},"أَلَيْسَ اللّٰهُ بِأَحْكَمِ الْحَاكِمِينَ",{"bn":"আল্লাহ কি শ্রেষ্ঠ বিচারক নন? (৯৫:৮)","en":"Is Allah not the most just of judges? (95:8)"}],["مَا",{"bn":"কী?","en":"what?"},"وَمَا تِلْكَ بِيَمِينِكَ يَا مُوسٰى",{"bn":"হে মূসা, তোমার ডান হাতে ওটা কী? (২০:১৭)","en":"What is that in your right hand, O Musa? (20:17)"}],["مَنْ",{"bn":"কে?","en":"who?"},"مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ",{"bn":"কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? (২:২৫৫)","en":"Who could intercede with Him except by His permission? (2:255)"}],["أَيْنَ",{"bn":"কোথায়?","en":"where?"},"فَأَيْنَ تَذْهَبُونَ",{"bn":"তাহলে তোমরা কোথায় যাচ্ছ? (৮১:২৬)","en":"So where are you going? (81:26)"}],["كَيْفَ",{"bn":"কীভাবে? কেমন?","en":"how?"},"كَيْفَ تَكْفُرُونَ بِاللّٰهِ",{"bn":"তোমরা কীভাবে আল্লাহকে অস্বীকার করো? (২:২৮)","en":"How can you disbelieve in Allah? (2:28)"}],["مَتٰى",{"bn":"কখন?","en":"when?"},"مَتٰى نَصْرُ اللّٰهِ",{"bn":"আল্লাহর সাহায্য কখন আসবে? (২:২১৪)","en":"When is the help of Allah? (2:214)"}],["لِمَ / لِمَاذَا",{"bn":"কেন?","en":"why?"},"لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ",{"bn":"তোমরা যা করো না, তা কেন বলো? (৬১:২)","en":"Why do you say what you do not do? (61:2)"}],["كَمْ",{"bn":"কত?","en":"how many / how long?"},"كَمْ لَبِثْتَ",{"bn":"তুমি কতকাল (এভাবে) ছিলে? (২:২৫৯)","en":"How long have you remained? (2:259)"}]]},{"type":"tip","kind":"warn","bn":"{{مَا}}-র তিনটি কাজ — প্রসঙ্গ দেখে বুঝতে হয়: (১) প্রশ্ন ‘কী?’ — {{مَا الْقَارِعَةُ}} (১০১:২); (২) না-বাচক ‘না’ — {{مَا وَدَّعَكَ}}; (৩) ‘যা’ — {{مَا لَمْ يَعْلَمْ}}। আর ‘কেন’-এর জন্য কুরআনে ছোট রূপ {{لِمَ}} আসে; {{لِمَاذَا}} পরবর্তী আরবিতে বেশি প্রচলিত।","en":"{{مَا}} has three jobs — context decides: (1) question 'what?' — {{مَا الْقَارِعَةُ}} (101:2); (2) negation 'not' — {{مَا وَدَّعَكَ}}; (3) 'what/that which' — {{مَا لَمْ يَعْلَمْ}}. And for 'why', the Quran uses the short {{لِمَ}}; {{لِمَاذَا}} is more common in later Arabic."},{"type":"tip","kind":"fun","bn":"{{أَلَمْ}} = {{أَ}} (কি?) + {{لَمْ}} (করেনি) = ‘করেনি কি?’ — অর্থাৎ ‘অবশ্যই করেছে!’ {{أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ}} (৯৪:১), {{أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ}} (১০৫:১) — উত্তর জানা প্রশ্ন, মনকে জাগিয়ে তোলার জন্য।","en":"{{أَلَمْ}} = {{أَ}} (?) + {{لَمْ}} (did not) = 'Did...not?' — meaning 'Of course He did!' {{أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ}} (94:1), {{أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ}} (105:1) — questions whose answer is known, asked to awaken the heart."},{"type":"text","title":{"bn":"চূড়ান্ত চ্যালেঞ্জ: একটি আয়াত নিজে ভাঙো!","en":"Final challenge: decode an ayah yourself!"},"bn":"এখন পর্যন্ত যা শিখেছ — ইসম, ফে'ল, হরফ, সর্বনাম, মুযারি' — সব একসাথে কাজে লাগাই। সূরা ফাতিহার এই আয়াতটি তুমি প্রতিদিন অন্তত ১৭ বার পড়ো!","en":"Let's use everything you've learned — ism, fi'l, harf, pronouns, the present verb — all at once. You recite this ayah of al-Fatiha at least 17 times every day!"},{"type":"ayah","ref":"1:5","ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","words":[{"ar":"إِيَّاكَ","bn":"শুধু তোমারই","en":"You alone"},{"ar":"نَعْبُدُ","bn":"আমরা ইবাদত করি","en":"we worship"},{"ar":"وَإِيَّاكَ","bn":"এবং শুধু তোমারই কাছে","en":"and You alone"},{"ar":"نَسْتَعِينُ","bn":"আমরা সাহায্য চাই","en":"we ask for help"}],"tr":{"bn":"ইয়্যাকা না'বুদু ওয়া ইয়্যাকা নাসতা'ঈন","en":"iyyāka na'budu wa iyyāka nasta'īn"},"mean":{"bn":"আমরা শুধু তোমারই ইবাদত করি এবং শুধু তোমারই কাছে সাহায্য চাই।","en":"You alone we worship, and You alone we ask for help."}},{"type":"steps","title":{"bn":"শব্দে শব্দে ব্যাকরণ","en":"Grammar, word by word"},"items":[{"title":{"bn":"{{إِيَّا}} + {{كَ}} — ‘তোমাকেই’","en":"{{إِيَّا}} + {{كَ}} — 'You (alone)'"},"ar":"إِيَّاكَ","tr":{"bn":"ইয়্যাকা","en":"iyyāka"},"desc":{"bn":"ইসম (সর্বনাম)। {{إِيَّا}} হলো কর্ম-সর্বনাম বহনকারী, {{كَ}} = তুমি (পুং, এক)। সাধারণত কর্ম ক্রিয়ার পরে বসে; এখানে **আগে** এসেছে — তাই অর্থ ‘শুধু তোমাকেই’, যেমন বাংলায় ‘-ই’ যোগ করে জোর দিই।","en":"Ism (pronoun). {{إِيَّا}} is a carrier for an object pronoun, {{كَ}} = you (m, one). Objects usually come after the verb; here it comes **first** — giving the meaning 'You and no one else'."}},{"title":{"bn":"{{نَعْبُدُ}} — ‘আমরা ইবাদত করি’","en":"{{نَعْبُدُ}} — 'we worship'"},"ar":"نَعْبُدُ","tr":{"bn":"না'বুদু","en":"na'budu"},"desc":{"bn":"ফে'লে মুযারি'। সামনে {{نَ}} = আমরা; মূল {{ع ب د}} (ইবাদত — {{عَبْدٌ}} বান্দা-ও এখান থেকে); শেষে পেশ — সাধারণ বর্তমান কাল।","en":"Present verb. Prefix {{نَ}} = we; root {{ع ب د}} (worship — {{عَبْدٌ}} 'servant' comes from it too); damma at the end — ordinary present."}},{"title":{"bn":"{{وَ}} — ‘এবং’","en":"{{وَ}} — 'and'"},"ar":"وَ","tr":{"bn":"ওয়া","en":"wa"},"desc":{"bn":"হরফ — দুই অংশকে জুড়ে দেয়; পরের শব্দের সাথে লেগে আছে।","en":"Harf — joins the two halves; glued to the next word."}},{"title":{"bn":"{{إِيَّاكَ}} — আবার ‘শুধু তোমারই’","en":"{{إِيَّاكَ}} — again 'You alone'"},"ar":"إِيَّاكَ","tr":{"bn":"ইয়্যাকা","en":"iyyāka"},"desc":{"bn":"আবার আগে এনে জোর — সাহায্যও চাই একমাত্র আল্লাহর কাছেই।","en":"Brought forward again for emphasis — help too is sought from Allah alone."}},{"title":{"bn":"{{نَسْتَعِينُ}} — ‘আমরা সাহায্য চাই’","en":"{{نَسْتَعِينُ}} — 'we seek help'"},"ar":"نَسْتَعِينُ","tr":{"bn":"নাসতা'ঈন","en":"nasta'īn"},"desc":{"bn":"ফে'লে মুযারি'। {{نَ}} = আমরা; মূল {{ع و ن}} (সাহায্য); মাঝের অতিরিক্ত {{سْت}} মানে ‘চাওয়া’ — যেমন {{اِسْتَغْفَرَ}} = ক্ষমা চাইল।","en":"Present verb. {{نَ}} = we; root {{ع و ن}} (help); the extra {{سْت}} adds 'seeking' — like {{اِسْتَغْفَرَ}} = he sought forgiveness."}}]},{"type":"table","title":{"bn":"বোনাস: পরের আয়াত {{اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ}} (১:৬)","en":"Bonus: the next ayah {{اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ}} (1:6)"},"head":[{"bn":"অংশ","en":"Piece"},{"bn":"অর্থ","en":"Meaning"},{"bn":"ব্যাকরণ","en":"Grammar"}],"rows":[["اِهْدِ",{"bn":"পথ দেখাও","en":"guide!"},{"bn":"আমর (আদেশ / দোয়া) — {{يَهْدِي}} থেকে","en":"Command (here a du'a) — from {{يَهْدِي}}"}],["نَا",{"bn":"আমাদেরকে","en":"us"},{"bn":"জোড়া সর্বনাম — কর্ম","en":"Attached pronoun — object"}],["الصِّرَاطَ",{"bn":"পথ","en":"the path"},{"bn":"ইসম, নির্দিষ্ট, যবর (কর্ম) — মাওসূফ","en":"Ism, definite, fatha (object) — the noun"}],["الْمُسْتَقِيمَ",{"bn":"সরল","en":"the straight"},{"bn":"সিফাত — {{اَلْ}}, লিঙ্গ, বচন, যবর সব মিলেছে","en":"Adjective — matches {{اَلْ}}, gender, number and fatha"}]]},{"type":"tip","kind":"fun","bn":"মাশাআল্লাহ! তুমি এখন কুরআনের একটি আয়াতকে ব্যাকরণ দিয়ে ভেঙে বুঝতে পারো। নামাজে এই আয়াত পড়ার সময় এখন থেকে প্রতিটি শব্দের ভেতরের গঠনটাও মনে পড়বে — এটাই অর্থ বুঝে পড়ার প্রথম ধাপ!","en":"Masha'Allah! You can now take apart an ayah of the Quran with grammar. From now on, when you recite it in salah, you'll feel the structure inside every word — the first step to reciting with understanding!"},{"type":"quiz","items":[{"q":{"bn":"‘সে কখনো করবে না’ বোঝাতে কোনটি?","en":"Which word means 'will never'?"},"options":["لَمْ","مَا","لَنْ","لَيْسَ"],"answer":2},{"q":{"bn":"{{لَمْ يَلِدْ}} — কোন কালের অর্থ?","en":"{{لَمْ يَلِدْ}} — what time does it refer to?"},"options":[{"bn":"অতীত (জন্ম দেননি)","en":"Past (did not beget)"},{"bn":"ভবিষ্যৎ (জন্ম দেবেন না)","en":"Future (will not beget)"},{"bn":"আদেশ","en":"Command"}],"answer":0},{"q":{"bn":"নামবাচক বাক্যকে না-বাচক করতে কোনটি?","en":"Which word negates a nominal sentence?"},"options":["لَنْ","لَيْسَ","لَمْ"],"answer":1},{"q":{"bn":"{{كَيْفَ}} অর্থ কী?","en":"What does {{كَيْفَ}} mean?"},"ar":"كَيْفَ","options":[{"bn":"কীভাবে?","en":"how?"},{"bn":"কোথায়?","en":"where?"},{"bn":"কখন?","en":"when?"},{"bn":"কে?","en":"who?"}],"answer":0},{"q":{"bn":"{{مَتٰى نَصْرُ اللّٰهِ}} — প্রশ্নবোধক শব্দটির অর্থ কী?","en":"In {{مَتٰى نَصْرُ اللّٰهِ}}, what does the question word mean?"},"options":[{"bn":"কত","en":"how many"},{"bn":"কেন","en":"why"},{"bn":"কখন","en":"when"}],"answer":2},{"q":{"bn":"{{مَا وَدَّعَكَ رَبُّكَ}} — এখানে {{مَا}} কী অর্থে?","en":"In {{مَا وَدَّعَكَ رَبُّكَ}}, what does {{مَا}} mean?"},"options":[{"bn":"না (করেননি)","en":"not (did not)"},{"bn":"যা","en":"that which"},{"bn":"কী?","en":"what?"}],"answer":0,"explain":{"bn":"অতীত ক্রিয়ার আগে {{مَا}} = না-বাচক।","en":"Before a past verb, {{مَا}} negates."}},{"q":{"bn":"{{نَسْتَعِينُ}}-এ {{نَ}} কী বোঝায়?","en":"In {{نَسْتَعِينُ}}, what does {{نَ}} show?"},"ar":"نَسْتَعِينُ","options":[{"bn":"আমি","en":"I"},{"bn":"আমরা","en":"we"},{"bn":"তুমি","en":"you"}],"answer":1},{"q":{"bn":"{{إِيَّاكَ}} ক্রিয়ার আগে আসায় কী অর্থ যোগ হয়েছে?","en":"What meaning is added by putting {{إِيَّاكَ}} before the verb?"},"options":[{"bn":"প্রশ্ন","en":"A question"},{"bn":"ভবিষ্যৎ কাল","en":"Future time"},{"bn":"‘শুধু তোমাকেই’ — একমাত্রতা","en":"'You alone' — exclusivity"}],"answer":2}]}]}]});
AQ.units.push({"id":"daily","order":6,"icon":"ح","color":"rose","title":{"bn":"দৈনন্দিন আরবি","en":"Everyday Arabic"},"subtitle":{"bn":"সালাম, পরিচয়, সংখ্যা, পরিবার, বাজার, সময় — প্রতিদিনের কাজের আরবি","en":"Greetings, numbers, family, market, time — Arabic you can use every day"},"lessons":[{"id":"daily-islamic-phrases","icon":"ﷲ","title":{"bn":"প্রতিদিনের ইসলামি বাক্য","en":"Islamic Phrases for Every Day"},"subtitle":{"bn":"কোন কথা কখন বলবেন — সালাম থেকে ইন্না লিল্লাহ","en":"What to say and when — from salam to inna lillah"},"minutes":15,"goals":[{"bn":"সালাম দেওয়া ও সালামের উত্তর দেওয়া","en":"Give salam and reply to it correctly"},{"bn":"আল্লাহর যিকরের ছোট ছোট বাক্যের অর্থ জানা","en":"Understand short phrases of dhikr"},{"bn":"কোন পরিস্থিতিতে কোন বাক্য বলতে হয় তা চেনা","en":"Know which phrase fits which situation"},{"bn":"ছেলে, মেয়ে ও দলকে বলার সময় শেষাংশ বদলানো","en":"Change the ending for a man, a woman or a group"}],"blocks":[{"type":"text","bn":"আপনি হয়তো খেয়াল করেননি — আপনি **ইতিমধ্যেই** অনেক আরবি বলেন! {{السَّلَامُ عَلَيْكُمْ}}, {{الْحَمْدُ لِلّٰهِ}}, {{إِنْ شَاءَ اللّٰهُ}} — এগুলো সবই আরবি বাক্য। এই পাঠে আমরা এগুলোর আসল অর্থ জানব, আর শিখব **কখন** কোনটা বলতে হয়।","en":"You may not have noticed — you **already** speak quite a bit of Arabic! {{السَّلَامُ عَلَيْكُمْ}}, {{الْحَمْدُ لِلّٰهِ}}, {{إِنْ شَاءَ اللّٰهُ}} are all Arabic sentences. In this lesson we learn what they really mean, and **when** to say each one."},{"type":"vocab","title":{"bn":"শান্তির সালাম","en":"The greeting of peace"},"items":[{"ar":"السَّلَامُ عَلَيْكُمْ","tr":{"bn":"আস্‌সালামু আলাইকুম","en":"as-salaamu 'alaykum"},"mean":{"bn":"আপনাদের উপর শান্তি বর্ষিত হোক","en":"Peace be upon you"},"root":"س ل م"},{"ar":"وَعَلَيْكُمُ السَّلَامُ","tr":{"bn":"ওয়া আলাইকুমুস সালাম","en":"wa 'alaykumus-salaam"},"mean":{"bn":"আপনাদের উপরও শান্তি বর্ষিত হোক (উত্তর)","en":"And upon you be peace (the reply)"}},{"ar":"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ","tr":{"bn":"আস্‌সালামু আলাইকুম ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ","en":"as-salaamu 'alaykum wa raḥmatullaahi wa barakaatuh"},"mean":{"bn":"আপনাদের উপর শান্তি, আল্লাহর রহমত ও তাঁর বরকত বর্ষিত হোক","en":"Peace be upon you, and the mercy of Allah and His blessings"}}]},{"type":"tip","kind":"memory","bn":"উত্তর দেওয়ার সহজ নিয়ম: শুধু শব্দ দুটো **উল্টে দিন** আর সামনে {{وَ}} (এবং) লাগান — {{السَّلَامُ عَلَيْكُمْ}} ➜ {{وَعَلَيْكُمُ السَّلَامُ}}। আর উত্তর সমান বা আরও সুন্দর করে দেওয়াই উত্তম — তাই {{وَرَحْمَةُ اللّٰهِ}} যোগ করে দিন।","en":"Easy rule for the reply: just **flip** the two words and put {{وَ}} (and) in front — {{السَّلَامُ عَلَيْكُمْ}} ➜ {{وَعَلَيْكُمُ السَّلَامُ}}. It is best to reply equally or more beautifully — so add {{وَرَحْمَةُ اللّٰهِ}}."},{"type":"vocab","title":{"bn":"আল্লাহর স্মরণ","en":"Remembering Allah"},"items":[{"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লাহ","en":"bismillaah"},"mean":{"bn":"আল্লাহর নামে (শুরু করছি)","en":"In the name of Allah"},"example":{"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","mean":{"bn":"পরম করুণাময়, অতি দয়ালু আল্লাহর নামে","en":"In the name of Allah, the Most Merciful, the Especially Merciful"},"ref":"1:1"}},{"ar":"الْحَمْدُ لِلّٰهِ","tr":{"bn":"আলহামদু লিল্লাহ","en":"al-ḥamdu lillaah"},"mean":{"bn":"সব প্রশংসা আল্লাহর জন্য","en":"All praise is for Allah"},"root":"ح م د","example":{"ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি সারা জগতের রব","en":"All praise is for Allah, Lord of all the worlds"},"ref":"1:2"}},{"ar":"سُبْحَانَ اللّٰهِ","tr":{"bn":"সুবহানাল্লাহ","en":"subḥaanallaah"},"mean":{"bn":"আল্লাহ পবিত্র (সব দোষ-ত্রুটি থেকে)","en":"Glory be to Allah (He is free of every flaw)"}},{"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},"root":"ك ب ر"},{"ar":"أَسْتَغْفِرُ اللّٰهَ","tr":{"bn":"আস্তাগফিরুল্লাহ","en":"astaghfirullaah"},"mean":{"bn":"আমি আল্লাহর কাছে ক্ষমা চাই","en":"I ask Allah for forgiveness"},"root":"غ ف ر"},{"ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ","tr":{"bn":"লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ","en":"laa ḥawla wa laa quwwata illaa billaah"},"mean":{"bn":"আল্লাহর সাহায্য ছাড়া কোনো শক্তি বা সামর্থ্য নেই","en":"There is no power and no strength except through Allah"}}]},{"type":"vocab","title":{"bn":"আশা, প্রশংসা ও কৃতজ্ঞতা","en":"Hope, admiration and thanks"},"items":[{"ar":"إِنْ شَاءَ اللّٰهُ","tr":{"bn":"ইন শা আল্লাহ","en":"in shaaʾallaah"},"mean":{"bn":"আল্লাহ চাইলে","en":"If Allah wills"}},{"ar":"مَا شَاءَ اللّٰهُ","tr":{"bn":"মা শা আল্লাহ","en":"maa shaaʾallaah"},"mean":{"bn":"আল্লাহ যা চেয়েছেন (তা-ই হয়েছে)","en":"What Allah has willed (has happened)"},"example":{"ar":"قُلْتَ مَا شَاءَ اللّٰهُ لَا قُوَّةَ إِلَّا بِاللّٰهِ","mean":{"bn":"তুমি বলতে: আল্লাহ যা চেয়েছেন; আল্লাহ ছাড়া কোনো শক্তি নেই","en":"You should have said: what Allah willed; there is no power except with Allah"},"ref":"18:39"}},{"ar":"جَزَاكَ اللّٰهُ خَيْرًا","tr":{"bn":"জাযাকাল্লাহু খাইরান","en":"jazaakallaahu khayran"},"mean":{"bn":"আল্লাহ আপনাকে উত্তম প্রতিদান দিন","en":"May Allah reward you with good"}},{"ar":"وَإِيَّاكَ","tr":{"bn":"ওয়া ইয়্যাকা","en":"wa iyyaaka"},"mean":{"bn":"আপনাকেও (জাযাকাল্লাহর উত্তরে)","en":"And you too (reply to jazaakallaah)"}},{"ar":"بَارَكَ اللّٰهُ فِيكَ","tr":{"bn":"বারাকাল্লাহু ফীক","en":"baarakallaahu feek"},"mean":{"bn":"আল্লাহ আপনার মধ্যে বরকত দিন","en":"May Allah bless you"},"root":"ب ر ك"},{"ar":"آمِينَ","tr":{"bn":"আমীন","en":"aameen"},"mean":{"bn":"হে আল্লাহ, কবুল করুন","en":"O Allah, accept (our prayer)"}}]},{"type":"vocab","title":{"bn":"কষ্টের সময় ও হাঁচি দিলে","en":"Hard moments and sneezing"},"items":[{"ar":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ","tr":{"bn":"ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিঊন","en":"innaa lillaahi wa innaa ilayhi raaji'oon"},"mean":{"bn":"আমরা আল্লাহরই, আর তাঁর কাছেই আমরা ফিরে যাব","en":"We belong to Allah, and to Him we shall return"},"example":{"ar":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ","mean":{"bn":"বিপদে ধৈর্যশীলরা এ কথা বলে","en":"The patient say this when struck by hardship"},"ref":"2:156"}},{"ar":"يَرْحَمُكَ اللّٰهُ","tr":{"bn":"ইয়ারহামুকাল্লাহ","en":"yarḥamukallaah"},"mean":{"bn":"আল্লাহ আপনার উপর রহম করুন","en":"May Allah have mercy on you"},"root":"ر ح م"},{"ar":"يَهْدِيكُمُ اللّٰهُ وَيُصْلِحُ بَالَكُمْ","tr":{"bn":"ইয়াহদীকুমুল্লাহু ওয়া ইউসলিহু বালাকুম","en":"yahdeekumullaahu wa yuṣliḥu baalakum"},"mean":{"bn":"আল্লাহ আপনাদের হিদায়াত দিন ও আপনাদের অবস্থা ভালো করে দিন","en":"May Allah guide you and set your affairs right"}}]},{"type":"table","title":{"bn":"কখন কী বলবেন","en":"When to say what"},"head":[{"bn":"পরিস্থিতি","en":"Situation"},{"bn":"বলুন","en":"Say"},{"bn":"অর্থ","en":"Meaning"}],"rows":[[{"bn":"কারো সাথে দেখা হলে","en":"Meeting someone"},"السَّلَامُ عَلَيْكُمْ",{"bn":"আপনাদের উপর শান্তি","en":"Peace be upon you"}],[{"bn":"খাওয়া, পড়া বা যেকোনো ভালো কাজ শুরুর আগে","en":"Before eating, reading or any good deed"},"بِسْمِ اللّٰهِ",{"bn":"আল্লাহর নামে","en":"In the name of Allah"}],[{"bn":"খাওয়ার পরে, ভালো খবর পেলে, কেউ কেমন আছেন জিজ্ঞেস করলে","en":"After eating, on good news, when asked how you are"},"الْحَمْدُ لِلّٰهِ",{"bn":"সব প্রশংসা আল্লাহর","en":"All praise is for Allah"}],[{"bn":"ভবিষ্যতে কিছু করার কথা বললে","en":"Talking about something you plan to do"},"إِنْ شَاءَ اللّٰهُ",{"bn":"আল্লাহ চাইলে","en":"If Allah wills"}],[{"bn":"সুন্দর কিছু দেখলে বা কারো প্রশংসা করলে","en":"Seeing something lovely or praising someone"},"مَا شَاءَ اللّٰهُ",{"bn":"আল্লাহ যা চেয়েছেন","en":"What Allah has willed"}],[{"bn":"আশ্চর্য কিছু দেখলে বা শুনলে","en":"Seeing or hearing something amazing"},"سُبْحَانَ اللّٰهِ",{"bn":"আল্লাহ পবিত্র","en":"Glory be to Allah"}],[{"bn":"ভুল হয়ে গেলে","en":"After a mistake or sin"},"أَسْتَغْفِرُ اللّٰهَ",{"bn":"আল্লাহর কাছে ক্ষমা চাই","en":"I seek Allah's forgiveness"}],[{"bn":"কেউ উপকার করলে","en":"When someone helps you"},"جَزَاكَ اللّٰهُ خَيْرًا",{"bn":"আল্লাহ উত্তম প্রতিদান দিন","en":"May Allah reward you well"}],[{"bn":"কাউকে দোয়া দিতে বা ধন্যবাদের উত্তরে","en":"Blessing someone or answering thanks"},"بَارَكَ اللّٰهُ فِيكَ",{"bn":"আল্লাহ বরকত দিন","en":"May Allah bless you"}],[{"bn":"মৃত্যুর খবর বা কোনো বিপদ-ক্ষতিতে","en":"News of a death, or any loss"},"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ",{"bn":"আমরা আল্লাহর, তাঁর কাছেই ফিরব","en":"We belong to Allah and return to Him"}],[{"bn":"কেউ হাঁচি দিয়ে আলহামদুলিল্লাহ বললে","en":"Someone sneezes and says al-ḥamdu lillaah"},"يَرْحَمُكَ اللّٰهُ",{"bn":"আল্লাহ আপনার উপর রহম করুন","en":"May Allah have mercy on you"}]]},{"type":"tip","kind":"warn","bn":"{{إِنْ شَاءَ اللّٰهُ}} লিখুন **তিনটি আলাদা শব্দে**। একসাথে জুড়ে {{إِنْشَاء}} লিখলে অর্থ দাঁড়ায় “তৈরি করা” বা “রচনা” — একেবারে অন্য জিনিস!","en":"Write {{إِنْ شَاءَ اللّٰهُ}} as **three separate words**. Joined together as {{إِنْشَاء}} it means “creating” or “an essay” — something completely different!"},{"type":"tip","kind":"memory","bn":"শেষের ছোট অংশটি বলে দেয় আপনি কাকে বলছেন: {{ـكَ}} (কা) = একজন ছেলে, {{ـكِ}} (কি) = একজন মেয়ে, {{ـكُمْ}} (কুম) = অনেকজন। যেমন: {{جَزَاكَ اللّٰهُ}}, {{جَزَاكِ اللّٰهُ}}, {{جَزَاكُمُ اللّٰهُ}}।","en":"The little ending tells who you are talking to: {{ـكَ}} (ka) = one male, {{ـكِ}} (ki) = one female, {{ـكُمْ}} (kum) = a group. E.g. {{جَزَاكَ اللّٰهُ}}, {{جَزَاكِ اللّٰهُ}}, {{جَزَاكُمُ اللّٰهُ}}."},{"type":"examples","title":{"bn":"ছোট্ট দৃশ্য","en":"Mini scenes"},"items":[{"ar":"بَارَكَ اللّٰهُ فِيكِ","tr":{"bn":"বারাকাল্লাহু ফীকি","en":"baarakallaahu feeki"},"mean":{"bn":"আল্লাহ তোমার মধ্যে বরকত দিন (মেয়েকে)","en":"May Allah bless you (to a girl/woman)"},"note":{"bn":"আম্মু মজার পিঠা বানিয়েছেন — তাঁকে এভাবে বলুন।","en":"Mum made delicious pitha — say this to her."},"hl":"فِيكِ"},{"ar":"جَزَاكُمُ اللّٰهُ خَيْرًا","tr":{"bn":"জাযাকুমুল্লাহু খাইরান","en":"jazaakumullaahu khayran"},"mean":{"bn":"আল্লাহ আপনাদের উত্তম প্রতিদান দিন","en":"May Allah reward you all with good"},"note":{"bn":"পুরো ক্লাসকে ধন্যবাদ দিতে চাইলে।","en":"To thank a whole class."},"hl":"جَزَاكُمُ"},{"ar":"أَرَاكَ غَدًا إِنْ شَاءَ اللّٰهُ","tr":{"bn":"আরাকা গাদান ইন শা আল্লাহ","en":"araaka ghadan in shaaʾallaah"},"mean":{"bn":"কাল তোমার সাথে দেখা হবে, ইন শা আল্লাহ","en":"See you tomorrow, if Allah wills"},"note":{"bn":"ভবিষ্যতের কথা — তাই ইন শা আল্লাহ।","en":"It is about the future — so in shaaʾallaah."},"hl":"إِنْ شَاءَ اللّٰهُ"}]},{"type":"tip","kind":"fun","bn":"বাংলায় আমরা বলি “সালাম দাও”, “শোকর আলহামদুলিল্লাহ”, “বরকত হোক”, “রহমত” — এই সালাম, শুকর, বরকত, রহমত সবই আরবি শব্দ! {{سَلَام}} (শান্তি), {{شُكْر}} (কৃতজ্ঞতা), {{بَرَكَة}} (বরকত), {{رَحْمَة}} (দয়া)।","en":"In Bangla we say “give salam”, “shukr alhamdulillah”, “barakat”, “rahmat” — salam, shukr, barakah and rahmah are all Arabic words! {{سَلَام}} (peace), {{شُكْر}} (thanks), {{بَرَكَة}} (blessing), {{رَحْمَة}} (mercy)."},{"type":"quiz","items":[{"q":{"bn":"কেউ বলল {{السَّلَامُ عَلَيْكُمْ}} — আপনি কী বলবেন?","en":"Someone says {{السَّلَامُ عَلَيْكُمْ}} — what do you reply?"},"options":["وَعَلَيْكُمُ السَّلَامُ","إِنْ شَاءَ اللّٰهُ","سُبْحَانَ اللّٰهِ","آمِينَ"],"answer":0},{"q":{"bn":"আপনার বন্ধু বলল, “কাল তোমার বাসায় আসব।” তার সাথে কোন বাক্য যোগ হওয়া উচিত?","en":"Your friend says, “I will come to your house tomorrow.” Which phrase should go with it?"},"options":["إِنَّا لِلّٰهِ","إِنْ شَاءَ اللّٰهُ","يَرْحَمُكَ اللّٰهُ"],"answer":1},{"q":{"bn":"{{أَسْتَغْفِرُ اللّٰهَ}} অর্থ কী?","en":"What does {{أَسْتَغْفِرُ اللّٰهَ}} mean?"},"options":[{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},{"bn":"আমি আল্লাহর কাছে ক্ষমা চাই","en":"I ask Allah for forgiveness"},{"bn":"আল্লাহর নামে","en":"In the name of Allah"}],"answer":1},{"q":{"bn":"কেউ হাঁচি দিয়ে {{الْحَمْدُ لِلّٰهِ}} বলল। আপনি কী বলবেন?","en":"Someone sneezes and says {{الْحَمْدُ لِلّٰهِ}}. What do you say?"},"options":["مَا شَاءَ اللّٰهُ","يَرْحَمُكَ اللّٰهُ","بِسْمِ اللّٰهِ","وَإِيَّاكَ"],"answer":1},{"q":{"bn":"আপনার বোন আপনাকে সাহায্য করল। তাকে কোনটি বলবেন?","en":"Your sister helped you. What do you say to her?"},"options":["جَزَاكَ اللّٰهُ خَيْرًا","جَزَاكِ اللّٰهُ خَيْرًا","جَزَاكُمُ اللّٰهُ خَيْرًا"],"answer":1,"explain":{"bn":"একজন মেয়েকে বলতে {{ـكِ}} (কি) লাগে।","en":"For one female we use {{ـكِ}} (ki)."}},{"q":{"bn":"কারো মৃত্যুর খবর শুনলে কোনটি বলা হয়?","en":"What is said on hearing of someone's death?"},"options":["اللّٰهُ أَكْبَرُ","إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ","مَا شَاءَ اللّٰهُ"],"answer":1},{"q":{"bn":"বন্ধুর নতুন সুন্দর বাগান দেখে কী বলবেন?","en":"You see your friend's lovely new garden. What do you say?"},"options":["مَا شَاءَ اللّٰهُ","أَسْتَغْفِرُ اللّٰهَ","وَعَلَيْكُمُ السَّلَامُ"],"answer":0,"explain":{"bn":"সূরা কাহফের (১৮:৩৯) বাগানওয়ালার ঘটনাতেও এই শিক্ষা আছে।","en":"The story of the garden owner in Surah al-Kahf (18:39) teaches exactly this."}}]}]},{"id":"daily-greetings","icon":"س","title":{"bn":"শুভেচ্ছা ও নিজের পরিচয়","en":"Greetings & Introducing Yourself"},"subtitle":{"bn":"সুপ্রভাত থেকে বিদায় — প্রথম আলাপের সব কথা","en":"From good morning to goodbye — your first conversation"},"minutes":15,"goals":[{"bn":"সকাল-সন্ধ্যার শুভেচ্ছা ও তার উত্তর","en":"Morning and evening greetings with replies"},{"bn":"কেমন আছেন, নাম কী, কোথা থেকে — জিজ্ঞেস ও উত্তর","en":"Ask and answer: how are you, your name, where from"},{"bn":"একটি ছোট সংলাপ পড়া ও অভিনয় করা","en":"Read and act out a short dialogue"}],"blocks":[{"type":"text","bn":"নতুন কারো সাথে দেখা? চিন্তা নেই! মাত্র দশ-বারোটি বাক্য শিখলেই আপনি আরবিতে পুরো একটা পরিচয়-আলাপ করতে পারবেন। সালাম দিয়ে শুরু করুন, তারপর এই বাক্যগুলো কাজে লাগান।","en":"Meeting someone new? No worries! With just ten or twelve sentences you can hold a whole introduction in Arabic. Start with salam, then use these."},{"type":"vocab","title":{"bn":"শুভেচ্ছা","en":"Greetings"},"items":[{"ar":"صَبَاحُ الْخَيْرِ","tr":{"bn":"সাবাহুল খাইর","en":"ṣabaaḥul-khayr"},"mean":{"bn":"সুপ্রভাত (সকালের শুভেচ্ছা)","en":"Good morning"}},{"ar":"صَبَاحُ النُّورِ","tr":{"bn":"সাবাহুন নূর","en":"ṣabaaḥun-noor"},"mean":{"bn":"আলোকিত সকাল (সুপ্রভাতের উত্তর)","en":"Morning of light (reply to good morning)"}},{"ar":"مَسَاءُ الْخَيْرِ","tr":{"bn":"মাসাউল খাইর","en":"masaaʾul-khayr"},"mean":{"bn":"শুভ সন্ধ্যা","en":"Good evening"}},{"ar":"مَسَاءُ النُّورِ","tr":{"bn":"মাসাউন নূর","en":"masaaʾun-noor"},"mean":{"bn":"আলোকিত সন্ধ্যা (উত্তর)","en":"Evening of light (reply)"}},{"ar":"مَرْحَبًا","tr":{"bn":"মারহাবান","en":"marḥaban"},"mean":{"bn":"স্বাগতম / হ্যালো","en":"Hello / welcome"}},{"ar":"أَهْلًا وَسَهْلًا","tr":{"bn":"আহলান ওয়া সাহলান","en":"ahlan wa sahlan"},"mean":{"bn":"স্বাগতম, আপন মনে করুন","en":"Welcome, make yourself at home"}}]},{"type":"tip","kind":"memory","bn":"খেয়াল করুন: উত্তরে শুধু {{الْخَيْرِ}} (কল্যাণ) বদলে {{النُّورِ}} (আলো) হয়ে যায়। “নূর” শব্দটি তো আমরা চিনি — নূরজাহান, নূরানী!","en":"Notice: in the reply, {{الْخَيْرِ}} (goodness) simply becomes {{النُّورِ}} (light). We already know “noor” — as in Noor Jahan, Noorani!"},{"type":"vocab","title":{"bn":"পরিচয়ের বাক্য","en":"Introduction sentences"},"items":[{"ar":"كَيْفَ حَالُكَ؟","tr":{"bn":"কাইফা হালুকা?","en":"kayfa ḥaaluka?"},"mean":{"bn":"কেমন আছেন? (ছেলেকে)","en":"How are you? (to a male)"}},{"ar":"كَيْفَ حَالُكِ؟","tr":{"bn":"কাইফা হালুকি?","en":"kayfa ḥaaluki?"},"mean":{"bn":"কেমন আছেন? (মেয়েকে)","en":"How are you? (to a female)"}},{"ar":"أَنَا بِخَيْرٍ، وَالْحَمْدُ لِلّٰهِ","tr":{"bn":"আনা বিখাইর, ওয়াল হামদু লিল্লাহ","en":"ana bikhayr, wal-ḥamdu lillaah"},"mean":{"bn":"আমি ভালো আছি, আলহামদুলিল্লাহ","en":"I am well, praise be to Allah"}},{"ar":"مَا اسْمُكَ؟","tr":{"bn":"মাসমুকা?","en":"masmuka?"},"mean":{"bn":"আপনার নাম কী?","en":"What is your name?"}},{"ar":"اِسْمِي ...","tr":{"bn":"ইসমী ...","en":"ismee ..."},"mean":{"bn":"আমার নাম ...","en":"My name is ..."}},{"ar":"مِنْ أَيْنَ أَنْتَ؟","tr":{"bn":"মিন আইনা আন্তা?","en":"min ayna anta?"},"mean":{"bn":"আপনি কোথা থেকে এসেছেন?","en":"Where are you from?"}},{"ar":"أَنَا مِنْ بَنْغْلَادِيشَ","tr":{"bn":"আনা মিন বাংলাদেশ","en":"ana min banghlaadeesh"},"mean":{"bn":"আমি বাংলাদেশ থেকে","en":"I am from Bangladesh"}},{"ar":"تَشَرَّفْنَا","tr":{"bn":"তাশাররাফনা","en":"tasharrafnaa"},"mean":{"bn":"আপনার সাথে পরিচিত হয়ে খুশি হলাম","en":"Pleased to meet you (lit. we are honoured)"}},{"ar":"شُكْرًا","tr":{"bn":"শুকরান","en":"shukran"},"mean":{"bn":"ধন্যবাদ","en":"Thank you"},"root":"ش ك ر"},{"ar":"عَفْوًا","tr":{"bn":"আফওয়ান","en":"'afwan"},"mean":{"bn":"কোনো ব্যাপার না / দুঃখিত","en":"You're welcome / excuse me"}},{"ar":"مَعَ السَّلَامَةِ","tr":{"bn":"মাআস সালামাহ","en":"ma'as-salaamah"},"mean":{"bn":"নিরাপদে থাকুন (বিদায়)","en":"Goodbye (lit. with safety)"}},{"ar":"إِلَى اللِّقَاءِ","tr":{"bn":"ইলাল লিকা","en":"ilal-liqaaʾ"},"mean":{"bn":"আবার দেখা হবে","en":"See you again"}}]},{"type":"compare","title":{"bn":"ছেলে না মেয়ে?","en":"Male or female?"},"items":[{"ar":"أَنْتَ","label":{"bn":"আন্তা — তুমি (ছেলে)","en":"anta — you (male)"},"desc":{"bn":"শেষে যবর: {{مِنْ أَيْنَ أَنْتَ؟}}","en":"Ends with fatha: {{مِنْ أَيْنَ أَنْتَ؟}}"}},{"ar":"أَنْتِ","label":{"bn":"আন্তি — তুমি (মেয়ে)","en":"anti — you (female)"},"desc":{"bn":"শেষে যের: {{مِنْ أَيْنَ أَنْتِ؟}}","en":"Ends with kasra: {{مِنْ أَيْنَ أَنْتِ؟}}"}}]},{"type":"tip","kind":"tip","bn":"{{مَا اسْمُكَ؟}}-তে {{ا}} পড়া হয় না — {{مَا}} সরাসরি {{سْ}}-এর সাথে মিলে যায়: “মাসমুকা”। কিন্তু বাক্যের শুরুতে {{اِسْمِي}} বললে “ই” উচ্চারণ করতে হয়।","en":"In {{مَا اسْمُكَ؟}} the {{ا}} is silent — {{مَا}} joins straight onto {{سْ}}: “masmuka”. But at the very start of a sentence, {{اِسْمِي}} begins with an “i” sound."},{"type":"steps","title":{"bn":"সংলাপ: মসজিদের বাইরে নতুন পরিচয়","en":"Dialogue: a new friend outside the masjid"},"items":[{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"السَّلَامُ عَلَيْكُمْ.","tr":{"bn":"আস্‌সালামু আলাইকুম।","en":"as-salaamu 'alaykum."},"mean":{"bn":"আসসালামু আলাইকুম।","en":"Peace be upon you."}},{"title":{"bn":"যায়েদ","en":"Zayd"},"ar":"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللّٰهِ.","tr":{"bn":"ওয়া আলাইকুমুস সালাম ওয়া রাহমাতুল্লাহ।","en":"wa 'alaykumus-salaam wa raḥmatullaah."},"mean":{"bn":"আপনার উপরও শান্তি ও আল্লাহর রহমত।","en":"And upon you be peace and Allah's mercy."}},{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"كَيْفَ حَالُكَ؟","tr":{"bn":"কাইফা হালুকা?","en":"kayfa ḥaaluka?"},"mean":{"bn":"কেমন আছেন?","en":"How are you?"}},{"title":{"bn":"যায়েদ","en":"Zayd"},"ar":"أَنَا بِخَيْرٍ، وَالْحَمْدُ لِلّٰهِ. وَأَنْتَ؟","tr":{"bn":"আনা বিখাইর, ওয়াল হামদু লিল্লাহ। ওয়া আন্তা?","en":"ana bikhayr, wal-ḥamdu lillaah. wa anta?"},"mean":{"bn":"ভালো আছি, আলহামদুলিল্লাহ। আর আপনি?","en":"I'm well, praise be to Allah. And you?"}},{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"بِخَيْرٍ، الْحَمْدُ لِلّٰهِ. مَا اسْمُكَ؟","tr":{"bn":"বিখাইর, আলহামদু লিল্লাহ। মাসমুকা?","en":"bikhayr, al-ḥamdu lillaah. masmuka?"},"mean":{"bn":"ভালো, আলহামদুলিল্লাহ। আপনার নাম কী?","en":"Well, praise be to Allah. What is your name?"}},{"title":{"bn":"যায়েদ","en":"Zayd"},"ar":"اِسْمِي زَيْدٌ. وَمَا اسْمُكَ؟","tr":{"bn":"ইসমী যাইদ। ওয়া মাসমুকা?","en":"ismee zayd. wa masmuka?"},"mean":{"bn":"আমার নাম যায়েদ। আর আপনার নাম?","en":"My name is Zayd. And your name?"}},{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"اِسْمِي أَحْمَدُ. مِنْ أَيْنَ أَنْتَ؟","tr":{"bn":"ইসমী আহমাদ। মিন আইনা আন্তা?","en":"ismee aḥmad. min ayna anta?"},"mean":{"bn":"আমার নাম আহমাদ। আপনি কোথা থেকে?","en":"My name is Ahmad. Where are you from?"}},{"title":{"bn":"যায়েদ","en":"Zayd"},"ar":"أَنَا مِنْ مِصْرَ. وَأَنْتَ؟","tr":{"bn":"আনা মিন মিসর। ওয়া আন্তা?","en":"ana min miṣr. wa anta?"},"mean":{"bn":"আমি মিশর থেকে। আর আপনি?","en":"I am from Egypt. And you?"}},{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"أَنَا مِنْ بَنْغْلَادِيشَ.","tr":{"bn":"আনা মিন বাংলাদেশ।","en":"ana min banghlaadeesh."},"mean":{"bn":"আমি বাংলাদেশ থেকে।","en":"I am from Bangladesh."}},{"title":{"bn":"যায়েদ","en":"Zayd"},"ar":"تَشَرَّفْنَا!","tr":{"bn":"তাশাররাফনা!","en":"tasharrafnaa!"},"mean":{"bn":"পরিচিত হয়ে খুশি হলাম!","en":"Pleased to meet you!"}},{"title":{"bn":"আহমাদ","en":"Ahmad"},"ar":"وَأَنَا كَذٰلِكَ. مَعَ السَّلَامَةِ.","tr":{"bn":"ওয়া আনা কাযালিক। মাআস সালামাহ।","en":"wa ana kadhaalik. ma'as-salaamah."},"mean":{"bn":"আমিও। আল্লাহ হাফেজ।","en":"Me too. Goodbye."}}]},{"type":"tip","kind":"fun","bn":"বাংলায় “শুকরিয়া” আর “শোকর” — দুটোই আরবি {{شُكْر}} থেকে এসেছে। আর অতিথি এলে আমরা যে বলি “মারহাবা!” — সেটাও খাঁটি আরবি {{مَرْحَبًا}}!","en":"The Bangla “shukriya” and “shokor” both come from Arabic {{شُكْر}}. And when a guest arrives and we say “marhaba!” — that's pure Arabic {{مَرْحَبًا}}!"},{"type":"examples","title":{"bn":"নিজের কথা বলুন","en":"Talk about yourself"},"items":[{"ar":"اِسْمِي فَاطِمَةُ","tr":{"bn":"ইসমী ফাতিমাহ","en":"ismee faaṭimah"},"mean":{"bn":"আমার নাম ফাতিমা","en":"My name is Fatimah"},"hl":"اِسْمِي"},{"ar":"أَنَا مِنْ دَاكَا","tr":{"bn":"আনা মিন ঢাকা","en":"ana min daakaa"},"mean":{"bn":"আমি ঢাকা থেকে","en":"I am from Dhaka"},"note":{"bn":"আরবিতে ‘ঢ’ নেই, তাই {{د}} দিয়ে লেখা হয়।","en":"Arabic has no ‘dh’ (ঢ) sound, so it is written with {{د}}."},"hl":"مِنْ"},{"ar":"أَنَا طَالِبٌ","tr":{"bn":"আনা তালিব","en":"ana ṭaalib"},"mean":{"bn":"আমি একজন ছাত্র","en":"I am a student (male)"},"hl":"طَالِبٌ"},{"ar":"أَنَا طَالِبَةٌ","tr":{"bn":"আনা তালিবাহ","en":"ana ṭaalibah"},"mean":{"bn":"আমি একজন ছাত্রী","en":"I am a student (female)"},"hl":"طَالِبَةٌ"}]},{"type":"quiz","items":[{"q":{"bn":"কেউ বলল {{صَبَاحُ الْخَيْرِ}}। সুন্দর উত্তর কোনটি?","en":"Someone says {{صَبَاحُ الْخَيْرِ}}. What is the nice reply?"},"options":["مَسَاءُ الْخَيْرِ","صَبَاحُ النُّورِ","مَعَ السَّلَامَةِ"],"answer":1},{"q":{"bn":"“আপনার নাম কী?” আরবিতে কোনটি?","en":"Which means “What is your name?”"},"options":["مِنْ أَيْنَ أَنْتَ؟","كَيْفَ حَالُكَ؟","مَا اسْمُكَ؟"],"answer":2},{"q":{"bn":"একজন মেয়েকে “কেমন আছেন?” জিজ্ঞেস করতে কোনটি বলবেন?","en":"To ask a woman “How are you?” you say:"},"options":["كَيْفَ حَالُكَ؟","كَيْفَ حَالُكِ؟","كَيْفَ حَالُكُمْ؟"],"answer":1},{"q":{"bn":"{{تَشَرَّفْنَا}} কখন বলা হয়?","en":"When do you say {{تَشَرَّفْنَا}}?"},"options":[{"bn":"কারো সাথে প্রথম পরিচয়ে","en":"When meeting someone for the first time"},{"bn":"খাবার শুরুর আগে","en":"Before starting a meal"},{"bn":"ঘুমাতে যাওয়ার আগে","en":"Before going to sleep"}],"answer":0},{"q":{"bn":"বিদায় নেওয়ার সময় কোনটি বলবেন?","en":"Which do you say when leaving?"},"options":["أَهْلًا وَسَهْلًا","مَعَ السَّلَامَةِ","مَرْحَبًا"],"answer":1},{"q":{"bn":"{{أَنَا مِنْ بَنْغْلَادِيشَ}} অর্থ কী?","en":"What does {{أَنَا مِنْ بَنْغْلَادِيشَ}} mean?"},"options":[{"bn":"আমি বাংলাদেশে যাব","en":"I will go to Bangladesh"},{"bn":"আমি বাংলাদেশ থেকে","en":"I am from Bangladesh"},{"bn":"বাংলাদেশ সুন্দর","en":"Bangladesh is beautiful"}],"answer":1},{"q":{"bn":"কেউ {{شُكْرًا}} বললে উত্তরে কী বলা যায়?","en":"Someone says {{شُكْرًا}}. What can you reply?"},"options":["عَفْوًا","صَبَاحُ النُّورِ","اِسْمِي"],"answer":0}]}]},{"id":"daily-numbers","icon":"١٢٣","title":{"bn":"সংখ্যা ও গণনা","en":"Numbers & Counting"},"subtitle":{"bn":"০ থেকে ১০০০ — আরবি অঙ্ক আর বাংলা অঙ্কের মজার আত্মীয়তা","en":"0 to 1000 — and the surprising family link with Bangla digits"},"minutes":20,"goals":[{"bn":"আরবি অঙ্ক ٠–٩ চেনা ও লেখা","en":"Recognise and write the Arabic digits ٠–٩"},{"bn":"০ থেকে ২০ পর্যন্ত আরবিতে গোনা","en":"Count from 0 to 20 in Arabic"},{"bn":"দশক, একশো ও এক হাজার বলা","en":"Say the tens, one hundred and one thousand"},{"bn":"২১, ৩৫-এর মতো সংখ্যা তৈরি করা","en":"Build numbers like 21 and 35"}],"blocks":[{"type":"text","bn":"একটা মজার রহস্য দিয়ে শুরু করি: ইংরেজিতে 1, 2, 3-কে বলে “Arabic numerals”, অথচ আরবরা নিজেরা লেখে ٢، ١، ٣ আর এগুলোকে বলে “হিন্দি অঙ্ক” ({{أَرْقَامٌ هِنْدِيَّةٌ}})! কারণ — শূন্যসহ এই দশ অঙ্কের পদ্ধতি জন্মেছিল **ভারতবর্ষে**, আরবরা তা শিখে উন্নত করে, তারপর ইউরোপে পৌঁছায়। আর আমাদের বাংলা অঙ্ক ০১২৩... এসেছে সেই একই ভারতীয় পরিবার থেকে। তাই আরবি, বাংলা আর ইংরেজি অঙ্ক — তিনজনই আসলে **চাচাতো ভাই**!","en":"Let's start with a fun puzzle: in English 1, 2, 3 are called “Arabic numerals”, yet Arabs themselves write ١، ٢، ٣ and call them “Hindi numerals” ({{أَرْقَامٌ هِنْدِيَّةٌ}})! Why? The ten-digit system with zero was born in **India**, Arab scholars learned and developed it, and from them it reached Europe. Our Bangla digits ০১২৩... come from the same Indian family. So Arabic, Bangla and English digits are really **cousins**!"},{"type":"table","title":{"bn":"তিন চাচাতো ভাই: অঙ্ক মিলিয়ে দেখুন","en":"Three cousins: compare the digits"},"head":[{"bn":"মান","en":"Value"},{"bn":"বাংলা","en":"Bangla"},{"bn":"আরবি অঙ্ক","en":"Arabic digit"},{"bn":"আরবি নাম","en":"Arabic name"}],"rows":[[{"bn":"শূন্য","en":"zero"},"০","٠","صِفْرٌ"],[{"bn":"এক","en":"one"},"১","١","وَاحِدٌ"],[{"bn":"দুই","en":"two"},"২","٢","اِثْنَانِ"],[{"bn":"তিন","en":"three"},"৩","٣","ثَلَاثَةٌ"],[{"bn":"চার","en":"four"},"৪","٤","أَرْبَعَةٌ"],[{"bn":"পাঁচ","en":"five"},"৫","٥","خَمْسَةٌ"],[{"bn":"ছয়","en":"six"},"৬","٦","سِتَّةٌ"],[{"bn":"সাত","en":"seven"},"৭","٧","سَبْعَةٌ"],[{"bn":"আট","en":"eight"},"৮","٨","ثَمَانِيَةٌ"],[{"bn":"নয়","en":"nine"},"৯","٩","تِسْعَةٌ"],[{"bn":"দশ","en":"ten"},"১০","١٠","عَشَرَةٌ"]]},{"type":"tip","kind":"warn","bn":"**ফাঁদ থেকে সাবধান!** আরবি {{٥}} (পাঁচ) দেখতে আমাদের বাংলা শূন্য ০-এর মতো গোল! আর আরবিতে শূন্য হলো ছোট্ট একটি বিন্দু {{٠}}। মনে রাখুন: **আরবিতে গোল = পাঁচ, বিন্দু = শূন্য।** আরও একটি: বাংলা ৪ দেখতে ইংরেজি 8-এর মতো, আর আরবি {{٨}} (আট) দেখতে উল্টো V-এর মতো।","en":"**Watch out for the trap!** The Arabic {{٥}} (five) is round like our Bangla zero ০! And the Arabic zero is just a tiny dot {{٠}}. Remember: **in Arabic, circle = five, dot = zero.** One more: Bangla ৪ looks like English 8, while Arabic {{٨}} (eight) looks like an upside-down V."},{"type":"tip","kind":"memory","bn":"চেহারার মিল খুঁজুন: আরবি {{٩}} আর বাংলা ৯ — দুটোতেই উপরে একটা গোল মাথা। আরবি {{٧}} (সাত) দেখতে V, আর {{٨}} (আট) তার উল্টো — যেন সাত উল্টে আট হয়ে গেল!","en":"Look for family faces: Arabic {{٩}} and Bangla ৯ both have a round head on top. Arabic {{٧}} (seven) looks like a V, and {{٨}} (eight) is its upside-down twin — as if seven flipped over into eight!"},{"type":"tip","kind":"fun","bn":"আরবি লেখা ডান থেকে বামে চলে, কিন্তু **সংখ্যা লেখা হয় বাম থেকে ডানে** — ঠিক বাংলার মতো! তাই {{٢٠٢٥}} মানে ২০২৫।","en":"Arabic text runs right to left, but **numbers are written left to right** — just like Bangla! So {{٢٠٢٥}} means 2025."},{"type":"vocab","title":{"bn":"০ থেকে ১০","en":"0 to 10"},"items":[{"ar":"صِفْرٌ","tr":{"bn":"সিফর","en":"ṣifr"},"mean":{"bn":"শূন্য (০)","en":"zero (0)"}},{"ar":"وَاحِدٌ","tr":{"bn":"ওয়াহিদ","en":"waaḥid"},"mean":{"bn":"এক (১)","en":"one (1)"},"example":{"ar":"وَإِلٰهُكُمْ إِلٰهٌ وَاحِدٌ","mean":{"bn":"আর তোমাদের ইলাহ একজনই ইলাহ","en":"And your god is One God"},"ref":"2:163"}},{"ar":"اِثْنَانِ","tr":{"bn":"ইসনান","en":"ithnaan"},"mean":{"bn":"দুই (২)","en":"two (2)"}},{"ar":"ثَلَاثَةٌ","tr":{"bn":"সালাসাহ","en":"thalaathah"},"mean":{"bn":"তিন (৩)","en":"three (3)"}},{"ar":"أَرْبَعَةٌ","tr":{"bn":"আরবাআহ","en":"arba'ah"},"mean":{"bn":"চার (৪)","en":"four (4)"}},{"ar":"خَمْسَةٌ","tr":{"bn":"খামসাহ","en":"khamsah"},"mean":{"bn":"পাঁচ (৫)","en":"five (5)"}},{"ar":"سِتَّةٌ","tr":{"bn":"সিত্তাহ","en":"sittah"},"mean":{"bn":"ছয় (৬)","en":"six (6)"}},{"ar":"سَبْعَةٌ","tr":{"bn":"সাবআহ","en":"sab'ah"},"mean":{"bn":"সাত (৭)","en":"seven (7)"}},{"ar":"ثَمَانِيَةٌ","tr":{"bn":"সামানিয়াহ","en":"thamaaniyah"},"mean":{"bn":"আট (৮)","en":"eight (8)"}},{"ar":"تِسْعَةٌ","tr":{"bn":"তিসআহ","en":"tis'ah"},"mean":{"bn":"নয় (৯)","en":"nine (9)"}},{"ar":"عَشَرَةٌ","tr":{"bn":"আশারাহ","en":"'asharah"},"mean":{"bn":"দশ (১০)","en":"ten (10)"},"example":{"ar":"تِلْكَ عَشَرَةٌ كَامِلَةٌ","mean":{"bn":"এই হলো পূর্ণ দশ","en":"That is ten complete (days)"},"ref":"2:196"}}]},{"type":"tip","kind":"fun","bn":"“আশারায়ে মুবাশশারা” (জান্নাতের সুসংবাদপ্রাপ্ত দশ সাহাবি) কথাটির “আশারা” মানেই দশ, {{عَشَرَة}}!","en":"The phrase “al-'ashara al-mubashshara” (the ten Companions given glad tidings of Paradise) — that “'ashara” is exactly {{عَشَرَة}}, ten!"},{"type":"table","title":{"bn":"১১ থেকে ২০","en":"11 to 20"},"head":[{"bn":"সংখ্যা","en":"Number"},{"bn":"আরবি","en":"Arabic"},{"bn":"উচ্চারণ","en":"Pronunciation"}],"rows":[["١١","أَحَدَ عَشَرَ",{"bn":"আহাদা আশার","en":"aḥada 'ashar"}],["١٢","اِثْنَا عَشَرَ",{"bn":"ইসনা আশার","en":"ithnaa 'ashar"}],["١٣","ثَلَاثَةَ عَشَرَ",{"bn":"সালাসাতা আশার","en":"thalaathata 'ashar"}],["١٤","أَرْبَعَةَ عَشَرَ",{"bn":"আরবাআতা আশার","en":"arba'ata 'ashar"}],["١٥","خَمْسَةَ عَشَرَ",{"bn":"খামসাতা আশার","en":"khamsata 'ashar"}],["١٦","سِتَّةَ عَشَرَ",{"bn":"সিত্তাতা আশার","en":"sittata 'ashar"}],["١٧","سَبْعَةَ عَشَرَ",{"bn":"সাবআতা আশার","en":"sab'ata 'ashar"}],["١٨","ثَمَانِيَةَ عَشَرَ",{"bn":"সামানিয়াতা আশার","en":"thamaaniyata 'ashar"}],["١٩","تِسْعَةَ عَشَرَ",{"bn":"তিসআতা আশার","en":"tis'ata 'ashar"}],["٢٠","عِشْرُونَ",{"bn":"ইশরূন","en":"'ishroon"}]]},{"type":"tip","kind":"memory","bn":"১৩ থেকে ১৯ বানানো খুব সহজ: **একক + {{عَشَرَ}}**। যেমন {{خَمْسَةَ}} (পাঁচ) + {{عَشَرَ}} (দশ) = পনেরো। শুধু ১১ ({{أَحَدَ عَشَرَ}}) আর ১২ ({{اِثْنَا عَشَرَ}}) একটু আলাদা — এ দুটো মুখস্থ করে নিন।","en":"13 to 19 are easy: **unit + {{عَشَرَ}}**. For example {{خَمْسَةَ}} (five) + {{عَشَرَ}} (ten) = fifteen. Only 11 ({{أَحَدَ عَشَرَ}}) and 12 ({{اِثْنَا عَشَرَ}}) are a little different — just memorise those two."},{"type":"examples","title":{"bn":"কুরআনে সংখ্যা","en":"A number in the Quran"},"items":[{"ar":"إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا","tr":{"bn":"ইন্নী রাআইতু আহাদা আশারা কাওকাবা","en":"innee ra'aytu aḥada 'ashara kawkaban"},"mean":{"bn":"আমি (স্বপ্নে) এগারোটি তারা দেখেছি (১২:৪)","en":"I saw eleven stars (12:4)"},"note":{"bn":"ইউসুফ (আ.)-এর স্বপ্নের কথা — এগারো তারা মানে তাঁর এগারো ভাই।","en":"Prophet Yusuf's dream — the eleven stars were his eleven brothers."},"hl":"أَحَدَ عَشَرَ"}]},{"type":"vocab","title":{"bn":"দশক, শত ও হাজার","en":"Tens, hundred and thousand"},"items":[{"ar":"عِشْرُونَ","tr":{"bn":"ইশরূন","en":"'ishroon"},"mean":{"bn":"বিশ (২০)","en":"twenty (20)"}},{"ar":"ثَلَاثُونَ","tr":{"bn":"সালাসূন","en":"thalaathoon"},"mean":{"bn":"ত্রিশ (৩০)","en":"thirty (30)"}},{"ar":"أَرْبَعُونَ","tr":{"bn":"আরবাঊন","en":"arba'oon"},"mean":{"bn":"চল্লিশ (৪০)","en":"forty (40)"}},{"ar":"خَمْسُونَ","tr":{"bn":"খামসূন","en":"khamsoon"},"mean":{"bn":"পঞ্চাশ (৫০)","en":"fifty (50)"}},{"ar":"سِتُّونَ","tr":{"bn":"সিত্তূন","en":"sittoon"},"mean":{"bn":"ষাট (৬০)","en":"sixty (60)"}},{"ar":"سَبْعُونَ","tr":{"bn":"সাবঊন","en":"sab'oon"},"mean":{"bn":"সত্তর (৭০)","en":"seventy (70)"}},{"ar":"ثَمَانُونَ","tr":{"bn":"সামানূন","en":"thamaanoon"},"mean":{"bn":"আশি (৮০)","en":"eighty (80)"}},{"ar":"تِسْعُونَ","tr":{"bn":"তিসঊন","en":"tis'oon"},"mean":{"bn":"নব্বই (৯০)","en":"ninety (90)"}},{"ar":"مِائَةٌ","tr":{"bn":"মিআহ","en":"miʾah"},"mean":{"bn":"একশো (১০০)","en":"one hundred (100)"}},{"ar":"أَلْفٌ","tr":{"bn":"আলফ","en":"alf"},"mean":{"bn":"এক হাজার (১০০০)","en":"one thousand (1000)"},"example":{"ar":"لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ","mean":{"bn":"কদরের রাত হাজার মাসের চেয়েও উত্তম","en":"The Night of Decree is better than a thousand months"},"ref":"97:3"}}]},{"type":"tip","kind":"memory","bn":"দশকগুলোর ছন্দ শুনুন: সবগুলোর শেষে **“-ঊন”** ({{ـُونَ}})। তিন {{ثَلَاثَة}} ➜ ত্রিশ {{ثَلَاثُونَ}}, চার {{أَرْبَعَة}} ➜ চল্লিশ {{أَرْبَعُونَ}}। শুধু বিশ ({{عِشْرُونَ}}) এসেছে দশ ({{عَشَرَة}}) থেকে।","en":"Hear the rhythm of the tens: they all end in **“-oon”** ({{ـُونَ}}). Three {{ثَلَاثَة}} ➜ thirty {{ثَلَاثُونَ}}, four {{أَرْبَعَة}} ➜ forty {{أَرْبَعُونَ}}. Only twenty ({{عِشْرُونَ}}) comes from ten ({{عَشَرَة}})."},{"type":"tip","kind":"warn","bn":"{{مِائَةٌ}} বানানে একটি {{ا}} আছে, কিন্তু সেটা **পড়া হয় না** — উচ্চারণ “মিআহ”। অনেক জায়গায় {{مِئَةٌ}} লেখা হয়, অর্থ একই।","en":"{{مِائَةٌ}} is spelled with an {{ا}}, but it is **silent** — say “mi'ah”. It is often written {{مِئَةٌ}} too; same meaning."},{"type":"examples","title":{"bn":"বড় সংখ্যা বানাই — একক আগে, দশক পরে","en":"Building bigger numbers — unit first, then the ten"},"items":[{"ar":"وَاحِدٌ وَعِشْرُونَ","tr":{"bn":"ওয়াহিদুন ওয়া ইশরূন","en":"waaḥidun wa 'ishroon"},"mean":{"bn":"একুশ (২১) — এক আর বিশ","en":"twenty-one (21) — one and twenty"},"note":{"bn":"বাংলাতেও “একুশ” মানে এক+বিশ — একক আগে! আরবিও ঠিক তাই করে।","en":"Bangla “ekush” is also ek (one) + bish (twenty) — unit first! Arabic does exactly the same."}},{"ar":"خَمْسَةٌ وَثَلَاثُونَ","tr":{"bn":"খামসাতুন ওয়া সালাসূন","en":"khamsatun wa thalaathoon"},"mean":{"bn":"পঁয়ত্রিশ (৩৫) — পাঁচ আর ত্রিশ","en":"thirty-five (35) — five and thirty"}},{"ar":"تِسْعَةٌ وَتِسْعُونَ","tr":{"bn":"তিসআতুন ওয়া তিসঊন","en":"tis'atun wa tis'oon"},"mean":{"bn":"নিরানব্বই (৯৯)","en":"ninety-nine (99)"},"note":{"bn":"আল্লাহর সুন্দর নামের হাদিসে এই সংখ্যাটি আছে।","en":"This number appears in the hadith about Allah's Beautiful Names."}}]},{"type":"tip","kind":"tip","bn":"আরও একটু এগিয়ে: জিনিস গোনার সময় ৩–১০ সংখ্যাগুলো উল্টো লিঙ্গ নেয় — পুরুষবাচক জিনিসের সাথে {{ة}}-যুক্ত সংখ্যা, স্ত্রীবাচকের সাথে {{ة}} ছাড়া। আপাতত শুধু গোনার রূপগুলো মুখস্থ করুন; এই নিয়ম পরে ব্যাকরণ অংশে আসবে।","en":"A peek ahead: when counting things, numbers 3–10 take the opposite gender — the {{ة}} form goes with masculine nouns, the form without {{ة}} with feminine ones. For now just learn the counting forms; this rule comes later in grammar."},{"type":"practice","bn":"জোরে জোরে গুনুন — প্রথমে ১ থেকে ১০, তারপর দশক।","en":"Count aloud — first 1 to 10, then the tens.","lines":["وَاحِدٌ اِثْنَانِ ثَلَاثَةٌ أَرْبَعَةٌ خَمْسَةٌ","سِتَّةٌ سَبْعَةٌ ثَمَانِيَةٌ تِسْعَةٌ عَشَرَةٌ","عِشْرُونَ ثَلَاثُونَ أَرْبَعُونَ خَمْسُونَ","سِتُّونَ سَبْعُونَ ثَمَانُونَ تِسْعُونَ مِائَةٌ"]},{"type":"quiz","items":[{"q":{"bn":"এই আরবি অঙ্কটি কত?","en":"What value is this Arabic digit?"},"ar":"٥","options":[{"bn":"শূন্য","en":"zero"},{"bn":"পাঁচ","en":"five"},{"bn":"আট","en":"eight"}],"answer":1,"explain":{"bn":"আরবিতে গোল চিহ্ন মানে পাঁচ; শূন্য হলো বিন্দু ٠।","en":"In Arabic a circle means five; zero is the dot ٠."}},{"q":{"bn":"আরবিতে লেখা এই সংখ্যাটি কত?","en":"What number is written here?"},"ar":"٧٨","options":["৮৭","৭৮","৬৯"],"answer":1,"explain":{"bn":"সংখ্যা বাম থেকে ডানে পড়া হয়: ٧ = ৭, ٨ = ৮।","en":"Numbers read left to right: ٧ = 7, ٨ = 8."}},{"q":{"bn":"{{سَبْعَةٌ}} মানে কত?","en":"What is {{سَبْعَةٌ}}?"},"options":["৬","৭","৯"],"answer":1},{"q":{"bn":"“পনেরো (১৫)” আরবিতে কোনটি?","en":"Which is “fifteen (15)”?"},"options":["خَمْسُونَ","خَمْسَةَ عَشَرَ","خَمْسَةٌ"],"answer":1},{"q":{"bn":"{{أَرْبَعُونَ}} কত?","en":"What is {{أَرْبَعُونَ}}?"},"options":["৪","১৪","৪০"],"answer":2},{"q":{"bn":"সূরা কদর অনুযায়ী লাইলাতুল কদর কত মাসের চেয়ে উত্তম?","en":"According to Surah al-Qadr, Laylat al-Qadr is better than how many months?"},"options":["مِائَة","أَلْف","عَشَرَة"],"answer":1},{"q":{"bn":"{{وَاحِدٌ وَعِشْرُونَ}} কোন সংখ্যা?","en":"Which number is {{وَاحِدٌ وَعِشْرُونَ}}?"},"options":["১২","২১","১০১"],"answer":1}]}]},{"id":"daily-family","icon":"أب","title":{"bn":"পরিবার ও মানুষজন","en":"Family & People"},"subtitle":{"bn":"আব্বা-আম্মা থেকে শিক্ষক-বন্ধু — আপন মানুষদের আরবি নাম","en":"From father and mother to teacher and friend — the people in your life"},"minutes":15,"goals":[{"bn":"পরিবারের সদস্যদের আরবি নাম জানা","en":"Name family members in Arabic"},{"bn":"{{ـِي}} যোগ করে “আমার” বলা","en":"Say “my” by adding {{ـِي}}"},{"bn":"{{ة}} দিয়ে পুরুষবাচক থেকে স্ত্রীবাচক বানানো","en":"Make feminine words with {{ة}}"},{"bn":"{{هٰذَا}} / {{هٰذِهِ}} দিয়ে কাউকে পরিচয় করিয়ে দেওয়া","en":"Introduce someone with {{هٰذَا}} / {{هٰذِهِ}}"}],"blocks":[{"type":"text","bn":"আপনার পরিবারের একটা ছবি কল্পনা করুন — আব্বু, আম্মু, ভাই-বোন, দাদা-দাদি, খালা-মামা... এই পাঠ শেষে আপনি ছবির প্রত্যেককে আরবিতে পরিচয় করিয়ে দিতে পারবেন। আর মজার ব্যাপার হলো, কয়েকটা শব্দ আপনি আগে থেকেই জানেন!","en":"Picture a photo of your family — father, mother, brothers and sisters, grandparents, aunts and uncles... By the end of this lesson you will be able to introduce everyone in it in Arabic. And the fun part: you already know a few of these words!"},{"type":"vocab","title":{"bn":"ঘরের মানুষ","en":"Close family"},"items":[{"ar":"أَبٌ","tr":{"bn":"আব","en":"ab"},"mean":{"bn":"বাবা","en":"father"}},{"ar":"أُمٌّ","tr":{"bn":"উম্ম","en":"umm"},"mean":{"bn":"মা","en":"mother"}},{"ar":"الْوَالِدَانِ","tr":{"bn":"আল-ওয়ালিদান","en":"al-waalidaan"},"mean":{"bn":"বাবা-মা (মাতা-পিতা)","en":"parents"},"root":"و ل د","example":{"ar":"وَبِالْوَالِدَيْنِ إِحْسَانًا","mean":{"bn":"এবং মাতা-পিতার সাথে সদ্ব্যবহার করো","en":"And be excellent to parents"},"ref":"17:23"}},{"ar":"أَخٌ","tr":{"bn":"আখ","en":"akh"},"mean":{"bn":"ভাই","en":"brother"}},{"ar":"أُخْتٌ","tr":{"bn":"উখত","en":"ukht"},"mean":{"bn":"বোন","en":"sister"}},{"ar":"اِبْنٌ","tr":{"bn":"ইবন","en":"ibn"},"mean":{"bn":"ছেলে (পুত্র)","en":"son"}},{"ar":"بِنْتٌ","tr":{"bn":"বিনত","en":"bint"},"mean":{"bn":"মেয়ে (কন্যা)","en":"daughter / girl"}},{"ar":"جَدٌّ","tr":{"bn":"জাদ্দ","en":"jadd"},"mean":{"bn":"দাদা / নানা","en":"grandfather"}},{"ar":"جَدَّةٌ","tr":{"bn":"জাদ্দাহ","en":"jaddah"},"mean":{"bn":"দাদি / নানি","en":"grandmother"}},{"ar":"زَوْجٌ","tr":{"bn":"যাওজ","en":"zawj"},"mean":{"bn":"স্বামী","en":"husband"}},{"ar":"زَوْجَةٌ","tr":{"bn":"যাওজাহ","en":"zawjah"},"mean":{"bn":"স্ত্রী","en":"wife"}},{"ar":"أُسْرَةٌ","tr":{"bn":"উসরাহ","en":"usrah"},"mean":{"bn":"পরিবার","en":"family"}}]},{"type":"vocab","title":{"bn":"চাচা-মামা-খালা-ফুফু","en":"Uncles and aunts"},"items":[{"ar":"عَمٌّ","tr":{"bn":"আম্ম","en":"'amm"},"mean":{"bn":"চাচা (বাবার ভাই)","en":"paternal uncle"}},{"ar":"عَمَّةٌ","tr":{"bn":"আম্মাহ","en":"'ammah"},"mean":{"bn":"ফুফু (বাবার বোন)","en":"paternal aunt"}},{"ar":"خَالٌ","tr":{"bn":"খাল","en":"khaal"},"mean":{"bn":"মামা (মায়ের ভাই)","en":"maternal uncle"}},{"ar":"خَالَةٌ","tr":{"bn":"খালাহ","en":"khaalah"},"mean":{"bn":"খালা (মায়ের বোন)","en":"maternal aunt"}}]},{"type":"tip","kind":"memory","bn":"বাংলার **খালা** সরাসরি আরবি {{خَالَةٌ}} থেকে এসেছে — অর্থও একই, মায়ের বোন! কিন্তু সাবধান: আরবিতে {{خَالٌ}} মানে **মামা** (মায়ের ভাই), আমাদের “খালু” নয়। আর {{عَمٌّ}} মানে চাচা।","en":"The Bangla word **khala** comes straight from Arabic {{خَالَةٌ}} — same meaning, mother's sister! But careful: in Arabic {{خَالٌ}} means **mother's brother** (mama), not the Bangla “khalu” (aunt's husband). And {{عَمٌّ}} is father's brother."},{"type":"vocab","title":{"bn":"ঘরের বাইরের মানুষ","en":"People around us"},"items":[{"ar":"رَجُلٌ","tr":{"bn":"রাজুল","en":"rajul"},"mean":{"bn":"পুরুষ, লোক","en":"man"}},{"ar":"اِمْرَأَةٌ","tr":{"bn":"ইমরাআহ","en":"imraʾah"},"mean":{"bn":"নারী, মহিলা","en":"woman"}},{"ar":"وَلَدٌ","tr":{"bn":"ওয়ালাদ","en":"walad"},"mean":{"bn":"ছেলে, সন্তান","en":"boy / child"},"root":"و ل د"},{"ar":"طِفْلٌ","tr":{"bn":"তিফল","en":"ṭifl"},"mean":{"bn":"শিশু","en":"baby / small child"}},{"ar":"صَدِيقٌ","tr":{"bn":"সাদীক","en":"ṣadeeq"},"mean":{"bn":"বন্ধু","en":"friend"},"root":"ص د ق"},{"ar":"جَارٌ","tr":{"bn":"জার","en":"jaar"},"mean":{"bn":"প্রতিবেশী","en":"neighbour"}},{"ar":"مُعَلِّمٌ","tr":{"bn":"মুআল্লিম","en":"mu'allim"},"mean":{"bn":"শিক্ষক","en":"teacher"},"root":"ع ل م"},{"ar":"طَالِبٌ","tr":{"bn":"তালিব","en":"ṭaalib"},"mean":{"bn":"ছাত্র","en":"student"},"root":"ط ل ب"}]},{"type":"tip","kind":"fun","bn":"“তালিবে ইলম” (জ্ঞান-অন্বেষী ছাত্র), “আওলাদ” (সন্তানসন্ততি), “মুআল্লিম” — এগুলো বাংলায় চলে আসা আরবি শব্দ। {{أَوْلَادٌ}} হলো {{وَلَدٌ}}-এর বহুবচন। আর “সিদ্দিক” নামটি এসেছে {{صَدِيقٌ}}-এর একই মূল {{ص د ق}} (সত্য) থেকে — সত্যিকারের বন্ধুই তো সত্যবাদী!","en":"“Talib-e-ilm” (student of knowledge), “awlad” (children), “muallim” — these are Arabic words living in Bangla. {{أَوْلَادٌ}} is the plural of {{وَلَدٌ}}. And the name “Siddiq” shares the root {{ص د ق}} (truth) with {{صَدِيقٌ}} — a true friend is a truthful one!"},{"type":"table","title":{"bn":"{{ة}} লাগিয়ে স্ত্রীবাচক","en":"Add {{ة}} for the feminine"},"head":[{"bn":"পুরুষ","en":"Male"},{"bn":"নারী","en":"Female"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["جَدٌّ","جَدَّةٌ",{"bn":"দাদা ➜ দাদি","en":"grandfather ➜ grandmother"}],["خَالٌ","خَالَةٌ",{"bn":"মামা ➜ খালা","en":"maternal uncle ➜ maternal aunt"}],["مُعَلِّمٌ","مُعَلِّمَةٌ",{"bn":"শিক্ষক ➜ শিক্ষিকা","en":"teacher (m) ➜ teacher (f)"}],["طَالِبٌ","طَالِبَةٌ",{"bn":"ছাত্র ➜ ছাত্রী","en":"student (m) ➜ student (f)"}],["صَدِيقٌ","صَدِيقَةٌ",{"bn":"বন্ধু (ছেলে) ➜ বান্ধবী","en":"friend (m) ➜ friend (f)"}]]},{"type":"tip","kind":"memory","bn":"“আমার” বলতে শব্দের শেষে শুধু {{ـِي}} (ঈ) লাগান: {{أَبٌ}} ➜ {{أَبِي}} (আমার বাবা), {{أُمٌّ}} ➜ {{أُمِّي}} (আমার মা), {{أَخٌ}} ➜ {{أَخِي}} (আমার ভাই)। {{ة}}-ওয়ালা শব্দে {{ة}} হয়ে যায় {{ت}}: {{جَدَّةٌ}} ➜ {{جَدَّتِي}}।","en":"To say “my”, just add {{ـِي}} (ee) at the end: {{أَبٌ}} ➜ {{أَبِي}} (my father), {{أُمٌّ}} ➜ {{أُمِّي}} (my mother), {{أَخٌ}} ➜ {{أَخِي}} (my brother). Words with {{ة}} turn it into {{ت}}: {{جَدَّةٌ}} ➜ {{جَدَّتِي}}."},{"type":"examples","title":{"bn":"পরিবারের ছবি দেখাই","en":"Showing a family photo"},"items":[{"ar":"هٰذَا أَبِي","tr":{"bn":"হাযা আবী","en":"haadhaa abee"},"mean":{"bn":"ইনি আমার বাবা","en":"This is my father"},"note":{"bn":"পুরুষের জন্য {{هٰذَا}}।","en":"{{هٰذَا}} for a male."},"hl":"هٰذَا"},{"ar":"هٰذِهِ أُمِّي","tr":{"bn":"হাযিহী উম্মী","en":"haadhihee ummee"},"mean":{"bn":"ইনি আমার মা","en":"This is my mother"},"note":{"bn":"নারীর জন্য {{هٰذِهِ}}।","en":"{{هٰذِهِ}} for a female."},"hl":"هٰذِهِ"},{"ar":"هٰذَا أَخِي الصَّغِيرُ","tr":{"bn":"হাযা আখিয়াস সাগীর","en":"haadhaa akhiyaṣ-ṣagheer"},"mean":{"bn":"এ আমার ছোট ভাই","en":"This is my little brother"},"hl":"أَخِي"},{"ar":"هٰذِهِ جَدَّتِي","tr":{"bn":"হাযিহী জাদ্দাতী","en":"haadhihee jaddatee"},"mean":{"bn":"ইনি আমার দাদি","en":"This is my grandmother"},"hl":"جَدَّتِي"},{"ar":"هُوَ مُعَلِّمِي","tr":{"bn":"হুয়া মুআল্লিমী","en":"huwa mu'allimee"},"mean":{"bn":"তিনি আমার শিক্ষক","en":"He is my teacher"},"hl":"مُعَلِّمِي"},{"ar":"هِيَ صَدِيقَتِي","tr":{"bn":"হিয়া সাদীকাতী","en":"hiya ṣadeeqatee"},"mean":{"bn":"সে আমার বান্ধবী","en":"She is my friend"},"hl":"صَدِيقَتِي"}]},{"type":"examples","title":{"bn":"বাবা-মায়ের জন্য কুরআনের দোয়া","en":"A Quranic dua for parents"},"items":[{"ar":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","tr":{"bn":"রাব্বির হামহুমা কামা রাব্বাইয়ানী সাগীরা","en":"rabbir-ḥamhumaa kamaa rabbayaanee ṣagheeraa"},"mean":{"bn":"হে আমার রব, তাঁদের প্রতি দয়া করুন, যেমন তাঁরা আমাকে ছোটবেলায় লালন-পালন করেছেন (১৭:২৪)","en":"My Lord, have mercy on them as they raised me when I was small (17:24)"},"note":{"bn":"প্রতিদিন নামাজের পর পড়ার মতো সুন্দর দোয়া।","en":"A beautiful dua to say after every prayer."}}]},{"type":"quiz","items":[{"q":{"bn":"{{أُخْتٌ}} মানে কী?","en":"What does {{أُخْتٌ}} mean?"},"options":[{"bn":"ভাই","en":"brother"},{"bn":"বোন","en":"sister"},{"bn":"মা","en":"mother"}],"answer":1},{"q":{"bn":"মায়ের বোন (খালা) আরবিতে কী?","en":"Mother's sister in Arabic is:"},"options":["عَمَّةٌ","خَالَةٌ","جَدَّةٌ"],"answer":1},{"q":{"bn":"“আমার মা” কোনটি?","en":"Which means “my mother”?"},"options":["أُمٌّ","أُمِّي","أَبِي"],"answer":1},{"q":{"bn":"{{مُعَلِّمٌ}}-এর স্ত্রীবাচক রূপ কোনটি?","en":"The feminine of {{مُعَلِّمٌ}} is:"},"options":["مُعَلِّمِي","مُعَلِّمَةٌ","مُعَلِّمُونَ"],"answer":1},{"q":{"bn":"আপনার দাদিকে দেখিয়ে কী বলবেন?","en":"Pointing to your grandmother, you say:"},"options":["هٰذَا جَدِّي","هٰذِهِ جَدَّتِي","هٰذَا أَخِي"],"answer":1},{"q":{"bn":"{{صَدِيقٌ}} মানে কী?","en":"What is {{صَدِيقٌ}}?"},"options":[{"bn":"প্রতিবেশী","en":"neighbour"},{"bn":"বন্ধু","en":"friend"},{"bn":"শিক্ষক","en":"teacher"}],"answer":1},{"q":{"bn":"{{الْوَالِدَانِ}} বলতে কাদের বোঝায়?","en":"Who are {{الْوَالِدَانِ}}?"},"options":[{"bn":"দুই ভাই","en":"two brothers"},{"bn":"বাবা-মা","en":"parents"},{"bn":"দাদা-দাদি","en":"grandparents"}],"answer":1}]}]},{"id":"daily-body","icon":"يد","title":{"bn":"আমার শরীর ও স্বাস্থ্য","en":"My Body & Health"},"subtitle":{"bn":"মাথা থেকে পা — আর অসুস্থ হলে কী বলবেন","en":"Head to toe — and what to say when you feel unwell"},"minutes":15,"goals":[{"bn":"শরীরের প্রধান অঙ্গের আরবি নাম","en":"Name the main parts of the body"},{"bn":"অজুর অঙ্গগুলো আরবিতে চেনা","en":"Recognise the parts of wudu in Arabic"},{"bn":"{{ـَانِ}} দিয়ে “দুটি” বলা","en":"Say “two of” with {{ـَانِ}}"},{"bn":"অসুস্থতা ও রোগী দেখার বাক্য","en":"Phrases for illness and visiting the sick"}],"blocks":[{"type":"text","bn":"চলুন একটা খেলা খেলি: প্রতিটি নতুন শব্দ শেখার সময় সেই অঙ্গটি **ছুঁয়ে** জোরে বলুন। মাথা ছুঁয়ে {{رَأْسٌ}}, চোখ ছুঁয়ে {{عَيْنٌ}}... শরীর নড়লে মগজও মনে রাখে!","en":"Let's play a game: as you learn each new word, **touch** that part of your body and say it aloud. Touch your head — {{رَأْسٌ}}, your eye — {{عَيْنٌ}}... When the body moves, the brain remembers!"},{"type":"vocab","title":{"bn":"মাথা ও মুখ","en":"Head and face"},"items":[{"ar":"رَأْسٌ","tr":{"bn":"রা'স","en":"raʾs"},"mean":{"bn":"মাথা","en":"head"}},{"ar":"وَجْهٌ","tr":{"bn":"ওয়াজহ","en":"wajh"},"mean":{"bn":"মুখমণ্ডল, চেহারা","en":"face"}},{"ar":"شَعْرٌ","tr":{"bn":"শা'র","en":"sha'r"},"mean":{"bn":"চুল","en":"hair"}},{"ar":"عَيْنٌ","tr":{"bn":"আইন","en":"'ayn"},"mean":{"bn":"চোখ","en":"eye"}},{"ar":"أُذُنٌ","tr":{"bn":"উযুন","en":"udhun"},"mean":{"bn":"কান","en":"ear"}},{"ar":"أَنْفٌ","tr":{"bn":"আনফ","en":"anf"},"mean":{"bn":"নাক","en":"nose"}},{"ar":"فَمٌ","tr":{"bn":"ফাম","en":"fam"},"mean":{"bn":"মুখ (হাঁ)","en":"mouth"}},{"ar":"لِسَانٌ","tr":{"bn":"লিসান","en":"lisaan"},"mean":{"bn":"জিহ্বা; ভাষা","en":"tongue; language"}},{"ar":"سِنٌّ","tr":{"bn":"সিন্ন","en":"sinn"},"mean":{"bn":"দাঁত","en":"tooth"}}]},{"type":"tip","kind":"fun","bn":"{{عَيْنٌ}} (চোখ) আর আরবি বর্ণ {{ع}}-এর নাম একই — “আইন”! আর {{لِسَانٌ}} মানে জিহ্বা ও ভাষা দুটোই — কুরআন নাজিল হয়েছে {{بِلِسَانٍ عَرَبِيٍّ مُبِينٍ}} — স্পষ্ট আরবি ভাষায় (২৬:১৯৫)।","en":"{{عَيْنٌ}} (eye) has the same name as the letter {{ع}} — “'ayn”! And {{لِسَانٌ}} means both tongue and language — the Quran was revealed {{بِلِسَانٍ عَرَبِيٍّ مُبِينٍ}} — in a clear Arabic tongue (26:195)."},{"type":"vocab","title":{"bn":"শরীরের বাকি অংশ","en":"The rest of the body"},"items":[{"ar":"يَدٌ","tr":{"bn":"ইয়াদ","en":"yad"},"mean":{"bn":"হাত","en":"hand"}},{"ar":"إِصْبَعٌ","tr":{"bn":"ইসবা'","en":"iṣba'"},"mean":{"bn":"আঙুল","en":"finger"}},{"ar":"رِجْلٌ","tr":{"bn":"রিজল","en":"rijl"},"mean":{"bn":"পা","en":"leg / foot"}},{"ar":"صَدْرٌ","tr":{"bn":"সাদর","en":"ṣadr"},"mean":{"bn":"বুক","en":"chest"}},{"ar":"قَلْبٌ","tr":{"bn":"কালব","en":"qalb"},"mean":{"bn":"হৃদয়, অন্তর","en":"heart"}},{"ar":"بَطْنٌ","tr":{"bn":"বাতন","en":"baṭn"},"mean":{"bn":"পেট","en":"stomach, belly"}},{"ar":"ظَهْرٌ","tr":{"bn":"যাহর","en":"ẓahr"},"mean":{"bn":"পিঠ","en":"back"}}]},{"type":"tip","kind":"memory","bn":"“কলব” শব্দটি আমরা ওয়াজে-দোয়ায় প্রায়ই শুনি — “কলব পরিষ্কার করো”। এটাই আরবি {{قَلْبٌ}} (হৃদয়)! আর {{ظَهْرٌ}} (পিঠ) এবং যোহরের নামাজ {{الظُّهْرُ}} — দুটোর মূল অক্ষর একই {{ظ ه ر}}; শুধু হরকত আলাদা!","en":"We often hear “qalb” in talks and duas — “purify your qalb”. That is Arabic {{قَلْبٌ}} (heart)! And {{ظَهْرٌ}} (back) and the Zuhr prayer {{الظُّهْرُ}} share the same root letters {{ظ ه ر}} — only the vowels differ!"},{"type":"table","title":{"bn":"অজুর অঙ্গগুলো আরবিতে","en":"The parts of wudu in Arabic"},"head":[{"bn":"কাজ","en":"Action"},{"bn":"অঙ্গ","en":"Body part"},{"bn":"অর্থ","en":"Meaning"}],"rows":[[{"bn":"তিনবার ধোয়া","en":"wash three times"},"الْيَدَانِ",{"bn":"দুই হাত (কবজি পর্যন্ত)","en":"both hands (to the wrists)"}],[{"bn":"কুলি করা","en":"rinse"},"الْفَمُ",{"bn":"মুখ","en":"mouth"}],[{"bn":"পানি দিয়ে পরিষ্কার","en":"clean with water"},"الْأَنْفُ",{"bn":"নাক","en":"nose"}],[{"bn":"ধোয়া","en":"wash"},"الْوَجْهُ",{"bn":"মুখমণ্ডল","en":"face"}],[{"bn":"কনুই পর্যন্ত ধোয়া","en":"wash to the elbows"},"الْيَدَانِ",{"bn":"দুই হাত","en":"both arms"}],[{"bn":"মাসেহ করা","en":"wipe"},"الرَّأْسُ وَالْأُذُنَانِ",{"bn":"মাথা ও দুই কান","en":"head and both ears"}],[{"bn":"টাখনু পর্যন্ত ধোয়া","en":"wash to the ankles"},"الرِّجْلَانِ",{"bn":"দুই পা","en":"both feet"}]]},{"type":"tip","kind":"memory","bn":"আমাদের অনেক অঙ্গ **জোড়ায় জোড়ায়**! আরবিতে “দুটি” বলতে শেষে {{ـَانِ}} (আন) লাগান: {{عَيْنٌ}} ➜ {{عَيْنَانِ}} (দুই চোখ), {{يَدٌ}} ➜ {{يَدَانِ}} (দুই হাত), {{أُذُنٌ}} ➜ {{أُذُنَانِ}} (দুই কান), {{رِجْلٌ}} ➜ {{رِجْلَانِ}} (দুই পা)।","en":"Many body parts come **in pairs**! To say “two” in Arabic, add {{ـَانِ}} (aan): {{عَيْنٌ}} ➜ {{عَيْنَانِ}} (two eyes), {{يَدٌ}} ➜ {{يَدَانِ}} (two hands), {{أُذُنٌ}} ➜ {{أُذُنَانِ}} (two ears), {{رِجْلٌ}} ➜ {{رِجْلَانِ}} (two feet)."},{"type":"vocab","title":{"bn":"স্বাস্থ্য ও অসুখ","en":"Health and illness"},"items":[{"ar":"صِحَّةٌ","tr":{"bn":"সিহ্‌হাহ","en":"ṣiḥḥah"},"mean":{"bn":"স্বাস্থ্য, সুস্থতা","en":"health"}},{"ar":"مَرِيضٌ","tr":{"bn":"মারীদ","en":"mareeḍ"},"mean":{"bn":"অসুস্থ, রোগী","en":"sick, patient"}},{"ar":"أَلَمٌ","tr":{"bn":"আলাম","en":"alam"},"mean":{"bn":"ব্যথা","en":"pain"}},{"ar":"صُدَاعٌ","tr":{"bn":"সুদা'","en":"ṣudaa'"},"mean":{"bn":"মাথাব্যথা","en":"headache"}},{"ar":"طَبِيبٌ","tr":{"bn":"তাবীব","en":"ṭabeeb"},"mean":{"bn":"ডাক্তার","en":"doctor"}},{"ar":"دَوَاءٌ","tr":{"bn":"দাওয়া","en":"dawaaʾ"},"mean":{"bn":"ওষুধ","en":"medicine"}},{"ar":"مُسْتَشْفًى","tr":{"bn":"মুসতাশফা","en":"mustashfaa"},"mean":{"bn":"হাসপাতাল","en":"hospital"},"root":"ش ف ي"}]},{"type":"tip","kind":"fun","bn":"বাংলার “দাওয়াই” (ওষুধ) এসেছে আরবি {{دَوَاءٌ}} থেকে, আর হাসপাতালের নামে যে “শেফা” দেখেন, সেটি আরবি {{شِفَاءٌ}} (আরোগ্য)। {{مُسْتَشْفًى}} (হাসপাতাল) মানে “আরোগ্য খোঁজার জায়গা” — একই মূল {{ش ف ي}}!","en":"The Bangla “dawai” (medicine) comes from Arabic {{دَوَاءٌ}}, and the “Shefa” you see on hospital signs is Arabic {{شِفَاءٌ}} (healing). {{مُسْتَشْفًى}} (hospital) literally means “the place where healing is sought” — same root {{ش ف ي}}!"},{"type":"examples","title":{"bn":"অসুস্থ হলে যা বলবেন","en":"What to say when unwell"},"items":[{"ar":"أَنَا مَرِيضٌ","tr":{"bn":"আনা মারীদ","en":"ana mareeḍ"},"mean":{"bn":"আমি অসুস্থ","en":"I am sick"},"note":{"bn":"মেয়ে বললে: {{أَنَا مَرِيضَةٌ}}","en":"A girl says: {{أَنَا مَرِيضَةٌ}}"}},{"ar":"رَأْسِي يُؤْلِمُنِي","tr":{"bn":"রা'সী ইউ'লিমুনী","en":"raʾsee yuʾlimunee"},"mean":{"bn":"আমার মাথা ব্যথা করছে","en":"My head hurts"},"hl":"رَأْسِي"},{"ar":"بَطْنِي يُؤْلِمُنِي","tr":{"bn":"বাতনী ইউ'লিমুনী","en":"baṭnee yuʾlimunee"},"mean":{"bn":"আমার পেট ব্যথা করছে","en":"My stomach hurts"},"hl":"بَطْنِي"},{"ar":"أُرِيدُ طَبِيبًا","tr":{"bn":"উরীদু তাবীবান","en":"ureedu ṭabeeban"},"mean":{"bn":"আমার একজন ডাক্তার দরকার","en":"I need a doctor"}},{"ar":"شَفَاكَ اللّٰهُ","tr":{"bn":"শাফাকাল্লাহ","en":"shafaakallaah"},"mean":{"bn":"আল্লাহ আপনাকে সুস্থ করে দিন","en":"May Allah heal you"},"note":{"bn":"অসুস্থ কাউকে দেখলে বলুন।","en":"Say this to someone who is ill."}},{"ar":"لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللّٰهُ","tr":{"bn":"লা বা'সা, তাহূরুন ইন শা আল্লাহ","en":"laa baʾsa, ṭahoorun in shaaʾallaah"},"mean":{"bn":"চিন্তা নেই, এটা (গুনাহ থেকে) পবিত্রকারী, ইন শা আল্লাহ","en":"No harm — it is a purification (from sins), if Allah wills"},"note":{"bn":"রোগী দেখতে গিয়ে নবী ﷺ এ কথা বলতেন (সহিহ বুখারি)।","en":"The Prophet ﷺ said this when visiting the sick (Sahih al-Bukhari)."}}]},{"type":"quiz","items":[{"q":{"bn":"{{عَيْنٌ}} মানে কী?","en":"What does {{عَيْنٌ}} mean?"},"options":[{"bn":"কান","en":"ear"},{"bn":"চোখ","en":"eye"},{"bn":"নাক","en":"nose"}],"answer":1},{"q":{"bn":"“হাত” আরবিতে কী?","en":"What is “hand” in Arabic?"},"options":["رِجْلٌ","يَدٌ","فَمٌ"],"answer":1},{"q":{"bn":"অজুতে কোন অঙ্গ মাসেহ করা হয়?","en":"Which part is wiped in wudu?"},"options":["الرَّأْسُ","الْوَجْهُ","الْبَطْنُ"],"answer":0},{"q":{"bn":"“দুই চোখ” কোনটি?","en":"Which means “two eyes”?"},"options":["عَيْنٌ","عَيْنِي","عَيْنَانِ"],"answer":2},{"q":{"bn":"{{قَلْبٌ}} মানে কী?","en":"What is {{قَلْبٌ}}?"},"options":[{"bn":"হৃদয়","en":"heart"},{"bn":"পিঠ","en":"back"},{"bn":"বুক","en":"chest"}],"answer":0},{"q":{"bn":"অসুস্থ বন্ধুকে দেখতে গিয়ে কোন দোয়া করবেন?","en":"Visiting a sick friend, which dua do you make?"},"options":["شَفَاكَ اللّٰهُ","صَبَاحُ النُّورِ","تَشَرَّفْنَا"],"answer":0},{"q":{"bn":"{{طَبِيبٌ}} কে?","en":"Who is a {{طَبِيبٌ}}?"},"options":[{"bn":"শিক্ষক","en":"teacher"},{"bn":"ডাক্তার","en":"doctor"},{"bn":"ছাত্র","en":"student"}],"answer":1}]}]},{"id":"daily-home","icon":"بيت","title":{"bn":"ঘর, মাদ্রাসা ও জিনিসপত্র","en":"Home, School & Things"},"subtitle":{"bn":"কিতাব-কলম থেকে মসজিদ-গাড়ি — চারপাশের জিনিসের নাম","en":"From book and pen to masjid and car — naming the world around you"},"minutes":15,"goals":[{"bn":"ঘর ও ক্লাসের জিনিসপত্রের নাম","en":"Name things at home and in class"},{"bn":"{{مَـ}} দিয়ে শুরু হওয়া “জায়গা”-বাচক শব্দ চেনা","en":"Spot “place” words that start with {{مَـ}}"},{"bn":"{{فِي}}, {{عَلَى}}, {{تَحْتَ}} দিয়ে কোথায় আছে বলা","en":"Say where things are with {{فِي}}, {{عَلَى}}, {{تَحْتَ}}"}],"blocks":[{"type":"text","bn":"আপনার ব্যাগ খুলুন — {{كِتَابٌ}}, {{قَلَمٌ}}, {{دَفْتَرٌ}}... আরে, এ তো আমাদের কিতাব, কলম আর দফতর! এই পাঠে আপনি দেখবেন, বাংলায় কত আরবি শব্দ লুকিয়ে আছে।","en":"Open your bag — {{كِتَابٌ}}, {{قَلَمٌ}}, {{دَفْتَرٌ}}... hey, those are our Bangla kitab, kolom and doftor! In this lesson you'll discover how much Arabic hides inside Bangla."},{"type":"vocab","title":{"bn":"ঘরের ভেতর","en":"Inside the home"},"items":[{"ar":"بَيْتٌ","tr":{"bn":"বাইত","en":"bayt"},"mean":{"bn":"ঘর, বাড়ি","en":"house, home"}},{"ar":"بَابٌ","tr":{"bn":"বাব","en":"baab"},"mean":{"bn":"দরজা","en":"door"}},{"ar":"نَافِذَةٌ","tr":{"bn":"নাফিযাহ","en":"naafidhah"},"mean":{"bn":"জানালা","en":"window"}},{"ar":"غُرْفَةٌ","tr":{"bn":"গুরফাহ","en":"ghurfah"},"mean":{"bn":"কক্ষ, রুম","en":"room"}},{"ar":"مَطْبَخٌ","tr":{"bn":"মাতবাখ","en":"maṭbakh"},"mean":{"bn":"রান্নাঘর","en":"kitchen"}},{"ar":"سَرِيرٌ","tr":{"bn":"সারীর","en":"sareer"},"mean":{"bn":"খাট, বিছানা","en":"bed"}},{"ar":"كُرْسِيٌّ","tr":{"bn":"কুরসিয়্য","en":"kursiyy"},"mean":{"bn":"চেয়ার","en":"chair"}},{"ar":"مِفْتَاحٌ","tr":{"bn":"মিফতাহ","en":"miftaaḥ"},"mean":{"bn":"চাবি","en":"key"},"root":"ف ت ح"},{"ar":"مِصْبَاحٌ","tr":{"bn":"মিসবাহ","en":"miṣbaaḥ"},"mean":{"bn":"বাতি","en":"lamp"}},{"ar":"سَاعَةٌ","tr":{"bn":"সা'আহ","en":"saa'ah"},"mean":{"bn":"ঘড়ি; ঘণ্টা","en":"clock, watch; hour"}},{"ar":"هَاتِفٌ","tr":{"bn":"হাতিফ","en":"haatif"},"mean":{"bn":"ফোন","en":"phone"}}]},{"type":"tip","kind":"fun","bn":"“আয়াতুল কুরসি” শুনেছেন তো? {{كُرْسِيٌّ}} মানে আসন বা চেয়ার! বাংলাতেও “কুরসি” মানে চেয়ার। আর {{مِفْتَاحٌ}} (চাবি) এসেছে {{فَتَحَ}} (খোলা) থেকে — সূরা ফাতিহাও “খোলার” সূরা, অর্থাৎ কুরআনের শুরু।","en":"Heard of “Ayat al-Kursi”? {{كُرْسِيٌّ}} means seat or chair! In Bangla too, “kursi” means chair. And {{مِفْتَاحٌ}} (key) comes from {{فَتَحَ}} (to open) — Surah al-Fatihah is “the Opener” of the Quran."},{"type":"vocab","title":{"bn":"পড়ার জিনিস","en":"Study things"},"items":[{"ar":"كِتَابٌ","tr":{"bn":"কিতাব","en":"kitaab"},"mean":{"bn":"বই","en":"book"},"root":"ك ت ب"},{"ar":"قَلَمٌ","tr":{"bn":"কালাম","en":"qalam"},"mean":{"bn":"কলম","en":"pen"},"example":{"ar":"الَّذِي عَلَّمَ بِالْقَلَمِ","mean":{"bn":"যিনি কলমের সাহায্যে শিক্ষা দিয়েছেন","en":"Who taught by the pen"},"ref":"96:4"}},{"ar":"دَفْتَرٌ","tr":{"bn":"দাফতার","en":"daftar"},"mean":{"bn":"খাতা","en":"notebook"}},{"ar":"حَقِيبَةٌ","tr":{"bn":"হাকীবাহ","en":"ḥaqeebah"},"mean":{"bn":"ব্যাগ","en":"bag"}},{"ar":"مَكْتَبٌ","tr":{"bn":"মাকতাব","en":"maktab"},"mean":{"bn":"টেবিল; অফিস","en":"desk; office"},"root":"ك ت ب"},{"ar":"سَبُّورَةٌ","tr":{"bn":"সাব্বূরাহ","en":"sabboorah"},"mean":{"bn":"ব্ল্যাকবোর্ড","en":"blackboard"}},{"ar":"مُصْحَفٌ","tr":{"bn":"মুসহাফ","en":"muṣḥaf"},"mean":{"bn":"কুরআনের কপি (মুসহাফ)","en":"a copy of the Quran"}}]},{"type":"tip","kind":"warn","bn":"বাংলায় “দফতর” মানে অফিস, কিন্তু আরবিতে {{دَفْتَرٌ}} মানে **খাতা**। আর আরবিতে অফিস হলো {{مَكْتَبٌ}} — যেখান থেকে আমাদের “মক্তব” শব্দটি এসেছে!","en":"In Bangla “doftor” means office, but Arabic {{دَفْتَرٌ}} means **notebook**. Office in Arabic is {{مَكْتَبٌ}} — which gave Bangla the word “moktob” (children's Quran school)!"},{"type":"vocab","title":{"bn":"বাইরের জায়গা","en":"Places outside"},"items":[{"ar":"مَسْجِدٌ","tr":{"bn":"মাসজিদ","en":"masjid"},"mean":{"bn":"মসজিদ","en":"mosque"},"root":"س ج د"},{"ar":"مَدْرَسَةٌ","tr":{"bn":"মাদরাসাহ","en":"madrasah"},"mean":{"bn":"স্কুল, মাদ্রাসা","en":"school"},"root":"د ر س"},{"ar":"مَكْتَبَةٌ","tr":{"bn":"মাকতাবাহ","en":"maktabah"},"mean":{"bn":"লাইব্রেরি; বইয়ের দোকান","en":"library; bookshop"},"root":"ك ت ب"},{"ar":"سُوقٌ","tr":{"bn":"সূক","en":"sooq"},"mean":{"bn":"বাজার","en":"market"}},{"ar":"شَارِعٌ","tr":{"bn":"শারি'","en":"shaari'"},"mean":{"bn":"রাস্তা","en":"street"}},{"ar":"سَيَّارَةٌ","tr":{"bn":"সাইয়ারাহ","en":"sayyaarah"},"mean":{"bn":"গাড়ি","en":"car"}}]},{"type":"table","title":{"bn":"{{مَـ}} = জায়গা: একটা গোপন সূত্র","en":"{{مَـ}} = place: a secret formula"},"head":[{"bn":"মূল কাজ","en":"Root action"},{"bn":"জায়গা","en":"Place"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["سَجَدَ","مَسْجِدٌ",{"bn":"সিজদা করল ➜ সিজদার জায়গা","en":"prostrated ➜ place of prostration"}],["دَرَسَ","مَدْرَسَةٌ",{"bn":"পড়াশোনা করল ➜ পড়ার জায়গা","en":"studied ➜ place of study"}],["كَتَبَ","مَكْتَبٌ",{"bn":"লিখল ➜ লেখার জায়গা","en":"wrote ➜ place of writing"}],["طَبَخَ","مَطْبَخٌ",{"bn":"রান্না করল ➜ রান্নার জায়গা","en":"cooked ➜ place of cooking"}]]},{"type":"tip","kind":"memory","bn":"একটি মূল থেকে কত শব্দ! {{ك ت ب}} (লেখা) ➜ {{كِتَابٌ}} বই, {{كَاتِبٌ}} লেখক, {{مَكْتَبٌ}} টেবিল/অফিস, {{مَكْتَبَةٌ}} লাইব্রেরি। মূল চিনলে একটা শব্দ শিখে চারটে পাবেন!","en":"So many words from one root! {{ك ت ب}} (writing) ➜ {{كِتَابٌ}} book, {{كَاتِبٌ}} writer, {{مَكْتَبٌ}} desk/office, {{مَكْتَبَةٌ}} library. Know the root — learn one word, get four!"},{"type":"compare","title":{"bn":"এটা কোথায়?","en":"Where is it?"},"items":[{"ar":"فِي","label":{"bn":"ফী — ভেতরে","en":"fee — in"},"desc":{"bn":"{{الْقَلَمُ فِي الْحَقِيبَةِ}} — কলম ব্যাগের ভেতরে","en":"{{الْقَلَمُ فِي الْحَقِيبَةِ}} — the pen is in the bag"}},{"ar":"عَلَى","label":{"bn":"আলা — উপরে","en":"'alaa — on"},"desc":{"bn":"{{الْكِتَابُ عَلَى الْمَكْتَبِ}} — বই টেবিলের উপরে","en":"{{الْكِتَابُ عَلَى الْمَكْتَبِ}} — the book is on the desk"}},{"ar":"تَحْتَ","label":{"bn":"তাহতা — নিচে","en":"taḥta — under"},"desc":{"bn":"{{الْحَقِيبَةُ تَحْتَ الْكُرْسِيِّ}} — ব্যাগ চেয়ারের নিচে","en":"{{الْحَقِيبَةُ تَحْتَ الْكُرْسِيِّ}} — the bag is under the chair"}}]},{"type":"examples","title":{"bn":"ছোট বাক্য","en":"Short sentences"},"items":[{"ar":"هٰذَا كِتَابٌ","tr":{"bn":"হাযা কিতাব","en":"haadhaa kitaab"},"mean":{"bn":"এটি একটি বই","en":"This is a book"},"hl":"هٰذَا"},{"ar":"هٰذِهِ سَيَّارَةٌ","tr":{"bn":"হাযিহী সাইয়ারাহ","en":"haadhihee sayyaarah"},"mean":{"bn":"এটি একটি গাড়ি","en":"This is a car"},"note":{"bn":"{{ة}}-ওয়ালা শব্দের জন্য {{هٰذِهِ}}।","en":"{{هٰذِهِ}} for a word ending in {{ة}}."},"hl":"هٰذِهِ"},{"ar":"أَيْنَ الْمَسْجِدُ؟","tr":{"bn":"আইনাল মাসজিদ?","en":"aynal-masjid?"},"mean":{"bn":"মসজিদ কোথায়?","en":"Where is the masjid?"},"hl":"أَيْنَ"},{"ar":"الْمَسْجِدُ قَرِيبٌ","tr":{"bn":"আল-মাসজিদু কারীব","en":"al-masjidu qareeb"},"mean":{"bn":"মসজিদ কাছেই","en":"The masjid is near"}},{"ar":"هٰذَا بَيْتِي","tr":{"bn":"হাযা বাইতী","en":"haadhaa baytee"},"mean":{"bn":"এটা আমার বাড়ি","en":"This is my house"},"hl":"بَيْتِي"}]},{"type":"quiz","items":[{"q":{"bn":"{{قَلَمٌ}} মানে কী?","en":"What is {{قَلَمٌ}}?"},"options":[{"bn":"বই","en":"book"},{"bn":"কলম","en":"pen"},{"bn":"ব্যাগ","en":"bag"}],"answer":1},{"q":{"bn":"আরবিতে {{دَفْتَرٌ}} মানে কী?","en":"In Arabic, {{دَفْتَرٌ}} means:"},"options":[{"bn":"অফিস","en":"office"},{"bn":"খাতা","en":"notebook"},{"bn":"দরজা","en":"door"}],"answer":1},{"q":{"bn":"“রান্নাঘর” কোনটি?","en":"Which is “kitchen”?"},"options":["مَطْبَخٌ","مَكْتَبٌ","مَسْجِدٌ"],"answer":0},{"q":{"bn":"{{مَسْجِدٌ}} শব্দটি কোন কাজ থেকে এসেছে?","en":"{{مَسْجِدٌ}} comes from which action?"},"options":[{"bn":"লেখা","en":"writing"},{"bn":"সিজদা করা","en":"prostrating"},{"bn":"পড়া","en":"studying"}],"answer":1},{"q":{"bn":"“বই টেবিলের উপরে” — শূন্যস্থানে কী বসবে? {{الْكِتَابُ ___ الْمَكْتَبِ}}","en":"“The book is on the desk” — fill the gap: {{الْكِتَابُ ___ الْمَكْتَبِ}}"},"options":["فِي","عَلَى","تَحْتَ"],"answer":1},{"q":{"bn":"{{سَيَّارَةٌ}}-এর জন্য কোন শব্দ ঠিক?","en":"Which word fits {{سَيَّارَةٌ}}?"},"options":["هٰذَا","هٰذِهِ"],"answer":1},{"q":{"bn":"{{مِفْتَاحٌ}} দিয়ে আমরা কী করি?","en":"What do we do with a {{مِفْتَاحٌ}}?"},"options":[{"bn":"দরজা খুলি","en":"open a door"},{"bn":"লিখি","en":"write"},{"bn":"খাই","en":"eat"}],"answer":0}]}]},{"id":"daily-food","icon":"تمر","title":{"bn":"খাবার-দাবার ও বাজার","en":"Food, Drink & the Market"},"subtitle":{"bn":"রুটি, পানি, খেজুর — আর দোকানে দরদাম","en":"Bread, water, dates — and bargaining at the shop"},"minutes":15,"goals":[{"bn":"প্রতিদিনের খাবার ও পানীয়ের নাম","en":"Name everyday foods and drinks"},{"bn":"দোকানে দাম জিজ্ঞেস করা ও কেনা","en":"Ask prices and buy at a shop"},{"bn":"খাওয়ার আগে-পরের সুন্নাহ বাক্য","en":"Sunnah phrases before and after eating"}],"blocks":[{"type":"text","bn":"ক্ষুধা লেগেছে? চলুন আরবির বাজারে ঘুরে আসি! খেজুর, রুটি, মধু, মাছ — সব কিনব, আর দাম নিয়ে একটু দরদামও করব। কিন্তু খাওয়ার আগে কী বলতে হয়, ভুলবেন না যেন!","en":"Hungry? Let's take a walk through an Arabic market! We'll buy dates, bread, honey, fish — and haggle a little over prices. But don't forget what to say before eating!"},{"type":"vocab","title":{"bn":"খাবার","en":"Food"},"items":[{"ar":"طَعَامٌ","tr":{"bn":"তা'আম","en":"ṭa'aam"},"mean":{"bn":"খাবার","en":"food"}},{"ar":"خُبْزٌ","tr":{"bn":"খুবয","en":"khubz"},"mean":{"bn":"রুটি","en":"bread"}},{"ar":"أَرُزٌّ","tr":{"bn":"আরুযয","en":"aruzz"},"mean":{"bn":"ভাত, চাল","en":"rice"}},{"ar":"لَحْمٌ","tr":{"bn":"লাহম","en":"laḥm"},"mean":{"bn":"মাংস","en":"meat"}},{"ar":"دَجَاجٌ","tr":{"bn":"দাজাজ","en":"dajaaj"},"mean":{"bn":"মুরগি","en":"chicken"}},{"ar":"سَمَكٌ","tr":{"bn":"সামাক","en":"samak"},"mean":{"bn":"মাছ","en":"fish"}},{"ar":"بَيْضٌ","tr":{"bn":"বাইদ","en":"bayḍ"},"mean":{"bn":"ডিম","en":"eggs"}},{"ar":"خُضَارٌ","tr":{"bn":"খুদার","en":"khuḍaar"},"mean":{"bn":"শাকসবজি","en":"vegetables"}},{"ar":"مِلْحٌ","tr":{"bn":"মিলহ","en":"milḥ"},"mean":{"bn":"লবণ","en":"salt"}},{"ar":"سُكَّرٌ","tr":{"bn":"সুক্কার","en":"sukkar"},"mean":{"bn":"চিনি","en":"sugar"}}]},{"type":"vocab","title":{"bn":"ফল ও মিষ্টি","en":"Fruit and sweet things"},"items":[{"ar":"فَاكِهَةٌ","tr":{"bn":"ফাকিহাহ","en":"faakihah"},"mean":{"bn":"ফল","en":"fruit"},"example":{"ar":"فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ","mean":{"bn":"সেখানে আছে ফল, খেজুর গাছ ও ডালিম","en":"In them are fruit, date-palms and pomegranates"},"ref":"55:68"}},{"ar":"تَمْرٌ","tr":{"bn":"তামর","en":"tamr"},"mean":{"bn":"খেজুর","en":"dates"}},{"ar":"تُفَّاحٌ","tr":{"bn":"তুফফাহ","en":"tuffaaḥ"},"mean":{"bn":"আপেল","en":"apples"}},{"ar":"مَوْزٌ","tr":{"bn":"মাওয","en":"mawz"},"mean":{"bn":"কলা","en":"bananas"}},{"ar":"عِنَبٌ","tr":{"bn":"ইনাব","en":"'inab"},"mean":{"bn":"আঙুর","en":"grapes"}},{"ar":"عَسَلٌ","tr":{"bn":"আসাল","en":"'asal"},"mean":{"bn":"মধু","en":"honey"},"example":{"ar":"وَأَنْهَارٌ مِنْ عَسَلٍ مُصَفًّى","mean":{"bn":"এবং বিশুদ্ধ মধুর নহর (জান্নাতে)","en":"and rivers of purified honey (in Paradise)"},"ref":"47:15"}}]},{"type":"vocab","title":{"bn":"পানীয়","en":"Drinks"},"items":[{"ar":"مَاءٌ","tr":{"bn":"মা","en":"maaʾ"},"mean":{"bn":"পানি","en":"water"},"example":{"ar":"وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ","mean":{"bn":"আর আমি পানি থেকে প্রত্যেক জীবন্ত জিনিস সৃষ্টি করেছি","en":"And We made from water every living thing"},"ref":"21:30"}},{"ar":"حَلِيبٌ","tr":{"bn":"হালীব","en":"ḥaleeb"},"mean":{"bn":"দুধ","en":"milk"}},{"ar":"شَايٌ","tr":{"bn":"শাই","en":"shaay"},"mean":{"bn":"চা","en":"tea"}},{"ar":"قَهْوَةٌ","tr":{"bn":"কাহওয়াহ","en":"qahwah"},"mean":{"bn":"কফি","en":"coffee"}},{"ar":"عَصِيرٌ","tr":{"bn":"আসীর","en":"'aṣeer"},"mean":{"bn":"ফলের রস, জুস","en":"juice"}}]},{"type":"tip","kind":"fun","bn":"শব্দের বিশ্বভ্রমণ! ইংরেজি **coffee** এসেছে তুর্কি হয়ে আরবি {{قَهْوَةٌ}} থেকে। ইংরেজি **sugar** এসেছে আরবি {{سُكَّرٌ}} থেকে — আর আরবরা শব্দটি পেয়েছিল পারস্য হয়ে আমাদের উপমহাদেশের “শর্করা” থেকে! আর বাংলার “শরবত” ও “হালুয়া” — দুটোই আরবি শিকড়ের শব্দ।","en":"Words travel the world! English **coffee** came via Turkish from Arabic {{قَهْوَةٌ}}. English **sugar** came from Arabic {{سُكَّرٌ}} — and the Arabs got it via Persian from our subcontinent's Sanskrit “sharkara”! Bangla “shorbot” (sherbet) and “halua” both have Arabic roots too."},{"type":"tip","kind":"tip","bn":"কুরআনে দুধের জন্য {{لَبَنٌ}} শব্দ এসেছে (যেমন ৪৭:১৫), আর আজকের আরবিতে দুধকে সাধারণত বলে {{حَلِيبٌ}}। দুটোই চিনে রাখুন।","en":"The Quran uses {{لَبَنٌ}} for milk (e.g. 47:15), while modern Arabic usually says {{حَلِيبٌ}}. Know both."},{"type":"steps","title":{"bn":"খাওয়ার সুন্নাহ","en":"Sunnah of eating"},"items":[{"title":{"bn":"শুরুতে","en":"Before eating"},"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লাহ","en":"bismillaah"},"mean":{"bn":"আল্লাহর নামে","en":"In the name of Allah"},"desc":{"bn":"ডান হাতে, নিজের সামনে থেকে খান।","en":"Eat with your right hand, from what is in front of you."}},{"title":{"bn":"শুরুতে ভুলে গেলে","en":"If you forgot at the start"},"ar":"بِسْمِ اللّٰهِ أَوَّلَهُ وَآخِرَهُ","tr":{"bn":"বিসমিল্লাহি আওয়ালাহু ওয়া আখিরাহ","en":"bismillaahi awwalahu wa aakhirah"},"mean":{"bn":"এর শুরু ও শেষ আল্লাহর নামে","en":"In the name of Allah, at its beginning and its end"}},{"title":{"bn":"শেষে","en":"After eating"},"ar":"الْحَمْدُ لِلّٰهِ","tr":{"bn":"আলহামদু লিল্লাহ","en":"al-ḥamdu lillaah"},"mean":{"bn":"সব প্রশংসা আল্লাহর","en":"All praise is for Allah"},"desc":{"bn":"আল্লাহর নিয়ামতের জন্য শুকরিয়া জানান।","en":"Thank Allah for His blessing."}}]},{"type":"vocab","title":{"bn":"বাজারের বাক্য","en":"Market phrases"},"items":[{"ar":"بِكَمْ هٰذَا؟","tr":{"bn":"বিকাম হাযা?","en":"bikam haadhaa?"},"mean":{"bn":"এটার দাম কত?","en":"How much is this?"}},{"ar":"أُرِيدُ ...","tr":{"bn":"উরীদু ...","en":"ureedu ..."},"mean":{"bn":"আমি ... চাই","en":"I want ..."}},{"ar":"هَلْ عِنْدَكَ ...؟","tr":{"bn":"হাল ইনদাকা ...?","en":"hal 'indaka ...?"},"mean":{"bn":"আপনার কাছে ... আছে?","en":"Do you have ...?"}},{"ar":"غَالٍ","tr":{"bn":"গালিন","en":"ghaalin"},"mean":{"bn":"দামি","en":"expensive"}},{"ar":"رَخِيصٌ","tr":{"bn":"রাখীস","en":"rakheeṣ"},"mean":{"bn":"সস্তা","en":"cheap"}},{"ar":"أَنَا جَائِعٌ","tr":{"bn":"আনা জাই'","en":"ana jaaʾi'"},"mean":{"bn":"আমার ক্ষুধা লেগেছে","en":"I am hungry"}},{"ar":"أَنَا عَطْشَانُ","tr":{"bn":"আনা আতশান","en":"ana 'aṭshaan"},"mean":{"bn":"আমার পিপাসা লেগেছে","en":"I am thirsty"}}]},{"type":"examples","title":{"bn":"দোকানে এক মিনিট","en":"One minute at the shop"},"items":[{"ar":"أُرِيدُ خُبْزًا وَحَلِيبًا","tr":{"bn":"উরীদু খুবযান ওয়া হালীবা","en":"ureedu khubzan wa ḥaleeban"},"mean":{"bn":"আমি রুটি আর দুধ চাই","en":"I want bread and milk"},"note":{"bn":"“চাই” ক্রিয়ার পরে শব্দের শেষে {{ـًا}} (আন) হয়।","en":"After “want”, the noun ends in {{ـًا}} (an)."},"hl":"أُرِيدُ"},{"ar":"هَلْ عِنْدَكَ تَمْرٌ؟","tr":{"bn":"হাল ইনদাকা তামর?","en":"hal 'indaka tamr?"},"mean":{"bn":"আপনার কাছে খেজুর আছে?","en":"Do you have dates?"},"hl":"هَلْ عِنْدَكَ"},{"ar":"بِكَمْ هٰذَا الْعَسَلُ؟","tr":{"bn":"বিকাম হাযাল আসাল?","en":"bikam haadhal-'asal?"},"mean":{"bn":"এই মধুর দাম কত?","en":"How much is this honey?"},"hl":"بِكَمْ"},{"ar":"هٰذَا غَالٍ جِدًّا","tr":{"bn":"হাযা গালিন জিদ্দা","en":"haadhaa ghaalin jiddan"},"mean":{"bn":"এটা খুব দামি","en":"This is very expensive"},"hl":"جِدًّا"}]},{"type":"quiz","items":[{"q":{"bn":"{{مَاءٌ}} মানে কী?","en":"What is {{مَاءٌ}}?"},"options":[{"bn":"দুধ","en":"milk"},{"bn":"পানি","en":"water"},{"bn":"চা","en":"tea"}],"answer":1},{"q":{"bn":"“খেজুর” আরবিতে কী?","en":"What is “dates” in Arabic?"},"options":["تُفَّاحٌ","تَمْرٌ","مَوْزٌ"],"answer":1},{"q":{"bn":"দোকানে দাম জিজ্ঞেস করতে কী বলবেন?","en":"To ask the price at a shop you say:"},"options":["بِكَمْ هٰذَا؟","أَيْنَ الْمَسْجِدُ؟","مَا اسْمُكَ؟"],"answer":0},{"q":{"bn":"{{سَمَكٌ}} কী?","en":"What is {{سَمَكٌ}}?"},"options":[{"bn":"মাংস","en":"meat"},{"bn":"মুরগি","en":"chicken"},{"bn":"মাছ","en":"fish"}],"answer":2},{"q":{"bn":"খাওয়ার শুরুতে বিসমিল্লাহ বলতে ভুলে গেলে কী বলবেন?","en":"If you forgot bismillah at the start of a meal, say:"},"options":["بِسْمِ اللّٰهِ أَوَّلَهُ وَآخِرَهُ","إِنَّا لِلّٰهِ","مَعَ السَّلَامَةِ"],"answer":0},{"q":{"bn":"{{رَخِيصٌ}}-এর বিপরীত কোনটি?","en":"The opposite of {{رَخِيصٌ}} is:"},"options":["غَالٍ","جَائِعٌ","عَسَلٌ"],"answer":0},{"q":{"bn":"ইংরেজি “coffee” শব্দটি কোন আরবি শব্দ থেকে এসেছে?","en":"English “coffee” comes from which Arabic word?"},"options":["قَهْوَةٌ","حَلِيبٌ","عَصِيرٌ"],"answer":0}]}]},{"id":"daily-time","icon":"يوم","title":{"bn":"সময়: দিন, মাস ও নামাজ","en":"Time: Days, Months & Prayers"},"subtitle":{"bn":"সপ্তাহের সাত দিন, হিজরি বারো মাস, দিনের ভাগ আর পাঁচ ওয়াক্ত","en":"Seven days, twelve Hijri months, parts of the day and the five prayers"},"minutes":20,"goals":[{"bn":"সপ্তাহের দিনগুলোর আরবি নাম (আর তাদের গোপন সংখ্যা!)","en":"The days of the week (and their hidden numbers!)"},{"bn":"হিজরি বারো মাসের নাম ও গুরুত্ব","en":"The twelve Hijri months and why they matter"},{"bn":"আজ, কাল, গতকাল, সকাল, রাত বলা","en":"Say today, tomorrow, yesterday, morning, night"},{"bn":"পাঁচ ওয়াক্ত নামাজের নামের অর্থ","en":"The meanings of the five prayer names"}],"blocks":[{"type":"text","bn":"একজন মুসলিমের দিন ঘড়ির কাঁটায় নয়, **নামাজের ওয়াক্তে** ভাগ হয় — ফজর, যোহর, আসর, মাগরিব, এশা। আর বছর চলে চাঁদের হিসেবে — মুহাররম থেকে যুলহিজ্জাহ। এই সব নাম আসলে আরবি শব্দ, এবং প্রতিটির পেছনে একটা সুন্দর অর্থ আছে।","en":"A Muslim's day is divided not by the clock but by **prayer times** — Fajr, Zuhr, 'Asr, Maghrib, 'Isha. And the year follows the moon — from Muharram to Dhul-Hijjah. All these names are Arabic words, and each hides a lovely meaning."},{"type":"vocab","title":{"bn":"সপ্তাহের দিন","en":"Days of the week"},"items":[{"ar":"يَوْمُ الْأَحَدِ","tr":{"bn":"ইয়াওমুল আহাদ","en":"yawmul-aḥad"},"mean":{"bn":"রবিবার","en":"Sunday"}},{"ar":"يَوْمُ الِاثْنَيْنِ","tr":{"bn":"ইয়াওমুল ইসনাইন","en":"yawmul-ithnayn"},"mean":{"bn":"সোমবার","en":"Monday"}},{"ar":"يَوْمُ الثُّلَاثَاءِ","tr":{"bn":"ইয়াওমুস সুলাসা","en":"yawmuth-thulaathaaʾ"},"mean":{"bn":"মঙ্গলবার","en":"Tuesday"}},{"ar":"يَوْمُ الْأَرْبِعَاءِ","tr":{"bn":"ইয়াওমুল আরবিআ","en":"yawmul-arbi'aaʾ"},"mean":{"bn":"বুধবার","en":"Wednesday"}},{"ar":"يَوْمُ الْخَمِيسِ","tr":{"bn":"ইয়াওমুল খামীস","en":"yawmul-khamees"},"mean":{"bn":"বৃহস্পতিবার","en":"Thursday"}},{"ar":"يَوْمُ الْجُمُعَةِ","tr":{"bn":"ইয়াওমুল জুমুআহ","en":"yawmul-jumu'ah"},"mean":{"bn":"শুক্রবার","en":"Friday"},"example":{"ar":"إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللّٰهِ","mean":{"bn":"যখন জুমার দিনে নামাজের জন্য ডাকা হয়, তখন আল্লাহর স্মরণের দিকে দ্রুত যাও","en":"When the call is made for prayer on Friday, hasten to the remembrance of Allah"},"ref":"62:9"}},{"ar":"يَوْمُ السَّبْتِ","tr":{"bn":"ইয়াওমুস সাবত","en":"yawmus-sabt"},"mean":{"bn":"শনিবার","en":"Saturday"}}]},{"type":"table","title":{"bn":"দিনের নামে লুকানো সংখ্যা","en":"Numbers hidden in the day names"},"head":[{"bn":"দিন","en":"Day"},{"bn":"লুকানো শব্দ","en":"Hidden word"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["الْأَحَدُ","أَحَدٌ",{"bn":"এক — সপ্তাহের ১ম দিন","en":"one — 1st day of the week"}],["الِاثْنَيْنِ","اِثْنَانِ",{"bn":"দুই — ২য় দিন","en":"two — 2nd day"}],["الثُّلَاثَاءُ","ثَلَاثَةٌ",{"bn":"তিন — ৩য় দিন","en":"three — 3rd day"}],["الْأَرْبِعَاءُ","أَرْبَعَةٌ",{"bn":"চার — ৪র্থ দিন","en":"four — 4th day"}],["الْخَمِيسُ","خَمْسَةٌ",{"bn":"পাঁচ — ৫ম দিন","en":"five — 5th day"}],["الْجُمُعَةُ","جَمَعَ",{"bn":"একত্র করা — সবাই জামাতে জড়ো হয়","en":"to gather — people gather for prayer"}],["السَّبْتُ","سَبْتٌ",{"bn":"বিরতি, বিশ্রাম","en":"rest, pause"}]]},{"type":"tip","kind":"memory","bn":"সংখ্যা পাঠের কথা মনে আছে? রবিবার থেকে বৃহস্পতিবার — আরবিতে দিনগুলো আসলে **১ম, ২য়, ৩য়, ৪র্থ, ৫ম দিন**! আর বাংলার “জুমা” তো আরবি {{الْجُمُعَةُ}}-ই।","en":"Remember the numbers lesson? Sunday to Thursday are literally **day 1, 2, 3, 4, 5** in Arabic! And the Bangla “Jumma” is simply Arabic {{الْجُمُعَةُ}}."},{"type":"tip","kind":"fun","bn":"ইসলামি হিসেবে নতুন দিন শুরু হয় **মাগরিবে**, মধ্যরাতে নয়। তাই বৃহস্পতিবার সন্ধ্যার পরের রাতটাই “জুমার রাত”, আর রমজানের চাঁদ দেখা গেলে সেই রাত থেকেই তারাবিহ শুরু।","en":"In the Islamic reckoning a new day begins at **Maghrib**, not midnight. So the night after Thursday's sunset is already “Friday night”, and when the Ramadan moon is sighted, tarawih starts that same night."},{"type":"table","title":{"bn":"হিজরি বারো মাস","en":"The twelve Hijri months"},"head":["#",{"bn":"আরবি নাম","en":"Arabic name"},{"bn":"উচ্চারণ","en":"Pronunciation"},{"bn":"এক লাইনে গুরুত্ব","en":"Why it matters"}],"rows":[["١","مُحَرَّمٌ",{"bn":"মুহাররম","en":"Muḥarram"},{"bn":"বছরের প্রথম মাস ও সম্মানিত মাস; ১০ তারিখ আশুরার রোজা।","en":"First month and a sacred month; fasting on the 10th, 'Ashura."}],["٢","صَفَرٌ",{"bn":"সফর","en":"Ṣafar"},{"bn":"এ মাসকে অশুভ ভাবার কুসংস্কার নবী ﷺ বাতিল করেছেন।","en":"The Prophet ﷺ rejected the superstition that this month is unlucky."}],["٣","رَبِيعُ الْأَوَّلِ",{"bn":"রবিউল আউয়াল","en":"Rabee'ul-Awwal"},{"bn":"নবী ﷺ-এর জন্ম ও মদিনায় হিজরতের মাস হিসেবে প্রসিদ্ধ।","en":"Known as the month of the Prophet's ﷺ birth and his Hijrah to Madinah."}],["٤","رَبِيعُ الْآخِرِ",{"bn":"রবিউল আখির (রবিউস সানি)","en":"Rabee'ul-Aakhir (Rabee' ath-Thaanee)"},{"bn":"“পরের রবি” — রবি মানে বসন্ত।","en":"“The later Rabee'” — rabee' means spring."}],["٥","جُمَادَى الْأُولَى",{"bn":"জুমাদাল উলা (জমাদিউল আউয়াল)","en":"Jumaadal-Oolaa"},{"bn":"প্রথম জুমাদা; নামটি সম্ভবত শীতে পানি জমে যাওয়া ({{جَمَدَ}}) থেকে।","en":"The first Jumada; the name probably comes from water freezing ({{جَمَدَ}}) in winter."}],["٦","جُمَادَى الْآخِرَةِ",{"bn":"জুমাদাল আখিরাহ (জমাদিউস সানি)","en":"Jumaadal-Aakhirah"},{"bn":"দ্বিতীয় জুমাদা; এ মাসে বছরের প্রথম অর্ধেক শেষ হয়।","en":"The second Jumada; the first half of the year ends here."}],["٧","رَجَبٌ",{"bn":"রজব","en":"Rajab"},{"bn":"চারটি সম্মানিত মাসের একটি।","en":"One of the four sacred months."}],["٨","شَعْبَانُ",{"bn":"শাবান","en":"Sha'baan"},{"bn":"নবী ﷺ এ মাসে অনেক নফল রোজা রাখতেন — রমজানের প্রস্তুতি।","en":"The Prophet ﷺ fasted much in it — preparing for Ramadan."}],["٩","رَمَضَانُ",{"bn":"রমাদান (রমজান)","en":"Ramaḍaan"},{"bn":"রোজার মাস; এ মাসেই কুরআন নাজিল হয় (২:১৮৫), আছে লাইলাতুল কদর।","en":"Month of fasting; the Quran was sent down in it (2:185); it holds Laylat al-Qadr."}],["١٠","شَوَّالٌ",{"bn":"শাওয়াল","en":"Shawwaal"},{"bn":"১ তারিখে ঈদুল ফিতর; ছয়টি নফল রোজার মাস।","en":"Eid al-Fitr on the 1st; six voluntary fasts."}],["١١","ذُو الْقَعْدَةِ",{"bn":"যুলকা'দাহ (জিলকদ)","en":"Dhul-Qa'dah"},{"bn":"সম্মানিত মাস; {{قَعَدَ}} (বসে থাকা) থেকে — আরবরা এ মাসে যুদ্ধ থেকে বিরত থাকত।","en":"A sacred month; from {{قَعَدَ}} (to sit) — Arabs stayed back from fighting in it."}],["١٢","ذُو الْحِجَّةِ",{"bn":"যুলহিজ্জাহ (জিলহজ)","en":"Dhul-Ḥijjah"},{"bn":"হজের মাস; ৯ তারিখ আরাফার দিন, ১০ তারিখ ঈদুল আযহা।","en":"Month of Hajj; 9th is the Day of 'Arafah, 10th is Eid al-Adha."}]]},{"type":"examples","title":{"bn":"কুরআনে মাসের হিসাব","en":"The months in the Quran"},"items":[{"ar":"إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللّٰهِ اثْنَا عَشَرَ شَهْرًا","tr":{"bn":"ইন্না ইদ্দাতাশ শুহূরি ইনদাল্লাহিসনা আশারা শাহরা","en":"inna 'iddatash-shuhoori 'indallaahith-naa 'ashara shahran"},"mean":{"bn":"নিশ্চয়ই আল্লাহর কাছে মাসের সংখ্যা বারো (৯:৩৬)","en":"Indeed, the number of months with Allah is twelve (9:36)"},"note":{"bn":"এই আয়াতেই বলা হয়েছে, এর মধ্যে চারটি সম্মানিত: মুহাররম, রজব, যুলকা'দাহ, যুলহিজ্জাহ।","en":"The same verse says four of them are sacred: Muharram, Rajab, Dhul-Qa'dah, Dhul-Hijjah."},"hl":"اثْنَا عَشَرَ"}]},{"type":"tip","kind":"memory","bn":"চারটি সম্মানিত মাস মনে রাখার ছড়া: **“বছরের শুরু-শেষ, মাঝে রজব বেশ”** — শুরু = মুহাররম, শেষ দুই = যুলকা'দাহ ও যুলহিজ্জাহ, আর মাঝে রজব।","en":"A rhyme for the four sacred months: **“Start and end, with Rajab in the middle”** — start = Muharram, the last two = Dhul-Qa'dah and Dhul-Hijjah, and Rajab in the middle."},{"type":"vocab","title":{"bn":"দিনের ভাগ ও সময়","en":"Parts of the day and time words"},"items":[{"ar":"فَجْرٌ","tr":{"bn":"ফাজর","en":"fajr"},"mean":{"bn":"ভোর, ঊষা","en":"dawn"}},{"ar":"صَبَاحٌ","tr":{"bn":"সাবাহ","en":"ṣabaaḥ"},"mean":{"bn":"সকাল","en":"morning"}},{"ar":"مَسَاءٌ","tr":{"bn":"মাসা","en":"masaaʾ"},"mean":{"bn":"সন্ধ্যা","en":"evening"}},{"ar":"لَيْلٌ","tr":{"bn":"লাইল","en":"layl"},"mean":{"bn":"রাত","en":"night"}},{"ar":"يَوْمٌ","tr":{"bn":"ইয়াওম","en":"yawm"},"mean":{"bn":"দিন","en":"day"}},{"ar":"أُسْبُوعٌ","tr":{"bn":"উসবূ'","en":"usboo'"},"mean":{"bn":"সপ্তাহ","en":"week"}},{"ar":"شَهْرٌ","tr":{"bn":"শাহর","en":"shahr"},"mean":{"bn":"মাস","en":"month"},"example":{"ar":"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ","mean":{"bn":"রমজান মাস, যাতে কুরআন নাজিল করা হয়েছে","en":"The month of Ramadan, in which the Quran was sent down"},"ref":"2:185"}},{"ar":"سَنَةٌ","tr":{"bn":"সানাহ","en":"sanah"},"mean":{"bn":"বছর","en":"year"}},{"ar":"الْيَوْمَ","tr":{"bn":"আল-ইয়াওমা","en":"al-yawma"},"mean":{"bn":"আজ","en":"today"}},{"ar":"غَدًا","tr":{"bn":"গাদান","en":"ghadan"},"mean":{"bn":"আগামীকাল","en":"tomorrow"}},{"ar":"أَمْسِ","tr":{"bn":"আমসি","en":"amsi"},"mean":{"bn":"গতকাল","en":"yesterday"}},{"ar":"الْآنَ","tr":{"bn":"আল-আনা","en":"al-aana"},"mean":{"bn":"এখন","en":"now"}}]},{"type":"table","title":{"bn":"পাঁচ ওয়াক্ত নামাজ","en":"The five daily prayers"},"head":[{"bn":"নামাজ","en":"Prayer"},{"bn":"বাংলায়","en":"Name"},{"bn":"শব্দের অর্থ","en":"Word meaning"},{"bn":"ফরজ রাকাত","en":"Fard rak'ahs"}],"rows":[["الْفَجْرُ",{"bn":"ফজর","en":"Fajr"},{"bn":"ভোর — রাতের অন্ধকার “ফেটে” আলো বের হওয়া","en":"dawn — light “breaking” through the night"},"٢"],["الظُّهْرُ",{"bn":"যোহর","en":"Ẓuhr"},{"bn":"দুপুর, সূর্য মাথার উপর থেকে হেলে পড়ার পর","en":"midday, just after the sun passes its peak"},"٤"],["الْعَصْرُ",{"bn":"আসর","en":"'Aṣr"},{"bn":"বিকেল; “সময়” — সূরা আসরের নাম","en":"afternoon; “time” — the name of Surah al-'Asr"},"٤"],["الْمَغْرِبُ",{"bn":"মাগরিব","en":"Maghrib"},{"bn":"সূর্য ডোবার সময় / পশ্চিম","en":"sunset / the west"},"٣"],["الْعِشَاءُ",{"bn":"এশা","en":"'Ishaaʾ"},{"bn":"রাতের অন্ধকার নেমে আসা","en":"when night's darkness falls"},"٤"]]},{"type":"tip","kind":"fun","bn":"{{الْمَغْرِبُ}} মানে “সূর্য ডোবার জায়গা” অর্থাৎ পশ্চিম — তাই আরবিতে মরক্কো দেশের নামও {{الْمَغْرِبُ}}, কারণ এটি আরব বিশ্বের একেবারে পশ্চিমে!","en":"{{الْمَغْرِبُ}} means “the place where the sun sets”, i.e. the west — that's why Morocco's Arabic name is also {{الْمَغْرِبُ}}: it is at the far west of the Arab world!"},{"type":"examples","title":{"bn":"সময় নিয়ে বাক্য","en":"Sentences about time"},"items":[{"ar":"الْيَوْمَ يَوْمُ الْجُمُعَةِ","tr":{"bn":"আল-ইয়াওমা ইয়াওমুল জুমুআহ","en":"al-yawma yawmul-jumu'ah"},"mean":{"bn":"আজ শুক্রবার","en":"Today is Friday"},"hl":"الْيَوْمَ"},{"ar":"أُصَلِّي الْفَجْرَ فِي الْمَسْجِدِ","tr":{"bn":"উসাল্লিল ফাজরা ফিল মাসজিদ","en":"uṣallil-fajra fil-masjid"},"mean":{"bn":"আমি মসজিদে ফজর পড়ি","en":"I pray Fajr in the masjid"},"hl":"الْفَجْرَ"},{"ar":"نَصُومُ فِي رَمَضَانَ","tr":{"bn":"নাসূমু ফী রামাদান","en":"naṣoomu fee ramaḍaan"},"mean":{"bn":"আমরা রমজানে রোজা রাখি","en":"We fast in Ramadan"},"hl":"رَمَضَانَ"},{"ar":"أَرَاكَ غَدًا بَعْدَ الْعَصْرِ","tr":{"bn":"আরাকা গাদান বা'দাল আসর","en":"araaka ghadan ba'dal-'aṣr"},"mean":{"bn":"কাল আসরের পর তোমার সাথে দেখা হবে","en":"See you tomorrow after 'Asr"},"hl":"غَدًا"}]},{"type":"quiz","items":[{"q":{"bn":"{{يَوْمُ الْخَمِيسِ}} কোন দিন?","en":"Which day is {{يَوْمُ الْخَمِيسِ}}?"},"options":[{"bn":"মঙ্গলবার","en":"Tuesday"},{"bn":"বৃহস্পতিবার","en":"Thursday"},{"bn":"শনিবার","en":"Saturday"}],"answer":1,"explain":{"bn":"{{خَمِيس}}-এ লুকিয়ে আছে {{خَمْسَة}} (পাঁচ) — সপ্তাহের ৫ম দিন।","en":"{{خَمِيس}} hides {{خَمْسَة}} (five) — the 5th day of the week."}},{"q":{"bn":"রোজার মাস কোনটি?","en":"Which is the month of fasting?"},"options":["شَعْبَانُ","رَمَضَانُ","شَوَّالٌ"],"answer":1},{"q":{"bn":"হজ কোন মাসে হয়?","en":"In which month is Hajj?"},"options":["ذُو الْحِجَّةِ","مُحَرَّمٌ","رَجَبٌ"],"answer":0},{"q":{"bn":"{{غَدًا}} মানে কী?","en":"What does {{غَدًا}} mean?"},"options":[{"bn":"গতকাল","en":"yesterday"},{"bn":"আজ","en":"today"},{"bn":"আগামীকাল","en":"tomorrow"}],"answer":2},{"q":{"bn":"সূর্য ডোবার পরের নামাজ কোনটি?","en":"Which prayer comes right after sunset?"},"options":["الْعَصْرُ","الْمَغْرِبُ","الْفَجْرُ"],"answer":1},{"q":{"bn":"আশুরা কোন মাসের ১০ তারিখ?","en":"'Ashura is the 10th of which month?"},"options":["صَفَرٌ","مُحَرَّمٌ","رَمَضَانُ"],"answer":1},{"q":{"bn":"{{لَيْلٌ}} মানে কী?","en":"What is {{لَيْلٌ}}?"},"options":[{"bn":"রাত","en":"night"},{"bn":"সকাল","en":"morning"},{"bn":"সপ্তাহ","en":"week"}],"answer":0},{"q":{"bn":"কোনটি চারটি সম্মানিত মাসের একটি নয়?","en":"Which is NOT one of the four sacred months?"},"options":["رَجَبٌ","مُحَرَّمٌ","شَعْبَانُ","ذُو الْقَعْدَةِ"],"answer":2}]}]},{"id":"daily-colours","icon":"لون","title":{"bn":"রং ও বর্ণনা","en":"Colours & Describing Things"},"subtitle":{"bn":"সাদা-কালো-লাল-সবুজ, আর বড়-ছোট-সুন্দর-নতুন","en":"White, black, red, green — and big, small, beautiful, new"},"minutes":15,"goals":[{"bn":"ছয়টি মূল রং ও আরও কয়েকটি রঙের নাম","en":"Six basic colours and a few more"},{"bn":"রঙের পুরুষবাচক ও স্ত্রীবাচক রূপ","en":"Masculine and feminine forms of colours"},{"bn":"বিপরীত শব্দ জোড়ায় বিশেষণ শেখা","en":"Learn adjectives in opposite pairs"},{"bn":"বিশেষ্যের পরে বিশেষণ বসিয়ে বর্ণনা করা","en":"Describe things: noun first, adjective after"}],"blocks":[{"type":"text","bn":"বাংলাদেশের পতাকায় কী কী রং? সবুজ আর লাল — আরবিতে {{أَخْضَرُ}} আর {{أَحْمَرُ}}! এই পাঠে আমরা রং আর বর্ণনার শব্দ শিখব, যাতে শুধু “এটা বই” নয়, বলতে পারি “এটা একটা **নতুন লাল** বই”।","en":"What colours are on Bangladesh's flag? Green and red — in Arabic {{أَخْضَرُ}} and {{أَحْمَرُ}}! In this lesson we learn colours and describing words, so that instead of just “this is a book” we can say “this is a **new red** book”."},{"type":"vocab","title":{"bn":"ছয়টি মূল রং","en":"Six basic colours"},"items":[{"ar":"أَبْيَضُ","tr":{"bn":"আবয়াদ","en":"abyaḍ"},"mean":{"bn":"সাদা","en":"white"},"example":{"ar":"الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ","mean":{"bn":"ভোরের সাদা রেখা কালো রেখা থেকে (স্পষ্ট হয়)","en":"the white thread (of dawn) from the black thread"},"ref":"2:187"}},{"ar":"أَسْوَدُ","tr":{"bn":"আসওয়াদ","en":"aswad"},"mean":{"bn":"কালো","en":"black"}},{"ar":"أَحْمَرُ","tr":{"bn":"আহমার","en":"aḥmar"},"mean":{"bn":"লাল","en":"red"}},{"ar":"أَخْضَرُ","tr":{"bn":"আখদার","en":"akhḍar"},"mean":{"bn":"সবুজ","en":"green"}},{"ar":"أَزْرَقُ","tr":{"bn":"আযরাক","en":"azraq"},"mean":{"bn":"নীল","en":"blue"}},{"ar":"أَصْفَرُ","tr":{"bn":"আসফার","en":"aṣfar"},"mean":{"bn":"হলুদ","en":"yellow"},"example":{"ar":"إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَوْنُهَا","mean":{"bn":"তা একটি হলুদ গাভী, যার রং উজ্জ্বল গাঢ়","en":"It is a yellow cow, bright in colour"},"ref":"2:69"}}]},{"type":"tip","kind":"memory","bn":"ছয়টি মূল রং একই ছাঁচে তৈরি: **{{أَ}} + তিন অক্ষর** — {{أَبْيَضُ}}, {{أَسْوَدُ}}, {{أَحْمَرُ}}, {{أَخْضَرُ}}, {{أَزْرَقُ}}, {{أَصْفَرُ}}। কাবার “হাজরে আসওয়াদ” মনে আছে? {{الْحَجَرُ الْأَسْوَدُ}} — **কালো** পাথর!","en":"All six basic colours share one mould: **{{أَ}} + three letters** — {{أَبْيَضُ}}, {{أَسْوَدُ}}, {{أَحْمَرُ}}, {{أَخْضَرُ}}, {{أَزْرَقُ}}, {{أَصْفَرُ}}. Remember the “Hajar al-Aswad” at the Ka'bah? {{الْحَجَرُ الْأَسْوَدُ}} — the **black** stone!"},{"type":"table","title":{"bn":"রঙের ছেলে-রূপ ও মেয়ে-রূপ","en":"Masculine and feminine colours"},"head":[{"bn":"পুরুষবাচক","en":"Masculine"},{"bn":"স্ত্রীবাচক","en":"Feminine"},{"bn":"রং","en":"Colour"}],"rows":[["أَبْيَضُ","بَيْضَاءُ",{"bn":"সাদা","en":"white"}],["أَسْوَدُ","سَوْدَاءُ",{"bn":"কালো","en":"black"}],["أَحْمَرُ","حَمْرَاءُ",{"bn":"লাল","en":"red"}],["أَخْضَرُ","خَضْرَاءُ",{"bn":"সবুজ","en":"green"}],["أَزْرَقُ","زَرْقَاءُ",{"bn":"নীল","en":"blue"}],["أَصْفَرُ","صَفْرَاءُ",{"bn":"হলুদ","en":"yellow"}]]},{"type":"tip","kind":"tip","bn":"স্ত্রীবাচক রঙে {{ة}} লাগে না! ছাঁচ হলো **তিন অক্ষর + {{ـَاءُ}}**: {{أَحْمَرُ}} ➜ {{حَمْرَاءُ}}। যেমন {{قَلَمٌ أَحْمَرُ}} (লাল কলম), কিন্তু {{سَيَّارَةٌ حَمْرَاءُ}} (লাল গাড়ি)। আলহামরা প্রাসাদের নামও এখান থেকে — “লাল প্রাসাদ”!","en":"Feminine colours don't take {{ة}}! The mould is **three letters + {{ـَاءُ}}**: {{أَحْمَرُ}} ➜ {{حَمْرَاءُ}}. So {{قَلَمٌ أَحْمَرُ}} (a red pen), but {{سَيَّارَةٌ حَمْرَاءُ}} (a red car). The Alhambra palace gets its name from here — “the red one”!"},{"type":"vocab","title":{"bn":"আরও কিছু রং","en":"More colours"},"items":[{"ar":"لَوْنٌ","tr":{"bn":"লাওন","en":"lawn"},"mean":{"bn":"রং","en":"colour"}},{"ar":"بُنِّيٌّ","tr":{"bn":"বুন্নিয়্য","en":"bunniyy"},"mean":{"bn":"বাদামি (কফি-বীজের রং)","en":"brown (colour of coffee beans)"}},{"ar":"رَمَادِيٌّ","tr":{"bn":"রামাদিয়্য","en":"ramaadiyy"},"mean":{"bn":"ধূসর (ছাইয়ের রং)","en":"grey (colour of ash)"}},{"ar":"وَرْدِيٌّ","tr":{"bn":"ওয়ারদিয়্য","en":"wardiyy"},"mean":{"bn":"গোলাপি (গোলাপের রং)","en":"pink (colour of roses)"}},{"ar":"بُرْتُقَالِيٌّ","tr":{"bn":"বুরতুকালিয়্য","en":"burtuqaaliyy"},"mean":{"bn":"কমলা (কমলালেবুর রং)","en":"orange (colour of oranges)"}}]},{"type":"tip","kind":"memory","bn":"এই রংগুলো একটা জিনিসের নাম + {{ـِيٌّ}} (ইয়্যুন) = “ওই জিনিসের রঙের”: {{بُنٌّ}} কফি-বীজ ➜ {{بُنِّيٌّ}}, {{رَمَادٌ}} ছাই ➜ {{رَمَادِيٌّ}}, {{وَرْدٌ}} গোলাপ ➜ {{وَرْدِيٌّ}}। ঠিক বাংলার “গোলাপি”, “কমলা” রঙের মতো!","en":"These colours are a thing's name + {{ـِيٌّ}} (-iyy) = “the colour of that thing”: {{بُنٌّ}} coffee beans ➜ {{بُنِّيٌّ}}, {{رَمَادٌ}} ash ➜ {{رَمَادِيٌّ}}, {{وَرْدٌ}} rose ➜ {{وَرْدِيٌّ}}. Just like English “rose-coloured” or “orange”!"},{"type":"vocab","title":{"bn":"বর্ণনার শব্দ (বিশেষণ)","en":"Describing words (adjectives)"},"items":[{"ar":"كَبِيرٌ","tr":{"bn":"কাবীর","en":"kabeer"},"mean":{"bn":"বড়","en":"big"},"root":"ك ب ر"},{"ar":"صَغِيرٌ","tr":{"bn":"সাগীর","en":"ṣagheer"},"mean":{"bn":"ছোট","en":"small"}},{"ar":"جَمِيلٌ","tr":{"bn":"জামীল","en":"jameel"},"mean":{"bn":"সুন্দর","en":"beautiful"}},{"ar":"جَدِيدٌ","tr":{"bn":"জাদীদ","en":"jadeed"},"mean":{"bn":"নতুন","en":"new"}},{"ar":"قَدِيمٌ","tr":{"bn":"কাদীম","en":"qadeem"},"mean":{"bn":"পুরনো","en":"old"}},{"ar":"طَوِيلٌ","tr":{"bn":"তাউয়ীল","en":"ṭaweel"},"mean":{"bn":"লম্বা","en":"tall, long"}},{"ar":"قَصِيرٌ","tr":{"bn":"কাসীর","en":"qaṣeer"},"mean":{"bn":"খাটো, ছোট","en":"short"}},{"ar":"حَارٌّ","tr":{"bn":"হার্র","en":"ḥaarr"},"mean":{"bn":"গরম","en":"hot"}},{"ar":"بَارِدٌ","tr":{"bn":"বারিদ","en":"baarid"},"mean":{"bn":"ঠান্ডা","en":"cold"}},{"ar":"سَهْلٌ","tr":{"bn":"সাহল","en":"sahl"},"mean":{"bn":"সহজ","en":"easy"}},{"ar":"صَعْبٌ","tr":{"bn":"সা'ব","en":"ṣa'b"},"mean":{"bn":"কঠিন","en":"difficult"}},{"ar":"نَظِيفٌ","tr":{"bn":"নাযীফ","en":"naẓeef"},"mean":{"bn":"পরিষ্কার","en":"clean"}},{"ar":"كَثِيرٌ","tr":{"bn":"কাসীর","en":"katheer"},"mean":{"bn":"অনেক","en":"many, a lot"}},{"ar":"قَلِيلٌ","tr":{"bn":"কালীল","en":"qaleel"},"mean":{"bn":"অল্প","en":"few, a little"}}]},{"type":"tip","kind":"fun","bn":"আমাদের চেনা অনেক নামই আসলে বিশেষণ! **কবির** = বড়/মহান ({{كَبِيرٌ}}), **জামিল/জামিলা** = সুন্দর ({{جَمِيلٌ}}), আর **সাহল** = সহজ ({{سَهْلٌ}}) — {{أَهْلًا وَسَهْلًا}}-র সেই “সাহলান”!","en":"Many familiar names are really adjectives! **Kabir** = big/great ({{كَبِيرٌ}}), **Jamil/Jamila** = beautiful ({{جَمِيلٌ}}), and **Sahl** = easy ({{سَهْلٌ}}) — the same “sahlan” in {{أَهْلًا وَسَهْلًا}}!"},{"type":"table","title":{"bn":"বিপরীত জোড়া","en":"Opposite pairs"},"head":[{"bn":"শব্দ","en":"Word"},{"bn":"বিপরীত","en":"Opposite"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["كَبِيرٌ","صَغِيرٌ",{"bn":"বড় ↔ ছোট","en":"big ↔ small"}],["جَدِيدٌ","قَدِيمٌ",{"bn":"নতুন ↔ পুরনো","en":"new ↔ old"}],["طَوِيلٌ","قَصِيرٌ",{"bn":"লম্বা ↔ খাটো","en":"tall ↔ short"}],["حَارٌّ","بَارِدٌ",{"bn":"গরম ↔ ঠান্ডা","en":"hot ↔ cold"}],["سَهْلٌ","صَعْبٌ",{"bn":"সহজ ↔ কঠিন","en":"easy ↔ difficult"}],["كَثِيرٌ","قَلِيلٌ",{"bn":"অনেক ↔ অল্প","en":"many ↔ few"}]]},{"type":"tip","kind":"warn","bn":"বাংলায় আমরা বলি “**বড়** বাড়ি” — বিশেষণ আগে। আরবিতে উল্টো: **বিশেষ্য আগে, বিশেষণ পরে** — {{بَيْتٌ كَبِيرٌ}} (বাড়ি বড়-টা)। আর বিশেষণ বিশেষ্যের সাথে মিলে চলে: স্ত্রীবাচক হলে {{ة}}, {{الْ}} থাকলে দুটোতেই {{الْ}}।","en":"In English and Bangla we say “a **big** house” — adjective first. Arabic flips it: **noun first, adjective after** — {{بَيْتٌ كَبِيرٌ}} (house big). And the adjective matches its noun: feminine gets {{ة}}, and if the noun has {{الْ}}, so does the adjective."},{"type":"examples","title":{"bn":"বর্ণনা করি","en":"Let's describe"},"items":[{"ar":"بَيْتٌ كَبِيرٌ","tr":{"bn":"বাইতুন কাবীর","en":"baytun kabeer"},"mean":{"bn":"একটি বড় বাড়ি","en":"a big house"},"hl":"كَبِيرٌ"},{"ar":"سَيَّارَةٌ كَبِيرَةٌ","tr":{"bn":"সাইয়ারাতুন কাবীরাহ","en":"sayyaaratun kabeerah"},"mean":{"bn":"একটি বড় গাড়ি","en":"a big car"},"note":{"bn":"গাড়ি স্ত্রীবাচক, তাই বিশেষণেও {{ة}}।","en":"Car is feminine, so the adjective takes {{ة}} too."},"hl":"كَبِيرَةٌ"},{"ar":"الْبَيْتُ الْكَبِيرُ","tr":{"bn":"আল-বাইতুল কাবীর","en":"al-baytul-kabeer"},"mean":{"bn":"বড় বাড়িটি","en":"the big house"},"note":{"bn":"দুটোতেই {{الْ}} — তাই এটা একটা শব্দগুচ্ছ।","en":"Both have {{الْ}} — so it is a phrase."},"hl":"الْكَبِيرُ"},{"ar":"الْبَيْتُ كَبِيرٌ","tr":{"bn":"আল-বাইতু কাবীর","en":"al-baytu kabeer"},"mean":{"bn":"বাড়িটি বড়","en":"The house is big"},"note":{"bn":"বিশেষণে {{الْ}} নেই — তাই এটা পূর্ণ বাক্য!","en":"No {{الْ}} on the adjective — so it is a full sentence!"},"hl":"كَبِيرٌ"},{"ar":"عِنْدِي قَلَمٌ أَزْرَقُ جَدِيدٌ","tr":{"bn":"ইনদী কালামুন আযরাকু জাদীদ","en":"'indee qalamun azraqu jadeed"},"mean":{"bn":"আমার একটি নতুন নীল কলম আছে","en":"I have a new blue pen"},"hl":"أَزْرَقُ"},{"ar":"مَا لَوْنُ سَيَّارَتِكَ؟","tr":{"bn":"মা লাওনু সাইয়ারাতিকা?","en":"maa lawnu sayyaaratika?"},"mean":{"bn":"তোমার গাড়ির রং কী?","en":"What colour is your car?"},"hl":"لَوْنُ"},{"ar":"الْعَرَبِيَّةُ سَهْلَةٌ وَجَمِيلَةٌ","tr":{"bn":"আল-আরাবিয়্যাতু সাহলাতুন ওয়া জামীলাহ","en":"al-'arabiyyatu sahlatun wa jameelah"},"mean":{"bn":"আরবি সহজ ও সুন্দর!","en":"Arabic is easy and beautiful!"},"hl":"سَهْلَةٌ"}]},{"type":"quiz","items":[{"q":{"bn":"{{أَخْضَرُ}} কোন রং?","en":"What colour is {{أَخْضَرُ}}?"},"options":[{"bn":"নীল","en":"blue"},{"bn":"সবুজ","en":"green"},{"bn":"হলুদ","en":"yellow"}],"answer":1},{"q":{"bn":"“সাদা” আরবিতে কোনটি?","en":"Which is “white”?"},"options":["أَسْوَدُ","أَبْيَضُ","أَحْمَرُ"],"answer":1},{"q":{"bn":"“লাল গাড়ি” — কোনটি সঠিক?","en":"“A red car” — which is correct?"},"options":["سَيَّارَةٌ أَحْمَرُ","سَيَّارَةٌ حَمْرَاءُ","أَحْمَرُ سَيَّارَةٌ"],"answer":1,"explain":{"bn":"গাড়ি স্ত্রীবাচক, তাই রঙের স্ত্রীবাচক রূপ {{حَمْرَاءُ}}, আর বিশেষণ বসে বিশেষ্যের পরে।","en":"Car is feminine, so we use the feminine colour {{حَمْرَاءُ}}, and the adjective comes after the noun."}},{"q":{"bn":"{{جَدِيدٌ}}-এর বিপরীত কোনটি?","en":"The opposite of {{جَدِيدٌ}} is:"},"options":["قَدِيمٌ","كَبِيرٌ","جَمِيلٌ"],"answer":0},{"q":{"bn":"{{الْبَيْتُ كَبِيرٌ}} মানে কী?","en":"What does {{الْبَيْتُ كَبِيرٌ}} mean?"},"options":[{"bn":"বড় বাড়িটি","en":"the big house"},{"bn":"বাড়িটি বড়","en":"The house is big"},{"bn":"একটি বড় বাড়ি","en":"a big house"}],"answer":1},{"q":{"bn":"{{بَارِدٌ}} মানে কী?","en":"What is {{بَارِدٌ}}?"},"options":[{"bn":"গরম","en":"hot"},{"bn":"ঠান্ডা","en":"cold"},{"bn":"পরিষ্কার","en":"clean"}],"answer":1},{"q":{"bn":"হাজরে আসওয়াদের {{الْأَسْوَدُ}} শব্দের অর্থ কী?","en":"In al-Hajar al-Aswad, what does {{الْأَسْوَدُ}} mean?"},"options":[{"bn":"সাদা","en":"white"},{"bn":"কালো","en":"black"},{"bn":"বড়","en":"big"}],"answer":1}]}]},{"id":"daily-conversation","icon":"قول","title":{"bn":"কথোপকথন ল্যাব","en":"Conversation Lab"},"subtitle":{"bn":"মসজিদে, বন্ধুর সাথে, দোকানে — আর ক্লাসের দরকারি বাক্য","en":"At the masjid, with a friend, at a shop — plus handy classroom phrases"},"minutes":20,"goals":[{"bn":"বাস্তব জীবনের তিনটি সংলাপ পড়া ও অভিনয় করা","en":"Read and act out three real-life dialogues"},{"bn":"আগের পাঠের শব্দগুলো একসাথে ব্যবহার করা","en":"Combine words from all the earlier lessons"},{"bn":"ক্লাসে প্রশ্ন করা ও সাহায্য চাওয়ার বাক্য","en":"Classroom phrases to ask questions and get help"}],"blocks":[{"type":"text","bn":"অভিনন্দন! আপনি এখন সালাম, পরিচয়, সংখ্যা, পরিবার, খাবার, সময় আর রং — সবই জানেন। এবার সব জুড়ে আসল কথা বলার পালা। একজন বন্ধুকে সঙ্গী বানিয়ে প্রতিটি সংলাপ **অভিনয় করে** পড়ুন, তারপর ভূমিকা বদল করুন।","en":"Congratulations! You now know greetings, introductions, numbers, family, food, time and colours. Time to put it all together and really talk. Grab a partner, **act out** each dialogue, then swap roles."},{"type":"steps","title":{"bn":"সংলাপ ১: মসজিদে নামাজের পর","en":"Dialogue 1: At the masjid after prayer"},"items":[{"title":{"bn":"ইউসুফ","en":"Yusuf"},"ar":"السَّلَامُ عَلَيْكُمْ يَا أَخِي.","tr":{"bn":"আস্‌সালামু আলাইকুম ইয়া আখী।","en":"as-salaamu 'alaykum yaa akhee."},"mean":{"bn":"আসসালামু আলাইকুম, ভাই।","en":"Peace be upon you, brother."}},{"title":{"bn":"ইমরান","en":"Imran"},"ar":"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ.","tr":{"bn":"ওয়া আলাইকুমুস সালাম ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ।","en":"wa 'alaykumus-salaam wa raḥmatullaahi wa barakaatuh."},"mean":{"bn":"আপনার উপরও শান্তি, আল্লাহর রহমত ও বরকত।","en":"And upon you be peace, Allah's mercy and His blessings."}},{"title":{"bn":"ইউসুফ","en":"Yusuf"},"ar":"تَقَبَّلَ اللّٰهُ.","tr":{"bn":"তাকাব্বালাল্লাহ।","en":"taqabbalallaah."},"mean":{"bn":"আল্লাহ কবুল করুন।","en":"May Allah accept (it)."}},{"title":{"bn":"ইমরান","en":"Imran"},"ar":"مِنَّا وَمِنْكُمْ. هَلْ أَنْتَ جَدِيدٌ هُنَا؟","tr":{"bn":"মিন্না ওয়া মিনকুম। হাল আন্তা জাদীদুন হুনা?","en":"minnaa wa minkum. hal anta jadeedun hunaa?"},"mean":{"bn":"আমাদের ও আপনাদের থেকে। আপনি কি এখানে নতুন?","en":"From us and from you. Are you new here?"}},{"title":{"bn":"ইউসুফ","en":"Yusuf"},"ar":"نَعَمْ، أَنَا طَالِبٌ جَدِيدٌ مِنْ بَنْغْلَادِيشَ.","tr":{"bn":"না'আম, আনা তালিবুন জাদীদুন মিন বাংলাদেশ।","en":"na'am, ana ṭaalibun jadeedun min banghlaadeesh."},"mean":{"bn":"জি, আমি বাংলাদেশ থেকে আসা নতুন ছাত্র।","en":"Yes, I am a new student from Bangladesh."}},{"title":{"bn":"ইমরান","en":"Imran"},"ar":"أَهْلًا وَسَهْلًا بِكَ!","tr":{"bn":"আহলান ওয়া সাহলান বিকা!","en":"ahlan wa sahlan bika!"},"mean":{"bn":"আপনাকে স্বাগতম!","en":"Welcome to you!"}},{"title":{"bn":"ইউসুফ","en":"Yusuf"},"ar":"مَتَى دَرْسُ الْقُرْآنِ؟","tr":{"bn":"মাতা দারসুল কুরআন?","en":"mataa darsul-qurʾaan?"},"mean":{"bn":"কুরআনের ক্লাস কখন?","en":"When is the Quran class?"}},{"title":{"bn":"ইমরান","en":"Imran"},"ar":"كُلَّ يَوْمٍ بَعْدَ صَلَاةِ الْمَغْرِبِ.","tr":{"bn":"কুল্লা ইয়াওমিন বা'দা সালাতিল মাগরিব।","en":"kulla yawmin ba'da ṣalaatil-maghrib."},"mean":{"bn":"প্রতিদিন মাগরিবের নামাজের পর।","en":"Every day after the Maghrib prayer."}},{"title":{"bn":"ইউসুফ","en":"Yusuf"},"ar":"جَزَاكَ اللّٰهُ خَيْرًا.","tr":{"bn":"জাযাকাল্লাহু খাইরান।","en":"jazaakallaahu khayran."},"mean":{"bn":"আল্লাহ আপনাকে উত্তম প্রতিদান দিন।","en":"May Allah reward you with good."}},{"title":{"bn":"ইমরান","en":"Imran"},"ar":"وَإِيَّاكَ. أَرَاكَ فِي الدَّرْسِ إِنْ شَاءَ اللّٰهُ.","tr":{"bn":"ওয়া ইয়্যাকা। আরাকা ফিদ দারসি ইন শা আল্লাহ।","en":"wa iyyaaka. araaka fid-darsi in shaaʾallaah."},"mean":{"bn":"আপনাকেও। ক্লাসে দেখা হবে, ইন শা আল্লাহ।","en":"And you. See you in class, if Allah wills."}}]},{"type":"steps","title":{"bn":"সংলাপ ২: দুই বান্ধবীর দেখা","en":"Dialogue 2: Two friends meet"},"items":[{"title":{"bn":"মারইয়াম","en":"Maryam"},"ar":"السَّلَامُ عَلَيْكُمْ يَا عَائِشَةُ!","tr":{"bn":"আস্‌সালামু আলাইকুম ইয়া আয়িশাহ!","en":"as-salaamu 'alaykum yaa 'aaʾishah!"},"mean":{"bn":"আসসালামু আলাইকুম, আয়েশা!","en":"Peace be upon you, Aishah!"}},{"title":{"bn":"আয়েশা","en":"Aishah"},"ar":"وَعَلَيْكُمُ السَّلَامُ يَا مَرْيَمُ! كَيْفَ حَالُكِ؟","tr":{"bn":"ওয়া আলাইকুমুস সালাম ইয়া মারইয়াম! কাইফা হালুকি?","en":"wa 'alaykumus-salaam yaa maryam! kayfa ḥaaluki?"},"mean":{"bn":"ওয়ালাইকুমুস সালাম, মারইয়াম! কেমন আছ?","en":"And upon you be peace, Maryam! How are you?"}},{"title":{"bn":"মারইয়াম","en":"Maryam"},"ar":"بِخَيْرٍ، وَالْحَمْدُ لِلّٰهِ. وَأَنْتِ؟","tr":{"bn":"বিখাইর, ওয়াল হামদু লিল্লাহ। ওয়া আন্তি?","en":"bikhayr, wal-ḥamdu lillaah. wa anti?"},"mean":{"bn":"ভালো, আলহামদুলিল্লাহ। আর তুমি?","en":"Well, praise be to Allah. And you?"}},{"title":{"bn":"আয়েশা","en":"Aishah"},"ar":"الْحَمْدُ لِلّٰهِ. أَيْنَ تَذْهَبِينَ؟","tr":{"bn":"আলহামদু লিল্লাহ। আইনা তাযহাবীন?","en":"al-ḥamdu lillaah. ayna tadhhabeen?"},"mean":{"bn":"আলহামদুলিল্লাহ। কোথায় যাচ্ছ?","en":"Praise be to Allah. Where are you going?"}},{"title":{"bn":"মারইয়াম","en":"Maryam"},"ar":"أَذْهَبُ إِلَى الْمَدْرَسَةِ. وَأَنْتِ؟","tr":{"bn":"আযহাবু ইলাল মাদরাসাহ। ওয়া আন্তি?","en":"adhhabu ilal-madrasah. wa anti?"},"mean":{"bn":"মাদ্রাসায় যাচ্ছি। আর তুমি?","en":"I'm going to school. And you?"}},{"title":{"bn":"আয়েশা","en":"Aishah"},"ar":"أَذْهَبُ إِلَى السُّوقِ مَعَ أُمِّي.","tr":{"bn":"আযহাবু ইলাস সূকি মাআ উম্মী।","en":"adhhabu ilas-sooqi ma'a ummee."},"mean":{"bn":"আম্মুর সাথে বাজারে যাচ্ছি।","en":"I'm going to the market with my mother."}},{"title":{"bn":"মারইয়াম","en":"Maryam"},"ar":"إِلَى اللِّقَاءِ غَدًا، إِنْ شَاءَ اللّٰهُ.","tr":{"bn":"ইলাল লিকাই গাদান, ইন শা আল্লাহ।","en":"ilal-liqaaʾi ghadan, in shaaʾallaah."},"mean":{"bn":"কাল দেখা হবে, ইন শা আল্লাহ।","en":"See you tomorrow, if Allah wills."}},{"title":{"bn":"আয়েশা","en":"Aishah"},"ar":"مَعَ السَّلَامَةِ!","tr":{"bn":"মাআস সালামাহ!","en":"ma'as-salaamah!"},"mean":{"bn":"আল্লাহ হাফেজ!","en":"Goodbye!"}}]},{"type":"tip","kind":"tip","bn":"সংলাপ ২-এ দুজনই মেয়ে, তাই খেয়াল করুন: {{حَالُكِ}}, {{أَنْتِ}}, {{تَذْهَبِينَ}} — সবখানে মেয়ে-রূপ। ছেলে হলে হতো {{حَالُكَ}}, {{أَنْتَ}}, {{تَذْهَبُ}}।","en":"In dialogue 2 both speakers are girls, so notice: {{حَالُكِ}}, {{أَنْتِ}}, {{تَذْهَبِينَ}} — feminine forms throughout. For boys it would be {{حَالُكَ}}, {{أَنْتَ}}, {{تَذْهَبُ}}."},{"type":"steps","title":{"bn":"সংলাপ ৩: খেজুরের দোকানে","en":"Dialogue 3: At the date shop"},"items":[{"title":{"bn":"ক্রেতা","en":"Customer"},"ar":"السَّلَامُ عَلَيْكُمْ. هَلْ عِنْدَكَ تَمْرٌ؟","tr":{"bn":"আস্‌সালামু আলাইকুম। হাল ইনদাকা তামর?","en":"as-salaamu 'alaykum. hal 'indaka tamr?"},"mean":{"bn":"আসসালামু আলাইকুম। আপনার কাছে খেজুর আছে?","en":"Peace be upon you. Do you have dates?"}},{"title":{"bn":"বিক্রেতা","en":"Seller"},"ar":"وَعَلَيْكُمُ السَّلَامُ. نَعَمْ، عِنْدِي تَمْرٌ جَيِّدٌ.","tr":{"bn":"ওয়া আলাইকুমুস সালাম। না'আম, ইনদী তামরুন জাইয়িদ।","en":"wa 'alaykumus-salaam. na'am, 'indee tamrun jayyid."},"mean":{"bn":"ওয়ালাইকুমুস সালাম। জি, আমার কাছে ভালো খেজুর আছে।","en":"And upon you be peace. Yes, I have good dates."}},{"title":{"bn":"ক্রেতা","en":"Customer"},"ar":"بِكَمِ الْكِيلُو؟","tr":{"bn":"বিকামিল কীলূ?","en":"bikamil-keeloo?"},"mean":{"bn":"এক কেজি কত?","en":"How much per kilo?"}},{"title":{"bn":"বিক্রেতা","en":"Seller"},"ar":"الْكِيلُو بِعِشْرِينَ رِيَالًا.","tr":{"bn":"আল-কীলূ বি-ইশরীনা রিয়ালা।","en":"al-keeloo bi-'ishreena riyaalan."},"mean":{"bn":"কেজি বিশ রিয়াল।","en":"Twenty riyals a kilo."}},{"title":{"bn":"ক্রেতা","en":"Customer"},"ar":"هٰذَا غَالٍ! هَلْ عِنْدَكَ تَمْرٌ أَرْخَصُ؟","tr":{"bn":"হাযা গালিন! হাল ইনদাকা তামরুন আরখাস?","en":"haadhaa ghaalin! hal 'indaka tamrun arkhaṣ?"},"mean":{"bn":"এটা তো দামি! আরও সস্তা খেজুর আছে?","en":"That's expensive! Do you have cheaper dates?"}},{"title":{"bn":"বিক্রেতা","en":"Seller"},"ar":"نَعَمْ، هٰذَا بِخَمْسَةَ عَشَرَ رِيَالًا.","tr":{"bn":"না'আম, হাযা বি-খামসাতা আশারা রিয়ালা।","en":"na'am, haadhaa bi-khamsata 'ashara riyaalan."},"mean":{"bn":"জি, এটা পনেরো রিয়াল।","en":"Yes, this one is fifteen riyals."}},{"title":{"bn":"ক্রেতা","en":"Customer"},"ar":"أَعْطِنِي كِيلُو مِنْ هٰذَا، مِنْ فَضْلِكَ.","tr":{"bn":"আ'তিনী কীলূ মিন হাযা, মিন ফাদলিক।","en":"a'ṭinee keeloo min haadhaa, min faḍlik."},"mean":{"bn":"দয়া করে এটা থেকে এক কেজি দিন।","en":"Give me a kilo of this, please."}},{"title":{"bn":"বিক্রেতা","en":"Seller"},"ar":"تَفَضَّلْ.","tr":{"bn":"তাফাদ্দাল।","en":"tafaḍḍal."},"mean":{"bn":"এই নিন।","en":"Here you are."}},{"title":{"bn":"ক্রেতা","en":"Customer"},"ar":"شُكْرًا، بَارَكَ اللّٰهُ فِيكَ.","tr":{"bn":"শুকরান, বারাকাল্লাহু ফীক।","en":"shukran, baarakallaahu feek."},"mean":{"bn":"ধন্যবাদ, আল্লাহ আপনাকে বরকত দিন।","en":"Thank you, may Allah bless you."}},{"title":{"bn":"বিক্রেতা","en":"Seller"},"ar":"وَفِيكَ بَارَكَ اللّٰهُ.","tr":{"bn":"ওয়া ফীকা বারাকাল্লাহ।","en":"wa feeka baarakallaah."},"mean":{"bn":"আপনাকেও আল্লাহ বরকত দিন।","en":"And may Allah bless you too."}}]},{"type":"tip","kind":"memory","bn":"{{تَفَضَّلْ}} একটা জাদুর শব্দ! কিছু এগিয়ে দিতে (“এই নিন”), কাউকে ভেতরে ডাকতে (“আসুন”) বা বসতে বলতে (“বসুন”) — সব জায়গায় চলে। মেয়েকে বললে {{تَفَضَّلِي}}।","en":"{{تَفَضَّلْ}} is a magic word! Use it when handing something over (“here you are”), inviting someone in (“come in”) or offering a seat (“please sit”). To a female: {{تَفَضَّلِي}}."},{"type":"vocab","title":{"bn":"ক্লাসের দরকারি বাক্য","en":"Useful classroom phrases"},"items":[{"ar":"أَعِدْ مِنْ فَضْلِكَ","tr":{"bn":"আ'ইদ মিন ফাদলিক","en":"a'id min faḍlik"},"mean":{"bn":"আবার বলুন, দয়া করে","en":"Repeat, please"}},{"ar":"لَا أَفْهَمُ","tr":{"bn":"লা আফহাম","en":"laa afham"},"mean":{"bn":"আমি বুঝতে পারছি না","en":"I don't understand"}},{"ar":"فَهِمْتُ","tr":{"bn":"ফাহিমতু","en":"fahimtu"},"mean":{"bn":"বুঝেছি","en":"I understood"}},{"ar":"مَا مَعْنَى ...؟","tr":{"bn":"মা মা'না ...?","en":"maa ma'naa ...?"},"mean":{"bn":"... এর অর্থ কী?","en":"What is the meaning of ...?"}},{"ar":"كَيْفَ أَقُولُ ... بِالْعَرَبِيَّةِ؟","tr":{"bn":"কাইফা আকূলু ... বিল আরাবিয়্যাহ?","en":"kayfa aqoolu ... bil-'arabiyyah?"},"mean":{"bn":"আরবিতে ... কীভাবে বলব?","en":"How do I say ... in Arabic?"}},{"ar":"تَكَلَّمْ بِبُطْءٍ مِنْ فَضْلِكَ","tr":{"bn":"তাকাল্লাম বিবুত'ইন মিন ফাদলিক","en":"takallam bibuṭʾin min faḍlik"},"mean":{"bn":"দয়া করে আস্তে বলুন","en":"Please speak slowly"}},{"ar":"عِنْدِي سُؤَالٌ","tr":{"bn":"ইনদী সুআল","en":"'indee suʾaal"},"mean":{"bn":"আমার একটা প্রশ্ন আছে","en":"I have a question"}},{"ar":"هَلْ هٰذَا صَحِيحٌ؟","tr":{"bn":"হাল হাযা সাহীহ?","en":"hal haadhaa ṣaḥeeḥ?"},"mean":{"bn":"এটা কি ঠিক?","en":"Is this correct?"}},{"ar":"لَا أَعْرِفُ","tr":{"bn":"লা আ'রিফ","en":"laa a'rif"},"mean":{"bn":"আমি জানি না","en":"I don't know"}},{"ar":"نَعَمْ","tr":{"bn":"না'আম","en":"na'am"},"mean":{"bn":"হ্যাঁ, জি","en":"yes"}},{"ar":"لَا","tr":{"bn":"লা","en":"laa"},"mean":{"bn":"না","en":"no"}},{"ar":"آسِفٌ","tr":{"bn":"আসিফ","en":"aasif"},"mean":{"bn":"দুঃখিত","en":"sorry"}},{"ar":"اِقْرَأْ","tr":{"bn":"ইকরা","en":"iqraʾ"},"mean":{"bn":"পড়ো!","en":"Read!"},"example":{"ar":"اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ","mean":{"bn":"পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন","en":"Read in the name of your Lord who created"},"ref":"96:1"}},{"ar":"اُكْتُبْ","tr":{"bn":"উকতুব","en":"uktub"},"mean":{"bn":"লেখো!","en":"Write!"},"root":"ك ت ب"},{"ar":"اِسْمَعْ","tr":{"bn":"ইসমা'","en":"isma'"},"mean":{"bn":"শোনো!","en":"Listen!"}}]},{"type":"tip","kind":"fun","bn":"কুরআনের সবচেয়ে প্রথম নাজিল হওয়া শব্দটি কী জানেন? {{اقْرَأْ}} — “পড়ো!” তাই আরবি পড়তে শেখা মানে কুরআনের প্রথম আদেশটাই মেনে চলা।","en":"Do you know the very first word of the Quran to be revealed? {{اقْرَأْ}} — “Read!” So learning to read Arabic means following the Quran's very first command."},{"type":"practice","bn":"সঙ্গীর সাথে অভিনয় করুন: প্রথমে একজন প্রশ্ন করবে, অন্যজন নিজের কথা দিয়ে উত্তর দেবে।","en":"Role-play with a partner: one asks, the other answers with their own details.","lines":["السَّلَامُ عَلَيْكُمْ — وَعَلَيْكُمُ السَّلَامُ","كَيْفَ حَالُكَ؟ — أَنَا بِخَيْرٍ، وَالْحَمْدُ لِلّٰهِ","مَا اسْمُكَ؟ — اِسْمِي ...","مِنْ أَيْنَ أَنْتَ؟ — أَنَا مِنْ بَنْغْلَادِيشَ","بِكَمْ هٰذَا؟ — بِعِشْرِينَ رِيَالًا","مَعَ السَّلَامَةِ — إِلَى اللِّقَاءِ"]},{"type":"quiz","items":[{"q":{"bn":"নামাজের পর কেউ বলল {{تَقَبَّلَ اللّٰهُ}}। উত্তরে কী বলা হয়?","en":"After prayer someone says {{تَقَبَّلَ اللّٰهُ}}. What is the reply?"},"options":["مِنَّا وَمِنْكُمْ","صَبَاحُ النُّورِ","بِكَمْ هٰذَا؟"],"answer":0},{"q":{"bn":"শিক্ষক খুব দ্রুত বলছেন। আপনি কী বলবেন?","en":"The teacher is speaking too fast. What do you say?"},"options":["تَكَلَّمْ بِبُطْءٍ مِنْ فَضْلِكَ","أَنَا جَائِعٌ","هٰذَا غَالٍ"],"answer":0},{"q":{"bn":"একটি শব্দের অর্থ জানতে চাইলে কোনটি বলবেন?","en":"To ask what a word means, you say:"},"options":["مَا اسْمُكَ؟","مَا مَعْنَى ...؟","مِنْ أَيْنَ أَنْتَ؟"],"answer":1},{"q":{"bn":"সংলাপ ৩-এ সস্তা খেজুরের দাম কত?","en":"In dialogue 3, how much were the cheaper dates?"},"options":[{"bn":"২০ রিয়াল","en":"20 riyals"},{"bn":"১৫ রিয়াল","en":"15 riyals"},{"bn":"৫০ রিয়াল","en":"50 riyals"}],"answer":1},{"q":{"bn":"একজন মেয়েকে “কোথায় যাচ্ছ?” জিজ্ঞেস করতে কোনটি?","en":"To ask a girl “Where are you going?”:"},"options":["أَيْنَ تَذْهَبُ؟","أَيْنَ تَذْهَبِينَ؟","أَيْنَ الْمَسْجِدُ؟"],"answer":1},{"q":{"bn":"{{لَا أَفْهَمُ}} মানে কী?","en":"What does {{لَا أَفْهَمُ}} mean?"},"options":[{"bn":"আমি জানি না","en":"I don't know"},{"bn":"আমি বুঝতে পারছি না","en":"I don't understand"},{"bn":"আমি দুঃখিত","en":"I'm sorry"}],"answer":1},{"q":{"bn":"দোকানদার জিনিস এগিয়ে দিয়ে কোন শব্দ বলে?","en":"Which word does the seller say when handing over the goods?"},"options":["تَفَضَّلْ","آسِفٌ","اِسْمَعْ"],"answer":0},{"q":{"bn":"কুরআনের প্রথম নাজিল হওয়া শব্দ কোনটি?","en":"Which was the first revealed word of the Quran?"},"options":["اُكْتُبْ","اقْرَأْ","اِسْمَعْ"],"answer":1}]}]}]});
AQ.units.push({"id":"quran","order":7,"icon":"۝","color":"violet","title":{"bn":"কুরআন ও সালাত বুঝে পড়ি","en":"Quran & Salah with Meaning"},"subtitle":{"bn":"নামাজ, ছোট সূরা আর প্রতিদিনের দোয়া — শব্দে শব্দে অর্থসহ","en":"Salah, short surahs and daily duas — word by word"},"lessons":[{"id":"quran-wudu-adhan","icon":"أذان","title":{"bn":"ওযু ও আযান","en":"Wudu & the Adhan"},"subtitle":{"bn":"ওযুর দোয়া, আযান-ইকামতের প্রতিটি বাক্যের অর্থ","en":"The wudu dua and the meaning of every adhan & iqamah phrase"},"minutes":15,"goals":[{"bn":"ওযুর শুরুতে ও শেষে কী বলতে হয় তা অর্থসহ জানব","en":"Know what to say before and after wudu, with meaning"},{"bn":"আযানের প্রতিটি বাক্য শব্দে শব্দে বুঝব","en":"Understand every phrase of the adhan word by word"},{"bn":"ইকামত ও আযানের পার্থক্য জানব","en":"Know how the iqamah differs from the adhan"},{"bn":"আযানের জবাব ও আযানের পরের দোয়া শিখব","en":"Learn how to answer the adhan and the dua after it"}],"blocks":[{"type":"text","bn":"এতদিন আমরা হরফ, হরকত, তাজবীদ আর শব্দ শিখেছি। এখন সেই সব কাজে লাগানোর সময়! এই ইউনিটে আমরা প্রতিদিন যা পড়ি — নামাজ, ছোট সূরা, দোয়া — সেগুলো **বুঝে** পড়া শিখব। শুরু করি নামাজের প্রস্তুতি দিয়ে: ওযু আর আযান।","en":"So far we learned letters, vowels, tajweed and words. Now it is time to use them! In this unit we learn to **understand** what we recite every day — salah, short surahs and duas. We begin with getting ready for salah: wudu and the adhan."},{"type":"steps","title":{"bn":"ওযু — সংক্ষেপে","en":"Wudu — in brief"},"items":[{"title":{"bn":"নিয়ত ও বিসমিল্লাহ","en":"Intention & Bismillah"},"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লাহ","en":"Bismillaah"},"mean":{"bn":"আল্লাহর নামে (শুরু করছি)","en":"In the name of Allah (I begin)"},"desc":{"bn":"মনে মনে ঠিক করি — আমি পবিত্র হচ্ছি আল্লাহর জন্য।","en":"Intend in your heart that you are purifying yourself for Allah."}},{"title":{"bn":"হাত, মুখ, নাক","en":"Hands, mouth, nose"},"desc":{"bn":"দুই হাত কবজি পর্যন্ত ধুই, কুলি করি, নাকে পানি দিয়ে পরিষ্কার করি — সাধারণত তিনবার করে।","en":"Wash both hands to the wrists, rinse the mouth, and rinse the nose — usually three times each."}},{"title":{"bn":"চেহারা ও দুই হাত","en":"Face & arms"},"desc":{"bn":"পুরো মুখমণ্ডল ধুই, তারপর ডান হাত ও বাম হাত কনুইসহ ধুই।","en":"Wash the whole face, then the right and left arms up to and including the elbows."}},{"title":{"bn":"মাথা মাসেহ ও পা","en":"Wipe the head & wash the feet"},"desc":{"bn":"ভেজা হাতে মাথা ও কান মাসেহ করি, তারপর দুই পা টাখনুসহ ধুই।","en":"Wipe the head and ears with wet hands, then wash both feet up to and including the ankles."}}]},{"type":"examples","title":{"bn":"ওযুর পরের দোয়া","en":"The dua after wudu"},"items":[{"ar":"أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tr":{"bn":"আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান 'আবদুহু ওয়া রাসূলুহু","en":"Ash-hadu al-laa ilaaha illallaahu waḥdahu laa shareeka lah, wa ash-hadu anna Muḥammadan 'abduhu wa rasooluh"},"mean":{"bn":"আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একা, তাঁর কোনো শরিক নেই; আর আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসূল।","en":"I bear witness that there is no god but Allah, alone, with no partner; and I bear witness that Muhammad ﷺ is His servant and His Messenger."},"note":{"bn":"সহীহ মুসলিমে আছে।","en":"Reported in Sahih Muslim."}},{"ar":"اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ","tr":{"bn":"আল্লাহুম্মাজ'আলনী মিনাত তাওয়াবীনা ওয়াজ'আলনী মিনাল মুতাতাহহিরীন","en":"Allaahummaj-'alnee minat-tawwaabeena waj-'alnee minal-mutaṭahhireen"},"mean":{"bn":"হে আল্লাহ! আমাকে তাওবাকারীদের অন্তর্ভুক্ত করুন এবং পবিত্রতা অর্জনকারীদের অন্তর্ভুক্ত করুন।","en":"O Allah, make me among those who turn back to You often, and make me among those who keep themselves pure."},"note":{"bn":"তিরমিযীর বর্ণনায় এই অংশটি অতিরিক্ত আছে।","en":"This addition comes in the narration of at-Tirmidhi."}}]},{"type":"table","title":{"bn":"শব্দে শব্দে","en":"Word by word"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["أَشْهَدُ",{"bn":"আমি সাক্ষ্য দিই","en":"I bear witness"}],["أَنْ لَا إِلٰهَ",{"bn":"যে, কোনো ইলাহ (উপাস্য) নেই","en":"that there is no god"}],["إِلَّا اللّٰهُ",{"bn":"আল্লাহ ছাড়া","en":"except Allah"}],["وَحْدَهُ",{"bn":"তিনি একা","en":"He alone"}],["لَا شَرِيكَ لَهُ",{"bn":"তাঁর কোনো শরিক নেই","en":"He has no partner"}],["عَبْدُهُ",{"bn":"তাঁর বান্দা","en":"His servant"}],["وَرَسُولُهُ",{"bn":"ও তাঁর রাসূল","en":"and His Messenger"}]]},{"type":"tip","kind":"fun","bn":"রাসূলুল্লাহ ﷺ বলেছেন: যে সুন্দর করে ওযু করে এই সাক্ষ্যটি পড়ে, তার জন্য জান্নাতের আটটি দরজাই খুলে দেওয়া হয় — যেটি দিয়ে ইচ্ছা সে প্রবেশ করবে। (সহীহ মুসলিম) ছোট্ট একটা দোয়া, কত বড় পুরস্কার!","en":"The Prophet ﷺ said: whoever performs wudu well and then says this testimony, all eight gates of Paradise are opened for him — he may enter by whichever he wishes. (Sahih Muslim) A tiny dua, a huge reward!"},{"type":"text","title":{"bn":"আযান — নামাজের ডাক","en":"The Adhan — the call to prayer"},"bn":"দিনে পাঁচবার মসজিদ থেকে আযান ভেসে আসে। এর প্রতিটি বাক্য আসলে একটি ছোট্ট বার্তা। চলো, বাক্যগুলো অর্থসহ দেখি।","en":"Five times a day the adhan rings out from the masjid. Every phrase is a short message. Let us see each phrase with its meaning."},{"type":"steps","title":{"bn":"আযানের বাক্যগুলো","en":"The phrases of the adhan"},"items":[{"title":{"bn":"৪ বার","en":"4 times"},"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"Allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},"desc":{"bn":"{{اللّٰهُ}} = আল্লাহ, {{أَكْبَرُ}} = সবচেয়ে বড় / সর্বশ্রেষ্ঠ। যা কিছুতে ব্যস্ত আছি, আল্লাহ তার চেয়েও বড়!","en":"{{اللّٰهُ}} = Allah, {{أَكْبَرُ}} = greatest. Whatever keeps us busy, Allah is greater!"}},{"title":{"bn":"২ বার","en":"2 times"},"ar":"أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ","tr":{"bn":"আশহাদু আল লা-ইলাহা ইল্লাল্লাহ","en":"Ash-hadu al-laa ilaaha illallaah"},"mean":{"bn":"আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই","en":"I bear witness that there is no god but Allah"},"desc":{"bn":"{{أَشْهَدُ}} = আমি সাক্ষ্য দিই, {{لَا إِلٰهَ}} = কোনো ইলাহ নেই, {{إِلَّا}} = ছাড়া।","en":"{{أَشْهَدُ}} = I testify, {{لَا إِلٰهَ}} = no god, {{إِلَّا}} = except."}},{"title":{"bn":"২ বার","en":"2 times"},"ar":"أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ","tr":{"bn":"আশহাদু আন্না মুহাম্মাদার রাসূলুল্লাহ","en":"Ash-hadu anna Muḥammadar-Rasoolullaah"},"mean":{"bn":"আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ আল্লাহর রাসূল","en":"I bear witness that Muhammad ﷺ is the Messenger of Allah"},"desc":{"bn":"{{أَنَّ}} = যে, নিশ্চয়ই; {{رَسُولُ اللّٰهِ}} = আল্লাহর রাসূল (বার্তাবাহক)।","en":"{{أَنَّ}} = that (indeed); {{رَسُولُ اللّٰهِ}} = the Messenger of Allah."}},{"title":{"bn":"২ বার","en":"2 times"},"ar":"حَيَّ عَلَى الصَّلَاةِ","tr":{"bn":"হাইয়্যা 'আলাস সালাহ","en":"Ḥayya 'alaṣ-ṣalaah"},"mean":{"bn":"নামাজের দিকে এসো","en":"Come to the prayer"},"desc":{"bn":"{{حَيَّ عَلَى}} = দ্রুত এসো, {{الصَّلَاةِ}} = নামাজ/সালাত।","en":"{{حَيَّ عَلَى}} = hurry to, come to; {{الصَّلَاةِ}} = the prayer."}},{"title":{"bn":"২ বার","en":"2 times"},"ar":"حَيَّ عَلَى الْفَلَاحِ","tr":{"bn":"হাইয়্যা 'আলাল ফালাহ","en":"Ḥayya 'alal-falaaḥ"},"mean":{"bn":"সফলতার দিকে এসো","en":"Come to success"},"desc":{"bn":"{{الْفَلَاحِ}} = সফলতা, কল্যাণ। লক্ষ করো — নামাজের ডাকের ঠিক পরেই সফলতার ডাক! নামাজই আসল সফলতার পথ।","en":"{{الْفَلَاحِ}} = success, true prosperity. Notice: the call to prayer is followed by the call to success — prayer is the road to real success."}},{"title":{"bn":"শুধু ফজরে, ২ বার","en":"Fajr only, 2 times"},"ar":"الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ","tr":{"bn":"আসসালাতু খাইরুম মিনান নাওম","en":"Aṣ-ṣalaatu khayrum minan-nawm"},"mean":{"bn":"ঘুমের চেয়ে নামাজ উত্তম","en":"Prayer is better than sleep"},"desc":{"bn":"{{خَيْرٌ}} = উত্তম, {{مِنَ}} = চেয়ে / থেকে, {{النَّوْمِ}} = ঘুম।","en":"{{خَيْرٌ}} = better, {{مِنَ}} = than / from, {{النَّوْمِ}} = sleep."}},{"title":{"bn":"২ বার","en":"2 times"},"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"Allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"}},{"title":{"bn":"১ বার","en":"1 time"},"ar":"لَا إِلٰهَ إِلَّا اللّٰهُ","tr":{"bn":"লা-ইলাহা ইল্লাল্লাহ","en":"Laa ilaaha illallaah"},"mean":{"bn":"আল্লাহ ছাড়া কোনো ইলাহ নেই","en":"There is no god but Allah"},"desc":{"bn":"আযান শুরু হয় আল্লাহর বড়ত্ব দিয়ে, শেষ হয় তাওহীদ দিয়ে।","en":"The adhan begins with Allah's greatness and ends with tawheed (His oneness)."}}]},{"type":"steps","title":{"bn":"ইকামত — নামাজ দাঁড়ানোর ঘোষণা","en":"Iqamah — the call to stand"},"items":[{"title":{"bn":"আযানের মতোই, তবে…","en":"Like the adhan, but…"},"desc":{"bn":"জামাত শুরুর ঠিক আগে ইকামত দেওয়া হয়। বাক্যগুলো আযানের মতোই, শুধু {{حَيَّ عَلَى الْفَلَاحِ}}-এর পরে একটি নতুন বাক্য যোগ হয়। আমাদের দেশে (হানাফী মাযহাবে) ইকামতের বাক্যগুলো আযানের মতো জোড়ায় জোড়ায় বলা হয়; অন্য অনেক জায়গায় বেশিরভাগ বাক্য একবার করে বলা হয় — দুটিই হাদীসে আছে।","en":"The iqamah is given just before the congregation starts. Its phrases are like the adhan, with one new phrase after {{حَيَّ عَلَى الْفَلَاحِ}}. In Bangladesh (Hanafi school) the phrases are said in pairs like the adhan; in many other places most phrases are said once — both come from the Sunnah."}},{"title":{"bn":"নতুন বাক্য, ২ বার","en":"The new phrase, 2 times"},"ar":"قَدْ قَامَتِ الصَّلَاةُ","tr":{"bn":"কাদ কামাতিস সালাহ","en":"Qad qaamatiṣ-ṣalaah"},"mean":{"bn":"নামাজ শুরু হয়ে গেছে / দাঁড়িয়ে গেছে","en":"The prayer has begun / is now established"},"desc":{"bn":"{{قَدْ}} = অবশ্যই (হয়ে গেছে), {{قَامَتْ}} = দাঁড়িয়েছে / কায়েম হয়েছে, {{الصَّلَاةُ}} = নামাজ।","en":"{{قَدْ}} = indeed (has), {{قَامَتْ}} = has stood / been established, {{الصَّلَاةُ}} = the prayer."}}]},{"type":"tip","kind":"tip","title":{"bn":"আযানের জবাব","en":"Answering the adhan"},"bn":"মুয়াজ্জিন যা বলেন, আমরাও আস্তে আস্তে তাই বলি। শুধু {{حَيَّ عَلَى الصَّلَاةِ}} ও {{حَيَّ عَلَى الْفَلَاحِ}} শুনে বলি: {{لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ}} — ‘আল্লাহর সাহায্য ছাড়া কোনো শক্তি ও ক্ষমতা নেই।’ (সহীহ মুসলিম)","en":"Quietly repeat what the muezzin says. Only at {{حَيَّ عَلَى الصَّلَاةِ}} and {{حَيَّ عَلَى الْفَلَاحِ}} say: {{لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ}} — ‘There is no power and no strength except through Allah.’ (Sahih Muslim)"},{"type":"examples","title":{"bn":"আযানের পরের দোয়া","en":"The dua after the adhan"},"items":[{"ar":"اللّٰهُمَّ رَبَّ هٰذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ","tr":{"bn":"আল্লাহুম্মা রাব্বা হা-যিহিদ দা'ওয়াতিত তা-ম্মাহ, ওয়াস সালাতিল কা-ইমাহ, আ-তি মুহাম্মাদানিল ওয়াসীলাতা ওয়াল ফাদীলাহ, ওয়াব'আসহু মাকামাম মাহমূদানিল্লাযী ওয়া'আত্তাহ","en":"Allaahumma rabba haadhihid-da'watit-taammah, waṣ-ṣalaatil-qaa'imah, aati Muḥammadanil-waseelata wal-faḍeelah, wab'ath-hu maqaamam maḥmoodanil-ladhee wa'adtah"},"mean":{"bn":"হে আল্লাহ! এই পরিপূর্ণ আহ্বান ও আসন্ন নামাজের রব! মুহাম্মাদ ﷺ-কে ‘ওয়াসীলা’ (জান্নাতের বিশেষ মর্যাদা) ও শ্রেষ্ঠত্ব দান করুন, এবং তাঁকে সেই প্রশংসিত স্থানে পৌঁছে দিন, যার ওয়াদা আপনি তাঁকে দিয়েছেন।","en":"O Allah, Lord of this perfect call and of the prayer about to begin, grant Muhammad ﷺ al-Waseelah (a special rank in Paradise) and excellence, and raise him to the praised station You have promised him."},"note":{"bn":"সহীহ বুখারী। হাদীসে আছে, যে এই দোয়া পড়ে কিয়ামতের দিন সে নবী ﷺ-এর শাফা'আত পাবে।","en":"Sahih al-Bukhari. The hadith says whoever says it will receive the Prophet's ﷺ intercession on the Day of Judgement."}}]},{"type":"vocab","title":{"bn":"এই পাঠের শব্দ","en":"Words from this lesson"},"items":[{"ar":"أَكْبَرُ","tr":{"bn":"আকবার","en":"akbar"},"mean":{"bn":"সবচেয়ে বড়","en":"greatest"},"root":"ك ب ر"},{"ar":"أَشْهَدُ","tr":{"bn":"আশহাদু","en":"ash-hadu"},"mean":{"bn":"আমি সাক্ষ্য দিই","en":"I bear witness"},"root":"ش ه د"},{"ar":"الصَّلَاةُ","tr":{"bn":"আস-সালাহ","en":"aṣ-ṣalaah"},"mean":{"bn":"নামাজ","en":"the prayer"},"root":"ص ل و"},{"ar":"الْفَلَاحُ","tr":{"bn":"আল-ফালাহ","en":"al-falaaḥ"},"mean":{"bn":"সফলতা","en":"success"},"root":"ف ل ح"},{"ar":"خَيْرٌ","tr":{"bn":"খাইর","en":"khayr"},"mean":{"bn":"উত্তম, ভালো","en":"better, good"},"root":"خ ي ر"},{"ar":"النَّوْمُ","tr":{"bn":"আন-নাওম","en":"an-nawm"},"mean":{"bn":"ঘুম","en":"sleep"},"root":"ن و م"},{"ar":"رَسُولٌ","tr":{"bn":"রাসূল","en":"rasool"},"mean":{"bn":"বার্তাবাহক, রাসূল","en":"messenger"},"root":"ر س ل"}]},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"আযানে দুটি ডাক পাশাপাশি: ‘নামাজে এসো’, ‘সফলতায় এসো’। পরীক্ষা, খেলা, কাজ — যা-ই চলুক, আযান শুনলে মনে রাখি: আসল সফলতা ওদিকেই ডাকছে।","en":"Two calls stand side by side in the adhan: ‘come to prayer’, ‘come to success’. Exams, games, work — whatever is going on, when you hear the adhan remember: real success is calling from there."},{"type":"quiz","items":[{"q":{"bn":"{{الْفَلَاحِ}} শব্দের অর্থ কী?","en":"What does {{الْفَلَاحِ}} mean?"},"options":[{"bn":"সফলতা","en":"success"},{"bn":"ঘুম","en":"sleep"},{"bn":"নামাজ","en":"prayer"},{"bn":"সাক্ষ্য","en":"testimony"}],"answer":0},{"q":{"bn":"কোন বাক্যটি শুধু ফজরের আযানে বলা হয়?","en":"Which phrase is said only in the Fajr adhan?"},"options":["قَدْ قَامَتِ الصَّلَاةُ","الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ","حَيَّ عَلَى الْفَلَاحِ","اللّٰهُ أَكْبَرُ"],"answer":1},{"q":{"bn":"ইকামতে কোন বাক্যটি বাড়তি থাকে?","en":"Which phrase is added in the iqamah?"},"options":["لَا إِلٰهَ إِلَّا اللّٰهُ","أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ","قَدْ قَامَتِ الصَّلَاةُ"],"answer":2,"explain":{"bn":"{{قَدْ قَامَتِ الصَّلَاةُ}} — নামাজ শুরু হয়ে গেছে।","en":"{{قَدْ قَامَتِ الصَّلَاةُ}} — the prayer has begun."}},{"q":{"bn":"{{حَيَّ عَلَى الصَّلَاةِ}} শুনে জবাবে কী বলি?","en":"What do we reply when we hear {{حَيَّ عَلَى الصَّلَاةِ}}?"},"options":["سُبْحَانَ اللّٰهِ","لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ","الْحَمْدُ لِلّٰهِ"],"answer":1},{"q":{"bn":"{{أَشْهَدُ}} মানে কী?","en":"What does {{أَشْهَدُ}} mean?"},"options":[{"bn":"আমি সাক্ষ্য দিই","en":"I bear witness"},{"bn":"আমি ক্ষমা চাই","en":"I seek forgiveness"},{"bn":"আমি আশ্রয় চাই","en":"I seek refuge"}],"answer":0},{"q":{"bn":"আযানে {{اللّٰهُ أَكْبَرُ}} শুরুতে কতবার বলা হয়?","en":"How many times is {{اللّٰهُ أَكْبَرُ}} said at the start of the adhan?"},"options":["২ / 2","৩ / 3","৪ / 4"],"answer":2},{"q":{"bn":"ওযুর পরের দোয়ায় {{وَحْدَهُ لَا شَرِيكَ لَهُ}} অর্থ কী?","en":"In the dua after wudu, what does {{وَحْدَهُ لَا شَرِيكَ لَهُ}} mean?"},"options":[{"bn":"তিনি একা, তাঁর কোনো শরিক নেই","en":"He is alone, He has no partner"},{"bn":"তিনি দয়াময়, পরম দয়ালু","en":"He is the Most Merciful"},{"bn":"তিনি সবকিছু শোনেন","en":"He hears everything"}],"answer":0}]}]},{"id":"quran-salah-steps","icon":"صلاة","title":{"bn":"ধাপে ধাপে নামাজ","en":"Salah Step by Step"},"subtitle":{"bn":"দাঁড়ানো থেকে সালাম — প্রতিটি অবস্থানে কী পড়ি, কী বুঝি","en":"From standing to salam — what we say in each position, and what it means"},"minutes":20,"goals":[{"bn":"নামাজের প্রতিটি অবস্থান ক্রমানুসারে জানব","en":"Know every position of salah in order"},{"bn":"প্রতিটি অবস্থানের দোয়া/তাসবীহর অর্থ বুঝব","en":"Understand the dua or tasbih of each position"},{"bn":"রুকু ও সিজদার তাসবীহর পার্থক্য মনে রাখব","en":"Remember the difference between the ruku' and sujud tasbih"}],"blocks":[{"type":"text","bn":"নামাজ হলো আল্লাহর সাথে কথা বলা। কিন্তু কী বলছি তা না বুঝলে কথাটা যেন অর্ধেক থেকে যায়। এই পাঠে আমরা দুই রাকাত নামাজের প্রতিটি ধাপে কী পড়ি আর তার মানে কী — সেটা দেখব।","en":"Salah is a conversation with Allah. But if we do not understand what we say, the conversation feels half-done. In this lesson we walk through a two-rak'ah prayer and see what we say at each step and what it means."},{"type":"steps","title":{"bn":"দুই রাকাত নামাজ — শুরু থেকে শেষ","en":"A two-rak'ah salah — start to finish"},"items":[{"title":{"bn":"১. নিয়ত","en":"1. Niyyah (intention)"},"desc":{"bn":"কিবলামুখী দাঁড়িয়ে মনে মনে ঠিক করি কোন নামাজ পড়ছি। নিয়ত অন্তরের কাজ — নির্দিষ্ট আরবি বাক্য মুখে বলা জরুরি নয়।","en":"Stand facing the qiblah and decide in your heart which prayer you are offering. Niyyah is an act of the heart — no fixed Arabic sentence has to be spoken."}},{"title":{"bn":"২. তাকবীরে তাহরীমা","en":"2. Opening takbir"},"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"Allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},"desc":{"bn":"দুই হাত তুলে তাকবীর বলি। এখন থেকে দুনিয়ার সব কাজ ‘হারাম’ (বন্ধ) — তাই এর নাম ‘তাহরীমা’।","en":"Raise both hands and say the takbir. From now, all worldly actions are ‘forbidden’ (paused) — hence the name ‘tahreemah’."}},{"title":{"bn":"৩. সানা","en":"3. Thana (opening praise)"},"ar":"سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلٰهَ غَيْرُكَ","tr":{"bn":"সুবহানাকাল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তা'আলা জাদ্দুকা, ওয়া লা ইলাহা গাইরুক","en":"Subḥaanakallaahumma wa biḥamdika, wa tabaarakasmuka, wa ta'aalaa jadduka, wa laa ilaaha ghayruk"},"mean":{"bn":"হে আল্লাহ! আপনি পবিত্র, সব প্রশংসা আপনার; আপনার নাম বরকতময়, আপনার মর্যাদা সুউচ্চ, আর আপনি ছাড়া কোনো ইলাহ নেই।","en":"Glory be to You, O Allah, and all praise is Yours; blessed is Your Name, exalted is Your majesty, and there is no god besides You."},"desc":{"bn":"শব্দে শব্দে: {{سُبْحَانَكَ}} আপনি পবিত্র • {{وَبِحَمْدِكَ}} ও আপনার প্রশংসাসহ • {{تَبَارَكَ}} বরকতময় • {{اسْمُكَ}} আপনার নাম • {{تَعَالَى}} সুউচ্চ • {{جَدُّكَ}} আপনার মহিমা • {{غَيْرُكَ}} আপনি ছাড়া।","en":"Word by word: {{سُبْحَانَكَ}} glory to You • {{وَبِحَمْدِكَ}} and with Your praise • {{تَبَارَكَ}} blessed • {{اسْمُكَ}} Your name • {{تَعَالَى}} highly exalted • {{جَدُّكَ}} Your majesty • {{غَيْرُكَ}} other than You."}},{"title":{"bn":"৪. তা'আউয","en":"4. Ta'awwudh (seeking refuge)"},"ar":"أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":{"bn":"আ'ঊযু বিল্লাহি মিনাশ শাইতানির রাজীম","en":"A'oodhu billaahi minash-shayṭaanir-rajeem"},"mean":{"bn":"বিতাড়িত শয়তান থেকে আমি আল্লাহর আশ্রয় চাই","en":"I seek refuge in Allah from Satan, the rejected one"},"desc":{"bn":"{{أَعُوذُ}} আমি আশ্রয় চাই • {{بِاللّٰهِ}} আল্লাহর কাছে • {{مِنَ}} থেকে • {{الشَّيْطَانِ}} শয়তান • {{الرَّجِيمِ}} বিতাড়িত।","en":"{{أَعُوذُ}} I seek refuge • {{بِاللّٰهِ}} in Allah • {{مِنَ}} from • {{الشَّيْطَانِ}} Satan • {{الرَّجِيمِ}} the outcast."}},{"title":{"bn":"৫. বিসমিল্লাহ","en":"5. Basmalah"},"ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","tr":{"bn":"বিসমিল্লাহির রাহমানির রাহীম","en":"Bismillaahir-Raḥmaanir-Raḥeem"},"mean":{"bn":"পরম করুণাময়, অসীম দয়ালু আল্লাহর নামে","en":"In the name of Allah, the Most Compassionate, the Most Merciful"}},{"title":{"bn":"৬. সূরা ফাতিহা ও আমীন","en":"6. Al-Fatiha & Ameen"},"ar":"آمِين","tr":{"bn":"আ-মীন","en":"Aameen"},"mean":{"bn":"হে আল্লাহ, কবুল করুন","en":"O Allah, accept (our prayer)"},"desc":{"bn":"প্রতি রাকাতে সূরা ফাতিহা পড়ি (পুরো অর্থ পরের পাঠে আসছে), শেষে ‘আমীন’ বলি।","en":"Recite Surah Al-Fatiha in every rak'ah (full meaning in a coming lesson), then say ‘Ameen’."}},{"title":{"bn":"৭. আরেকটি সূরা","en":"7. Another surah"},"desc":{"bn":"প্রথম দুই রাকাতে ফাতিহার পর কুরআনের যেকোনো অংশ পড়ি — যেমন সূরা ইখলাস, কাওসার বা আসর। এগুলোর অর্থও আমরা এই ইউনিটে শিখব।","en":"In the first two rak'ahs, after Al-Fatiha, recite any part of the Quran — such as Al-Ikhlas, Al-Kawthar or Al-'Asr. We will learn their meanings in this unit too."}},{"title":{"bn":"৮. রুকু","en":"8. Ruku' (bowing)"},"ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","tr":{"bn":"সুবহানা রাব্বিয়াল 'আযীম","en":"Subḥaana rabbiyal-'aẓeem"},"mean":{"bn":"আমার মহান রব পবিত্র","en":"Glory be to my Lord, the Magnificent"},"desc":{"bn":"‘আল্লাহু আকবার’ বলে ঝুঁকে কমপক্ষে ৩ বার পড়ি। {{سُبْحَانَ}} পবিত্র • {{رَبِّيَ}} আমার রব • {{الْعَظِيمِ}} মহান।","en":"Say ‘Allaahu akbar’, bow, and say it at least 3 times. {{سُبْحَانَ}} glory • {{رَبِّيَ}} my Lord • {{الْعَظِيمِ}} the Magnificent."}},{"title":{"bn":"৯. রুকু থেকে ওঠা","en":"9. Rising from ruku'"},"ar":"سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ","tr":{"bn":"সামি'আল্লাহু লিমান হামিদাহ","en":"Sami'allaahu liman ḥamidah"},"mean":{"bn":"যে আল্লাহর প্রশংসা করে, আল্লাহ তার কথা শোনেন","en":"Allah hears whoever praises Him"},"desc":{"bn":"{{سَمِعَ}} শুনলেন/শোনেন • {{اللّٰهُ}} আল্লাহ • {{لِمَنْ}} তার কথা, যে • {{حَمِدَهُ}} তাঁর প্রশংসা করল।","en":"{{سَمِعَ}} hears • {{اللّٰهُ}} Allah • {{لِمَنْ}} the one who • {{حَمِدَهُ}} praised Him."}},{"title":{"bn":"১০. সোজা দাঁড়িয়ে","en":"10. Standing straight"},"ar":"رَبَّنَا وَلَكَ الْحَمْدُ","tr":{"bn":"রাব্বানা ওয়া লাকাল হামদ","en":"Rabbanaa wa lakal-ḥamd"},"mean":{"bn":"হে আমাদের রব! সব প্রশংসা আপনারই","en":"Our Lord, and to You belongs all praise"},"desc":{"bn":"এইমাত্র বললাম, ‘যে প্রশংসা করে, আল্লাহ তার কথা শোনেন’ — তাই সঙ্গে সঙ্গে প্রশংসা করি! {{رَبَّنَا لَكَ الْحَمْدُ}} রূপেও পড়া যায়।","en":"We just said ‘Allah hears whoever praises Him’ — so we praise Him right away! It may also be said as {{رَبَّنَا لَكَ الْحَمْدُ}}."}},{"title":{"bn":"১১. সিজদা","en":"11. Sujud (prostration)"},"ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى","tr":{"bn":"সুবহানা রাব্বিয়াল আ'লা","en":"Subḥaana rabbiyal-a'laa"},"mean":{"bn":"আমার সর্বোচ্চ রব পবিত্র","en":"Glory be to my Lord, the Most High"},"desc":{"bn":"‘আল্লাহু আকবার’ বলে সিজদায় গিয়ে কমপক্ষে ৩ বার পড়ি। {{الْأَعْلَى}} = সবার ঊর্ধ্বে। আমরা যখন সবচেয়ে নিচে, তখন বলি — আমার রব সবচেয়ে উঁচুতে!","en":"Say ‘Allaahu akbar’, go into sujud and say it at least 3 times. {{الْأَعْلَى}} = the Most High. When we are at our lowest, we declare: my Lord is the Highest!"}},{"title":{"bn":"১২. দুই সিজদার মাঝে বসা","en":"12. Sitting between the two sajdahs"},"ar":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي","tr":{"bn":"রাব্বিগফিরলী, রাব্বিগফিরলী","en":"Rabbighfir lee, rabbighfir lee"},"mean":{"bn":"হে আমার রব! আমাকে ক্ষমা করুন, হে আমার রব! আমাকে ক্ষমা করুন","en":"My Lord, forgive me; my Lord, forgive me"},"desc":{"bn":"{{رَبِّ}} হে আমার রব • {{اغْفِرْ}} ক্ষমা করুন • {{لِي}} আমাকে। চাইলে আরও পড়া যায়: {{اللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي}} — ক্ষমা করুন, দয়া করুন, সুস্থ রাখুন, পথ দেখান, রিযিক দিন।","en":"{{رَبِّ}} my Lord • {{اغْفِرْ}} forgive • {{لِي}} me. You may add: {{اللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي}} — forgive me, have mercy on me, keep me well, guide me, provide for me."}},{"title":{"bn":"১৩. দ্বিতীয় সিজদা ও দ্বিতীয় রাকাত","en":"13. Second sajdah & second rak'ah"},"desc":{"bn":"আবার সিজদা করে একই তাসবীহ পড়ি। তারপর উঠে দ্বিতীয় রাকাত — ফাতিহা, সূরা, রুকু, সিজদা — আগের মতোই (সানা আর পড়তে হয় না)।","en":"Prostrate again with the same tasbih. Then stand for the second rak'ah — Fatiha, a surah, ruku', sujud — just like before (the thana is not repeated)."}},{"title":{"bn":"১৪. তাশাহহুদ (আত্তাহিয়্যাতু)","en":"14. Tashahhud (at-taḥiyyaat)"},"ar":"التَّحِيَّاتُ لِلّٰهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللّٰهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tr":{"bn":"আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়্যিবাতু, আসসালামু 'আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ, আসসালামু 'আলাইনা ওয়া 'আলা 'ইবাদিল্লাহিস সালিহীন, আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়া আশহাদু আন্না মুহাম্মাদান 'আবদুহু ওয়া রাসূলুহ","en":"At-taḥiyyaatu lillaahi waṣ-ṣalawaatu waṭ-ṭayyibaat, as-salaamu 'alayka ayyuhan-nabiyyu wa raḥmatullaahi wa barakaatuh, as-salaamu 'alaynaa wa 'alaa 'ibaadillaahiṣ-ṣaaliḥeen, ash-hadu al-laa ilaaha illallaahu wa ash-hadu anna Muḥammadan 'abduhu wa rasooluh"},"mean":{"bn":"সব সম্মান, সব ইবাদত ও সব পবিত্র কথা আল্লাহর জন্য। হে নবী! আপনার উপর শান্তি, আল্লাহর রহমত ও বরকত। শান্তি আমাদের উপর এবং আল্লাহর নেক বান্দাদের উপর। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, এবং সাক্ষ্য দিচ্ছি, মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসূল।","en":"All greetings, prayers and good words are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and I bear witness that Muhammad ﷺ is His servant and Messenger."},"desc":{"bn":"দ্বিতীয় রাকাতের পর বসে পড়ি। শব্দে শব্দে অর্থ পরের পাঠে।","en":"Said while sitting after the second rak'ah. Word-by-word meaning in the next lesson."}},{"title":{"bn":"১৫. দরূদে ইবরাহীম","en":"15. Durood Ibrahim"},"ar":"اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللّٰهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ","tr":{"bn":"আল্লাহুম্মা সাল্লি 'আলা মুহাম্মাদিও ওয়া 'আলা আ-লি মুহাম্মাদ, কামা সাল্লাইতা 'আলা ইবরাহীমা ওয়া 'আলা আ-লি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক 'আলা মুহাম্মাদিও ওয়া 'আলা আ-লি মুহাম্মাদ, কামা বারাকতা 'আলা ইবরাহীমা ওয়া 'আলা আ-লি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ","en":"Allaahumma ṣalli 'alaa Muḥammadiw-wa 'alaa aali Muḥammad, kamaa ṣallayta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Ḥameedum Majeed. Allaahumma baarik 'alaa Muḥammadiw-wa 'alaa aali Muḥammad, kamaa baarakta 'alaa Ibraaheema wa 'alaa aali Ibraaheem, innaka Ḥameedum Majeed"},"mean":{"bn":"হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারের উপর রহমত বর্ষণ করুন, যেমন ইবরাহীম (আ.) ও তাঁর পরিবারের উপর করেছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও তাঁর পরিবারের উপর বরকত দিন, যেমন ইবরাহীম (আ.) ও তাঁর পরিবারের উপর দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।","en":"O Allah, send Your grace upon Muhammad ﷺ and the family of Muhammad, as You sent it upon Ibrahim and the family of Ibrahim; You are truly Praiseworthy, Glorious. O Allah, bless Muhammad ﷺ and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are truly Praiseworthy, Glorious."},"desc":{"bn":"শেষ বৈঠকে তাশাহহুদের পর পড়ি।","en":"Said in the final sitting, after the tashahhud."}},{"title":{"bn":"১৬. সালামের আগে দোয়া","en":"16. Dua before salam"},"ar":"اللّٰهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","tr":{"bn":"আল্লাহুম্মা ইন্নী যালামতু নাফসী যুলমান কাসীরাও ওয়া লা ইয়াগফিরুয যুনূবা ইল্লা আনতা, ফাগফিরলী মাগফিরাতাম মিন 'ইনদিকা ওয়ারহামনী, ইন্নাকা আনতাল গাফূরুর রাহীম","en":"Allaahumma innee ẓalamtu nafsee ẓulman katheeraw-wa laa yaghfirudh-dhunooba illaa ant, faghfir lee maghfiratam min 'indika warḥamnee, innaka antal-Ghafoorur-Raḥeem"},"mean":{"bn":"হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর আপনি ছাড়া কেউ গুনাহ মাফ করতে পারে না। তাই আপনার পক্ষ থেকে আমাকে ক্ষমা করুন এবং আমার প্রতি দয়া করুন; নিশ্চয়ই আপনি পরম ক্ষমাশীল, অতি দয়ালু।","en":"O Allah, I have wronged myself greatly, and none forgives sins but You. So forgive me with forgiveness from Yourself and have mercy on me; You are the Forgiving, the Merciful."},"desc":{"bn":"নবী ﷺ এই দোয়াটি আবু বকর (রা.)-কে নামাজে পড়ার জন্য শিখিয়েছিলেন। (বুখারী, মুসলিম)","en":"The Prophet ﷺ taught this dua to Abu Bakr (may Allah be pleased with him) to say in his prayer. (Bukhari, Muslim)"}},{"title":{"bn":"১৭. সালাম","en":"17. Taslim (ending with salam)"},"ar":"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ","tr":{"bn":"আসসালামু 'আলাইকুম ওয়া রাহমাতুল্লাহ","en":"As-salaamu 'alaykum wa raḥmatullaah"},"mean":{"bn":"তোমাদের উপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক","en":"Peace be upon you and the mercy of Allah"},"desc":{"bn":"প্রথমে ডানে, তারপর বামে মুখ ফিরিয়ে বলি। নামাজ শুরু হয়েছিল ‘আল্লাহু আকবার’ দিয়ে, শেষ হলো ‘শান্তি’ দিয়ে।","en":"Turn the face to the right, then to the left, saying it each time. Salah began with ‘Allah is the Greatest’ and ends with ‘peace’."}}]},{"type":"tip","kind":"memory","title":{"bn":"মনে রাখার কৌশল","en":"Memory trick"},"bn":"রুকুতে আমরা ঝুঁকে থাকি, তাই বলি রব **মহান** ({{الْعَظِيمِ}})। সিজদায় আমরা সবচেয়ে নিচে, তাই বলি রব **সর্বোচ্চ** ({{الْأَعْلَى}})। নিচু = আ'লা (উঁচু)!","en":"In ruku' we bow, so we say our Lord is **Magnificent** ({{الْعَظِيمِ}}). In sujud we are at our lowest, so we say our Lord is **Most High** ({{الْأَعْلَى}}). Lowest body = A'laa (Highest)!"},{"type":"table","title":{"bn":"এক নজরে","en":"At a glance"},"head":[{"bn":"অবস্থান","en":"Position"},{"bn":"কী বলি","en":"What we say"},{"bn":"অর্থ","en":"Meaning"}],"rows":[[{"bn":"দাঁড়ানো (কিয়াম)","en":"Standing (qiyam)"},"سُبْحَانَكَ اللّٰهُمَّ …",{"bn":"সানা, ফাতিহা, সূরা","en":"Thana, Fatiha, surah"}],[{"bn":"রুকু","en":"Ruku'"},"سُبْحَانَ رَبِّيَ الْعَظِيمِ",{"bn":"আমার মহান রব পবিত্র","en":"Glory to my Magnificent Lord"}],[{"bn":"রুকু থেকে ওঠা","en":"Rising"},"سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ",{"bn":"প্রশংসাকারীর কথা আল্লাহ শোনেন","en":"Allah hears the one who praises Him"}],[{"bn":"সোজা দাঁড়ানো","en":"Standing straight"},"رَبَّنَا وَلَكَ الْحَمْدُ",{"bn":"হে রব, সব প্রশংসা আপনার","en":"Our Lord, all praise is Yours"}],[{"bn":"সিজদা","en":"Sujud"},"سُبْحَانَ رَبِّيَ الْأَعْلَى",{"bn":"আমার সর্বোচ্চ রব পবিত্র","en":"Glory to my Lord Most High"}],[{"bn":"দুই সিজদার মাঝে","en":"Between sajdahs"},"رَبِّ اغْفِرْ لِي",{"bn":"হে রব, আমাকে ক্ষমা করুন","en":"My Lord, forgive me"}],[{"bn":"বৈঠক","en":"Sitting"},"التَّحِيَّاتُ لِلّٰهِ …",{"bn":"তাশাহহুদ, দরূদ, দোয়া","en":"Tashahhud, durood, dua"}],[{"bn":"শেষ","en":"End"},"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ",{"bn":"শান্তি ও রহমত","en":"Peace and mercy"}]]},{"type":"tip","kind":"tip","bn":"তিন বা চার রাকাতের নামাজে দ্বিতীয় রাকাতের পর শুধু তাশাহহুদ পড়ে উঠে দাঁড়াই; দরূদ ও দোয়া পড়ি একেবারে শেষ বৈঠকে। আর তৃতীয়-চতুর্থ রাকাতের ফরজে সাধারণত শুধু ফাতিহা পড়ি।","en":"In a three- or four-rak'ah prayer, after the second rak'ah we recite only the tashahhud and stand up; the durood and dua come in the final sitting. In the 3rd and 4th rak'ahs of a fard prayer we usually recite only Al-Fatiha."},{"type":"tip","kind":"fun","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"নবী ﷺ বলেছেন, বান্দা তার রবের সবচেয়ে কাছে থাকে যখন সে সিজদায় থাকে — তাই সিজদায় বেশি বেশি দোয়া করো। (সহীহ মুসলিম) মাথা যত নিচে, আল্লাহ তত কাছে।","en":"The Prophet ﷺ said a servant is closest to his Lord while in sujud, so make plenty of dua there. (Sahih Muslim) The lower the head, the nearer to Allah."},{"type":"quiz","items":[{"q":{"bn":"রুকুতে কোন তাসবীহ পড়ি?","en":"Which tasbih do we say in ruku'?"},"options":["سُبْحَانَ رَبِّيَ الْأَعْلَى","سُبْحَانَ رَبِّيَ الْعَظِيمِ","رَبِّ اغْفِرْ لِي"],"answer":1},{"q":{"bn":"{{الْأَعْلَى}} অর্থ কী?","en":"What does {{الْأَعْلَى}} mean?"},"options":[{"bn":"সর্বোচ্চ","en":"the Most High"},{"bn":"মহান","en":"the Magnificent"},{"bn":"দয়ালু","en":"the Merciful"}],"answer":0},{"q":{"bn":"{{سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ}} কখন বলি?","en":"When do we say {{سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ}}?"},"options":[{"bn":"সিজদায় যাওয়ার সময়","en":"Going into sujud"},{"bn":"রুকু থেকে ওঠার সময়","en":"Rising from ruku'"},{"bn":"সালাম ফেরানোর সময়","en":"When giving salam"}],"answer":1},{"q":{"bn":"দুই সিজদার মাঝে বসে কী বলি?","en":"What do we say sitting between the two sajdahs?"},"options":["رَبِّ اغْفِرْ لِي","آمِين","سُبْحَانَكَ اللّٰهُمَّ"],"answer":0},{"q":{"bn":"{{وَلَا إِلٰهَ غَيْرُكَ}} — এখানে {{غَيْرُكَ}} মানে কী?","en":"In {{وَلَا إِلٰهَ غَيْرُكَ}}, what does {{غَيْرُكَ}} mean?"},"options":[{"bn":"আপনার নাম","en":"Your name"},{"bn":"আপনি ছাড়া","en":"other than You"},{"bn":"আপনার প্রশংসা","en":"Your praise"}],"answer":1},{"q":{"bn":"নামাজ শেষ হয় কোন কথা দিয়ে?","en":"Which words end the salah?"},"options":["اللّٰهُ أَكْبَرُ","السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ","آمِين"],"answer":1},{"q":{"bn":"{{آمِين}} অর্থ কী?","en":"What does {{آمِين}} mean?"},"options":[{"bn":"হে আল্লাহ, কবুল করুন","en":"O Allah, accept"},{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},{"bn":"সব প্রশংসা আল্লাহর","en":"All praise is for Allah"}],"answer":0}]}]},{"id":"quran-tashahhud","icon":"تشهد","title":{"bn":"তাশাহহুদ, দরূদ ও শেষ দোয়া","en":"Tashahhud, Durood & Final Duas"},"subtitle":{"bn":"বৈঠকের দোয়াগুলো শব্দে শব্দে, আর নামাজের পরের যিকির","en":"The sitting duas word by word, plus remembrance after salah"},"minutes":18,"goals":[{"bn":"আত্তাহিয়্যাতু শব্দে শব্দে বুঝব","en":"Understand at-taḥiyyaat word by word"},{"bn":"দরূদে ইবরাহীমের অর্থ জানব","en":"Know the meaning of Durood Ibrahim"},{"bn":"সালামের আগের দোয়া ও নামাজের পরের যিকির শিখব","en":"Learn the dua before salam and the dhikr after salah"}],"blocks":[{"type":"text","bn":"নামাজের শেষ বৈঠকটা যেন একটা সুন্দর চিঠির শেষ অংশ: প্রথমে আল্লাহকে সম্মান, তারপর নবী ﷺ-কে সালাম, নিজের ও সব নেককারের জন্য শান্তি, ঈমানের সাক্ষ্য, নবীর জন্য দোয়া, আর শেষে নিজের জন্য ক্ষমা চাওয়া।","en":"The final sitting of salah is like the closing of a beautiful letter: first honour to Allah, then greetings to the Prophet ﷺ, peace for ourselves and all the righteous, the testimony of faith, prayers for the Prophet, and finally asking forgiveness for ourselves."},{"type":"table","title":{"bn":"তাশাহহুদ — শব্দে শব্দে","en":"Tashahhud — word by word"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["التَّحِيَّاتُ",{"bn":"সব সম্মান ও অভিবাদন","en":"all greetings and honours"}],["لِلّٰهِ",{"bn":"আল্লাহর জন্য","en":"are for Allah"}],["وَالصَّلَوَاتُ",{"bn":"এবং সব নামাজ/ইবাদত","en":"and all prayers"}],["وَالطَّيِّبَاتُ",{"bn":"এবং সব পবিত্র ভালো কথা ও কাজ","en":"and all pure, good things"}],["السَّلَامُ عَلَيْكَ",{"bn":"আপনার উপর শান্তি","en":"peace be upon you"}],["أَيُّهَا النَّبِيُّ",{"bn":"হে নবী","en":"O Prophet"}],["وَرَحْمَةُ اللّٰهِ",{"bn":"এবং আল্লাহর রহমত","en":"and the mercy of Allah"}],["وَبَرَكَاتُهُ",{"bn":"এবং তাঁর বরকত","en":"and His blessings"}],["السَّلَامُ عَلَيْنَا",{"bn":"আমাদের উপর শান্তি","en":"peace be upon us"}],["وَعَلَى عِبَادِ اللّٰهِ",{"bn":"এবং আল্লাহর বান্দাদের উপর","en":"and upon the servants of Allah"}],["الصَّالِحِينَ",{"bn":"যারা নেককার","en":"who are righteous"}],["أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ",{"bn":"আমি সাক্ষ্য দিই, আল্লাহ ছাড়া কোনো ইলাহ নেই","en":"I bear witness there is no god but Allah"}],["وَأَشْهَدُ أَنَّ مُحَمَّدًا",{"bn":"এবং সাক্ষ্য দিই যে মুহাম্মাদ ﷺ","en":"and I bear witness that Muhammad ﷺ"}],["عَبْدُهُ وَرَسُولُهُ",{"bn":"তাঁর বান্দা ও তাঁর রাসূল","en":"is His servant and His Messenger"}]]},{"type":"tip","kind":"fun","bn":"নবী ﷺ বলেছেন: যখন তোমরা বলো {{وَعَلَى عِبَادِ اللّٰهِ الصَّالِحِينَ}}, তখন আসমান ও জমিনের প্রত্যেক নেক বান্দার কাছে তা পৌঁছে যায়। (বুখারী, মুসলিম) প্রতিটি নামাজে তুমি পৃথিবীর সব ভালো মানুষের জন্য শান্তি পাঠাচ্ছ!","en":"The Prophet ﷺ said: when you say {{وَعَلَى عِبَادِ اللّٰهِ الصَّالِحِينَ}}, it reaches every righteous servant in the heavens and the earth. (Bukhari, Muslim) In every prayer you send peace to every good person in the world!"},{"type":"tip","kind":"tip","bn":"সাক্ষ্যের বাক্যে ({{أَشْهَدُ أَنْ لَا إِلٰهَ}}) পৌঁছে অনেকেই ডান হাতের শাহাদাত আঙুল দিয়ে ইশারা করে — এক আল্লাহর সাক্ষ্য।","en":"When reaching the testimony ({{أَشْهَدُ أَنْ لَا إِلٰهَ}}), many raise the right index finger — a sign of witnessing that Allah is One."},{"type":"table","title":{"bn":"দরূদে ইবরাহীম — শব্দে শব্দে","en":"Durood Ibrahim — word by word"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["اللّٰهُمَّ",{"bn":"হে আল্লাহ","en":"O Allah"}],["صَلِّ عَلَى مُحَمَّدٍ",{"bn":"মুহাম্মাদ ﷺ-এর উপর রহমত ও সম্মান বর্ষণ করুন","en":"send Your grace and honour upon Muhammad ﷺ"}],["وَعَلَى آلِ مُحَمَّدٍ",{"bn":"এবং মুহাম্মাদ ﷺ-এর পরিবারের উপর","en":"and upon the family of Muhammad"}],["كَمَا صَلَّيْتَ",{"bn":"যেমন আপনি রহমত বর্ষণ করেছেন","en":"just as You sent grace"}],["عَلَى إِبْرَاهِيمَ",{"bn":"ইবরাহীম (আ.)-এর উপর","en":"upon Ibrahim"}],["وَعَلَى آلِ إِبْرَاهِيمَ",{"bn":"এবং ইবরাহীম (আ.)-এর পরিবারের উপর","en":"and upon the family of Ibrahim"}],["إِنَّكَ",{"bn":"নিশ্চয়ই আপনি","en":"indeed You are"}],["حَمِيدٌ",{"bn":"প্রশংসিত","en":"Praiseworthy"}],["مَجِيدٌ",{"bn":"মহিমান্বিত","en":"Glorious"}],["اللّٰهُمَّ بَارِكْ",{"bn":"হে আল্লাহ, বরকত দিন","en":"O Allah, bless"}],["كَمَا بَارَكْتَ",{"bn":"যেমন আপনি বরকত দিয়েছেন","en":"just as You blessed"}]]},{"type":"tip","kind":"memory","bn":"দরূদের দুটি অংশ প্রায় একই রকম — শুধু প্রথম অংশে {{صَلِّ}} / {{صَلَّيْتَ}} (রহমত), দ্বিতীয় অংশে {{بَارِكْ}} / {{بَارَكْتَ}} (বরকত)। একটা মুখস্থ হলে অন্যটাও হয়ে যায়!","en":"The two halves of the durood are almost the same — the first uses {{صَلِّ}} / {{صَلَّيْتَ}} (grace), the second {{بَارِكْ}} / {{بَارَكْتَ}} (blessing). Learn one half and you nearly have the other!"},{"type":"table","title":{"bn":"সালামের আগের দোয়া — শব্দে শব্দে","en":"Dua before salam — word by word"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["اللّٰهُمَّ إِنِّي",{"bn":"হে আল্লাহ, নিশ্চয়ই আমি","en":"O Allah, indeed I"}],["ظَلَمْتُ نَفْسِي",{"bn":"নিজের উপর জুলুম করেছি","en":"have wronged myself"}],["ظُلْمًا كَثِيرًا",{"bn":"অনেক বেশি জুলুম","en":"a great deal"}],["وَلَا يَغْفِرُ الذُّنُوبَ",{"bn":"আর কেউ গুনাহ মাফ করে না","en":"and none forgives sins"}],["إِلَّا أَنْتَ",{"bn":"আপনি ছাড়া","en":"except You"}],["فَاغْفِرْ لِي",{"bn":"তাই আমাকে ক্ষমা করুন","en":"so forgive me"}],["مَغْفِرَةً مِنْ عِنْدِكَ",{"bn":"আপনার নিজের পক্ষ থেকে ক্ষমা","en":"with forgiveness from Yourself"}],["وَارْحَمْنِي",{"bn":"এবং আমার প্রতি দয়া করুন","en":"and have mercy on me"}],["إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ",{"bn":"নিশ্চয়ই আপনিই পরম ক্ষমাশীল, অতি দয়ালু","en":"You alone are the Forgiving, the Merciful"}]]},{"type":"examples","title":{"bn":"সালামের আগে আরেকটি দোয়া","en":"Another dua before salam"},"items":[{"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","tr":{"bn":"আল্লাহুম্মা ইন্নী আ'ঊযু বিকা মিন 'আযাবি জাহান্নামা, ওয়া মিন 'আযাবিল কাবরি, ওয়া মিন ফিতনাতিল মাহইয়া ওয়াল মামাতি, ওয়া মিন শাররি ফিতনাতিল মাসীহিদ দাজ্জাল","en":"Allaahumma innee a'oodhu bika min 'adhaabi jahannama, wa min 'adhaabil-qabri, wa min fitnatil-maḥyaa wal-mamaati, wa min sharri fitnatil-maseeḥid-dajjaal"},"mean":{"bn":"হে আল্লাহ! আমি আপনার আশ্রয় চাই জাহান্নামের শাস্তি থেকে, কবরের শাস্তি থেকে, জীবন ও মৃত্যুর পরীক্ষা থেকে, এবং মাসীহ দাজ্জালের ফিতনার অনিষ্ট থেকে।","en":"O Allah, I seek refuge in You from the punishment of Hell, from the punishment of the grave, from the trials of life and death, and from the evil of the trial of the False Messiah (Dajjal)."},"note":{"bn":"নবী ﷺ শেষ তাশাহহুদের পর এই চারটি জিনিস থেকে আশ্রয় চাইতে বলেছেন। (সহীহ মুসলিম)","en":"The Prophet ﷺ told us to seek refuge from these four after the final tashahhud. (Sahih Muslim)"}}]},{"type":"examples","title":{"bn":"নামাজের পরের যিকির","en":"Dhikr after salah"},"items":[{"ar":"أَسْتَغْفِرُ اللّٰهَ","tr":{"bn":"আসতাগফিরুল্লাহ","en":"Astaghfirullaah"},"mean":{"bn":"আমি আল্লাহর কাছে ক্ষমা চাই","en":"I seek Allah's forgiveness"},"note":{"bn":"সালামের পর ৩ বার। (সহীহ মুসলিম)","en":"3 times after salam. (Sahih Muslim)"}},{"ar":"اللّٰهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","tr":{"bn":"আল্লাহুম্মা আনতাস সালামু ওয়া মিনকাস সালামু, তাবারাকতা ইয়া যাল জালালি ওয়াল ইকরাম","en":"Allaahumma antas-salaamu wa minkas-salaamu, tabaarakta yaa dhal-jalaali wal-ikraam"},"mean":{"bn":"হে আল্লাহ! আপনিই শান্তি (আস-সালাম), আপনার কাছ থেকেই শান্তি আসে; আপনি বরকতময়, হে মহিমা ও সম্মানের অধিকারী।","en":"O Allah, You are Peace (as-Salaam) and from You comes peace; blessed are You, O Possessor of majesty and honour."},"note":{"bn":"সহীহ মুসলিম","en":"Sahih Muslim"}},{"ar":"سُبْحَانَ اللّٰهِ","tr":{"bn":"সুবহানাল্লাহ","en":"Subḥaanallaah"},"mean":{"bn":"আল্লাহ পবিত্র","en":"Glory be to Allah"},"note":{"bn":"৩৩ বার","en":"33 times"}},{"ar":"الْحَمْدُ لِلّٰهِ","tr":{"bn":"আলহামদু লিল্লাহ","en":"Alḥamdu lillaah"},"mean":{"bn":"সব প্রশংসা আল্লাহর","en":"All praise is for Allah"},"note":{"bn":"৩৩ বার","en":"33 times"}},{"ar":"اللّٰهُ أَكْبَرُ","tr":{"bn":"আল্লাহু আকবার","en":"Allaahu akbar"},"mean":{"bn":"আল্লাহ সবচেয়ে বড়","en":"Allah is the Greatest"},"note":{"bn":"৩৪ বার (সহীহ মুসলিম)","en":"34 times (Sahih Muslim)"}}]},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"এত সুন্দর নামাজ পড়ার পরেও প্রথম কথা — {{أَسْتَغْفِرُ اللّٰهَ}}! কারণ আমাদের ইবাদতে ভুল-ত্রুটি থেকেই যায়। ভালো কাজ করে অহংকার নয়, বিনয় শেখায় এই যিকির।","en":"Even after a beautiful prayer, our first words are {{أَسْتَغْفِرُ اللّٰهَ}}! Because our worship always has gaps. This dhikr teaches humility after good deeds, not pride."},{"type":"vocab","items":[{"ar":"سَلَامٌ","tr":{"bn":"সালাম","en":"salaam"},"mean":{"bn":"শান্তি","en":"peace"},"root":"س ل م"},{"ar":"رَحْمَةٌ","tr":{"bn":"রাহমাহ","en":"raḥmah"},"mean":{"bn":"দয়া, রহমত","en":"mercy"},"root":"ر ح م"},{"ar":"بَرَكَةٌ","tr":{"bn":"বারাকাহ","en":"barakah"},"mean":{"bn":"বরকত, কল্যাণের প্রাচুর্য","en":"blessing"},"root":"ب ر ك"},{"ar":"عِبَادٌ","tr":{"bn":"'ইবাদ","en":"'ibaad"},"mean":{"bn":"বান্দারা","en":"servants"},"root":"ع ب د"},{"ar":"صَالِحٌ","tr":{"bn":"সালিহ","en":"ṣaaliḥ"},"mean":{"bn":"নেককার, ভালো","en":"righteous"},"root":"ص ل ح"},{"ar":"ذُنُوبٌ","tr":{"bn":"যুনূব","en":"dhunoob"},"mean":{"bn":"গুনাহসমূহ","en":"sins"},"root":"ذ ن ب"},{"ar":"نَفْسٌ","tr":{"bn":"নাফস","en":"nafs"},"mean":{"bn":"নিজ, আত্মা","en":"self, soul"},"root":"ن ف س"}]},{"type":"quiz","items":[{"q":{"bn":"{{التَّحِيَّاتُ}} অর্থ কী?","en":"What does {{التَّحِيَّاتُ}} mean?"},"options":[{"bn":"সব সম্মান ও অভিবাদন","en":"all greetings and honours"},{"bn":"সব গুনাহ","en":"all sins"},{"bn":"সব বান্দা","en":"all servants"}],"answer":0},{"q":{"bn":"তাশাহহুদে কাকে {{أَيُّهَا}} বলে সম্বোধন করি?","en":"In the tashahhud, who is addressed with {{أَيُّهَا}}?"},"options":[{"bn":"নবী ﷺ","en":"the Prophet ﷺ"},{"bn":"ইমাম","en":"the imam"},{"bn":"ফেরেশতা","en":"the angels"}],"answer":0,"explain":{"bn":"{{أَيُّهَا النَّبِيُّ}} — হে নবী।","en":"{{أَيُّهَا النَّبِيُّ}} — O Prophet."}},{"q":{"bn":"{{الصَّالِحِينَ}} মানে কী?","en":"What does {{الصَّالِحِينَ}} mean?"},"options":[{"bn":"নামাজীরা","en":"those who pray"},{"bn":"নেককাররা","en":"the righteous"},{"bn":"নবীরা","en":"the prophets"}],"answer":1},{"q":{"bn":"দরূদে {{حَمِيدٌ مَجِيدٌ}} অর্থ কী?","en":"In the durood, what does {{حَمِيدٌ مَجِيدٌ}} mean?"},"options":[{"bn":"ক্ষমাশীল, দয়ালু","en":"Forgiving, Merciful"},{"bn":"প্রশংসিত, মহিমান্বিত","en":"Praiseworthy, Glorious"},{"bn":"শ্রোতা, দ্রষ্টা","en":"All-Hearing, All-Seeing"}],"answer":1},{"q":{"bn":"দরূদে মুহাম্মাদ ﷺ-এর সাথে কোন নবীর নাম আসে?","en":"Which prophet is mentioned alongside Muhammad ﷺ in the durood?"},"options":[{"bn":"মূসা (আ.)","en":"Musa"},{"bn":"ইবরাহীম (আ.)","en":"Ibrahim"},{"bn":"ঈসা (আ.)","en":"'Isa"}],"answer":1},{"q":{"bn":"{{ظَلَمْتُ نَفْسِي}} অর্থ কী?","en":"What does {{ظَلَمْتُ نَفْسِي}} mean?"},"options":[{"bn":"আমি নিজের উপর জুলুম করেছি","en":"I have wronged myself"},{"bn":"আমি আপনার আশ্রয় চাই","en":"I seek Your refuge"},{"bn":"আমাকে পথ দেখান","en":"guide me"}],"answer":0},{"q":{"bn":"নামাজের পর {{اللّٰهُ أَكْبَرُ}} কতবার পড়ার কথা হাদীসে আছে?","en":"How many times is {{اللّٰهُ أَكْبَرُ}} said after salah in the hadith?"},"options":["৩৩ / 33","৩৪ / 34","১০০ / 100"],"answer":1}]}]},{"id":"quran-fatiha","icon":"١","title":{"bn":"সূরা আল-ফাতিহা","en":"Surah Al-Fatiha"},"subtitle":{"bn":"কুরআনের শুরু, প্রতিটি রাকাতের প্রাণ — শব্দে শব্দে","en":"The Opening of the Quran, the heart of every rak'ah — word by word"},"minutes":20,"goals":[{"bn":"সূরা ফাতিহার সাতটি আয়াত শব্দে শব্দে বুঝব","en":"Understand all seven ayahs of Al-Fatiha word by word"},{"bn":"ফাতিহা যে আল্লাহর সাথে একটি ‘কথোপকথন’ — তা জানব","en":"Discover how Al-Fatiha is a ‘conversation’ with Allah"},{"bn":"নামাজে মনোযোগ বাড়ানোর একটি কৌশল শিখব","en":"Learn a way to focus better in salah"}],"blocks":[{"type":"text","bn":"দিনে অন্তত ১৭ বার আমরা সূরা ফাতিহা পড়ি — প্রতিটি ফরজ রাকাতে একবার। নবী ﷺ বলেছেন, যে ফাতিহা পড়ে না তার নামাজ হয় না। (বুখারী, মুসলিম) এই সূরার আরও নাম আছে: ‘উম্মুল কিতাব’ (কিতাবের মূল) ও ‘আস-সাব'উল মাসানী’ (বারবার পড়া সাত আয়াত)।","en":"We recite Al-Fatiha at least 17 times a day — once in every fard rak'ah. The Prophet ﷺ said there is no prayer for one who does not recite Al-Fatiha. (Bukhari, Muslim) It has other names too: ‘Umm al-Kitab’ (the Mother of the Book) and ‘as-Sab' al-Mathani’ (the seven oft-repeated verses)."},{"type":"ayah","ref":"1:1","ar":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ","words":[{"ar":"بِسْمِ","bn":"নামে","en":"In the name"},{"ar":"اللّٰهِ","bn":"আল্লাহর","en":"of Allah"},{"ar":"الرَّحْمٰنِ","bn":"পরম করুণাময়","en":"the Most Compassionate"},{"ar":"الرَّحِيمِ","bn":"অসীম দয়ালু","en":"the Most Merciful"}],"tr":{"bn":"বিসমিল্লাহির রাহমানির রাহীম","en":"Bismillaahir-Raḥmaanir-Raḥeem"},"mean":{"bn":"পরম করুণাময়, অসীম দয়ালু আল্লাহর নামে (শুরু করছি)।","en":"In the name of Allah, the Most Compassionate, the Most Merciful."}},{"type":"tip","kind":"tip","bn":"{{الرَّحْمٰنِ}} আর {{الرَّحِيمِ}} দুটোই এসেছে {{رَحْمَة}} (দয়া) থেকে। ‘আর-রাহমান’ — যাঁর দয়া বিশাল, সবার জন্য ছড়ানো; ‘আর-রাহীম’ — যিনি সবসময় দয়া করেই চলেন। দুটো একসাথে মানে: দয়া আর দয়া!","en":"{{الرَّحْمٰنِ}} and {{الرَّحِيمِ}} both come from {{رَحْمَة}} (mercy). ‘Ar-Rahman’ — whose mercy is vast and covers everyone; ‘Ar-Raheem’ — who keeps showing mercy, again and again. Together: mercy upon mercy!"},{"type":"ayah","ref":"1:2","ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","words":[{"ar":"الْحَمْدُ","bn":"সব প্রশংসা","en":"All praise"},{"ar":"لِلّٰهِ","bn":"আল্লাহর জন্য","en":"is for Allah"},{"ar":"رَبِّ","bn":"রব, প্রতিপালক","en":"Lord"},{"ar":"الْعَالَمِينَ","bn":"সব জগতের","en":"of all the worlds"}],"tr":{"bn":"আলহামদু লিল্লাহি রাব্বিল 'আলামীন","en":"Al-ḥamdu lillaahi rabbil-'aalameen"},"mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি সব জগতের রব।","en":"All praise is for Allah, Lord of all the worlds."}},{"type":"ayah","ref":"1:3","ar":"الرَّحْمٰنِ الرَّحِيمِ","words":[{"ar":"الرَّحْمٰنِ","bn":"পরম করুণাময়","en":"the Most Compassionate"},{"ar":"الرَّحِيمِ","bn":"অসীম দয়ালু","en":"the Most Merciful"}],"tr":{"bn":"আর-রাহমানির রাহীম","en":"Ar-Raḥmaanir-Raḥeem"},"mean":{"bn":"যিনি পরম করুণাময়, অসীম দয়ালু।","en":"The Most Compassionate, the Most Merciful."}},{"type":"ayah","ref":"1:4","ar":"مَالِكِ يَوْمِ الدِّينِ","words":[{"ar":"مَالِكِ","bn":"মালিক","en":"Master / Owner"},{"ar":"يَوْمِ","bn":"দিনের","en":"of the Day"},{"ar":"الدِّينِ","bn":"প্রতিদান / বিচার","en":"of Judgement"}],"tr":{"bn":"মা-লিকি ইয়াওমিদ্দীন","en":"Maaliki yawmid-deen"},"mean":{"bn":"যিনি বিচার দিবসের মালিক।","en":"Master of the Day of Judgement."}},{"type":"ayah","ref":"1:5","ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","words":[{"ar":"إِيَّاكَ","bn":"শুধু আপনারই","en":"You alone"},{"ar":"نَعْبُدُ","bn":"আমরা ইবাদত করি","en":"we worship"},{"ar":"وَإِيَّاكَ","bn":"এবং শুধু আপনারই কাছে","en":"and You alone"},{"ar":"نَسْتَعِينُ","bn":"আমরা সাহায্য চাই","en":"we ask for help"}],"tr":{"bn":"ইয়্যাকা না'বুদু ওয়া ইয়্যাকা নাসতা'ঈন","en":"Iyyaaka na'budu wa iyyaaka nasta'een"},"mean":{"bn":"আমরা শুধু আপনারই ইবাদত করি এবং শুধু আপনারই কাছে সাহায্য চাই।","en":"You alone we worship, and You alone we ask for help."}},{"type":"tip","kind":"memory","bn":"সাধারণ আরবিতে বলা যেত ‘না'বুদুকা’ (আমরা আপনার ইবাদত করি)। কিন্তু এখানে {{إِيَّاكَ}} আগে এসেছে — অর্থ দাঁড়ায় ‘**শুধু** আপনারই’। শব্দের এই আগে-পিছে বসানোতেই লুকিয়ে আছে তাওহীদ!","en":"Ordinary Arabic could say ‘na'buduka’ (we worship You). But here {{إِيَّاكَ}} comes first — giving the meaning ‘You **alone**’. Tawheed is hidden in the word order!"},{"type":"ayah","ref":"1:6","ar":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","words":[{"ar":"اهْدِنَا","bn":"আমাদের পথ দেখান","en":"Guide us"},{"ar":"الصِّرَاطَ","bn":"পথে","en":"to the path"},{"ar":"الْمُسْتَقِيمَ","bn":"সরল, সোজা","en":"the straight"}],"tr":{"bn":"ইহদিনাস সিরাতাল মুসতাকীম","en":"Ihdinaṣ-ṣiraaṭal-mustaqeem"},"mean":{"bn":"আমাদের সরল-সঠিক পথ দেখান।","en":"Guide us to the straight path."}},{"type":"ayah","ref":"1:7","ar":"صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ","words":[{"ar":"صِرَاطَ","bn":"পথ","en":"The path"},{"ar":"الَّذِينَ","bn":"তাদের, যাদের","en":"of those"},{"ar":"أَنْعَمْتَ","bn":"আপনি অনুগ্রহ করেছেন","en":"You have blessed"},{"ar":"عَلَيْهِمْ","bn":"তাদের উপর","en":"upon them"},{"ar":"غَيْرِ","bn":"নয়","en":"not"},{"ar":"الْمَغْضُوبِ","bn":"যাদের উপর ক্রোধ পড়েছে","en":"those who earned anger"},{"ar":"عَلَيْهِمْ","bn":"তাদের উপর","en":"upon them"},{"ar":"وَلَا","bn":"এবং নয়","en":"and not"},{"ar":"الضَّالِّينَ","bn":"পথভ্রষ্টদের","en":"those who went astray"}],"tr":{"bn":"সিরাতাল্লাযীনা আন'আমতা 'আলাইহিম, গাইরিল মাগদূবি 'আলাইহিম ওয়ালাদ্দাল্লীন","en":"Ṣiraaṭal-ladheena an'amta 'alayhim, ghayril-maghḍoobi 'alayhim wa laḍ-ḍaalleen"},"mean":{"bn":"তাদের পথ, যাদের আপনি অনুগ্রহ করেছেন; তাদের পথ নয়, যাদের উপর আপনার ক্রোধ পড়েছে, আর তাদেরও নয়, যারা পথ হারিয়েছে।","en":"The path of those You have blessed — not of those who earned Your anger, nor of those who went astray."}},{"type":"steps","title":{"bn":"ফাতিহা — আল্লাহর সাথে কথোপকথন","en":"Al-Fatiha — a conversation with Allah"},"items":[{"title":{"bn":"আমরা বলি","en":"We say"},"ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","desc":{"bn":"আল্লাহ বলেন: ‘আমার বান্দা আমার প্রশংসা করল।’","en":"Allah says: ‘My servant has praised Me.’"}},{"title":{"bn":"আমরা বলি","en":"We say"},"ar":"الرَّحْمٰنِ الرَّحِيمِ","desc":{"bn":"আল্লাহ বলেন: ‘আমার বান্দা আমার গুণগান করল।’","en":"Allah says: ‘My servant has extolled Me.’"}},{"title":{"bn":"আমরা বলি","en":"We say"},"ar":"مَالِكِ يَوْمِ الدِّينِ","desc":{"bn":"আল্লাহ বলেন: ‘আমার বান্দা আমার মহিমা ঘোষণা করল।’","en":"Allah says: ‘My servant has glorified Me.’"}},{"title":{"bn":"আমরা বলি","en":"We say"},"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","desc":{"bn":"আল্লাহ বলেন: ‘এটা আমার ও আমার বান্দার মাঝে; আমার বান্দা যা চাইবে তা পাবে।’","en":"Allah says: ‘This is between Me and My servant, and My servant shall have what he asks.’"}},{"title":{"bn":"আমরা বলি","en":"We say"},"ar":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ …","desc":{"bn":"আল্লাহ বলেন: ‘এটা আমার বান্দার জন্য; আমার বান্দা যা চাইল তা পাবে।’ (সহীহ মুসলিম, হাদীসে কুদসী)","en":"Allah says: ‘This is for My servant, and My servant shall have what he asked.’ (Sahih Muslim, hadith qudsi)"}}]},{"type":"tip","kind":"fun","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"পরের নামাজে প্রতিটি আয়াতের পর একটু থামো আর মনে করো — আল্লাহ এইমাত্র আমার কথার জবাব দিলেন! ফাতিহা তখন আর মুখস্থ পড়া থাকবে না, হয়ে যাবে সত্যিকারের কথা বলা। আর লক্ষ করো, আমরা চাই ‘**আমাদের**’ পথ দেখান — শুধু ‘আমাকে’ নয়। মুমিন সবার জন্য ভালো চায়।","en":"In your next prayer, pause briefly after each ayah and remember — Allah has just answered me! Al-Fatiha stops being a memorised recital and becomes a real conversation. And notice we ask ‘guide **us**’ — not just ‘me’. A believer wants good for everyone."},{"type":"vocab","items":[{"ar":"حَمْدٌ","tr":{"bn":"হামদ","en":"ḥamd"},"mean":{"bn":"প্রশংসা","en":"praise"},"root":"ح م د","example":{"ar":"الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ","mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি সব জগতের রব","en":"All praise is for Allah, Lord of the worlds"},"ref":"1:2"}},{"ar":"رَبٌّ","tr":{"bn":"রব","en":"rabb"},"mean":{"bn":"প্রতিপালক, মালিক","en":"Lord, Sustainer"},"root":"ر ب ب"},{"ar":"يَوْمٌ","tr":{"bn":"ইয়াওম","en":"yawm"},"mean":{"bn":"দিন","en":"day"},"root":"ي و م"},{"ar":"نَعْبُدُ","tr":{"bn":"না'বুদু","en":"na'budu"},"mean":{"bn":"আমরা ইবাদত করি","en":"we worship"},"root":"ع ب د"},{"ar":"صِرَاطٌ","tr":{"bn":"সিরাত","en":"ṣiraaṭ"},"mean":{"bn":"পথ","en":"path"},"root":"ص ر ط"},{"ar":"مُسْتَقِيمٌ","tr":{"bn":"মুসতাকীম","en":"mustaqeem"},"mean":{"bn":"সোজা, সরল","en":"straight"},"root":"ق و م"}]},{"type":"quiz","items":[{"q":{"bn":"{{الْعَالَمِينَ}} অর্থ কী?","en":"What does {{الْعَالَمِينَ}} mean?"},"options":[{"bn":"সব জগৎ","en":"all the worlds"},{"bn":"বিচার দিবস","en":"the Day of Judgement"},{"bn":"সরল পথ","en":"the straight path"}],"answer":0},{"q":{"bn":"{{نَسْتَعِينُ}} মানে কী?","en":"What does {{نَسْتَعِينُ}} mean?"},"options":[{"bn":"আমরা ইবাদত করি","en":"we worship"},{"bn":"আমরা সাহায্য চাই","en":"we ask for help"},{"bn":"আমাদের পথ দেখান","en":"guide us"}],"answer":1},{"q":{"bn":"কোন আয়াতে আল্লাহকে ‘বিচার দিবসের মালিক’ বলা হয়েছে?","en":"Which ayah calls Allah ‘Master of the Day of Judgement’?"},"options":["الرَّحْمٰنِ الرَّحِيمِ","مَالِكِ يَوْمِ الدِّينِ","اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ"],"answer":1},{"q":{"bn":"{{اهْدِنَا}} অর্থ কী?","en":"What does {{اهْدِنَا}} mean?"},"options":[{"bn":"আমাদের ক্ষমা করুন","en":"forgive us"},{"bn":"আমাদের পথ দেখান","en":"guide us"},{"bn":"আমাদের রিযিক দিন","en":"provide for us"}],"answer":1},{"q":{"bn":"{{الضَّالِّينَ}} কারা?","en":"Who are {{الضَّالِّينَ}}?"},"options":[{"bn":"যারা পথ হারিয়েছে","en":"those who went astray"},{"bn":"যাদের অনুগ্রহ করা হয়েছে","en":"those who were blessed"},{"bn":"যারা ইবাদত করে","en":"those who worship"}],"answer":0},{"q":{"bn":"সূরা ফাতিহায় কয়টি আয়াত?","en":"How many ayahs are in Al-Fatiha?"},"options":["৫ / 5","৬ / 6","৭ / 7","৮ / 8"],"answer":2},{"q":{"bn":"হাদীসে কুদসী অনুযায়ী, {{إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ}} শুনে আল্লাহ কী বলেন?","en":"According to the hadith qudsi, what does Allah say at {{إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ}}?"},"options":[{"bn":"আমার বান্দা আমার প্রশংসা করল","en":"My servant has praised Me"},{"bn":"এটা আমার ও আমার বান্দার মাঝে","en":"This is between Me and My servant"},{"bn":"আমার বান্দা আমার মহিমা ঘোষণা করল","en":"My servant has glorified Me"}],"answer":1}]}]},{"id":"quran-ikhlas","icon":"١١٢","title":{"bn":"সূরা আল-ইখলাস","en":"Surah Al-Ikhlas"},"subtitle":{"bn":"চার আয়াতে আল্লাহর পরিচয় — শব্দে শব্দে","en":"Who Allah is, in four ayahs — word by word"},"minutes":12,"goals":[{"bn":"সূরা ইখলাসের প্রতিটি শব্দের অর্থ জানব","en":"Know the meaning of every word of Al-Ikhlas"},{"bn":"{{أَحَدٌ}} ও {{الصَّمَدُ}} — এই দুটি নামের গভীরতা বুঝব","en":"Grasp the depth of the names {{أَحَدٌ}} and {{الصَّمَدُ}}"},{"bn":"এই সূরার বিশেষ ফযিলত জানব","en":"Learn the special virtue of this surah"}],"blocks":[{"type":"text","bn":"কেউ যদি জিজ্ঞেস করে, ‘তোমার রব কেমন?’ — সবচেয়ে সুন্দর উত্তর এই ছোট্ট সূরাটি। ‘ইখলাস’ মানে খাঁটি করা — এই সূরা আমাদের ঈমানকে খাঁটি তাওহীদে পরিষ্কার করে দেয়।","en":"If someone asks, ‘What is your Lord like?’ — the most beautiful answer is this little surah. ‘Ikhlas’ means making pure — this surah purifies our faith into pure tawheed."},{"type":"ayah","ref":"112:1","ar":"قُلْ هُوَ اللّٰهُ أَحَدٌ","words":[{"ar":"قُلْ","bn":"বলুন","en":"Say"},{"ar":"هُوَ","bn":"তিনি","en":"He is"},{"ar":"اللّٰهُ","bn":"আল্লাহ","en":"Allah"},{"ar":"أَحَدٌ","bn":"এক ও অদ্বিতীয়","en":"the One, the Unique"}],"tr":{"bn":"কুল হুওয়াল্লা-হু আহাদ","en":"Qul huwallaahu aḥad"},"mean":{"bn":"বলুন: তিনিই আল্লাহ, এক ও অদ্বিতীয়।","en":"Say: He is Allah, the One and Only."}},{"type":"ayah","ref":"112:2","ar":"اللّٰهُ الصَّمَدُ","words":[{"ar":"اللّٰهُ","bn":"আল্লাহ","en":"Allah"},{"ar":"الصَّمَدُ","bn":"অমুখাপেক্ষী, সবাই যাঁর মুখাপেক্ষী","en":"the Self-Sufficient, on whom all depend"}],"tr":{"bn":"আল্লা-হুস সামাদ","en":"Allaahuṣ-ṣamad"},"mean":{"bn":"আল্লাহ কারও মুখাপেক্ষী নন, আর সবকিছু তাঁরই মুখাপেক্ষী।","en":"Allah needs no one, and everything depends on Him."}},{"type":"tip","kind":"memory","bn":"{{الصَّمَدُ}} এমন একজন, যাঁর কাছে সবাই নিজের প্রয়োজন নিয়ে যায়, কিন্তু তাঁর নিজের কোনো প্রয়োজন নেই। আমাদের খিদে লাগে, ঘুম পায়, সাহায্য লাগে — আল্লাহর এসব কিছুই লাগে না। তাই সব চাওয়া তাঁর কাছেই।","en":"{{الصَّمَدُ}} is the One everyone turns to with their needs, while He Himself needs nothing. We get hungry, sleepy, we need help — Allah needs none of these. So every request goes to Him."},{"type":"ayah","ref":"112:3","ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","words":[{"ar":"لَمْ يَلِدْ","bn":"তিনি কাউকে জন্ম দেননি","en":"He has not begotten"},{"ar":"وَلَمْ يُولَدْ","bn":"এবং তাঁকেও জন্ম দেওয়া হয়নি","en":"nor was He begotten"}],"tr":{"bn":"লাম ইয়ালিদ ওয়া লাম ইউলাদ","en":"Lam yalid wa lam yoolad"},"mean":{"bn":"তিনি কাউকে জন্ম দেননি, কেউ তাঁকে জন্ম দেয়নি।","en":"He has no child, and He was not born of anyone."}},{"type":"ayah","ref":"112:4","ar":"وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ","words":[{"ar":"وَلَمْ يَكُن","bn":"এবং নেই","en":"And there is not"},{"ar":"لَّهُ","bn":"তাঁর","en":"to Him"},{"ar":"كُفُوًا","bn":"সমতুল্য","en":"equal, comparable"},{"ar":"أَحَدٌ","bn":"কেউ","en":"anyone"}],"tr":{"bn":"ওয়া লাম ইয়াকুল লাহূ কুফুওয়ান আহাদ","en":"Wa lam yakul-lahoo kufuwan aḥad"},"mean":{"bn":"আর তাঁর সমতুল্য কেউই নেই।","en":"And there is none comparable to Him."}},{"type":"tip","kind":"tip","bn":"লক্ষ করো: {{لَمْ}} + বর্তমান কালের ক্রিয়া = অতীতে ‘করেনি’। {{يَلِدْ}} = জন্ম দেয়, {{لَمْ يَلِدْ}} = জন্ম দেননি। একই শব্দমূল {{و ل د}} থেকে {{وَلَد}} (সন্তান) শব্দটিও এসেছে।","en":"Notice: {{لَمْ}} + a present-tense verb = ‘did not’. {{يَلِدْ}} = begets, {{لَمْ يَلِدْ}} = did not beget. The same root {{و ل د}} gives {{وَلَد}} (child)."},{"type":"tip","kind":"fun","title":{"bn":"এই সূরার মর্যাদা","en":"The rank of this surah"},"bn":"নবী ﷺ বলেছেন, সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান। (সহীহ বুখারী) একজন সাহাবী নামাজে প্রতিবার এই সূরা পড়তেন; কারণ জিজ্ঞেস করলে বললেন, ‘এতে দয়াময়ের গুণাবলি আছে, তাই আমি এটা পড়তে ভালোবাসি।’ নবী ﷺ বললেন, ‘তাকে জানিয়ে দাও, আল্লাহও তাকে ভালোবাসেন।’ (বুখারী, মুসলিম)","en":"The Prophet ﷺ said Surah Al-Ikhlas equals one third of the Quran. (Sahih al-Bukhari) A companion used to recite it in every prayer; when asked why, he said, ‘It describes the Most Merciful, and I love to recite it.’ The Prophet ﷺ said, ‘Tell him that Allah loves him too.’ (Bukhari, Muslim)"},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"যে জিনিস ভালোবাসো, তার কথা বারবার বলো — সাহাবী আল্লাহর গুণ ভালোবাসতেন, আর আল্লাহ তাঁকে ভালোবাসলেন। আজ থেকে ইখলাস পড়ার সময় অর্থটা মনে করো — শুধু মুখে নয়, মন দিয়ে।","en":"We speak often of what we love — the companion loved Allah's qualities, and Allah loved him. From today, recall the meaning whenever you recite Al-Ikhlas — not only with the tongue, but with the heart."},{"type":"quiz","items":[{"q":{"bn":"{{الصَّمَدُ}} অর্থ কী?","en":"What does {{الصَّمَدُ}} mean?"},"options":[{"bn":"অমুখাপেক্ষী, সবাই যাঁর মুখাপেক্ষী","en":"Self-Sufficient, on whom all depend"},{"bn":"সর্বশ্রোতা","en":"All-Hearing"},{"bn":"ক্ষমাশীল","en":"Forgiving"}],"answer":0},{"q":{"bn":"{{أَحَدٌ}} মানে কী?","en":"What does {{أَحَدٌ}} mean?"},"options":[{"bn":"এক ও অদ্বিতীয়","en":"the One, the Unique"},{"bn":"প্রথম","en":"the First"},{"bn":"মহান","en":"the Great"}],"answer":0},{"q":{"bn":"কোন আয়াত বলে ‘তিনি কাউকে জন্ম দেননি, কেউ তাঁকে জন্ম দেয়নি’?","en":"Which ayah says ‘He has no child, and was not born’?"},"options":["اللّٰهُ الصَّمَدُ","لَمْ يَلِدْ وَلَمْ يُولَدْ","قُلْ هُوَ اللّٰهُ أَحَدٌ"],"answer":1},{"q":{"bn":"{{كُفُوًا}} অর্থ কী?","en":"What does {{كُفُوًا}} mean?"},"options":[{"bn":"সন্তান","en":"child"},{"bn":"সমতুল্য","en":"equal"},{"bn":"বন্ধু","en":"friend"}],"answer":1},{"q":{"bn":"হাদীস অনুযায়ী সূরা ইখলাস কুরআনের কত অংশের সমান?","en":"According to the hadith, Al-Ikhlas equals what portion of the Quran?"},"options":[{"bn":"অর্ধেক","en":"half"},{"bn":"এক-তৃতীয়াংশ","en":"one third"},{"bn":"এক-চতুর্থাংশ","en":"one quarter"}],"answer":1},{"q":{"bn":"{{قُلْ}} অর্থ কী?","en":"What does {{قُلْ}} mean?"},"options":[{"bn":"পড়ুন","en":"Read"},{"bn":"বলুন","en":"Say"},{"bn":"শুনুন","en":"Listen"}],"answer":1}]}]},{"id":"quran-falaq-nas","icon":"١١٣","title":{"bn":"সূরা আল-ফালাক ও আন-নাস","en":"Surah Al-Falaq & An-Nas"},"subtitle":{"bn":"দুই আশ্রয়ের সূরা — বাইরের ও ভেতরের অনিষ্ট থেকে সুরক্ষা","en":"The two surahs of refuge — protection from outer and inner harm"},"minutes":18,"goals":[{"bn":"সূরা ফালাক ও নাস শব্দে শব্দে বুঝব","en":"Understand Al-Falaq and An-Nas word by word"},{"bn":"কোন কোন অনিষ্ট থেকে আশ্রয় চাই তা জানব","en":"Know which harms we seek refuge from"},{"bn":"রাতে ঘুমানোর আগে নবী ﷺ-এর সুন্নাহ শিখব","en":"Learn the Prophet's ﷺ bedtime sunnah with these surahs"}],"blocks":[{"type":"text","bn":"কুরআনের শেষ দুটি সূরাকে বলে ‘মু'আওয়িযাতাইন’ — আশ্রয় চাওয়ার দুই সূরা। দুটোই শুরু হয় {{قُلْ أَعُوذُ}} দিয়ে: ‘বলুন, আমি আশ্রয় চাই।’ সূরা ফালাক বাইরের বিপদ থেকে, আর সূরা নাস ভেতরের কুমন্ত্রণা থেকে সুরক্ষা চায়।","en":"The last two surahs of the Quran are called ‘al-Mu'awwidhatayn’ — the two surahs of seeking refuge. Both begin with {{قُلْ أَعُوذُ}}: ‘Say, I seek refuge.’ Al-Falaq asks protection from outer dangers, An-Nas from inner whispers."},{"type":"tip","kind":"fun","bn":"সাহাবী উকবা ইবনে আমের (রা.)-কে নবী ﷺ বলেছিলেন: ‘তুমি কি দেখোনি, আজ রাতে এমন কিছু আয়াত নাযিল হয়েছে যার মতো আর কখনো দেখা যায়নি? — {{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}} ও {{قُلْ أَعُوذُ بِرَبِّ النَّاسِ}}।’ (সহীহ মুসলিম)","en":"The Prophet ﷺ told the companion 'Uqbah ibn 'Amir: ‘Have you not seen the verses revealed tonight, the like of which has never been seen? — {{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}} and {{قُلْ أَعُوذُ بِرَبِّ النَّاسِ}}.’ (Sahih Muslim)"},{"type":"text","title":{"bn":"সূরা আল-ফালাক (১১৩)","en":"Surah Al-Falaq (113)"},"bn":"‘ফালাক’ মানে ভোর — অন্ধকার চিরে আলো বের হওয়া।","en":"‘Falaq’ means daybreak — light splitting through the darkness."},{"type":"ayah","ref":"113:1","ar":"قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","words":[{"ar":"قُلْ","bn":"বলুন","en":"Say"},{"ar":"أَعُوذُ","bn":"আমি আশ্রয় চাই","en":"I seek refuge"},{"ar":"بِرَبِّ","bn":"রবের কাছে","en":"in the Lord"},{"ar":"الْفَلَقِ","bn":"ভোরের","en":"of daybreak"}],"tr":{"bn":"কুল আ'ঊযু বিরাব্বিল ফালাক","en":"Qul a'oodhu birabbil-falaq"},"mean":{"bn":"বলুন: আমি আশ্রয় চাই ভোরের রবের কাছে,","en":"Say: I seek refuge in the Lord of daybreak,"}},{"type":"ayah","ref":"113:2","ar":"مِنْ شَرِّ مَا خَلَقَ","words":[{"ar":"مِنْ","bn":"থেকে","en":"from"},{"ar":"شَرِّ","bn":"অনিষ্ট","en":"the evil of"},{"ar":"مَا","bn":"যা কিছু","en":"what"},{"ar":"خَلَقَ","bn":"তিনি সৃষ্টি করেছেন","en":"He created"}],"tr":{"bn":"মিন শাররি মা খালাক","en":"Min sharri maa khalaq"},"mean":{"bn":"তিনি যা কিছু সৃষ্টি করেছেন তার অনিষ্ট থেকে,","en":"from the evil of what He has created,"}},{"type":"ayah","ref":"113:3","ar":"وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ","words":[{"ar":"وَمِنْ شَرِّ","bn":"এবং অনিষ্ট থেকে","en":"and from the evil of"},{"ar":"غَاسِقٍ","bn":"আঁধার রাতের","en":"the darkness (of night)"},{"ar":"إِذَا","bn":"যখন","en":"when"},{"ar":"وَقَبَ","bn":"তা ছেয়ে যায়","en":"it settles in"}],"tr":{"bn":"ওয়া মিন শাররি গা-সিকিন ইযা ওয়াকাব","en":"Wa min sharri ghaasiqin idhaa waqab"},"mean":{"bn":"এবং রাতের আঁধারের অনিষ্ট থেকে, যখন তা ছেয়ে যায়,","en":"and from the evil of the darkness when it settles,"}},{"type":"ayah","ref":"113:4","ar":"وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ","words":[{"ar":"وَمِنْ شَرِّ","bn":"এবং অনিষ্ট থেকে","en":"and from the evil of"},{"ar":"النَّفَّاثَاتِ","bn":"ফুঁ-দানকারীদের","en":"those who blow"},{"ar":"فِي الْعُقَدِ","bn":"গিঁটে","en":"on knots"}],"tr":{"bn":"ওয়া মিন শাররিন নাফফা-সা-তি ফিল 'উকাদ","en":"Wa min sharrin-naffaathaati fil-'uqad"},"mean":{"bn":"এবং গিঁটে ফুঁ দেয় যারা (জাদুকর), তাদের অনিষ্ট থেকে,","en":"and from the evil of those who blow on knots (practising magic),"}},{"type":"ayah","ref":"113:5","ar":"وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ","words":[{"ar":"وَمِنْ شَرِّ","bn":"এবং অনিষ্ট থেকে","en":"and from the evil of"},{"ar":"حَاسِدٍ","bn":"হিংসুকের","en":"an envier"},{"ar":"إِذَا","bn":"যখন","en":"when"},{"ar":"حَسَدَ","bn":"সে হিংসা করে","en":"he envies"}],"tr":{"bn":"ওয়া মিন শাররি হা-সিদিন ইযা হাসাদ","en":"Wa min sharri ḥaasidin idhaa ḥasad"},"mean":{"bn":"এবং হিংসুকের অনিষ্ট থেকে, যখন সে হিংসা করে।","en":"and from the evil of an envier when he envies."}},{"type":"text","title":{"bn":"সূরা আন-নাস (১১৪)","en":"Surah An-Nas (114)"},"bn":"‘নাস’ মানে মানুষ। এই সূরায় আল্লাহর তিনটি পরিচয় দিয়ে একটিমাত্র বিপদ থেকে আশ্রয় চাওয়া হয়েছে — অন্তরের কুমন্ত্রণা।","en":"‘Nas’ means people. In this surah, we call on three qualities of Allah to seek refuge from just one danger — the whisper in the heart."},{"type":"ayah","ref":"114:1","ar":"قُلْ أَعُوذُ بِرَبِّ النَّاسِ","words":[{"ar":"قُلْ","bn":"বলুন","en":"Say"},{"ar":"أَعُوذُ","bn":"আমি আশ্রয় চাই","en":"I seek refuge"},{"ar":"بِرَبِّ","bn":"রবের কাছে","en":"in the Lord"},{"ar":"النَّاسِ","bn":"মানুষের","en":"of mankind"}],"tr":{"bn":"কুল আ'ঊযু বিরাব্বিন না-স","en":"Qul a'oodhu birabbin-naas"},"mean":{"bn":"বলুন: আমি আশ্রয় চাই মানুষের রবের কাছে,","en":"Say: I seek refuge in the Lord of mankind,"}},{"type":"ayah","ref":"114:2","ar":"مَلِكِ النَّاسِ","words":[{"ar":"مَلِكِ","bn":"বাদশাহ","en":"the King"},{"ar":"النَّاسِ","bn":"মানুষের","en":"of mankind"}],"tr":{"bn":"মালিকিন না-স","en":"Malikin-naas"},"mean":{"bn":"মানুষের বাদশাহর কাছে,","en":"the King of mankind,"}},{"type":"ayah","ref":"114:3","ar":"إِلٰهِ النَّاسِ","words":[{"ar":"إِلٰهِ","bn":"ইলাহ, উপাস্য","en":"the God"},{"ar":"النَّاسِ","bn":"মানুষের","en":"of mankind"}],"tr":{"bn":"ইলা-হিন না-স","en":"Ilaahin-naas"},"mean":{"bn":"মানুষের ইলাহর কাছে,","en":"the God of mankind,"}},{"type":"ayah","ref":"114:4","ar":"مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ","words":[{"ar":"مِنْ شَرِّ","bn":"অনিষ্ট থেকে","en":"from the evil of"},{"ar":"الْوَسْوَاسِ","bn":"কুমন্ত্রণাদাতার","en":"the whisperer"},{"ar":"الْخَنَّاسِ","bn":"যে পিছিয়ে লুকিয়ে যায়","en":"who slinks away"}],"tr":{"bn":"মিন শাররিল ওয়াসওয়া-সিল খান্না-স","en":"Min sharril-waswaasil-khannaas"},"mean":{"bn":"সেই কুমন্ত্রণাদাতার অনিষ্ট থেকে, যে (আল্লাহর নাম শুনলে) পিছিয়ে লুকিয়ে যায়,","en":"from the evil of the whisperer who slinks away (when Allah is remembered),"}},{"type":"ayah","ref":"114:5","ar":"الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ","words":[{"ar":"الَّذِي","bn":"যে","en":"who"},{"ar":"يُوَسْوِسُ","bn":"কুমন্ত্রণা দেয়","en":"whispers"},{"ar":"فِي صُدُورِ","bn":"অন্তরে","en":"into the hearts"},{"ar":"النَّاسِ","bn":"মানুষের","en":"of people"}],"tr":{"bn":"আল্লাযী ইউওয়াসউইসু ফী সুদূরিন না-স","en":"Alladhee yuwaswisu fee ṣudoorin-naas"},"mean":{"bn":"যে মানুষের অন্তরে কুমন্ত্রণা দেয়,","en":"who whispers into the hearts of people,"}},{"type":"ayah","ref":"114:6","ar":"مِنَ الْجِنَّةِ وَالنَّاسِ","words":[{"ar":"مِنَ","bn":"মধ্য থেকে","en":"from among"},{"ar":"الْجِنَّةِ","bn":"জিনদের","en":"the jinn"},{"ar":"وَالنَّاسِ","bn":"ও মানুষের","en":"and mankind"}],"tr":{"bn":"মিনাল জিন্নাতি ওয়ান না-স","en":"Minal-jinnati wan-naas"},"mean":{"bn":"সে জিনদের মধ্য থেকে হোক বা মানুষের মধ্য থেকে।","en":"whether from among the jinn or mankind."}},{"type":"compare","title":{"bn":"দুই সূরার তুলনা","en":"The two surahs compared"},"items":[{"ar":"الْفَلَقِ","label":{"bn":"আল্লাহর ১টি গুণ, ৪টি বিপদ","en":"1 quality of Allah, 4 dangers"},"desc":{"bn":"সৃষ্টির অনিষ্ট, রাতের আঁধার, জাদু, হিংসা — বাইরের বিপদ।","en":"Evil of creation, darkness, magic, envy — outer dangers."}},{"ar":"النَّاسِ","label":{"bn":"আল্লাহর ৩টি গুণ, ১টি বিপদ","en":"3 qualities of Allah, 1 danger"},"desc":{"bn":"রব, বাদশাহ, ইলাহ — শুধু কুমন্ত্রণা থেকে বাঁচতে! ভেতরের বিপদ সবচেয়ে বড়।","en":"Lord, King, God — just to escape the whisper! The inner danger is the greatest."}}]},{"type":"tip","kind":"tip","title":{"bn":"ঘুমানোর আগের সুন্নাহ","en":"The bedtime sunnah"},"bn":"নবী ﷺ প্রতি রাতে বিছানায় গিয়ে দুই হাত একত্র করে সূরা ইখলাস, ফালাক ও নাস পড়ে হাতে ফুঁ দিতেন, তারপর মাথা ও মুখ থেকে শুরু করে যতটা সম্ভব শরীরে হাত বুলাতেন — তিনবার। (সহীহ বুখারী)","en":"Every night when the Prophet ﷺ went to bed, he would cup his hands, recite Al-Ikhlas, Al-Falaq and An-Nas, blow into them, then wipe over as much of his body as he could, starting with the head and face — three times. (Sahih al-Bukhari)"},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"{{الْخَنَّاسِ}} — যে পিছিয়ে যায়। খারাপ চিন্তা আসলে ভয় পেও না; আল্লাহকে স্মরণ করো, {{أَعُوذُ بِاللّٰهِ}} বলো — কুমন্ত্রণাদাতা পালিয়ে যাবে। শয়তানের শক্তি শুধু ফিসফিস করা পর্যন্ত, জোর করার ক্ষমতা তার নেই।","en":"{{الْخَنَّاسِ}} — the one who retreats. When a bad thought comes, don't panic; remember Allah and say {{أَعُوذُ بِاللّٰهِ}} — the whisperer runs away. Satan's power is only to whisper; he cannot force you."},{"type":"quiz","items":[{"q":{"bn":"{{الْفَلَقِ}} অর্থ কী?","en":"What does {{الْفَلَقِ}} mean?"},"options":[{"bn":"ভোর","en":"daybreak"},{"bn":"রাত","en":"night"},{"bn":"মানুষ","en":"mankind"}],"answer":0},{"q":{"bn":"{{أَعُوذُ}} মানে কী?","en":"What does {{أَعُوذُ}} mean?"},"options":[{"bn":"আমি ইবাদত করি","en":"I worship"},{"bn":"আমি আশ্রয় চাই","en":"I seek refuge"},{"bn":"আমি সাক্ষ্য দিই","en":"I bear witness"}],"answer":1},{"q":{"bn":"কোন আয়াতে হিংসুকের অনিষ্ট থেকে আশ্রয় চাওয়া হয়েছে?","en":"Which ayah seeks refuge from the envier?"},"options":["وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ","مِنْ شَرِّ مَا خَلَقَ","مَلِكِ النَّاسِ"],"answer":0},{"q":{"bn":"সূরা নাসে আল্লাহর কোন তিনটি পরিচয় এসেছে?","en":"Which three qualities of Allah appear in An-Nas?"},"options":[{"bn":"রব, বাদশাহ, ইলাহ","en":"Lord, King, God"},{"bn":"দয়াময়, দয়ালু, মালিক","en":"Compassionate, Merciful, Master"},{"bn":"জীবিত, চিরস্থায়ী, মহান","en":"Living, Eternal, Great"}],"answer":0},{"q":{"bn":"{{الْوَسْوَاسِ}} কে?","en":"Who is {{الْوَسْوَاسِ}}?"},"options":[{"bn":"কুমন্ত্রণাদাতা","en":"the whisperer"},{"bn":"জাদুকর","en":"the magician"},{"bn":"হিংসুক","en":"the envier"}],"answer":0},{"q":{"bn":"{{صُدُورِ}} অর্থ কী?","en":"What does {{صُدُورِ}} mean?"},"options":[{"bn":"মুখ","en":"faces"},{"bn":"অন্তর / বুক","en":"hearts / chests"},{"bn":"হাত","en":"hands"}],"answer":1},{"q":{"bn":"ঘুমানোর আগে নবী ﷺ কোন তিনটি সূরা পড়ে হাতে ফুঁ দিতেন?","en":"Which three surahs did the Prophet ﷺ recite into his hands before sleeping?"},"options":[{"bn":"ফাতিহা, ইখলাস, নাস","en":"Fatiha, Ikhlas, Nas"},{"bn":"ইখলাস, ফালাক, নাস","en":"Ikhlas, Falaq, Nas"},{"bn":"কাওসার, আসর, নাসর","en":"Kawthar, 'Asr, Nasr"}],"answer":1}]}]},{"id":"quran-kawthar-asr","icon":"١٠٨","title":{"bn":"সূরা আল-কাওসার ও আল-আসর","en":"Surah Al-Kawthar & Al-'Asr"},"subtitle":{"bn":"কুরআনের সবচেয়ে ছোট সূরা আর সময়ের মূল্য","en":"The shortest surah of the Quran, and the value of time"},"minutes":15,"goals":[{"bn":"সূরা কাওসার ও আসর শব্দে শব্দে বুঝব","en":"Understand Al-Kawthar and Al-'Asr word by word"},{"bn":"‘কাওসার’ কী — সহীহ হাদীস থেকে জানব","en":"Learn what ‘al-Kawthar’ is, from an authentic hadith"},{"bn":"ক্ষতি থেকে বাঁচার চারটি গুণ মনে রাখব","en":"Remember the four qualities that save from loss"}],"blocks":[{"type":"text","title":{"bn":"সূরা আল-কাওসার (১০৮)","en":"Surah Al-Kawthar (108)"},"bn":"মাত্র তিন আয়াত — কুরআনের সবচেয়ে ছোট সূরা। কিন্তু এতে আছে নবী ﷺ-এর জন্য বিশাল সুসংবাদ।","en":"Only three ayahs — the shortest surah in the Quran. Yet it carries enormous good news for the Prophet ﷺ."},{"type":"ayah","ref":"108:1","ar":"إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ","words":[{"ar":"إِنَّا","bn":"নিশ্চয়ই আমরা","en":"Indeed, We"},{"ar":"أَعْطَيْنَاكَ","bn":"আপনাকে দান করেছি","en":"have given you"},{"ar":"الْكَوْثَرَ","bn":"কাওসার (অফুরন্ত কল্যাণ)","en":"al-Kawthar (abundant good)"}],"tr":{"bn":"ইন্না আ'তাইনা-কাল কাওসার","en":"Innaa a'ṭaynaakal-kawthar"},"mean":{"bn":"নিশ্চয়ই আমি আপনাকে কাওসার (অফুরন্ত কল্যাণ) দান করেছি।","en":"Indeed, We have given you al-Kawthar (abundant good)."}},{"type":"ayah","ref":"108:2","ar":"فَصَلِّ لِرَبِّكَ وَانْحَرْ","words":[{"ar":"فَصَلِّ","bn":"সুতরাং নামাজ পড়ুন","en":"So pray"},{"ar":"لِرَبِّكَ","bn":"আপনার রবের জন্য","en":"to your Lord"},{"ar":"وَانْحَرْ","bn":"এবং কুরবানি করুন","en":"and sacrifice"}],"tr":{"bn":"ফাসাল্লি লিরাব্বিকা ওয়ানহার","en":"Faṣalli lirabbika wanḥar"},"mean":{"bn":"তাই আপনার রবের জন্যই নামাজ পড়ুন এবং কুরবানি করুন।","en":"So pray to your Lord and offer sacrifice (for Him alone)."}},{"type":"ayah","ref":"108:3","ar":"إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ","words":[{"ar":"إِنَّ","bn":"নিশ্চয়ই","en":"Indeed"},{"ar":"شَانِئَكَ","bn":"আপনার শত্রু / বিদ্বেষী","en":"your hater"},{"ar":"هُوَ","bn":"সে-ই","en":"he is"},{"ar":"الْأَبْتَرُ","bn":"শিকড়কাটা, নাম-নিশানাহীন","en":"the one cut off"}],"tr":{"bn":"ইন্না শা-নি'আকা হুওয়াল আবতার","en":"Inna shaani'aka huwal-abtar"},"mean":{"bn":"নিশ্চয়ই আপনার বিদ্বেষীই শিকড়কাটা (তার কোনো স্থায়ী স্মৃতি থাকবে না)।","en":"Indeed, it is your hater who is cut off (with no lasting legacy)."}},{"type":"tip","kind":"fun","title":{"bn":"কাওসার কী?","en":"What is al-Kawthar?"},"bn":"আনাস (রা.) বলেন, একদিন নবী ﷺ হালকা তন্দ্রা থেকে হাসিমুখে মাথা তুললেন এবং এই সূরা পড়লেন। তারপর বললেন, ‘কাওসার হলো জান্নাতের একটি নহর, যার ওয়াদা আমার রব আমাকে দিয়েছেন — তাতে অনেক কল্যাণ।’ (সহীহ মুসলিম)","en":"Anas (may Allah be pleased with him) said the Prophet ﷺ once lifted his head from a light doze, smiling, and recited this surah. Then he said, ‘Al-Kawthar is a river in Paradise my Lord has promised me, full of abundant good.’ (Sahih Muslim)"},{"type":"tip","kind":"memory","bn":"শত্রুরা নবী ﷺ-কে ‘আবতার’ (যার বংশ টিকবে না) বলে উপহাস করত। আজ দেড় হাজার বছর পরেও প্রতিটি আযানে, প্রতিটি নামাজে তাঁর নাম উচ্চারিত হয় — আর সেই শত্রুদের নামই কেউ মনে রাখে না। আল্লাহর ওয়াদা সত্য!","en":"Enemies mocked the Prophet ﷺ as ‘abtar’ (one whose line will not last). Fourteen centuries later, his name is spoken in every adhan and every prayer — while hardly anyone remembers those enemies. Allah's promise is true!"},{"type":"text","title":{"bn":"সূরা আল-আসর (১০৩)","en":"Surah Al-'Asr (103)"},"bn":"তিন আয়াতে জীবনের পুরো রোডম্যাপ! আল্লাহ সময়ের শপথ করে বলছেন — সব মানুষ ক্ষতিতে আছে, শুধু চার গুণের মানুষ ছাড়া।","en":"A complete roadmap for life in three ayahs! Allah swears by time that all people are in loss — except those with four qualities."},{"type":"ayah","ref":"103:1","ar":"وَالْعَصْرِ","words":[{"ar":"وَالْعَصْرِ","bn":"সময়ের শপথ","en":"By time"}],"tr":{"bn":"ওয়াল 'আসর","en":"Wal-'aṣr"},"mean":{"bn":"সময়ের শপথ!","en":"By time!"}},{"type":"ayah","ref":"103:2","ar":"إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ","words":[{"ar":"إِنَّ","bn":"নিশ্চয়ই","en":"Indeed"},{"ar":"الْإِنْسَانَ","bn":"মানুষ","en":"mankind"},{"ar":"لَفِي","bn":"অবশ্যই মধ্যে আছে","en":"is surely in"},{"ar":"خُسْرٍ","bn":"ক্ষতির","en":"loss"}],"tr":{"bn":"ইন্নাল ইনসা-না লাফী খুসর","en":"Innal-insaana lafee khusr"},"mean":{"bn":"নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে,","en":"Indeed, mankind is in loss,"}},{"type":"ayah","ref":"103:3","ar":"إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ","words":[{"ar":"إِلَّا","bn":"তবে তারা নয়","en":"except"},{"ar":"الَّذِينَ","bn":"যারা","en":"those who"},{"ar":"آمَنُوا","bn":"ঈমান এনেছে","en":"believe"},{"ar":"وَعَمِلُوا","bn":"এবং করেছে","en":"and do"},{"ar":"الصَّالِحَاتِ","bn":"নেক কাজ","en":"righteous deeds"},{"ar":"وَتَوَاصَوْا","bn":"এবং পরস্পরকে উপদেশ দিয়েছে","en":"and urge one another"},{"ar":"بِالْحَقِّ","bn":"সত্যের","en":"to the truth"},{"ar":"وَتَوَاصَوْا","bn":"এবং পরস্পরকে উপদেশ দিয়েছে","en":"and urge one another"},{"ar":"بِالصَّبْرِ","bn":"ধৈর্যের","en":"to patience"}],"tr":{"bn":"ইল্লাল্লাযীনা আ-মানূ ওয়া 'আমিলুস সা-লিহা-তি ওয়া তাওয়া-সাও বিল হাক্কি ওয়া তাওয়া-সাও বিস সাবর","en":"Illal-ladheena aamanoo wa 'amiluṣ-ṣaaliḥaati wa tawaaṣaw bil-ḥaqqi wa tawaaṣaw biṣ-ṣabr"},"mean":{"bn":"তবে তারা নয়, যারা ঈমান এনেছে, নেক কাজ করেছে, পরস্পরকে সত্যের উপদেশ দিয়েছে এবং পরস্পরকে ধৈর্যের উপদেশ দিয়েছে।","en":"except those who believe, do righteous deeds, urge one another to the truth, and urge one another to patience."}},{"type":"steps","title":{"bn":"ক্ষতি থেকে বাঁচার ৪টি চাবি","en":"4 keys to escape loss"},"items":[{"title":{"bn":"ঈমান","en":"Faith"},"ar":"آمَنُوا","desc":{"bn":"মনে বিশ্বাস — সবকিছুর ভিত্তি।","en":"Belief in the heart — the foundation of everything."}},{"title":{"bn":"নেক আমল","en":"Good deeds"},"ar":"وَعَمِلُوا الصَّالِحَاتِ","desc":{"bn":"বিশ্বাসকে কাজে দেখানো।","en":"Showing belief through action."}},{"title":{"bn":"সত্যের উপদেশ","en":"Urging the truth"},"ar":"وَتَوَاصَوْا بِالْحَقِّ","desc":{"bn":"শুধু নিজে নয় — অন্যকেও ভালোর দিকে ডাকা।","en":"Not only yourself — inviting others to good too."}},{"title":{"bn":"ধৈর্যের উপদেশ","en":"Urging patience"},"ar":"وَتَوَاصَوْا بِالصَّبْرِ","desc":{"bn":"কঠিন সময়ে একে অপরকে সাহস দেওয়া।","en":"Encouraging each other through hard times."}}]},{"type":"tip","kind":"fun","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"ইমাম শাফেয়ী (রহ.) বলেছেন বলে বর্ণিত আছে: মানুষ যদি শুধু এই সূরা নিয়েই চিন্তা করত, তবে এটাই তাদের জন্য যথেষ্ট হতো। সময় যেন রোদে রাখা বরফ — ব্যবহার না করলেও গলে যায়। তাই আজকের দিনটা ঈমান, ভালো কাজ, সত্য আর ধৈর্যে কাজে লাগাও।","en":"Imam ash-Shafi'i is reported to have said: if people reflected on this surah alone, it would be enough for them. Time is like ice in the sun — it melts away even if you don't use it. So spend today on faith, good deeds, truth and patience."},{"type":"vocab","items":[{"ar":"أَعْطَى","tr":{"bn":"আ'তা","en":"a'ṭaa"},"mean":{"bn":"দিলেন, দান করলেন","en":"he gave"},"root":"ع ط و"},{"ar":"رَبُّكَ","tr":{"bn":"রাব্বুকা","en":"rabbuka"},"mean":{"bn":"তোমার রব","en":"your Lord"},"root":"ر ب ب"},{"ar":"الْإِنْسَانُ","tr":{"bn":"আল-ইনসান","en":"al-insaan"},"mean":{"bn":"মানুষ","en":"human being"},"root":"ا ن س"},{"ar":"خُسْرٌ","tr":{"bn":"খুসর","en":"khusr"},"mean":{"bn":"ক্ষতি","en":"loss"},"root":"خ س ر"},{"ar":"الْحَقُّ","tr":{"bn":"আল-হাক্ক","en":"al-ḥaqq"},"mean":{"bn":"সত্য","en":"the truth"},"root":"ح ق ق"},{"ar":"الصَّبْرُ","tr":{"bn":"আস-সাবর","en":"aṣ-ṣabr"},"mean":{"bn":"ধৈর্য","en":"patience"},"root":"ص ب ر"}]},{"type":"quiz","items":[{"q":{"bn":"হাদীস অনুযায়ী {{الْكَوْثَرَ}} কী?","en":"According to the hadith, what is {{الْكَوْثَرَ}}?"},"options":[{"bn":"জান্নাতের একটি নহর","en":"a river in Paradise"},{"bn":"একটি পাহাড়","en":"a mountain"},{"bn":"একটি মসজিদ","en":"a masjid"}],"answer":0},{"q":{"bn":"{{وَانْحَرْ}} অর্থ কী?","en":"What does {{وَانْحَرْ}} mean?"},"options":[{"bn":"এবং কুরবানি করুন","en":"and sacrifice"},{"bn":"এবং ধৈর্য ধরুন","en":"and be patient"},{"bn":"এবং ক্ষমা চান","en":"and seek forgiveness"}],"answer":0},{"q":{"bn":"{{الْأَبْتَرُ}} কাকে বলা হয়েছে?","en":"Who is called {{الْأَبْتَرُ}}?"},"options":[{"bn":"নবী ﷺ-এর বিদ্বেষীকে","en":"the Prophet's ﷺ hater"},{"bn":"নবী ﷺ-কে","en":"the Prophet ﷺ"},{"bn":"মুমিনদের","en":"the believers"}],"answer":0},{"q":{"bn":"{{الْعَصْرِ}} অর্থ কী?","en":"What does {{الْعَصْرِ}} mean?"},"options":[{"bn":"সময়","en":"time"},{"bn":"ভোর","en":"daybreak"},{"bn":"রাত","en":"night"}],"answer":0},{"q":{"bn":"{{خُسْرٍ}} মানে কী?","en":"What does {{خُسْرٍ}} mean?"},"options":[{"bn":"সফলতা","en":"success"},{"bn":"ক্ষতি","en":"loss"},{"bn":"ধৈর্য","en":"patience"}],"answer":1},{"q":{"bn":"সূরা আসরে ক্ষতি থেকে বাঁচার গুণ কয়টি?","en":"How many qualities save from loss in Al-'Asr?"},"options":["২ / 2","৩ / 3","৪ / 4"],"answer":2},{"q":{"bn":"কুরআনের সবচেয়ে ছোট সূরা কোনটি?","en":"Which is the shortest surah of the Quran?"},"options":[{"bn":"আল-আসর","en":"Al-'Asr"},{"bn":"আল-কাওসার","en":"Al-Kawthar"},{"bn":"আল-ইখলাস","en":"Al-Ikhlas"}],"answer":1}]}]},{"id":"quran-nasr-fil","icon":"١١٠","title":{"bn":"সূরা আন-নাসর, আল-ফীল ও কুরাইশ","en":"Surah An-Nasr, Al-Fil & Quraysh"},"subtitle":{"bn":"বিজয়ের সূরা, হাতির ঘটনা আর কুরাইশের প্রতি অনুগ্রহ","en":"The surah of victory, the story of the elephant, and Allah's favour on Quraysh"},"minutes":20,"goals":[{"bn":"সূরা নাসর, ফীল ও কুরাইশ শব্দে শব্দে বুঝব","en":"Understand An-Nasr, Al-Fil and Quraysh word by word"},{"bn":"হাতির বছরের ঘটনা জানব","en":"Learn the story of the Year of the Elephant"},{"bn":"সফলতার পরে কী করতে হয় — সূরা নাসর থেকে শিখব","en":"Learn from An-Nasr what to do after success"}],"blocks":[{"type":"text","title":{"bn":"সূরা আন-নাসর (১১০)","en":"Surah An-Nasr (110)"},"bn":"এটি সবশেষে নাযিল হওয়া সূরাগুলোর একটি। মক্কা বিজয়ের পর দলে দলে মানুষ ইসলামে আসছিল — এই সূরা সেই বিজয়ের কথা বলে, আর শেখায় বিজয়ের পর কী করতে হয়।","en":"This is among the last surahs revealed. After the conquest of Makkah, people were entering Islam in crowds — this surah speaks of that victory and teaches what to do after it."},{"type":"ayah","ref":"110:1","ar":"إِذَا جَاءَ نَصْرُ اللّٰهِ وَالْفَتْحُ","words":[{"ar":"إِذَا","bn":"যখন","en":"When"},{"ar":"جَاءَ","bn":"আসে","en":"comes"},{"ar":"نَصْرُ اللّٰهِ","bn":"আল্লাহর সাহায্য","en":"the help of Allah"},{"ar":"وَالْفَتْحُ","bn":"ও বিজয়","en":"and the victory"}],"tr":{"bn":"ইযা জা-আ নাসরুল্লা-হি ওয়াল ফাতহ","en":"Idhaa jaa'a naṣrullaahi wal-fatḥ"},"mean":{"bn":"যখন আল্লাহর সাহায্য ও বিজয় আসবে,","en":"When the help of Allah and the victory come,"}},{"type":"ayah","ref":"110:2","ar":"وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللّٰهِ أَفْوَاجًا","words":[{"ar":"وَرَأَيْتَ","bn":"এবং আপনি দেখবেন","en":"and you see"},{"ar":"النَّاسَ","bn":"মানুষকে","en":"the people"},{"ar":"يَدْخُلُونَ","bn":"প্রবেশ করছে","en":"entering"},{"ar":"فِي دِينِ اللّٰهِ","bn":"আল্লাহর দ্বীনে","en":"into the religion of Allah"},{"ar":"أَفْوَاجًا","bn":"দলে দলে","en":"in crowds"}],"tr":{"bn":"ওয়া রা-আইতান না-সা ইয়াদখুলূনা ফী দীনিল্লা-হি আফওয়া-জা","en":"Wa ra'aytan-naasa yadkhuloona fee deenillaahi afwaajaa"},"mean":{"bn":"আর আপনি দেখবেন, মানুষ দলে দলে আল্লাহর দ্বীনে প্রবেশ করছে,","en":"and you see people entering the religion of Allah in crowds,"}},{"type":"ayah","ref":"110:3","ar":"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا","words":[{"ar":"فَسَبِّحْ","bn":"তখন পবিত্রতা ঘোষণা করুন","en":"then glorify"},{"ar":"بِحَمْدِ رَبِّكَ","bn":"আপনার রবের প্রশংসাসহ","en":"with the praise of your Lord"},{"ar":"وَاسْتَغْفِرْهُ","bn":"এবং তাঁর কাছে ক্ষমা চান","en":"and ask His forgiveness"},{"ar":"إِنَّهُ","bn":"নিশ্চয়ই তিনি","en":"indeed He"},{"ar":"كَانَ","bn":"হলেন","en":"is ever"},{"ar":"تَوَّابًا","bn":"তাওবা কবুলকারী","en":"accepting of repentance"}],"tr":{"bn":"ফাসাব্বিহ বিহামদি রাব্বিকা ওয়াসতাগফিরহ, ইন্নাহূ কা-না তাওয়্যা-বা","en":"Fasabbiḥ biḥamdi rabbika wastaghfirh, innahoo kaana tawwaabaa"},"mean":{"bn":"তখন আপনার রবের প্রশংসাসহ তাঁর পবিত্রতা ঘোষণা করুন এবং তাঁর কাছে ক্ষমা চান; নিশ্চয়ই তিনি বারবার তাওবা কবুলকারী।","en":"then glorify your Lord with His praise and ask His forgiveness; indeed, He is ever accepting of repentance."}},{"type":"tip","kind":"fun","bn":"উমর (রা.) সাহাবীদের জিজ্ঞেস করলেন এই সূরার অর্থ কী। তরুণ ইবনে আব্বাস (রা.) বললেন: এটি নবী ﷺ-কে জানিয়ে দিচ্ছে যে তাঁর দুনিয়ার কাজ শেষ হয়ে আসছে। উমর (রা.) বললেন, ‘আমিও এটাই বুঝি।’ (সহীহ বুখারী) আয়েশা (রা.) বলেন, এরপর নবী ﷺ রুকু-সিজদায় প্রায়ই বলতেন: {{سُبْحَانَكَ اللّٰهُمَّ رَبَّنَا وَبِحَمْدِكَ اللّٰهُمَّ اغْفِرْ لِي}}। (বুখারী, মুসলিম)","en":"'Umar asked the companions what this surah meant. Young Ibn 'Abbas said: it tells the Prophet ﷺ that his mission in this world is nearing its end. 'Umar said, ‘I understand the same.’ (Sahih al-Bukhari) 'A'ishah said that afterwards the Prophet ﷺ often said in ruku' and sujud: {{سُبْحَانَكَ اللّٰهُمَّ رَبَّنَا وَبِحَمْدِكَ اللّٰهُمَّ اغْفِرْ لِي}}. (Bukhari, Muslim)"},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"পরীক্ষায় ভালো রেজাল্ট, খেলায় জয়, কাজে সফলতা — তখন কী করব? সূরা নাসর বলে: অহংকার নয়, বরং {{سُبْحَانَ اللّٰهِ}}, {{الْحَمْدُ لِلّٰهِ}} আর {{أَسْتَغْفِرُ اللّٰهَ}}। সফলতা আল্লাহর দান — আমার একার কৃতিত্ব নয়।","en":"A great exam result, a win in a match, success at work — what then? An-Nasr says: not pride, but {{سُبْحَانَ اللّٰهِ}}, {{الْحَمْدُ لِلّٰهِ}} and {{أَسْتَغْفِرُ اللّٰهَ}}. Success is Allah's gift — not my achievement alone."},{"type":"text","title":{"bn":"সূরা আল-ফীল (১০৫)","en":"Surah Al-Fil (105)"},"bn":"নবী ﷺ-এর জন্মের বছর ইয়েমেনের শাসক আবরাহা বিশাল সৈন্যবাহিনী আর হাতি নিয়ে কাবা ভাঙতে এসেছিল। মক্কাবাসীর তাকে থামানোর শক্তি ছিল না — কিন্তু আল্লাহ নিজেই তাঁর ঘর রক্ষা করলেন। এই বছরকে বলে ‘আমুল ফীল’ — হাতির বছর।","en":"In the year the Prophet ﷺ was born, Abrahah, ruler of Yemen, marched with a huge army and an elephant to destroy the Ka'bah. The people of Makkah had no power to stop him — but Allah Himself protected His House. That year is called ‘'Aam al-Feel’ — the Year of the Elephant."},{"type":"ayah","ref":"105:1","ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ","words":[{"ar":"أَلَمْ تَرَ","bn":"আপনি কি দেখেননি","en":"Have you not seen"},{"ar":"كَيْفَ","bn":"কেমন","en":"how"},{"ar":"فَعَلَ","bn":"করেছিলেন","en":"dealt"},{"ar":"رَبُّكَ","bn":"আপনার রব","en":"your Lord"},{"ar":"بِأَصْحَابِ","bn":"অধিপতিদের সাথে","en":"with the companions"},{"ar":"الْفِيلِ","bn":"হাতির","en":"of the elephant"}],"tr":{"bn":"আলাম তারা কাইফা ফা'আলা রাব্বুকা বিআসহা-বিল ফীল","en":"Alam tara kayfa fa'ala rabbuka bi'aṣḥaabil-feel"},"mean":{"bn":"আপনি কি দেখেননি, আপনার রব হাতিওয়ালাদের সাথে কী করেছিলেন?","en":"Have you not seen how your Lord dealt with the people of the elephant?"}},{"type":"ayah","ref":"105:2","ar":"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ","words":[{"ar":"أَلَمْ يَجْعَلْ","bn":"তিনি কি করে দেননি","en":"Did He not make"},{"ar":"كَيْدَهُمْ","bn":"তাদের চক্রান্ত","en":"their plot"},{"ar":"فِي تَضْلِيلٍ","bn":"ব্যর্থ","en":"go astray (fail)"}],"tr":{"bn":"আলাম ইয়াজ'আল কাইদাহুম ফী তাদলীল","en":"Alam yaj'al kaydahum fee taḍleel"},"mean":{"bn":"তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?","en":"Did He not make their plot fail completely?"}},{"type":"ayah","ref":"105:3","ar":"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","words":[{"ar":"وَأَرْسَلَ","bn":"এবং তিনি পাঠালেন","en":"And He sent"},{"ar":"عَلَيْهِمْ","bn":"তাদের উপর","en":"against them"},{"ar":"طَيْرًا","bn":"পাখি","en":"birds"},{"ar":"أَبَابِيلَ","bn":"ঝাঁকে ঝাঁকে","en":"in flocks"}],"tr":{"bn":"ওয়া আরসালা 'আলাইহিম তাইরান আবা-বীল","en":"Wa arsala 'alayhim ṭayran abaabeel"},"mean":{"bn":"আর তিনি তাদের উপর ঝাঁকে ঝাঁকে পাখি পাঠালেন,","en":"And He sent against them birds in flocks,"}},{"type":"ayah","ref":"105:4","ar":"تَرْمِيهِمْ بِحِجَارَةٍ مِّنْ سِجِّيلٍ","words":[{"ar":"تَرْمِيهِمْ","bn":"যারা তাদের উপর ছুড়ছিল","en":"striking them"},{"ar":"بِحِجَارَةٍ","bn":"পাথর","en":"with stones"},{"ar":"مِّنْ سِجِّيلٍ","bn":"পোড়া মাটির","en":"of baked clay"}],"tr":{"bn":"তারমীহিম বিহিজা-রাতিম মিন সিজ্জীল","en":"Tarmeehim biḥijaaratim min sijjeel"},"mean":{"bn":"যারা তাদের উপর পোড়া মাটির পাথর ছুড়ছিল,","en":"pelting them with stones of baked clay,"}},{"type":"ayah","ref":"105:5","ar":"فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ","words":[{"ar":"فَجَعَلَهُمْ","bn":"ফলে তিনি তাদের করে দিলেন","en":"So He made them"},{"ar":"كَعَصْفٍ","bn":"ভুসির মতো","en":"like straw"},{"ar":"مَّأْكُولٍ","bn":"চিবানো / খাওয়া","en":"eaten up"}],"tr":{"bn":"ফাজা'আলাহুম কা'আসফিম মা'কূল","en":"Faja'alahum ka'aṣfim ma'kool"},"mean":{"bn":"ফলে তিনি তাদের চিবানো ভুসির মতো করে দিলেন।","en":"So He made them like chewed-up straw."}},{"type":"text","title":{"bn":"সূরা কুরাইশ (১০৬)","en":"Surah Quraysh (106)"},"bn":"সূরা ফীলের ঠিক পরের সূরা। কাবা রক্ষা পাওয়ায় কুরাইশ গোত্র নিরাপদে শীতে ইয়েমেনে আর গ্রীষ্মে শামে (সিরিয়া অঞ্চলে) বাণিজ্য-সফর করত। আল্লাহ মনে করিয়ে দিচ্ছেন — এই নিরাপত্তা আর রিযিক কার দান?","en":"The surah right after Al-Fil. Because the Ka'bah was protected, the Quraysh tribe travelled safely for trade — to Yemen in winter and to Sham (Syria region) in summer. Allah reminds them: whose gift is this safety and provision?"},{"type":"ayah","ref":"106:1","ar":"لِإِيلَافِ قُرَيْشٍ","words":[{"ar":"لِإِيلَافِ","bn":"অভ্যস্ততার কারণে / নিরাপত্তার জন্য","en":"For the security / familiarity"},{"ar":"قُرَيْشٍ","bn":"কুরাইশের","en":"of Quraysh"}],"tr":{"bn":"লিঈলা-ফি কুরাইশ","en":"Li'eelaafi Quraysh"},"mean":{"bn":"কুরাইশের নিরাপদ অভ্যস্ত জীবনের জন্য —","en":"For the secure, familiar life of Quraysh —"}},{"type":"ayah","ref":"106:2","ar":"إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ","words":[{"ar":"إِيلَافِهِمْ","bn":"তাদের অভ্যস্ততা","en":"their familiarity with"},{"ar":"رِحْلَةَ","bn":"সফরে","en":"the journey"},{"ar":"الشِّتَاءِ","bn":"শীতের","en":"of winter"},{"ar":"وَالصَّيْفِ","bn":"ও গ্রীষ্মের","en":"and summer"}],"tr":{"bn":"ঈলা-ফিহিম রিহলাতাশ শিতা-য়ি ওয়াস সাইফ","en":"Eelaafihim riḥlatash-shitaa'i waṣ-ṣayf"},"mean":{"bn":"শীত ও গ্রীষ্মের সফরে তাদের নিরাপদ অভ্যস্ততার জন্য,","en":"their safe journeys of winter and summer,"}},{"type":"ayah","ref":"106:3","ar":"فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِ","words":[{"ar":"فَلْيَعْبُدُوا","bn":"তাই তারা যেন ইবাদত করে","en":"so let them worship"},{"ar":"رَبَّ","bn":"রবের","en":"the Lord"},{"ar":"هٰذَا الْبَيْتِ","bn":"এই ঘরের (কাবার)","en":"of this House (the Ka'bah)"}],"tr":{"bn":"ফালইয়া'বুদূ রাব্বা হা-যাল বাইত","en":"Falya'budoo rabba haadhal-bayt"},"mean":{"bn":"তাই তারা যেন এই ঘরের রবের ইবাদত করে,","en":"so let them worship the Lord of this House,"}},{"type":"ayah","ref":"106:4","ar":"الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَّآمَنَهُمْ مِنْ خَوْفٍ","words":[{"ar":"الَّذِي","bn":"যিনি","en":"who"},{"ar":"أَطْعَمَهُمْ","bn":"তাদের খাবার দিয়েছেন","en":"fed them"},{"ar":"مِنْ جُوعٍ","bn":"ক্ষুধায়","en":"against hunger"},{"ar":"وَّآمَنَهُمْ","bn":"এবং তাদের নিরাপত্তা দিয়েছেন","en":"and made them safe"},{"ar":"مِنْ خَوْفٍ","bn":"ভয় থেকে","en":"from fear"}],"tr":{"bn":"আল্লাযী আত'আমাহুম মিন জূ'ইওঁ ওয়া আ-মানাহুম মিন খাওফ","en":"Alladhee aṭ'amahum min joo'iw-wa aamanahum min khawf"},"mean":{"bn":"যিনি তাদের ক্ষুধায় খাবার দিয়েছেন এবং ভয় থেকে নিরাপত্তা দিয়েছেন।","en":"who fed them against hunger and made them safe from fear."}},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"পেট ভরা খাবার আর নিরাপদ ঘর — এ দুটোকে আমরা সাধারণ মনে করি। সূরা কুরাইশ বলে: এগুলো আল্লাহর বিশেষ দান, আর এর শুকরিয়া হলো তাঁর ইবাদত করা। আজ খাওয়ার সময় একবার ভেবো — এই খাবার কে দিলেন?","en":"A full stomach and a safe home — we take them for granted. Surah Quraysh says: these are special gifts from Allah, and the way to thank Him is to worship Him. At your next meal, think for a moment — who gave me this food?"},{"type":"quiz","items":[{"q":{"bn":"{{أَفْوَاجًا}} অর্থ কী?","en":"What does {{أَفْوَاجًا}} mean?"},"options":[{"bn":"দলে দলে","en":"in crowds"},{"bn":"একা একা","en":"one by one"},{"bn":"দ্রুত","en":"quickly"}],"answer":0},{"q":{"bn":"সূরা নাসর অনুযায়ী বিজয়ের পর কী করতে হবে?","en":"According to An-Nasr, what should be done after victory?"},"options":[{"bn":"উৎসব করা","en":"celebrate loudly"},{"bn":"রবের প্রশংসা ও ক্ষমা প্রার্থনা","en":"praise the Lord and seek forgiveness"},{"bn":"বিশ্রাম নেওয়া","en":"rest"}],"answer":1},{"q":{"bn":"{{تَوَّابًا}} মানে কী?","en":"What does {{تَوَّابًا}} mean?"},"options":[{"bn":"বারবার তাওবা কবুলকারী","en":"ever accepting of repentance"},{"bn":"সবচেয়ে বড়","en":"the greatest"},{"bn":"সাহায্যকারী","en":"the helper"}],"answer":0},{"q":{"bn":"{{طَيْرًا أَبَابِيلَ}} কী?","en":"What are {{طَيْرًا أَبَابِيلَ}}?"},"options":[{"bn":"ঝাঁকে ঝাঁকে পাখি","en":"birds in flocks"},{"bn":"হাতির দল","en":"a herd of elephants"},{"bn":"সৈন্যবাহিনী","en":"an army"}],"answer":0},{"q":{"bn":"{{سِجِّيلٍ}} অর্থ কী?","en":"What does {{سِجِّيلٍ}} mean?"},"options":[{"bn":"লোহা","en":"iron"},{"bn":"পোড়া মাটি","en":"baked clay"},{"bn":"বালি","en":"sand"}],"answer":1},{"q":{"bn":"কুরাইশরা কোন দুই ঋতুতে বাণিজ্য-সফর করত?","en":"In which two seasons did Quraysh travel for trade?"},"options":[{"bn":"শীত ও গ্রীষ্ম","en":"winter and summer"},{"bn":"বর্ষা ও বসন্ত","en":"monsoon and spring"},{"bn":"শরৎ ও হেমন্ত","en":"autumn and late autumn"}],"answer":0},{"q":{"bn":"কোন আয়াতে বলা হয়েছে ‘তাদের ক্ষুধায় খাবার দিয়েছেন’?","en":"Which ayah says ‘He fed them against hunger’?"},"options":["فَلْيَعْبُدُوا رَبَّ هٰذَا الْبَيْتِ","الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَّآمَنَهُمْ مِنْ خَوْفٍ","لِإِيلَافِ قُرَيْشٍ"],"answer":1}]}]},{"id":"quran-ayatul-kursi","icon":"كرسي","title":{"bn":"আয়াতুল কুরসী","en":"Ayat al-Kursi"},"subtitle":{"bn":"কুরআনের সবচেয়ে মর্যাদাপূর্ণ আয়াত — শব্দগুচ্ছে শব্দগুচ্ছে","en":"The greatest ayah of the Quran — phrase by phrase"},"minutes":20,"goals":[{"bn":"আয়াতুল কুরসীর প্রতিটি শব্দগুচ্ছের অর্থ জানব","en":"Know the meaning of every phrase of Ayat al-Kursi"},{"bn":"এতে আল্লাহর কোন কোন গুণ এসেছে তা চিনব","en":"Recognise the qualities of Allah it describes"},{"bn":"কখন পড়লে বিশেষ ফযিলত — সহীহ হাদীস থেকে জানব","en":"Learn from authentic hadith when to recite it"}],"blocks":[{"type":"text","bn":"নবী ﷺ সাহাবী উবাই ইবনে কা'ব (রা.)-কে জিজ্ঞেস করলেন, ‘কুরআনের কোন আয়াত সবচেয়ে মহান?’ তিনি বললেন, {{اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ}}। নবী ﷺ খুশি হয়ে তাঁর বুকে হাত রেখে বললেন, ‘তোমার জ্ঞান তোমার জন্য আনন্দময় হোক!’ (সহীহ মুসলিম) এটি সূরা বাকারার ২৫৫ নম্বর আয়াত।","en":"The Prophet ﷺ asked the companion Ubayy ibn Ka'b, ‘Which ayah of the Quran is the greatest?’ He answered, {{اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ}}. The Prophet ﷺ, pleased, placed his hand on his chest and said, ‘May your knowledge bring you joy!’ (Sahih Muslim) It is ayah 255 of Surah Al-Baqarah."},{"type":"ayah","ref":"2:255","ar":"اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَّلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ","words":[{"ar":"اللّٰهُ","bn":"আল্লাহ","en":"Allah"},{"ar":"لَا إِلٰهَ إِلَّا هُوَ","bn":"তিনি ছাড়া কোনো ইলাহ নেই","en":"there is no god but He"},{"ar":"الْحَيُّ","bn":"চিরঞ্জীব","en":"the Ever-Living"},{"ar":"الْقَيُّومُ","bn":"সবকিছুর ধারক","en":"the Sustainer of all"},{"ar":"لَا تَأْخُذُهُ","bn":"তাঁকে স্পর্শ করে না","en":"does not overtake Him"},{"ar":"سِنَةٌ وَّلَا نَوْمٌ","bn":"তন্দ্রা, না ঘুম","en":"drowsiness nor sleep"},{"ar":"لَهُ","bn":"তাঁরই","en":"to Him belongs"},{"ar":"مَا فِي السَّمَاوَاتِ","bn":"যা কিছু আকাশসমূহে","en":"whatever is in the heavens"},{"ar":"وَمَا فِي الْأَرْضِ","bn":"ও যা কিছু পৃথিবীতে","en":"and whatever is on the earth"},{"ar":"مَنْ ذَا الَّذِي","bn":"কে আছে এমন","en":"who is it that"},{"ar":"يَشْفَعُ عِنْدَهُ","bn":"তাঁর কাছে সুপারিশ করবে","en":"can intercede with Him"},{"ar":"إِلَّا بِإِذْنِهِ","bn":"তাঁর অনুমতি ছাড়া","en":"except by His permission"},{"ar":"يَعْلَمُ","bn":"তিনি জানেন","en":"He knows"},{"ar":"مَا بَيْنَ أَيْدِيهِمْ","bn":"যা তাদের সামনে আছে","en":"what is before them"},{"ar":"وَمَا خَلْفَهُمْ","bn":"ও যা তাদের পেছনে আছে","en":"and what is behind them"},{"ar":"وَلَا يُحِيطُونَ","bn":"আর তারা আয়ত্ত করতে পারে না","en":"and they cannot grasp"},{"ar":"بِشَيْءٍ مِّنْ عِلْمِهِ","bn":"তাঁর জ্ঞানের কিছুই","en":"anything of His knowledge"},{"ar":"إِلَّا بِمَا شَاءَ","bn":"তিনি যতটুকু চান তা ছাড়া","en":"except what He wills"},{"ar":"وَسِعَ","bn":"পরিব্যাপ্ত","en":"extends over"},{"ar":"كُرْسِيُّهُ","bn":"তাঁর কুরসী","en":"His Kursi (Footstool)"},{"ar":"السَّمَاوَاتِ وَالْأَرْضَ","bn":"আকাশসমূহ ও পৃথিবী","en":"the heavens and the earth"},{"ar":"وَلَا يَئُودُهُ","bn":"আর তাঁকে ক্লান্ত করে না","en":"and it does not tire Him"},{"ar":"حِفْظُهُمَا","bn":"এ দুটির রক্ষণাবেক্ষণ","en":"guarding them both"},{"ar":"وَهُوَ الْعَلِيُّ","bn":"আর তিনিই সর্বোচ্চ","en":"and He is the Most High"},{"ar":"الْعَظِيمُ","bn":"মহান","en":"the Magnificent"}],"tr":{"bn":"আল্লা-হু লা ইলা-হা ইল্লা হুওয়াল হাইয়্যুল কাইয়্যূম, লা তা'খুযুহূ সিনাতুঁও ওয়ালা নাওম, লাহূ মা ফিস সামা-ওয়া-তি ওয়ামা ফিল আরদ, মান যাল্লাযী ইয়াশফা'উ 'ইনদাহূ ইল্লা বিইযনিহ, ইয়া'লামু মা বাইনা আইদীহিম ওয়ামা খালফাহুম, ওয়ালা ইউহীতূনা বিশাইয়িম মিন 'ইলমিহী ইল্লা বিমা শা-আ, ওয়াসি'আ কুরসিয়্যুহুস সামা-ওয়া-তি ওয়াল আরদ, ওয়ালা ইয়াঊদুহূ হিফযুহুমা, ওয়া হুওয়াল 'আলিয়্যুল 'আযীম","en":"Allaahu laa ilaaha illaa huwal-ḥayyul-qayyoom, laa ta'khudhuhoo sinatuw-wa laa nawm, lahoo maa fis-samaawaati wa maa fil-arḍ, man dhal-ladhee yashfa'u 'indahoo illaa bi'idhnih, ya'lamu maa bayna aydeehim wa maa khalfahum, wa laa yuḥeeṭoona bishay'im min 'ilmihee illaa bimaa shaa', wasi'a kursiyyuhus-samaawaati wal-arḍ, wa laa ya'ooduhoo ḥifẓuhumaa, wa huwal-'aliyyul-'aẓeem"},"mean":{"bn":"আল্লাহ — তিনি ছাড়া কোনো ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা বা ঘুম তাঁকে স্পর্শ করে না। আকাশসমূহ ও পৃথিবীতে যা কিছু আছে সব তাঁরই। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? মানুষের সামনে-পেছনে যা আছে সবই তিনি জানেন; আর তিনি যতটুকু চান, তার বাইরে তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসী আকাশসমূহ ও পৃথিবী জুড়ে বিস্তৃত, আর এ দুটির রক্ষণাবেক্ষণ তাঁকে একটুও ক্লান্ত করে না। তিনিই সর্বোচ্চ, মহান।","en":"Allah — there is no god but He, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who could intercede with Him except by His permission? He knows what is before them and what is behind them, and they grasp nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and guarding them both does not tire Him at all. He is the Most High, the Magnificent."}},{"type":"table","title":{"bn":"১০টি বাক্যে আয়াতুল কুরসী","en":"Ayat al-Kursi in 10 sentences"},"head":["#",{"bn":"আরবি","en":"Arabic"},{"bn":"মূল বার্তা","en":"Core message"}],"rows":[["1","اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ",{"bn":"উপাস্য শুধু তিনিই","en":"He alone is worthy of worship"}],["2","الْحَيُّ الْقَيُّومُ",{"bn":"চিরঞ্জীব, সবকিছু তাঁর উপর টিকে আছে","en":"Ever-Living; everything stands by Him"}],["3","لَا تَأْخُذُهُ سِنَةٌ وَّلَا نَوْمٌ",{"bn":"তাঁর কোনো দুর্বলতা নেই","en":"He has no weakness"}],["4","لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ",{"bn":"সবকিছুর মালিক তিনি","en":"He owns everything"}],["5","مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ",{"bn":"তাঁর অনুমতি ছাড়া কেউ সুপারিশ করতে পারে না","en":"No one intercedes without His permission"}],["6","يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ",{"bn":"অতীত-ভবিষ্যৎ সব তিনি জানেন","en":"He knows past and future"}],["7","وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ",{"bn":"আমাদের জ্ঞান তাঁরই দান","en":"Our knowledge is only what He grants"}],["8","وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ",{"bn":"তাঁর কুরসী সবকিছুর চেয়ে বিশাল","en":"His Kursi is vaster than all creation"}],["9","وَلَا يَئُودُهُ حِفْظُهُمَا",{"bn":"মহাবিশ্ব চালাতে তাঁর ক্লান্তি নেই","en":"Running the universe never tires Him"}],["10","وَهُوَ الْعَلِيُّ الْعَظِيمُ",{"bn":"তিনি সর্বোচ্চ, মহান","en":"He is the Most High, the Magnificent"}]]},{"type":"tip","kind":"memory","bn":"আয়াতটি শুরু হয় {{اللّٰهُ}} দিয়ে আর শেষ হয় {{الْعَظِيمُ}} দিয়ে। শুরু ও শেষ দুটোই আল্লাহর পরিচয় — মাঝখানে তাঁর জীবন, ক্ষমতা, মালিকানা আর জ্ঞানের বর্ণনা। এভাবে ভাগ করে মুখস্থ করলে সহজ হয়।","en":"The ayah begins with {{اللّٰهُ}} and ends with {{الْعَظِيمُ}}. Both ends name Allah — in between come His life, power, ownership and knowledge. Memorising it in these chunks makes it easy."},{"type":"steps","title":{"bn":"কখন পড়ব?","en":"When to recite it"},"items":[{"title":{"bn":"ঘুমানোর আগে","en":"Before sleeping"},"desc":{"bn":"নবী ﷺ জানিয়েছেন, রাতে বিছানায় গিয়ে আয়াতুল কুরসী পড়লে সকাল পর্যন্ত আল্লাহর পক্ষ থেকে একজন রক্ষক থাকে, আর শয়তান কাছে আসতে পারে না। (সহীহ বুখারী)","en":"The Prophet ﷺ confirmed that whoever recites Ayat al-Kursi on going to bed has a guardian from Allah until morning, and Satan cannot come near. (Sahih al-Bukhari)"}},{"title":{"bn":"প্রতি ফরজ নামাজের পর","en":"After every fard prayer"},"desc":{"bn":"হাদীসে আছে, যে প্রতি ফরজ নামাজের পর আয়াতুল কুরসী পড়ে, মৃত্যু ছাড়া তার জান্নাতে যাওয়ার পথে আর কোনো বাধা থাকে না। (নাসাঈ; মুহাদ্দিসগণ সহীহ বলেছেন)","en":"A hadith says whoever recites Ayat al-Kursi after every fard prayer, nothing stands between him and Paradise except death. (An-Nasa'i; graded authentic by hadith scholars)"}}]},{"type":"tip","kind":"fun","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"আমরা ঘুমালে সব ছেড়ে দিই — কিন্তু আল্লাহ কখনো ঘুমান না, কখনো ক্লান্ত হন না। তাই রাতে ভয় লাগলে বা দুশ্চিন্তা হলে মনে রাখো: যিনি পুরো আকাশ-পৃথিবী রক্ষা করছেন, তিনি তোমাকেও দেখছেন। নিশ্চিন্তে ঘুমাও!","en":"When we sleep we let go of everything — but Allah never sleeps and never tires. So when you feel afraid or worried at night, remember: the One guarding all the heavens and the earth is watching over you too. Sleep in peace!"},{"type":"vocab","items":[{"ar":"الْحَيُّ","tr":{"bn":"আল-হাইয়্যু","en":"al-ḥayy"},"mean":{"bn":"চিরঞ্জীব","en":"the Ever-Living"},"root":"ح ي ي"},{"ar":"الْقَيُّومُ","tr":{"bn":"আল-কাইয়্যূম","en":"al-qayyoom"},"mean":{"bn":"সবকিছুর ধারক","en":"the Self-Sustaining Sustainer"},"root":"ق و م"},{"ar":"نَوْمٌ","tr":{"bn":"নাওম","en":"nawm"},"mean":{"bn":"ঘুম","en":"sleep"},"root":"ن و م"},{"ar":"السَّمَاوَاتُ","tr":{"bn":"আস-সামাওয়াত","en":"as-samaawaat"},"mean":{"bn":"আকাশসমূহ","en":"the heavens"},"root":"س م و"},{"ar":"الْأَرْضُ","tr":{"bn":"আল-আরদ","en":"al-arḍ"},"mean":{"bn":"পৃথিবী, জমিন","en":"the earth"},"root":"ا ر ض"},{"ar":"عِلْمٌ","tr":{"bn":"'ইলম","en":"'ilm"},"mean":{"bn":"জ্ঞান","en":"knowledge"},"root":"ع ل م"},{"ar":"الْعَلِيُّ","tr":{"bn":"আল-'আলিয়্যু","en":"al-'aliyy"},"mean":{"bn":"সর্বোচ্চ","en":"the Most High"},"root":"ع ل و"}]},{"type":"quiz","items":[{"q":{"bn":"{{الْقَيُّومُ}} অর্থ কী?","en":"What does {{الْقَيُّومُ}} mean?"},"options":[{"bn":"সবকিছুর ধারক","en":"the Sustainer of all"},{"bn":"সর্বশ্রোতা","en":"the All-Hearing"},{"bn":"ক্ষমাশীল","en":"the Forgiving"}],"answer":0},{"q":{"bn":"{{سِنَةٌ}} মানে কী?","en":"What does {{سِنَةٌ}} mean?"},"options":[{"bn":"বছর","en":"year"},{"bn":"তন্দ্রা","en":"drowsiness"},{"bn":"সুপারিশ","en":"intercession"}],"answer":1},{"q":{"bn":"কোন অংশ বলে ‘তাঁর অনুমতি ছাড়া কে সুপারিশ করবে?’","en":"Which part says ‘who could intercede without His permission?’"},"options":["وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ","مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ","وَهُوَ الْعَلِيُّ الْعَظِيمُ"],"answer":1},{"q":{"bn":"{{وَلَا يَئُودُهُ حِفْظُهُمَا}} — এর অর্থ কী?","en":"What does {{وَلَا يَئُودُهُ حِفْظُهُمَا}} mean?"},"options":[{"bn":"এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না","en":"guarding them both does not tire Him"},{"bn":"তিনি সবকিছু জানেন","en":"He knows everything"},{"bn":"তাঁকে ঘুম স্পর্শ করে না","en":"sleep does not overtake Him"}],"answer":0},{"q":{"bn":"আয়াতুল কুরসী কোন সূরায়?","en":"Ayat al-Kursi is in which surah?"},"options":[{"bn":"আল-বাকারা","en":"Al-Baqarah"},{"bn":"আল-ফাতিহা","en":"Al-Fatiha"},{"bn":"আল-ইখলাস","en":"Al-Ikhlas"}],"answer":0},{"q":{"bn":"কোন সাহাবী বলেছিলেন আয়াতুল কুরসী সবচেয়ে মহান আয়াত?","en":"Which companion answered that Ayat al-Kursi is the greatest ayah?"},"options":[{"bn":"উবাই ইবনে কা'ব (রা.)","en":"Ubayy ibn Ka'b"},{"bn":"উকবা ইবনে আমের (রা.)","en":"'Uqbah ibn 'Amir"},{"bn":"আনাস (রা.)","en":"Anas"}],"answer":0},{"q":{"bn":"{{الْحَيُّ}} অর্থ কী?","en":"What does {{الْحَيُّ}} mean?"},"options":[{"bn":"চিরঞ্জীব","en":"the Ever-Living"},{"bn":"সর্বোচ্চ","en":"the Most High"},{"bn":"মহান","en":"the Magnificent"}],"answer":0}]}]},{"id":"quran-daily-duas","icon":"دعاء","title":{"bn":"কুরআন ও সুন্নাহর প্রতিদিনের দোয়া","en":"Daily Duas from Quran & Sunnah"},"subtitle":{"bn":"ঘুম থেকে ওঠা থেকে ঘুমাতে যাওয়া — সারাদিন আল্লাহর সাথে","en":"From waking to sleeping — with Allah all day long"},"minutes":25,"goals":[{"bn":"দিনের বিভিন্ন কাজের ছোট ছোট সহীহ দোয়া অর্থসহ শিখব","en":"Learn short authentic duas for daily moments, with meaning"},{"bn":"কুরআনের কয়েকটি সুন্দর দোয়া শব্দে শব্দে বুঝব","en":"Understand several beautiful Quranic duas word by word"},{"bn":"কখন কোন দোয়া পড়তে হয় তা মনে রাখব","en":"Remember which dua to say when"}],"blocks":[{"type":"text","bn":"ইসলামে প্রতিটি সাধারণ কাজই ইবাদত হয়ে যেতে পারে — শুধু একটা ছোট্ট দোয়া দিয়ে। ঘুম, খাওয়া, ঘর থেকে বের হওয়া, সফর — সবকিছুর জন্য নবী ﷺ আমাদের সুন্দর কথা শিখিয়েছেন। চলো, সারাদিনের সঙ্গী এই দোয়াগুলো অর্থসহ শিখি।","en":"In Islam every ordinary action can become worship — with just a little dua. Sleeping, eating, leaving home, travelling — for each the Prophet ﷺ taught us beautiful words. Let us learn these all-day companions with their meanings."},{"type":"examples","title":{"bn":"ঘুম ও জাগরণ","en":"Sleeping & waking"},"items":[{"ar":"الْحَمْدُ لِلّٰهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","tr":{"bn":"আলহামদু লিল্লা-হিল্লাযী আহইয়া-না বা'দা মা আমা-তানা ওয়া ইলাইহিন নুশূর","en":"Al-ḥamdu lillaahil-ladhee aḥyaanaa ba'da maa amaatanaa wa ilayhin-nushoor"},"mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি আমাদের (ঘুমের মতো) মৃত্যুর পর আবার জীবিত করলেন, আর তাঁর কাছেই আমাদের ফিরে যেতে হবে।","en":"All praise is for Allah who gave us life after He had caused us to die (in sleep), and to Him is the return."},"note":{"bn":"ঘুম থেকে উঠে। (সহীহ বুখারী)","en":"On waking up. (Sahih al-Bukhari)"}},{"ar":"بِاسْمِكَ اللّٰهُمَّ أَمُوتُ وَأَحْيَا","tr":{"bn":"বিসমিকা আল্লা-হুম্মা আমূতু ওয়া আহইয়া","en":"Bismika Allaahumma amootu wa aḥyaa"},"mean":{"bn":"হে আল্লাহ! আপনার নামেই আমি মরি (ঘুমাই) ও জীবিত হই (জাগি)।","en":"In Your name, O Allah, I die (sleep) and I live (wake)."},"note":{"bn":"ঘুমানোর সময়। (সহীহ বুখারী)","en":"When going to sleep. (Sahih al-Bukhari)"}}]},{"type":"tip","kind":"memory","bn":"ঘুম যেন ছোট্ট মৃত্যু, আর জেগে ওঠা যেন নতুন জীবন। প্রতিদিন সকালটা আল্লাহর দেওয়া একটা নতুন সুযোগ — তাই দিনের প্রথম কথাই {{الْحَمْدُ لِلّٰهِ}}!","en":"Sleep is like a small death, and waking is like new life. Every morning is a fresh chance from Allah — so the first words of the day are {{الْحَمْدُ لِلّٰهِ}}!"},{"type":"examples","title":{"bn":"খাওয়া-দাওয়া","en":"Eating"},"items":[{"ar":"بِسْمِ اللّٰهِ","tr":{"bn":"বিসমিল্লাহ","en":"Bismillaah"},"mean":{"bn":"আল্লাহর নামে","en":"In the name of Allah"},"note":{"bn":"খাওয়ার শুরুতে; ডান হাতে, নিজের সামনে থেকে খাই। (বুখারী, মুসলিম)","en":"Before eating; eat with the right hand, from what is in front of you. (Bukhari, Muslim)"}},{"ar":"بِسْمِ اللّٰهِ أَوَّلَهُ وَآخِرَهُ","tr":{"bn":"বিসমিল্লা-হি আওয়ালাহূ ওয়া আ-খিরাহ","en":"Bismillaahi awwalahoo wa aakhirah"},"mean":{"bn":"আল্লাহর নামে — এর শুরুতে ও শেষে।","en":"In the name of Allah, at its beginning and its end."},"note":{"bn":"শুরুতে বিসমিল্লাহ বলতে ভুলে গেলে, মনে পড়লেই। (আবু দাউদ, তিরমিযী)","en":"If you forgot Bismillah at the start, say this when you remember. (Abu Dawud, at-Tirmidhi)"}},{"ar":"الْحَمْدُ لِلّٰهِ الَّذِي أَطْعَمَنِي هٰذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tr":{"bn":"আলহামদু লিল্লা-হিল্লাযী আত'আমানী হা-যা ওয়া রাযাকানীহি মিন গাইরি হাওলিম মিন্নী ওয়ালা কুওয়াহ","en":"Al-ḥamdu lillaahil-ladhee aṭ'amanee haadhaa wa razaqaneehi min ghayri ḥawlim minnee wa laa quwwah"},"mean":{"bn":"সব প্রশংসা আল্লাহর, যিনি আমাকে এটা খাওয়ালেন এবং আমার কোনো শক্তি-সামর্থ্য ছাড়াই এই রিযিক দিলেন।","en":"All praise is for Allah who fed me this and provided it for me without any power or strength on my part."},"note":{"bn":"খাওয়া শেষে। (আবু দাউদ, তিরমিযী)","en":"After eating. (Abu Dawud, at-Tirmidhi)"}}]},{"type":"examples","title":{"bn":"ঘর ও মসজিদ","en":"Home & masjid"},"items":[{"ar":"بِسْمِ اللّٰهِ تَوَكَّلْتُ عَلَى اللّٰهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ","tr":{"bn":"বিসমিল্লা-হি তাওয়াক্কালতু 'আলাল্লা-হি ওয়ালা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ","en":"Bismillaahi tawakkaltu 'alallaahi wa laa ḥawla wa laa quwwata illaa billaah"},"mean":{"bn":"আল্লাহর নামে (বের হলাম), আল্লাহর উপর ভরসা করলাম; আল্লাহর সাহায্য ছাড়া কোনো শক্তি ও ক্ষমতা নেই।","en":"In the name of Allah, I rely on Allah; there is no power and no strength except through Allah."},"note":{"bn":"ঘর থেকে বের হওয়ার সময়। (আবু দাউদ, তিরমিযী)","en":"When leaving home. (Abu Dawud, at-Tirmidhi)"}},{"ar":"بِسْمِ اللّٰهِ، السَّلَامُ عَلَيْكُمْ","tr":{"bn":"বিসমিল্লাহ, আসসালামু 'আলাইকুম","en":"Bismillaah, as-salaamu 'alaykum"},"mean":{"bn":"আল্লাহর নামে; তোমাদের উপর শান্তি বর্ষিত হোক।","en":"In the name of Allah; peace be upon you."},"note":{"bn":"ঘরে ঢোকার সময় আল্লাহর নাম নিই — হাদীসে আছে, তাহলে শয়তান সেখানে থাকার জায়গা পায় না (সহীহ মুসলিম); আর ঘরের লোকদের সালাম দিই (সূরা নূর ২৪:৬১)।","en":"Mention Allah's name on entering — the hadith says Satan then finds no place to stay (Sahih Muslim); and greet the household with salam (Surah An-Nur 24:61)."}},{"ar":"اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":{"bn":"আল্লা-হুম্মাফতাহ লী আবওয়া-বা রাহমাতিক","en":"Allaahummaf-taḥ lee abwaaba raḥmatik"},"mean":{"bn":"হে আল্লাহ! আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন।","en":"O Allah, open for me the doors of Your mercy."},"note":{"bn":"মসজিদে ঢোকার সময়, ডান পা আগে দিয়ে। (সহীহ মুসলিম)","en":"On entering the masjid, right foot first. (Sahih Muslim)"}},{"ar":"اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","tr":{"bn":"আল্লা-হুম্মা ইন্নী আসআলুকা মিন ফাদলিক","en":"Allaahumma innee as'aluka min faḍlik"},"mean":{"bn":"হে আল্লাহ! আমি আপনার অনুগ্রহ চাই।","en":"O Allah, I ask You of Your bounty."},"note":{"bn":"মসজিদ থেকে বের হওয়ার সময়, বাম পা আগে দিয়ে। (সহীহ মুসলিম)","en":"On leaving the masjid, left foot first. (Sahih Muslim)"}}]},{"type":"tip","kind":"fun","bn":"মসজিদে ঢুকতে চাই **রহমত** ({{رَحْمَتِكَ}}), আর বের হয়ে দুনিয়ার কাজে যেতে চাই **অনুগ্রহ/রিযিক** ({{فَضْلِكَ}})। ভেতরে আখিরাতের পুঁজি, বাইরে হালাল উপার্জন — দুটোই আল্লাহর কাছে চাই।","en":"Entering the masjid we ask for **mercy** ({{رَحْمَتِكَ}}); leaving for worldly work we ask for **bounty/provision** ({{فَضْلِكَ}}). Inside, savings for the Hereafter; outside, halal earning — we ask Allah for both."},{"type":"examples","title":{"bn":"টয়লেট","en":"The toilet"},"items":[{"ar":"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","tr":{"bn":"আল্লা-হুম্মা ইন্নী আ'ঊযু বিকা মিনাল খুবুসি ওয়াল খাবা-ইস","en":"Allaahumma innee a'oodhu bika minal-khubuthi wal-khabaa'ith"},"mean":{"bn":"হে আল্লাহ! আমি আপনার কাছে সব অপবিত্র পুরুষ ও নারী শয়তান (এবং সব নোংরা) থেকে আশ্রয় চাই।","en":"O Allah, I seek refuge in You from the male and female evil ones (and all impurity)."},"note":{"bn":"টয়লেটে ঢোকার আগে, বাম পা আগে দিয়ে। (বুখারী, মুসলিম)","en":"Before entering the toilet, left foot first. (Bukhari, Muslim)"}},{"ar":"غُفْرَانَكَ","tr":{"bn":"গুফরা-নাক","en":"Ghufraanak"},"mean":{"bn":"(হে আল্লাহ!) আপনার ক্ষমা চাই।","en":"(O Allah,) I ask Your forgiveness."},"note":{"bn":"টয়লেট থেকে বের হয়ে, ডান পা আগে দিয়ে। (আবু দাউদ, তিরমিযী)","en":"After leaving the toilet, right foot first. (Abu Dawud, at-Tirmidhi)"}}]},{"type":"examples","title":{"bn":"সফর","en":"Travel"},"items":[{"ar":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ","tr":{"bn":"সুবহা-নাল্লাযী সাখখারা লানা হা-যা ওয়ামা কুন্না লাহূ মুকরিনীন, ওয়া ইন্না ইলা রাব্বিনা লামুনকালিবূন","en":"Subḥaanal-ladhee sakhkhara lanaa haadhaa wa maa kunnaa lahoo muqrineen, wa innaa ilaa rabbinaa lamunqaliboon"},"mean":{"bn":"পবিত্র তিনি, যিনি এটাকে আমাদের বশ করে দিয়েছেন, অথচ আমরা নিজেরা একে বশ করতে পারতাম না; আর নিশ্চয়ই আমরা আমাদের রবের কাছেই ফিরে যাব।","en":"Glory be to the One who has placed this at our service, though we could never have managed it ourselves; and surely to our Lord we shall return."},"note":{"bn":"গাড়ি, বাস, নৌকা বা যেকোনো বাহনে উঠে। এটি কুরআনের আয়াত (৪৩:১৩–১৪), নবী ﷺ সফরে এটি পড়তেন। (সহীহ মুসলিম)","en":"On boarding a car, bus, boat or any ride. These are Quranic ayahs (43:13–14) the Prophet ﷺ recited when travelling. (Sahih Muslim)"}}]},{"type":"table","title":{"bn":"সফরের দোয়া — শব্দে শব্দে","en":"Travel dua — word by word"},"head":[{"bn":"আরবি","en":"Arabic"},{"bn":"অর্থ","en":"Meaning"}],"rows":[["سُبْحَانَ الَّذِي",{"bn":"পবিত্র তিনি, যিনি","en":"Glory be to the One who"}],["سَخَّرَ لَنَا",{"bn":"আমাদের বশীভূত করে দিয়েছেন","en":"subjected for us"}],["هٰذَا",{"bn":"এটাকে","en":"this"}],["وَمَا كُنَّا لَهُ مُقْرِنِينَ",{"bn":"আর আমরা একে বশ করতে সক্ষম ছিলাম না","en":"and we could not have controlled it"}],["وَإِنَّا إِلَى رَبِّنَا",{"bn":"আর নিশ্চয়ই আমরা আমাদের রবের দিকে","en":"and surely to our Lord"}],["لَمُنْقَلِبُونَ",{"bn":"অবশ্যই ফিরে যাব","en":"we will return"}]]},{"type":"text","title":{"bn":"কুরআনের দোয়া","en":"Duas from the Quran"},"bn":"এবার কুরআনের কয়েকটি দোয়া — নবী-রাসূল ও নেককারদের মুখের দোয়া, যা আল্লাহ নিজেই আমাদের শিখিয়েছেন।","en":"Now some duas from the Quran — words of prophets and righteous people that Allah Himself has taught us."},{"type":"examples","items":[{"ar":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","tr":{"bn":"রাব্বির হামহুমা কামা রাব্বাইয়া-নী সাগীরা","en":"Rabbir-ḥamhumaa kamaa rabbayaanee ṣagheeraa"},"mean":{"bn":"হে আমার রব! তাঁদের (আমার বাবা-মায়ের) প্রতি দয়া করুন, যেমন তাঁরা ছোটবেলায় আমাকে লালন-পালন করেছেন।","en":"My Lord, have mercy on them (my parents) as they raised me when I was small."},"note":{"bn":"বাবা-মায়ের জন্য — প্রতিদিন, বিশেষ করে নামাজের পর। (সূরা ইসরা ১৭:২৪)","en":"For parents — every day, especially after salah. (Surah Al-Isra 17:24)"}},{"ar":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَّفِي الْآخِرَةِ حَسَنَةً وَّقِنَا عَذَابَ النَّارِ","tr":{"bn":"রাব্বানা আ-তিনা ফিদ দুনইয়া হাসানাতাঁও ওয়া ফিল আ-খিরাতি হাসানাতাঁও ওয়া কিনা 'আযা-বান না-র","en":"Rabbanaa aatinaa fid-dunyaa ḥasanataw-wa fil-aakhirati ḥasanataw-wa qinaa 'adhaaban-naar"},"mean":{"bn":"হে আমাদের রব! আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতেও কল্যাণ দিন, এবং আমাদের জাহান্নামের আগুন থেকে রক্ষা করুন।","en":"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."},"note":{"bn":"নবী ﷺ সবচেয়ে বেশি এই দোয়াটি পড়তেন। (বুখারী, মুসলিম) যেকোনো সময়, নামাজে সালামের আগেও। (সূরা বাকারা ২:২০১)","en":"The dua the Prophet ﷺ made most often. (Bukhari, Muslim) Any time, including before salam in salah. (Surah Al-Baqarah 2:201)"}},{"ar":"رَبِّ زِدْنِي عِلْمًا","tr":{"bn":"রাব্বি যিদনী 'ইলমা","en":"Rabbi zidnee 'ilmaa"},"mean":{"bn":"হে আমার রব! আমার জ্ঞান বাড়িয়ে দিন।","en":"My Lord, increase me in knowledge."},"note":{"bn":"পড়তে বসার আগে, ক্লাসে, পরীক্ষার আগে। (সূরা ত্বহা ২০:১১৪)","en":"Before studying, in class, before exams. (Surah Ta-Ha 20:114)"}}]},{"type":"tip","kind":"fun","bn":"আলেমগণ লক্ষ করেছেন: কুরআনে আল্লাহ নবী ﷺ-কে একটিমাত্র জিনিস ‘বাড়িয়ে চাইতে’ বলেছেন — সম্পদ নয়, ক্ষমতা নয় — **জ্ঞান**: {{رَبِّ زِدْنِي عِلْمًا}}। তুমি যে এখন আরবি শিখছ, এটাও সেই দোয়ার পথে হাঁটা!","en":"Scholars have noticed: in the Quran, the one thing Allah told the Prophet ﷺ to ask for ‘more’ of is not wealth or power — it is **knowledge**: {{رَبِّ زِدْنِي عِلْمًا}}. Learning Arabic right now is walking the path of that dua!"},{"type":"text","title":{"bn":"মূসা (আ.)-এর দোয়া (২০:২৫–২৮)","en":"The dua of Musa (20:25–28)"},"bn":"ফেরাউনের মতো জালিম শাসকের কাছে যাওয়ার আগে মূসা (আ.) এই দোয়া করেছিলেন। কঠিন কোনো কাজ, বক্তৃতা বা পরীক্ষার আগে এটা পড়া যায়।","en":"Musa (peace be upon him) made this dua before going to a tyrant like Pharaoh. It is perfect before any hard task, speech or exam."},{"type":"ayah","ref":"20:25","ar":"قَالَ رَبِّ اشْرَحْ لِي صَدْرِي","words":[{"ar":"قَالَ","bn":"তিনি বললেন","en":"He said"},{"ar":"رَبِّ","bn":"হে আমার রব","en":"My Lord"},{"ar":"اشْرَحْ","bn":"প্রশস্ত করে দিন","en":"expand"},{"ar":"لِي","bn":"আমার জন্য","en":"for me"},{"ar":"صَدْرِي","bn":"আমার বুক / অন্তর","en":"my chest"}],"tr":{"bn":"কা-লা রাব্বিশ রাহ লী সাদরী","en":"Qaala rabbish-raḥ lee ṣadree"},"mean":{"bn":"তিনি বললেন: হে আমার রব! আমার বুক (অন্তর) প্রশস্ত করে দিন,","en":"He said: My Lord, expand my chest for me (give me confidence),"}},{"type":"ayah","ref":"20:26","ar":"وَيَسِّرْ لِي أَمْرِي","words":[{"ar":"وَيَسِّرْ","bn":"এবং সহজ করে দিন","en":"and make easy"},{"ar":"لِي","bn":"আমার জন্য","en":"for me"},{"ar":"أَمْرِي","bn":"আমার কাজ","en":"my task"}],"tr":{"bn":"ওয়া ইয়াসসির লী আমরী","en":"Wa yassir lee amree"},"mean":{"bn":"আর আমার কাজ আমার জন্য সহজ করে দিন,","en":"and make my task easy for me,"}},{"type":"ayah","ref":"20:27","ar":"وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي","words":[{"ar":"وَاحْلُلْ","bn":"এবং খুলে দিন","en":"and untie"},{"ar":"عُقْدَةً","bn":"জড়তা / গিঁট","en":"the knot"},{"ar":"مِّن لِّسَانِي","bn":"আমার জিহ্বা থেকে","en":"from my tongue"}],"tr":{"bn":"ওয়াহলুল 'উকদাতাম মিল লিসা-নী","en":"Waḥlul 'uqdatam mil-lisaanee"},"mean":{"bn":"আর আমার জিহ্বার জড়তা দূর করে দিন,","en":"and untie the knot from my tongue,"}},{"type":"ayah","ref":"20:28","ar":"يَفْقَهُوا قَوْلِي","words":[{"ar":"يَفْقَهُوا","bn":"যেন তারা বুঝতে পারে","en":"so they may understand"},{"ar":"قَوْلِي","bn":"আমার কথা","en":"my speech"}],"tr":{"bn":"ইয়াফকাহূ কাওলী","en":"Yafqahoo qawlee"},"mean":{"bn":"যাতে তারা আমার কথা বুঝতে পারে।","en":"so that they may understand my speech."}},{"type":"tip","kind":"memory","title":{"bn":"ভাবনার খোরাক","en":"Reflect"},"bn":"মূসা (আ.) একজন মহান নবী হয়েও কঠিন কাজের আগে আল্লাহর কাছে সাহস ও সহজতা চেয়েছেন। ভয় পাওয়া দোষ নয় — ভয় পেলে আল্লাহর দিকে ফেরাই আসল শক্তি।","en":"Even Musa, a great prophet, asked Allah for courage and ease before a hard task. Feeling nervous is not a fault — turning to Allah when nervous is true strength."},{"type":"table","title":{"bn":"কখন কোন দোয়া — এক নজরে","en":"Which dua when — at a glance"},"head":[{"bn":"সময়","en":"When"},{"bn":"দোয়া","en":"Dua"}],"rows":[[{"bn":"ঘুম থেকে উঠে","en":"Waking up"},"الْحَمْدُ لِلّٰهِ الَّذِي أَحْيَانَا …"],[{"bn":"ঘুমাতে যাওয়ার সময়","en":"Going to sleep"},"بِاسْمِكَ اللّٰهُمَّ أَمُوتُ وَأَحْيَا"],[{"bn":"খাওয়ার আগে / পরে","en":"Before / after eating"},"بِسْمِ اللّٰهِ / الْحَمْدُ لِلّٰهِ …"],[{"bn":"ঘর থেকে বের হতে","en":"Leaving home"},"بِسْمِ اللّٰهِ تَوَكَّلْتُ عَلَى اللّٰهِ …"],[{"bn":"মসজিদে ঢুকতে","en":"Entering the masjid"},"اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ"],[{"bn":"টয়লেট থেকে বের হয়ে","en":"Leaving the toilet"},"غُفْرَانَكَ"],[{"bn":"বাহনে উঠে","en":"Boarding a ride"},"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هٰذَا …"],[{"bn":"পড়ালেখার আগে","en":"Before studying"},"رَبِّ زِدْنِي عِلْمًا"]]},{"type":"quiz","items":[{"q":{"bn":"মসজিদে ঢোকার সময় কোন দোয়া পড়ি?","en":"Which dua do we say on entering the masjid?"},"options":["اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","غُفْرَانَكَ"],"answer":1},{"q":{"bn":"{{غُفْرَانَكَ}} কখন বলি?","en":"When do we say {{غُفْرَانَكَ}}?"},"options":[{"bn":"টয়লেট থেকে বের হয়ে","en":"after leaving the toilet"},{"bn":"খাওয়ার আগে","en":"before eating"},{"bn":"ঘুমানোর আগে","en":"before sleeping"}],"answer":0},{"q":{"bn":"{{رَبِّ زِدْنِي عِلْمًا}} অর্থ কী?","en":"What does {{رَبِّ زِدْنِي عِلْمًا}} mean?"},"options":[{"bn":"হে রব, আমার জ্ঞান বাড়িয়ে দিন","en":"My Lord, increase me in knowledge"},{"bn":"হে রব, আমাকে ক্ষমা করুন","en":"My Lord, forgive me"},{"bn":"হে রব, আমার কাজ সহজ করুন","en":"My Lord, make my task easy"}],"answer":0},{"q":{"bn":"{{كَمَا رَبَّيَانِي صَغِيرًا}} — কাদের জন্য দোয়া?","en":"{{كَمَا رَبَّيَانِي صَغِيرًا}} — this dua is for whom?"},"options":[{"bn":"শিক্ষকদের","en":"teachers"},{"bn":"বাবা-মায়ের","en":"parents"},{"bn":"বন্ধুদের","en":"friends"}],"answer":1},{"q":{"bn":"কোন দোয়াটি নবী ﷺ সবচেয়ে বেশি পড়তেন?","en":"Which dua did the Prophet ﷺ make most often?"},"options":["رَبِّ اشْرَحْ لِي صَدْرِي","رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَّفِي الْآخِرَةِ حَسَنَةً وَّقِنَا عَذَابَ النَّارِ","بِاسْمِكَ اللّٰهُمَّ أَمُوتُ وَأَحْيَا"],"answer":1},{"q":{"bn":"বাসে বা গাড়িতে উঠে কী বলি?","en":"What do we say on boarding a bus or car?"},"options":["سُبْحَانَ الَّذِي سَخَّرَ لَنَا هٰذَا","اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","الْحَمْدُ لِلّٰهِ الَّذِي أَحْيَانَا"],"answer":0},{"q":{"bn":"{{وَيَسِّرْ لِي أَمْرِي}} অর্থ কী?","en":"What does {{وَيَسِّرْ لِي أَمْرِي}} mean?"},"options":[{"bn":"আমার কাজ সহজ করে দিন","en":"make my task easy for me"},{"bn":"আমার বুক প্রশস্ত করুন","en":"expand my chest"},{"bn":"আমার কথা বুঝুক","en":"may they understand my speech"}],"answer":0},{"q":{"bn":"ঘুমানোর সময়ের দোয়ায় {{أَمُوتُ وَأَحْيَا}} মানে কী?","en":"In the bedtime dua, what does {{أَمُوتُ وَأَحْيَا}} mean?"},"options":[{"bn":"আমি মরি ও জীবিত হই","en":"I die and I live"},{"bn":"আমি খাই ও পান করি","en":"I eat and drink"},{"bn":"আমি আসি ও যাই","en":"I come and go"}],"answer":0}]}]}]});
